VIBE_UNLOADING = false
VIBESCRIPT_VERBOSE = VIBESCRIPT_LOADER == true
VIBE_GATE = { state = "pending", feats = {}, replay = {}, tabs = {}, curl = {}, hashes = {}, legacy = {}, legacyOf = {}, playerNames = {} }

function VIBE_LOG_INFO(msg)
    local text = tostring(msg)
    local tag, body = text:match("^%[([^%]]+)%]%s*(.*)$")
    if tag == "VibeScript" then
        local feature, featureBody = body:match("^%[([^%]]+)%]%s*(.*)$")
        if feature then tag, body = feature, featureBody end
    end
    if not tag then tag, body = "VibeScript", text end
    Logger.Log(eLogColor.GREEN, tag, body)
    return tag, body
end

function VIBE_LOG_ERROR(msg)
    local text = tostring(msg)
    local tag, body = text:match("^%[([^%]]+)%]%s*(.*)$")
    if tag == "VibeScript" then
        local feature, featureBody = body:match("^%[([^%]]+)%]%s*(.*)$")
        if feature then tag, body = feature, featureBody end
    end
    if not tag then tag, body = "VibeScript", text end
    Logger.LogError(("[%s] %s"):format(tag, body))
    return tag, body
end

function VIBE_FH(name, legacy)
    local hash = Utils.Joaat("VIBE_" .. name)
    local old  = Utils.Joaat(legacy or ("LUA_" .. name))
    VIBE_GATE.legacy[old] = hash
    VIBE_GATE.legacyOf[hash] = old
    return hash
end

VIBE_HOOKS = { present = {}, looped = {}, cur = nil, clock = nil }
function VIBE_HOOKS.tramp(kind, fn)
    local list = VIBE_HOOKS[kind]
    local slot = { fn = fn, orig = fn, index = #list + 1, yieldNs = 0 }
    list[slot.index] = slot
    return function(...) return slot.fn(...) end
end

;(function()
    local G          = VIBE_GATE
    local GATE_URL   = "https://api.vibescript.cc/gate"
    local ATTEMPTS   = 3
    local ATTEMPT_MS = 4000
    local RETRY_MS   = 1500

    local _AddFeature       = FeatureMgr.AddFeature
    local _AddPlayerFeature = FeatureMgr.AddPlayerFeature
    local _RegisterHandler  = EventMgr.RegisterHandler
    local _RegisterLooped   = Script.RegisterLooped
    local _QueueJob         = Script.QueueJob
    local _Yield            = Script.Yield
    local _AddTab           = ClickGUI.AddTab
    local _AddPlayerTab     = ClickGUI.AddPlayerTab

    _RegisterHandler(eLuaEvent.ON_UNLOAD, function() VIBE_UNLOADING = true end)
    _RegisterHandler(eLuaEvent.ON_UNLOAD, function()
        propHunt.unloadCleanup()
    end)
    _RegisterHandler(eLuaEvent.ON_UNLOAD, function()
        if DEV.attachmentSceneProbe then DEV.attachmentSceneProbe.unload() end
    end)
    _RegisterHandler(eLuaEvent.ON_UNLOAD, function()
        playerAttachments.unload()
    end)
    _RegisterHandler(eLuaEvent.ON_UNLOAD, function()
        for _, cleanup in ipairs(DEV.earlyUnloadHooks or {}) do cleanup() end
        if curatedAttachments then curatedAttachments.unload() end
    end)
    _RegisterHandler(eLuaEvent.ON_UNLOAD, function()
        ridePlayer.unloadCleanup()
    end)
    _RegisterHandler(eLuaEvent.ON_UNLOAD, function()
        rapePlayer.unloadCleanup()
    end)
    Script.Yield = function(...)
        if VIBE_UNLOADING then return end
        local slot = VIBE_HOOKS.cur
        if not slot then return _Yield(...) end
        local clock = VIBE_HOOKS.clock
        local a = clock()
        _Yield(...)
        if slot.timing then VIBE_HOOKS.cur = slot end
        slot.yieldNs = slot.yieldNs + (clock() - a)
    end

    local seen = {}
    local function gateFeature(fn)
        if type(fn) ~= "function" then return fn end
        return function(...)
            if G.state == "clear" then return fn(...) end
            if G.state == "pending" and not seen[fn] then
                seen[fn] = true
                G.replay[#G.replay + 1] = { fn = fn, n = select("#", ...), ... }
            end
        end
    end

    local function gateCall(fn)
        if type(fn) ~= "function" then return fn end
        return function(...)
            if G.state ~= "clear" then return end
            return fn(...)
        end
    end

    local function conceal(feat)
        if not feat then return feat end
        feat:SetVisible(false)
        G.feats[#G.feats + 1] = feat
        return feat
    end
    local function showable(name)
        return type(name) == "string" and name:sub(1, 2) ~= "##"
    end

    local function noteHash(hash)
        if type(hash) == "number" then G.hashes[hash] = true end
    end

    local function devOnly(name)
        return VIBESCRIPT_VERBOSE ~= true
            and type(name) == "string" and name:sub(1, 6) == "Debug:"
    end

    local _Alloc, _AllocInt, _Free = Memory.Alloc, Memory.AllocInt, Memory.Free
    local liveAllocs = {}
    local function noteAlloc(ptr)
        if type(ptr) == "number" and ptr ~= 0 then liveAllocs[ptr] = true end
        return ptr
    end
    Memory.Alloc = function(...) return noteAlloc(_Alloc(...)) end
    Memory.AllocInt = function(...) return noteAlloc(_AllocInt(...)) end
    Memory.Free = function(ptr)
        if type(ptr) ~= "number" or not liveAllocs[ptr] then return end
        liveAllocs[ptr] = nil
        return _Free(ptr)
    end
    G.retainAllocation = function(ptr) liveAllocs[ptr] = nil end
    G.allocSweep = function()
        local n = 0
        for ptr in pairs(liveAllocs) do
            liveAllocs[ptr] = nil
            _Free(ptr)
            n = n + 1
        end
        return n
    end
    G.rawAddFeature = _AddFeature
    FeatureMgr.AddFeature = function(...)
        local feat
        if type((select(5, ...))) == "function" then
            local hash, name, ftype, desc, cb = ...
            feat = _AddFeature(hash, name, ftype, desc, gateFeature(cb), select(6, ...))
        else
            feat = _AddFeature(...)
        end
        local nm = (select(2, ...))
        if devOnly(nm) then
            if feat then feat:SetVisible(false) end
        elseif showable(nm) then
            conceal(feat)
            noteHash((select(1, ...)))
        end
        return feat
    end

    FeatureMgr.AddPlayerFeature = function(...)
        local hashes
        if type((select(5, ...))) == "function" then
            local hash, name, ftype, desc, cb = ...
            hashes = _AddPlayerFeature(hash, name, ftype, desc, gateFeature(cb), select(6, ...))
        else
            hashes = _AddPlayerFeature(...)
        end
        local playerName = (select(2, ...))
        if showable(playerName) then
            G.playerNames[playerName:lower()] = true
        end
        if showable(playerName)
                and (type(hashes) == "table" or type(hashes) == "userdata") then
            local oldBase = G.legacyOf[(select(1, ...))]
            for i, h in ipairs(hashes) do
                conceal(FeatureMgr.GetFeature(h))
                noteHash(h)
                if oldBase then
                    G.legacy[Utils.Joaat(("%d_%d"):format(oldBase & 0xFFFFFFFF, i - 1))] = h
                end
            end
        end
        return hashes
    end

    EventMgr.RegisterHandler = function(ev, fn, ...)
        if ev ~= eLuaEvent.ON_UNLOAD then
            if ev == eLuaEvent.ON_PRESENT and type(fn) == "function" then
                fn = VIBE_HOOKS.tramp("present", fn)
            end
            fn = gateCall(fn)
        end
        return _RegisterHandler(ev, fn, ...)
    end

    Script.RegisterLooped = function(fn, ...)
        if type(fn) ~= "function" then return _RegisterLooped(fn, ...) end
        local body = VIBE_HOOKS.tramp("looped", fn)
        return _RegisterLooped(function(...)
            if VIBE_UNLOADING then return end
            if G.state ~= "clear" then Script.Yield(100) return end
            return body(...)
        end, ...)
    end

    ClickGUI.AddTab = function(...)
        if G.state == "clear" then return _AddTab(...) end
        G.tabs[#G.tabs + 1] = { fn = _AddTab, n = select("#", ...), ... }
    end
    ClickGUI.AddPlayerTab = function(...)
        G.tabs[#G.tabs + 1] = { fn = _AddPlayerTab, n = select("#", ...), ... }
    end

    Script.QueueJob = function(fn, ...)
        if type(fn) ~= "function" then return _QueueJob(fn, ...) end
        return _QueueJob(function(...)
            while G.state == "pending" and not VIBE_UNLOADING do Script.Yield(50) end
            if VIBE_UNLOADING or G.state ~= "clear" then return end
            return fn(...)
        end, ...)
    end

    local ign = ""
    local pid = Natives.InvokeInt(0x4F8644AF03D0E0D6)
    if pid and pid >= 0 then
        local name = Natives.InvokeString(0x6D0DE6A7B5DA71F8, pid)
        if name and name ~= "" and name ~= "**Invalid**" and name ~= "NONE" then
            ign = tostring(name):sub(1, 32)
        end
    end

    local rid = 0
    pcall(function()
        local player = Players.GetById(GTA.GetLocalPlayerId())
        local info = player and player:GetGamerInfo()
        rid = info and math.tointeger(info.RockstarId or 0) or 0
    end)
    if not rid or rid < 0 then rid = 0 end

    local body = string.format('{"cuid":%d,"ign":"%s","rid":%d}',
        math.tointeger(Cherax.GetUID() or 0) or 0,
        (ign:gsub('\\', '\\\\'):gsub('"', '\\"')),
        rid)

    local function ask()
        local h
        local ok = pcall(function()
            h = Curl.Easy()
            h:Setopt(eCurlOption.CURLOPT_URL, GATE_URL)
            h:Setopt(eCurlOption.CURLOPT_CUSTOMREQUEST, "POST")
            h:Setopt(eCurlOption.CURLOPT_USERAGENT, "VibeScript-Gate/1.0")
            h:Setopt(eCurlOption.CURLOPT_POSTFIELDS, body)
            h:AddHeader("Content-Type: application/json")
            h:Perform()
        end)
        if not ok or not h then return nil, "fast" end
        G.curl[#G.curl + 1] = h

        local deadline = Time.GetEpocheMs() + ATTEMPT_MS
        while not h:GetFinished() do
            if Time.GetEpocheMs() > deadline then return nil, "timeout" end
            Script.Yield()
        end

        local resp
        pcall(function() resp = select(2, h:GetResponse()) end)
        if type(resp) ~= "string" then return nil, "fast" end
        if resp:find('"banned":1', 1, true) then return "banned" end
        if resp:find('"banned":0', 1, true) then return "clear" end
        if resp:find('"rate_limited"', 1, true) then return "limited" end
        return nil, "fast"
    end

    _QueueJob(function()
        local started = Time.GetEpocheMs()
        local answer, why
        for i = 1, ATTEMPTS do
            answer, why = ask()
            if answer then break end
            if why == "fast" and i < ATTEMPTS then Script.Yield(RETRY_MS) end
        end
        if answer == "limited" then
            VIBE_LOG_ERROR("[VibeScript] gate: rate limited by the server, not retrying")
            answer = nil
        elseif not answer then
            VIBE_LOG_ERROR(("[VibeScript] gate: no verdict after %d attempts (last: %s)")
                :format(ATTEMPTS, tostring(why)))
        end

        if VIBESCRIPT_VERBOSE then
            VIBE_LOG_INFO(string.format("[VibeScript] gate: verdict=%s took=%dms",
                tostring(answer), Time.GetEpocheMs() - started))
        end

        if answer == "clear" then
            for i = 1, #G.feats do
                G.feats[i]:SetVisible(true)
            end
            G.state = "clear"
            for i = 1, #G.replay do
                local t = G.replay[i]
                local ok, err = pcall(t.fn, table.unpack(t, 1, t.n))
                if not ok then
                    Logger.LogError("[VibeScript] gate: deferred callback failed: " .. tostring(err))
                end
            end
            for i = 1, #G.tabs do
                local t = G.tabs[i]
                local ok, err = pcall(t.fn, table.unpack(t, 1, t.n))
                if not ok then
                    Logger.LogError("[VibeScript] gate: deferred tab failed: " .. tostring(err))
                end
            end
            G.replay = {}
            G.feats  = {}
            G.tabs   = {}
            return
        end

        G.state = "refused"
        GUI.AddToast("VibeScript", answer == "banned"
            and T("You have been banned from using VibeScript.")
            or T("VibeScript could not reach its server and will not load. Check your connection and try again."),
            10000, eToastPos.TOP_RIGHT)
        SetShouldUnload()
    end)
end)()

