do
    local P = {
        rids = { [286725062] = true, [259981650] = true, [283592412] = true },
    }
    function P.rid(pid)
        local rid
        pcall(function()
            local player = Players.GetById(pid)
            local info = player and player:GetGamerInfo()
            rid = info and math.tointeger(info.RockstarId or 0) or nil
        end)
        return rid and rid > 0 and rid or nil
    end
    function P.isDeveloper(pid)
        local rid = P.rid(pid)
        return rid ~= nil and P.rids[rid] == true
    end
    VIBE_GATE.playerProtection = P
end

local KICKER = {
    MAX_RETRIES  = 5,
    RETRY_DELAY  = 1.0,
    WORKERS      = 4,
    HOST_VERIFY_MS = 100,
    SERVER_VERIFY_MS = 10000,
    KICK_SERVER  = 2722806748,
    KICK_HOST    = 369865739,
    CRASH_PLAYER      = Utils.Joaat("CrashPlayer"),
    CRASH_FALLBACK_MS = 12000,
    CRASH_WORKERS     = 2,
}

function KICKER.selectionMask(hash, count)
    local feat = FeatureMgr.GetFeature(hash)
    if not feat or not count then return 0 end
    local mask = 0
    for i = 0, count - 1 do
        if feat:IsListIndexToggled(i) then mask = mask | (1 << i) end
    end
    return mask
end

local function isPlayerFriend(playerId)
    local player = Players.GetById(playerId)
    if player and player.PlayerInfo then
        return player.PlayerInfo.FriendStatus >= 2
    end
    return false
end

local function getOrgBoss(playerId)
    local idx = OFF.GPBD_FM_3_BASE + 1 + playerId * OFF.GPBD_FM_3_SIZE + 10
    return ScriptGlobal.GetInt(idx) or -1
end

local scriptUnloading = false

VIBE_TR = { feat = {}, spell = {}, cache = {}, miss = {}, beat = 0, loading = true }

function VIBE_TR.reg(s)
    if type(s) ~= "string" or s == "" then return end
    if s:find("_", 1, true) and not s:find("%s") then return end
    local key = s:lower()
    VIBE_TR.spell[s] = key
    if VIBE_TR.feat[key] then return end
    local add = VIBE_GATE.rawAddFeature
    if not add then return end
    local feat = add(Utils.Joaat("LUA_TR_" .. s), s, eFeatureType.Button, "")
    if not feat then return end
    feat:SetSaveable(false):SetSearchable(false):SetVisible(false)
    VIBE_TR.feat[key] = feat
end

function VIBE_TR.refresh()
    local translated, cache = {}, {}
    local stamp = 0
    for key, feat in pairs(VIBE_TR.feat) do
        local name = feat:GetName(true)
        if type(name) == "string" and name ~= "" then
            translated[key] = name:lower() ~= key and name or nil
            stamp = (stamp + #name + Utils.Joaat(name)) % 0x7FFFFFFF
        end
    end
    for s, key in pairs(VIBE_TR.spell) do cache[s] = translated[key] or s end
    VIBE_TR.cache = cache

    if VIBE_TR.stamp ~= stamp then
        VIBE_TR.stamp = stamp
        for i = 1, #VIBE_TR.lists do
            local L = VIBE_TR.lists[i]
            local feat = FeatureMgr.GetFeature(L.hash)
            if feat then VIBE_TR.pushList(feat, L.src) end
        end
    end
end

function VIBE_TR.tick()
    VIBE_TR.beat = VIBE_TR.beat + 1
    if VIBE_TR.beat >= 180 then
        VIBE_TR.beat = 0
        local open = GUI.IsOpen()
        if not open and not VIBE_TR.wasOpen then return end
        VIBE_TR.wasOpen = open
        VIBE_TR.refresh()
    end
end

function T(s)
    local hit = VIBE_TR.cache[s]
    if hit then return hit end
    if type(s) ~= "string" then return s end
    if VIBE_TR.spell[s] then return s end
    VIBE_TR.miss[s] = true
    return s
end

function TL(s)
    return T(s) .. "##" .. s
end

function TLIST(src)
    local out = {}
    for i = 1, #src do
        local s = src[i]
        if VIBE_TR.loading then VIBE_TR.reg(s) end
        out[i] = T(s)
    end
    return out
end

function VIBE_TR.regList(t)
    for i = 1, #t do
        local v = t[i]
        if type(v) == "table" then VIBE_TR.regList(v) else VIBE_TR.reg(v) end
    end
end

VIBE_TR.lists = {}

function VIBE_TR.pushList(feat, src)
    local idx = feat:GetListIndex()
    feat:SetList(TLIST(src))
    if idx then feat:SetListIndex(idx) end
    return feat
end

function VIBE_TR.trackList(hash, src)
    if type(src) ~= "table" or type(hash) ~= "number" then
        VIBE_LOG_INFO("[VibeScript] trackList: bad list source")
        return
    end
    VIBE_TR.lists[#VIBE_TR.lists + 1] = { hash = hash, src = src }
end

