local Widget = { _open = {} }

function Widget.overflowTooltip(text, width)
    if ImGui.IsItemHovered() and ImGui.CalcTextSize(text) > math.max(1, width) then
        ImGui.SetTooltip(text)
    end
end

function Widget.clippedRows(count, height, draw)
    if count == 0 then return end
    local rowH = ImGui.GetTextLineHeightWithSpacing()
    local spacing = rowH - ImGui.GetTextLineHeight()
    local offset = ImGui.GetScrollY() - ImGui.GetCursorPosY()
    local skipped = math.min(count, math.max(0, math.floor(offset / rowH) - 1))
    local last = math.min(count, math.max(skipped, math.ceil((offset + height) / rowH) + 1))
    if skipped > 0 then ImGui.Dummy(1, skipped * rowH - spacing) end
    for index = skipped + 1, last do draw(index) end
    if last < count then ImGui.Dummy(1, (count - last) * rowH - spacing) end
end

function Widget.chevron(x, y, w, h)
    local r, g, b, a = ImGui.GetStyleColorVec4(ImGuiCol.Text)
    r, g, b, a = math.floor(r * 255), math.floor(g * 255),
                 math.floor(b * 255), math.floor(a * 255)
    local cx = x + w - h * 0.5
    local cy = y + h * 0.5
    local hw = h * 0.19
    local hh = hw * 0.5
    ImGui.AddLine(cx - hw, cy - hh, cx, cy + hh, r, g, b, a, 1.5)
    ImGui.AddLine(cx, cy + hh, cx + hw, cy - hh, r, g, b, a, 1.5)
end

function Widget.fitPreview(text, w, h)
    if type(text) ~= "string" then return text end
    local avail = w - h
    if avail <= 0 then return text end
    local tw = ImGui.CalcTextSize(text)
    if tw <= avail then return text end
    return text:sub(1, math.max(1, math.floor(#text * avail / tw) - 3)) .. "..."
end

function Widget.beginCombo(label, preview, flags)
    local x, y = ImGui.GetCursorScreenPos()
    local w, h = ImGui.CalcItemWidth(), ImGui.GetFrameHeight()
    local open = ImGui.BeginCombo(label, Widget.fitPreview(preview, w, h), (flags or 0) | 32)
    if open then
        Widget._open[#Widget._open + 1] = { x, y, w, h }
    else
        Widget.chevron(x, y, w, h)
    end
    return open
end

function Widget.endCombo()
    ImGui.EndCombo()
    local g = table.remove(Widget._open)
    if g then Widget.chevron(g[1], g[2], g[3], g[4]) end
end

Widget._marquee = {}

function Widget.marquee(id, text, indent)
    if indent then ImGui.SetCursorPosX(ImGui.GetCursorPosX() + indent) end
    local avail = ImGui.GetContentRegionAvail()
    local tw, th = ImGui.CalcTextSize(text)
    if tw <= avail then
        Widget._marquee[id] = nil
        ImGui.TextUnformatted(text)
        return
    end
    local now = ImGui.GetTime()
    local st = Widget._marquee[id]
    if not st or st.text ~= text then
        st = { text = text, t0 = now }
        Widget._marquee[id] = st
    end
    local HOLD, SPEED = 1.5, 36
    local over = tw - avail
    local run = over / SPEED
    local p = (now - st.t0) % (2 * (HOLD + run))
    local off
    if p < HOLD then off = 0
    elseif p < HOLD + run then off = (p - HOLD) * SPEED
    elseif p < 2 * HOLD + run then off = over
    else off = over - (p - 2 * HOLD - run) * SPEED end
    if ImGui.BeginChild(id, avail, th, false, ImGuiWindowFlags.NoDecoration
            | ImGuiWindowFlags.NoBackground | ImGuiWindowFlags.NoInputs) then
        ImGui.SetCursorPosX(-math.floor(off))
        ImGui.TextUnformatted(text)
    end
    ImGui.EndChild()
end

function Widget.combo(label, current, items, count)
    local sel, changed = current, false
    if Widget.beginCombo(T(label), T(items[current + 1] or "")) then
        for i = 1, (count or #items) do
            ImGui.PushID(i)
            local picked = ImGui.Selectable(T(items[i]), i - 1 == current)
            ImGui.PopID()
            if picked and i - 1 ~= current then
                sel, changed = i - 1, true
            end
        end
        Widget.endCombo()
    end
    return sel, changed
end

CENTRAL_TICK = { single = {}, player = {}, cb = {}, isTick = {}, mark = {}, frame = 0 }
do
    local _AddFeature = FeatureMgr.AddFeature
    FeatureMgr.AddFeature = function(...)
        local hash, cb = (select(1, ...)), (select(5, ...))
        CENTRAL_TICK._lastHash = hash
        CENTRAL_TICK._lastCb = cb
        if type(hash) == "number" and type(cb) == "function" then
            CENTRAL_TICK.cb[hash] = cb
        end
        return _AddFeature(...)
    end
end
function centralOnTick(feat)
    if feat then
        CENTRAL_TICK.single[#CENTRAL_TICK.single + 1] =
            { feat = feat, fn = CENTRAL_TICK._lastCb, hash = CENTRAL_TICK._lastHash }
        if type(CENTRAL_TICK._lastHash) == "number" then
            CENTRAL_TICK.isTick[CENTRAL_TICK._lastHash] = true
        end
    end
    return feat
end
function centralPlayerOnTick(hash, fn)
    local h = {}
    for pid = 0, 31 do h[pid] = FeatureMgr.GetFeature(hash, pid) end
    CENTRAL_TICK.player[#CENTRAL_TICK.player + 1] = { hash = hash, fn = fn, h = h }
end
CENTRAL_TICK.inFlight = nil
CENTRAL_TICK.faultsLogged = 0
CENTRAL_TICK.FAULT_LOG_MAX = 20
CENTRAL_TICK.featureName = function(hash)
    if type(hash) ~= "number" then return "?" end
    for name, h in pairs(H) do
        if h == hash then return name end
    end
    return ("0x%08X"):format(hash & 0xFFFFFFFF)
end
CENTRAL_TICK.reportFault = function()
    local f = CENTRAL_TICK.inFlight
    CENTRAL_TICK.inFlight = nil
    if not f then return end
    if CENTRAL_TICK.faultsLogged >= CENTRAL_TICK.FAULT_LOG_MAX then return end
    CENTRAL_TICK.faultsLogged = CENTRAL_TICK.faultsLogged + 1
    VIBE_LOG_ERROR(("[VibeScript] central tick FAULTED inside %s feature %s%s%s (%d/%d)")
        :format(f.kind, CENTRAL_TICK.featureName(f.hash),
            f.pid and (" pid " .. f.pid) or "",
            f.step and (" at step " .. f.step) or "",
            CENTRAL_TICK.faultsLogged, CENTRAL_TICK.FAULT_LOG_MAX))
end
function CENTRAL_TICK.run()
    if scriptUnloading then return end
    CENTRAL_TICK.frame = CENTRAL_TICK.frame + 1
    local single = CENTRAL_TICK.single
    local mark = CENTRAL_TICK.mark
    for i = 1, #single do
        local t = single[i]
        mark.kind, mark.hash, mark.pid, mark.step = "single", t.hash, nil, nil
        CENTRAL_TICK.inFlight = mark
        local ok, err = pcall(t.fn, t.feat)
        if not ok and not t.warned then
            t.warned = true
            Logger.LogError(("[VibeScript] central OnTick error [%s; entry %d]: %s")
                :format(CENTRAL_TICK.featureName(t.hash), i, tostring(err)))
        end
    end
    local player = CENTRAL_TICK.player
    local np = #player
    if np > 0 then
        for pid = 0, 31 do
            if NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                for j = 1, np do
                    local p = player[j]
                    mark.kind, mark.hash, mark.pid, mark.step = "player", p.hash, pid, nil
                    CENTRAL_TICK.inFlight = mark
                    local ok, err = pcall(p.fn, p.h[pid] or FeatureMgr.GetFeature(p.hash, pid))
                    if not ok and not p.warned then
                        p.warned = true
                        Logger.LogError(("[VibeScript] central player OnTick error [%s; entry %d; pid %d]: %s")
                            :format(CENTRAL_TICK.featureName(p.hash), j, pid, tostring(err)))
                    end
                end
            end
        end
    end
    CENTRAL_TICK.inFlight = nil
end
function CENTRAL_TICK.driver()
    if CENTRAL_TICK.inFlight then CENTRAL_TICK.reportFault() end
    if scriptUnloading then return end
    if VIBE_GATE.state ~= "clear" then return end
    pcall(VIBE_TR.tick)
    local ok, err = pcall(CENTRAL_TICK.run)
    if not ok and not CENTRAL_TICK.driverWarned then
        CENTRAL_TICK.driverWarned = true
        Logger.LogError("[VibeScript] central driver error: " .. tostring(err))
    end
end
FeatureMgr.AddFeature(VIBE_FH("CentralTickDriver"), "##CentralTickDriver",
    eFeatureType.Toggle, "", CENTRAL_TICK.driver)
    :RegisterCallbackTrigger(eCallbackTrigger.OnTick)
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
    :SetSearchable(false)
    :SetVisible(false)
FeatureMgr.GetFeature(VIBE_FH("CentralTickDriver")):Toggle(true)

local pendingKicks = {}
KICKER.pendingKickIds = {}
KICKER.crashQueue     = {}
KICKER.crashFallbacks = {}

local function doKick(playerId)
    playerId = math.tointeger(playerId)
    if not playerId or playerId < 0 or playerId > 31 then return false end
    if KICKER.pendingKickIds[playerId] then return false end
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(playerId) then return false end
    KICKER.pendingKickIds[playerId] = true
    local autoCrash = FeatureMgr.GetFeature(H.AUTO_CRASH)
    if autoCrash and autoCrash:IsToggled() then
        KICKER.crashQueue[#KICKER.crashQueue + 1] = playerId
    else
        pendingKicks[#pendingKicks + 1] = playerId
    end
    return true
end

local function kickWorker()
    if scriptUnloading or #pendingKicks == 0 then
        Script.Yield(100)
        return
    end

    local pid = table.remove(pendingKicks, 1)
    local attempts = 0
    while not scriptUnloading
        and attempts < KICKER.MAX_RETRIES
        and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) do
        if KICKER.isProtected(pid) then break end

        attempts = attempts + 1
        local isHost = NETWORK.NETWORK_IS_HOST()
        local verifyMs = isHost and KICKER.HOST_VERIFY_MS or KICKER.SERVER_VERIFY_MS
        local sentAt = Time.GetEpocheMs()
        FeatureMgr.TriggerFeatureCallback(
            isHost and KICKER.KICK_HOST or KICKER.KICK_SERVER, pid)

        local remaining = verifyMs - (Time.GetEpocheMs() - sentAt)
        if remaining > 0 then Script.Yield(remaining) end
    end

    KICKER.pendingKickIds[pid] = nil
    Script.Yield()
end

for _ = 1, KICKER.WORKERS do
    Script.RegisterLooped(kickWorker)
end

for _ = 1, KICKER.CRASH_WORKERS do
    Script.RegisterLooped(function()
        if scriptUnloading or #KICKER.crashQueue == 0 then
            Script.Yield(100)
            return
        end

        local pid = table.remove(KICKER.crashQueue, 1)
        if NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) and not KICKER.isProtected(pid) then
            KICKER.crashFallbacks[pid] = Time.GetEpocheMs() + KICKER.CRASH_FALLBACK_MS
            FeatureMgr.TriggerFeatureCallback(KICKER.CRASH_PLAYER, pid)
        else
            KICKER.pendingKickIds[pid] = nil
        end
        Script.Yield()
    end)
end

Script.RegisterLooped(function()
    if scriptUnloading or next(KICKER.crashFallbacks) == nil then
        Script.Yield(250)
        return
    end

    local now = Time.GetEpocheMs()
    for pid, dueAt in pairs(KICKER.crashFallbacks) do
        if now >= dueAt then
            KICKER.crashFallbacks[pid] = nil
            if NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                pendingKicks[#pendingKicks + 1] = pid
            else
                KICKER.pendingKickIds[pid] = nil
            end
        end
    end
    Script.Yield()
end)

FeatureMgr.AddFeature(H.AUTO_CRASH, "Auto Crash", eFeatureType.Toggle,
    "Tries to crash the player once before kicking them.")
    :SetSaveable(false)

