    FeatureMgr.GetFeature(fitment.H.TRACK_REAR):SetFloatValue(tr)
    FeatureMgr.GetFeature(fitment.H.TOE_FRONT):SetFloatValue(toeF or 0.0)
    FeatureMgr.GetFeature(fitment.H.TOE_REAR):SetFloatValue(toeR or 0.0)
    FeatureMgr.GetFeature(fitment.H.CASTOR):SetFloatValue(castor or 0.0)
end

