local FITMENT_DIR = FileMgr.GetMenuRootPath() .. "\\lua\\VibeScript"
local FITMENT_FILE = FITMENT_DIR .. "\\fitment.cfg"

local BUILTIN_PRESETS = {
    { id = "builtin:low",  name = "Low Daily",   h = -0.060, cf = -3.0, cr = -4.0,  tf = 0.035, tr = 0.045 },
    { id = "builtin:slam", name = "Aired Out",   h = -0.140, cf = -6.0, cr = -7.5,  tf = 0.060, tr = 0.070 },
    { id = "builtin:show", name = "Show Stance", h = -0.220, cf = -8.0, cr = -10.0, tf = 0.085, tr = 0.100 },
}

for _, pr in ipairs(BUILTIN_PRESETS) do VIBE_TR.reg(pr.name) end

local function presetSanitize(s)
    return (tostring(s or ""):gsub("[\t\r\n%%]", " "):gsub("^%s+", ""):gsub("%s+$", ""))
end

local function savePresets()
    local lines = { "V\t4", "A\t" .. presetSanitize(fitment.autoPreset) }
    for _, pr in ipairs(fitment.presets) do
        lines[#lines + 1] = ("P\t%s\t%.4f\t%.4f\t%.4f\t%.4f\t%.4f\t%.4f\t%.4f\t%.4f")
            :format(presetSanitize(pr.name), pr.h, pr.cf, pr.cr, pr.tf, pr.tr,
                pr.toeF or 0.0, pr.toeR or 0.0, pr.castor or 0.0)
    end
    FileMgr.CreateDir(FITMENT_DIR)
    local ok = FileMgr.WriteFileContent(FITMENT_FILE, table.concat(lines, "\n"), false)
    if not ok then
        VIBE_LOG_ERROR("[VibeScript] fitment: could not write " .. FITMENT_FILE)
    end
    return ok
end

local function loadPresets()
    if not FileMgr.DoesFileExist(FITMENT_FILE) then return end
    local content = FileMgr.ReadFileContent(FITMENT_FILE)
    if not content or content == "" then return end
    local list, ver = {}, 1
    for line in content:gmatch("[^\r\n]+") do
        local kind, rest = line:match("^(%a)\t(.*)$")
        if kind == "V" then
            ver = tonumber(rest) or 1
        elseif kind == "A" then
            fitment.autoPreset = presetSanitize(rest)
        elseif kind == "P" then
            local f = {}
            for part in (rest .. "\t"):gmatch("([^\t]*)\t") do f[#f + 1] = part end
            local name = presetSanitize(f[1])
            local h, cf = tonumber(f[2]), tonumber(f[3])
            local cr, tf, tr = tonumber(f[4]), tonumber(f[5]), tonumber(f[6])
            if name ~= "" and h and cf and cr and tf and tr then
                list[#list + 1] = {
                    name = name, h = h, cf = cf, cr = cr, tf = tf, tr = tr,
                    toeF = tonumber(f[7]) or 0.0,
                    toeR = tonumber(f[8]) or 0.0,
                    castor = tonumber(f[9]) or 0.0,
                }
            end
        end
    end
    if ver < 2 then
        for _, pr in ipairs(list) do pr.cf, pr.cr = -pr.cf, -pr.cr end
        fitment.presets = list
        savePresets()
    else
        fitment.presets = list
    end
end

