function vehicleDismantle.toast(msg)
    GUI.AddToast("Dismantle Vehicle", msg, 3500)
end

function vehicleDismantle.note(quiet, msg)
    if quiet then
        if VIBESCRIPT_VERBOSE == true then log("[VehicleDismantle] " .. msg) end
    else
        vehicleDismantle.toast(msg)
    end
end

function vehicleDismantle.resolveFn(slot, label)
    if slot.addr then return slot.addr end
    local pat = IS_ENHANCED and slot.enh or slot.leg
    local hit = Memory.Scan(pat)
    if hit and hit > 0x10000 then
        slot.addr = hit
        log(("[VehicleDismantle] %s @ 0x%X (%s)")
            :format(label, hit, IS_ENHANCED and "Enhanced" or "Legacy"))
    else
        log(("[VehicleDismantle] %s pattern not found (will retry next use)"):format(label))
    end
    return slot.addr
end

function vehicleDismantle.getVehicle(pid, quiet)
    if not isPlayerReady() then
        vehicleDismantle.note(quiet, "You aren't ready (cutscene / switch / not playing).")
        return nil
    end
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
        vehicleDismantle.note(quiet, "Player not connected.")
        return nil
    end
    if PLAYER.IS_REMOTE_PLAYER_IN_NON_CLONED_VEHICLE(pid) then
        vehicleDismantle.note(quiet, "Player's vehicle isn't streamed in. Spectate them first, then try again.")
        return nil
    end
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then
        vehicleDismantle.note(quiet, "Player is too far away (not streamed in). Spectate them first, then try again.")
        return nil
    end
    if not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        vehicleDismantle.note(quiet, "Player isn't in a vehicle.")
        return nil
    end
    local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if not veh or veh == 0 or not ENTITY.DOES_ENTITY_EXIST(veh) then
        vehicleDismantle.note(quiet, "Couldn't find the player's vehicle.")
        return nil
    end
    if VEHICLE.GET_PED_IN_VEHICLE_SEAT(veh, -1, false) ~= ped then
        vehicleDismantle.note(quiet, "Player is a passenger, not driving.")
        return nil
    end
    local model = ENTITY.GET_ENTITY_MODEL(veh)
    return veh,
        Natives.InvokeBool(aircraftSabotage.H_IS_PLANE, model),
        Natives.InvokeBool(aircraftSabotage.H_IS_HELI, model)
end

function vehicleDismantle.run(pid, quiet)
    local veh, isPlane, isHeli = vehicleDismantle.getVehicle(pid, quiet)
    if not veh then return "done" end

    if not aircraftSabotage.takeControl(veh) then
        return "retry"
    end

    local vehAddr = aircraftSabotage.getVehAddr(veh)
    if not vehAddr then
        vehicleDismantle.note(quiet, "Couldn't resolve the vehicle's memory address.")
        return "done"
    end

    local dmg = vehAddr + vehicleDismantle.DMG_OFFSET
    local parent = Memory.ReadLong(dmg + vehicleDismantle.PARENT_REL)
    if parent ~= vehAddr then
        vehicleDismantle.note(quiet, "Vehicle layout check failed; dismantle unavailable on this build.")
        logErr("[VehicleDismantle] m_pParent mismatch (CVehicleDamage offset invalid?)")
        return "done"
    end

    Natives.InvokeVoid(vehicleDismantle.H_WHEELS_CAN_BREAK, veh, true)

    local bfn = vehicleDismantle.resolveFn(vehicleDismantle.blowUpFn, "BlowUpCarParts")
    if bfn then
        for _ = 1, vehicleDismantle.BLOWUP_PASSES do
            Memory.LuaCallCFunction(bfn, dmg, 0, 0)
        end
    end

    for door = 0, 5 do
        Natives.InvokeVoid(vehicleDismantle.H_DOOR_BROKEN, veh, door, false)
    end

    local wfn = vehicleDismantle.resolveFn(vehicleDismantle.wheelFn, "BreakOffWheel")
    if wfn then
        local n = Memory.ReadInt(vehAddr + vehicleDismantle.NUMWHEELS_OFF)
        if n and n > 0 and n <= 10 then
            for i = 0, n - 1 do
                Memory.LuaCallCFunction(wfn, dmg, i)
            end
        end
    elseif bfn then
        vehicleDismantle.note(quiet, "Wheel break-off unavailable (couldn't locate the game function).")
    end

    local kind = aircraftSabotage.dismantleExtras(veh, vehAddr, isPlane, isHeli)

    if bfn then
        vehicleDismantle.note(quiet, (kind or "Vehicle") .. " dismantled.")
        return "ok"
    end
    vehicleDismantle.note(quiet, "Dismantle unavailable (couldn't locate the game function).")
    return "done"
end


function vehicleDismantle.classify(pid)
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then return "none" end
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then return "none" end

    if PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
        if veh and veh ~= 0 and ENTITY.DOES_ENTITY_EXIST(veh) then
            if VEHICLE.GET_PED_IN_VEHICLE_SEAT(veh, -1, false) ~= ped then return "none" end
            return "ready", veh
        end
    elseif not PLAYER.IS_REMOTE_PLAYER_IN_NON_CLONED_VEHICLE(pid) then
        return "none"
    end

    local pos = ENTITY.GET_ENTITY_COORDS(ped, true)
    if pos.z < vehicleDismantle.LIMBO_Z then return "none" end
    return "hop", pos
end

function vehicleDismantle.camTo(pid)
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then return end
    local p = ENTITY.GET_ENTITY_COORDS(ped, true)
    local vd = vehicleDismantle
    if not vd.cam then
        vd.cam = Natives.InvokeInt(vd.H_CREATE_CAM, "DEFAULT_SCRIPTED_CAMERA", true)
        if not vd.cam or vd.cam == 0 then vd.cam = nil return end
        Natives.InvokeVoid(vd.H_SET_CAM_ACTIVE, vd.cam, true)
        Natives.InvokeVoid(vd.H_RENDER_CAMS, true, false, 0, true, false, 0)
    end
    Natives.InvokeVoid(vd.H_SET_CAM_COORD, vd.cam,
        p.x + 0.0, p.y - vd.CAM_BACK_M, p.z + vd.CAM_UP_M)
    Natives.InvokeVoid(vd.H_POINT_CAM_AT, vd.cam, ped, 0.0, 0.0, 0.0, true)
    Natives.InvokeVoid(vd.H_SET_FOCUS_ENT, ped)
end

function vehicleDismantle.camRelease()
    local vd = vehicleDismantle
    if not vd.cam then return end
    Natives.InvokeVoid(vd.H_RENDER_CAMS, false, false, 0, true, false, 0)
    Natives.InvokeVoid(vd.H_DESTROY_CAM, vd.cam, true)
    Natives.InvokeVoid(vd.H_CLEAR_FOCUS)
    vd.cam = nil
end

function vehicleDismantle.holdScope(s)
    vehicleDismantle.camTo(s.cur)
end


function vehicleDismantle.specFeat(pid)
    local f = FeatureMgr.GetFeature(vehicleDismantle.SPECTATE_BUILTIN, pid)
    if f then return f end
    return FeatureMgr.GetFeatureByName(vehicleDismantle.SPECTATE_NAME, pid)
end

function vehicleDismantle.spectatedPid()
    for pid = 0, 31 do
        local f = vehicleDismantle.specFeat(pid)
        if f and f:GetBoolValue() then return pid end
    end
    return nil
end

function vehicleDismantle.startSweep(now)
    local s = {
        list     = {},
        i        = 0,
        cur      = nil,
        phase    = nil,
        ok       = 0,
        noCtrl   = 0,
        noReach  = 0,
        inflight = 0,
        deadline = 0,
        dwellUntil = 0,
        endBy    = now + vehicleDismantle.SWEEP_MAX_MS,
        lastTick = now,
        paused   = 0,
    }
    for pid = 0, 31 do
        if lockOntoPlayers.isSessionTarget(pid)
                and vehicleDismantle.classify(pid) ~= "none" then
            s.list[#s.list + 1] = pid
        end
    end
    s.n = #s.list
    if s.n == 0 then
        vehicleDismantle.toast(T("No one else in the session is in a vehicle."))
        return
    end
    s.specPid = vehicleDismantle.spectatedPid()
    if s.specPid then
        vehicleDismantle.specWant = { pid = s.specPid, on = false }
        s.specUntil = now + vehicleDismantle.SPEC_SETTLE_MS
        logf("[VehicleDismantle] menu spectate is on pid %d -- dropping it for the sweep",
            s.specPid)
    end

    vehicleDismantle.sweep = s
    vehicleDismantle.toast(T("Dismantling %d vehicle(s)..."):format(s.n))
end

function vehicleDismantle.abortSweep()
    local s = vehicleDismantle.sweep
    if not s then return end
    vehicleDismantle.sweep = nil
    vehicleDismantle.camRelease()

    vehicleDismantle.specWant = nil
    if s.specPid and not scriptUnloading and Players.GetById(s.specPid) then
        vehicleDismantle.specWant = { pid = s.specPid, on = true }
    end
end

function vehicleDismantle.endSweep(cancelled)
    local s = vehicleDismantle.sweep
    if not s then return end
    local ok, n, noCtrl, noReach = s.ok, s.n, s.noCtrl, s.noReach
    vehicleDismantle.abortSweep()
    logf("[VehicleDismantle] sweep done: %d/%d ok, %d no control, %d unreachable%s",
        ok, n, noCtrl, noReach, cancelled and " (stopped)" or "")
    local why = {}
    if noCtrl > 0 then why[#why + 1] = ("%d wouldn't hand over control"):format(noCtrl) end
    if noReach > 0 then why[#why + 1] = ("%d out of reach"):format(noReach) end
    local tail = #why > 0 and (" - " .. table.concat(why, ", ")) or ""
    if cancelled then
        vehicleDismantle.toast(T("Stopped after %d of %d vehicle(s)."):format(ok, n))
    elseif ok > 0 then
        vehicleDismantle.toast(T("Dismantled %d of %d vehicle(s)%s."):format(ok, n, tail))
    else
        vehicleDismantle.toast(T("Couldn't reach any vehicles%s."):format(tail))
    end
end

function vehicleDismantle.sweepJobDone(why)
    local s = vehicleDismantle.sweep
    if not s then return end
    s.inflight = s.inflight - 1
    if not why then s.ok = s.ok + 1
    elseif why == "control" then s.noCtrl = s.noCtrl + 1 end
    s.phase = "dwell"
    s.dwellUntil = MISC.GET_GAME_TIMER()
        + (why and 0 or vehicleDismantle.SWEEP_DWELL_MS)
end

function vehicleDismantle.sweepTick(now)
    local s = vehicleDismantle.sweep
    if not s then return end

    local dt = now - s.lastTick
    s.lastTick = now
    if not isPlayerReady() then
        s.paused = s.paused + dt
        if s.paused >= vehicleDismantle.SWEEP_PAUSE_MAX_MS then
            vehicleDismantle.endSweep(true)
            return
        end
        s.endBy, s.deadline = s.endBy + dt, s.deadline + dt
        s.dwellUntil = s.dwellUntil + dt
        return
    end

    if s.specUntil then
        local released = vehicleDismantle.specWant == nil
                         and not NETWORK.NETWORK_IS_IN_SPECTATOR_MODE()
        if not released and now < s.specUntil then
            s.endBy = s.endBy + dt
            return
        end
        s.specUntil = nil
    end

    if now >= s.endBy and s.inflight == 0 then
        vehicleDismantle.endSweep(false)
        return
    end

    if not s.cur then
        s.i = s.i + 1
        if s.i > #s.list then
            vehicleDismantle.endSweep(false)
            return
        end
        local pid = s.list[s.i]
        if vehicleDismantle.classify(pid) == "none" then
            s.n = s.n - 1
            return
        end
        s.cur, s.phase = pid, "wait"
        s.deadline = now + vehicleDismantle.SWEEP_HOP_MS
        vehicleDismantle.holdScope(s)
        vehicleDismantle.toast(T("Dismantling %s (%d/%d)..."):format(
            Players.GetName(pid) or T("player"),  s.i,  #s.list))
        return
    end

    vehicleDismantle.holdScope(s)
    if s.inflight > 0 then return end

    if s.phase == "wait" then
        local kind = vehicleDismantle.classify(s.cur)
        if kind == "ready" then
            s.inflight = 1
            vehicleDismantle.queue[#vehicleDismantle.queue + 1] =
                { pid = s.cur, quiet = true, sweep = true }
            return
        end
        if kind == "none" then
            s.n = s.n - 1
            vehicleDismantle.endVisit(s)
        elseif now >= s.deadline then
            s.noReach = s.noReach + 1
            logf("[VehicleDismantle] pid %d: vehicle never cloned", s.cur)
            vehicleDismantle.endVisit(s)
        end
        return
    end

    if now >= s.dwellUntil then vehicleDismantle.endVisit(s) end
end

function vehicleDismantle.endVisit(s)
    s.cur, s.phase = nil, nil
end

function vehicleDismantle.onTick(f)
    if not f:IsToggled() then return end
    local now = MISC.GET_GAME_TIMER()
    vehicleDismantle.sweepTick(now)
    if #vehicleDismantle.queue == 0 then return end
    if not isPlayerReady() then
        for i = 1, #vehicleDismantle.queue do vehicleDismantle.queue[i].started = nil end
        return
    end
    local q = vehicleDismantle.queue
    vehicleDismantle.queue = {}
    local ran = 0
    for i = 1, #q do
        local job = q[i]
        if job.all then
            if vehicleDismantle.sweep then
                vehicleDismantle.endSweep(true)
            else
                vehicleDismantle.startSweep(now)
            end
        elseif job.sweep and not vehicleDismantle.sweep then
        elseif ran >= vehicleDismantle.DRAIN or (job.nextTry and now < job.nextTry) then
            vehicleDismantle.queue[#vehicleDismantle.queue + 1] = job
        else
            job.started = job.started or now
            ran = ran + 1
            local window = job.sweep and vehicleDismantle.SWEEP_CONTROL_MS or 3000
            local result
            if job.sweep and not lockOntoPlayers.isSessionTarget(job.pid) then
                result = "gone"
            else
                result = vehicleDismantle.run(job.pid, job.quiet)
            end
            if result == "retry" and now - job.started < window then
                vehicleDismantle.queue[#vehicleDismantle.queue + 1] = job
                job.nextTry = now + 100
            else
                if result == "retry" then
                    logf("[VehicleDismantle] pid %d: no control after %dms", job.pid, window)
                    vehicleDismantle.note(job.quiet,
                        "Couldn't get control of the player's vehicle.")
                elseif result == "ok" and not job.quiet then
                    telemetryCountAction("DismantleVehicle")
                end
                if job.sweep then
                    vehicleDismantle.sweepJobDone(result ~= "ok"
                        and (result == "retry" and "control" or "gone") or nil)
                end
            end
        end
    end
end

for _, featureHash in ipairs(FeatureMgr.AddPlayerFeature(
    H.DISMANTLE_VEHICLE, "Dismantle", eFeatureType.Button,
    "Breaks off as much as the vehicle has in one go - doors, bumpers, fenders, wheels, panels and more, plus wings/tail/props on planes and the tail boom/rotors on helis. Works on any vehicle.",
    function(f)
        vehicleDismantle.queue[#vehicleDismantle.queue + 1] = { pid = f:GetPlayerIndex() }
    end)) do
    FeatureMgr.GetFeature(featureHash):SetSaveable(false)
end

FeatureMgr.AddFeature(H.DISMANTLE_VEHICLE_ALL, "Dismantle All Vehicles", eFeatureType.Button,
    "Dismantles the vehicle of every other player in the session, one at a time. The camera spectates each player while their vehicle is torn apart, so you can watch it happen. Press again to stop.",
    function(_)
        vehicleDismantle.queue[#vehicleDismantle.queue + 1] = { all = true }
        if not vehicleDismantle.sweep then telemetryCountAction("DismantleVehicleAll") end
    end)
    :SetSaveable(false)

EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
    if scriptUnloading then return end
    local w = vehicleDismantle.specWant
    if not w then return end
    vehicleDismantle.specWant = nil

    local f = vehicleDismantle.specFeat(w.pid)
    if not f then
        logErr('[VehicleDismantle] the menu\'s "Spectate Player" feature is missing on this build.')
        return
    end
    f:SetBoolValue(w.on):OnClick()
    logf("[VehicleDismantle] menu spectate %s for pid %d",
        w.on and "restored" or "switched off", w.pid)
end)

centralOnTick(FeatureMgr.AddFeature(vehicleDismantle.runnerHash, "##VehicleDismantleRunner",
    eFeatureType.Toggle, "", vehicleDismantle.onTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
FeatureMgr.GetFeature(vehicleDismantle.runnerHash):Toggle()

do
local vehicleHeist = {
    ENTER_FLAGS   = 2 | 8 | 16 | 64 | 512,
    GETAWAY_STYLE = 4 | 32 | 256 | 4096 | 262144 | 524288,
    PING_LIMIT_MS = 80,
    N_CAN_DAMAGE   = 0x1760FFA8AB074D66,
    N_SET_PROOFS   = 0xFAEE099C6F890BB8,
    N_COMBAT_ATTR  = 0x9F7794730795E019,
    N_FLEE_ATTR    = 0x70A2D1137C8ED7C9,
    N_KEEP_TASK    = 0x971D38760FBC02EF,
    N_LOCK_ALL     = 0xA2F80B8D040727CC,
    N_GET_LOCK_FOR = 0xF6AF6CB341349015,
    delBuf = Memory.Alloc(4),
    active = nil,
}
vehicleHeist.fn = {}

vehicleHeist.fn.now   = function() return Time.GetEpocheMs() end
vehicleHeist.fn.stop  = function() return scriptUnloading == true end
vehicleHeist.fn.toast = function(msg) GUI.AddToast("VibeScript", msg, 5000) end
vehicleHeist.fn.name  = function(pid)
    return Players.GetName(pid) or T("player")
end
vehicleHeist.fn.localPed = function() return PLAYER.PLAYER_PED_ID() end

vehicleHeist.fn.seatOf = function(ped)
    local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if veh == 0 then return nil end
    local seats = VEHICLE.GET_VEHICLE_MODEL_NUMBER_OF_SEATS(ENTITY.GET_ENTITY_MODEL(veh))
    for i = -1, seats - 1 do
        if VEHICLE.GET_PED_IN_VEHICLE_SEAT(veh, i, false) == ped then return i end
    end
    return nil
end

vehicleHeist.fn.noMigrate = function(ped)
    local netId = NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(ped)
    if netId ~= 0 then NETWORK.SET_NETWORK_ID_CAN_MIGRATE(netId, false) end
end

vehicleHeist.fn.markForRemoval = function()
    if not vehicleHeist.activeAddr then return 0 end
    return UnloadReap.markAll(
        { { addr = vehicleHeist.activeAddr, pop = vehicleHeist.activePop } },
        "VehicleHeist")
end

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    vehicleHeist.fn.markForRemoval()
end)

vehicleHeist.fn.deletePed = function(ped)
    if not ped or ped == 0 then return end
    if not ENTITY.DOES_ENTITY_EXIST(ped) then return end
    Memory.WriteInt(vehicleHeist.delBuf, ped)
    ENTITY.DELETE_ENTITY(vehicleHeist.delBuf)
end

vehicleHeist.fn.requestControl = function(entity, timeoutMs)
    local deadline = vehicleHeist.fn.now() + (timeoutMs or 2500)
    while deadline > vehicleHeist.fn.now()
        and not NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(entity)
        and not vehicleHeist.fn.stop() do
        NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(entity)
        Script.Yield()
    end
end

vehicleHeist.fn.harden = function(ped)
    ENTITY.SET_ENTITY_INVINCIBLE(ped, true)
    Natives.InvokeVoid(vehicleHeist.N_CAN_DAMAGE, ped, false)
    Natives.InvokeVoid(vehicleHeist.N_SET_PROOFS, ped,
        true, true, true, true, true, true, 1, true)
    PED.SET_PED_SUFFERS_CRITICAL_HITS(ped, false)

    PED.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS(ped, true)
    Natives.InvokeVoid(vehicleHeist.N_FLEE_ATTR, ped, 2, true)
    PED.SET_PED_CONFIG_FLAG(ped, 229, true)
    PED.SET_PED_CONFIG_FLAG(ped, 294, true)
    PED.SET_PED_CONFIG_FLAG(ped, 208, true)
    PED.SET_PED_CONFIG_FLAG(ped, 188, true)
    Natives.InvokeVoid(vehicleHeist.N_COMBAT_ATTR, ped, 3,  false)
    Natives.InvokeVoid(vehicleHeist.N_COMBAT_ATTR, ped, 6,  true)
    Natives.InvokeVoid(vehicleHeist.N_COMBAT_ATTR, ped, 17, false)
    Natives.InvokeVoid(vehicleHeist.N_COMBAT_ATTR, ped, 38, true)
    Natives.InvokeVoid(vehicleHeist.N_COMBAT_ATTR, ped, 58, true)
    Natives.InvokeVoid(vehicleHeist.N_KEEP_TASK, ped, true)
end

vehicleHeist.fn.clearPlayerLocks = function(vehicle, pid)
    local before = Natives.InvokeBool(vehicleHeist.N_GET_LOCK_FOR, vehicle, pid)
    Natives.InvokeVoid(vehicleHeist.N_LOCK_ALL, vehicle, false)
    logf("[VehicleHeist] getaway player locks for victim %s -> %s",
        tostring(before),
        tostring(Natives.InvokeBool(vehicleHeist.N_GET_LOCK_FOR, vehicle, pid)))
end

vehicleHeist.fn.spawnThief = function(x, y, z)
    local ped = GTA.CreateRandomPed(x, y, z - 30.0)
    if not ped or ped == 0 then return 0 end
    vehicleHeist.fn.harden(ped)
    vehicleHeist.fn.noMigrate(ped)
    return ped
end

vehicleHeist.fn.cloak = function(userPed, pid)
    NETWORK.SET_LOCAL_PLAYER_AS_GHOST(true, 0)
    ENTITY.SET_ENTITY_COLLISION(userPed, false, false)
    ENTITY.FREEZE_ENTITY_POSITION(userPed, true)
    ENTITY.SET_ENTITY_ALPHA(userPed, 0, false)
    local cam = Players.GetCam(pid)
    if cam then
        ENTITY.SET_ENTITY_COORDS_NO_OFFSET(userPed, cam.x, cam.y, cam.z, false, false, false)
    end
end

vehicleHeist.fn.hide = function(userPed)
    NETWORK.SET_LOCAL_PLAYER_AS_GHOST(true, 0)
    ENTITY.SET_ENTITY_ALPHA(userPed, 0, false)
end

vehicleHeist.fn.uncloak = function(userPed, restorePos)
    ENTITY.SET_ENTITY_COLLISION(userPed, true, true)
    ENTITY.FREEZE_ENTITY_POSITION(userPed, false)
    ENTITY.RESET_ENTITY_ALPHA(userPed)
    NETWORK.SET_LOCAL_PLAYER_AS_GHOST(false, 0)
    NETWORK.RESET_GHOST_ALPHA()
    if restorePos then
        ENTITY.SET_ENTITY_COORDS_NO_OFFSET(userPed,
            restorePos.x, restorePos.y, restorePos.z, false, false, false)
    end
end

vehicleHeist.fn.queue = function(pid, kind)
    if not pid or pid < 0 then return end
    if pid == GTA.GetLocalPlayerId() then
        vehicleHeist.fn.toast(T("Can't jack your own vehicle."))
        return
    end
    if playerState.takeover or #playerState.takeoverPending > 0 then
        vehicleHeist.fn.toast(T("Already jacking a vehicle - let that finish first."))
        return
    end
    playerState.takeoverPending[#playerState.takeoverPending + 1] = { pid = pid, kind = kind }
end

vehicleHeist.fn.runHijack = function(pid)
    local f = vehicleHeist.fn
    local timer = f.now() + 2500
    local targetPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if targetPed == 0 or not ENTITY.DOES_ENTITY_EXIST(targetPed) then
        f.toast(T("%s isn't in a vehicle."):format(f.name(pid))); return
    end
    local vehicle = PED.GET_VEHICLE_PED_IS_IN(targetPed, false)
    local ping = math.floor(NETWORK.NETWORK_GET_AVERAGE_PING(pid))

    if PLAYER.IS_REMOTE_PLAYER_IN_NON_CLONED_VEHICLE(pid) then
        f.toast(T("%s's vehicle isn't streamed in yet. Spectate them first, then try again."):format(f.name(pid))); return
    end
    if not PED.IS_PED_IN_ANY_VEHICLE(targetPed, false) or vehicle == 0 then
        f.toast(T("%s isn't in a vehicle."):format(f.name(pid))); return
    end
    if not PED.IS_PED_A_PLAYER(VEHICLE.GET_PED_IN_VEHICLE_SEAT(vehicle, -1, false)) then
        f.toast(T("%s's vehicle already has someone in the driver seat."):format(f.name(pid))); return
    end

    local pos = ENTITY.GET_ENTITY_COORDS(targetPed, true)
    local thief = f.spawnThief(pos.x, pos.y, pos.z)
    if thief == 0 then
        f.toast(T("Couldn't spawn a ped to hijack the vehicle.")); return
    end
    vehicleHeist.active = thief
    vehicleHeist.activeAddr = UnloadReap.addrOf(thief)
    vehicleHeist.activePop  = UnloadReap.popOf(thief)

    TASK.TASK_ENTER_VEHICLE(thief, vehicle, 1000, -1, 1.0, vehicleHeist.ENTER_FLAGS, 0, false)

    while not TASK.GET_IS_TASK_ACTIVE(thief, 160) and not f.stop() do
        if timer < f.now() then
            f.toast(T("Couldn't get the ped into their vehicle."))
            f.deletePed(thief); vehicleHeist.active = nil
            vehicleHeist.activeAddr, vehicleHeist.activePop = nil, nil; return
        end
        Script.Yield()
    end
    if f.stop() then return end

    repeat
        if TASK.GET_IS_TASK_ACTIVE(targetPed, 2) then timer = f.now() + 4000 end
        if timer < f.now() and PED.IS_PED_IN_ANY_VEHICLE(targetPed, false) then
            f.toast(ping > vehicleHeist.PING_LIMIT_MS
                and (T("Couldn't hijack the vehicle - the target's ping is too high (%sms)."):format(ping))
                or T("Couldn't hijack the vehicle."))
            f.deletePed(thief); vehicleHeist.active = nil
            vehicleHeist.activeAddr, vehicleHeist.activePop = nil, nil; return
        end
        Script.Yield()
    until f.stop() or not PED.IS_PED_IN_ANY_VEHICLE(targetPed, false)
    if f.stop() then return end

    if f.seatOf(thief) == -1 then
        f.requestControl(vehicle, 2500)
        TASK.TASK_VEHICLE_DRIVE_WANDER(thief, vehicle, 9999.0, vehicleHeist.GETAWAY_STYLE)
        f.toast(T("Hijacked %s's vehicle - it's driving off."):format(f.name(pid)))
    end

    if not TASK.GET_IS_TASK_ACTIVE(thief, 151) and not PED.IS_PED_IN_ANY_VEHICLE(thief, false) then
        timer = f.now() + 2500
        repeat
            if timer < f.now() then
                f.toast(T("Got them out, but couldn't drive the vehicle away."))
                f.deletePed(thief); vehicleHeist.active = nil
                vehicleHeist.activeAddr, vehicleHeist.activePop = nil, nil; return
            end
            PED.SET_PED_INTO_VEHICLE(thief, vehicle, -1)
            Script.Yield()
        until f.stop() or PED.GET_VEHICLE_PED_IS_IN(thief, false) == vehicle
        if f.stop() then return end
        f.requestControl(vehicle, 2500)
        TASK.TASK_VEHICLE_DRIVE_WANDER(thief, vehicle, 9999.0, vehicleHeist.GETAWAY_STYLE)
    end

    Script.Yield(5000)
    if not PED.IS_PED_IN_ANY_VEHICLE(thief, false) then
        f.deletePed(thief)
    else
        f.clearPlayerLocks(vehicle, pid)
        Memory.WriteInt(vehicleHeist.delBuf, thief)
        Natives.InvokeVoid(0x2595DD4236549CE3, vehicleHeist.delBuf)
        logf("[VehicleHeist] getaway released, poptype %s -> %s",
            tostring(vehicleHeist.activePop), tostring(UnloadReap.popOf(thief)))
    end
    telemetryCountAction("CarjackVehicle")
    vehicleHeist.active = nil
    vehicleHeist.activeAddr, vehicleHeist.activePop = nil, nil
end

vehicleHeist.fn.runTakeover = function(pid)
    local f = vehicleHeist.fn
    local timer = f.now() + 2500
    local userPed = f.localPed()
    local localPos = ENTITY.GET_ENTITY_COORDS(userPed, true)
    local targetPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if targetPed == 0 or not ENTITY.DOES_ENTITY_EXIST(targetPed) then
        f.toast(T("%s isn't in a vehicle."):format(f.name(pid))); return
    end
    local vehicle = PED.GET_VEHICLE_PED_IS_IN(targetPed, false)
    local ping = math.floor(NETWORK.NETWORK_GET_AVERAGE_PING(pid))

    if PLAYER.IS_REMOTE_PLAYER_IN_NON_CLONED_VEHICLE(pid) then
        f.toast(T("%s's vehicle isn't streamed in yet. Spectate them first, then try again."):format(f.name(pid))); return
    end
    if not PED.IS_PED_IN_ANY_VEHICLE(targetPed, false) or vehicle == 0 then
        f.toast(T("%s isn't in a vehicle."):format(f.name(pid))); return
    end

    DECORATOR.DECOR_REMOVE(vehicle, "Player_Vehicle")

    local targetPos = ENTITY.GET_ENTITY_COORDS(targetPed, true)
    local dx, dy, dz = localPos.x - targetPos.x, localPos.y - targetPos.y, localPos.z - targetPos.z
    local pedDistance = math.sqrt(dx * dx + dy * dy + dz * dz)
    local tp = false
    if pedDistance > 100.0 then
        f.cloak(userPed, pid)
        tp = true
    end

    local thief = f.spawnThief(targetPos.x, targetPos.y, targetPos.z)
    if thief == 0 then
        if tp then f.uncloak(userPed, localPos) end
        f.toast(T("Couldn't spawn a ped to take over the vehicle.")); return
    end
    vehicleHeist.active = thief
    vehicleHeist.activeAddr = UnloadReap.addrOf(thief)
    vehicleHeist.activePop  = UnloadReap.popOf(thief)
    TASK.TASK_ENTER_VEHICLE(thief, vehicle, 1000, -1, 1.0, vehicleHeist.ENTER_FLAGS, 0, false)

    if f.seatOf(thief) ~= -1 then
        repeat
            PED.SET_PED_INTO_VEHICLE(thief, vehicle, -1)
            if tp then f.cloak(userPed, pid) end
            if TASK.GET_IS_TASK_ACTIVE(targetPed, 2) then timer = f.now() + 5000 end
            if timer < f.now() then
                if tp then f.uncloak(userPed, localPos) end
                f.toast(ping > vehicleHeist.PING_LIMIT_MS
                    and (T("Couldn't take over the vehicle - the target's ping is too high (%sms)."):format(ping))
                    or T("Couldn't take over the vehicle."))
                f.deletePed(thief); vehicleHeist.active = nil
                vehicleHeist.activeAddr, vehicleHeist.activePop = nil, nil; return
            end
            Script.Yield()
        until f.stop() or f.seatOf(targetPed) ~= -1
    end
    if f.stop() then
        if tp then f.uncloak(userPed, localPos) end
        return
    end

    f.deletePed(thief)
    vehicleHeist.active = nil
    vehicleHeist.activeAddr, vehicleHeist.activePop = nil, nil
    timer = f.now() + 2500
    PED.SET_PED_INTO_VEHICLE(userPed, vehicle, -1)
    repeat
        if timer < f.now() then
            local decor = DECORATOR.DECOR_GET_INT(vehicle, "Player_Vehicle")
            f.toast(decor ~= 0
                and T("Got them out, but their personal-vehicle permissions blocked the seat.")
                or T("Got them out, but couldn't warp into the seat."))
            if tp then f.uncloak(userPed, localPos) end
            return
        end
        if not PED.IS_PED_IN_ANY_VEHICLE(targetPed, false) then
            if tp then f.hide(userPed) end
            PED.SET_PED_INTO_VEHICLE(userPed, vehicle, -1)
        end
        Script.Yield()
    until f.stop() or PED.GET_VEHICLE_PED_IS_IN(userPed, false) == vehicle
    if f.stop() then
        if tp then f.uncloak(userPed, localPos) end
        return
    end

    f.toast(T("Took over %s's vehicle."):format(f.name(pid)))
    telemetryCountAction("TakeTheWheel")
    if tp then f.uncloak(userPed) end
end

Script.RegisterLooped(function()
    if ShouldUnload() or scriptUnloading then
        if vehicleHeist.active then
            vehicleHeist.fn.deletePed(vehicleHeist.active)
            vehicleHeist.active = nil
            vehicleHeist.activeAddr, vehicleHeist.activePop = nil, nil
        end
        playerState.takeover = nil
        Script.Yield(100)
        return
    end

    local job = table.remove(playerState.takeoverPending, 1)
    if not job then
        Script.Yield(100)
        return
    end

    playerState.takeover = true
    local routine = (job.kind == "hijack") and vehicleHeist.fn.runHijack or vehicleHeist.fn.runTakeover
    local ok, err = pcall(routine, job.pid)
    if not ok then
        logErr("[VehJack] " .. tostring(err))
        GUI.AddToast("VibeScript", T("Vehicle jack hit an error (see log)."), 4000)
        if vehicleHeist.active then
            vehicleHeist.fn.deletePed(vehicleHeist.active)
            vehicleHeist.active = nil
            vehicleHeist.activeAddr, vehicleHeist.activePop = nil, nil
        end
    end
    playerState.takeover = nil
    Script.Yield()
end)
for _, hash in ipairs(FeatureMgr.AddPlayerFeature(
    H.HIJACK_VEH, "Carjack", eFeatureType.Button,
    "Spawns a ped that jacks them out and drives their car away.",
    function(f) vehicleHeist.fn.queue(f:GetPlayerIndex(), "hijack") end)) do
    FeatureMgr.GetFeature(hash):SetSaveable(false)
end
for _, hash in ipairs(FeatureMgr.AddPlayerFeature(
    H.TAKEOVER_VEH, "Take the Wheel", eFeatureType.Button,
    "Spawns a ped that jacks them out, then warps you in so you drive.",
    function(f) vehicleHeist.fn.queue(f:GetPlayerIndex(), "takeover") end)) do
    FeatureMgr.GetFeature(hash):SetSaveable(false)
end
end

do
local towDispatch = {
    MODEL            = Utils.Joaat("towtruck3"),
    DRIVER_MODEL     = Utils.Joaat("s_m_m_trucker_01"),
    DRIVE_STYLE      = 4096 | 262144,
    DRIVE_SPEED      = 20.0,
    MODEL_WAIT_MS    = 5000,
    CONTROL_WAIT_MS  = 5000,
    DRIVER_WAIT_MS   = 2000,
    HOOK_WAIT_MS     = 5000,
    HOOK_STABLE_MS   = 2000,
    N_IS_CAR         = 0x7F6DB52EEFC96DF8,
    N_SET_MAX_SPEED  = 0xBAA045B4E42F3C06,
    N_SET_ON_GROUND  = 0x49733E92263139D1,
    N_CREATE_DRIVER  = 0x7DD959874C1FD534,
    N_ATTACH_TOW     = 0x29A16F8D621C4508,
    N_IS_ATTACHED    = 0x146DF9EC4C4B9FD4,
    N_CAN_DAMAGE     = 0x1760FFA8AB074D66,
    N_SET_PROOFS     = 0xFAEE099C6F890BB8,
    N_SET_STRONG     = 0x3E8C8727991A8A0B,
    N_VISIBLE_DAMAGE = 0x4C7028F78FFD3681,
    N_ENGINE_DEGRADE = 0x983765856F2564F9,
    N_TYRES_BURST    = 0xEB9DC3C7D8596C46,
    N_NO_TANK_FIRE   = 0x465BF26AB9684352,
    N_NO_TANK_DAMAGE = 0x37C8252A7C92D017,
    delBuf           = Memory.Alloc(4),
    active           = nil,
    modelsHeld       = false,
}

towDispatch.now = function() return Time.GetEpocheMs() end
towDispatch.stopping = function()
    return scriptUnloading == true or ShouldUnload() == true
end
towDispatch.toast = function(message)
    GUI.AddToast("Tow Vehicle", message, 4500)
end
towDispatch.playerName = function(pid)
    local name = Players.GetName(pid)
    return (name and name ~= "") and name or ("Player %d"):format(pid)
end

towDispatch.deleteEntity = function(handle)
    if not handle or handle == 0 or not ENTITY.DOES_ENTITY_EXIST(handle) then return end
    NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(handle)
    Memory.WriteInt(towDispatch.delBuf, handle)
    ENTITY.DELETE_ENTITY(towDispatch.delBuf)
    if ENTITY.DOES_ENTITY_EXIST(handle) then
        Memory.WriteInt(towDispatch.delBuf, handle)
        ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED(towDispatch.delBuf)
    end
end

towDispatch.markForRemoval = function()
    local a = towDispatch.active
    if not a then return 0 end
    return UnloadReap.markAll({
        { addr = a.truckAddr,  pop = a.truckPop  },
        { addr = a.driverAddr, pop = a.driverPop },
    }, "TowVehicle")
end

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    towDispatch.markForRemoval()
end)

towDispatch.abort = function()
    local active = towDispatch.active
    if not active then return end
    if active.target and active.target ~= 0 and ENTITY.DOES_ENTITY_EXIST(active.target) then
        Natives.InvokeVoid(towDispatch.N_SET_MAX_SPEED, active.target, 0.0)
    end
    towDispatch.deleteEntity(active.driver)
    towDispatch.deleteEntity(active.truck)
    towDispatch.active = nil
end

towDispatch.loadModels = function()
    if not STREAMING.IS_MODEL_VALID(towDispatch.MODEL)
    or not STREAMING.IS_MODEL_VALID(towDispatch.DRIVER_MODEL) then return false end
    local deadline = towDispatch.now() + towDispatch.MODEL_WAIT_MS
    repeat
        STREAMING.REQUEST_MODEL(towDispatch.MODEL)
        STREAMING.REQUEST_MODEL(towDispatch.DRIVER_MODEL)
        if STREAMING.HAS_MODEL_LOADED(towDispatch.MODEL)
        and STREAMING.HAS_MODEL_LOADED(towDispatch.DRIVER_MODEL) then
            towDispatch.modelsHeld = true
            return true
        end
        Script.Yield()
    until towDispatch.stopping() or towDispatch.now() >= deadline
    towDispatch.modelsHeld = true
    return false
end

towDispatch.releaseModels = function()
    if not towDispatch.modelsHeld then return end
    towDispatch.modelsHeld = false
    STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(towDispatch.MODEL)
    STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(towDispatch.DRIVER_MODEL)
end

towDispatch.createDriver = function(truck)
    local driver = 0
    Script.ExecuteAsScript("freemode", function()
        driver = Natives.InvokeInt(towDispatch.N_CREATE_DRIVER,
            truck, 4, towDispatch.DRIVER_MODEL, -1, true, false) or 0
    end)
    if driver == 0 or not ENTITY.DOES_ENTITY_EXIST(driver) then
        driver = Natives.InvokeInt(towDispatch.N_CREATE_DRIVER,
            truck, 4, towDispatch.DRIVER_MODEL, -1, false, false) or 0
    end
    if driver == 0 or not ENTITY.DOES_ENTITY_EXIST(driver) then return 0 end

    local deadline = towDispatch.now() + towDispatch.DRIVER_WAIT_MS
    repeat
        if VEHICLE.GET_PED_IN_VEHICLE_SEAT(truck, -1, false) == driver then return driver end
        PED.SET_PED_INTO_VEHICLE(driver, truck, -1)
        Script.Yield(100)
    until towDispatch.stopping() or towDispatch.now() >= deadline

    towDispatch.deleteEntity(driver)
    return 0
end

towDispatch.takeControl = function(vehicle)
    if NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(vehicle) then return true end

    local deadline = towDispatch.now() + towDispatch.CONTROL_WAIT_MS
    repeat
        NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(vehicle)
        if NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(vehicle) then return true end
        Script.Yield()
    until towDispatch.stopping() or towDispatch.now() >= deadline
    return false
end

towDispatch.fail = function(message)
    towDispatch.abort()
    if not towDispatch.stopping() then towDispatch.toast(message) end
end

towDispatch.protectTruck = function(truck)
    ENTITY.SET_ENTITY_INVINCIBLE(truck, true)
    Natives.InvokeVoid(towDispatch.N_CAN_DAMAGE, truck, false)
    Natives.InvokeVoid(towDispatch.N_SET_PROOFS, truck,
        true, true, true, true, true, true, 1, true)
    Natives.InvokeVoid(towDispatch.N_SET_STRONG, truck, true)
    Natives.InvokeVoid(towDispatch.N_VISIBLE_DAMAGE, truck, false)
    Natives.InvokeVoid(towDispatch.N_ENGINE_DEGRADE, truck, false)
    Natives.InvokeVoid(towDispatch.N_TYRES_BURST, truck, false)
    Natives.InvokeVoid(towDispatch.N_NO_TANK_FIRE, truck, true)
    Natives.InvokeVoid(towDispatch.N_NO_TANK_DAMAGE, truck, true)
end

towDispatch.protectDriver = function(driver)
    ENTITY.SET_ENTITY_INVINCIBLE(driver, true)
    Natives.InvokeVoid(towDispatch.N_CAN_DAMAGE, driver, false)
    Natives.InvokeVoid(towDispatch.N_SET_PROOFS, driver,
        true, true, true, true, true, true, 1, true)
    PED.SET_PED_SUFFERS_CRITICAL_HITS(driver, false)
end

towDispatch.run = function(pid)
    local name = towDispatch.playerName(pid)
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
        towDispatch.toast(T("%s is no longer in the session."):format(name))
        return
    end
    if PLAYER.IS_REMOTE_PLAYER_IN_NON_CLONED_VEHICLE(pid) then
        towDispatch.toast(T("%s's vehicle is not streamed in yet. Spectate them, then try again."):format(name))
        return
    end

    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped)
    or not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        towDispatch.toast(T("%s isn't driving a vehicle right now."):format(name))
        return
    end

    local target = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if not target or target == 0 or not ENTITY.DOES_ENTITY_EXIST(target) then
        towDispatch.toast(T("Couldn't find %s's vehicle."):format(name))
        return
    end
    if not Natives.InvokeBool(towDispatch.N_IS_CAR, ENTITY.GET_ENTITY_MODEL(target)) then
        towDispatch.toast(T("%s's current vehicle can't be hooked to a tow truck."):format(name))
        return
    end
    if not towDispatch.loadModels() then
        towDispatch.toast(T("The tow truck or driver model did not finish loading."))
        return
    end
    if not towDispatch.takeControl(target) then
        towDispatch.toast(T("Couldn't take control of %s's vehicle."):format(name))
        return
    end

    towDispatch.active = { target = target }
    Natives.InvokeVoid(towDispatch.N_SET_MAX_SPEED, target, 0.1)
    Script.Yield(350)
    if towDispatch.stopping() or not ENTITY.DOES_ENTITY_EXIST(target) then
        towDispatch.abort()
        return
    end

    local spawn = ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(target, 0.0, 7.0, 0.0)
    local heading = ENTITY.GET_ENTITY_HEADING(target)
    local truck = GTA.SpawnVehicle(towDispatch.MODEL,
        spawn.x, spawn.y, spawn.z, heading, true, true)
    if not truck or truck == 0 or not ENTITY.DOES_ENTITY_EXIST(truck) then
        towDispatch.fail("The tow truck couldn't be spawned here.")
        return
    end
    towDispatch.active.truck = truck
    towDispatch.active.truckAddr = UnloadReap.addrOf(truck)
    towDispatch.active.truckPop  = UnloadReap.popOf(truck)
    Natives.InvokeBool(towDispatch.N_SET_ON_GROUND, truck, 5.0)
    towDispatch.protectTruck(truck)
    VEHICLE.SET_VEHICLE_ENGINE_ON(truck, true, true, false)

    local driver = towDispatch.createDriver(truck)
    if not driver or driver == 0 or not ENTITY.DOES_ENTITY_EXIST(driver) then
        towDispatch.fail("The tow truck arrived without a driver.")
        return
    end
    towDispatch.active.driver = driver
    towDispatch.active.driverAddr = UnloadReap.addrOf(driver)
    towDispatch.active.driverPop  = UnloadReap.popOf(driver)
    towDispatch.protectDriver(driver)
    PED.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS(driver, true)
    VEHICLE.SET_VEHICLE_DOORS_LOCKED(truck, 2)

    local hookDeadline = towDispatch.now() + towDispatch.HOOK_WAIT_MS
    local hooked = false
    repeat
        if not NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(target) then
            NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(target)
        end
        if not Natives.InvokeBool(towDispatch.N_IS_ATTACHED, truck, target) then
            Natives.InvokeVoid(towDispatch.N_ATTACH_TOW,
                truck, target, false, 0.0, 0.0, 0.0)
        end
        Script.Yield(100)
        hooked = Natives.InvokeBool(towDispatch.N_IS_ATTACHED, truck, target)
    until hooked or towDispatch.stopping() or towDispatch.now() >= hookDeadline

    Natives.InvokeVoid(towDispatch.N_SET_MAX_SPEED, target, 0.0)
    if not hooked then
        towDispatch.fail("The truck arrived, but " .. name .. "'s vehicle wouldn't stay on the hook.")
        return
    end

    TASK.TASK_VEHICLE_DRIVE_WANDER(driver, truck,
        towDispatch.DRIVE_SPEED, towDispatch.DRIVE_STYLE)
    hookDeadline = towDispatch.now() + towDispatch.HOOK_WAIT_MS
    local stableSince = nil
    hooked = false
    repeat
        if not NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(target) then
            NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(target)
        end
        if Natives.InvokeBool(towDispatch.N_IS_ATTACHED, truck, target) then
            stableSince = stableSince or towDispatch.now()
            hooked = towDispatch.now() - stableSince >= towDispatch.HOOK_STABLE_MS
        else
            stableSince = nil
            Natives.InvokeVoid(towDispatch.N_ATTACH_TOW,
                truck, target, false, 0.0, 0.0, 0.0)
        end
        Script.Yield(100)
    until hooked or towDispatch.stopping() or towDispatch.now() >= hookDeadline
    if not hooked then
        towDispatch.fail("The truck started moving, but " .. name .. "'s vehicle broke off the hook.")
        return
    end

    Natives.InvokeVoid(0x971D38760FBC02EF, driver, true)
    Memory.WriteInt(towDispatch.delBuf, driver)
    Natives.InvokeVoid(0x2595DD4236549CE3, towDispatch.delBuf)
    Memory.WriteInt(towDispatch.delBuf, truck)
    ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED(towDispatch.delBuf)
    UnloadReap.makeAmbient(towDispatch.active.driverAddr, towDispatch.active.driverPop)
    UnloadReap.makeAmbient(towDispatch.active.truckAddr,  towDispatch.active.truckPop)
    logf("[TowVehicle] released, truck poptype %s -> %s, driver %s -> %s",
        tostring(towDispatch.active.truckPop),
        tostring(Memory.ReadUShort(towDispatch.active.truckAddr + UnloadReap.OFF_DE_POPTYPE) & 0xF),
        tostring(towDispatch.active.driverPop),
        tostring(Memory.ReadUShort(towDispatch.active.driverAddr + UnloadReap.OFF_DE_POPTYPE) & 0xF))
    towDispatch.active = nil
    telemetryCountAction("TowVehicle")
    towDispatch.toast(T("Tow dispatched - %s's vehicle is being hauled away."):format(name))
end

Script.RegisterLooped(function()
    if towDispatch.stopping() then
        playerState.towPending = {}
        towDispatch.abort()
        Script.Yield(100)
        return
    end

    local request = table.remove(playerState.towPending, 1)
    if not request then
        Script.Yield(100)
        return
    end

    local ok, err = pcall(towDispatch.run, request.pid)
    towDispatch.releaseModels()
    if not ok then
        logErr("[TowVehicle] " .. tostring(err))
        towDispatch.fail("Tow dispatch hit an error; check the Cherax log.")
    end
    Script.Yield()
end)

for _, hash in ipairs(FeatureMgr.AddPlayerFeature(
    H.TOW_VEH, "Tow Vehicle", eFeatureType.Button,
    "Spawns a tow truck to drive away with the player's vehicle.",
    function(feature)
        playerState.towPending[#playerState.towPending + 1] =
            { pid = feature:GetPlayerIndex() }
    end)) do
    FeatureMgr.GetFeature(hash):SetSaveable(false)
end
end

pothole = {
    queue       = {},
    delayed     = {},
    wheels      = {},
    runnerHash  = VIBE_FH("PotholeRunner"),
    DETACH_MS   = 50,
    CONTROL_MS  = 3000,
    KICK_FORCE  = 10.0,
    H_TYRES_CAN_BURST = 0xEB9DC3C7D8596C46,
    H_TYRE_BURST      = 0xEC6A202EE4960385,
    H_IS_TYRE_BURST   = 0xBA291848A0815CA9,
    H_WORLD_TO_LOCAL  = 0x2274BC1C4885E333,
}

function pothole.toast(msg)
    GUI.AddToast(T("Pothole"), T(msg), 4000)
end

function pothole.tyreId(wheelIndex, wheelCount)
    if wheelCount == 2 then
        return ({ 0, 4 })[wheelIndex + 1]
    elseif wheelCount == 4 then
        return ({ 0, 1, 4, 5 })[wheelIndex + 1]
    elseif wheelCount == 8 then
        return ({ 0, 1, 2, 3, 45, 47, 4, 5 })[wheelIndex + 1]
    end
    return wheelIndex
end

function pothole.wheelBone(veh, wheelIndex, wheelCount)
    local names
    if wheelCount == 2 then
        names = wheelIndex == 0 and { "wheel_f", "wheel_lf" }
            or { "wheel_r", "wheel_lr" }
    elseif wheelCount == 4 then
        names = ({ "wheel_lf", "wheel_rf", "wheel_lr", "wheel_rr" })[wheelIndex + 1]
        names = { names }
    elseif wheelCount == 6 then
        names = { ({ "wheel_lf", "wheel_rf", "wheel_lm1", "wheel_rm1", "wheel_lr", "wheel_rr" })[wheelIndex + 1] }
    elseif wheelCount == 8 then
        names = { ({ "wheel_lf", "wheel_rf", "wheel_lm1", "wheel_rm1", "wheel_lm2", "wheel_rm2", "wheel_lr", "wheel_rr" })[wheelIndex + 1] }
    else
        names = { ("wheel_%d"):format(wheelIndex) }
    end
    for i = 1, #names do
        local bone = ENTITY.GET_ENTITY_BONE_INDEX_BY_NAME(veh, names[i])
        if bone and bone >= 0 then return bone end
    end
    return 0
end

function pothole.wheelOffset(veh, bone, wheelIndex, wheelCount)
    if bone and bone > 0 then
        local world = ENTITY.GET_WORLD_POSITION_OF_ENTITY_BONE(veh, bone)
        local off = V3.New(Natives.InvokeV3(pothole.H_WORLD_TO_LOCAL,
            veh, world.x + 0.0, world.y + 0.0, world.z + 0.0))
        return off.x, off.y, off.z
    end

    local x = 0.0
    if wheelCount > 2 then x = (wheelIndex % 2 == 0) and -1.0 or 1.0 end
    local axle = math.floor(wheelIndex / 2)
    local axles = math.max(2, math.ceil(wheelCount / 2))
    local y = 1.5 - (3.0 * axle / (axles - 1))
    return x, y, -0.3
end

function pothole.getWheelState(veh, vehAddr, wheelCount)
    local netId = NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(veh) or 0
    local model = ENTITY.GET_ENTITY_MODEL(veh)
    local state = pothole.wheels[vehAddr]
    if not state or state.veh ~= veh or state.netId ~= netId
    or state.model ~= model or state.count ~= wheelCount then
        state = { veh = veh, netId = netId, model = model, count = wheelCount, slots = {} }
        pothole.wheels[vehAddr] = state
    else
        for wheelIndex, status in pairs(state.slots) do
            if type(status) == "table" and status.burstTracked
            and not Natives.InvokeBool(pothole.H_IS_TYRE_BURST, veh, status.tyreId, false) then
                state.slots[wheelIndex] = nil
            end
        end
    end
    return state
end

function pothole.releaseWheel(job, discardVehicle)
    local state = job.wheelState
    if discardVehicle then
        if pothole.wheels[job.vehAddr] == state then pothole.wheels[job.vehAddr] = nil end
    elseif state and state.slots[job.wheelIndex] == "pending" then
        state.slots[job.wheelIndex] = nil
    end
end

function pothole.begin(job, now)
    local veh = vehicleDismantle.getVehicle(job.pid, true)
    if not veh then
        pothole.toast("The player must be driving a streamed-in vehicle.")
        return "done"
    end

    if not aircraftSabotage.takeControl(veh) then return "retry" end

    local vehAddr = aircraftSabotage.getVehAddr(veh)
    if not vehAddr then
        pothole.toast("Couldn't resolve the player's vehicle memory.")
        return "done"
    end
    local dmg = vehAddr + vehicleDismantle.DMG_OFFSET
    if Memory.ReadLong(dmg + vehicleDismantle.PARENT_REL) ~= vehAddr then
        pothole.toast("Vehicle layout check failed; Pothole is unavailable on this build.")
        logErr("[Pothole] m_pParent mismatch (CVehicleDamage offset invalid?)")
        return "done"
    end

    local wheelCount = Memory.ReadInt(vehAddr + vehicleDismantle.NUMWHEELS_OFF)
    if not wheelCount or wheelCount < 1 or wheelCount > 10 then
        pothole.toast("This vehicle has no detachable wheels.")
        return "done"
    end
    local wheelFn = vehicleDismantle.resolveFn(vehicleDismantle.wheelFn, "BreakOffWheel")
    if not wheelFn then
        pothole.toast("Wheel break-off unavailable (couldn't locate the game function).")
        return "done"
    end

    local wheelState = pothole.getWheelState(veh, vehAddr, wheelCount)
    local available = {}
    for wheelIndex = 0, wheelCount - 1 do
        if not wheelState.slots[wheelIndex] then
            available[#available + 1] = wheelIndex
        end
    end
    if #available == 0 then
        pothole.toast("This vehicle has no detachable wheels.")
        return "done"
    end
    local wheelIndex = available[math.random(#available)]
    wheelState.slots[wheelIndex] = "pending"
    local tyreId = pothole.tyreId(wheelIndex, wheelCount)
    Natives.InvokeVoid(pothole.H_TYRES_CAN_BURST, veh, true)
    Natives.InvokeVoid(vehicleDismantle.H_WHEELS_CAN_BREAK, veh, true)
    Natives.InvokeVoid(pothole.H_TYRE_BURST, veh, tyreId, true, 1000.0)
    local wheelBone = pothole.wheelBone(veh, wheelIndex, wheelCount)
    local offX, offY, offZ = pothole.wheelOffset(veh, wheelBone, wheelIndex, wheelCount)
    pothole.delayed[#pothole.delayed + 1] = {
        veh = veh, vehAddr = vehAddr, dmg = dmg, wheelIndex = wheelIndex,
        wheelState = wheelState,
        wheelFn = wheelFn, offX = offX, offY = offY, offZ = offZ,
        detachAt = now + pothole.DETACH_MS,
        controlDeadline = now + pothole.DETACH_MS + pothole.CONTROL_MS,
    }
    return "started"
end

function pothole.onTick(_)
    if scriptUnloading then
        pothole.queue, pothole.delayed, pothole.wheels = {}, {}, {}
        return
    end
    local now = Time.GetEpocheMs()

    for i = #pothole.delayed, 1, -1 do
        local job = pothole.delayed[i]
        if not ENTITY.DOES_ENTITY_EXIST(job.veh) then
            table.remove(pothole.delayed, i)
            pothole.releaseWheel(job, true)
            log("[Pothole] delayed vehicle entity no longer exists")
            pothole.toast("The vehicle disappeared before its wheel could break off.")
        else
            local hasControl = aircraftSabotage.takeControl(job.veh)
            if now >= job.detachAt then
                local liveAddr = aircraftSabotage.getVehAddr(job.veh)
                local layoutOK = liveAddr == job.vehAddr
                    and Memory.ReadLong(job.dmg + vehicleDismantle.PARENT_REL) == job.vehAddr
                if not layoutOK then
                    table.remove(pothole.delayed, i)
                    pothole.releaseWheel(job, true)
                    logf("[Pothole] delayed layout changed: handle=%d expected=0x%X live=%s parent=%s",
                        job.veh, job.vehAddr, liveAddr and ("0x%X"):format(liveAddr) or "nil",
                        liveAddr and ("0x%X"):format(Memory.ReadLong(job.dmg + vehicleDismantle.PARENT_REL) or 0) or "n/a")
                    pothole.toast("The vehicle disappeared before its wheel could break off.")
                elseif hasControl then
                    table.remove(pothole.delayed, i)
                    ENTITY.APPLY_FORCE_TO_ENTITY(job.veh, 1,
                        0.0, 0.0, pothole.KICK_FORCE,
                        job.offX, job.offY, job.offZ,
                        0, true, true, true, false, true)
                    Memory.LuaCallCFunction(job.wheelFn, job.dmg, job.wheelIndex,
                        0.0, 0.0, 0.0, false, false)
                    local tyreId = pothole.tyreId(job.wheelIndex, job.wheelState.count)
                    job.wheelState.slots[job.wheelIndex] = {
                        tyreId = tyreId,
                        burstTracked = Natives.InvokeBool(
                            pothole.H_IS_TYRE_BURST, job.veh, tyreId, false),
                    }
                    telemetryCountAction("Pothole")
                    pothole.toast("Pothole!")
                elseif now >= job.controlDeadline then
                    table.remove(pothole.delayed, i)
                    pothole.releaseWheel(job, false)
                    logf("[Pothole] handle=%d: no control for delayed detach after %dms",
                        job.veh, pothole.CONTROL_MS)
                    pothole.toast("Couldn't get control of the player's vehicle.")
                end
            end
        end
    end

    local pending = pothole.queue[1]
    if not pending then return end
    pending.started = pending.started or now
    local result = pothole.begin(pending, now)
    if result == "retry" and now - pending.started < pothole.CONTROL_MS then return end
    table.remove(pothole.queue, 1)
    if result == "retry" then
        pothole.toast("Couldn't get control of the player's vehicle.")
    end
end

for _, hash in ipairs(FeatureMgr.AddPlayerFeature(
    H.POTHOLE, "Pothole", eFeatureType.Button,
    "Breaks off a random wheel from the player's vehicle.",
    function(feature)
        pothole.queue[#pothole.queue + 1] = { pid = feature:GetPlayerIndex() }
    end)) do
    FeatureMgr.GetFeature(hash):SetSaveable(false)
end

