do
carCrashProd = {
    MODEL = Utils.Joaat("prop_windmill_01"),
    RUNNER_HASH = VIBE_FH("CarCrashProdRunner"),
    H_GROUND_Z = 0xC906A7DAB05C8D2B,
    H_LOAD_COLLISION = 0x0DC7CABAB1E9B67E,
    H_ACTIVATE_PHYSICS = 0x710311ADF0E20730,
    HOLD_MS = 1500,
    SECOND_DELAY_MS = 250,
    LOAD_MS = 3000,
    queue = {},
    second = {},
    active = {},
    groundBuf = Memory.Alloc(4),
    delBuf = Memory.Alloc(4),
    buffersFreed = false,
    modelRequested = false,
}

function carCrashProd.toast(msg)
    GUI.AddToast("VibeScript", T(msg), 3500)
end

function carCrashProd.getVehicle(pid, quiet)
    local function reject(msg)
        if quiet then log("[CarCrash] " .. msg) else carCrashProd.toast(msg) end
    end
    if not isPlayerReady() then
        reject("You aren't ready (cutscene / switch / not playing).")
        return nil
    end
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
        reject("Player not connected.")
        return nil
    end
    if PLAYER.IS_REMOTE_PLAYER_IN_NON_CLONED_VEHICLE(pid) then
        reject("Player's vehicle isn't streamed in. Spectate them first, then try again.")
        return nil
    end
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then
        reject("Player is too far away (not streamed in). Spectate them first, then try again.")
        return nil
    end
    if not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        reject("Player isn't in a vehicle.")
        return nil
    end
    local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if not veh or veh == 0 or not ENTITY.DOES_ENTITY_EXIST(veh) then
        reject("Couldn't find the player's vehicle.")
        return nil
    end
    return veh
end

function carCrashProd.delete(entry)
    local handle = entry and entry.handle or 0
    if handle == 0 or not ENTITY.DOES_ENTITY_EXIST(handle) then return true end
    local networked = NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(handle)
    if networked and not aircraftSabotage.takeControl(handle) then
        entry.deleteReason = "could not regain network control"
        return false
    end
    if networked then
        local netId = NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(handle)
        if netId and netId ~= 0 then
            NETWORK.SET_NETWORK_ID_EXISTS_ON_ALL_MACHINES(netId, false)
            NETWORK.SET_NETWORK_ID_CAN_MIGRATE(netId, false)
        end
    end
    ENTITY.FREEZE_ENTITY_POSITION(handle, false)
    ENTITY.SET_ENTITY_AS_MISSION_ENTITY(handle, true, true)
    Memory.WriteInt(carCrashProd.delBuf, handle)
    ENTITY.DELETE_ENTITY(carCrashProd.delBuf)
    local gone = not ENTITY.DOES_ENTITY_EXIST(handle)
    entry.deleteReason = gone and nil or
        (networked and "network DELETE_ENTITY left handle alive"
            or "local DELETE_ENTITY left handle alive")
    return gone
end

function carCrashProd.markAllForRemoval()
    return UnloadReap.markAll(carCrashProd.active, "CarCrash")
end

function carCrashProd.cleanup()
    carCrashProd.queue = {}
    carCrashProd.second = {}
    for i = #carCrashProd.active, 1, -1 do
        if carCrashProd.delete(carCrashProd.active[i]) then
            table.remove(carCrashProd.active, i)
        end
    end
    if carCrashProd.modelRequested then
        STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(carCrashProd.MODEL)
        carCrashProd.modelRequested = false
    end
    if #carCrashProd.active == 0 and not carCrashProd.buffersFreed then
        Memory.Free(carCrashProd.groundBuf)
        Memory.Free(carCrashProd.delBuf)
        carCrashProd.buffersFreed = true
    end
end

function carCrashProd.groundZ(x, y, referenceZ, fallbackZ)
    STREAMING.REQUEST_COLLISION_AT_COORD(x, y, referenceZ)
    local hit = Natives.InvokeBool(carCrashProd.H_GROUND_Z,
        x, y, referenceZ + 10.0, carCrashProd.groundBuf, false, false)
    if hit then
        local ground = Memory.ReadFloat(carCrashProd.groundBuf)
        if ground and ground <= referenceZ + 4.0 and ground >= referenceZ - 15.0 then
            return ground - 0.15, true
        end
    end
    return fallbackZ, false
end

function carCrashProd.spawn(pid, stage)
    local veh = carCrashProd.getVehicle(pid, true)
    if not veh then return false end
    local pos = ENTITY.GET_ENTITY_COORDS(veh, true)
    local vel = ENTITY.GET_ENTITY_VELOCITY(veh)
    if not pos or not vel then return false end

    local horizontal = math.sqrt(vel.x * vel.x + vel.y * vel.y)
    local dx, dy
    if horizontal > 0.5 then
        dx, dy = vel.x / horizontal, vel.y / horizontal
    else
        local fwd = ENTITY.GET_ENTITY_FORWARD_VECTOR(veh)
        dx, dy = fwd.x, fwd.y
    end
    local lead = math.max(2.5, math.min(18.0, horizontal * 0.45))
    local x = pos.x + dx * lead - dy * 0.45
    local y = pos.y + dy * lead + dx * 0.45
    local aboveGround = ENTITY.GET_ENTITY_HEIGHT_ABOVE_GROUND(veh) or 0.0
    local groundOffset = math.max(0.0, math.min(1.5, aboveGround))
    local fallbackZ = pos.z - groundOffset - 0.15
    local z, groundHit = carCrashProd.groundZ(x, y, pos.z, fallbackZ)

    local object = GTA.CreateWorldObject(carCrashProd.MODEL, x, y, z, true, true)
    if not object or object == 0 then
        carCrashProd.toast("Couldn't create the collision object (object/network pool may be full).")
        return false
    end
    ENTITY.SET_ENTITY_AS_MISSION_ENTITY(object, true, true)
    local visible = DEV.collisionPropsVisible == true
    ENTITY.SET_ENTITY_VISIBLE(object, visible, false)
    ENTITY.SET_ENTITY_ALPHA(object, visible and 255 or 0, false)
    ENTITY.SET_ENTITY_INVINCIBLE(object, true)
    ENTITY.SET_ENTITY_COLLISION(object, true, true)
    Natives.InvokeVoid(carCrashProd.H_LOAD_COLLISION, object, true, true)
    Natives.InvokeVoid(carCrashProd.H_ACTIVATE_PHYSICS, object)
    ENTITY.FREEZE_ENTITY_POSITION(object, true)
    local netId = NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(object)
    if netId and netId ~= 0 then
        NETWORK.SET_NETWORK_ID_EXISTS_ON_ALL_MACHINES(netId, true)
        NETWORK.SET_NETWORK_ID_CAN_MIGRATE(netId, false)
    end
    carCrashProd.active[#carCrashProd.active + 1] = {
        handle = object,
        addr   = UnloadReap.addrOf(object),
        stage = stage or 0,
        deleteAt = Time.GetEpocheMs() + carCrashProd.HOLD_MS,
    }
    if VIBESCRIPT_VERBOSE == true then
        logf("[CarCrash] spawned blocker %d handle=%d pid=%d; delete in %dms; "
            .. "vehicleZ=%.2f aboveGround=%.2f spawnZ=%.2f groundHit=%s",
            stage or 0, object, pid, carCrashProd.HOLD_MS, pos.z, aboveGround, z,
            tostring(groundHit))
    end
    return true
end

function carCrashProd.onTick(feature)
    if not feature:IsToggled() then return end
    local now = Time.GetEpocheMs()
    for i = #carCrashProd.active, 1, -1 do
        local blocker = carCrashProd.active[i]
        if now >= blocker.deleteAt then
            if carCrashProd.delete(blocker) then
                if VIBESCRIPT_VERBOSE == true then
                    logf("[CarCrash] deleted blocker %d handle=%d", blocker.stage, blocker.handle)
                end
                table.remove(carCrashProd.active, i)
            elseif not blocker.deleteWarned then
                blocker.deleteWarned = true
                if VIBESCRIPT_VERBOSE == true then
                    logf("[CarCrash] blocker %d handle=%d survived first delete (%s); retrying",
                        blocker.stage, blocker.handle, blocker.deleteReason or "unknown reason")
                end
            end
        end
    end
    for i = #carCrashProd.second, 1, -1 do
        local delayed = carCrashProd.second[i]
        if now >= delayed.spawnAt then
            carCrashProd.spawn(delayed.pid, 2)
            table.remove(carCrashProd.second, i)
        end
    end
    if #carCrashProd.queue > 0 then
        STREAMING.REQUEST_MODEL(carCrashProd.MODEL)
        carCrashProd.modelRequested = true
        if STREAMING.HAS_MODEL_LOADED(carCrashProd.MODEL) then
            local queued = carCrashProd.queue
            carCrashProd.queue = {}
            for i = 1, #queued do
                local job = queued[i]
                if carCrashProd.getVehicle(job.pid, false)
                and carCrashProd.spawn(job.pid, 1) then
                    carCrashProd.second[#carCrashProd.second + 1] = {
                        pid = job.pid,
                        spawnAt = now + carCrashProd.SECOND_DELAY_MS,
                    }
                    telemetryCountAction("CarCrash")
                end
            end
        elseif now - carCrashProd.queue[1].queuedAt >= carCrashProd.LOAD_MS then
            carCrashProd.queue = {}
            carCrashProd.toast("Collision model did not load in time.")
        end
    end
    if #carCrashProd.queue == 0 and #carCrashProd.second == 0
    and #carCrashProd.active == 0 and carCrashProd.modelRequested then
        STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(carCrashProd.MODEL)
        carCrashProd.modelRequested = false
    end
end

for _, hash in ipairs(FeatureMgr.AddPlayerFeature(
    H.CAR_CRASH, "Car Crash", eFeatureType.Button,
    "Crashes the player's vehicle into two short-lived props, invisible by default. The player must be streamed in.",
    function(feature)
        local pid = feature:GetPlayerIndex()
        if carCrashProd.getVehicle(pid, false) then
            carCrashProd.queue[#carCrashProd.queue + 1] = {
                pid = pid,
                queuedAt = Time.GetEpocheMs(),
            }
        end
    end)) do
    FeatureMgr.GetFeature(hash):SetSaveable(false)
end

centralOnTick(FeatureMgr.AddFeature(carCrashProd.RUNNER_HASH, "##CarCrashProdRunner",
    eFeatureType.Toggle, "", carCrashProd.onTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
    :SetSearchable(false)
    :SetVisible(false)
FeatureMgr.GetFeature(carCrashProd.RUNNER_HASH):Toggle()

Script.RegisterLooped(function()
    if ShouldUnload() or scriptUnloading then
        carCrashProd.cleanup()
    end
    Script.Yield()
end)
end


do
rampVehicleProd = {
    MODEL = Utils.Joaat("stt_prop_ramp_jump_s"),
    RUNNER_HASH = VIBE_FH("RampVehicleProdRunner"),
    H_GROUND_Z = 0xC906A7DAB05C8D2B,
    H_LOAD_COLLISION = 0x0DC7CABAB1E9B67E,
    H_ACTIVATE_PHYSICS = 0x710311ADF0E20730,
    H_MODEL_DIMS = 0x03E8D3D5F549087A,
    HOLD_MS = 1500,
    LOAD_MS = 3000,
    COUNT = 3,
    queue = {},
    active = {},
    groundBuf = Memory.Alloc(4),
    delBuf = Memory.Alloc(4),
    dimsBuf = Memory.Alloc(48),
    buffersFreed = false,
    modelRequested = false,
    spacing = nil,
}

function rampVehicleProd.toast(msg)
    GUI.AddToast("VibeScript", T(msg), 3500)
end

function rampVehicleProd.delete(entry)
    local handle = entry and entry.handle or 0
    if handle == 0 or not ENTITY.DOES_ENTITY_EXIST(handle) then return true end
    local networked = NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(handle)
    if networked and not aircraftSabotage.takeControl(handle) then
        entry.deleteReason = "could not regain network control"
        return false
    end
    if networked then
        local netId = NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(handle)
        if netId and netId ~= 0 then
            NETWORK.SET_NETWORK_ID_EXISTS_ON_ALL_MACHINES(netId, false)
            NETWORK.SET_NETWORK_ID_CAN_MIGRATE(netId, false)
        end
    end
    ENTITY.FREEZE_ENTITY_POSITION(handle, false)
    ENTITY.SET_ENTITY_AS_MISSION_ENTITY(handle, true, true)
    Memory.WriteInt(rampVehicleProd.delBuf, handle)
    ENTITY.DELETE_ENTITY(rampVehicleProd.delBuf)
    local gone = not ENTITY.DOES_ENTITY_EXIST(handle)
    entry.deleteReason = gone and nil or
        (networked and "network DELETE_ENTITY left handle alive"
            or "local DELETE_ENTITY left handle alive")
    return gone
end

function rampVehicleProd.markAllForRemoval()
    return UnloadReap.markAll(rampVehicleProd.active, "RampVehicle")
end

function rampVehicleProd.cleanup()
    rampVehicleProd.queue = {}
    for i = #rampVehicleProd.active, 1, -1 do
        if rampVehicleProd.delete(rampVehicleProd.active[i]) then
            table.remove(rampVehicleProd.active, i)
        end
    end
    if rampVehicleProd.modelRequested then
        STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(rampVehicleProd.MODEL)
        rampVehicleProd.modelRequested = false
    end
    if #rampVehicleProd.active == 0 and not rampVehicleProd.buffersFreed then
        Memory.Free(rampVehicleProd.groundBuf)
        Memory.Free(rampVehicleProd.delBuf)
        Memory.Free(rampVehicleProd.dimsBuf)
        rampVehicleProd.buffersFreed = true
    end
end

function rampVehicleProd.groundZ(x, y, referenceZ, fallbackZ)
    STREAMING.REQUEST_COLLISION_AT_COORD(x, y, referenceZ)
    local hit = Natives.InvokeBool(rampVehicleProd.H_GROUND_Z,
        x, y, referenceZ + 10.0, rampVehicleProd.groundBuf, false, false)
    if hit then
        local ground = Memory.ReadFloat(rampVehicleProd.groundBuf)
        if ground and ground <= referenceZ + 4.0 and ground >= referenceZ - 15.0 then
            return ground - 0.15, true
        end
    end
    return fallbackZ, false
end

function rampVehicleProd.lateralPitch()
    if rampVehicleProd.spacing then return rampVehicleProd.spacing end
    Natives.InvokeVoid(rampVehicleProd.H_MODEL_DIMS, rampVehicleProd.MODEL,
        rampVehicleProd.dimsBuf, rampVehicleProd.dimsBuf + 24)
    local minY = Memory.ReadFloat(rampVehicleProd.dimsBuf + 8) or 0.0
    local maxY = Memory.ReadFloat(rampVehicleProd.dimsBuf + 32) or 0.0
    local width = maxY - minY
    if not (width > 0.5) or width > 20.0 then width = 4.0 end
    rampVehicleProd.spacing = width
    return width
end

function rampVehicleProd.spawn(pid)
    local veh = carCrashProd.getVehicle(pid, true)
    if not veh then return false end

    local pos = ENTITY.GET_ENTITY_COORDS(veh, true)
    local vel = ENTITY.GET_ENTITY_VELOCITY(veh)
    if not pos or not vel then return false end

    local horizontal = math.sqrt(vel.x * vel.x + vel.y * vel.y)
    local dx, dy
    if horizontal > 0.5 then
        dx, dy = vel.x / horizontal, vel.y / horizontal
    else
        local fwd = ENTITY.GET_ENTITY_FORWARD_VECTOR(veh)
        dx, dy = fwd.x, fwd.y
    end

    local lead = math.max(2.5, math.min(18.0, horizontal * 0.45))
    local cx = pos.x + dx * lead
    local cy = pos.y + dy * lead
    local aboveGround = ENTITY.GET_ENTITY_HEIGHT_ABOVE_GROUND(veh) or 0.0
    local groundOffset = math.max(0.0, math.min(1.5, aboveGround))
    local fallbackZ = pos.z - groundOffset - 0.15
    local heading = (math.deg(math.atan(-dx, dy)) + 90.0) % 360.0

    local sx, sy = -dy, dx
    local pitch = rampVehicleProd.lateralPitch()
    local count = rampVehicleProd.COUNT
    local first = -(count - 1) * 0.5

    local spawned = 0
    for i = 0, count - 1 do
        local offset = (first + i) * pitch
        local x = cx + sx * offset
        local y = cy + sy * offset
        local z, groundHit = rampVehicleProd.groundZ(x, y, pos.z, fallbackZ)

        local object = GTA.CreateWorldObject(rampVehicleProd.MODEL, x, y, z, true, true)
        if object and object ~= 0 then
            ENTITY.SET_ENTITY_AS_MISSION_ENTITY(object, true, true)
            ENTITY.SET_ENTITY_HEADING(object, heading)
            ENTITY.SET_ENTITY_VISIBLE(object, DEV.collisionPropsVisible == true, false)
            ENTITY.SET_ENTITY_INVINCIBLE(object, true)
            ENTITY.SET_ENTITY_COLLISION(object, true, true)
            Natives.InvokeVoid(rampVehicleProd.H_LOAD_COLLISION, object, true, true)
            Natives.InvokeVoid(rampVehicleProd.H_ACTIVATE_PHYSICS, object)
            ENTITY.FREEZE_ENTITY_POSITION(object, true)

            local netId = NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(object)
            if netId and netId ~= 0 then
                NETWORK.SET_NETWORK_ID_EXISTS_ON_ALL_MACHINES(netId, true)
                NETWORK.SET_NETWORK_ID_CAN_MIGRATE(netId, false)
            end

            rampVehicleProd.active[#rampVehicleProd.active + 1] = {
                handle = object,
                addr   = UnloadReap.addrOf(object),
                slot = i + 1,
                deleteAt = Time.GetEpocheMs() + rampVehicleProd.HOLD_MS,
            }
            spawned = spawned + 1
            logf("[RampVehicle] spawned ramp %d/%d handle=%d pid=%d offset=%.2f "
                .. "heading=%.1f pitch=%.2f; delete in %dms; "
                .. "vehicleZ=%.2f spawnZ=%.2f groundHit=%s",
                i + 1, count, object, pid, offset, heading, pitch,
                rampVehicleProd.HOLD_MS, pos.z, z, tostring(groundHit))
        else
            VIBE_LOG_ERROR(string.format("[RampVehicle] create failed pid=%d ramp %d/%d offset=%.2f",
                pid, i + 1, count, offset))
        end
    end

    if spawned == 0 then
        rampVehicleProd.toast("Couldn't create the ramps (object/network pool may be full).")
        return false
    end
    return true
end

function rampVehicleProd.onTick(feature)
    if not feature:IsToggled() then return end
    local now = Time.GetEpocheMs()
    for i = #rampVehicleProd.active, 1, -1 do
        local ramp = rampVehicleProd.active[i]
        if now >= ramp.deleteAt then
            if rampVehicleProd.delete(ramp) then
                logf("[RampVehicle] deleted ramp %d handle=%d", ramp.slot, ramp.handle)
                table.remove(rampVehicleProd.active, i)
            elseif not ramp.deleteWarned then
                ramp.deleteWarned = true
                logf("[RampVehicle] ramp %d handle=%d survived first delete (%s); retrying",
                    ramp.slot, ramp.handle, ramp.deleteReason or "unknown reason")
            end
        end
    end
    if #rampVehicleProd.queue > 0 then
        STREAMING.REQUEST_MODEL(rampVehicleProd.MODEL)
        rampVehicleProd.modelRequested = true
        if STREAMING.HAS_MODEL_LOADED(rampVehicleProd.MODEL) then
            local queued = rampVehicleProd.queue
            rampVehicleProd.queue = {}
            for i = 1, #queued do
                local job = queued[i]
                if carCrashProd.getVehicle(job.pid, false)
                and rampVehicleProd.spawn(job.pid) then
                    telemetryCountAction("RampVehicle")
                end
            end
        elseif now - rampVehicleProd.queue[1].queuedAt >= rampVehicleProd.LOAD_MS then
            rampVehicleProd.queue = {}
            rampVehicleProd.toast("Ramp model did not load in time.")
        end
    end
    if #rampVehicleProd.queue == 0 and #rampVehicleProd.active == 0
    and rampVehicleProd.modelRequested then
        STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(rampVehicleProd.MODEL)
        rampVehicleProd.modelRequested = false
    end
end

for _, hash in ipairs(FeatureMgr.AddPlayerFeature(
    H.RAMP_VEHICLE, "Ramp Vehicle", eFeatureType.Button,
    "Lays three short-lived stunt ramps, invisible by default, side by side across the path of the player's current vehicle, launching it into the air. The player must be in a streamed-in vehicle. Wont work well at low speeds.",
    function(feature)
