patchFn.proxMine = {
    LEGACY_SITES = {
        { AOB = "4D 85 C9 0F 84 ?? ?? ?? ?? 41 3B D0 73 0E 48 0F BE C1 4C 8B 8C C3 A8 0C 00 00 EB 03 4C 8B CE 41 F6 81 90 10 00 00 02 0F 84 ?? ?? ?? ?? 41 3B D0 73 0E 48 0F BE C1 4C 8B 8C C3 A8 0C 00 00 EB 03 4C 8B CE 41 8A 81 90 10 00 00 A8 01 ?? ?? ?? ?? ?? ?? A8 02 0F 84", PATCH_OFF = 3,
          ORIG = {0x0F, 0x84, 0xA8, 0x00, 0x00, 0x00}, NEW = {0x0F, 0x84, 0xB7, 0x04, 0x00, 0x00} },
        { AOB = "4C 8B 8C C3 A8 0C 00 00 EB 03 4C 8B CE 41 8A 81 90 10 00 00 A8 01 ?? ?? ?? ?? ?? ?? A8 02 0F 84", PATCH_OFF = 22,
          ORIG = {0x0F, 0x85, 0x6E, 0x04, 0x00, 0x00}, NEW = {0x90, 0xE9, 0x6E, 0x04, 0x00, 0x00} },
        { AOB = "8A 83 90 10 00 00 A8 02 74 ?? A8 01 ?? ?? ?? ?? ?? ?? 48 8B 87 D8 04 00 00", PATCH_OFF = 12,
          ORIG = {0x0F, 0x85, 0x28, 0x02, 0x00, 0x00}, NEW = {0x90, 0xE9, 0x28, 0x02, 0x00, 0x00} },
    },
    ENHANCED_SITES = {
        { AOB = "?? ?? ?? ?? ?? ?? ?? ?? 38 87 A0 0C 00 00 0F 86 ?? ?? ?? ?? 48 8B 84 C7 A8 0C 00 00 48 85 C0 0F 84 ?? ?? ?? ?? 0F B6 88 90 10 00 00 F6 C1 02 0F 84", PATCH_OFF = 14,
          ORIG = {0x0F, 0x86, 0x9D, 0xFE, 0xFF, 0xFF}, NEW = {0x0F, 0x86, 0x96, 0xFF, 0xFF, 0xFF} },
        { AOB = "?? ?? ?? ?? ?? ?? ?? ?? 38 87 A0 0C 00 00 0F 86 ?? ?? ?? ?? 48 8B 84 C7 A8 0C 00 00 48 85 C0 0F 84 ?? ?? ?? ?? 0F B6 88 90 10 00 00 F6 C1 02 0F 84", PATCH_OFF = 31,
          ORIG = {0x0F, 0x84, 0x8C, 0xFE, 0xFF, 0xFF}, NEW = {0x0F, 0x84, 0x85, 0xFF, 0xFF, 0xFF} },
        { AOB = "?? ?? ?? ?? ?? ?? ?? ?? 38 87 A0 0C 00 00 0F 86 ?? ?? ?? ?? 48 8B 84 C7 A8 0C 00 00 48 85 C0 0F 84 ?? ?? ?? ?? 0F B6 88 90 10 00 00 F6 C1 02 0F 84", PATCH_OFF = 59,
          ORIG = {0x0F, 0x85, 0x69, 0xFF, 0xFF, 0xFF}, NEW = {0x90, 0xE9, 0x69, 0xFF, 0xFF, 0xFF} },
        { AOB = "24 03 3C 02 ?? ?? ?? ?? ?? ?? 49 8B 84 24 D8 04 00 00 80 B8 10 01 00 00 00", PATCH_OFF = 4,
          ORIG = {0x0F, 0x85, 0x2D, 0xFD, 0xFF, 0xFF}, NEW = {0x90, 0xE9, 0x2D, 0xFD, 0xFF, 0xFF} },
    },
    sites = nil, applied = false, ready = false, retryIn = 0, reported = {},
}
patchFn.proxMine.buildVehicleGate = function(cave, entry, skip, stolen)
    local bytes, labels, fixups = {}, {}, {}
    local function emit(hex)
        for byte in hex:gmatch('%x%x') do bytes[#bytes + 1] = tonumber(byte, 16) end
    end
    local function jump(op, target)
        emit(op)
        fixups[#fixups + 1] = {offset = #bytes, target = target}
        emit('00 00 00 00')
    end
    emit('9C 50 51 52')
    emit(IS_ENHANCED and '48 8B 87 D0 00 00 00' or '48 8B 83 D0 00 00 00')
    emit('48 85 C0'); jump('0F 84', 'seats')
    emit('80 78 4B 00'); jump('0F 85', 'normal')
    emit('80 78 4A FF'); jump('0F 85', 'normal')
    labels.seats = #bytes
    emit(IS_ENHANCED and '0F BE 8F A0 0C 00 00' or '0F BE 8B A0 0C 00 00')
    emit('85 C9'); jump('0F 88', 'normal')
    jump('0F 84', 'skip')
    emit('31 D2')
    labels.seat = #bytes
    emit(IS_ENHANCED and '48 8B 84 D7 A8 0C 00 00' or '48 8B 84 D3 A8 0C 00 00')
    emit('48 85 C0'); jump('0F 84', 'nextSeat')
    emit('F6 80 90 10 00 00 02'); jump('0F 84', 'normal')
    labels.nextSeat = #bytes
    emit('FF C2 39 CA'); jump('0F 82', 'seat')
    labels.skip = #bytes
    emit('5A 59 58 9D'); jump('E9', skip)
    labels.normal = #bytes
    emit('5A 59 58 9D')
    for _, byte in ipairs(stolen) do bytes[#bytes + 1] = byte end
    jump('E9', entry + #stolen)
    for _, fix in ipairs(fixups) do
        local target = type(fix.target) == 'string' and cave + labels[fix.target] or fix.target
        local relative = target - (cave + fix.offset + 4)
        if relative < -0x80000000 or relative > 0x7FFFFFFF then return nil end
        for j = 0, 3 do bytes[fix.offset + j + 1] = (relative >> (j * 8)) & 255 end
    end
    return bytes
end
patchFn.proxMine.resolveVehicleGate = function()
    local p = patchFn.proxMine
    local playerGate = p.sites[#p.sites - 1].address
    local displacement = Memory.ReadUInt(playerGate + 2)
    if displacement >= 0x80000000 then displacement = displacement - 0x100000000 end
    local skip = playerGate + 6 + displacement
    local entry = playerGate - (IS_ENHANCED and 59 or 115)
    local stolen = IS_ENHANCED and {0x48, 0x0F, 0xBE, 0x87, 0xA1, 0x0C, 0, 0}
        or {0x0F, 0xBE, 0x8B, 0xA1, 0x0C, 0, 0}
    local original = {table.unpack(stolen)}
    if not IS_ENHANCED then original[8] = 0x44 end
    if entry % 64 > 56 then return false end
    local inherited
    if not p.matches(entry, original) then
        if Memory.ReadUByte(entry) ~= 0xE9 then return false end
        for i = 5, #stolen - 1 do if Memory.ReadUByte(entry + i) ~= 0x90 then return false end end
        if not IS_ENHANCED and Memory.ReadUByte(entry + 7) ~= 0x44 then return false end
        local rel = Memory.ReadUInt(entry + 1)
        if rel >= 0x80000000 then rel = rel - 0x100000000 end
        inherited = entry + 5 + rel
    end
    local size = #p.buildVehicleGate(entry, entry, skip, stolen)
    local cave = lockOntoPlayers.pedThreatGatePatch.findPlayerCave(size,
        IS_ENHANCED and 'GTA5_Enhanced.exe' or 'GTA5.exe', inherited)
    if not cave then return false end
    local shell = p.buildVehicleGate(cave, entry, skip, stolen)
    local relative = cave - (entry + 5)
    if not shell or relative < -0x80000000 or relative > 0x7FFFFFFF then return false end
    if inherited and not p.matches(cave, shell) then return false end
    local patch = {0xE9}
    for i = 0, 3 do patch[#patch + 1] = (relative >> (i * 8)) & 255 end
    for i = 6, #original do patch[i] = 0x90 end
    if not IS_ENHANCED then patch[8] = 0x44 end
    p.vehicle = {address = entry, original = original, patch = patch, cave = cave, shell = shell}
    return true
end
patchFn.proxMine.releaseCave = function()
    local p = patchFn.proxMine
    local v = p.vehicle
    if v and p.matches(v.address, v.original) and p.matches(v.cave, v.shell) then
        for i = 0, #v.shell - 1 do Memory.WriteByte(v.cave + i, 0) end
        p.vehicle, p.sites, p.ready = nil, nil, false
    end
end
patchFn.proxMine.matches = function(address, bytes)
    for i = 1, #bytes do
        if Memory.ReadUByte(address + i - 1) ~= bytes[i] then return false end
    end
    return true
end
patchFn.proxMine.fail = function(reason)
    local p = patchFn.proxMine
    if not p.reported[reason] then
        p.reported[reason] = true
        VIBE_LOG_ERROR("[VibeScript] Proximity Mine Immunity: " .. reason)
    end
end
patchFn.proxMine.word = function(address, original, replacement)
    local first, last
    for i = 1, #original do
        if original[i] ~= replacement[i] then first = first or i; last = i end
    end
    if not first then return nil end
    local start, finish = address + first - 1, address + last - 1
    local size = 4
    local aligned = start - start % size
    if finish >= aligned + size then
        size = 8
        aligned = start - start % size
    end
    if finish >= aligned + size then return nil end
    local orig, patched = {}, {}
    for i = 1, size do
        local a = aligned + i - 1
        local byte = Memory.ReadUByte(a)
        local index = a - address + 1
        orig[i] = index >= first and index <= last and original[index] or byte
        patched[i] = index >= first and index <= last and replacement[index] or byte
    end
    return {address = aligned, size = size, original = orig, patch = patched}
end
patchFn.proxMine.writeWord = function(w, patched)
    local p = patchFn.proxMine
    local want = patched and w.patch or w.original
    if p.matches(w.address, want) then return true end
    if not p.matches(w.address, patched and w.original or w.patch) then return false end
    local value = string.unpack(w.size == 4 and '<i4' or '<i8', string.char(table.unpack(want)))
    if w.size == 4 then Memory.WriteInt(w.address, value)
    else Memory.WriteLong(w.address, value) end
    return true
end
patchFn.proxMine.resolve = function()
    local p = patchFn.proxMine
    if p.ready then return true end
    if p.retryIn > 0 then p.retryIn = p.retryIn - 1; return false end
    p.retryIn = 120
    p.sites = {}
    local defs = IS_ENHANCED and p.ENHANCED_SITES or p.LEGACY_SITES
    for i = 1, #defs do
        local hit = Memory.Scan(defs[i].AOB)
        if hit and hit ~= 0 then
            local s = hit + defs[i].PATCH_OFF
            if p.matches(s, defs[i].ORIG) or p.matches(s, defs[i].NEW) then
                local word = p.word(s, defs[i].ORIG, defs[i].NEW)
                if word then p.sites[#p.sites + 1] = {address = s, def = defs[i], word = word} end
            end
        end
    end
    if #p.sites ~= #defs or not p.resolveVehicleGate() then
        p.fail("verified trigger checks or safe instruction alignment unavailable (retrying)")
        return false
    end
    p.ready, p.reported = true, {}
    return true
end
patchFn.proxMine.write = function(patched)
    local p = patchFn.proxMine
    local v = p.vehicle
    if patched and (not p.ready or not v) then return false end
    if patched then
        for _, site in ipairs(p.sites) do
            if (not p.matches(site.address, site.def.ORIG) and not p.matches(site.address, site.def.NEW))
                or (not p.matches(site.word.address, site.word.original) and not p.matches(site.word.address, site.word.patch)) then
                p.fail("game code changed; refusing to enable")
                return false
            end
        end
        local blank = {}
        for i = 1, #v.shell do blank[i] = 0 end
        if (not p.matches(v.address, v.original) and not p.matches(v.address, v.patch))
            or (not p.matches(v.cave, blank) and not p.matches(v.cave, v.shell)) then
            p.fail("game code changed; refusing to enable")
            return false
        end
        if not p.matches(v.cave, v.shell) then
            for i, byte in ipairs(v.shell) do Memory.WriteByte(v.cave + i - 1, byte) end
        end
    end
    local restored = true
    if not patched and v then
        if p.matches(v.address, v.patch) then
            Memory.WriteLong(v.address, (string.unpack('<i8', string.char(table.unpack(v.original)))))
        elseif not p.matches(v.address, v.original) then restored = false end
    end
    for i = 1, #p.sites do
        local site = p.sites[i]
        local d, address = site.def, site.address
        if (p.matches(address, d.ORIG) or p.matches(address, d.NEW)) then
            if not p.writeWord(site.word, patched and i == #p.sites) then restored = false end
        else
            restored = false
        end
    end
    if patched and not p.matches(v.address, v.patch) then
        Memory.WriteLong(v.address, (string.unpack('<i8', string.char(table.unpack(v.patch)))))
    end
    if not restored then
        p.fail("game code changed; unfamiliar bytes were left untouched")
    end
    return restored
end
patchFn.proxMine.onTick = function(f)
    local p = patchFn.proxMine
    local on = f:IsToggled()
    if on ~= p.requested then
        p.requested, p.warned, p.retryIn = on, false, 0
    end
    local ready = p.resolve()
    if on then
        if ready and p.write(true) then
            p.applied, p.warned = true, false
        else
            p.restore()
            if not p.warned then
                p.warned = true
                GUI.AddToast("VibeScript", T("Proximity Mine Immunity is not active yet; retrying. Your toggle stays on."), 5000)
            end
        end
    else
        p.restore()
    end
end
patchFn.proxMine.restore = function()
    local p = patchFn.proxMine
    if p.sites and #p.sites > 0 then p.write(false) end
    p.applied = false
end

