    patchFn.proxMine.restore()
    patchFn.proxMine.releaseCave()
end)

do
    local idx = IS_ENHANCED and {
        gangByColour = 2649983,
        gangByBoss   = 2649994,
        gang         = 2650027,
        colourCache  = 2689338,
    } or {
        gangByColour = 2649980,
        gangByBoss   = 2649991,
        gang         = 2650024,
        colourCache  = 2689333,
    }
    local SLOTS      = 10
    local STEP_MS    = 500
    local IS_SESSION_ACTIVE = 0xD83C2B94E7508980
    local IS_IN_TRANSITION  = 0x68049AEFF83D8F0A
    local active     = false
    local nextStepAt = 0
    local slot       = 0
    local restore    = nil
    local statusText = nil

    local function colourIdx(gang) return idx.gang + gang * 2 + 1 end

    local FREEMODE = Utils.sJoaat("freemode")
    local function sessionReady()
        return Natives.InvokeBool(IS_SESSION_ACTIVE)
            and not Natives.InvokeBool(IS_IN_TRANSITION)
            and (SCRIPT.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH(FREEMODE) or 0) > 0
    end

    local function orgState()
        local boss = getOrgBoss(GTA.GetLocalPlayerId())
        if boss < 0 or boss > 31 then return -1, -1 end
        local gang = ScriptGlobal.GetInt(idx.gangByBoss + boss) or -1
        if gang < 0 or gang >= SLOTS then return boss, -1 end
        return boss, gang
    end

    local HOST_OF_SCRIPT = 0x1D6A14F1F9A736FC

    local function setColour(gang, colour)
        ScriptGlobal.SetInt(colourIdx(gang), colour)
        ScriptGlobal.SetInt(idx.colourCache, colour)
    end

    local function ownsWrite(r)
        if not r then return false end
        return GTA.GetLocalPlayerId() == r.localPid
            and ScriptGlobal.GetInt(idx.gangByBoss + r.boss) == r.gang
            and ScriptGlobal.GetInt(idx.gangByColour + r.colour) == r.gang
            and ScriptGlobal.GetInt(colourIdx(r.gang)) == r.written
    end

    local function release()
        if not restore then return end
        local r = restore
        if ownsWrite(r) then
            ScriptGlobal.SetInt(colourIdx(r.gang), r.colour)
            if getOrgBoss(r.localPid) == r.boss then
                ScriptGlobal.SetInt(idx.colourCache, r.colour)
            end
        end
        restore = nil
    end

    local function stop()
        release()
        statusText = nil
        active = false
    end

    rainbowBlipOnTick = function(f)
        if not f:IsToggled() then
            if active then stop() end
            return
        end

        active = true

        if not sessionReady() then
            statusText = "Waiting for session"
            return
        end

        local boss, gang = orgState()
        if boss == -1 then
            release()
            statusText = "Not in an organization"
            return
        end
        if gang == -1 then
            release()
            statusText = nil
            return
        end


        if restore and (restore.boss ~= boss or restore.gang ~= gang
            or restore.localPid ~= GTA.GetLocalPlayerId()) then
            release()
        end

        if restore == nil then
            local home = -1
            for c = 0, SLOTS - 1 do
                if ScriptGlobal.GetInt(idx.gangByColour + c) == gang then home = c; break end
            end
            if home < 0 then
                statusText = nil
                return
            end
            local cur = ScriptGlobal.GetInt(colourIdx(gang)) or -1
            restore = {
                gang = gang, colour = home, written = cur, boss = boss,
                localPid = GTA.GetLocalPlayerId(),
            }
            slot = (cur >= 0 and cur < SLOTS) and cur or home
            nextStepAt = 0
        end

        local now = Time.GetEpocheMs()
        if now < nextStepAt then return end
        nextStepAt = now + STEP_MS

        slot = (slot + 1) % SLOTS
        setColour(gang, slot)
        restore.written = slot

        local host = Natives.InvokeInt(HOST_OF_SCRIPT, "freemode", -1, 0)
        if host ~= GTA.GetLocalPlayerId() then
            statusText = "Local only"
        else
            statusText = "Session-wide"
        end
    end

    rainbowBlipStatus = function() return statusText end

    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, stop)
end

centralOnTick(FeatureMgr.AddFeature(H.RAINBOW_BLIP, "Rainbow Blip", eFeatureType.Toggle,
    "Cycles through all of the colors applied to an organization. Must be script host for others to see this, otherwise local only.",
    rainbowBlipOnTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)

do
    local bossLimit = {
        SLOT0   = IS_ENHANCED and 1923262 or 1922989,
        MAX_IDX = IS_ENHANCED and 275059 or 275055,
        SLOTS   = 10,
        GANG_OF = IS_ENHANCED and 2649994 or 2649991,
        GANG0   = IS_ENHANCED and 2650027 or 2650024,
        RETIRE  = IS_ENHANCED and (2733326 + 3989 + 755)
                              or  (2733190 + 3988 + 755),
        REVOKED = IS_ENHANCED and (2733326 + 922)
                              or  (2733190 + 921),
        FREEMODE   = Utils.sJoaat("freemode"),
        NEXT_VISIT = IS_ENHANCED and (7387 + 5) or (7329 + 5),
        freed    = nil,
        borrowed = nil,
        seated   = nil,
        status   = nil,
    }

    local IS_SESSION_ACTIVE = 0xD83C2B94E7508980
    local IS_IN_TRANSITION  = 0x68049AEFF83D8F0A
    local HOST_OF_SCRIPT    = 0x1D6A14F1F9A736FC

    local function sessionReady()
        return Natives.InvokeBool(IS_SESSION_ACTIVE)
            and not Natives.InvokeBool(IS_IN_TRANSITION)
            and (SCRIPT.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH(bossLimit.FREEMODE) or 0) > 0
    end

    local playerRid = VIBE_GATE.playerProtection.rid

    function bossLimit.count()
        local s = bossLimit
        local n = ScriptGlobal.GetInt(s.MAX_IDX) or 0
        if n < 1 or n > s.SLOTS then n = s.SLOTS end
        return n
    end

    function bossLimit.restoreSlot()
        local s = bossLimit
        local b = s.freed
        if not b then return end

        local duplicate = false
        for i = 0, b.count - 1 do
            if i ~= b.slot and ScriptGlobal.GetInt(s.SLOT0 + i) == b.pid then
                duplicate = true
                break
            end
        end

        local stillFree = ScriptGlobal.GetInt(s.SLOT0 + b.slot) == -1
        local rid = playerRid(b.pid)
        if not duplicate and stillFree and rid == nil then
            return
        end
        if not duplicate and stillFree and rid == b.rid and getOrgBoss(b.pid) == b.pid then
            ScriptGlobal.SetInt(s.SLOT0 + b.slot, b.pid)
        end
        s.freed = nil
    end

    function bossLimit.dropGang()
        local s = bossLimit
        local b = s.borrowed
        if not b then return end
        if playerRid(b.pid) == b.rid
            and ScriptGlobal.GetInt(s.GANG0 + b.gang * 2) ~= b.pid
            and ScriptGlobal.GetInt(s.GANG_OF + b.pid) == b.gang
        then
            ScriptGlobal.SetInt(s.GANG_OF + b.pid, -1)
        end
        s.borrowed = nil
    end

    function bossLimit.restore()
        bossLimit.unseat()
        bossLimit.restoreSlot()
        bossLimit.dropGang()
    end

    local function untilVisit(pid, nextPid)
        return (pid - nextPid) % 32
    end

    function bossLimit.pickSlot(n, nextPid)
        local s = bossLimit
        local best, bestPid, bestRid, bestDist
        for slot = n - 1, 0, -1 do
            local pid = ScriptGlobal.GetInt(s.SLOT0 + slot)
            local rid = playerRid(pid)
            if rid and getOrgBoss(pid) == pid then
                local d = nextPid and untilVisit(pid, nextPid) or 0
                if not best or d > bestDist then
                    best, bestPid, bestRid, bestDist = slot, pid, rid, d
                end
            end
        end
        return best, bestPid, bestRid
    end

    function bossLimit.keepBoss()
        local s = bossLimit
        if (ScriptGlobal.GetInt(s.RETIRE) or 0) == 0 then return end
        ScriptGlobal.SetInt(s.RETIRE, 0)
        local bits = ScriptGlobal.GetInt(s.REVOKED)
        if bits then ScriptGlobal.SetInt(s.REVOKED, bits & ~(1 << 25)) end
        if not s.loggedKeep then
            s.loggedKeep = true
            logf("[NoOrgLimit] blocked freemode's over-limit retire")
        end
    end

    local function holdsSlot(pid, n)
        for i = 0, n - 1 do
            if ScriptGlobal.GetInt(bossLimit.SLOT0 + i) == pid then return i end
        end
        return nil
    end

    function bossLimit.unseat()
        local s = bossLimit
        local b = s.seated
        if not b then return end
        s.seated = nil
        if b.me ~= GTA.GetLocalPlayerId()
            or ScriptGlobal.GetInt(s.SLOT0 + b.slot) ~= b.me then return end
        local back = -1
        if b.pid and playerRid(b.pid) == b.rid and getOrgBoss(b.pid) == b.pid
            and not holdsSlot(b.pid, b.count)
        then
            back = b.pid
        end
        ScriptGlobal.SetInt(s.SLOT0 + b.slot, back)
        logf("[NoOrgLimit] left seat %d, wrote back %d", b.slot, back)
    end

    function bossLimit.seat(n, me)
        local s = bossLimit
        local b = s.seated
        if b then
            if b.me == me and ScriptGlobal.GetInt(s.SLOT0 + b.slot) == me then return end
            s.seated = nil
        end
        if holdsSlot(me, n) then return end
        local held = s.freed
        if held and ScriptGlobal.GetInt(s.SLOT0 + held.slot) ~= -1 then held = nil end
        for i = 0, n - 1 do
            if ScriptGlobal.GetInt(s.SLOT0 + i) == -1 and not (held and i == held.slot) then
                return
            end
        end
        local slot, pid, rid
        if held then
            slot, pid, rid = held.slot, held.pid, held.rid
        else
            slot, pid, rid = s.pickSlot(n, nil)
            if not slot then return end
        end
        s.freed = nil
        s.seated = { slot = slot, pid = pid, rid = rid, count = n, me = me }
        ScriptGlobal.SetInt(s.SLOT0 + slot, me)
        logf("[NoOrgLimit] seated in slot %d (displaced boss %d)", slot, pid or -1)
    end

    function bossLimit.handOver(n, me)
        local s = bossLimit
        s.unseat()
        s.restoreSlot()
        local mine = holdsSlot(me, n)
        if not mine then return end
        for pid = 0, 31 do
            if pid ~= me and getOrgBoss(pid) == pid and playerRid(pid)
                and not holdsSlot(pid, n)
            then
                ScriptGlobal.SetInt(s.SLOT0 + mine, pid)
                logf("[NoOrgLimit] handed slot %d to boss %d", mine, pid)
                return
            end
        end
    end

    function bossLimit.gangTick(n)
        local s  = bossLimit
        local me = GTA.GetLocalPlayerId()
        local b  = s.borrowed

        if b then
            local rid = playerRid(me)
            if rid == nil then return end
            if b.pid ~= me or b.rid ~= rid
                or ScriptGlobal.GetInt(s.GANG_OF + b.pid) ~= b.gang
                or ScriptGlobal.GetInt(s.GANG0 + b.gang * 2) == me
            then
                s.borrowed, b = nil, nil
            end
        end

        if getOrgBoss(me) ~= me then
            s.dropGang()
            return
        end

        for i = 0, n - 1 do
            local owner = ScriptGlobal.GetInt(s.GANG0 + i * 2) or 0
            if owner ~= -1 and (owner < 0 or owner > 31) then return end
            if owner == -1 then
                s.dropGang()
                return
            end
        end

        if b or (ScriptGlobal.GetInt(s.GANG_OF + me) or -1) ~= -1 then return end

        for i = n - 1, 0, -1 do
            local colour = ScriptGlobal.GetInt(s.GANG0 + i * 2 + 1) or -1
            if colour >= 0 and colour < s.SLOTS then
                local myRid = playerRid(me)
                if not myRid then return end
                s.borrowed = { gang = i, pid = me, rid = myRid }
                ScriptGlobal.SetInt(s.GANG_OF + me, i)
                return
            end
        end
    end

    function bossLimit.onTick(f)
        local s = bossLimit
        if not f:IsToggled() then s.status = nil end
        if not sessionReady() then
            return
        end


        if s.freed then
            local b = s.freed
            local rid = playerRid(b.pid)
            if rid == nil then return end
            local duplicate = false
            for i = 0, b.count - 1 do
                if i ~= b.slot and ScriptGlobal.GetInt(s.SLOT0 + i) == b.pid then
                    duplicate = true
                    break
                end
            end
            if rid ~= b.rid or getOrgBoss(b.pid) ~= b.pid
                or ScriptGlobal.GetInt(s.SLOT0 + b.slot) ~= -1 or duplicate
            then
                s.freed = nil
            end
        end
        if not f:IsToggled() then
            if s.freed or s.borrowed or s.seated then s.restore() end
            s.frees, s.loggedKeep = nil, nil
            return
        end

        local host = Natives.InvokeInt(HOST_OF_SCRIPT, "freemode", -1, 0)
        s.status = host == GTA.GetLocalPlayerId() and T("Session-wide") or T("Local only")

        local n     = s.count()
        local free  = nil
        local zeros = 0
        for i = 0, n - 1 do
            local v = ScriptGlobal.GetInt(s.SLOT0 + i) or 0
            if v ~= -1 and (v < 0 or v > 31) then
                s.freed = nil
                return
            end
            if v == 0 then zeros = zeros + 1 end
            if v == -1 and not free then free = i end
        end
        if zeros == n then return end

        local me = GTA.GetLocalPlayerId()
        local isBoss = getOrgBoss(me) == me
        if isBoss then s.keepBoss() else s.loggedKeep = nil end

        if isBoss and host == me then
            s.handOver(n, me)
        elseif isBoss then
            s.seat(n, me)
        elseif s.seated then
            s.unseat()
        else
            local nextPid = nil
            if host == me then
                local v = ScriptLocal.GetInt(s.FREEMODE, s.NEXT_VISIT)
                if v and v >= 0 and v <= 31 then nextPid = v end
            end

            if not free then
                local slot, pid, rid = s.pickSlot(n, nextPid)
                if slot then
                    s.freed = { slot = slot, pid = pid, rid = rid, count = n }
                    ScriptGlobal.SetInt(s.SLOT0 + slot, -1)
                    s.frees = (s.frees or 0) + 1
                    if s.frees == 1 or s.frees == 10 then
                        logf("[NoOrgLimit] freed slot %d (boss %d), host=%s next=%s (#%d)",
                            slot, pid, tostring(host == me), tostring(nextPid), s.frees)
                    end
                end
            elseif nextPid and s.freed and untilVisit(s.freed.pid, nextPid) < 3 then
                local b = s.freed
                local slot, pid, rid = s.pickSlot(n, nextPid)
                if slot and untilVisit(pid, nextPid) >= 3 then
                    ScriptGlobal.SetInt(s.SLOT0 + b.slot, b.pid)
                    ScriptGlobal.SetInt(s.SLOT0 + slot, -1)
                    s.freed = { slot = slot, pid = pid, rid = rid, count = n }
                end
            end
        end

        s.gangTick(n)
    end

    bossLimitStatus = function() return bossLimit.status end

    centralOnTick(FeatureMgr.AddFeature(H.BOSS_LIMIT,
        "No Organization Limit", eFeatureType.Toggle,
        "Bypass the session's boss limit of 10. When you are the script host, this applies to the entire lobby.",
        bossLimit.onTick))
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)

    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, bossLimit.restore)
end

do
    local p = { PATCHED = 0xC3, addr = nil, retryIn = 0, missLogged = false }
    if IS_ENHANCED then
        p.ANCHOR   = "48 81 EC 30 09 00 00 48 89 CE 03 15"
        p.SITE_OFF = -1
        p.ORIG     = 0x56
    else
        p.ANCHOR   = "89 91 1C 83 02 00 E9"
        p.SITE_OFF = -6
        p.ORIG     = 0x03
    end

    p.resolve = function()
        if p.addr then return true end
        if p.retryIn > 0 then p.retryIn = p.retryIn - 1; return false end
        p.retryIn = 120
        local runBody = function()
            local hit = Memory.Scan(p.ANCHOR)
            if not hit or hit == 0 then
                if not p.missLogged then
                    p.missLogged = true
                    if VIBESCRIPT_VERBOSE then
                        VIBE_LOG_INFO("[VibeScript] Better Escape: anchor not found yet (retrying)")
                    end
                end
                return
            end
            local site = hit + p.SITE_OFF
            local b = Memory.ReadUByte(site)
            if b ~= p.ORIG and b ~= p.PATCHED then
                if VIBESCRIPT_VERBOSE then
                    VIBE_LOG_INFO(string.format(
                        "[VibeScript] Better Escape: unexpected site byte 0x%02X @0x%X; aborting", b or 0, site))
                end
                return
            end
            p.addr = site
            logf("Better Escape: resolved @0x%X (cur=0x%02X)", site, b)
        end
        runBody()
        return p.addr ~= nil
    end

    p.ensure = function(wantPatched)
        if not p.resolve() then return end
        do
            local cur = Memory.ReadUByte(p.addr)
            if wantPatched then
                if cur == p.ORIG then Memory.WriteByte(p.addr, p.PATCHED) end
            else
                if cur == p.PATCHED then Memory.WriteByte(p.addr, p.ORIG) end
            end
        end
    end

    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function() p.ensure(false) end)

    centralOnTick(FeatureMgr.AddFeature(H.BETTER_ESC_ENGINE, "Better Escape", eFeatureType.Toggle,
        "Removes the short delay before Escape can reopen the pause menu after closing it.",
        function(f)
            p.ensure(f:IsToggled())
        end))
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)
end

do
    local function site(name, legacyAnchor, enhancedAnchor, enhancedOrig)
        local orig = IS_ENHANCED and enhancedOrig or 0x48C48B48
        local patched = (orig & 0xFF000000) | 0x00C3C033
        local p = { name = name, ANCHOR = IS_ENHANCED and enhancedAnchor or legacyAnchor,
            addr = nil, retryIn = 0, missLogged = false }
        p.resolve = function()
            if p.addr then return true end
            if p.retryIn > 0 then p.retryIn = p.retryIn - 1; return false end
            p.retryIn = 120
            local hit = Memory.Scan(p.ANCHOR)
            if not hit or hit == 0 then
                if not p.missLogged then
                    p.missLogged = true
                    VIBE_LOG_ERROR("[VibeScript] " .. p.name .. ": site not found yet (retrying)")
                end
                return false
            end
            local cur = Memory.ReadUInt(hit)
            if cur ~= orig and cur ~= patched or hit % 4 ~= 0 then
                if not p.missLogged then
                    p.missLogged = true
                    if VIBESCRIPT_VERBOSE == true then VIBE_LOG_ERROR(string.format(
                        "[VibeScript] %s: unexpected bytes 0x%08X @0x%X; not patching", p.name, cur, hit)) end
                end
                return false
            end
            p.addr = hit
            logf("%s: resolved @0x%X (cur=0x%08X)", p.name, hit, cur)
            return true
        end
        p.ensure = function(wantPatched)
            if not p.resolve() then return end
            local cur = Memory.ReadUInt(p.addr)
            if wantPatched then
                if cur == orig then Memory.WriteInt(p.addr, patched) end
            elseif cur == patched then
                Memory.WriteInt(p.addr, orig)
            end
        end
        p.restore = function()
            if p.addr and Memory.ReadUInt(p.addr) == patched then Memory.WriteInt(p.addr, orig) end
        end
        return p
    end
    local drop = site("No Ledge Drop-Downs",
        "?? ?? ?? 48 89 58 08 48 89 68 10 48 89 70 18 57 41 56 41 57 48 83 EC 40 0F 29 70 D8 45 8A F9 48 8B DA 48 8B E9",
        "?? ?? ?? 56 56 57 55 53 48 83 EC 48 0F 29 74 24 30 4D 85 C0 0F 84 ?? ?? ?? ?? 44 89 CD 48 89 D7 48 89 CE C6 44 24 28 01 C6 44 24 20 01 31 DB 48 89 D1",
        0x56415741)
    local slope = site("No Slope Stumble",
        "?? ?? ?? 48 89 58 08 48 89 78 10 55 48 8B EC 48 81 EC 80 00 00 00 0F 29 70 E8 44 0F 29 40 D8 44 0F 29 48 C8 48 8B 81 D0 00 00 00 40 8A FA 48 8B D9",
        "?? ?? ?? 48 81 EC 90 00 00 00 44 0F 29 94 24 80 00 00 00 44 0F 29 4C 24 70 44 0F 29 44 24 60 0F 29 7C 24 50 0F 29 74 24 40 89 D3 48 89 CE 48 8B 81 D0 00 00 00",
        0x48535756)
    patchFn.edgeSlides = { drop = drop, slope = slope }

    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function() drop.restore(); slope.restore() end)

    centralOnTick(FeatureMgr.AddFeature(H.NO_DROP_DOWN, "No Ledge Drop-Downs", eFeatureType.Toggle,
        "Stops automatic slides, dives and skydives at ledges so you can jump off normally.",
        function(f)
            local on = f:IsToggled()
            drop.ensure(on)
            if on then PED.SET_PED_RESET_FLAG(PLAYER.PLAYER_PED_ID(), 195, true) end
        end))
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)

    centralOnTick(FeatureMgr.AddFeature(H.NO_SLOPE_SCRAMBLE, "No Slope Stumble", eFeatureType.Toggle,
        "Stops forced stumbling on steep ground and near ledges. Applies to all peds.",
        function(f)
            slope.ensure(f:IsToggled())
        end))
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)
end

centralOnTick(FeatureMgr.AddFeature(H.WP_INTERIOR, "Allow Exterior Waypoint", eFeatureType.Toggle,
    "Lets you set a waypoint from the pause map while inside interiors.",
    function(f)
        if not f:IsToggled() then return end
        if not HUD.IS_PAUSE_MENU_ACTIVE() then return end
        local interior = Natives.InvokeInt(0x2107BA504071A6BB, PLAYER.PLAYER_PED_ID())
        if not interior or interior == 0 then return end
        Natives.InvokeVoid(0x58FADDED207897DC, false)
    end))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)


do
    local p = { retryIn = 0, words = nil, reported = {} }
    p.AOB = IS_ENHANCED
        and "F6 86 56 14 00 00 ?? 75 4E F3 0F 10 03 0F 57 C9 0F 2E C1 77 42 48 8B 5F 10 48 8B 8B B8 10 00 00 48 85 C9 74 46 E8 ?? ?? ?? ?? 48 85 C0 74 06 48 8B 40 40 EB 14 48 8B 8B B8 10 00 00 48 8B 41 68 48 85 C0 75 04 48 8B 41 70 48 85 C0 74 1D F6 80 01 09 00 00 08 74 14 F3 0F 10 44 24 34 F3 0F 5D 05 ?? ?? ?? ?? F3 0F 11 44 24 34 F6 86 8A 01 00 00 40 ?? 3A 83 BE 30 02 00 00 00 74 31 F3 0F 10 86 48 02 00 00 0F 2E 05 ?? ?? ?? ?? 76 20 F3 0F 10 44 24 34 F3 0F 5D 05 ?? ?? ?? ?? F3 0F 11 44 24 34 8B 05 ?? ?? ?? ?? 89 87 C0 02 00 00 B8 FA 00 00 00 03 87 C0 02 00 00 3B 05 ?? ?? ?? ?? ?? 14 F3 0F 10 44 24 34 F3 0F 5D 05 ?? ?? ?? ?? F3 0F 11 44 24 34 F3 0F 10 3D ?? ?? ?? ?? F6 86 AA 14 00 00 ?? 75 76 48 8B 46 30 48 85 C0 74 2A"
        or "8B 83 54 14 00 00 45 0F 57 E4 C1 E8 14 ?? ?? ?? 75 12 45 0F 2F 26 72 0C 48 8B CF E8 ?? ?? ?? ?? 84 C0 74 10 F3 0F 10 05 ?? ?? ?? ?? 0F 2F F0 72 03 0F 28 F0 F7 83 88 01 00 00 00 00 40 00 ?? 35 39 B3 30 02 00 00 74 2D F3 0F 10 05 ?? ?? ?? ?? 0F 2F 83 48 02 00 00 73 1C F3 0F 10 05 ?? ?? ?? ?? 0F 2F F0 72 03 0F 28 F0 8B 05 ?? ?? ?? ?? 89 87 C0 02 00 00 8B 87 C0 02 00 00 05 FA 00 00 00 3B 05 ?? ?? ?? ?? ?? 10 F3 0F 10 05 ?? ?? ?? ?? 0F 2F F0 72 03 0F 28 F0 8B 83 A8 14 00 00 F3 44 0F 10 05 ?? ?? ?? ?? C1 E8 13 ?? ?? ?? 74 76 F3 0F 10 8F 54 02 00 00"
    p.sites = IS_ENHANCED and {
        { 0x06, {0x10}, {0x00} },
        { 0x72, {0x74}, {0xEB} },
        { 0xBF, {0x76}, {0xEB} },
        { 0xE3, {0x08}, {0x00} },
    } or {
        { 0x0D, {0x41,0x84,0xC4}, {0xA8,0x00,0x90} },
        { 0x3E, {0x74}, {0xEB} },
        { 0x86, {0x76}, {0xEB} },
        { 0xAA, {0x41,0x84,0xC4}, {0xA8,0x00,0x90} },
    }
    p.deepAOB = IS_ENHANCED
        and "F3 0F 10 05 ?? ?? ?? ?? 0F 2E C7 ?? ?? C7 07 00 00 00 00 0F 57 C0 E9 ?? ?? ?? ?? F6 83 70 14 00 00 20 75 E9 0F 28 83 90 00 00 00"
        or "0F 2F D1 ?? 7E 41 8B 82 70 14 00 00 C1 E8 05 40 84 C7 75 6F 84 C9 75 6B F3 0F 10 05 ?? ?? ?? ?? 0F 2F D0"
    p.deepSites = IS_ENHANCED and {
        { 0x0B, {0x76,0x0E}, {0x66,0x90} },
    } or {
        { 0x03, {0x72}, {0xEB} },
    }
    p.fail = function(key, message)
        if not p.reported[key] then
            p.reported[key] = true
            VIBE_LOG_ERROR("[VibeScript] Disable Terrain Slowdown: " .. message)
        end
    end
    p.write = function(addr, value)
        if value >= 0x80000000 then value = value - 0x100000000 end
        Memory.WriteInt(addr, value)
    end
    p.restore = function()
        if not p.words then return end
        for _, w in ipairs(p.words) do
            local cur = Memory.ReadUInt(w.addr)
            if cur == w.patched then
                p.write(w.addr, w.orig)
            elseif cur ~= w.orig then
                p.fail("restore", "code changed externally; refusing to overwrite unfamiliar bytes")
            end
        end
    end
    p.resolve = function()
        if p.words then return true end
        if p.retryIn > 0 then p.retryIn = p.retryIn - 1; return false end
        p.retryIn = 120
        local hit = Memory.Scan(p.AOB)
        local deepHit = Memory.Scan(p.deepAOB)
        if not hit or hit == 0 or not deepHit or deepHit == 0 then
            p.fail("scan", "verified terrain checks not found (retrying); no patch applied")
            return false
        end
        local words = {}
        for _, group in ipairs({{hit, p.sites}, {deepHit, p.deepSites}}) do
            for _, site in ipairs(group[2]) do
                local addr, original, replacement = group[1] + site[1], site[2], site[3]
                local byteOffset = addr % 4
                if byteOffset + #original > 4 then
                    p.fail("alignment", "instruction edit crosses an aligned dword; no patch applied")
                    return false
                end
                local origBits, newBits = 0, 0
                for i = 1, #original do
                    origBits = origBits | (original[i] << ((i - 1) * 8))
                    newBits = newBits | (replacement[i] << ((i - 1) * 8))
                end
                local shift = byteOffset * 8
                local mask = ((1 << (#original * 8)) - 1) << shift
                origBits, newBits = origBits << shift, newBits << shift
                local aligned = addr - byteOffset
                local cur = Memory.ReadUInt(aligned)
                if (cur & mask) ~= origBits and (cur & mask) ~= newBits then
                    p.fail("bytes", "unexpected terrain-check bytes; no patch applied")
                    return false
                end
                words[#words + 1] = { addr = aligned,
                    orig = (cur & ~mask) | origBits, patched = (cur & ~mask) | newBits }
            end
        end
        p.words = words
        return true
    end
    p.ensure = function(on)
        if not p.resolve() then return end
        for _, w in ipairs(p.words) do
            local cur = Memory.ReadUInt(w.addr)
            if cur ~= w.orig and cur ~= w.patched then
                p.fail("changed", "terrain code changed externally; restoring known patches and refusing new writes")
                p.restore()
                p.words, p.retryIn = nil, 120
                return
            end
        end
        for _, w in ipairs(p.words) do
            local want = on and w.patched or w.orig
            if Memory.ReadUInt(w.addr) ~= want then p.write(w.addr, want) end
        end
    end
    patchFn.terrainSlowdown = p
    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, p.restore)
    centralOnTick(FeatureMgr.AddFeature(H.NO_TERRAIN_SLOWDOWN,
        "Disable Terrain Slowdown", eFeatureType.Toggle,
        "Removes movement slowdown from slopes, shallow water, bushes, mud, sand and snow.",
        function(f) p.ensure(f:IsToggled()) end))
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)
end

do
    local function climbPatch(tag, aob, sites)
        local p = { AOB = aob, sites = sites, retryIn = 0, words = nil, reported = {} }
        p.fail = function(key, message)
            if not p.reported[key] then
                p.reported[key] = true
                VIBE_LOG_ERROR("[VibeScript] Climb Steep Slopes (" .. tag .. "): " .. message)
            end
        end
        p.write = function(addr, value)
            if value >= 0x80000000 then value = value - 0x100000000 end
            Memory.WriteInt(addr, value)
        end
        p.restore = function()
            if not p.words then return end
            for _, w in ipairs(p.words) do
                if Memory.ReadUInt(w.addr) == w.patched then p.write(w.addr, w.orig) end
            end
        end
        p.resolve = function()
            if p.words then return true end
            if p.retryIn > 0 then p.retryIn = p.retryIn - 1; return false end
            p.retryIn = 120
            local hit = Memory.Scan(p.AOB)
            if not hit or hit == 0 then
                p.fail("scan", "check not found (retrying); no patch applied")
                return false
            end
            local words = {}
            for _, site in ipairs(p.sites) do
                local addr, original, replacement = hit + site[1], site[2], site[3]
                local byteOffset = addr % 4
                if byteOffset + #original > 4 then
                    p.fail("alignment", "instruction edit crosses an aligned dword; no patch applied")
                    return false
                end
                local origBits, newBits = 0, 0
                for i = 1, #original do
                    origBits = origBits | (original[i] << ((i - 1) * 8))
                    newBits = newBits | (replacement[i] << ((i - 1) * 8))
                end
                local shift = byteOffset * 8
                local mask = ((1 << (#original * 8)) - 1) << shift
                origBits, newBits = origBits << shift, newBits << shift
                local aligned = addr - byteOffset
                local cur = Memory.ReadUInt(aligned)
                if (cur & mask) ~= origBits and (cur & mask) ~= newBits then
                    p.fail("bytes", "unexpected bytes; no patch applied")
                    return false
                end
                words[#words + 1] = { addr = aligned,
                    orig = (cur & ~mask) | origBits, patched = (cur & ~mask) | newBits }
            end
            p.words = words
            return true
        end
        p.ensure = function(on)
            if not p.resolve() then return end
            for _, w in ipairs(p.words) do
                local cur = Memory.ReadUInt(w.addr)
                if cur ~= w.orig and cur ~= w.patched then
                    p.fail("changed", "code changed externally; restoring and refusing new writes")
                    p.restore()
                    p.words, p.retryIn = nil, 120
                    return
                end
            end
            for _, w in ipairs(p.words) do
                local want = on and w.patched or w.orig
                if Memory.ReadUInt(w.addr) ~= want then p.write(w.addr, want) end
            end
        end
        return p
    end
    local velocity = climbPatch("velocity", IS_ENHANCED
        and "80 3D ?? ?? ?? ?? 00 74 29 31 C0 F7 87 B8 14 00 00 00 08 00 00 0F 94 C0 48 8D 0D ?? ?? ?? ?? F3 0F 10 04 81 0F 2E 87 A8 03 00 00 ?? ?? E9 ?? ?? ?? ?? F3 0F 10 05 ?? ?? ?? ?? 0F 2E 87 A8 03 00 00 ?? ?? ?? ?? ?? ?? F6 87 63 14 00 00 20 0F 85"
        or "80 3D ?? ?? ?? ?? 00 74 18 8B 83 B8 14 00 00 C1 E8 0B 41 84 C7 74 0A F3 0F 10 05 ?? ?? ?? ?? EB 08 F3 0F 10 05 ?? ?? ?? ?? 0F 2F 83 A8 03 00 00 ?? ?? ?? ?? ?? ?? 8B 83 60 14 00 00 C1 E8 1D 41 84 C7 0F 85",
        IS_ENHANCED and {
            { 0x2B, {0x77,0x1A}, {0x66,0x90} },
            { 0x41, {0x0F,0x86}, {0x90,0xE9} },
        } or {
            { 0x30, {0x0F,0x86}, {0x90,0xE9} },
        })
    local ground = climbPatch("ground", IS_ENHANCED
        and "4C 89 EE 41 0F 28 14 24 0F C6 D2 AA 0F C2 D0 02 0F 28 45 00 0F C6 C0 AA 0F C2 C8 ?? 0F 54 CA 0F 50 C1 41 B6 01 85 C0"
        or "0F 57 E4 4C 8B BC 24 ?? ?? ?? ?? 66 41 0F 70 0C 24 AA 45 0F 57 C0 C6 84 24 ?? ?? ?? ?? 01 66 41 0F 70 07 AA 0F C2 CB 02 0F C2 E0 ?? 0F 54 E1 66 41 0F 76 E0 0F 50 C4 83 F8 0F",
        IS_ENHANCED and {
            { 0x1B, {0x02}, {0x07} },
        } or {
            { 0x2B, {0x02}, {0x07} },
        })
    local capsule = { OFF_INFO = 0x1298, OFF_MAX = 0x28, FLAT_MAX = 0.0,
        EXPECT = { [0x28] = 0.95, [0x2C] = -0.99, [0x30] = 0.75, [0x34] = 0.40 },
        touched = {}, ped = 0, info = 0, retryIn = 0, reported = false }
    capsule.near = function(a, b) return math.abs(a - b) < 0.0005 end
    capsule.restore = function()
        for info, orig in pairs(capsule.touched) do
            if capsule.near(Memory.ReadFloat(info + capsule.OFF_MAX), capsule.FLAT_MAX) then
                Memory.WriteFloat(info + capsule.OFF_MAX, orig)
            end
        end
        capsule.touched, capsule.ped, capsule.info, capsule.retryIn = {}, 0, 0, 0
    end
    capsule.ensure = function(on)
        if not on then
            if next(capsule.touched) then capsule.restore() end
            return
        end
        local ped = PLAYER.PLAYER_PED_ID()
        if ped == 0 then return end
        if ped ~= capsule.ped then
            if capsule.retryIn > 0 then capsule.retryIn = capsule.retryIn - 1; return end
            capsule.retryIn = 30
            local ptr = GTA.HandleToPointer(ped)
            local addr = ptr and ptr:GetAddress() or 0
            if addr == 0 then return end
            local info = Memory.ReadLong(addr + capsule.OFF_INFO)
            if not info or info < 0x10000 then return end
            if not capsule.touched[info] then
                for off, want in pairs(capsule.EXPECT) do
                    if not capsule.near(Memory.ReadFloat(info + off), want) then
                        if not capsule.reported then
                            capsule.reported = true
                            VIBE_LOG_ERROR(string.format(
                                "[VibeScript] Climb Steep Slopes (capsule): unexpected value at +0x%X; capsule left alone", off))
                        end
                        capsule.ped, capsule.info = ped, 0
                        return
                    end
                end
                capsule.touched[info] = Memory.ReadFloat(info + capsule.OFF_MAX)
            end
            capsule.ped, capsule.info, capsule.retryIn = ped, info, 0
        end
        if capsule.info ~= 0 and capsule.touched[capsule.info]
            and not capsule.near(Memory.ReadFloat(capsule.info + capsule.OFF_MAX), capsule.FLAT_MAX) then
            Memory.WriteFloat(capsule.info + capsule.OFF_MAX, capsule.FLAT_MAX)
        end
    end
    patchFn.climbAnySlope = { velocity = velocity, ground = ground, capsule = capsule }
    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function() velocity.restore(); ground.restore(); capsule.restore() end)
    centralOnTick(FeatureMgr.AddFeature(H.CLIMB_ANY_SLOPE,
        "Climb Steep Slopes", eFeatureType.Toggle,
        "Lets you walk up steep hills and cliffs. Use No Slope Stumble to prevent stumbling.",
        function(f)
            local on = f:IsToggled()
            velocity.ensure(on)
            ground.ensure(on)
            capsule.ensure(on)
        end))
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)
end


