function louderRadio.deleteBus(handle)
    local s = louderRadio
    if scriptUnloading then return end
    if not ENTITY.DOES_ENTITY_EXIST(handle) then s.dying[handle] = nil return end
    Natives.InvokeVoid(SET_ENTITY_VISIBLE, handle, false, false)
    NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(handle)
    Natives.InvokeVoid(DETACH_ENTITY, handle, true, false)
    ENTITY.SET_ENTITY_AS_MISSION_ENTITY(handle, true, true)
    if NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(handle) then
        NETWORK.NETWORK_UNREGISTER_NETWORKED_ENTITY(handle)
    end
    Memory.WriteInt(s.delBuf, handle)
    ENTITY.DELETE_ENTITY(s.delBuf)
    if ENTITY.DOES_ENTITY_EXIST(handle) then
        Memory.WriteInt(s.delBuf, handle)
        ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED(s.delBuf)
        s.dying[handle] = true
        if not s.deleteFailLogged then
            s.deleteFailLogged = true
            logf("[LouderRadio] bus survived its delete (mission=%s networked=%s control=%s); retrying",
                tostring(Natives.InvokeBool(0x0A7B270912999B3C, handle)),
                tostring(NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(handle)),
                tostring(NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(handle)))
        end
        ENTITY.FREEZE_ENTITY_POSITION(handle, true)
        ENTITY.SET_ENTITY_COLLISION(handle, false, false)
    else
        s.dying[handle] = nil
    end
end

function louderRadio.retryDying()
    local s = louderRadio
    if next(s.dying) == nil then return end
    local live = {}
    for _, bus in ipairs(s.buses) do live[bus.handle] = true end
    if radioCtl.plBus then
        for _, st in pairs(radioCtl.plBus) do
            if st.handle and st.handle ~= 0 then live[st.handle] = true end
        end
    end
    for handle in pairs(s.dying) do
        if live[handle] or Natives.InvokeInt(GET_ENTITY_MODEL, handle) ~= s.MODEL then
            s.dying[handle] = nil
        else
            louderRadio.deleteBus(handle)
        end
    end
end

function louderRadio.playerRealVehicle()
    local ped = PLAYER.PLAYER_PED_ID()
    if not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then return 0 end
    local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if veh == 0 then return 0 end
    for _, bus in ipairs(louderRadio.buses) do
        if bus.handle == veh then return 0 end
    end
    if Natives.InvokeInt(GET_ENTITY_MODEL, veh) == louderRadio.MODEL
        and Natives.InvokeBool(IS_ENTITY_ATTACHED_TO_ENTITY, veh, ped) then
        return 0
    end
    return veh
end

function louderRadio.inTransition()
    return Natives.InvokeBool(IS_SCREEN_FADED_OUT)
        or Natives.InvokeBool(IS_SCREEN_FADING_OUT)
        or Natives.InvokeBool(GET_IS_LOADING_SCREEN_ACTIVE)
        or Natives.InvokeBool(IS_PLAYER_TELEPORT_ACTIVE)
end

function louderRadio.deleteAll()
    local s = louderRadio
    local had = #s.buses
    local i = 1
    while i <= #s.buses do
        louderRadio.deleteBus(s.buses[i].handle)
        if ENTITY.DOES_ENTITY_EXIST(s.buses[i].handle) then
            i = i + 1
        else
            table.remove(s.buses, i)
        end
    end
    louderRadio.dropAllHolds()
    if #s.buses > 0 then
        logf("[LouderRadio] deleteAll: %d/%d bus(es) survived, retrying", #s.buses, had)
    end
    if #s.buses == 0 then STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(s.MODEL) end
end

function louderRadio.inSession()
    return Natives.InvokeBool(louderRadio.NAT_IS_SESSION_ACTIVE)
end

function louderRadio.disarmForExit(reason, mayYield)
    local s = louderRadio
    local had = #s.buses
    s.arriveSweepUntil = Time.GetEpocheMs() + s.ARRIVE_SWEEP_MS
    s.nextArriveSweepAt = 0
    louderRadio.deleteAll()
    if mayYield then
        for _ = 1, 8 do
            if #s.buses == 0 then break end
            Script.Yield(50)
            louderRadio.deleteAll()
        end
    end
    logf("[LouderRadio] disarm (%s): %d bus(es) -> %d left", reason, had, #s.buses)
    return #s.buses == 0
end

function louderRadio.startHold(stName, now)
    local s = louderRadio
    if not stName or stName == "" or stName == "OFF" then return end
    for _, h in ipairs(s.holds) do
        if h.station == stName then h.at = now; return end
    end
    if #s.holds >= s.HOLD_MAX then
        local oldest = 1
        for i = 2, #s.holds do
            if s.holds[i].at < s.holds[oldest].at then oldest = i end
        end
        louderRadio.dropHold(oldest)
    end
    local pos = ENTITY.GET_ENTITY_COORDS(PLAYER.PLAYER_PED_ID(), true)
    local veh = VEHICLE.CREATE_VEHICLE(s.MODEL, pos.x + s.HOLD_DIST, pos.y,
        pos.z - s.HOLD_DEPTH, 0.0, false, false, false)
    if not veh or veh == 0 then return end
    Natives.InvokeVoid(SET_ENTITY_VISIBLE, veh, false, false)
    ENTITY.SET_ENTITY_COLLISION(veh, false, false)
    ENTITY.SET_ENTITY_AS_MISSION_ENTITY(veh, true, true)
    VEHICLE.SET_VEHICLE_ENGINE_ON(veh, true, true, false)
    Natives.InvokeVoid(KEEP_ENGINE_ON_WHEN_ABANDONED, veh, true)
    Natives.InvokeVoid(SET_VEHICLE_RADIO_ENABLED, veh, true)
    Natives.InvokeVoid(SET_VEH_HAS_NORMAL_RADIO, veh)
    louderRadio.tuneBus(veh, stName)
    s.holds[#s.holds + 1] = {
        handle = veh, station = stName, at = now,
        addr = UnloadReap.addrOf(veh), pop = UnloadReap.popOf(veh),
        kind = "vehicle",
    }
    logf("[LouderRadio] holding %s on a parked emitter (%d held)", stName, #s.holds)
end

function louderRadio.dropHold(i)
    local s = louderRadio
    local h = s.holds[i]
    if not h then return end
    if h.handle then louderRadio.deleteBus(h.handle) end
    table.remove(s.holds, i)
    logf("[LouderRadio] released hold on %s (%d held)", tostring(h.station), #s.holds)
end

function louderRadio.dropAllHolds()
    local s = louderRadio
    for i = #s.holds, 1, -1 do louderRadio.dropHold(i) end
end

function louderRadio.holdTick(now)
    local s = louderRadio
    if s.holdWanted then
        local want = s.holdWanted
        s.holdWanted = nil
        if want ~= s.station then louderRadio.startHold(want, now) end
    end
    for i = #s.holds, 1, -1 do
        if now - s.holds[i].at >= s.HOLD_MS then louderRadio.dropHold(i) end
    end
end

function louderRadio.stripExtras(veh)
    for id = 1, MAX_EXTRA_ID do
        if Natives.InvokeBool(DOES_EXTRA_EXIST, veh, id)
            and Natives.InvokeBool(IS_VEHICLE_EXTRA_TURNED_ON, veh, id) then
            Natives.InvokeVoid(SET_VEHICLE_EXTRA, veh, id, true)
        end
    end
end

function louderRadio.disableTargeting(veh)
    Natives.InvokeVoid(louderRadio.N_VEHICLE_CAN_BE_TARGETTED, veh, false)
    Natives.InvokeVoid(louderRadio.N_ALLOW_NO_PASSENGERS_LOCKON, veh, false)
    Natives.InvokeVoid(louderRadio.N_ALLOW_HOMING_LOCKON, veh, false, true)
    Natives.InvokeVoid(louderRadio.N_ALLOW_HOMING_LOCKON_SYNCED, veh, false, true)
end

function louderRadio.configure(veh, visible)
    ENTITY.SET_ENTITY_COLLISION(veh, false, false)
    ENTITY.SET_ENTITY_INVINCIBLE(veh, true)
    ENTITY.SET_ENTITY_AS_MISSION_ENTITY(veh, true, true)
    louderRadio.disableTargeting(veh)
    louderRadio.stripExtras(veh)
    Natives.InvokeVoid(SET_ENTITY_VISIBLE, veh, visible and true or false, false)
    Natives.InvokeVoid(SET_ENTITY_PROOFS, veh, true, true, true, true, true, true, 1, true)
    VEHICLE.SET_VEHICLE_ENGINE_ON(veh, true, true, false)
    Natives.InvokeVoid(KEEP_ENGINE_ON_WHEN_ABANDONED, veh, true)
    Natives.InvokeVoid(SET_VEHICLE_RADIO_ENABLED, veh, true)
    Natives.InvokeVoid(SET_VEH_HAS_NORMAL_RADIO, veh)
    Natives.InvokeVoid(SET_VEHICLE_RADIO_LOUD, veh, true)
end

function louderRadio.reannounceHidden(now, hidden)
    local s = louderRadio
    if s.visResendPending then
        s.visResendPending = false
        for _, bus in ipairs(s.buses) do
            Natives.InvokeVoid(s.N_SET_RENDER_SCORCHED, bus.handle, false)
        end
        return
    end
    if not hidden or #s.buses == 0 or now < s.nextVisResendAt then return end
    s.nextVisResendAt = now + s.VIS_RESEND_MS
    s.visResendPending = true
    for _, bus in ipairs(s.buses) do
        Natives.InvokeVoid(s.N_SET_RENDER_SCORCHED, bus.handle, true)
    end
    if not s.visResendLogged then
        s.visResendLogged = true
        logf("[LouderRadio] hidden-state re-announce beating every %dms (%d bus(es))",
            s.VIS_RESEND_MS, #s.buses)
    end
end

function louderRadio.resolveStopPatch()
    local p = louderRadio.stopPatch
    if not p.AOB or p.failed then return p.addr ~= 0 end
    if p.addr ~= 0 then return true end
    p.tries = p.tries + 1
    if p.tries > p.SCAN_TRIES then
        p.failed = true
        log("[LouderRadio] StopEmitters setter not found; enable-at-speed may lag")
        return false
    end
    local hit = Memory.Scan(p.WILD)
    if not hit or hit == 0 then return false end
    local addr = hit + p.OFF
    local cur = Memory.ReadByte(addr)
    if cur == p.PATCHED then
        Memory.WriteByte(addr, p.PRISTINE)
        logf("[LouderRadio] StopEmitters setter was stale-patched @ %X; healed", addr)
    elseif cur ~= p.PRISTINE then
        return false
    end
    p.addr = addr
    logf("[LouderRadio] StopEmitters setter resolved @ %X", addr)
    return true
end

function louderRadio.setStopPatch(on)
    local p = louderRadio.stopPatch
    if p.addr == 0 or p.applied == on then return end
    Memory.WriteByte(p.addr, on and p.PATCHED or p.PRISTINE)
    p.applied = on
end

function louderRadio.resolveWheelPatch()
    local p = louderRadio.wheelPatch
    if not p.AOB or p.failed then return p.addr ~= 0 end
    if p.addr ~= 0 then return true end
    p.tries = p.tries + 1
    if p.tries > p.SCAN_TRIES then
        p.failed = true
        log("[LouderRadio] radio-wheel gate not found; on-foot wheel unavailable")
        return false
    end
    local hit = Memory.Scan(p.AOB)
    if not hit or hit == 0 then return false end
    local addr = hit + p.OFF
    if Memory.ReadByte(addr) == p.PATCHED[1] then
        for i = 1, #p.PRISTINE do Memory.WriteByte(addr + i - 1, p.PRISTINE[i]) end
        logf("[LouderRadio] radio-wheel gate was stale-patched @ %X; healed", addr)
    end
    p.addr = addr
    logf("[LouderRadio] radio-wheel gate resolved @ %X", addr)
    return true
end

function louderRadio.setWheelPatch(on)
    local p = louderRadio.wheelPatch
    if p.addr == 0 or p.applied == on then return end
    local bytes = on and p.PATCHED or p.PRISTINE
    for i = 1, #bytes do Memory.WriteByte(p.addr + i - 1, bytes[i]) end
    p.applied = on
end


function louderRadio.tuneBus(veh, station)
    Natives.InvokeVoid(SET_VEH_RADIO_STATION, veh, station)
end

function louderRadio.attachBus(veh, idx, ped, zOff, count)
    local ox, oy, h = louderRadio.starChord(idx, count)
    Natives.InvokeVoid(DETACH_ENTITY, veh, false, false)
    Natives.InvokeVoid(ATTACH_ENTITY_TO_ENTITY, veh, ped, -1,
        ox, oy, zOff,
        louderRadio.PITCH_DEG, 0.0, math.deg(h),
        false,
        false,
        false,
        true,
        0,
        true,
        0)
end

function louderRadio.netVehicleCount()
    local n = 0
    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        local cveh = PoolMgr.GetCVehicle(i)
        if cveh and cveh.NetObject then n = n + 1 end
    end
    return n
end

function louderRadio.nearbyBusCount(pos)
    local s, n = louderRadio, 0
    local r2 = s.DENSITY_RADIUS * s.DENSITY_RADIUS
    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        local veh = PoolMgr.GetVehicle(i)
        if veh and veh > 0
            and Natives.InvokeInt(GET_ENTITY_MODEL, veh) == s.MODEL then
            local vp = ENTITY.GET_ENTITY_COORDS(veh, false)
            local dx, dy, dz = vp.x - pos.x, vp.y - pos.y, vp.z - pos.z
            if dx * dx + dy * dy + dz * dz <= r2 then n = n + 1 end
        end
    end
    return n
end

function louderRadio.nearestPlayers(pos)
    local me, near = GTA.GetLocalPlayerId(), {}
    for pid = 0, 31 do
        if pid ~= me and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
            local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
            if ped and ped ~= 0 and ENTITY.DOES_ENTITY_EXIST(ped) then
                local p = ENTITY.GET_ENTITY_COORDS(ped, false)
                local dx, dy, dz = p.x - pos.x, p.y - pos.y, p.z - pos.z
                near[#near + 1] = { d = math.sqrt(dx * dx + dy * dy + dz * dz), pid = pid }
            end
        end
    end
    table.sort(near, function(a, b) return a.d < b.d end)
    local out = {}
    for k = 1, math.min(3, #near) do
        out[k] = string.format("%s %.1fm", tostring(PLAYER.GET_PLAYER_NAME(near[k].pid)), near[k].d)
    end
    return #out > 0 and table.concat(out, ", ") or "none"
end

function louderRadio.parkBus(veh, park)
    Natives.InvokeVoid(KEEP_ENGINE_ON_WHEN_ABANDONED, veh, not park)
    VEHICLE.SET_VEHICLE_ENGINE_ON(veh, not park, true, park)
end

function louderRadio.spawnFailed(reason, n)
    local s = louderRadio
    if reason == s.lastSpawnFail then return nil end
    s.lastSpawnFail = reason
    if reason == "create" then
        VIBE_LOG_ERROR(string.format("[LouderRadio] spawn refused: CREATE_VEHICLE returned 0"
            .. " (model %08X loaded=%s valid=%s, vehicles %d/%d)",
            s.MODEL & 0xFFFFFFFF,
            tostring(STREAMING.HAS_MODEL_LOADED(s.MODEL)),
            tostring(STREAMING.IS_MODEL_VALID(s.MODEL)),
            PoolMgr.GetCurrentVehicleCount(), PoolMgr.GetMaxVehicleCount()))
    elseif reason == "netpool" then
        VIBE_LOG_ERROR(string.format("[LouderRadio] spawn refused: %d/%d networked vehicles in use",
            n or 0, NETWORK.GET_MAX_NUM_NETWORK_VEHICLES()))
    elseif reason == "register" then
        local d = type(n) == "table" and n or {}
        VIBE_LOG_ERROR(string.format("[LouderRadio] spawn refused: networked create left the bus local"
            .. " (mission=%s entity=%s netVehicles=%d/%d)",
            tostring(d.mission), tostring(d.exists), d.used or -1, d.max or -1))
    else
        log("[LouderRadio] spawning again")
    end
    return nil
end

function louderRadio.spawnBus(pos, station, ped, zOff, visible, count)
    local s = louderRadio
    local used = louderRadio.netVehicleCount()
    if used > 0 and used + s.NET_HEADROOM >= NETWORK.GET_MAX_NUM_NETWORK_VEHICLES() then
        s.nextSpawnAt = Time.GetEpocheMs() + s.RESPAWN_COOLDOWN_MS
        return louderRadio.spawnFailed("netpool", used)
    end

    local veh, bus, networked = 0, nil, false
    Script.ExecuteAsScript("freemode", function()
        veh = VEHICLE.CREATE_VEHICLE(s.MODEL, pos.x, pos.y, pos.z + s.SPAWN_DEPTH,
            0.0, true, false, false) or 0
        if veh == 0 then return end
        bus = {
            handle = veh,
            zOff   = zOff,
            count  = count,
            bornAt = Time.GetEpocheMs(),
            bornFrame = s.frameNo or 0,
            addr   = UnloadReap.addrOf(veh),
        }
        table.insert(s.buses, bus)
        s.everSpawned[veh] = true
        Natives.InvokeVoid(SET_ENTITY_VISIBLE, veh, false, false)
        ENTITY.SET_ENTITY_COLLISION(veh, false, false)
        networked = NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(veh)
        if networked then
            bus.netId = NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(veh)
            NETWORK.SET_NETWORK_ID_CAN_MIGRATE(bus.netId, false)
        end
    end)
    if veh == 0 then return louderRadio.spawnFailed("create") end

    ENTITY.SET_ENTITY_AS_MISSION_ENTITY(veh, true, true)
    louderRadio.disableTargeting(veh)

    if not networked then
        for i = #s.buses, 1, -1 do
            if s.buses[i] == bus then table.remove(s.buses, i) break end
        end
        louderRadio.deleteBus(veh)
        return louderRadio.spawnFailed("register", {
            mission = Natives.InvokeBool(0x0A7B270912999B3C, veh),
            exists  = ENTITY.DOES_ENTITY_EXIST(veh),
            used    = louderRadio.netVehicleCount(),
            max     = NETWORK.GET_MAX_NUM_NETWORK_VEHICLES(),
        })
    end
    if not s.createLogged then
        s.createLogged = true
        logf("[LouderRadio] bus created as a mission net object (netVehicles=%d/%d)",
            louderRadio.netVehicleCount(), NETWORK.GET_MAX_NUM_NETWORK_VEHICLES())
    end

    louderRadio.configure(veh, false)
    louderRadio.attachBus(veh, #s.buses, ped, zOff, count)
    Natives.InvokeVoid(SET_ENTITY_VISIBLE, veh, visible and true or false, false)
    if station then
        louderRadio.tuneBus(veh, station)
        bus.station = station
    end
    bus.pop = UnloadReap.popOf(veh)
    bus.kind = "vehicle"
    louderRadio.spawnFailed(nil)
    return veh
end

function louderRadio.sweepOrphans()
    local s = louderRadio
    local ped = PLAYER.PLAYER_PED_ID()
    local pos = ENTITY.GET_ENTITY_COORDS(ped, true)
    local own = {}
    for _, bus in ipairs(s.buses) do own[bus.handle] = true end
    for _, h in ipairs(s.holds) do if h.handle then own[h.handle] = true end end
    if radioCtl.plBus then
        for _, st in pairs(radioCtl.plBus) do
            if st.handle and st.handle ~= 0 then own[st.handle] = true end
        end
    end
    local r2, swept = s.SWEEP_RADIUS * s.SWEEP_RADIUS, 0
    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        if swept >= s.SWEEP_LIMIT then break end
        local veh = PoolMgr.GetVehicle(i)
        if veh and veh > 0 and not own[veh]
            and Natives.InvokeInt(GET_ENTITY_MODEL, veh) == s.MODEL
            and NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(veh) then
            local vp = ENTITY.GET_ENTITY_COORDS(veh, false)
            local dx, dy, dz = vp.x - pos.x, vp.y - pos.y, vp.z - pos.z
            if dx * dx + dy * dy + dz * dz <= r2
                and (Natives.InvokeBool(IS_ENTITY_ATTACHED_TO_ENTITY, veh, ped)
                     or not (Natives.InvokeBool(s.N_IS_ENTITY_ATTACHED, veh)
                             or Natives.InvokeBool(s.N_IS_ENTITY_VISIBLE, veh))) then
                louderRadio.deleteBus(veh)
                swept = swept + 1
            end
        end
    end
    if swept > 0 then logf("[LouderRadio] swept %d orphaned speaker(s)", swept) end
    return swept
end

function louderRadio.modelBox()
    local s = louderRadio
    if s.box then return s.box end
    local buf = s.dimBuf
    Natives.InvokeVoid(GET_MODEL_DIMENSIONS, s.MODEL, buf, buf + 24)
    local box = { miny = Memory.ReadFloat(buf + 8), maxy = Memory.ReadFloat(buf + 32) }
    if not (box.maxy and box.maxy > 1.0) then return nil end
    s.box = box
    return box
end

function louderRadio.logBusAxes(veh, h)
    local s = louderRadio
    if s.axesLogged then return end
    s.axesLogged = true
    local ox, oy = Natives.InvokeV3(s.N_OFFSET_TO_WORLD, veh, 0.0, 0.0, 0.0)
    local xx, xy = Natives.InvokeV3(s.N_OFFSET_TO_WORLD, veh, 1.0, 0.0, 0.0)
    local zx, zy = Natives.InvokeV3(s.N_OFFSET_TO_WORLD, veh, 0.0, 0.0, 1.0)
    if not (ox and xx and zx) then s.axesLogged = false return end
    logf("[LouderRadio] bus axes: +X at %+.1f, +Z at %+.1f from heading",
        math.deg(math.atan(xy - oy, xx - ox) - h),
        math.deg(math.atan(zy - oy, zx - ox) - h))
end

function louderRadio.starChord(idx, count)
    local s      = louderRadio
    local shape  = s.SHAPES[count] or s.SHAPES[#s.SHAPES]
    local n      = shape.points
    local step   = shape.step
    local r      = s.STAR_LINE_LEN / (2.0 * math.sin(math.pi * step / n))
    local a1     = shape.rot + (idx - 1) * (2.0 * math.pi / n)
    local a2     = a1 + step * (2.0 * math.pi / n)
    local x1, y1 = math.cos(a1) * r, math.sin(a1) * r
    local x2, y2 = math.cos(a2) * r, math.sin(a2) * r
    local h      = math.atan(y2 - y1, x2 - x1)
    local off    = shape.lineOff or s.STAR_LINE_OFF
    local shift  = shape.lineShift or 0.0
    return (x1 + x2) * 0.5 + math.cos(h + math.pi * 0.5) * off - math.cos(h) * shift,
           (y1 + y2) * 0.5 + math.sin(h + math.pi * 0.5) * off - math.sin(h) * shift,
           h
end

function louderRadio.audit(ped, now)
    local s = louderRadio
    if now < s.nextAuditAt then return end
    s.nextAuditAt = now + s.AUDIT_INTERVAL_MS

    local box     = louderRadio.modelBox()
    local pp      = ENTITY.GET_ENTITY_COORDS(ped, true)
    local groundZ = pp.z - ENTITY.GET_ENTITY_HEIGHT_ABOVE_GROUND(ped)

    local mine, unattached, nose, noseIdx = {}, 0, nil, 0
    for idx, bus in ipairs(s.buses) do
        mine[bus.handle] = true
        if not Natives.InvokeBool(IS_ENTITY_ATTACHED_TO_ENTITY, bus.handle, ped) then
            unattached = unattached + 1
        end
        if box then
            local top = ENTITY.GET_ENTITY_COORDS(bus.handle, false).z + box.maxy - groundZ
            if not nose or top > nose then nose, noseIdx = top, idx end
        end
    end
    if radioCtl.plBus then
        for _, st in pairs(radioCtl.plBus) do
            if st.handle and st.handle ~= 0 then mine[st.handle] = true end
        end
    end

    local extra, ours, nearest, nearAttached = 0, 0, nil, false
    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        local veh = PoolMgr.GetVehicle(i)
        if veh and veh > 0 and not mine[veh]
            and Natives.InvokeInt(GET_ENTITY_MODEL, veh) == s.MODEL then
            extra = extra + 1
            if s.everSpawned[veh] then ours = ours + 1 end
            local vp = ENTITY.GET_ENTITY_COORDS(veh, false)
            local dx, dy, dz = vp.x - pp.x, vp.y - pp.y, vp.z - pp.z
            local d = math.sqrt(dx * dx + dy * dy + dz * dz)
            if not nearest or d < nearest then
                nearest      = d
                nearAttached = Natives.InvokeBool(IS_ENTITY_ATTACHED_TO_ENTITY, veh, ped)
            end
        end
    end

    local dying = 0
    for _ in pairs(s.dying) do dying = dying + 1 end

    logf("[LouderRadio][audit] buses=%d unattached=%d nose=%s untracked=%d ours=%d%s dying=%d",
        #s.buses, unattached,
        nose and string.format("%+.2f(#%d)", nose, noseIdx) or "n/a",
        extra, ours,
        nearest and string.format(" nearest=%.1fm attachedToMe=%s", nearest, tostring(nearAttached)) or "",
        dying)
end

function louderRadio.markAllForRemoval()
    local n = UnloadReap.markAll(louderRadio.buses, "LouderRadio")
    return n + UnloadReap.markAll(louderRadio.holds, "LouderRadio holds")
end

function louderRadio.unloadCleanup()
    louderRadio.setStopPatch(false)
    louderRadio.setWheelPatch(false)
end

function louderRadio.logOffBlip(resolvedTo)
    local s = louderRadio
    if not s.offCandidateSince then return end
    local dur = Time.GetEpocheMs() - s.offCandidateSince
    if dur > s.maxOffBlipMs then s.maxOffBlipMs = dur end
    local d = FeatureMgr.GetFeature(H.LOUDER_RADIO_AUDIT)
    if d and d:IsToggled() then
        logf("[LouderRadio][off] 255 blip=%dms (max=%dms) believedOff=%s inVeh=%s -> %s",
            dur, s.maxOffBlipMs, tostring(s.station == "OFF"),
            tostring(louderRadio.playerRealVehicle() ~= 0), tostring(resolvedTo))
    end
end

function louderRadio.currentStation()
    local s = louderRadio
    local name = Natives.InvokeString(GET_PLAYER_RADIO_STATION_NAME)
    local idx = Natives.InvokeInt(GET_PLAYER_RADIO_STATION_INDEX)
    if name and name ~= "" and name ~= "OFF" then
        louderRadio.logOffBlip(name)
        s.offCandidateSince = nil
        if s.station == nil or s.station == "OFF" then
            s.station = name
            s.pendingStation = nil
        elseif name == s.station then
            s.pendingStation = nil
        elseif name ~= s.pendingStation then
            s.pendingStation = name
            s.pendingSince = Time.GetEpocheMs()
        elseif Time.GetEpocheMs() - s.pendingSince >= s.STATION_SETTLE_MS then
            s.holdWanted = s.station
            s.station = name
            s.pendingStation = nil
        end
    elseif idx == 255 or idx == -1 then
        if louderRadio.playerRealVehicle() ~= 0 or louderRadio.isOnFootRadioActive() then
            local now = Time.GetEpocheMs()
            s.offCandidateSince = s.offCandidateSince or now
            if now - s.offCandidateSince >= s.OFF_DEBOUNCE_MS then
                s.station = "OFF"
                s.pendingStation = nil
            end
        else
            s.offCandidateSince = nil
        end
    else
        louderRadio.logOffBlip("idx=" .. tostring(idx))
        s.offCandidateSince = nil
    end
    louderRadio.holdTick(Time.GetEpocheMs())
    return s.station
end

function louderRadio.setFrontendRadio(active)
    Natives.InvokeVoid(SET_FRONTEND_RADIO_ACTIVE, active)
    louderRadio.frontendOff = not active
end

function louderRadio.liveSpeakers()
    local n = 0
    for _, b in ipairs(louderRadio.buses) do
        if b.station then n = n + 1 end
    end
    return n
end

function louderRadio.syncFrontendToRig()
    local s = louderRadio
    if louderRadio.liveSpeakers() > 0 then
        s.rigSilentSince = nil
        louderRadio.setFrontendRadio(false)
        return
    end
    local now = Time.GetEpocheMs()
    if not s.rigSilentSince then s.rigSilentSince = now end
    if s.frontendOff and not s.transportPaused and now - s.rigSilentSince >= s.EMPTY_GRACE_MS then
        logf("[LouderRadio] no speakers up for %dms; handing the stock radio back until one spawns",
            now - s.rigSilentSince)
        louderRadio.setFrontendRadio(true)
    end
end

function louderRadio.setMobileRadio(on)
    Natives.InvokeVoid(SET_AUDIO_FLAG, "MobileRadioInGame", on and true or false)
    if not on then Natives.InvokeVoid(SET_MOBILE_PHONE_RADIO_STATE, false) end
    louderRadio.mobileOn = on
end

function louderRadio.isOnFootRadioActive()
    local master = FeatureMgr.GetFeature(H.LOUDER_RADIO)
    local f = FeatureMgr.GetFeature(H.LOUDER_RADIO_ONFOOT)
    return master and master:IsToggled() and f and f:IsToggled() or false
end

function louderRadio.renderOptions()
    local master = FeatureMgr.GetFeature(H.LOUDER_RADIO)
    local enabled = master and master:IsToggled()
    for _, option in ipairs({
        { H.LOUDER_RADIO_ONFOOT, "On Foot Radio" },
        { H.LOUDER_RADIO_SHOW, "Show Speakers" },
    }) do
        if enabled then
            ClickGUI.RenderFeature(option[1])
        else
            local f = FeatureMgr.GetFeature(option[1])
            local shade = f and f:IsToggled() and 110 or 55
            local size = ImGui.GetFrameHeight()
            local x, y = ImGui.GetCursorScreenPos()
            local inset = size * 0.15
            ImGui.AddRectFilled(x, y, x + size, y + size,
                20, 20, 20, 255, size * 0.35, 0)
            ImGui.AddRectFilled(x + inset, y + inset,
                x + size - inset, y + size - inset,
                shade, shade, shade, 255, size * 0.25, 0)
            ImGui.AlignTextToFramePadding()
            ImGui.Dummy(size, size)
            ImGui.SameLine()
            ImGui.TextDisabled(T(option[2]))
            if ImGui.IsItemHovered() then
                ImGui.SetTooltip(T("Requires Louder Radio. Enable it above to use these options."))
            end
        end
    end
    if not enabled then ImGui.TextDisabled(T("Requires Louder Radio")) end
end

function louderRadio.ensureAudioMode()
    louderRadio.syncFrontendToRig()
    if louderRadio.isOnFootRadioActive() then
        louderRadio.setMobileRadio(true)
    elseif louderRadio.mobileOn then
        louderRadio.setMobileRadio(false)
    end
end

function louderRadio.syncStationOnTransition(inVehicle, veh)
    local s = louderRadio
    if s.wasInVehicle == nil then s.wasInVehicle = inVehicle return end
    if inVehicle == s.wasInVehicle then return end
    s.wasInVehicle = inVehicle
    local st = s.station
    if not st or st == "OFF" then return end
    if inVehicle then
        if veh and veh ~= 0 then Natives.InvokeVoid(SET_VEH_RADIO_STATION, veh, st) end
    elseif louderRadio.isOnFootRadioActive() then
        Natives.InvokeVoid(SET_RADIO_TO_STATION_NAME, st)
    end
end

function louderRadio.revertAudioFlags()
    local s = louderRadio
    if s.frontendOff then louderRadio.setFrontendRadio(true) end
    if s.mobileOn then louderRadio.setMobileRadio(false) end
end

local RADIO_WHEEL_INPUTS = { 85, 332, 333 }

function louderRadio.wheelHelperOnTick()
    local s = louderRadio
    if ShouldUnload() and not scriptUnloading then
        louderRadio.revertAudioFlags()
        if #s.buses > 0 then louderRadio.deleteAll() end
        louderRadio.retryDying()
    end

    local lr = FeatureMgr.GetFeature(H.LOUDER_RADIO)
    if not (lr and lr:IsToggled()) then return end

    local dbg = FeatureMgr.GetFeature(H.LOUDER_RADIO_SHOW)
    local busVis = dbg and dbg:IsToggled() or false
    s.frameNo = (s.frameNo or 0) + 1
    for _, bus in ipairs(s.buses) do
        if not bus.goneFrame and not ENTITY.DOES_ENTITY_EXIST(bus.handle) then
            bus.goneFrame, bus.goneMs = s.frameNo, Time.GetEpocheMs()
        else
            Natives.InvokeVoid(SET_ENTITY_VISIBLE, bus.handle, busVis, false)
        end
    end

    local veh = louderRadio.playerRealVehicle()

    if veh ~= 0 then return end
    if not louderRadio.isOnFootRadioActive() then return end
    if not Natives.InvokeBool(louderRadio.N_CHAT_TYPING) then
        for _, c in ipairs(RADIO_WHEEL_INPUTS) do
            Natives.InvokeVoid(ENABLE_CONTROL_ACTION, 0, c, true)
        end
    end
end

function louderRadio.tick()
    local s = louderRadio
    local feat = FeatureMgr.GetFeature(H.LOUDER_RADIO)

    if not s.didInit and isPlayerReady() then
        s.didInit = true
        if not (feat and feat:IsToggled()) then
            Natives.InvokeVoid(SET_FRONTEND_RADIO_ACTIVE, true)
            Natives.InvokeVoid(SET_MOBILE_PHONE_RADIO_STATE, false)
            Natives.InvokeVoid(SET_AUDIO_FLAG, "MobileRadioInGame", false)
            s.frontendOff, s.mobileOn = false, false
        end
    end

    if isPlayerReady() then louderRadio.retryDying() end

    local nowInSession = louderRadio.inSession()
    if s.wasInSession == nil then
        s.wasInSession = nowInSession
    elseif s.wasInSession and not nowInSession then
        s.wasInSession = false
        logf("[LouderRadio] session ended with %d bus(es) up", #s.buses)
        if #s.buses > 0 then louderRadio.disarmForExit("session ended", false) end
    elseif nowInSession and not s.wasInSession then
        s.wasInSession = true
    end

    if s.sessionChanged then
        s.sessionChanged = false
        s.arriveSweepUntil = Time.GetEpocheMs() + s.ARRIVE_SWEEP_MS
        s.nextArriveSweepAt = 0
        logf("[LouderRadio] session change: dropping %d tracked bus(es), sweeping for %.0fs",
            #s.buses, s.ARRIVE_SWEEP_MS / 1000)
        if #s.buses > 0 then louderRadio.deleteAll() end
    end
    if s.arriveSweepUntil > 0 and isPlayerReady() then
        local now = Time.GetEpocheMs()
        if now >= s.arriveSweepUntil then
            s.arriveSweepUntil = 0
        elseif now >= s.nextArriveSweepAt then
            s.nextArriveSweepAt = now + s.ARRIVE_SWEEP_EVERY
            louderRadio.sweepOrphans()
        end
    end

    if not (feat and feat:IsToggled()) then
        if s.wasOn then
            s.wasOn = false
            s.shortfallSince = nil
            s.shortfallToasted = false
            s.lastSpawnFail = nil
            s.rigSilentSince = nil
            if s.transportPaused then
                if s.mobileOn then louderRadio.setMobileRadio(false) end
            else
                louderRadio.revertAudioFlags()
            end
            louderRadio.setStopPatch(false)
            louderRadio.setWheelPatch(false)
            if louderRadio.playerRealVehicle() == 0 then
                Natives.InvokeVoid(SET_RADIO_TO_STATION_NAME, "OFF")
            end
        end
        if #s.buses > 0 then louderRadio.deleteAll() end
        return 250
    end
    if louderRadio.inTransition() or not isPlayerReady() or not nowInSession
        or (rejoin and rejoin.running) then
        if #s.buses > 0 then louderRadio.deleteAll() end
        s.wasInVehicle = nil
        louderRadio.syncFrontendToRig()
        return 250
    end

    if not s.wasOn then
        louderRadio.sweepOrphans()
        s.wasInVehicle = nil
        s.wasOnFootRadio = false
    end
    s.wasOn = true
    louderRadio.ensureAudioMode()
    if s.transportPaused then
        if not s.rigMuted then
            s.rigMuted = true
            if s.station and s.station ~= "OFF" then
                louderRadio.startHold(s.station, Time.GetEpocheMs())
            end
            for _, b in ipairs(s.buses) do
                if ENTITY.DOES_ENTITY_EXIST(b.handle) then
                    Natives.InvokeVoid(SET_VEHICLE_RADIO_ENABLED, b.handle, false)
                    louderRadio.parkBus(b.handle, true)
                end
            end
        end
        return 50
    end
    if s.rigMuted then
        s.rigMuted = false
        for _, b in ipairs(s.buses) do
            if ENTITY.DOES_ENTITY_EXIST(b.handle) then
                louderRadio.parkBus(b.handle, false)
                Natives.InvokeVoid(SET_VEHICLE_RADIO_ENABLED, b.handle, true)
                if b.station then louderRadio.tuneBus(b.handle, b.station) end
            end
        end
    end
    if louderRadio.resolveStopPatch() then louderRadio.setStopPatch(true) end
    if louderRadio.isOnFootRadioActive() then
        if louderRadio.resolveWheelPatch() then louderRadio.setWheelPatch(true) end
    else
        louderRadio.setWheelPatch(false)
    end

    STREAMING.REQUEST_MODEL(s.MODEL)
    if not STREAMING.HAS_MODEL_LOADED(s.MODEL) then return 50 end

    local volFeat = FeatureMgr.GetFeature(H.LOUDER_RADIO_VOL)
    local desired = volFeat and volFeat:GetIntValue() or 1
    if desired < 1 then desired = 1 elseif desired > s.MAX_BUSES then desired = s.MAX_BUSES end
    local requestedDesired = desired

    local showFeat = FeatureMgr.GetFeature(H.LOUDER_RADIO_SHOW)
    local debug    = showFeat and showFeat:IsToggled() or false
    local audFeat  = FeatureMgr.GetFeature(H.LOUDER_RADIO_AUDIT)
    local zOff     = s.Z_OFFSET

    local ped = PLAYER.PLAYER_PED_ID()
    local pos = ENTITY.GET_ENTITY_COORDS(ped, true)
    local now = Time.GetEpocheMs()


    local veh = louderRadio.playerRealVehicle()
    louderRadio.syncStationOnTransition(veh ~= 0, veh)
    local station = louderRadio.currentStation()
    local onFootRadio = louderRadio.isOnFootRadioActive()
    if onFootRadio and not s.wasOnFootRadio and veh == 0 then
        if station and station ~= "OFF" then
            Natives.InvokeVoid(SET_RADIO_TO_STATION_NAME, station)
            s.wasOnFootRadio = true
            logf("[LouderRadio] on-foot host tuned to %s", station)
        end
    else
        s.wasOnFootRadio = onFootRadio
    end
    local busTarget = s.pendingStation and "OFF" or station
    if veh == 0 and not onFootRadio then
        busTarget = "OFF"
    end
    local parked = station == nil or station == "OFF" or (veh == 0 and not onFootRadio)

    local i, lostThisPass, lostGone, lostDead, lostControl, lostReplaced = 1, 0, 0, 0, 0, 0
    while i <= #s.buses do
        local bus = s.buses[i]
        local h = bus.handle
        local why
        if not ENTITY.DOES_ENTITY_EXIST(h) then
            why = "gone"
            if bus.netId and Natives.InvokeBool(0x38CE16C96BD11344, bus.netId) then
                local other = Natives.InvokeInt(0xCE4E5D9B0A4FF560, bus.netId)
                if not s.everSpawned[other] then
                    why = "replaced"
                    s.lossReplacedId = bus.netId
                    s.lossReplacedModel = other ~= 0 and Natives.InvokeInt(GET_ENTITY_MODEL, other) or 0
                end
            end
        elseif Natives.InvokeBool(IS_ENTITY_DEAD, h, false) then
            why = "dead"
        elseif NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(h)
            and not NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(h) then
            why = "control"
        end
        if why then
            lostThisPass = lostThisPass + 1
            local life = (bus.goneMs or now) - (bus.bornAt or now)
            if not s.lossLifeMin or life < s.lossLifeMin then s.lossLifeMin = life end
            if not s.lossLifeMax or life > s.lossLifeMax then s.lossLifeMax = life end
            if bus.goneFrame then
                local fr = bus.goneFrame - (bus.bornFrame or bus.goneFrame)
                if not s.lossFrMin or fr < s.lossFrMin then s.lossFrMin = fr end
                if not s.lossFrMax or fr > s.lossFrMax then s.lossFrMax = fr end
            end
            if VIBESCRIPT_VERBOSE == true and why == "gone" and bus.addr and not s.lossStale then
                s.lossStale = "address free"
                for k = 0, PoolMgr.GetMaxVehicleCount() - 1 do
                    local cv = PoolMgr.GetCVehicle(k)
                    if cv and cv:GetAddress() == bus.addr then
                        local h2 = GTA.PointerToHandle(cv)
                        if h2 and h2 ~= 0 and not s.everSpawned[h2] then
                            s.lossStale = string.format("address still in pool as handle %d model %08X attachedToMe=%s",
                                h2, Natives.InvokeInt(GET_ENTITY_MODEL, h2) & 0xFFFFFFFF,
                                tostring(Natives.InvokeBool(IS_ENTITY_ATTACHED_TO_ENTITY, h2, ped)))
                        else
                            s.lossStale = "address reused by a newer bus of ours"
                        end
                        break
                    end
                end
            end
            if why == "gone" then lostGone = lostGone + 1
            elseif why == "replaced" then lostReplaced = lostReplaced + 1
            elseif why == "dead" then lostDead = lostDead + 1
            else lostControl = lostControl + 1 end
            louderRadio.deleteBus(h)
            table.remove(s.buses, i)
        else
            i = i + 1
        end
    end

    if lostThisPass > 0 then
        s.lossGone = (s.lossGone or 0) + lostGone
        s.lossDead = (s.lossDead or 0) + lostDead
        s.lossControl = (s.lossControl or 0) + lostControl
        s.lossReplaced = (s.lossReplaced or 0) + lostReplaced
    end
    if (s.lossGone or 0) + (s.lossDead or 0) + (s.lossControl or 0) + (s.lossReplaced or 0) > 0
        and now >= (s.nextLossLogAt or 0) then
        s.nextLossLogAt = now + 2000
        if VIBESCRIPT_VERBOSE == true then
            VIBE_LOG_ERROR(string.format(
                "[LouderRadio] speakers lost: %d gone, %d replaced by another player's object on the same net ID (last id=%d model=%08X), %d dead, %d taken over by another player; lived %d-%dms (%d-%d frames); first gone bus: %s; rebuilding (%d up, netVehicles=%d/%d); nearest players: %s",
                s.lossGone or 0, s.lossReplaced or 0, s.lossReplacedId or -1,
                (s.lossReplacedModel or 0) & 0xFFFFFFFF, s.lossDead or 0, s.lossControl or 0,
                s.lossLifeMin or -1, s.lossLifeMax or -1, s.lossFrMin or -1, s.lossFrMax or -1,
                s.lossStale or "n/a", #s.buses,
                louderRadio.netVehicleCount(), NETWORK.GET_MAX_NUM_NETWORK_VEHICLES(),
                louderRadio.nearestPlayers(pos)))
        end
        s.lossGone, s.lossDead, s.lossControl, s.lossReplaced = 0, 0, 0, 0
        s.lossLifeMin, s.lossLifeMax, s.lossFrMin, s.lossFrMax, s.lossStale = nil, nil, nil, nil, nil
    end

    while #s.buses > desired do
        louderRadio.deleteBus(table.remove(s.buses).handle)
    end

    if audFeat and audFeat:IsToggled() then louderRadio.audit(ped, now) end
    local reassert = now >= s.nextAssertAt
    if reassert then s.nextAssertAt = now + s.ASSERT_INTERVAL_MS end
    local retune = now >= s.nextRetuneAt
    if retune then s.nextRetuneAt = now + s.RETUNE_INTERVAL_MS end

    for idx, bus in ipairs(s.buses) do
        if bus.zOff ~= zOff or bus.count ~= desired
            or not Natives.InvokeBool(IS_ENTITY_ATTACHED_TO_ENTITY, bus.handle, ped) then
            louderRadio.attachBus(bus.handle, idx, ped, zOff, desired)
            bus.zOff = zOff
            bus.count = desired
        end
        if reassert and busTarget ~= "OFF" then louderRadio.configure(bus.handle, debug) end

        if busTarget and busTarget ~= "OFF" then
            Natives.InvokeVoid(SET_VEH_FORCED_RADIO_THIS_FRAME, bus.handle)
            if not Natives.InvokeBool(GET_IS_VEHICLE_ENGINE_RUNNING, bus.handle) then
                louderRadio.parkBus(bus.handle, false)
            end
        elseif parked then
            if Natives.InvokeBool(GET_IS_VEHICLE_ENGINE_RUNNING, bus.handle) then
                louderRadio.parkBus(bus.handle, true)
            end
        end

        if busTarget and (retune or busTarget == "OFF" or bus.station ~= busTarget) then
            louderRadio.tuneBus(bus.handle, busTarget)
            bus.station = busTarget
        end
    end

    if not s.axesLogged and s.buses[1] and now - s.buses[1].bornAt > 500 then
        local _, _, h = louderRadio.starChord(1, s.buses[1].count)
        louderRadio.logBusAxes(s.buses[1].handle, h)
    end

    louderRadio.reannounceHidden(now, not debug)

    if #s.buses < desired and now >= s.nextSpawnAt then
        for _ = 1, s.SPAWN_PER_PASS do
            if #s.buses >= desired then break end
            local born = louderRadio.spawnBus(pos, busTarget, ped, zOff, debug, desired)
            if not born then
                s.nextSpawnAt = now + s.RESPAWN_COOLDOWN_MS
                break
            end
            if parked then louderRadio.parkBus(born, true) end
        end
    end

    local radioNeedsSpeakers = busTarget and busTarget ~= "OFF" and requestedDesired > 0
    if radioNeedsSpeakers and #s.buses < requestedDesired then
        if not s.shortfallSince then s.shortfallSince = now end
        if not s.shortfallToasted and now - s.shortfallSince >= 5000 then
            s.shortfallToasted = true
            GUI.AddToast("VibeScript",
                T("Louder Radio is struggling to spawn all requested speakers. Clearing the area may help."),
                10000)
        end
    else
        if s.shortfallToasted and #s.buses >= requestedDesired then
            GUI.AddToast("VibeScript", T("Louder Radio: Spawned all requested speakers"), 5000)
        end
        s.shortfallSince = nil
        s.shortfallToasted = false
    end

    return s.PASS_INTERVAL_MS
end

Script.RegisterLooped(function()
    if scriptUnloading then
        if louderRadio.stopPatch.applied then louderRadio.setStopPatch(false) end
        if louderRadio.wheelPatch.applied then louderRadio.setWheelPatch(false) end
        Script.Yield(100)
        return
    end
    if ShouldUnload() then
        louderRadio.revertAudioFlags()
        if louderRadio.stopPatch.applied then louderRadio.setStopPatch(false) end
        if louderRadio.wheelPatch.applied then louderRadio.setWheelPatch(false) end
        if #louderRadio.buses > 0 then louderRadio.deleteAll() end
        Script.Yield(100)
        return
    end

    local ok, wait = pcall(louderRadio.tick)
    if not ok then
        logErr("[LouderRadio] " .. tostring(wait))
        wait = 500
    end
    Script.Yield(wait or louderRadio.PASS_INTERVAL_MS)
end)

FeatureMgr.AddFeature(H.LOUDER_RADIO, "Louder Radio", eFeatureType.Toggle,
    "Blasts your radio to you and other players. Small delay between station changes.")
    :SetSaveable(false)

FeatureMgr.AddFeature(H.LOUDER_RADIO_VOL, "Volume", eFeatureType.SliderInt,
    "Number of party buses (speakers). Max of 8 due to game limitations.")
    :SetLimitValues(1, louderRadio.SLIDER_MAX)
    :SetDefaultValue(5)
    :Reset()
    :SetSaveable(false)

FeatureMgr.AddFeature(H.LOUDER_RADIO_ONFOOT, "On Foot Radio", eFeatureType.Toggle,
    "Use the Louder Radio on foot. Allows you to use the radio wheel selector while not in a vehicle.")
    :SetSaveable(false)

FeatureMgr.AddFeature(H.LOUDER_RADIO_SHOW, "Show Speakers", eFeatureType.Toggle,
    "Renders the party buses instead of hiding them. Everyone in the session sees them, not just you.")
    :SetSaveable(false)

centralOnTick(FeatureMgr.AddFeature(H.LOUDER_RADIO_WHEEL, "##LouderRadioWheelHelper",
    eFeatureType.Toggle, "", louderRadio.wheelHelperOnTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
FeatureMgr.GetFeature(H.LOUDER_RADIO_WHEEL):Toggle()

end)()


;(function()

local iv = function(h, ...) return Natives.InvokeVoid(h, ...) end
local ii = function(h, ...) return Natives.InvokeInt(h, ...) end
local is = function(h, ...) return Natives.InvokeString(h, ...) end
local ib = function(h, ...) return Natives.InvokeBool(h, ...) end

local HASH = {
    NUM_STATIONS   = 0xF1620ECB50E01DE7,
    STATION_NAME   = 0xB28ECA15046CA8B9,
