aimRestrict = {
    hash         = H.AIM_RESTRICT,
    OFF_WPN_MGR  = 0x10B8,
    OFF_EQUIPPED = 0x68,
    OFF_AIM_INFO = 0x68,
    AI_HEADING   = 0x04,
    AI_MIN       = 0x08,
    AI_MAX       = 0x0C,
    PITCH_MIN    = -89.0,
    PITCH_MAX    = 89.0,
    CAM_LIMITS   = 0xA516C198B7DCA1E1,
    FREE_AIMING  = 0x2E397FD2ECD37C87,
    DOING_DRIVEBY = 0xB2C086CC1BF8F2BF,
    GLIDE_RATE   = 35.0,
    GLIDE_MIN_MS = 600,
    GLIDE_WAIT_MS = 300,
    GLIDE_PAD    = 10.0,
    patched      = {},

    RESOLVE_TRIES = 60,
    tries         = 0,
    patchOn       = false,

    DIRECTOR = {
        leg = { pat = "48 89 5C 24 10 57 48 83 EC 20 48 8B 05 ? ? ? ? F3 0F 10 81 48 04 00 00 F3 0F 10 89 4C 04 00 00 48 8B FA 48 8B D9 80 B8 FD 06 00 00 00 0F 84", rip = 13 },
        enh = { pat = "48 8B 05 ? ? ? ? 80 B8 FD 06 00 00 00 74 ? F2 0F 10 B0 E8 06 00 00 48 8B 87 30 02 00 00 80 78 3C 00", rip = 3 },
    },
    OFF_ACTIVE_CAM = 0x3C0,
    OFF_PITCH_LIM  = 0x448,
    dirTries       = 0,

    PATCH = {
        leg = {
            pat     = "4C 8D A6 F0 0E 00 00 49 8B CC E8 ? ? ? ? A8 04 75 ? 4C 8D A6 F0 0E 00 00 49 8B CC E8 ? ? ? ? A8 10 0F 84",
            patched = "4C 8D A6 F0 0E 00 00 49 8B CC E8 ? ? ? ? A8 00 75 ? 4C 8D A6 F0 0E 00 00 49 8B CC E8 ? ? ? ? A8 00 0F 84",
            edits   = { { 16, 0x04, 0x00 }, { 35, 0x10, 0x00 } },
        },
        enh = {
            pat     = "48 8D 8E F0 0E 00 00 E8 ? ? ? ? A8 04 75 ? 48 8D 8E F0 0E 00 00 E8 ? ? ? ? A8 10 0F 84",
            patched = "48 8D 8E F0 0E 00 00 E8 ? ? ? ? A8 00 75 ? 48 8D 8E F0 0E 00 00 E8 ? ? ? ? A8 00 0F 84",
            edits   = { { 13, 0x04, 0x00 }, { 29, 0x10, 0x00 } },
        },
    },
}

aimRestrict.ptr = function(addr)
    if not addr or addr <= 0 or addr >= 0x800000000000 then return nil end
    local v = Memory.ReadLong(addr)
    if v <= 0 or v >= 0x800000000000 then return nil end
    return v
end

function aimRestrict.aimingInfo()
    local s = aimRestrict
    local cped = GTA.GetLocalPed()
    if not cped then return nil end
    local pedAddr = cped:GetAddress()
    if not pedAddr or pedAddr == 0 then return nil end

    local mgr = s.ptr(pedAddr + s.OFF_WPN_MGR)
    if not mgr then return nil end
    local cwi = s.ptr(mgr + s.OFF_EQUIPPED)
    if not cwi then return nil end
    local ai = s.ptr(cwi + s.OFF_AIM_INFO)
    if not ai then return nil end

    if Memory.ReadUInt(ai) == 0 then return nil end
    local heading = Memory.ReadFloat(ai + s.AI_HEADING)
    local pmin    = Memory.ReadFloat(ai + s.AI_MIN)
    local pmax    = Memory.ReadFloat(ai + s.AI_MAX)
    if not heading or not pmin or not pmax then return nil end
    if heading < 0.0 or heading > 180.0 then return nil end
    if pmin < -90.0 or pmin > 0.0 then return nil end
    if pmax < 0.0 or pmax > 90.0 then return nil end
    if pmin >= pmax then return nil end
    return ai, pmin, pmax
end

function aimRestrict.apply()
    local s = aimRestrict
    local ai, pmin, pmax = s.aimingInfo()
    if not ai then
        if not s.warnedMiss then
            s.warnedMiss = true
            VIBE_LOG_ERROR("[AimRestrict] no CAimingInfo for the held weapon (offset moved?)")
        end
        return
    end

    if pmin == s.PITCH_MIN and pmax == s.PITCH_MAX then
        if s.patched[ai] == nil then s.patched[ai] = false end
        return
    end
    if type(s.patched[ai]) ~= "table" then
        s.patched[ai] = { min = pmin, max = pmax }
    end
    Memory.WriteFloat(ai + s.AI_MIN, s.PITCH_MIN)
    Memory.WriteFloat(ai + s.AI_MAX, s.PITCH_MAX)
end

function aimRestrict.resolve()
    local s = aimRestrict
    if s.site ~= nil then return s.site end

    local spec = s.PATCH[IS_ENHANCED and "enh" or "leg"]
    local hit, stale = Memory.Scan(spec.pat), false
    if not hit or hit == 0 then
        hit, stale = Memory.Scan(spec.patched), true
    end
    if hit and hit ~= 0 then
        local list = {}
        for i = 1, #spec.edits do
            local e = spec.edits[i]
            list[i] = { addr = hit + e[1], orig = e[2], patched = e[3] }
            if stale then Memory.WriteByte(list[i].addr, e[2]) end
        end
        s.site = list
        return list
    end

    s.tries = s.tries + 1
    if s.tries < s.RESOLVE_TRIES then return nil end
    s.site = false
    VIBE_LOG_ERROR("[AimRestrict] firing-vector IK gate not found (game update?)")
    return false
end

function aimRestrict.resolveDirector()
    local s = aimRestrict
    if s.dirGlobal ~= nil then return s.dirGlobal end
    local spec = s.DIRECTOR[IS_ENHANCED and "enh" or "leg"]
    local hit = Memory.Scan(spec.pat)
    if hit and hit ~= 0 then
        s.dirGlobal = Memory.Rip(hit + spec.rip)
        return s.dirGlobal
    end
    s.dirTries = s.dirTries + 1
    if s.dirTries < s.RESOLVE_TRIES then return nil end
    s.dirGlobal = false
    VIBE_LOG_ERROR("[AimRestrict] gameplay director not found (game update?)")
    return false
end

function aimRestrict.activeCam()
    local s = aimRestrict
    local g = s.resolveDirector()
    local dir = g and s.ptr(g)
    return dir and s.ptr(dir + s.OFF_ACTIVE_CAM)
end

function aimRestrict.camLimits(cam)
    local s = aimRestrict
    local lo = Memory.ReadFloat(cam + s.OFF_PITCH_LIM)
    local hi = Memory.ReadFloat(cam + s.OFF_PITCH_LIM + 4)
    if not lo or not hi then return nil end
    if lo < -1.58 or lo > 0.0 or hi < 0.0 or hi > 1.58 or lo >= hi then return nil end
    return math.deg(lo), math.deg(hi)
end

function aimRestrict.setPatch(on)
    local s = aimRestrict
    if on == s.patchOn then return end
    local list = s.resolve()
    if not list then return end
    for i = 1, #list do
        Memory.WriteByte(list[i].addr, on and list[i].patched or list[i].orig)
    end
    s.patchOn = on
end

function aimRestrict.restore()
    local s = aimRestrict
    s.setPatch(false)
    for ai, stock in pairs(s.patched) do
        if type(stock) == "table" then
            Memory.WriteFloat(ai + s.AI_MIN, stock.min)
            Memory.WriteFloat(ai + s.AI_MAX, stock.max)
        end
    end
    s.patched = {}
end

function aimRestrict.onTick(f)
    local s = aimRestrict
    if not f:IsToggled() then
        if next(s.patched) or s.patchOn then s.restore() end
        return
    end

    local pid = GTA.GetLocalPlayerId()
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not ped or ped == 0 then return end
    s.setPatch(true)

    local aiming
    local inVeh = PED.IS_PED_IN_ANY_VEHICLE(ped, false)
    if inVeh then
        aiming = Natives.InvokeBool(s.DOING_DRIVEBY, ped)
            or PAD.IS_DISABLED_CONTROL_PRESSED(0, INPUT.VEH_AIM)
            or PAD.IS_DISABLED_CONTROL_PRESSED(0, INPUT.VEH_ATTACK)
        if aiming and not s.loggedVeh then
            s.loggedVeh = true
        end
    else
        s.apply()
        aiming = Natives.InvokeBool(s.FREE_AIMING, pid)
            or PAD.IS_DISABLED_CONTROL_PRESSED(0, INPUT.AIM)
            or PAD.IS_DISABLED_CONTROL_PRESSED(0, INPUT.ATTACK)
    end

    if aiming then
        Natives.InvokeVoid(s.CAM_LIMITS, s.PITCH_MIN + 0.0, s.PITCH_MAX + 0.0)
        s.lastPitch = inVeh and CAM.GET_GAMEPLAY_CAM_RELATIVE_PITCH() or nil
        s.aimCam = inVeh and s.activeCam() or nil
        s.glide = nil
        return
    end

    local now = MISC.GET_GAME_TIMER()
    if s.lastPitch then
        if inVeh then
            local up = s.lastPitch > 0.0
            s.glide = {
                up    = up,
                from  = up and math.min(s.lastPitch + s.GLIDE_PAD, s.PITCH_MAX)
                             or math.max(s.lastPitch - s.GLIDE_PAD, s.PITCH_MIN),
                start = now,
            }
        end
        s.lastPitch = nil
    end
    local g = s.glide
    if not g then return end
    if not inVeh then
        s.glide = nil
        return
    end

    if not g.ms then
        local cam = s.activeCam()
        local waited = now - g.start
        if cam and (cam ~= s.aimCam or waited >= s.GLIDE_WAIT_MS) then
            local lo, hi = s.camLimits(cam)
            if not lo then
                s.glide = nil
                return
            end
            g.edge = g.up and hi or lo
            if (g.up and g.from <= g.edge) or (not g.up and g.from >= g.edge) then
                s.glide = nil
                return
            end
            g.ms = math.max(s.GLIDE_MIN_MS, math.abs(g.from - g.edge) / s.GLIDE_RATE * 1000.0)
            g.start = now
        elseif not cam and waited >= s.GLIDE_WAIT_MS then
            s.glide = nil
            return
        end
    end

    local edge = g.from
    if g.ms then
        local t = (now - g.start) / g.ms
        if t >= 1.0 then
            s.glide = nil
            return
        end
        t = t * t * (3.0 - 2.0 * t)
        edge = g.from + (g.edge - g.from) * t
    end
    if g.up then
        Natives.InvokeVoid(s.CAM_LIMITS, s.PITCH_MIN + 0.0, edge + 0.0)
    else
        Natives.InvokeVoid(s.CAM_LIMITS, edge + 0.0, s.PITCH_MAX + 0.0)
    end
end

