    local joinWatch = {
        on = false,
        last = nil,
        from = 0,
        to   = 80,
    }
    joinWatch.tick = function(f)
        if not f:IsToggled() then
            if joinWatch.on then
                joinWatch.on = false
                joinWatch.last = nil
                VIBE_LOG_INFO("[VibeScript][JoinWatch] off")
            end
            return
        end
        if not isPlayerReady() then return end
        local localPid = GTA.GetLocalPlayerId()
        if not joinWatch.on then
            joinWatch.on = true
            joinWatch.last = {}
            for off = joinWatch.from, joinWatch.to do
                joinWatch.last[off] = joinCeo.readInt(localPid, off)
            end
            VIBE_LOG_INFO(("[VibeScript][JoinWatch] on, baseline established for ORG ints +%d..+%d (abs +%d..+%d)")
                :format(joinWatch.from, joinWatch.to,
                joinCeo.ORG + joinWatch.from, joinCeo.ORG + joinWatch.to))
            return
        end
        for off = joinWatch.from, joinWatch.to do
            local v = joinCeo.readInt(localPid, off)
            local prev = joinWatch.last[off]
            if v ~= prev then
                VIBE_LOG_INFO(("[VibeScript][JoinWatch] sMag+%d (abs+%d): %s -> %s (0x%08x)")
                    :format(off, joinCeo.ORG + off,
                        tostring(prev), tostring(v),
                        (v or 0) & 0xffffffff))
                joinWatch.last[off] = v
            end
        end
    end
    centralOnTick(FeatureMgr.AddFeature(H.JOIN_CEO_WATCH,
        "Debug: Watch ORG ints", eFeatureType.Toggle,
        "Logs every per-tick change to your own GPBD_FM_3 ORG ints +0..+80.",
        joinWatch.tick))
        :SetSaveable(false)

    FeatureMgr.AddFeature(H.CLEAN_MISSION_STATE,
        "Debug: Force Clean Mission State", eFeatureType.Button,
        "Triggers freemode's own mission-end music events, nukes audio scenes, clears HUD prints/help/brief/floating-help, resets the mission flag, then runs the staged boss-event kill pass immediately (FORCE_CLEANUP each running boss-event script, then terminate anything that ignored it 1.5s later). Only touches known boss-triggered event scripts that are currently running. Use to unstick blips/music/objectives left over from an org event.",
        function(f)
            joinCeo.manualCleanRequested = true
        end)
        :SetSaveable(false)


    centralOnTick(FeatureMgr.AddFeature(playerState.passiveRunnerHash, "##RemovePassiveRunner",
        eFeatureType.Toggle, "", function(f)
            if not f:IsToggled() then return end
            if playerState.stripVehGodJob then
                playerState.stripVehGodStep()
            end
            removeGhost.holdTick()
            if #playerState.passivePending == 0 then
                playerState.passiveBatch = nil
                return
            end
            local pending = playerState.passivePending
            playerState.passivePending = {}
            local sweptOne = false
            for _, req in ipairs(pending) do
                if req.all then
                    playerState.expandPassiveAll()
                elseif req.stripVehGod then
                    playerState.stripVehGodStart(req.pid)
                elseif req.ghost then
                    removeGhost.run(req.pid)
                elseif req.quiet then
                    if sweptOne then
                        playerState.passivePending[#playerState.passivePending + 1] = req
                    else
                        sweptOne = true
                        playerState.passiveBatchDone(
                            lockOntoPlayers.isSessionTarget(req.pid)
                                and removePassiveForPlayer(req.pid, true) or false)
                    end
                else
                    removePassiveForPlayer(req.pid)
                end
            end
        end, true))
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)
    FeatureMgr.GetFeature(playerState.passiveRunnerHash):Toggle()




end



removeGhost = {
    H_IS_ENTITY_A_GHOST       = 0x21D04D7BC538C146,
    H_SET_REMOTE_PLAYER_GHOST = 0xA7C511FA1C5BDA38,

    GUESS_BYTE = 0x1C5,
    GUESS_BIT  = 6,
    SCAN_FROM  = 0x100,
    SCAN_TO    = 0x2A0,

    HOLD_MS = 300000,

    byte = nil, mask = nil,
    hold = {},
}

function removeGhost.isGhost(entity)
    if not entity or entity == 0 then return false end
    return Natives.InvokeBool(removeGhost.H_IS_ENTITY_A_GHOST, entity) and true or false
end

function removeGhost.netObjOf(cent)
    if not cent then return nil end
    local addr = cent:GetAddress()
    if not addr or addr == 0 then return nil end
    return readPtr(addr + lockOntoPlayers.OFF_PED_NET_OBJECT)
end

function removeGhost.netObjOfHandle(handle)
    if not handle or handle == 0 then return nil end
    local ent = GTA.HandleToPointer(handle)
    if not ent then return nil end
    return removeGhost.netObjOf(ent)
end

function removeGhost.clearBit(netObj)
    if not netObj or not removeGhost.byte then return false end
    local addr = netObj + removeGhost.byte
    local v = Memory.ReadUByte(addr)
    if not v or (v & removeGhost.mask) == 0 then return false end
    Memory.WriteByte(addr, v & (~removeGhost.mask & 0xFF))
    return true
end

function removeGhost.proveBit(netObj, ped, off, mask)
    local addr = netObj + off
    local orig = Memory.ReadUByte(addr)
    if not orig then return false end
    Memory.WriteByte(addr, orig | mask)
    local readsOn = removeGhost.isGhost(ped)
    Memory.WriteByte(addr, orig & (~mask & 0xFF))
    local readsOff = removeGhost.isGhost(ped)
    Memory.WriteByte(addr, orig)
    return readsOn and not readsOff
end

function removeGhost.calibrate()
    local cped = GTA.GetLocalPed()
    if not cped then return false, "no local ped" end
    local netObj = removeGhost.netObjOf(cped)
    if not netObj then return false, "no netobj - join a session first" end
    local ped = PLAYER.PLAYER_PED_ID()
    if removeGhost.isGhost(ped) then
        return false, "you are a ghost right now - retry once it drops"
    end

    local lo, hi = removeGhost.SCAN_FROM, removeGhost.SCAN_TO
    local a, b, c = {}, {}, {}
    for off = lo, hi - 1 do a[off] = Memory.ReadUByte(netObj + off) end
    NETWORK.SET_LOCAL_PLAYER_AS_GHOST(true, false)
    local readsOn = removeGhost.isGhost(ped)
    for off = lo, hi - 1 do b[off] = Memory.ReadUByte(netObj + off) end
    NETWORK.SET_LOCAL_PLAYER_AS_GHOST(false, false)
    NETWORK.RESET_GHOST_ALPHA()
    local readsOff = removeGhost.isGhost(ped)
    for off = lo, hi - 1 do c[off] = Memory.ReadUByte(netObj + off) end

    if not readsOn or readsOff then
        return false, ("SET_LOCAL_PLAYER_AS_GHOST did not move IS_ENTITY_A_GHOST (on=%s off=%s)")
            :format(tostring(readsOn), tostring(readsOff))
    end

    local cands = {}
    for off = lo, hi - 1 do
        local only = (b[off] or 0) & ~(a[off] or 0) & ~(c[off] or 0) & 0xFF
        if only ~= 0 then
            for bit = 0, 7 do
                local m = 1 << bit
                if (only & m) ~= 0 then
                    if off == removeGhost.GUESS_BYTE and bit == removeGhost.GUESS_BIT then
                        table.insert(cands, 1, { off = off, mask = m, bit = bit })
                    else
                        cands[#cands + 1] = { off = off, mask = m, bit = bit }
                    end
                end
            end
        end
    end
    if #cands == 0 then
        return false, ("no bit in 0x%X-0x%X tracked the toggle"):format(lo, hi)
    end

    for _, h in ipairs(cands) do
        if removeGhost.proveBit(netObj, ped, h.off, h.mask) then
            removeGhost.byte, removeGhost.mask = h.off, h.mask
            return true, ("m_bGhost at netobj+0x%X bit %d%s"):format(h.off, h.bit,
                (h.off == removeGhost.GUESS_BYTE and h.bit == removeGhost.GUESS_BIT)
                    and " (as predicted)"
                    or (" (predicted 0x%X bit %d)"):format(removeGhost.GUESS_BYTE, removeGhost.GUESS_BIT))
        end
    end
    return false, ("%d candidate bit(s) but none drove IS_ENTITY_A_GHOST"):format(#cands)
end

function removeGhost.clearFor(pid)
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not ped or ped == 0 then return 0, false end

    Natives.InvokeVoid(removeGhost.H_SET_REMOTE_PLAYER_GHOST, pid, false)

    local cped = Players.GetCPed(pid)
    local cleared = removeGhost.clearBit(removeGhost.netObjOf(cped))

    if PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
        if veh and veh ~= 0 and removeGhost.clearBit(removeGhost.netObjOfHandle(veh)) then
            cleared = true
        end
    end
    return ped, cleared
end

function removeGhost.windowLabel()
    local secs = removeGhost.HOLD_MS // 1000
    if secs >= 60 and secs % 60 == 0 then return ("%dm"):format(secs // 60) end
    return ("%ds"):format(secs)
end

function removeGhost.run(pid)
    local name = Players.GetName(pid)
    if not name or name == "" then name = ("Player %d"):format(pid) end

    if not removeGhost.byte then
        local ok, msg = removeGhost.calibrate()
        logf("Remove Ghost: calibration %s - %s", ok and "ok" or "FAILED", msg)
        if not ok then
            GUI.AddToast("VibeScript", T("Remove Ghost Mode: %s"):format(msg), 5000)
            return
        end
    end

    local wasGhost = removeGhost.isGhost(PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid))
    local ped, cleared = removeGhost.clearFor(pid)
    if ped == 0 then
        GUI.AddToast("VibeScript",
            T("%s has no ped here - get closer to them."):format(name), 3000)
        return
    end

    local stillGhost = removeGhost.isGhost(ped)
    logf("Remove Ghost: pid=%d %s wasGhost=%s cleared=%s stillGhost=%s selfGhost=%s hold=%dms",
        pid, name, tostring(wasGhost), tostring(cleared), tostring(stillGhost),
        tostring(removeGhost.isGhost(PLAYER.PLAYER_PED_ID())), removeGhost.HOLD_MS)

    if stillGhost then
        removeGhost.byte, removeGhost.mask = nil, nil
        GUI.AddToast("VibeScript",
            T("%s still reads as a ghost - press again to re-calibrate."):format(name), 5000)
        return
    end

    removeGhost.hold[pid] = MISC.GET_GAME_TIMER() + removeGhost.HOLD_MS
    GUI.AddToast("VibeScript", wasGhost
        and (T("Ghost removed from %s - shoot within %s.")):format(name, removeGhost.windowLabel())
        or (T("%s was not ghosted to you - holding for %s anyway.")):format(name, removeGhost.windowLabel()),
        3000)
end

function removeGhost.holdTick()
    if scriptUnloading then return end
    if not removeGhost.byte or not next(removeGhost.hold) then return end
    local now = MISC.GET_GAME_TIMER()
    for pid, closesAt in pairs(removeGhost.hold) do
        if now >= closesAt or not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
            removeGhost.hold[pid] = nil
        else
            removeGhost.clearFor(pid)
        end
    end
end

EventMgr.RegisterHandler(eLuaEvent.ON_SESSION_CHANGE, function()
    removeGhost.hold = {}
    louderRadio.sessionChanged = true
    radioPl.sessionChanged = true
end)

for _, hash in ipairs(FeatureMgr.AddPlayerFeature(
    H.REMOVE_GHOST, "Remove Ghost Mode", eFeatureType.Button,
