function vehBlock.pickerMask()
    local feat = FeatureMgr.GetFeature(H.VEH_BLOCK_LIST)
    if not feat then return 0 end
    local m = 0
    for i = 0, #vehBlock.NAMES - 1 do
        if feat:IsListIndexToggled(i) then m = m | (1 << i) end
    end
    return m
end

function vehBlock.blockedModels()
    local mask = vehBlock.pickerMask()
    if mask ~= vehBlock.setMask then
        local set = {}
        for i = 1, #vehBlock.NAMES do
            if (mask & (1 << (i - 1))) ~= 0 then
                for _, h in ipairs(vehBlock.HASHES[i]) do set[h] = true end
            end
        end
        vehBlock.modelSet = set
        vehBlock.setMask  = mask
    end
    return vehBlock.modelSet
end

function vehBlock.playerBlipType(pid)
    local v = ScriptGlobal.GetInt(
        vehBlock.GPBD_BASE + 1 + pid * vehBlock.GPBD_STRIDE + vehBlock.GPBD_BLIP_TYPE)
    if type(v) ~= "number" or v < 0 or v > 97 then return nil end
    return math.tointeger(v) or v
end

function vehBlock.remoteSelection(pid)
    local blipType = vehBlock.playerBlipType(pid)
    local groupIndex = blipType and vehBlock.BLIP_GROUP_INDEX[blipType] or nil
    if not groupIndex then return nil end
    if (vehBlock.pickerMask() & (1 << (groupIndex - 1))) == 0 then return nil end
    return blipType, groupIndex, vehBlock.NAMES[groupIndex]
end

function vehBlock.groupSelected(groupName)
    local groupIndex = vehBlock.GROUP_INDEX[groupName]
    return groupIndex ~= nil
        and (vehBlock.pickerMask() & (1 << (groupIndex - 1))) ~= 0
end

function vehBlock.playerHasStampedClone(pid)
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not ped or ped == 0 or not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then return false end
    local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    return veh and veh ~= 0 and ENTITY.DOES_ENTITY_EXIST(veh)
        and vehBlock.held[veh] ~= nil
end

vehBlock.INTERIOR_GROUP = {
    [147] = "Kosatka",
    [81]  = "Mobile Operations Center",
    [88]  = "Avenger",
    [117] = "Terrorbyte",
}

function vehBlock.playerVehicleInterior(pid)
    local groupName = vehBlock.INTERIOR_GROUP[lockOntoPlayers.bdSimpleInterior(pid)]
    if groupName and vehBlock.groupSelected(groupName) then return groupName end
    return nil
end

function vehBlock.queueInteriorKick(pid, groupName, now)
    local last = vehBlock.remoteLastKick[pid] or 0
    if now - last < vehBlock.REMOTE_KICK_MS then return end
    for _, req in ipairs(playerState.kickInteriorPending) do
        if req.vehBlockInterior and req.pid == pid then return end
    end
    vehBlock.remoteLastKick[pid] = now
    playerState.kickInteriorPending[#playerState.kickInteriorPending + 1] = {
        pid = pid,
        quiet = true,
        autoInterior = true,
        vehBlockInterior = true,
    }
end

function vehBlock.queueRemoteKick(pid, blipType, groupName, now)
    local last = vehBlock.remoteLastKick[pid] or 0
    if now - last < vehBlock.REMOTE_KICK_MS or vehBlock.remoteQueued[pid] then return end
    vehBlock.remoteLastKick[pid] = now
    vehBlock.remoteQueued[pid] = true
    vehBlock.remoteQueue[#vehBlock.remoteQueue + 1] = {
        pid = pid, blipType = blipType, groupName = groupName,
    }
end

function vehBlock.dispatchRemoteKick()
    if vehBlock.remoteBusy or #vehBlock.remoteQueue == 0 then return end
    local req = table.remove(vehBlock.remoteQueue, 1)
    vehBlock.remoteQueued[req.pid] = nil

    if not lockOntoPlayers.isSessionTarget(req.pid) then return end
    local blipType, _, groupName = vehBlock.remoteSelection(req.pid)
    if blipType ~= req.blipType or groupName ~= req.groupName
        or vehBlock.playerHasStampedClone(req.pid)
        or vehBlock.playerVehicleInterior(req.pid) then
        return
    end

    vehBlock.remoteBusy = true
    Script.QueueJob(function()
        local parent = FeatureMgr.GetFeature(H.VEH_BLOCK)
        if scriptUnloading or not parent or not parent:IsToggled()
            or not lockOntoPlayers.isSessionTarget(req.pid)
            or vehBlock.playerHasStampedClone(req.pid) then
            vehBlock.remoteBusy = false
            return
        end
        local liveType, _, liveGroup = vehBlock.remoteSelection(req.pid)
        if liveType ~= req.blipType or liveGroup ~= req.groupName then
            vehBlock.remoteBusy = false
            return
        end
        local kick = FeatureMgr.GetFeature(vehBlock.H_VEHICLE_KICK, req.pid)
            or FeatureMgr.GetFeatureByName("Vehicle Kick", req.pid)
        if not kick then
            if not vehBlock.remoteKickMissingLogged then
                vehBlock.remoteKickMissingLogged = true
                VIBE_LOG_ERROR('[BlockVehicles] Cherax built-in "Vehicle Kick" is missing')
            end
            vehBlock.remoteBusy = false
            return
        end
        kick:TriggerCallback()
        vehBlock.remoteBusy = false
    end)
end

function vehBlock.remoteSweep(now)
    for pid = 0, 31 do
        if lockOntoPlayers.isSessionTarget(pid) then
            local interiorGroup = vehBlock.playerVehicleInterior(pid)
            if interiorGroup then
                vehBlock.queueInteriorKick(pid, interiorGroup, now)
            else
                local blipType, _, groupName = vehBlock.remoteSelection(pid)
                if not blipType or vehBlock.playerHasStampedClone(pid) then
                    vehBlock.remoteLastKick[pid] = nil
                else
                    vehBlock.queueRemoteKick(pid, blipType, groupName, now)
                end
            end
        else
            vehBlock.remoteLastKick[pid] = nil
            vehBlock.remoteQueued[pid] = nil
        end
    end
end

function vehBlock.resetRemote()
    vehBlock.remoteLastKick = {}
    vehBlock.remoteQueue = {}
    vehBlock.remoteQueued = {}
    vehBlock.lastRemoteScan = 0
    for i = #playerState.kickInteriorPending, 1, -1 do
        if playerState.kickInteriorPending[i].vehBlockInterior then
            table.remove(playerState.kickInteriorPending, i)
        end
    end
end

function vehBlock.stamp(veh, ped)
    Natives.InvokeVoid(vehBlock.H_SET_EXCLUSIVE_DRIVER, veh, ped or 0, 0)
    if ped and ped ~= 0 then
        Natives.InvokeVoid(vehBlock.H_LOCK_FOR_ALL_PLAYERS, veh, true)
        Natives.InvokeVoid(vehBlock.H_LOCK_FOR_PLAYER, veh, GTA.GetLocalPlayerId(), false)
    else
        Natives.InvokeVoid(vehBlock.H_LOCK_FOR_ALL_PLAYERS, veh, false)
    end
end

function vehBlock.releaseAll()
    for veh in pairs(vehBlock.held) do
        if ENTITY.DOES_ENTITY_EXIST(veh) then vehBlock.stamp(veh, 0) end
    end
    vehBlock.held   = {}
    vehBlock.claims = 0
end

function vehBlock.protectedDrivenVehicles()
    local protected = {}
    local me = GTA.GetLocalPlayerId()
    for pid = 0, 31 do
        if NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid)
            and (pid == me or not lockOntoPlayers.isSessionTarget(pid)) then
            local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
            if ped and ped ~= 0 and PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
                local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
                if veh and veh ~= 0 and ENTITY.DOES_ENTITY_EXIST(veh)
                    and VEHICLE.GET_PED_IN_VEHICLE_SEAT(veh, -1, false) == ped then
                    protected[veh] = true
                end
            end
        end
    end
    return protected
end

function vehBlock.releaseLocalDrivenVehicle()
    local me = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
    if not me or me == 0 or not PED.IS_PED_IN_ANY_VEHICLE(me, false) then return end
    local veh = PED.GET_VEHICLE_PED_IS_IN(me, false)
    if not veh or veh == 0 or not vehBlock.held[veh]
        or VEHICLE.GET_PED_IN_VEHICLE_SEAT(veh, -1, false) ~= me then return end
    vehBlock.stamp(veh, 0)
    vehBlock.held[veh] = nil
end

function vehBlock.sweep(now)
    local blocked = vehBlock.blockedModels()
    local me = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
    if not me or me == 0 then return end
    local protected = vehBlock.protectedDrivenVehicles()

    for veh, st in pairs(vehBlock.held) do
        local gone = not ENTITY.DOES_ENTITY_EXIST(veh)
        if gone or protected[veh] or not blocked[st.model]
            or (Natives.InvokeInt(vehBlock.H_GET_ENTITY_MODEL, veh) & 0xFFFFFFFF) ~= st.model then
            if not gone then vehBlock.stamp(veh, 0) end
            vehBlock.held[veh] = nil
        end
    end

    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        local veh = PoolMgr.GetVehicle(i)
        if veh and veh > 0 then
            local model = Natives.InvokeInt(vehBlock.H_GET_ENTITY_MODEL, veh) & 0xFFFFFFFF
            if blocked[model] and not protected[veh] then
                local st = vehBlock.held[veh]
                if not st then
                    vehBlock.stamp(veh, me)
                    vehBlock.held[veh] = { model = model, lastMs = now }
                    vehBlock.claims = vehBlock.claims + 1
                elseif now - st.lastMs >= vehBlock.REASSERT_MS then
                    vehBlock.stamp(veh, me)
                    st.lastMs = now
                end
            end
        end
    end
end

function vehBlock.onTick(f)
    local toggled = f:IsToggled()
    telemetryCountToggleEdge("BlockVehicles", 0, toggled)
    if scriptUnloading then return end
    if not toggled then
        if next(vehBlock.held) then vehBlock.releaseAll() end
        if next(vehBlock.remoteLastKick) or #vehBlock.remoteQueue > 0 then
            vehBlock.resetRemote()
        end
        return
    end
    if not isPlayerReady() then return end
    local now = Time.GetEpocheMs()

    vehBlock.releaseLocalDrivenVehicle()

    vehBlock.dispatchRemoteKick()

    if now - vehBlock.lastSweep >= vehBlock.SWEEP_MS then
        vehBlock.lastSweep = now
        vehBlock.sweep(now)
    end

    if now - vehBlock.lastRemoteScan >= vehBlock.REMOTE_SCAN_MS then
        vehBlock.lastRemoteScan = now
        vehBlock.remoteSweep(now)
    end
end

