function vehBlock.restorePickerDefaults()
    local feat = FeatureMgr.GetFeature(H.VEH_BLOCK_LIST)
    if not feat then return end
    for i, name in ipairs(vehBlock.NAMES) do
        feat:ToggleListIndex(i - 1, vehBlock.DEFAULT_ON[name] == true)
    end
end
vehBlock.restorePickerDefaults()

function vehBlock.renderPicker()
    local feat = FeatureMgr.GetFeature(H.VEH_BLOCK_LIST)
    if not feat then return end
    local n, count, first = #vehBlock.NAMES, 0, nil
    for i = 0, n - 1 do
        if feat:IsListIndexToggled(i) then
            count = count + 1
            first = first or vehBlock.NAMES[i + 1]
        end
    end
    local preview = count == 0 and T("None selected")
        or count == 1 and T(first)
        or count == n and T("All vehicles")
        or T("%d vehicles selected"):format(count)
    if Widget.beginCombo(T("Vehicles") .. "##vs_vehblock_list", preview) then
        if ImGui.Button(T("Select all") .. "##vs_vehblock_all", 0, 0) then
            for i = 0, n - 1 do feat:ToggleListIndex(i, true) end
        end
        ImGui.SameLine()
        if ImGui.Button(T("Clear") .. "##vs_vehblock_clear", 0, 0) then
            for i = 0, n - 1 do feat:ToggleListIndex(i, false) end
        end
        for i, name in ipairs(vehBlock.NAMES) do
            local on = feat:IsListIndexToggled(i - 1)
            local want = ImGui.Checkbox(T(name) .. "##vs_vehblock_" .. i, on)
            if want ~= on then feat:ToggleListIndex(i - 1, want) end
        end
        Widget.endCombo()
    end
end

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    vehBlock.resetRemote()
    vehBlock.releaseAll()
end)


