centralOnTick(FeatureMgr.AddFeature(rainCars.RUNNER_HASH, "##RainCarsRunner",
    eFeatureType.Toggle, "", rainCars.onTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
    :SetSearchable(false)
    :SetVisible(false)
FeatureMgr.GetFeature(rainCars.RUNNER_HASH):Toggle(true)

function rainCars.teardownDrain()
    if rainCars.teardownDone then return end
    rainCars.inSafeTeardown = true
    local n = #rainCars.pool
    rainCars.deleteAll()
    rainCars.inSafeTeardown = false
    if #rainCars.pool == 0 then
        rainCars.teardownDone = true
        if not rainCars.delBufFreed then
            Memory.Free(rainCars.delBuf)
            rainCars.delBufFreed = true
        end
        logf("Rain Cars: teardown removed %d car(s)", n)
    end
end

Script.RegisterLooped(function()
    if ShouldUnload() or scriptUnloading then rainCars.teardownDrain() end
    Script.Yield()
end)

end)()



