;(function()

npcVehicleThief = {
    queue = {},
    active = nil,
    stolenBy = {},
    delBuf = Memory.Alloc(4),

    N_KEEP_TASK     = 0x971D38760FBC02EF,
    N_LOCK_ALL      = 0xA2F80B8D040727CC,
    N_RELEASE_PED   = 0x2595DD4236549CE3,
    N_TASK_WARP     = 0x9A7D091411C5F684,
    N_ENTITY_DEAD   = 0x5F9532F3B5CC2551,
    N_PLAYER_HASH   = 0xBC1D768F2F5D6C05,
    N_DECOR_EXISTS  = 0x05661B80A8C9165F,
    N_PED_IN_VEH    = 0xA3EE4A07279BB9DB,
    N_DRAG_OUT      = 0xC1670E958EEE24E5,
    N_COMBAT_ATTR   = 0x9F7794730795E019,
    N_FLEE_ATTR     = 0x70A2D1137C8ED7C9,

    ENTER_FLAGS = 2 | 8 | 16 | 64 | 512,
    DRIVE_STYLE = 4 | 32 | 256 | 4096 | 262144 | 524288,
    TASK_ENTER_VEHICLE = 160,
    MAX_RETASK = 3,
}

function npcVehicleThief.toast(message)
    GUI.AddToast(T("NPC Vehicle Thief"), message, 5000, eToastPos.TOP_RIGHT)
end

function npcVehicleThief.playerName(pid)
    return Players.GetName(pid) or T("player")
end

function npcVehicleThief.kindLabel(kind)
    if kind == "personal vehicle" then return T("personal vehicle") end
    if kind == "current vehicle" then return T("current vehicle") end
    return T("last-driven vehicle")
end

function npcVehicleThief.distance(a, b)
    local dx, dy, dz = a.x - b.x, a.y - b.y, a.z - b.z
    return math.sqrt(dx * dx + dy * dy + dz * dz)
end

function npcVehicleThief.harden(ped)
    PED.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS(ped, true)
    PED.SET_PED_CONFIG_FLAG(ped, 229, true)
    PED.SET_PED_CONFIG_FLAG(ped, 294, true)
    PED.SET_PED_CONFIG_FLAG(ped, 208, true)
    PED.SET_PED_CONFIG_FLAG(ped, 188, true)
    Natives.InvokeVoid(npcVehicleThief.N_FLEE_ATTR, ped, 2, true)
    Natives.InvokeVoid(npcVehicleThief.N_COMBAT_ATTR, ped, 3, false)
    Natives.InvokeVoid(npcVehicleThief.N_COMBAT_ATTR, ped, 17, false)
    Natives.InvokeVoid(npcVehicleThief.N_COMBAT_ATTR, ped, 38, true)
    Natives.InvokeVoid(npcVehicleThief.N_COMBAT_ATTR, ped, 58, true)
    Natives.InvokeVoid(npcVehicleThief.N_KEEP_TASK, ped, true)
end

function npcVehicleThief.findPersonalVehicle(pid, targetPos)
    local ownerHash = Natives.InvokeInt(npcVehicleThief.N_PLAYER_HASH, pid)
    local best, bestDistance = 0, math.huge
    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        local vehicle = PoolMgr.GetVehicle(i)
        if vehicle and vehicle ~= 0 and ENTITY.DOES_ENTITY_EXIST(vehicle)
            and Natives.InvokeBool(npcVehicleThief.N_DECOR_EXISTS,
                vehicle, "Player_Vehicle") then
            if DECORATOR.DECOR_GET_INT(vehicle, "Player_Vehicle") == ownerHash then
                local driver = VEHICLE.GET_PED_IN_VEHICLE_SEAT(vehicle, -1, false)
                local previousThief = npcVehicleThief.stolenBy[vehicle]
                local driverDead = driver ~= 0
                    and Natives.InvokeBool(npcVehicleThief.N_ENTITY_DEAD,
                        driver, false)
                if not (previousThief and driver == previousThief and not driverDead) then
                    if previousThief then
                        npcVehicleThief.stolenBy[vehicle] = nil
                    end
                    local distance = npcVehicleThief.distance(
                        ENTITY.GET_ENTITY_COORDS(vehicle, true), targetPos)
                    if distance < bestDistance then
                        best, bestDistance = vehicle, distance
                    end
                end
            end
        end
    end
    return best, bestDistance
end

function npcVehicleThief.resolveVehicle(pid, targetPed)
    local targetPos = ENTITY.GET_ENTITY_COORDS(targetPed, true)
    local personal, personalDistance =
        npcVehicleThief.findPersonalVehicle(pid, targetPos)

    if personal ~= 0 then
        return personal, "personal vehicle", personalDistance
    end

    if PED.IS_PED_IN_ANY_VEHICLE(targetPed, false) then
        local current = PED.GET_VEHICLE_PED_IS_IN(targetPed, false)
        if current ~= 0 and ENTITY.DOES_ENTITY_EXIST(current) then
            return current, "current vehicle", 0.0
        end
    end

    local last = PED.GET_VEHICLE_PED_IS_IN(targetPed, true)
    if last ~= 0 and ENTITY.DOES_ENTITY_EXIST(last) then
        local lastDistance = npcVehicleThief.distance(
            ENTITY.GET_ENTITY_COORDS(last, true), targetPos)
        return last, "last-driven vehicle", lastDistance
    end

    return 0, nil, nil
end

function npcVehicleThief.disposePed(job)
    if job.ped == 0 or not ENTITY.DOES_ENTITY_EXIST(job.ped) then return true end
    Memory.WriteInt(npcVehicleThief.delBuf, job.ped)
    ENTITY.DELETE_ENTITY(npcVehicleThief.delBuf)
    if not ENTITY.DOES_ENTITY_EXIST(job.ped) then return true end
    Memory.WriteInt(npcVehicleThief.delBuf, job.ped)
    ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED(npcVehicleThief.delBuf)
    local ok, why = UnloadReap.mark(job.addr, job.pop, "ped")
    return ok, why
end

function npcVehicleThief.deleteActive(reason, message)
    local job = npcVehicleThief.active
    npcVehicleThief.active = nil
    if job then
        local gone, why = npcVehicleThief.disposePed(job)
        if not gone then
            VIBE_LOG_ERROR(("[NpcVehicleThief] ped %d survived delete and mark (%s): %s")
                :format(job.ped, reason, tostring(why)))
        end
    end
    if message then npcVehicleThief.toast(message) end
end

function npcVehicleThief.unlock(vehicle)
    Natives.InvokeVoid(npcVehicleThief.N_LOCK_ALL, vehicle, false)
    VEHICLE.SET_VEHICLE_DOORS_LOCKED(vehicle, 1)
end

function npcVehicleThief.issueEnter(job, now)
    npcVehicleThief.unlock(job.vehicle)
    local driver = VEHICLE.GET_PED_IN_VEHICLE_SEAT(job.vehicle, -1, false)
    if driver ~= 0 then Natives.InvokeVoid(npcVehicleThief.N_DRAG_OUT, driver, true) end
    TASK.TASK_ENTER_VEHICLE(job.ped, job.vehicle, 30000, -1, 2.0,
        npcVehicleThief.ENTER_FLAGS, 0, false)
    job.state = "enter"
    job.taskCheckAt = now + 1000
end

function npcVehicleThief.driveAway(job)
    npcVehicleThief.unlock(job.vehicle)
    Natives.InvokeVoid(npcVehicleThief.N_KEEP_TASK, job.ped, true)
    TASK.TASK_VEHICLE_DRIVE_WANDER(job.ped, job.vehicle, 60.0,
        npcVehicleThief.DRIVE_STYLE)
    npcVehicleThief.stolenBy[job.vehicle] = job.ped

    Memory.WriteInt(npcVehicleThief.delBuf, job.ped)
    Natives.InvokeVoid(npcVehicleThief.N_RELEASE_PED, npcVehicleThief.delBuf)
    npcVehicleThief.active = nil
    telemetryCountAction("StealLastVehicle")
    npcVehicleThief.toast(T("An NPC stole %s's %s and drove away.")
        :format(npcVehicleThief.playerName(job.pid),
            npcVehicleThief.kindLabel(job.vehicleKind)))
end

function npcVehicleThief.handOffToCarjack(pid, targetPed, vehicle, vehicleKind)
    if pid == GTA.GetLocalPlayerId() then return false end
    if not PED.IS_PED_IN_ANY_VEHICLE(targetPed, false) then return false end
    if PED.GET_VEHICLE_PED_IS_IN(targetPed, false) ~= vehicle then return false end
    if VEHICLE.GET_PED_IN_VEHICLE_SEAT(vehicle, -1, false) ~= targetPed then
        return false
    end

    if PLAYER.IS_REMOTE_PLAYER_IN_NON_CLONED_VEHICLE(pid) then
        npcVehicleThief.toast(T("%s's vehicle isn't streamed in yet. Spectate them first, then try again.")
            :format(npcVehicleThief.playerName(pid)))
        return true
    end
    if playerState.takeover or #playerState.takeoverPending > 0 then
        npcVehicleThief.toast(T("Already jacking a vehicle - let that finish first."))
        return true
    end

    playerState.takeoverPending[#playerState.takeoverPending + 1] =
        { pid = pid, kind = "hijack" }
    npcVehicleThief.toast(T("NPC is carjacking %s out of their %s.")
        :format(npcVehicleThief.playerName(pid),
            npcVehicleThief.kindLabel(vehicleKind)))
    return true
end

function npcVehicleThief.begin(pid)
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
        npcVehicleThief.toast(T("That player is no longer in the session."))
        return
    end

    local targetPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if targetPed == 0 or not ENTITY.DOES_ENTITY_EXIST(targetPed) then
        npcVehicleThief.toast(T("That player's ped is not streamed in."))
        return
    end

    local vehicle, vehicleKind = npcVehicleThief.resolveVehicle(pid, targetPed)
    if vehicle == 0 then
        VIBE_LOG_ERROR(("[NpcVehicleThief] pid=%d no vehicle: no streamed PV, not seated, last-vehicle field empty"):format(pid))
        npcVehicleThief.toast(T("%s has no current, last-driven, or streamed personal vehicle.")
            :format(npcVehicleThief.playerName(pid)))
        return
    end

    if npcVehicleThief.handOffToCarjack(pid, targetPed, vehicle, vehicleKind) then
        return
    end

    local spawn = ENTITY.GET_ENTITY_COORDS(vehicle, true)
    local ped = GTA.CreateRandomPed(spawn.x, spawn.y, spawn.z - 30.0)
    if not ped or ped == 0 then
        npcVehicleThief.toast(T("Couldn't create a nearby NPC."))
        return
    end

    npcVehicleThief.harden(ped)
    local netId = NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(ped)
    if netId ~= 0 then NETWORK.SET_NETWORK_ID_CAN_MIGRATE(netId, false) end

    local now = Time.GetEpocheMs()
    local job = {
        pid = pid,
        ped = ped,
        vehicle = vehicle,
        vehicleKind = vehicleKind,
        startedAt = now,
        deadline = now + 12000,
        stallAt = now + 2000,
        retasks = 0,
        nextControl = now,
        addr = UnloadReap.addrOf(ped),
        pop = UnloadReap.popOf(ped),
    }
    NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(vehicle)
    npcVehicleThief.issueEnter(job, now)
    npcVehicleThief.active = job
    npcVehicleThief.toast(T("NPC is stealing %s's %s.")
        :format(npcVehicleThief.playerName(pid),
            npcVehicleThief.kindLabel(vehicleKind)))
end

function npcVehicleThief.queueFor(pid)
    if npcVehicleThief.active or #npcVehicleThief.queue > 0 then
        npcVehicleThief.toast(T("A vehicle theft is already in progress."))
        return
    end
    npcVehicleThief.queue[#npcVehicleThief.queue + 1] = pid
end

function npcVehicleThief.onTick(f)
    if not f:IsToggled() then return end
    if scriptUnloading then return end

    if not npcVehicleThief.active and #npcVehicleThief.queue > 0 then
        local pid = table.remove(npcVehicleThief.queue, 1)
        npcVehicleThief.begin(pid)
    end

    local job = npcVehicleThief.active
    if not job then return end
    if not ENTITY.DOES_ENTITY_EXIST(job.ped) then
        npcVehicleThief.active = nil
        npcVehicleThief.toast(T("The thief NPC disappeared."))
        return
    end
    if Natives.InvokeBool(npcVehicleThief.N_ENTITY_DEAD, job.ped, false) then
        npcVehicleThief.deleteActive("thief killed", T("The thief NPC was killed."))
        return
    end
    if not ENTITY.DOES_ENTITY_EXIST(job.vehicle) then
        npcVehicleThief.deleteActive("vehicle gone",
            T("The player's last vehicle is no longer available."))
        return
    end

    local now = Time.GetEpocheMs()
    local driver = VEHICLE.GET_PED_IN_VEHICLE_SEAT(job.vehicle, -1, false)
    local driverDead = driver ~= 0
        and Natives.InvokeBool(npcVehicleThief.N_ENTITY_DEAD, driver, false)
    if driver == job.ped
        or Natives.InvokeBool(npcVehicleThief.N_PED_IN_VEH,
            job.ped, job.vehicle, false) then
        if job.state ~= "control" then
            job.state = "control"
            job.controlUntil = now + 3000
        end
        if NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(job.vehicle)
            or now >= job.controlUntil then
            npcVehicleThief.driveAway(job)
        else
            NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(job.vehicle)
        end
        return
    end

    if job.state == "warp" then
        if driver ~= 0 and not driverDead then
            npcVehicleThief.issueEnter(job, now)
        elseif now >= job.warpUntil then
            npcVehicleThief.deleteActive("warp did not seat",
                T("The NPC couldn't get into the empty vehicle."))
        end
        return
    end

    local gettingIn = Natives.InvokeBool(npcVehicleThief.N_PED_IN_VEH,
        job.ped, job.vehicle, true)

    if not NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(job.vehicle)
        and now >= job.nextControl then
        NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(job.vehicle)
        job.nextControl = now + 250
    end

    if driver == 0 or driverDead then
        if driverDead then
            Natives.InvokeVoid(npcVehicleThief.N_DRAG_OUT, driver, true)
        end
        if now >= job.stallAt then
            npcVehicleThief.unlock(job.vehicle)
            Natives.InvokeVoid(npcVehicleThief.N_TASK_WARP,
                job.ped, job.vehicle, -1)
            job.state = "warp"
            job.warpUntil = now + 6000
            return
        end
    end

    if job.state == "control" then
        npcVehicleThief.deleteActive("pulled back out",
            T("The NPC was pulled back out of the vehicle."))
        return
    end

    if now >= job.deadline then
        npcVehicleThief.deleteActive("job deadline",
            T("The NPC couldn't get into the vehicle."))
        return
    end

    if not gettingIn and job.retasks < npcVehicleThief.MAX_RETASK
        and now >= job.taskCheckAt
        and not TASK.GET_IS_TASK_ACTIVE(
            job.ped, npcVehicleThief.TASK_ENTER_VEHICLE) then
        job.retasks = job.retasks + 1
        npcVehicleThief.issueEnter(job, now)
    end
end

for _, hash in ipairs(FeatureMgr.AddPlayerFeature(
    H.NPC_STEAL_LAST_VEHICLE, "Steal Last Vehicle/PV", eFeatureType.Button,
    "Teleports an NPC into the player's deployed personal vehicle, current vehicle, or last-driven vehicle and drives it away. If they are sitting in it, the NPC jacks them out of it first.",
    function(f) npcVehicleThief.queueFor(f:GetPlayerIndex()) end)) do
    FeatureMgr.GetFeature(hash):SetSaveable(false)
end

centralOnTick(FeatureMgr.AddFeature(H.NPC_STEAL_LAST_VEHICLE_RUNNER,
    "##NpcStealLastVehicleRunner", eFeatureType.Toggle, "", npcVehicleThief.onTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
FeatureMgr.GetFeature(H.NPC_STEAL_LAST_VEHICLE_RUNNER):Toggle(true)

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    local job = npcVehicleThief.active
    if job and job.addr then
        UnloadReap.markAll({ { addr = job.addr, pop = job.pop } }, "NpcVehicleThief")
    end
end)

end)()


;(function()


vehicleFlatten = {
    queue      = {},
    active     = {},
    runnerHash = H.FLATTEN_VEHICLE_RUNNER,

    MODEL = Utils.Joaat("rhino"),

    H_MODEL_DIMS = 0x03E8D3D5F549087A,

    LOAD_MS    = 3000,
    CRUSH_MS   = 2200,
    DOWN_SPEED = 5.0,
    CLEARANCE  = 0.40,
    TRACK_GAIN = 6.0,
    MAX_DRIFT  = 8.0,

    BLEND_LAG_MS = 120,
    LEAD_MIN_MS  = 60,
    LEAD_MAX_MS  = 500,

    dimsBuf = Memory.Alloc(48),
    delBuf  = Memory.Alloc(4),
    modelRequested = false,
}

function vehicleFlatten.toast(msg)
    GUI.AddToast(T("Flatten Vehicle"), T(msg), 3500)
end

function vehicleFlatten.getVehicle(pid, quiet)
    local function reject(msg)
        if not quiet then vehicleFlatten.toast(msg) end
    end

    if not isPlayerReady() then
        reject("You aren't ready (cutscene / switch / not playing).")
        return nil
    end
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
        reject("Player not connected.")
        return nil
    end
    if PLAYER.IS_REMOTE_PLAYER_IN_NON_CLONED_VEHICLE(pid) then
        reject("Player's vehicle isn't streamed in. Spectate them first, then try again.")
        return nil
    end
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then
        reject("Player is too far away (not streamed in). Spectate them first, then try again.")
        return nil
    end
    if not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        reject("Player isn't in a vehicle.")
        return nil
    end
    local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if not veh or veh == 0 or not ENTITY.DOES_ENTITY_EXIST(veh) then
        reject("Couldn't find the player's vehicle.")
        return nil
    end
    if VEHICLE.GET_PED_IN_VEHICLE_SEAT(veh, -1, false) ~= ped then
        reject("Player is a passenger, not driving.")
        return nil
    end
    return veh
end

function vehicleFlatten.leadSeconds(pid)
    local D = vehicleFlatten
    local ping = NETWORK.NETWORK_GET_AVERAGE_PING(pid) or 0.0
    if ping ~= ping or ping < 0.0 or ping > 2000.0 then ping = 0.0 end
    local ms = ping * 0.5 + D.BLEND_LAG_MS
    if ms < D.LEAD_MIN_MS then ms = D.LEAD_MIN_MS end
    if ms > D.LEAD_MAX_MS then ms = D.LEAD_MAX_MS end
    return ms / 1000.0, ping, ms
end

function vehicleFlatten.aimPoint(veh, pid)
    local pos = ENTITY.GET_ENTITY_COORDS(veh, false)
    if not pos then return nil end
    local vel = ENTITY.GET_ENTITY_VELOCITY(veh)
    local lead, ping, leadMs = vehicleFlatten.leadSeconds(pid)
    local vx, vy = 0.0, 0.0
    if vel then vx, vy = vel.x, vel.y end
    return pos.x + vx * lead, pos.y + vy * lead, pos.z,
           vx, vy, lead, ping, leadMs
end

function vehicleFlatten.modelBox(hash)
    local D = vehicleFlatten
    Natives.InvokeVoid(D.H_MODEL_DIMS, hash, D.dimsBuf, D.dimsBuf + 24)
    return Memory.ReadFloat(D.dimsBuf + 16) or 0.0,
           Memory.ReadFloat(D.dimsBuf + 40) or 0.0,
           Memory.ReadFloat(D.dimsBuf +  0) or 0.0,
           Memory.ReadFloat(D.dimsBuf + 24) or 0.0,
           Memory.ReadFloat(D.dimsBuf +  8) or 0.0,
           Memory.ReadFloat(D.dimsBuf + 32) or 0.0
end

function vehicleFlatten.delete(entry)
    local handle = entry and entry.handle or 0
    if handle == 0 or not ENTITY.DOES_ENTITY_EXIST(handle) then return true end

    local networked = NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(handle)
    if networked and not aircraftSabotage.takeControl(handle) then
        entry.deleteReason = "could not regain network control"
        return false
    end
    if networked then
        local netId = NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(handle)
        if netId and netId ~= 0 then
            NETWORK.SET_NETWORK_ID_EXISTS_ON_ALL_MACHINES(netId, false)
            NETWORK.SET_NETWORK_ID_CAN_MIGRATE(netId, false)
        end
    end
    ENTITY.FREEZE_ENTITY_POSITION(handle, false)
    ENTITY.SET_ENTITY_AS_MISSION_ENTITY(handle, true, true)
    Memory.WriteInt(vehicleFlatten.delBuf, handle)
    ENTITY.DELETE_ENTITY(vehicleFlatten.delBuf)
    local gone = not ENTITY.DOES_ENTITY_EXIST(handle)
    entry.deleteReason = gone and nil or
        (networked and "network DELETE_ENTITY left handle alive"
            or "local DELETE_ENTITY left handle alive")
    return gone
end

function vehicleFlatten.spawn(job, veh, now)
    local D = vehicleFlatten
    local pos = ENTITY.GET_ENTITY_COORDS(veh, false)
    if not pos then return false end
    local aimX, aimY = D.aimPoint(veh, job.pid)
    if not aimX then return false end

    local _, carMaxZ = D.modelBox(ENTITY.GET_ENTITY_MODEL(veh))
    local tankMinZ = D.modelBox(D.MODEL)

    local spawnZ = pos.z + carMaxZ + D.CLEARANCE - tankMinZ
    local heading = ENTITY.GET_ENTITY_HEADING(veh)

    local used = louderRadio.netVehicleCount()
    local maxVeh = NETWORK.GET_MAX_NUM_NETWORK_VEHICLES() or 0
    if maxVeh > 0 and used > 0 and used + 8 >= maxVeh then
        D.toast("Couldn't create the tank (network vehicle pool is busy).")
        VIBE_LOG_ERROR(("[FlattenVehicle] mission create held for network headroom (%d/%d)"):format(used, maxVeh))
        return false
    end

    local tank, networked = 0, false
    Script.ExecuteAsScript("freemode", function()
        tank = VEHICLE.CREATE_VEHICLE(D.MODEL, aimX, aimY, spawnZ, heading,
            true, false, false) or 0
        if tank == 0 then return end
        networked = NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(tank)
        if networked then
            local netId = NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(tank)
            if netId and netId ~= 0 then
                NETWORK.SET_NETWORK_ID_EXISTS_ON_ALL_MACHINES(netId, true)
                NETWORK.SET_NETWORK_ID_CAN_MIGRATE(netId, false)
            end
        end
    end)
    if tank == 0 then
        D.toast("Couldn't create the tank (vehicle or network pool may be full).")
        return false
    end

    ENTITY.SET_ENTITY_AS_MISSION_ENTITY(tank, true, true)
    if not networked then
        VIBE_LOG_ERROR(("[FlattenVehicle] mission create left tank %d local; deleting"):format(tank))
        D.delete({ handle = tank })
        D.toast("Couldn't create a networked tank.")
        return false
    end

    ENTITY.SET_ENTITY_VISIBLE(tank, false, false)
    ENTITY.SET_ENTITY_ALPHA(tank, 0, false)
    ENTITY.SET_ENTITY_INVINCIBLE(tank, true)
    ENTITY.SET_ENTITY_COLLISION(tank, true, true)

    local myPed = PLAYER.PLAYER_PED_ID()
    if myPed and myPed ~= 0 then
        ENTITY.SET_ENTITY_NO_COLLISION_ENTITY(tank, myPed, false)
        local myVeh = PED.GET_VEHICLE_PED_IS_IN(myPed, false)
        if myVeh and myVeh ~= 0 and myVeh ~= veh then
            ENTITY.SET_ENTITY_NO_COLLISION_ENTITY(tank, myVeh, false)
        end
    end

    ENTITY.SET_ENTITY_INVINCIBLE(veh, true)
    job.godmoded = veh

    job.tank       = tank
    job.crushStart = now
    job.entry      = {
        handle = tank,
        addr   = UnloadReap.addrOf(tank),
        kind   = "vehicle",
    }
    D.active[#D.active + 1] = job.entry


    return true
end

function vehicleFlatten.crush(job, veh, now)
    local D = vehicleFlatten
    if not ENTITY.DOES_ENTITY_EXIST(job.tank) then return "done" end

    local aimX, aimY, _, carVx, carVy = D.aimPoint(veh, job.pid)
    if not aimX then return "again" end

    local vx, vy = carVx, carVy

    local tankPos = ENTITY.GET_ENTITY_COORDS(job.tank, false)
    if tankPos then
        local dx, dy = aimX - tankPos.x, aimY - tankPos.y
        if (dx * dx + dy * dy) > (D.MAX_DRIFT * D.MAX_DRIFT) then
            if VIBESCRIPT_VERBOSE == true then VIBE_LOG_ERROR(("[FlattenVehicle] tank=%d lost the car (%.1fm from aim point); ending crush"):format(job.tank, math.sqrt(dx * dx + dy * dy))) end
            return "ok"
        end
        vx = vx + dx * D.TRACK_GAIN
        vy = vy + dy * D.TRACK_GAIN
    end

    ENTITY.SET_ENTITY_VELOCITY(job.tank, vx, vy, -D.DOWN_SPEED)

    if now - job.crushStart >= D.CRUSH_MS then return "ok" end
    return "again"
end

function vehicleFlatten.step(job, now)
    local D = vehicleFlatten
    local veh = D.getVehicle(job.pid, job.tank ~= nil)
    if not veh then return "done" end

    if not job.tank then
        STREAMING.REQUEST_MODEL(D.MODEL)
        D.modelRequested = true
        if not STREAMING.HAS_MODEL_LOADED(D.MODEL) then
            if now - job.queuedAt >= D.LOAD_MS then
                D.toast("Tank model did not load in time.")
                return "done"
            end
            return "again"
        end
        if not D.spawn(job, veh, now) then return "done" end
        return "again"
    end

    return D.crush(job, veh, now)
end

function vehicleFlatten.finish(job, now)
    if job.entry then job.entry.deleteAt = now end
    if job.godmoded and ENTITY.DOES_ENTITY_EXIST(job.godmoded) then
        ENTITY.SET_ENTITY_INVINCIBLE(job.godmoded, false)
    end
    job.godmoded = nil
end

function vehicleFlatten.onTick(f)
    if not f:IsToggled() then return end
    if scriptUnloading then return end
    local D = vehicleFlatten
    local now = Time.GetEpocheMs()

    for i = #D.active, 1, -1 do
        local entry = D.active[i]
        if entry.deleteAt and now >= entry.deleteAt then
            if D.delete(entry) then
                table.remove(D.active, i)
            elseif not entry.deleteWarned then
                entry.deleteWarned = true
                VIBE_LOG_ERROR(("[FlattenVehicle] tank=%d survived first delete (%s); retrying"):format(entry.handle, entry.deleteReason or "unknown reason"))
            end
        end
    end

    if #D.queue == 0 then
        if #D.active == 0 and D.modelRequested then
            STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(D.MODEL)
            D.modelRequested = false
        end
        return
    end

    local q = D.queue
    D.queue = {}
    for i = 1, #q do
        local job = q[i]
        local result = D.step(job, now)
        if result == "again" then
            D.queue[#D.queue + 1] = job
        else
            D.finish(job, now)
            if result == "ok" then
                D.toast("Vehicle flattened.")
                telemetryCountAction("FlattenVehicle")
            end
        end
    end
end

for _, hash in ipairs(FeatureMgr.AddPlayerFeature(
    H.FLATTEN_VEHICLE, "Flatten Vehicle", eFeatureType.Button,
    "Flattens the player's vehicle with an invisible tank.",
    function(f)
        vehicleFlatten.queue[#vehicleFlatten.queue + 1] = {
            pid = f:GetPlayerIndex(),
            queuedAt = Time.GetEpocheMs(),
        }
    end)) do
    FeatureMgr.GetFeature(hash):SetSaveable(false)
end

centralOnTick(FeatureMgr.AddFeature(vehicleFlatten.runnerHash, "##VehicleFlattenRunner",
    eFeatureType.Toggle, "", vehicleFlatten.onTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
    :SetSearchable(false)
    :SetVisible(false)
FeatureMgr.GetFeature(vehicleFlatten.runnerHash):Toggle()

Script.RegisterLooped(function()
    if ShouldUnload() or scriptUnloading then
        for i = #vehicleFlatten.active, 1, -1 do
            if vehicleFlatten.delete(vehicleFlatten.active[i]) then
                table.remove(vehicleFlatten.active, i)
            end
        end
        vehicleFlatten.queue = {}
    end
    Script.Yield()
end)

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    UnloadReap.markAll(vehicleFlatten.active, "FlattenVehicle")
end)

end)()



lockVeh = {
    H_SET_EXCLUSIVE_DRIVER = 0xB5C51B5502E85E83,
    H_LOCK_FOR_PLAYER      = 0x517AAF684BB50CD1,
    H_GET_PED_IN_SEAT      = 0xBB40DD2270B65366,
    H_TRYING_TO_ENTER      = 0x814FA8BE5449445D,
    H_IS_SEAT_FREE         = 0x22AC59A870E6A669,
    H_DONT_TRY_IF_LOCKED   = 0xDBC631F109350B8C,
    SWEEP_MS       = 1000,
    REASSERT_MS    = 5000,
    RESTAMP_MS     = 50,
    RADIUS         = 8.0,
    RELEASE_RADIUS = 15.0,
    state       = {},
}

function lockVeh.hasDriver(veh)
    return not Natives.InvokeBool(lockVeh.H_IS_SEAT_FREE, veh, -1, false)
end

function lockVeh.driverOf(veh)
    return Natives.InvokeInt(lockVeh.H_GET_PED_IN_SEAT, veh, -1, false) or 0
end

function lockVeh.stateFor(pid)
    local st = lockVeh.state[pid]
    if not st then
        st = { held = {}, lastSweep = 0 }
        lockVeh.state[pid] = st
    end
    return st
end

function lockVeh.stamp(veh, pid, excl, me, noTry)
    if excl then
        Natives.InvokeVoid(lockVeh.H_SET_EXCLUSIVE_DRIVER, veh, me, 0)
    end
    Natives.InvokeVoid(lockVeh.H_LOCK_FOR_PLAYER, veh, pid, true)
    if noTry then
        Natives.InvokeVoid(lockVeh.H_DONT_TRY_IF_LOCKED, veh, true)
    end
end

function lockVeh.unstamp(veh, pid, h)
    if h.excl then
        Natives.InvokeVoid(lockVeh.H_SET_EXCLUSIVE_DRIVER, veh, 0, 0)
    end
    Natives.InvokeVoid(lockVeh.H_LOCK_FOR_PLAYER, veh, pid, false)
    if h.noTry then
        Natives.InvokeVoid(lockVeh.H_DONT_TRY_IF_LOCKED, veh, false)
    end
end

function lockVeh.otherPlayerDrives(drv, ped)
    return drv ~= 0 and drv ~= ped and PED.IS_PED_A_PLAYER(drv)
end

function lockVeh.release(pid)
    local st = lockVeh.state[pid]
    if not st then return end
    lockVeh.state[pid] = nil
    for veh, h in pairs(st.held) do
        if ENTITY.DOES_ENTITY_EXIST(veh) then lockVeh.unstamp(veh, pid, h) end
    end
end

function lockVeh.releaseAll()
    local pids = {}
    for pid in pairs(lockVeh.state) do pids[#pids + 1] = pid end
    for i = 1, #pids do lockVeh.release(pids[i]) end
end

function lockVeh.retryAttemptLock(pid, st, h, now)
    if now - h.lastMs < lockVeh.RESTAMP_MS then return end
    Natives.InvokeVoid(lockVeh.H_LOCK_FOR_PLAYER, st.attempt.veh, pid, true)
    h.lastMs = now
end

function lockVeh.catchEntry(pid, st, now)
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not ped or ped == 0 then return end

    local veh = Natives.InvokeInt(lockVeh.H_TRYING_TO_ENTER, ped) or 0
    if veh ~= 0 and not ENTITY.DOES_ENTITY_EXIST(veh) then veh = 0 end

    if st.attempt and st.attempt.veh ~= veh then st.attempt = nil end
    if veh == 0 then return end

    local h = st.held[veh]
    if h then
        if not st.attempt then st.attempt = { veh = veh } end
        lockVeh.retryAttemptLock(pid, st, h, now)
        return
    end

    local occupied = lockVeh.hasDriver(veh)
    local drv = occupied and lockVeh.driverOf(veh) or 0

    local noTry = lockVeh.otherPlayerDrives(drv, ped)
    local excl = occupied and not noTry
    lockVeh.stamp(veh, pid, excl,
        PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId()), noTry)
    st.held[veh] = { lastMs = now, excl = excl, noTry = noTry }
    st.attempt = { veh = veh }
end

function lockVeh.sweep(pid, st, now)
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then return end
    local me = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
    if not me or me == 0 then return end

    local inVeh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if inVeh ~= 0 and not ENTITY.DOES_ENTITY_EXIST(inVeh) then inVeh = 0 end

    for veh, h in pairs(st.held) do
        if not ENTITY.DOES_ENTITY_EXIST(veh) then
            st.held[veh] = nil
        elseif h.excl and not lockVeh.hasDriver(veh) then
            Natives.InvokeVoid(lockVeh.H_SET_EXCLUSIVE_DRIVER, veh, 0, 0)
            h.excl = false
        end
    end

    local pos = ENTITY.GET_ENTITY_COORDS(ped, true)
    local r2 = lockVeh.RADIUS * lockVeh.RADIUS
    local rr2 = lockVeh.RELEASE_RADIUS * lockVeh.RELEASE_RADIUS
    local attemptVeh = st.attempt and st.attempt.veh or 0

    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        local veh = PoolMgr.GetVehicle(i)
        if veh and veh > 0 then
            local near = (veh == inVeh)
            if not near then
                local vp = ENTITY.GET_ENTITY_COORDS(veh, true)
                local dx, dy, dz = vp.x - pos.x, vp.y - pos.y, vp.z - pos.z
                local d2 = dx * dx + dy * dy + dz * dz
                near = d2 <= r2

                local h = st.held[veh]
                if h and d2 > rr2 and veh ~= attemptVeh then
                    lockVeh.unstamp(veh, pid, h)
                    st.held[veh] = nil
                end
            end

            local occupied = near and lockVeh.hasDriver(veh) or false
            local drv = occupied and lockVeh.driverOf(veh) or 0
            local noTry = occupied and lockVeh.otherPlayerDrives(drv, ped)
            if occupied and drv ~= ped and not noTry then near = false end

            if near then
                local want = (drv == ped)
                local h = st.held[veh]
                if not h then
                    lockVeh.stamp(veh, pid, want, me, noTry)
                    st.held[veh] = { lastMs = now, excl = want, noTry = noTry }
                elseif h.excl ~= want or (noTry and not h.noTry) then
                    lockVeh.stamp(veh, pid, want, me, noTry)
                    h.lastMs, h.excl = now, want
                    h.noTry = h.noTry or noTry
                elseif now - h.lastMs >= lockVeh.REASSERT_MS then
                    lockVeh.stamp(veh, pid, want, me, h.noTry)
                    h.lastMs = now
                end
            end
        end
    end
end

function lockVeh.onTick(f)
    local pid = f:GetPlayerIndex()
    telemetryCountToggleEdge("LockVehicle", pid, f:IsToggled())
    if scriptUnloading then return end
    if not f:IsToggled() then
        if lockVeh.state[pid] then lockVeh.release(pid) end
        return
    end
    if not isPlayerReady() then return end
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
        if lockVeh.state[pid] then lockVeh.release(pid) end
        return
    end

    local st = lockVeh.stateFor(pid)
    local now = Time.GetEpocheMs()
    lockVeh.catchEntry(pid, st, now)

    if now - st.lastSweep < lockVeh.SWEEP_MS then return end
    st.lastSweep = now
    lockVeh.sweep(pid, st, now)
end

