function playerState.speed.queueApply(pid)
    local mult = playerState.speed.wantedMult(pid)

    playerState.speed.done[pid] = nil
    playerState.speed.cooldown[pid] = nil
    playerState.speed.attempt[pid] = nil

    local q = playerState.speed.pending
    for i = 1, #q do
        if q[i].pid == pid then q[i].mult, q[i].started = mult, nil return end
    end
    q[#q + 1] = { pid = pid, mult = mult }
end

function playerState.speed.runner(f)
    if not f:IsToggled() then return end
    local q = playerState.speed.pending
    local job = q[1]
    if not job then return end
    if not isPlayerReady() then return end

    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(job.pid) then
        table.remove(q, 1)
        playerState.speed.stopSyncFor(job.pid, "speed")
        return
    end

    local now = MISC.GET_GAME_TIMER()
    job.started = job.started or now
    if playerState.speed.apply(job.pid, job.mult) then
        table.remove(q, 1)
        GUI.AddToast("Engine Power",
            T("Applied x%.1f to %s."):format(job.mult, Players.GetName(job.pid) or T("player")), 3000)
    elseif now - job.started >= playerState.speed.ATTEMPT_TIMEOUT_MS then
        table.remove(q, 1)
        playerState.speed.stopSyncFor(job.pid, "speed")
        playerState.speed.attempt[job.pid] = nil
        GUI.AddToast("Engine Power",
            T("Couldn't reach %s's vehicle."):format(Players.GetName(job.pid) or T("player")), 3000)
    end
end

