playerState.hornMuzzleBuf = Memory.Alloc(48)

function playerState.hornMuzzleOffsets(veh)
    local buf = playerState.hornMuzzleBuf
    MISC.GET_MODEL_DIMENSIONS(ENTITY.GET_ENTITY_MODEL(veh), buf, buf + 24)
    local halfWidth = Memory.ReadFloat(buf + 24) or 0.0
    local nose      = Memory.ReadFloat(buf + 32) or 0.0
    if nose <= 0.0 then return 1.25, 0.5 end
    local lateral = halfWidth * 0.7
    if lateral < 0.4 then lateral = 0.4 elseif lateral > 1.5 then lateral = 1.5 end
    return lateral, nose + 1.0
end

playerState.hornRocketsOnTick = function(f)
    local pid = f:GetPlayerIndex()
    telemetryCountToggleEdge("HornRockets", pid, f:IsToggled())
    if not f:IsToggled() then
        playerState.hornRockets[pid] = nil
        return
    end
    if not isPlayerReady() then return end
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then return end

    local driver = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if driver == 0 or not ENTITY.DOES_ENTITY_EXIST(driver) then return end
    if not PED.IS_PED_IN_ANY_VEHICLE(driver, false) then
        playerState.hornRockets[pid] = nil
        return
    end
    local veh = PED.GET_VEHICLE_PED_IS_IN(driver, false)
    if veh == 0 or not ENTITY.DOES_ENTITY_EXIST(veh) then return end

    if not PLAYER.IS_PLAYER_PRESSING_HORN(pid) then
        playerState.hornRockets[pid] = nil
        return
    end
    if playerState.hornRockets[pid] then return end

    local shell = Utils.Joaat("VEHICLE_WEAPON_TANK")
    if not WEAPON.HAS_WEAPON_ASSET_LOADED(shell) then
        WEAPON.REQUEST_WEAPON_ASSET(shell, 31, 0)
        return
    end
    playerState.hornRockets[pid] = true

    local side, muzzle = playerState.hornMuzzleOffsets(veh)
    local portFrom = ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(veh, -side, muzzle, 0.35)
    local portTo   = ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(veh, -side, muzzle + 100.0, 0.35)
    local starFrom = ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(veh, side, muzzle, 0.35)
    local starTo   = ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(veh, side, muzzle + 100.0, 0.35)
    MISC.SHOOT_SINGLE_BULLET_BETWEEN_COORDS(portFrom.x, portFrom.y, portFrom.z,
        portTo.x, portTo.y, portTo.z, 0, true, shell, 0, true, false, 5.0)
    MISC.SHOOT_SINGLE_BULLET_BETWEEN_COORDS(starFrom.x, starFrom.y, starFrom.z,
        starTo.x, starTo.y, starTo.z, 0, true, shell, 0, true, false, 5.0)
end

