function playerState.expBulletTag()
    local f = FeatureMgr.GetFeature(H.EXP_BULLETS_TAG)
    return playerState.expBulletTags[(f and f:GetListIndex() or 0) + 1] or 45
end

function playerState.expBulletImpact(ped)
    local e = playerState.expBullets
    if e.buf == 0 then
        e.buf = Memory.Alloc(24) or 0
        if e.buf == 0 then return nil end
    end
    if not Natives.InvokeBool(e.IMPACT, ped, e.buf) then return nil end
    local x = Memory.ReadFloat(e.buf)
    local y = Memory.ReadFloat(e.buf + 8)
    local z = Memory.ReadFloat(e.buf + 16)
    if x == 0.0 and y == 0.0 and z == 0.0 then return nil end
    return x, y, z
end

playerState.expBulletsOnTick = function(f)
    local pid = f:GetPlayerIndex()
    local on = f:IsToggled()
    telemetryCountToggleEdge("ExplosiveBullets", pid, on)
    local e = playerState.expBullets
    if not on then
        e.nextAt[pid] = nil
        return
    end
    if not isPlayerReady() then return end
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
        e.nextAt[pid] = nil
        return
    end

    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then return end
    local shooter = ped
    if pid == GTA.GetLocalPlayerId() and rideAnimal.gunPed then
        shooter = rideAnimal.gunPed
    end
    if not Natives.InvokeBool(e.IS_ARMED, shooter, e.ARMED_GUN) then return end
    if PED.IS_PED_PERFORMING_MELEE_ACTION(shooter) then return end

    local x, y, z = playerState.expBulletImpact(shooter)
    if not x then return end

    local now = Time.GetEpocheMs()
    if now < (e.nextAt[pid] or 0) then return end
    e.nextAt[pid] = now + e.MIN_GAP_MS

    FIRE.ADD_OWNED_EXPLOSION(ped, x, y, z, playerState.expBulletTag(),
        1.0, true, false, 0.0)
end

