do
    local LANGUAGE_OPTIONS = {
        { "Chinese (Simplified)",  12 },
        { "Chinese (Traditional)", 9 },
        { "English",               0 },
        { "French",                1 },
        { "German",                2 },
        { "Italian",               3 },
        { "Japanese",             10 },
        { "Korean",                8 },
        { "Polish",                6 },
        { "Portuguese (Brazil)",   5 },
        { "Russian",               7 },
        { "Spanish (Mexico)",      11 },
        { "Spanish (Spain)",       4 },
    }
    local LANGUAGE_NAMES, LANGUAGE_INDEX_BY_ID = {}, {}
    for displayIndex, option in ipairs(LANGUAGE_OPTIONS) do
        LANGUAGE_NAMES[displayIndex] = option[1]
        LANGUAGE_INDEX_BY_ID[option[2]] = displayIndex - 1
    end
    local MAX_LANGUAGE = 12

    local GPBD_FM_3_LANGUAGE = 132

    local function readPlayerLanguage(playerId)
        local v = ScriptGlobal.GetInt(
            OFF.GPBD_FM_3_BASE + 1 + playerId * OFF.GPBD_FM_3_SIZE + GPBD_FM_3_LANGUAGE)
        if not v or v < 0 or v > MAX_LANGUAGE then return nil end
        return v
    end

    local function detectLanguage(playerId)
        local listFeat = FeatureMgr.GetFeature(H.LANGUAGE_LIST)
        if not listFeat then return false end

        local lang = readPlayerLanguage(playerId)
        if not lang then return nil end

        if lang == 0 and not languageKicker.zeroSeen[playerId] then
            languageKicker.zeroSeen[playerId] = true
            return nil
        end

        local displayIndex = LANGUAGE_INDEX_BY_ID[lang]
        if displayIndex ~= nil and listFeat:IsListIndexToggled(displayIndex) then
            return true, LANGUAGE_NAMES[displayIndex + 1]
        end
        return false
    end

    local function kickLanguagePlayer(playerId, reason)
        if KICKER.isProtected(playerId) then
            languageKicker.pending[playerId] = nil
            return
        end
        local name = Players.GetName(playerId) or "?"
        if not doKick(playerId) then
            languageKicker.kicked[playerId] = true
            languageKicker.pending[playerId] = nil
            return
        end

        VIBE_LOG_INFO(("[VibeScript] Language Kicker: kicking %s - %s (id %d)"):format(name, reason, playerId))
        GUI.AddToast("VibeScript",
            T("Language Kicker: kicking %s (%s)"):format(name, reason), 5000)

        languageKicker.kicked[playerId] = true
        languageKicker.pending[playerId] = nil
    end

    local function checkAndKickLanguage(playerId)
        if playerId == GTA.GetLocalPlayerId() then return end
        if languageKicker.kicked[playerId] then return end
        if KICKER.deferFreshJoin(languageKicker, playerId) then return end
        if KICKER.isProtected(playerId) then return end

        local result, reason = detectLanguage(playerId)
        if result == true then
            kickLanguagePlayer(playerId, reason)
        elseif result == nil then
            if not languageKicker.pending[playerId] then
                languageKicker.pending[playerId] = {
                    attempts = 0,
                    nextCheck = os.clock() + KICKER.RETRY_DELAY,
                }
            end
        end
    end

    local function onLanguagePlayerJoin(playerId)
        local feat = FeatureMgr.GetFeature(H.LANGUAGE_KICKER)
        if not feat or not feat:IsToggled() then return end
        languageKicker.kicked[playerId] = nil
        languageKicker.pending[playerId] = nil
        languageKicker.zeroSeen[playerId] = nil
        KICKER.noteJoin(playerId)
        checkAndKickLanguage(playerId)
    end

    local function languageKickerOnTick(f)
        if not f:IsToggled() then
            if languageKicker.scanned or languageKicker.eventId
               or next(languageKicker.pending) or next(languageKicker.kicked) then
                languageKicker.kicked = {}
                languageKicker.pending = {}
                languageKicker.zeroSeen = {}
                languageKicker.scanned = false
                languageKicker.mask = nil
                if languageKicker.eventId then
                    EventMgr.RemoveHandler(languageKicker.eventId)
                    languageKicker.eventId = nil
                end
            end
            return
        end

        if not languageKicker.eventId then
            languageKicker.eventId = EventMgr.RegisterHandler(
                eLuaEvent.ON_PLAYER_JOIN, onLanguagePlayerJoin)
        end

        local mask = KICKER.selectionMask(H.LANGUAGE_LIST, languageKicker.languageCount)
        if mask ~= languageKicker.mask then
            languageKicker.mask = mask
            languageKicker.kicked = {}
            languageKicker.pending = {}
            languageKicker.scanned = false
        end

        if not languageKicker.scanned then
            languageKicker.scanned = true
            local localId = GTA.GetLocalPlayerId()
            for pid = 0, 31 do
                if pid ~= localId and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                    checkAndKickLanguage(pid)
                end
            end
        end

        local now = os.clock()
        for pid, info in pairs(languageKicker.pending) do
            if now >= info.nextCheck then
                if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                    languageKicker.pending[pid] = nil
                    languageKicker.zeroSeen[pid] = nil
                elseif KICKER.deferFreshJoin(languageKicker, pid) then
                elseif KICKER.isProtected(pid) then
                    languageKicker.pending[pid] = nil
                else
                    local result, reason = detectLanguage(pid)
                    if result == true then
                        kickLanguagePlayer(pid, reason)
                    elseif result == nil then
                        info.attempts = info.attempts + 1
                        if info.attempts >= KICKER.MAX_RETRIES then
                            logf("Language Kicker: gave up on player %d after %d retries", pid, KICKER.MAX_RETRIES)
                            languageKicker.pending[pid] = nil
                        else
                            info.nextCheck = now + KICKER.RETRY_DELAY
                        end
                    else
                        languageKicker.pending[pid] = nil
                    end
                end
            end
        end
    end

    centralOnTick(FeatureMgr.AddFeature(H.LANGUAGE_KICKER, "Language Kicker", eFeatureType.Toggle,
        "Kicks players whose game language is selected below.",
        languageKickerOnTick))
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)

    FeatureMgr.AddFeature(H.LANGUAGE_LIST, "Languages", eFeatureType.ComboToggles)
        :SetList(TLIST(LANGUAGE_NAMES))
        :SetSaveable(false)
    VIBE_TR.trackList(H.LANGUAGE_LIST, LANGUAGE_NAMES)
    local listFeat = FeatureMgr.GetFeature(H.LANGUAGE_LIST)
    for i = 0, #LANGUAGE_NAMES - 1 do listFeat:ToggleListIndex(i, false) end
    languageKicker.languageCount = #LANGUAGE_NAMES
end

do
    local function getLocalCountry()
        if myCountryOnly.localCC then return myCountryOnly.localCC end
        local ipInfo = getPlayerIPInfo(GTA.GetLocalPlayerId())
        if not ipInfo then return nil end
        local cc = ipInfo["countryCode"] or ""
        if cc == "" or cc == "NA" then return nil end
        myCountryOnly.localCC = cc
        return cc
    end

    local function detectForeign(playerId)
        local localCC = getLocalCountry()
        if not localCC then return nil end

        local ipInfo = getPlayerIPInfo(playerId)
        if not ipInfo then return nil end

        local cc = ipInfo["countryCode"] or ""
        if cc == "" or cc == "NA" then return nil end

        if cc ~= localCC then
            return true, cc
        end
        return false
    end

    local function kickForeignPlayer(playerId, cc)
        if KICKER.isProtected(playerId) then
            myCountryOnly.pending[playerId] = nil
            return
        end
        local name = Players.GetName(playerId) or "?"
        if not doKick(playerId) then
            myCountryOnly.kicked[playerId] = true
            myCountryOnly.pending[playerId] = nil
            return
        end

        VIBE_LOG_INFO(("[VibeScript] Maximize Xenophobia: kicking %s - %s (id %d)"):format(name, cc, playerId))
        GUI.AddToast("VibeScript",
            T("Maximize Xenophobia: kicking %s (%s)"):format(name, cc), 5000)

        myCountryOnly.kicked[playerId] = true
        myCountryOnly.pending[playerId] = nil
    end

    local function checkAndKickForeign(playerId)
        if playerId == GTA.GetLocalPlayerId() then return end
        if myCountryOnly.kicked[playerId] then return end
        if KICKER.deferFreshJoin(myCountryOnly, playerId) then return end
        if KICKER.isProtected(playerId) then return end

        local result, cc = detectForeign(playerId)
        if result == true then
            kickForeignPlayer(playerId, cc)
        elseif result == nil then
            if not myCountryOnly.pending[playerId] then
                myCountryOnly.pending[playerId] = {
                    attempts = 0,
                    nextCheck = os.clock() + KICKER.RETRY_DELAY,
                }
            end
        end
    end

    local function onForeignPlayerJoin(playerId)
        local feat = FeatureMgr.GetFeature(H.MY_COUNTRY_ONLY)
        if not feat or not feat:IsToggled() then return end
        myCountryOnly.kicked[playerId] = nil
        myCountryOnly.pending[playerId] = nil
        KICKER.noteJoin(playerId)
        checkAndKickForeign(playerId)
    end

    local function myCountryOnlyOnTick(f)
        if not f:IsToggled() then
            if myCountryOnly.scanned or myCountryOnly.eventId or myCountryOnly.localCC
               or next(myCountryOnly.pending) or next(myCountryOnly.kicked) then
                myCountryOnly.kicked = {}
                myCountryOnly.pending = {}
                myCountryOnly.scanned = false
                myCountryOnly.localCC = nil
                if myCountryOnly.eventId then
                    EventMgr.RemoveHandler(myCountryOnly.eventId)
                    myCountryOnly.eventId = nil
                end
            end
            return
        end

        if not myCountryOnly.eventId then
            myCountryOnly.eventId = EventMgr.RegisterHandler(
                eLuaEvent.ON_PLAYER_JOIN, onForeignPlayerJoin)
        end

        if not myCountryOnly.scanned then
            if not getLocalCountry() then return end
            myCountryOnly.scanned = true
            local localId = GTA.GetLocalPlayerId()
            for pid = 0, 31 do
                if pid ~= localId and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                    checkAndKickForeign(pid)
                end
            end
        end

        local now = os.clock()
        for pid, info in pairs(myCountryOnly.pending) do
            if now >= info.nextCheck then
                if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                    myCountryOnly.pending[pid] = nil
                elseif KICKER.deferFreshJoin(myCountryOnly, pid) then
                elseif KICKER.isProtected(pid) then
                    myCountryOnly.pending[pid] = nil
                else
                    local result, cc = detectForeign(pid)
                    if result == true then
                        kickForeignPlayer(pid, cc)
                    elseif result == nil then
                        info.attempts = info.attempts + 1
                        if info.attempts >= KICKER.MAX_RETRIES then
                            logf("Maximize Xenophobia: gave up on player %d after %d retries", pid, KICKER.MAX_RETRIES)
                            myCountryOnly.pending[pid] = nil
                        else
                            info.nextCheck = now + KICKER.RETRY_DELAY
                        end
                    else
                        myCountryOnly.pending[pid] = nil
                    end
                end
            end
        end
    end

    centralOnTick(FeatureMgr.AddFeature(H.MY_COUNTRY_ONLY, "Maximize Xenophobia", eFeatureType.Toggle,
        "Kicks every player whose country does not match yours.",
        myCountryOnlyOnTick))
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)
end

do
    local countryNotify = { pending = {}, seen = {}, eventId = nil, localCC = nil }
    local NOTIFY_RETRIES = 15

    local function notifyLocalCountry()
        if countryNotify.localCC then return countryNotify.localCC end
        local ipInfo = getPlayerIPInfo(GTA.GetLocalPlayerId())
        if not ipInfo then return nil end
        local cc = ipInfo["countryCode"] or ""
        if cc == "" or cc == "NA" then return nil end
        countryNotify.localCC = cc
        return cc
    end

    local function notifySameCountry(playerId)
        local localCC = notifyLocalCountry()
        if not localCC then return nil end
        local ipInfo = getPlayerIPInfo(playerId)
        if not ipInfo then return nil end
        local cc = ipInfo["countryCode"] or ""
        if cc == "" or cc == "NA" then return nil end
        if cc ~= localCC then return false end
        return true, cc
    end

    local function announceCountryman(playerId, cc)
        if countryNotify.seen[playerId] then return end
        countryNotify.seen[playerId] = true
        local name = Players.GetName(playerId) or "?"
        local where = countryFinder.name(cc) or cc
        VIBE_LOG_INFO(("[VibeScript] Notify Same Country: %s (%s, id %d)")
            :format(name, cc, playerId))
        GUI.AddToast("VibeScript", T("%s is from %s"):format(name, where), 8000)
    end

    local function onCountryPlayerJoin(playerId)
        local feat = FeatureMgr.GetFeature(H.COUNTRY_NOTIFY)
        if not feat or not feat:IsToggled() then return end
        if playerId == GTA.GetLocalPlayerId() then return end
        countryNotify.seen[playerId] = nil
        countryNotify.pending[playerId] = {
            attempts  = 0,
            nextCheck = os.clock() + KICKER.RETRY_DELAY,
        }
    end

    local function countryNotifyOnTick(f)
        if not f:IsToggled() then
            if countryNotify.eventId or countryNotify.localCC
               or next(countryNotify.pending) or next(countryNotify.seen) then
                countryNotify.pending = {}
                countryNotify.seen = {}
                countryNotify.localCC = nil
                if countryNotify.eventId then
                    EventMgr.RemoveHandler(countryNotify.eventId)
                    countryNotify.eventId = nil
                end
            end
            return
        end

        if not countryNotify.eventId then
            countryNotify.eventId = EventMgr.RegisterHandler(
                eLuaEvent.ON_PLAYER_JOIN, onCountryPlayerJoin)
        end

        local now = os.clock()
        for pid, info in pairs(countryNotify.pending) do
            if now >= info.nextCheck then
                if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                    countryNotify.pending[pid] = nil
                else
                    local result, cc = notifySameCountry(pid)
                    if result == true then
                        announceCountryman(pid, cc)
                        countryNotify.pending[pid] = nil
                    elseif result == nil then
                        info.attempts = info.attempts + 1
                        if info.attempts >= NOTIFY_RETRIES then
                            countryNotify.pending[pid] = nil
                        else
                            info.nextCheck = now + KICKER.RETRY_DELAY
                        end
                    else
                        countryNotify.pending[pid] = nil
                    end
                end
            end
        end
    end

    centralOnTick(FeatureMgr.AddFeature(H.COUNTRY_NOTIFY, "Notify Same Country", eFeatureType.Toggle,
        "Toasts when a player from your country joins the session.",
        countryNotifyOnTick))
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)
end


do
    local function wordSet(text)
        local t = {}
        for w in text:gmatch("%a+") do t[w] = true end
        return t
    end

    local LEGAL = wordSet([[
        inc incorporated llc llp ltd ltda limited limitada gmbh mbh ag nv bv sa
        sas sarl srl spa sl ab aps oy oyj plc pte pty sdn bhd co corp corporation
        company holding holdings jsc pjsc ojsc cjsc ooo cc kft doo shpk kk kg ug
        sia uab ou eood fzco fz trading dba
    ]])

    local GENERIC = wordSet([[
        cloud clouds hosting host hosted hosts server servers service services
        solution solutions network networks networking internet technology
        technologies tech telecom telecoms telecommunications communications
        communication data datacenter datacentre center centre centers colocation
        systems system group groups digital online web computer computers
        computing information media provider providers infrastructure enterprise
        enterprises industry first com net vpn vpns the and of
    ]])

    local GEO = wordSet([[
        hk hong kong cn china chinese us usa uk gb eu europe european america
        american asia asian japan jp japanese singapore sg korea korean india
        indian netherlands nl holland germany de deutschland france fr canada ca
        sweden se sverige finland fi norway denmark russia ru russian brazil
        brasil br australia au nz spain es italy it poland pl romania ro turkey
        mexico africa international global worldwide east west north south
        shenzhen hangzhou beijing shanghai guangzhou tokyo london amsterdam
        frankfurt paris moscow
    ]])

    local COMPOUND = wordSet([[
        server servers cloud clouds hosting host net network networks tech
        technologies telecom group games data dc vps vpn cdn online web digital
        systems
    ]])

    local DENY = { "google fiber", "freedom mobile" }

    local KEYWORDS = { "hosting", "datacent", "data cent", "cloud" }

    local NAMES = {
        "Zenlayer Inc",
        "Shenzhen Tencent Computer Systems Company Limited",
        "NETEASE (HONG KONG) LIMITED",
        "Datacamp Limited",
        "M247 Europe SRL",
        "Alibaba (US) Technology Co., Ltd.",
        "HUAWEI INTERNATIONAL PTE. LTD.",
        "SCALEWAY S.A.S.",
        "UAB Cherry Servers",
        "Byteplus Pte. Ltd.",
        "Clouvider Limited",
        "WorldStream B.V.",
        "OVH SAS",
        "Hangzhou Alibaba Advertising Co.,Ltd.",
        "Amazon.com, Inc.",
        "Bytedance Inc.",
        "Akamai Technologies, Inc.",
        "G-Core Labs S.A.",
        "SERVERS TECH FZCO",
        "DigitalOcean, LLC",
        "JSC TIMEWEB",
        "Leaseweb USA, Inc.",
        "Timeweb, LLP",
        "FIRST SERVER LIMITED",
        "Oracle Corporation",
        "AEZA INTERNATIONAL LTD",
        "Hetzner Online GmbH",
        "Scaleway SAS",
        "HOSTKEY B.V.",
        "Google LLC",
        "LeaseWeb Netherlands B.V.",
        "HOSTKEY",
        "Voxility LLP",
        "NForce Entertainment B.V.",
        "Leaseweb Canada Inc.",
        "JSC Selectel",
        "LEASEWEB SINGAPORE PTE. LTD.",
        "HIVELOCITY, Inc.",
        "Server Farm LLC",
        "Servers Australia Pty. Ltd",
        "Dedicated.com",
        "M247 UK Ltd",
        "Psychz Networks",
        "Beget LLC",
        "Servers.com, Inc.",
        "Microsoft Corporation",
        "M247 Ltd",
        "Contabo GmbH",
        "Mullvad VPN AB",
        "31173 Services AB",
        "Proton AG",
        "CDN77",
        "Aliyun Computing Co., Ltd",
    }

    local OPS = {}
    for i = 1, #NAMES do
        local words, core = {}, {}
        for w in NAMES[i]:lower():gmatch("[%a%d]+") do
            if not LEGAL[w] then
                words[#words + 1] = w
                if #w >= 3 and not GENERIC[w] and not GEO[w] then
                    core[#core + 1] = w
                end
            end
        end
        OPS[i] = { name = NAMES[i], words = words, core = core }
    end

    local function editDist(a, b, budget)
        local la, lb = #a, #b
        if la - lb > budget or lb - la > budget then return budget + 1 end
        local prev, cur = {}, {}
        for j = 0, lb do prev[j] = j end
        for i = 1, la do
            cur[0] = i
            local best, ca = i, a:byte(i)
            for j = 1, lb do
                local v = prev[j - 1] + ((ca == b:byte(j)) and 0 or 1)
                local d = prev[j] + 1
                if d < v then v = d end
                d = cur[j - 1] + 1
                if d < v then v = d end
                cur[j] = v
                if v < best then best = v end
            end
            if best > budget then return budget + 1 end
            prev, cur = cur, prev
        end
        return prev[lb]
    end

    local function tokenHit(want, tokens)
        local n = #want
        local budget = (n >= 12 and 2) or (n >= 5 and 1) or 0
        for i = 1, #tokens do
            local t = tokens[i]
            if t == want then return true end
            if budget > 0 and editDist(want, t, budget) <= budget then
                return true
            end
            if n >= 5 and #t > n and t:sub(1, n) == want
               and COMPOUND[t:sub(n + 1)] then
                return true
            end
        end
        return false
    end

    local function operatorFor(name)
        local tokens, padded = {}, " "
        for w in name:lower():gmatch("[%a%d]+") do
            tokens[#tokens + 1] = w
            padded = padded .. w .. " "
        end
        if #tokens == 0 then return nil end
        for i = 1, #DENY do
            if padded:find(" " .. DENY[i] .. " ", 1, true) then return nil end
        end
        for i = 1, #OPS do
            local op = OPS[i]
            local want, need = op.core, 1
            if #want == 0 then want, need = op.words, 2 end
            if #want >= need then
                local all = true
                for j = 1, #want do
                    if not tokenHit(want[j], tokens) then all = false; break end
                end
                if all then return op.name end
            end
        end
        for i = 1, #KEYWORDS do
            if padded:find(KEYWORDS[i], 1, true) then return name end
        end
        return nil
    end

    local memo = {}
    local function lookup(name)
        if not name or name == "" or name == "NA" then return nil end
        local v = memo[name]
        if v == nil then
            v = operatorFor(name) or false
            memo[name] = v
        end
        return v or nil
    end

    function KICKER.hostingOperator(ipInfo)
        return lookup(ipInfo["isp"]) or lookup(ipInfo["org"])
            or lookup(ipInfo["as"])
    end
end


local function detectVPN(playerId)
    local ipInfo = Players.GetIPInfo(playerId)
    if not ipInfo then
        return nil
    end

    local operator = KICKER.hostingOperator(ipInfo)
    if operator then return true, operator end

    local proxy = ipInfo["proxy"] or ""
    if proxy == "1" then return true, "Cherax proxy flag" end
    if proxy == "" or proxy == "NA" then return nil end
    return false
end

local function kickVPNPlayer(playerId, reason)
    if KICKER.isProtected(playerId) then
        vpnKicker.pending[playerId] = nil
        return
    end
    local name = Players.GetName(playerId) or "?"
    if not doKick(playerId) then
        vpnKicker.kicked[playerId] = true
        vpnKicker.pending[playerId] = nil
        return
    end

    VIBE_LOG_INFO(("[VibeScript] VPN Kicker: kicking %s (id %d): %s")
        :format(name, playerId, reason or "?"))
    GUI.AddToast("VibeScript",
        T("VPN Kicker: kicking %s"):format(name), 5000)

    vpnKicker.kicked[playerId] = true
    vpnKicker.pending[playerId] = nil
end

local function checkAndKickVPN(playerId)
    if playerId == GTA.GetLocalPlayerId() then return end
    if vpnKicker.kicked[playerId] then return end
    if KICKER.deferFreshJoin(vpnKicker, playerId) then return end
    if KICKER.isProtected(playerId) then return end

    local result, reason = detectVPN(playerId)
    if result == true then
        kickVPNPlayer(playerId, reason)
    elseif result == nil then
        if not vpnKicker.pending[playerId] then
            vpnKicker.pending[playerId] = {
                attempts = 0,
                nextCheck = os.clock() + KICKER.RETRY_DELAY,
            }
        end
    end
end

local function onVPNPlayerJoin(playerId)
    local feat = FeatureMgr.GetFeature(H.VPN_KICKER)
    if not feat or not feat:IsToggled() then return end
    vpnKicker.kicked[playerId] = nil
    vpnKicker.pending[playerId] = nil
    KICKER.noteJoin(playerId)
    checkAndKickVPN(playerId)
end

local function vpnKickerOnTick(f)
    if not f:IsToggled() then
        if vpnKicker.scanned or vpnKicker.eventId
           or next(vpnKicker.pending) or next(vpnKicker.kicked) then
            vpnKicker.kicked = {}
            vpnKicker.pending = {}
            vpnKicker.scanned = false
            if vpnKicker.eventId then
                EventMgr.RemoveHandler(vpnKicker.eventId)
                vpnKicker.eventId = nil
            end
        end
        return
    end

    if not vpnKicker.eventId then
        vpnKicker.eventId = EventMgr.RegisterHandler(
            eLuaEvent.ON_PLAYER_JOIN, onVPNPlayerJoin)
    end

    if not vpnKicker.scanned then
        vpnKicker.scanned = true
        local localId = GTA.GetLocalPlayerId()
        for pid = 0, 31 do
            if pid ~= localId and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                checkAndKickVPN(pid)
            end
        end
    end

    local now = os.clock()
    for pid, info in pairs(vpnKicker.pending) do
        if now >= info.nextCheck then
            if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                vpnKicker.pending[pid] = nil
            elseif KICKER.deferFreshJoin(vpnKicker, pid) then
            elseif KICKER.isProtected(pid) then
                vpnKicker.pending[pid] = nil
            else
                local result, reason = detectVPN(pid)
                if result == true then
                    kickVPNPlayer(pid, reason)
                elseif result == nil then
                    info.attempts = info.attempts + 1
                    if info.attempts >= KICKER.MAX_RETRIES then
                        logf("VPN Kicker: gave up on player %d after %d retries", pid, KICKER.MAX_RETRIES)
                        vpnKicker.pending[pid] = nil
                    else
                        info.nextCheck = now + KICKER.RETRY_DELAY
                    end
                else
                    vpnKicker.pending[pid] = nil
                end
            end
        end
    end
end

centralOnTick(FeatureMgr.AddFeature(H.VPN_KICKER, "VPN Kicker", eFeatureType.Toggle,
    "Kicks players using a VPN or proxy.",
    vpnKickerOnTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)


relayKicker.TYPE_NAMES = { "Relay Server", "Peer Relay" }
relayKicker.TYPE_INDEX = { [2] = 0, [3] = 1 }

relayKicker.mask = nil

function relayKicker.typeMask()
    local feat = FeatureMgr.GetFeature(H.RELAY_TYPES)
    if not feat then return (1 << #relayKicker.TYPE_NAMES) - 1 end
    local m = 0
    for i = 0, #relayKicker.TYPE_NAMES - 1 do
        if feat:IsListIndexToggled(i) then m = m | (1 << i) end
    end
    return m
end

local function detectRelay(playerId)
    local addr = Players.GetNetAddress(playerId)
    if not addr then
        return nil
    end
    local idx = relayKicker.TYPE_INDEX[addr.Type]
    if not idx then return false end
    local mask = relayKicker.mask or ((1 << #relayKicker.TYPE_NAMES) - 1)
    if mask & (1 << idx) == 0 then return false end
    return true, relayKicker.TYPE_NAMES[idx + 1]
end

local function kickRelayPlayer(playerId, label)
    if KICKER.isProtected(playerId) then
        relayKicker.pending[playerId] = nil
        return
    end
    local name = Players.GetName(playerId) or "?"
    if not doKick(playerId) then
        relayKicker.kicked[playerId] = true
        relayKicker.pending[playerId] = nil
        return
    end
    label = label or "relay"
    VIBE_LOG_INFO(("[VibeScript] Relay Kicker: kicking %s - %s (pid %d)")
        :format(name, label, playerId))
    GUI.AddToast("VibeScript",
        T("Relay Kicker: kicking %s"):format(name), 5000)

    relayKicker.kicked[playerId] = true
    relayKicker.pending[playerId] = nil
end

local function checkAndKickRelay(playerId)
    if playerId == GTA.GetLocalPlayerId() then return end
    if relayKicker.kicked[playerId] then return end
    if KICKER.deferFreshJoin(relayKicker, playerId) then return end
    if KICKER.isProtected(playerId) then return end

    local result, label = detectRelay(playerId)
    if result == true then
        kickRelayPlayer(playerId, label)
    elseif result == nil then
        if not relayKicker.pending[playerId] then
            relayKicker.pending[playerId] = {
                attempts = 0,
                nextCheck = os.clock() + KICKER.RETRY_DELAY,
            }
        end
    end
end

local function onRelayPlayerJoin(playerId)
    local feat = FeatureMgr.GetFeature(H.RELAY_KICKER)
    if not feat or not feat:IsToggled() then return end
    relayKicker.kicked[playerId] = nil
    relayKicker.pending[playerId] = nil
    KICKER.noteJoin(playerId)
    checkAndKickRelay(playerId)
end

local function relayKickerOnTick(f)
    if not f:IsToggled() then
        if relayKicker.scanned or relayKicker.eventId
           or next(relayKicker.pending) or next(relayKicker.kicked) then
            relayKicker.kicked = {}
            relayKicker.pending = {}
            relayKicker.scanned = false
            if relayKicker.eventId then
                EventMgr.RemoveHandler(relayKicker.eventId)
                relayKicker.eventId = nil
            end
        end
        return
    end

    if not relayKicker.eventId then
        relayKicker.eventId = EventMgr.RegisterHandler(
            eLuaEvent.ON_PLAYER_JOIN, onRelayPlayerJoin)
    end

    local mask = relayKicker.typeMask()
    if mask ~= relayKicker.mask then
        relayKicker.mask = mask
        relayKicker.scanned = false
    end

    if not relayKicker.scanned then
        relayKicker.scanned = true
        local localId = GTA.GetLocalPlayerId()
        for pid = 0, 31 do
            if pid ~= localId and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                checkAndKickRelay(pid)
            end
        end
    end

    local now = os.clock()
    for pid, info in pairs(relayKicker.pending) do
        if now >= info.nextCheck then
            if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                relayKicker.pending[pid] = nil
            elseif KICKER.deferFreshJoin(relayKicker, pid) then
            elseif KICKER.isProtected(pid) then
                relayKicker.pending[pid] = nil
            else
                local result, label = detectRelay(pid)
                if result == true then
                    kickRelayPlayer(pid, label)
                elseif result == nil then
                    info.attempts = info.attempts + 1
                    if info.attempts >= KICKER.MAX_RETRIES then
                        logf("Relay Kicker: gave up on player %d after %d retries", pid, KICKER.MAX_RETRIES)
                        relayKicker.pending[pid] = nil
                    else
                        info.nextCheck = now + KICKER.RETRY_DELAY
                    end
                else
                    relayKicker.pending[pid] = nil
                end
            end
        end
    end
end

centralOnTick(FeatureMgr.AddFeature(H.RELAY_KICKER, "Relay Kicker", eFeatureType.Toggle,
    "Kicks players connected via relay/peer relay. Pick which of the two counts below.",
    relayKickerOnTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)

FeatureMgr.AddFeature(H.RELAY_TYPES, "Connections", eFeatureType.ComboToggles,
    "Which relayed connections the kicker acts on. Relay Server routes through Rockstar; Peer Relay routes through another player. Both on is the old behavior; with neither selected the kicker does nothing.")
    :SetList(TLIST(relayKicker.TYPE_NAMES))
    :SetSaveable(false)
do
    local feat = FeatureMgr.GetFeature(H.RELAY_TYPES)
    for i = 0, #relayKicker.TYPE_NAMES - 1 do
        feat:ToggleListIndex(i, true)
    end
    relayKicker.typeCount = #relayKicker.TYPE_NAMES
end
VIBE_TR.trackList(H.RELAY_TYPES, relayKicker.TYPE_NAMES)


local census = {
    data = {},
    countries = {},
    lastRefresh = 0,
    REFRESH_INTERVAL = 5.0,
}

local CONN_TYPE_LABELS = {
    [1] = "Direct",
    [2] = "Relay",
    [3] = "Peer Relay",
}
for i = 1, 3 do VIBE_TR.reg(CONN_TYPE_LABELS[i]) end

local function getConnLabel(pid)
    local addr = Players.GetNetAddress(pid)
    if not addr then return "?" end
    local t = addr.Type
    local lbl = CONN_TYPE_LABELS[t]
    return lbl and T(lbl) or T("Type %d"):format(t)
end

local function refreshCensus()
    local now = os.clock()
    if now - census.lastRefresh < census.REFRESH_INTERVAL then return end
    census.lastRefresh = now

    local players = {}
    local countryMap = {}
    local localId = GTA.GetLocalPlayerId()

    for pid = 0, 31 do
        if NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
            local name = Players.GetName(pid) or "?"
            local country, region, city = "Unknown", "", ""
            local ipInfo = Players.GetIPInfo(pid)
            if ipInfo then
                local cc = ipInfo["country"] or ""
                if cc ~= "" and cc ~= "NA" then country = cc end
                local r = ipInfo["region"] or ""
                if r ~= "" and r ~= "NA" then region = r end
                local ci = ipInfo["city"] or ""
                if ci ~= "" and ci ~= "NA" then city = ci end
            end
            local connLabel = getConnLabel(pid)
            local vpn = false
            if ipInfo then
                vpn = (ipInfo["proxy"] == "1")
            end
            if pid == localId then name = T("%s (you)"):format(name) end
            table.insert(players, {
                name = name, country = country,
                region = region, city = city,
                conn = connLabel, vpn = vpn,
            })
            countryMap[country] = (countryMap[country] or 0) + 1
        end
    end

    local sorted = {}
    for cname, count in pairs(countryMap) do
        table.insert(sorted, {name = cname, count = count})
    end
    table.sort(sorted, function(a, b) return a.count > b.count end)

    census.data = players
    census.countries = sorted
end

local function sliceColor(index, total)
    local h = ((index - 1) / math.max(total, 1)) % 1.0
    return ImGui.ColorConvertHSVtoRGB(h, 0.65, 0.90)
end

local function sliceColorInt(index, total)
    local r, g, b = sliceColor(index, total)
    return math.floor(r * 255 + 0.5), math.floor(g * 255 + 0.5), math.floor(b * 255 + 0.5)
end

local function drawPieChart(cx, cy, radius, slices, totalPlayers)
    if #slices == 0 then return end
    if totalPlayers == 0 then return end

    local startAngle = -math.pi / 2
    local segments = 64

    for i, s in ipairs(slices) do
        local sweep = (s.count / totalPlayers) * 2 * math.pi
        local numSegs = math.max(2, math.floor(segments * (sweep / (2 * math.pi)) + 0.5))
        local step = sweep / numSegs
        local ri, gi, bi = sliceColorInt(i, #slices)

        for seg = 0, numSegs - 1 do
            local a1 = startAngle + seg * step
            local a2 = startAngle + (seg + 1) * step + 0.02
            ImGui.AddTriangleFilled(
                cx, cy,
                cx + radius * math.cos(a1), cy + radius * math.sin(a1),
                cx + radius * math.cos(a2), cy + radius * math.sin(a2),
                ri, gi, bi, 255)
        end
        startAngle = startAngle + sweep
    end

    ImGui.AddCircle(cx, cy, radius, 180, 180, 180, 200, 64, 1.0)
end

local function renderCensusPie()
    refreshCensus()

    if #census.data == 0 then
        ImGui.TextDisabled(T("No players in session"))
        return
    end

    local total = #census.data
    local PIE_RADIUS = 55
    local ELBOW_LEN = 12
    local HORIZ_LEN = 18
    local LINE_H = 14

    local avail_x, _ = ImGui.GetContentRegionAvail()
    local sx, sy = ImGui.GetCursorScreenPos()
    local cx = sx + avail_x / 2
    local TOP_PAD = ELBOW_LEN + LINE_H
    local cy = sy + PIE_RADIUS + TOP_PAD

    drawPieChart(cx, cy, PIE_RADIUS, census.countries, total)

    local leftLabels = {}
    local rightLabels = {}
    local startAngle = -math.pi / 2
    for i, entry in ipairs(census.countries) do
        local sweep = (entry.count / total) * 2 * math.pi
        local midAngle = startAngle + sweep / 2
        local ri, gi, bi = sliceColorInt(i, #census.countries)
        local pct = math.floor((entry.count / total) * 100 + 0.5)
        local label = T("%s %d (%d%%)"):format(T(entry.name), entry.count, pct)

        local info = {
            midAngle = midAngle,
            edgeX = cx + PIE_RADIUS * math.cos(midAngle),
            edgeY = cy + PIE_RADIUS * math.sin(midAngle),
            naturalY = cy + (PIE_RADIUS + ELBOW_LEN) * math.sin(midAngle),
            ri = ri, gi = gi, bi = bi,
            label = label,
        }
        if math.cos(midAngle) >= 0 then
            table.insert(rightLabels, info)
        else
            table.insert(leftLabels, info)
        end
        startAngle = startAngle + sweep
    end

    local function spreadLabels(labels)
        table.sort(labels, function(a, b) return a.naturalY < b.naturalY end)
        for j = 1, #labels do
            labels[j].drawY = labels[j].naturalY
        end
        for j = 2, #labels do
            if labels[j].drawY - labels[j - 1].drawY < LINE_H then
                labels[j].drawY = labels[j - 1].drawY + LINE_H
            end
        end
    end
    spreadLabels(leftLabels)
    spreadLabels(rightLabels)

    for _, info in ipairs(rightLabels) do
        local elbowX = cx + (PIE_RADIUS + ELBOW_LEN) * math.cos(info.midAngle)
        local horizEndX = elbowX + HORIZ_LEN
        ImGui.AddLine(info.edgeX, info.edgeY, elbowX, info.drawY,
            info.ri, info.gi, info.bi, 255, 1.0)
        ImGui.AddLine(elbowX, info.drawY, horizEndX, info.drawY,
            info.ri, info.gi, info.bi, 255, 1.0)
        ImGui.AddText(horizEndX + 3, info.drawY - LINE_H / 2,
            info.label, info.ri, info.gi, info.bi, 255)
    end

    for _, info in ipairs(leftLabels) do
        local elbowX = cx + (PIE_RADIUS + ELBOW_LEN) * math.cos(info.midAngle)
        local horizEndX = elbowX - HORIZ_LEN
        ImGui.AddLine(info.edgeX, info.edgeY, elbowX, info.drawY,
            info.ri, info.gi, info.bi, 255, 1.0)
        ImGui.AddLine(elbowX, info.drawY, horizEndX, info.drawY,
            info.ri, info.gi, info.bi, 255, 1.0)
        local tw, _ = ImGui.CalcTextSize(info.label)
        ImGui.AddText(horizEndX - tw - 3, info.drawY - LINE_H / 2,
            info.label, info.ri, info.gi, info.bi, 255)
    end

    ImGui.Dummy(avail_x, (PIE_RADIUS + TOP_PAD) * 2)
end
local function renderCensusPlayers()
    if #census.data == 0 then return end
    local total = #census.data
    ImGui.Text(T("Players (%d):"):format(total))
    for _, p in ipairs(census.data) do
        local loc = T(p.country)
        if p.region ~= "" then loc = loc .. ", " .. p.region end
        if p.city ~= "" then loc = loc .. ", " .. p.city end
        local tags = p.conn
        if p.vpn then tags = T("%s, VPN"):format(tags) end
        ImGui.BulletText(T("%s - %s (%s)"):format(p.name, loc, tags))
    end
end


local function rewindAddSnapshot(snap)
    rewindState.head = (rewindState.head % rewindState.maxSnapshots) + 1
    rewindState.snapshots[rewindState.head] = snap
    if rewindState.count < rewindState.maxSnapshots then
        rewindState.count = rewindState.count + 1
    end
end

local function rewindGetSnapshot(stepsBack)
    if stepsBack < 0 or stepsBack >= rewindState.count then return nil end
    local idx = rewindState.head - stepsBack
    if idx < 1 then idx = idx + rewindState.maxSnapshots end
    return rewindState.snapshots[idx]
end

function rewindState.lerpAngle(a, b, t)
    local d = (b - a) % 360
    if d > 180 then d = d - 360 end
    return a + d * t
end

function rewindState.colliderSpin(entity)
    local a = ENTITY.GET_ENTITY_ROTATION_VELOCITY(entity)
    local buf = rewindState.matrixBuf
    ENTITY.GET_ENTITY_MATRIX(entity, buf, buf + 24, buf + 48, buf + 72)
    local fx, fy, fz = Memory.ReadFloat(buf), Memory.ReadFloat(buf + 8), Memory.ReadFloat(buf + 16)
    local sx, sy, sz = Memory.ReadFloat(buf + 24), Memory.ReadFloat(buf + 32), Memory.ReadFloat(buf + 40)
    local ux, uy, uz = Memory.ReadFloat(buf + 48), Memory.ReadFloat(buf + 56), Memory.ReadFloat(buf + 64)
    return a.x * sx + a.y * sy + a.z * sz,
        a.x * fx + a.y * fy + a.z * fz,
        a.x * ux + a.y * uy + a.z * uz
end


function rewindState.ptrOk(p)
    return p > 0x10000 and p < 0x7FFFFFFFFFFF
end

function rewindState.vehAddr(veh)
    if veh ~= rewindState._addrHandle then
        local phys = GTA.HandleToPointer(veh)
        rewindState._addr = phys and phys:GetAddress() or 0
        rewindState._addrHandle = veh
    end
    return rewindState._addr
end

function rewindState.wheelPtrs(addr, out)
    if not rewindState.ptrOk(addr) then return 0 end
    local n = Memory.ReadInt(addr + rewindState.OFF_NUM_WHEELS)
    if n < 1 or n > rewindState.MAX_WHEELS then return 0 end
    local arr = Memory.ReadLong(addr + rewindState.OFF_WHEELS)
    if not rewindState.ptrOk(arr) then return 0 end
    for i = 1, n do
        local w = Memory.ReadLong(arr + (i - 1) * 8)
        if not rewindState.ptrOk(w)
            or Memory.ReadLong(w + rewindState.OFF_WHEEL_PARENT) ~= addr then
            return 0
        end
        out[i] = w
    end
    return n
end

function rewindState.readRevs(veh, addr)
    local rev = Natives.InvokeFloat(rewindState.H_GET_REV_RATIO, veh)
    if not rewindState.revFieldOk and rev > 0.25 and rev < 0.999 and rewindState.ptrOk(addr) then
        local field = Memory.ReadFloat(addr + rewindState.OFF_REV_RATIO)
        if field == rev then
            rewindState.revFieldOk = true
            logf("[Rewind] rev ratio field verified at +0x%X (%.4f)", rewindState.OFF_REV_RATIO, rev)
        elseif not rewindState.revMismatchLogged then
            rewindState.revMismatchLogged = true
            logf("[Rewind] rev ratio field at +0x%X reads %.4f, getter %.4f - rev restore off",
                rewindState.OFF_REV_RATIO, field, rev)
        end
    end
    return rev
end

function rewindState.restoreDrivetrain(veh, snap)
    local addr = rewindState.vehAddr(veh)
    local wheels, written = snap.wheels, 0
    if wheels then
        local ptrs = rewindState._wheelScratch
        if rewindState.wheelPtrs(addr, ptrs) == #wheels then
            for i = 1, #wheels do
                local w = wheels[i]
                if w == w and w > -1e4 and w < 1e4 then
                    Memory.WriteFloat(ptrs[i] + rewindState.OFF_WHEEL_SPIN, w)
                    written = written + 1
                end
            end
        end
    end
    local revWritten = false
    if rewindState.revFieldOk and snap.rev > 0 and rewindState.ptrOk(addr)
        and Memory.ReadFloat(addr + rewindState.OFF_REV_RATIO)
            == Natives.InvokeFloat(rewindState.H_GET_REV_RATIO, veh) then
        Memory.WriteFloat(addr + rewindState.OFF_REV_RATIO, snap.rev)
        revWritten = true
    end
    logf("[Rewind] drivetrain wheels %d/%d rev %.3f %s",
        written, wheels and #wheels or 0, snap.rev, revWritten and "written" or "skipped")
end


function rewindState.vehCaps(veh)
    local V, cls = rewindState.VH, VEHICLE.GET_VEHICLE_CLASS(veh)
    local caps = {
        model   = ENTITY.GET_ENTITY_MODEL(veh),
        heli    = cls == 15,
        plane   = cls == 16,
        gear    = Natives.InvokeBool(V.HAS_LANDING_GEAR, veh),
        retract = Natives.InvokeBool(V.HAS_RETRACT, veh),
        roof    = Natives.InvokeBool(V.IS_CONVERTIBLE, veh, false),
        rocket  = Natives.InvokeBool(V.HAS_ROCKET, veh),
        doors   = {},
    }
    for d = 0, 6 do
        if Natives.InvokeBool(V.DOOR_VALID, veh, d) then caps.doors[#caps.doors + 1] = d end
    end
    return caps
end

function rewindState.sampleVehState(veh, caps, prev)
    local V, s = rewindState.VH, { model = caps.model }
    if caps.gear then s.gear = Natives.InvokeInt(V.GET_LANDING_GEAR, veh) end
    if caps.plane or caps.heli then s.bombBay = Natives.InvokeBool(V.BOMB_BAY_OPEN, veh) end
    if caps.heli then s.wings = Natives.InvokeBool(V.WINGS_DEPLOYED, veh) end
    if caps.plane then
        local n = Natives.InvokeFloat(V.GET_NOZZLE, veh)
        s.nozzle = n
        local p = prev and prev.nozzle
        if p and n > p + 0.001 then s.nozzleDest = 1.0
        elseif p and n < p - 0.001 then s.nozzleDest = 0.0
        else s.nozzleDest = n >= 0.5 and 1.0 or 0.0 end
    end
    if caps.retract then s.retracted = Natives.InvokeBool(V.WHEELS_RETRACTED, veh) end
    if caps.roof then s.roof = Natives.InvokeInt(V.ROOF_STATE, veh) end
    if caps.rocket then s.rocket = Natives.InvokeBool(V.ROCKET_ON, veh) end
    s.sub         = Natives.InvokeBool(V.IN_SUB_MODE, veh)
    s.siren       = Natives.InvokeBool(V.SIREN_ON, veh)
    s.engine      = Natives.InvokeBool(V.ENGINE_ON, veh)
    s.nitrous     = Natives.InvokeBool(V.NITROUS_ON, veh)
    s.nitrousLeft = Natives.InvokeFloat(V.NITROUS_LEFT, veh)
    local b = rewindState.lightBuf
    Memory.WriteInt(b, 0); Memory.WriteInt(b + 8, 0)
    Natives.InvokeBool(V.LIGHTS_STATE, veh, b, b + 8)
    s.fullBeam = Memory.ReadInt(b + 8) ~= 0
    if #caps.doors > 0 then
        s.doors = {}
        for i, d in ipairs(caps.doors) do s.doors[i] = Natives.InvokeFloat(V.DOOR_RATIO, veh, d) end
    end
    return s
end

function rewindState.restoreVehState(veh, s)
    if not s or ENTITY.GET_ENTITY_MODEL(veh) ~= s.model then return end
    local caps = rewindState._vsHandle == veh and rewindState._vsCaps or rewindState.vehCaps(veh)
    local now = rewindState.sampleVehState(veh, caps, nil)
    local V, changed = rewindState.VH, {}
    local function did(name) changed[#changed + 1] = name end

    if s.sub ~= now.sub then
        Natives.InvokeVoid(s.sub and V.TO_SUB or V.TO_CAR, veh, true)
        did("sub")
    end
    if s.gear and now.gear and s.gear ~= 5 and now.gear ~= 5 then
        local wantUp = s.gear == 1 or s.gear == 2 or s.gear == 4
        local isUp = now.gear == 1 or now.gear == 2 or now.gear == 4
        if wantUp ~= isUp then
            Natives.InvokeVoid(V.CONTROL_LANDING_GEAR, veh, wantUp and 3 or 2)
            did("gear")
        end
    end
    if s.bombBay ~= nil and s.bombBay ~= now.bombBay then
        Natives.InvokeVoid(s.bombBay and V.OPEN_BOMB_BAY or V.CLOSE_BOMB_BAY, veh)
        did("bombbay")
    end
    if s.wings ~= nil and s.wings ~= now.wings then
        Natives.InvokeVoid(V.DEPLOY_WINGS, veh, s.wings, true)
        did("wings")
    end
    if s.nozzle and now.nozzle and math.abs(s.nozzle - now.nozzle) > 0.01 then
        Natives.InvokeVoid(V.SET_NOZZLE_NOW, veh, s.nozzle + 0.0)
        Natives.InvokeVoid(V.SET_NOZZLE, veh, s.nozzleDest + 0.0)
        did("nozzle")
    end
    if s.retracted ~= nil and s.retracted ~= now.retracted then
        Natives.InvokeVoid(s.retracted and V.RETRACT_WHEELS or V.EXTEND_WHEELS, veh)
        did("wheels")
    end
    if s.roof and now.roof and s.roof <= 3 and now.roof <= 3 then
        local wantDown = s.roof == 1 or s.roof == 2
        if wantDown ~= (now.roof == 1 or now.roof == 2) then
            Natives.InvokeVoid(wantDown and V.LOWER_ROOF or V.RAISE_ROOF, veh, true)
            did("roof")
        end
    end
    if s.engine ~= now.engine then
        Natives.InvokeVoid(V.SET_ENGINE, veh, s.engine, true, false)
        did("engine")
    end
    if s.siren ~= now.siren then
        Natives.InvokeVoid(V.SET_SIREN, veh, s.siren)
        did("siren")
    end
    if s.fullBeam ~= now.fullBeam then
        Natives.InvokeVoid(V.SET_FULLBEAM, veh, s.fullBeam)
        did("highbeam")
    end
    if math.abs(s.nitrousLeft - now.nitrousLeft) > 0.01 then
        Natives.InvokeVoid(V.SET_NITROUS_LEFT, veh, s.nitrousLeft + 0.0)
        did("nitrous-left")
    end
    if s.nitrous ~= now.nitrous then
        Natives.InvokeVoid(V.SET_NITROUS_ON, veh, s.nitrous)
        did("nitrous")
    end
    if s.rocket ~= nil and s.rocket ~= now.rocket then
        Natives.InvokeVoid(V.SET_ROCKET_ON, veh, s.rocket)
        did("rocket")
    end
    if s.doors and now.doors and #s.doors == #now.doors then
        for i, d in ipairs(caps.doors) do
            local wasOpen = s.doors[i] > 0.1
            if wasOpen ~= (now.doors[i] > 0.1) and not Natives.InvokeBool(V.DOOR_DAMAGED, veh, d) then
                if wasOpen then
                    Natives.InvokeVoid(V.DOOR_OPEN, veh, d, true, false)
                else
                    Natives.InvokeVoid(V.DOOR_SHUT, veh, d, true)
                end
                did("door" .. d)
            end
        end
    end
    logf("[Rewind] vehicle state restored: %s", #changed > 0 and table.concat(changed, " ") or "none")
end

rewindState._blend = { pos = {}, rot = {}, vel = {}, angVel = {} }

function rewindState.sampleAt(ph)
    local i = math.floor(ph)
    local a = rewindGetSnapshot(i)
    if not a then return nil end
    local t = ph - i
    if t <= 0.001 then return a end
    local b = rewindGetSnapshot(i + 1)
    if not b or a.inVeh ~= b.inVeh or a.vehHandle ~= b.vehHandle
        or a.vehModel ~= b.vehModel or a.seat ~= b.seat then
        return a
    end

    local o = rewindState._blend
    o.pos.x = a.pos.x + (b.pos.x - a.pos.x) * t
    o.pos.y = a.pos.y + (b.pos.y - a.pos.y) * t
    o.pos.z = a.pos.z + (b.pos.z - a.pos.z) * t
    o.rot.x = rewindState.lerpAngle(a.rot.x, b.rot.x, t)
    o.rot.y = rewindState.lerpAngle(a.rot.y, b.rot.y, t)
    o.rot.z = rewindState.lerpAngle(a.rot.z, b.rot.z, t)
    o.vel.x = a.vel.x + (b.vel.x - a.vel.x) * t
    o.vel.y = a.vel.y + (b.vel.y - a.vel.y) * t
    o.vel.z = a.vel.z + (b.vel.z - a.vel.z) * t
    o.angVel.x = a.angVel.x + (b.angVel.x - a.angVel.x) * t
    o.angVel.y = a.angVel.y + (b.angVel.y - a.angVel.y) * t
    o.angVel.z = a.angVel.z + (b.angVel.z - a.angVel.z) * t
    o.camH = rewindState.lerpAngle(a.camH, b.camH, t)
    o.camP = a.camP + (b.camP - a.camP) * t
    o.rev  = a.rev + (b.rev - a.rev) * t
    o.vs   = a.vs
    local aw, bw = a.wheels, b.wheels
    if aw and bw and #aw == #bw then
        local ow = rewindState._blendWheels
        for k = 1, #aw do ow[k] = aw[k] + (bw[k] - aw[k]) * t end
        for k = #aw + 1, rewindState.MAX_WHEELS do ow[k] = nil end
        o.wheels = ow
    else
        o.wheels = aw
    end
    o.inVeh     = a.inVeh
    o.vehHandle = a.vehHandle
    o.vehModel  = a.vehModel
    o.seat      = a.seat
    return o
end

local function rewindCapture()
    local playerId = GTA.GetLocalPlayerId()
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
    if not ENTITY.DOES_ENTITY_EXIST(ped) then return nil end

    local inVeh = PED.IS_PED_IN_ANY_VEHICLE(ped, false)
    local entity = ped
    local vehHandle, vehModel, seat = 0, 0, -1

    if inVeh then
        local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
        if veh ~= 0 and ENTITY.DOES_ENTITY_EXIST(veh) then
            entity = veh
            vehHandle = veh
            vehModel = ENTITY.GET_ENTITY_MODEL(veh)
            for s = -1, VEHICLE.GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS(veh) - 1 do
                if VEHICLE.GET_PED_IN_VEHICLE_SEAT(veh, s, false) == ped then
                    seat = s
                    break
                end
            end
        end
    end

    local c = ENTITY.GET_ENTITY_COORDS(entity, true)
    local r = ENTITY.GET_ENTITY_ROTATION(entity, 2)
    local v = ENTITY.GET_ENTITY_VELOCITY(entity)
    local ax, ay, az = rewindState.colliderSpin(entity)

    local rev, wheels = 0, nil
    if vehHandle ~= 0 then
        local addr = rewindState.vehAddr(vehHandle)
        rev = rewindState.readRevs(vehHandle, addr)
        local ptrs = rewindState._wheelScratch
        local n = rewindState.wheelPtrs(addr, ptrs)
        if n > 0 then
            wheels = {}
            for i = 1, n do
                wheels[i] = Memory.ReadFloat(ptrs[i] + rewindState.OFF_WHEEL_SPIN)
            end
        end
    end

    local vs = nil
    if vehHandle ~= 0 then
        if vehHandle ~= rewindState._vsHandle then
            rewindState._vsHandle = vehHandle
            rewindState._vsCaps = rewindState.vehCaps(vehHandle)
            rewindState._vsLast = nil
            rewindState._vsNextMs = 0
        end
        local nowMs = MISC.GET_GAME_TIMER()
        if nowMs >= rewindState._vsNextMs then
            rewindState._vsNextMs = nowMs + rewindState.VS_SAMPLE_MS
            rewindState._vsLast = rewindState.sampleVehState(vehHandle,
                rewindState._vsCaps, rewindState._vsLast)
        end
        vs = rewindState._vsLast
    end

    return {
        pos    = { x = c.x, y = c.y, z = c.z },
        rot    = { x = r.x, y = r.y, z = r.z },
        vel    = { x = v.x, y = v.y, z = v.z },
        angVel = { x = ax, y = ay, z = az },
        camH   = CAM.GET_GAMEPLAY_CAM_RELATIVE_HEADING(),
        camP   = CAM.GET_GAMEPLAY_CAM_RELATIVE_PITCH(),
        inVeh  = inVeh,
        vehHandle = vehHandle,
        vehModel  = vehModel,
        seat      = seat,
        rev       = rev,
        wheels    = wheels,
        vs        = vs,
    }
end

local function rewindLoadSnapshot(snap)
    if not snap then return end
    local playerId = GTA.GetLocalPlayerId()
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
    if not ENTITY.DOES_ENTITY_EXIST(ped) then return end

    local currentlyInVeh = PED.IS_PED_IN_ANY_VEHICLE(ped, false)

    if snap.inVeh then
        if rewindState._walkAnimPlaying then
            do
                TASK.CLEAR_PED_TASKS_IMMEDIATELY(ped)
                if STREAMING.HAS_ANIM_DICT_LOADED("mini@strip_club@walk") then
                    STREAMING.REMOVE_ANIM_DICT("mini@strip_club@walk")
                end
            end
            rewindState._walkAnimPlaying = false
        end

        local veh = snap.vehHandle
        local valid = veh ~= 0 and ENTITY.DOES_ENTITY_EXIST(veh)
            and ENTITY.GET_ENTITY_MODEL(veh) == snap.vehModel
        if not valid then
            veh = GTA.CreateVehicle(snap.vehModel,
                snap.pos.x, snap.pos.y, snap.pos.z, 0.0, true, false)
            if veh == 0 then
                ENTITY.SET_ENTITY_COORDS_NO_OFFSET(ped,
                    snap.pos.x, snap.pos.y, snap.pos.z, false, false, false)
                ENTITY.SET_ENTITY_ROTATION(ped, snap.rot.x, snap.rot.y, snap.rot.z, 2, true)
                return
            end
        end
        ENTITY.SET_ENTITY_COORDS_NO_OFFSET(veh,
            snap.pos.x, snap.pos.y, snap.pos.z, false, false, false)
        ENTITY.SET_ENTITY_ROTATION(veh, snap.rot.x, snap.rot.y, snap.rot.z, 2, true)
        ENTITY.SET_ENTITY_VELOCITY(veh, 0.0, 0.0, 0.0)
        ENTITY.FREEZE_ENTITY_POSITION(veh, true)
        rewindState.frozenEntity = veh
        if ENTITY.DOES_ENTITY_EXIST(veh) and not currentlyInVeh then
            TASK.CLEAR_PED_TASKS_IMMEDIATELY(ped)
            ENTITY.FREEZE_ENTITY_POSITION(veh, false)
            PED.SET_PED_INTO_VEHICLE(ped, veh, snap.seat)
            ENTITY.FREEZE_ENTITY_POSITION(veh, true)
        end
    else
        if currentlyInVeh then
            TASK.CLEAR_PED_TASKS_IMMEDIATELY(ped)
            ENTITY.SET_ENTITY_COORDS_NO_OFFSET(ped,
                snap.pos.x, snap.pos.y, snap.pos.z, false, false, false)
        end
        local c = ENTITY.GET_ENTITY_COORDS(ped, true)
        local dx = snap.pos.x - c.x
        local dy = snap.pos.y - c.y
        local dz = snap.pos.z - c.z
        local dist = math.sqrt(dx * dx + dy * dy + dz * dz)

        local spd = math.max(rewindState.REWIND_SPEED, 1.0)
        if dist > 5.0 * spd then
            ENTITY.SET_ENTITY_COORDS_NO_OFFSET(ped,
                snap.pos.x, snap.pos.y, snap.pos.z, false, false, false)
            rewindState._walkAnimPlaying = false
        elseif dist > 0.01 then
            local speed = math.min(dist / math.max(rewindState._dtSec, 0.001), 4.0 * spd)
            local nx, ny, nz = dx / dist, dy / dist, dz / dist
            ENTITY.SET_ENTITY_VELOCITY(ped, nx * speed, ny * speed, nz * speed)
        else
            ENTITY.SET_ENTITY_VELOCITY(ped, 0.0, 0.0, 0.0)
        end
        ENTITY.SET_ENTITY_HEADING(ped, snap.rot.z)

        if not rewindState._walkAnimPlaying then
            local dict = "mini@strip_club@walk"
            if not STREAMING.HAS_ANIM_DICT_LOADED(dict) then
                STREAMING.REQUEST_ANIM_DICT(dict)
            else
                TASK.TASK_PLAY_ANIM(ped, dict, "walk",
                    2.0, -2.0, -1, 1, 0.0, false, false, false)
                rewindState._walkAnimPlaying = true
            end
        end
        rewindState.frozenEntity = ped
    end

    CAM.SET_GAMEPLAY_CAM_RELATIVE_HEADING(snap.camH)
    CAM.SET_GAMEPLAY_CAM_RELATIVE_PITCH(snap.camP, 1.0)
end

local function rewindDrawHUD()
    local pct = rewindState.playhead / math.max(1, rewindState.count)

    local barW, barH = 0.25, 0.005
    local barX, barY = 0.5, 0.05

    GRAPHICS.DRAW_RECT(barX, barY, barW, barH, 0, 0, 0, 150, false)

    local fillW = barW * pct
    local fillX = barX - (barW - fillW) * 0.5
    GRAPHICS.DRAW_RECT(fillX, barY, fillW, barH, 255, 200, 50, 220, false)

    local cursorX = barX - barW * 0.5 + barW * pct
    GRAPHICS.DRAW_RECT(cursorX, barY, 0.004, 0.012, 255, 255, 255, 255, false)
end

local function rewindCancel()
    if rewindState.frozenEntity ~= 0 then
        do
            if ENTITY.DOES_ENTITY_EXIST(rewindState.frozenEntity) then
                ENTITY.FREEZE_ENTITY_POSITION(rewindState.frozenEntity, false)
            end
        end
        rewindState.frozenEntity = 0
    end
    if not rewindState._unloading then
        do
            local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
            if not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
                TASK.CLEAR_PED_TASKS_IMMEDIATELY(ped)
                ENTITY.SET_ENTITY_VELOCITY(ped, 0.0, 0.0, 0.0)
            end
        end
    end
    rewindState._walkAnimPlaying = false
    do
        if STREAMING.HAS_ANIM_DICT_LOADED("mini@strip_club@walk") then
            STREAMING.REMOVE_ANIM_DICT("mini@strip_club@walk")
        end
    end
    if rewindState.soundId ~= -1 then
        do
            AUDIO.STOP_SOUND(rewindState.soundId)
            AUDIO.RELEASE_SOUND_ID(rewindState.soundId)
        end
        rewindState.soundId = -1
    end
    do
        GRAPHICS.CLEAR_TIMECYCLE_MODIFIER()
    end
    rewindState.state = 0
    rewindState.playhead = 0
    rewindState._lastPlayMs = nil
    rewindState._nextCaptureMs = 0
end

local function rewindClearBuffer()
    rewindState.snapshots = {}
    rewindState.head = 0
    rewindState.count = 0
    rewindState.playhead = 0
    rewindState._nextCaptureMs = 0
end

local function rewindIsRemoteHeld()
    local feat = FeatureMgr.GetFeature(H.REWIND_REMOTE_HOLD)
    if not feat then return false end
    return feat:IsToggled() or false
end

local function rewindForceRemoteHoldOff()
    local feat = FeatureMgr.GetFeature(H.REWIND_REMOTE_HOLD)
    if not feat then return end
    if feat:IsToggled() then
        feat:Toggle(false)
    end
end

local function rewindOnTick(f)
    if not f:IsToggled() then
        if rewindState.state ~= 0 then
            rewindCancel()
        end
        if rewindState.count > 0 then
            rewindClearBuffer()
        end
        return
    end
    if not isPlayerReady() then
        if rewindState.state ~= 0 then rewindCancel() end
        return
    end
    if NETWORK.NETWORK_IS_IN_SPECTATOR_MODE() then
        if rewindState.state ~= 0 then rewindCancel() end
        return
    end

    local playerId = GTA.GetLocalPlayerId()
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)

    if PED.IS_PED_INJURED(ped) then
        if rewindState.state ~= 0 then rewindCancel() end
        return
    end

    do
        local kf = FeatureMgr.GetFeature(H.REWIND_KEY)
        if kf then
            local fv = kf:GetIntValue()
            if fv >= 1 and fv <= 255 then rewindState.rewindVK = fv end
        end
    end

    local keyDown
    if PAD.IS_USING_KEYBOARD_AND_MOUSE(2) then
        keyDown = isAnyKeyDown(rewindState.rewindVK) and not GUI.IsOpen() and not isGameChatOpen()
    else
        keyDown = rewindState.controlId > 0
            and PAD.IS_DISABLED_CONTROL_PRESSED(0, rewindState.controlId)
    end
    keyDown = keyDown or rewindIsRemoteHeld()

    if rewindState.state == 0 then
        local nowMs = MISC.GET_GAME_TIMER()
        if nowMs >= rewindState._nextCaptureMs then
            local due = rewindState._nextCaptureMs + rewindState.CAPTURE_MS
            if due <= nowMs then due = nowMs + rewindState.CAPTURE_MS end
            rewindState._nextCaptureMs = due
            local snap = rewindCapture()
            if snap then rewindAddSnapshot(snap) end
        end

        if keyDown and rewindState.count > 1 then
            rewindState.state = 1
            rewindState.playhead = 0
            rewindState._lastPlayMs = nil

            do
                rewindState.soundId = AUDIO.GET_SOUND_ID()
                AUDIO.PLAY_SOUND(rewindState.soundId,
                    "CHARACTER_CHANGE_DPAD_DOWN_MASTER",
                    "PLAYER_SWITCH_CUSTOM_SOUNDSET", true, 0, true)
                GRAPHICS.SET_TIMECYCLE_MODIFIER("NG_deathfail")
                GRAPHICS.SET_TIMECYCLE_MODIFIER_STRENGTH(0.6)
            end
        end
        return
    end

    if rewindState.state == 1 then
        if not keyDown then
            rewindState.state = 2
            rewindState.settleStart = MISC.GET_GAME_TIMER()
            if rewindState.soundId ~= -1 then
                do
                    AUDIO.STOP_SOUND(rewindState.soundId)
                    AUDIO.RELEASE_SOUND_ID(rewindState.soundId)
                end
                rewindState.soundId = -1
            end
            return
        end

        local nowMs = MISC.GET_GAME_TIMER()
        local dtMs = nowMs - (rewindState._lastPlayMs or nowMs)
        rewindState._lastPlayMs = nowMs
        if dtMs < 0 then dtMs = 0 elseif dtMs > 100 then dtMs = 100 end
        rewindState._dtSec = dtMs / 1000.0
        rewindState.playhead = math.min(
            rewindState.playhead
                + rewindState.REWIND_SPEED * dtMs / rewindState.CAPTURE_MS,
            rewindState.count - 1)

        rewindLoadSnapshot(rewindState.sampleAt(rewindState.playhead))
        rewindDrawHUD()
        return
    end

    if rewindState.state == 2 then
        rewindDrawHUD()

        if keyDown then
            rewindState.state = 1
            rewindState._lastPlayMs = nil
            do
                rewindState.soundId = AUDIO.GET_SOUND_ID()
                AUDIO.PLAY_SOUND(rewindState.soundId,
                    "CHARACTER_CHANGE_DPAD_DOWN_MASTER",
                    "PLAYER_SWITCH_CUSTOM_SOUNDSET", true, 0, true)
            end
            return
        end

        local elapsed = MISC.GET_GAME_TIMER() - rewindState.settleStart
        if elapsed < rewindState.SETTLE_MS then return end

        local snap = rewindState.sampleAt(rewindState.playhead)
        if snap and rewindState.frozenEntity ~= 0
            and ENTITY.DOES_ENTITY_EXIST(rewindState.frozenEntity) then
            if ENTITY.IS_ENTITY_A_PED(rewindState.frozenEntity)
                and not PED.IS_PED_IN_ANY_VEHICLE(rewindState.frozenEntity, false) then
                TASK.CLEAR_PED_TASKS_IMMEDIATELY(rewindState.frozenEntity)
                ENTITY.SET_ENTITY_VELOCITY(rewindState.frozenEntity,
                    snap.vel.x, snap.vel.y, snap.vel.z)
                ENTITY.SET_ENTITY_ANGULAR_VELOCITY(rewindState.frozenEntity,
                    snap.angVel.x, snap.angVel.y, snap.angVel.z)
            else
                ENTITY.FREEZE_ENTITY_POSITION(rewindState.frozenEntity, false)
                local fwd = ENTITY.GET_ENTITY_FORWARD_VECTOR(rewindState.frozenEntity)
                local fwdSpeed = snap.vel.x * fwd.x + snap.vel.y * fwd.y + snap.vel.z * fwd.z
                VEHICLE.SET_VEHICLE_FORWARD_SPEED(rewindState.frozenEntity, fwdSpeed)
                ENTITY.SET_ENTITY_VELOCITY(rewindState.frozenEntity,
                    snap.vel.x, snap.vel.y, snap.vel.z)
                ENTITY.SET_ENTITY_ANGULAR_VELOCITY(rewindState.frozenEntity,
                    snap.angVel.x, snap.angVel.y, snap.angVel.z)
                local bx, by, bz = rewindState.colliderSpin(rewindState.frozenEntity)
                logf("[Rewind] spin read back %.3f %.3f %.3f", bx, by, bz)
                rewindState.restoreDrivetrain(rewindState.frozenEntity, snap)
                rewindState.restoreVehState(rewindState.frozenEntity, snap.vs)
            end
            logf("[Rewind] resume entity %d vel %.2f %.2f %.2f spin %.2f %.2f %.2f playhead %.2f",
                rewindState.frozenEntity,
                snap.vel.x, snap.vel.y, snap.vel.z,
                snap.angVel.x, snap.angVel.y, snap.angVel.z, rewindState.playhead)
        end
        rewindState.frozenEntity = 0
        rewindState._walkAnimPlaying = false
        do
            if STREAMING.HAS_ANIM_DICT_LOADED("mini@strip_club@walk") then
                STREAMING.REMOVE_ANIM_DICT("mini@strip_club@walk")
            end
        end

        do
            GRAPHICS.CLEAR_TIMECYCLE_MODIFIER()
        end

        local ph = math.floor(rewindState.playhead)
        rewindState.count = rewindState.count - ph
        if rewindState.count < 0 then rewindState.count = 0 end
        rewindState.head = rewindState.head - ph
        if rewindState.head < 1 then
            rewindState.head = rewindState.head + rewindState.maxSnapshots
        end

        rewindState.playhead = 0
        rewindState._lastPlayMs = nil
        rewindState._nextCaptureMs = 0
        rewindState.state = 0
    end
end

