vehParachute.AUTO_TESTS = {
    0x7F6DB52EEFC96DF8,
    0x39DAC362EE65FA28,
    0xA1A9FC1C76A6730D,
    0xA0948AB42D7BA0DE,
    0xDCE4334788AF94EA,
}
vehParachute.autoModel = {}
vehParachute.isAutomobile = function(model)
    local known = vehParachute.autoModel[model]
    if known ~= nil then return known end
    local ok = false
    for _, h in ipairs(vehParachute.AUTO_TESTS) do
        if Natives.InvokeBool(h, model) then
            ok = true
            break
        end
    end
    vehParachute.autoModel[model] = ok
    return ok
end

vehParachute.modelInfo = function(veh)
    local phys = GTA.HandleToPointer(veh)
    if not phys then return nil end
    local addr = phys:GetAddress()
    if not addr or addr == 0 then return nil end
    local mi = Memory.ReadLong(addr + 0x20)
    if mi <= 0 or mi >= 0x800000000000 then return nil end
    return mi
end

vehParachute.calibrate = function(veh, mi, initiallyHas)
    for cand = vehParachute.SCAN_LO, vehParachute.SCAN_HI, 4 do
        local addr = mi + cand + vehParachute.FLAG_DWORD
        local orig = Memory.ReadUInt(addr)
        local bitSet = (orig & vehParachute.FLAG_BIT) ~= 0
        if bitSet == initiallyHas then
            local probe = initiallyHas
                and (orig & ~vehParachute.FLAG_BIT)
                or (orig | vehParachute.FLAG_BIT)
            Memory.WriteUInt(addr, probe)
            local flipped = Natives.InvokeBool(vehParachute.H_HAS_PARACHUTE, veh) ~= initiallyHas
            Memory.WriteUInt(addr, orig)
            if flipped then
                vehParachute.off = cand
                logf("[VehParachute] m_VehicleFlags latched at CVehicleModelInfo+0x%X", cand)
                return true
            end
        end
    end
    vehParachute.failed = true
    logf("[VehParachute] nothing in 0x%X..0x%X flipped GET_VEHICLE_HAS_PARACHUTE - feature inert",
        vehParachute.SCAN_LO, vehParachute.SCAN_HI)
    return false
end

vehParachute.restore = function(exceptModel)
    for model, p in pairs(vehParachute.patched) do
        if model ~= exceptModel then
            Memory.WriteUInt(p.addr, p.value & ~vehParachute.FLAG_BIT)
            vehParachute.patched[model] = nil
            vehParachute.logged[model] = nil
        end
    end
end

vehParachute.currentVehicle = function()
    if not isPlayerReady() then return 0 end
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
    if not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then return 0 end
    local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if veh == 0 or not ENTITY.DOES_ENTITY_EXIST(veh) then return 0 end
    return veh
end

vehParachute.entityAddr = function(handle)
    if handle == 0 then return 0 end
    local ptr = GTA.HandleToPointer(handle)
    if not ptr then return 0 end
    return ptr:GetAddress() or 0
end

vehParachute.resolveFinish = function()
    if vehParachute.finishFn or vehParachute.finishFailed then
        return vehParachute.finishFn
    end
    local hit = Memory.Scan(IS_ENHANCED and vehParachute.AOB.enh or vehParachute.AOB.leg)
    if type(hit) == "number" and hit ~= 0 then
        vehParachute.finishFn = hit
        logf("[VehParachute] CAutomobile::FinishParachuting resolved @ %X", hit)
    else
        vehParachute.finishFailed = true
        logf("[VehParachute] CAutomobile::FinishParachuting signature missed - a "
            .. "canopy can only be left to the engine, not ended")
    end
    return vehParachute.finishFn
end

vehParachute.watchedVehicle = function(veh)
    if veh ~= 0 then return veh end
    local watch = vehParachute.watchVeh
    if watch ~= 0 and not ENTITY.DOES_ENTITY_EXIST(watch) then
        vehParachute.watchVeh = 0
        return 0
    end
    return watch
end

vehParachute.canopyOut = function(veh)
    vehParachute.canopyAddr, vehParachute.canopyLiveModel = nil, nil
    if veh == 0 or not ENTITY.DOES_ENTITY_EXIST(veh) then return nil end
    local model = ENTITY.GET_ENTITY_MODEL(veh) & 0xFFFFFFFF
    if not vehParachute.isAutomobile(model) then return nil end
    local addr = vehParachute.entityAddr(veh)
    if addr == 0 then return nil end
    local state = Memory.ReadUInt(addr + vehParachute.OFF_STATE)
    if state ~= 4 and state ~= 5 then return nil end
    if Memory.ReadLong(addr + vehParachute.OFF_CHUTE_OBJ) == 0 then return nil end
    vehParachute.canopyAddr, vehParachute.canopyLiveModel = addr, model
    return model
end

vehParachute.unloadRelease = function()
    if not next(vehParachute.patched) then return end
    local hold = nil
    local addr = vehParachute.canopyAddr
    if addr and addr ~= 0 then
        local state = Memory.ReadUInt(addr + vehParachute.OFF_STATE)
        if (state == 4 or state == 5)
            and Memory.ReadLong(addr + vehParachute.OFF_CHUTE_OBJ) ~= 0 then
            local fn = vehParachute.finishFn
            if not fn then
                hold = vehParachute.canopyLiveModel
            else
                Memory.LuaCallCFunction(fn, addr)
                if Memory.ReadUInt(addr + vehParachute.OFF_STATE) ~= 0 then
                    hold = vehParachute.canopyLiveModel
                end
            end
        end
    end
    vehParachute.canopyModel = hold
    vehParachute.restore(hold)
    logf("[VehParachute] unload: flags cleared%s",
        hold and string.format(", 0x%08X held (canopy still out)", hold) or "")
end

vehParachute.endCanopy = function(veh)
    local fn = vehParachute.resolveFinish()
    if not fn or veh == 0 or not ENTITY.DOES_ENTITY_EXIST(veh) then return false end
    local addr = vehParachute.entityAddr(veh)
    if addr == 0 then return false end
    local state = Memory.ReadUInt(addr + vehParachute.OFF_STATE)
    if state ~= 4 and state ~= 5 then return false end
    if Memory.ReadLong(addr + vehParachute.OFF_CHUTE_OBJ) == 0 then return false end

    Memory.LuaCallCFunction(fn, addr)
    local after = Memory.ReadUInt(addr + vehParachute.OFF_STATE)
    if after ~= 0 then
        logf("[VehParachute] FinishParachuting did not take (state %d -> %d)", state, after)
        return false
    end
    logf("[VehParachute] canopy cut away by FinishParachuting (state %d -> 0)", state)
    return true
end

vehParachute.reclaimLeak = function(veh)
    if veh == 0 or vehParachute.failed then return end
    local model = ENTITY.GET_ENTITY_MODEL(veh) & 0xFFFFFFFF
    if vehParachute.reclaimed[model] or vehParachute.patched[model] then return end
    if model == (vehParachute.RUINER2_MODEL & 0xFFFFFFFF) then return end
    if not vehParachute.isAutomobile(model) then return end
    local mi = vehParachute.modelInfo(veh)
    if not mi then return end
    if not vehParachute.off then
        local has = Natives.InvokeBool(vehParachute.H_HAS_PARACHUTE, veh) == true
        if not vehParachute.calibrate(veh, mi, has) then return end
    end
    vehParachute.reclaimed[model] = true

    local addr = mi + vehParachute.off + vehParachute.FLAG_DWORD
    local orig = Memory.ReadUInt(addr)
    if (orig & vehParachute.FLAG_BIT) == 0 then return end
    if vehParachute.canopyOut(veh) then
        vehParachute.endCanopy(veh)
    end
    Memory.WriteUInt(addr, orig & ~vehParachute.FLAG_BIT)
    logf("[VehParachute] cleared a leaked FLAG_HAS_PARACHUTE on model 0x%X", model)
end

vehParachute.releaseAll = function(veh)
    if not next(vehParachute.patched) then return end
    local watched = vehParachute.watchedVehicle(veh)
    local hold = vehParachute.canopyOut(watched)
    if hold then
        vehParachute.watchVeh = watched
        if vehParachute.endCanopy(watched) then hold = nil end
    end
    vehParachute.canopyModel = hold
    vehParachute.restore(hold)
    if hold then return end
    vehParachute.watchVeh = 0
    vehParachute.chuteOpen = false
    vehParachute.playedDeploy = false
    vehParachute.playedDetach = false
end

vehParachute.playChuteSound = function(veh, name)
    AUDIO.PLAY_SOUND_FROM_ENTITY(-1, name, veh, vehParachute.CHUTE_SOUNDSET, true, 100)
end

vehParachute.underCanopy = function(ped, veh)
    local deployed = Natives.InvokeBool(vehParachute.H_CHUTE_DEPLOYED, veh)

    local now = MISC.GET_GAME_TIMER()
    local spaceDown = isAnyKeyDown(0x20)
    local pressed = spaceDown and not vehParachute.spaceWasDown
    vehParachute.spaceWasDown = spaceDown

    if now - (vehParachute.hbAt or 0) > 1000 then
        vehParachute.hbAt = now
        logf("[VehParachuteT] tick veh=%s deployed=%s chuteOpen=%s space=%s",
            tostring(veh), tostring(deployed), tostring(vehParachute.chuteOpen),
            tostring(spaceDown))
    end

    if not deployed and pressed
        and Natives.InvokeBool(vehParachute.H_CAN_DEPLOY, veh) then
        if now - vehParachute.lastBeepAt > 1000 then
            vehParachute.lastBeepAt = now
            vehParachute.tPress = now
            vehParachute.playChuteSound(veh, "Stabilize")
            vehParachute.playedDeploy = true
            vehParachute.playChuteSound(veh, "Deploy")
            logf("[VehParachuteT] +0ms Space accepted, Stabilize + Deploy")
        end
    end

    if deployed and pressed and not vehParachute.playedDetach then
        vehParachute.playedDetach = true
        vehParachute.playChuteSound(veh, "Detach")
        logf("[VehParachuteT] cut-away press, Detach")
    end

    if deployed ~= vehParachute.chuteOpen then
        vehParachute.chuteOpen = deployed
        if deployed then
            logf("[VehParachuteT] +%dms IsOut rose%s",
                vehParachute.tPress and (now - vehParachute.tPress) or -1,
                vehParachute.playedDeploy and "" or " - Deploy from this LATE edge")
            if not vehParachute.playedDeploy then
                vehParachute.playedDeploy = true
                vehParachute.playChuteSound(veh, "Deploy")
            end
        else
            logf("[VehParachuteT] IsOut fell%s",
                vehParachute.playedDetach and "" or " - Detach from this LATE edge")
            if not vehParachute.playedDetach then
                vehParachute.playChuteSound(veh, "Detach")
            end
            vehParachute.playedDeploy = false
            vehParachute.playedDetach = false
        end
    end
    if not deployed then return end

    local gain = vehParachute.STEER_ASSIST
    if VEHICLE.GET_PED_IN_VEHICLE_SEAT(veh, -1, false) ~= ped then return end

    local stick = Natives.InvokeFloat(vehParachute.H_CONTROL_NORMAL, 0, vehParachute.CTRL_VEH_MOVE_LR) or 0.0
    if math.abs(stick) < 0.05 then return end

    ENTITY.APPLY_FORCE_TO_ENTITY(veh, 4,
        0.0, 0.0, -stick * gain,
        0.0, 0.0, 0.0,
        0, false, false, true, false, false)
    if not vehParachute.loggedApply then
        vehParachute.loggedApply = true
        logf("[VehParachute] steer assist applying: stick=%.2f gain=%.2f", stick, gain)
    end
end


vehParachute.onTick = function(f)
    local toggled = f:IsToggled()
    local veh = vehParachute.currentVehicle()

    if ShouldUnload() and not scriptUnloading then
        vehParachute.releaseAll(veh)
        logf("[VehParachute] pre-teardown window: canopy %s",
            vehParachute.canopyModel and "left to the engine" or "clear")
        return
    end

    if not toggled then
        vehParachute.reclaimLeak(veh)
        vehParachute.releaseAll(veh)
        return
    end

    if vehParachute.failed or not isPlayerReady() then return end

    if veh == 0 then
        vehParachute.chuteOpen = false
        vehParachute.canopyModel = vehParachute.canopyOut(vehParachute.watchedVehicle(0))
        return
    end
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())

    local model = ENTITY.GET_ENTITY_MODEL(veh) & 0xFFFFFFFF
    if not vehParachute.isAutomobile(model) then return end
    if model == (vehParachute.RUINER2_MODEL & 0xFFFFFFFF) then
        vehParachute.underCanopy(ped, veh)
        return
    end

    local mi = vehParachute.modelInfo(veh)
    if not mi then return end
    if not vehParachute.off then
        local has = Natives.InvokeBool(vehParachute.H_HAS_PARACHUTE, veh) == true
        if not vehParachute.calibrate(veh, mi, has) then return end
    end

    local addr = mi + vehParachute.off + vehParachute.FLAG_DWORD
    local p = vehParachute.patched[model]
    if not p then
        p = { addr = addr, value = Memory.ReadUInt(addr) }
        vehParachute.patched[model] = p
    elseif p.addr ~= addr then
        p.addr = addr
        p.value = Memory.ReadUInt(addr)
        vehParachute.logged[model] = nil
    end

    local orig = Memory.ReadUInt(addr)
    if (orig & vehParachute.FLAG_BIT) == 0 then
        Memory.WriteUInt(addr, orig | vehParachute.FLAG_BIT)
        if not vehParachute.logged[model] then
            vehParachute.logged[model] = true
            logf("[VehParachute] FLAG_HAS_PARACHUTE set on model 0x%X (archetype 0x%X)", model, mi)
        end
    end

    vehParachute.canopyModel = vehParachute.canopyOut(veh)
    if vehParachute.canopyModel then vehParachute.watchVeh = veh end
    vehParachute.underCanopy(ped, veh)
end

vehParachute.resolveFinish()

scanDoctor.register("VEH-PARACHUTE-FINISH", {
    probe = function()
        return scanDoctor.scanOk(IS_ENHANCED and vehParachute.AOB.enh
            or vehParachute.AOB.leg)
    end,
    sig = scanDoctor.fieldSig(vehParachute, "AOB", "leg", "enh"),
})

centralOnTick(FeatureMgr.AddFeature(vehParachute.featHash, "Parachute On Anything",
    eFeatureType.Toggle,
    "Gives the car you are driving the Ruiner 2000's parachute.",
    vehParachute.onTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)


EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    local flying = vehParachute.canopyModel
    vehParachute.restore(flying)
    if flying then
        logf("[VehParachute] unload under canopy on model 0x%X - flag left armed "
            .. "for the engine to finish with; the next load clears it", flying)
    end
end)

;(function()

local EL = {
    RANGE_M    = 10.0,
    RELEASE_M  = 15.0,
    SCAN_MS    = 250,
    RESEND_MS  = 1000,
    PRESS_MS   = 3000,
    INPUT_ENTER = 23,

    N_LOCK_FOR    = 0x517AAF684BB50CD1,
    N_GET_LOCK    = 0xF6AF6CB341349015,
    N_PED_IN_VEH  = 0xA3EE4A07279BB9DB,
    N_TRYING      = 0x814FA8BE5449445D,

    held = nil,
    pressMs = 0,
    lastScan = 0,
}

function EL.lockedForMe(veh, pid)
    return Natives.InvokeBool(EL.N_GET_LOCK, veh, pid)
end

function EL.release()
    local h = EL.held
    EL.held = nil
    EL.pressMs = 0
    if not h or not ENTITY.DOES_ENTITY_EXIST(h.veh)
        or (ENTITY.GET_ENTITY_MODEL(h.veh) & 0xFFFFFFFF) ~= h.model then return end
    Natives.InvokeVoid(EL.N_LOCK_FOR, h.veh, GTA.GetLocalPlayerId(), true)
end

function EL.findTarget(me, pid)
    local myPos = ENTITY.GET_ENTITY_COORDS(me, true)
    local best, bestD2 = nil, EL.RANGE_M * EL.RANGE_M
    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        local veh = PoolMgr.GetVehicle(i)
        if veh and veh > 0 then
            local pos = ENTITY.GET_ENTITY_COORDS(veh, true)
            local dx, dy, dz = pos.x - myPos.x, pos.y - myPos.y, pos.z - myPos.z
            local d2 = dx * dx + dy * dy + dz * dz
            if d2 < bestD2 and EL.lockedForMe(veh, pid) then
                local driver = VEHICLE.GET_PED_IN_VEHICLE_SEAT(veh, -1, false)
                if driver == 0 or PED.IS_PED_A_PLAYER(driver) then
                    best, bestD2 = veh, d2
                end
            end
        end
    end
    return best
end

function EL.tick(f)
    if scriptUnloading then return end
    if not f:IsToggled() then
        if EL.held then EL.release() end
        return
    end
    if not isPlayerReady() then return end

    local now = Time.GetEpocheMs()
    local pid = GTA.GetLocalPlayerId()
    local me = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not me or me == 0 then return end

    local h = EL.held
    if h and (not ENTITY.DOES_ENTITY_EXIST(h.veh)
        or (ENTITY.GET_ENTITY_MODEL(h.veh) & 0xFFFFFFFF) ~= h.model) then
        EL.held, EL.pressMs, h = nil, 0, nil
    end

    if h then
        local inside = Natives.InvokeBool(EL.N_PED_IN_VEH, me, h.veh, false)
        local entering = Natives.InvokeInt(EL.N_TRYING, me) == h.veh
        local locked = EL.lockedForMe(h.veh, pid)

        if locked and now - h.sentMs >= EL.RESEND_MS then
            Natives.InvokeVoid(EL.N_LOCK_FOR, h.veh, pid, false)
            h.sentMs = now
        end

        if inside then
            EL.pressMs = 0
            return
        end

        if not entering then
            local a = ENTITY.GET_ENTITY_COORDS(me, true)
            local b = ENTITY.GET_ENTITY_COORDS(h.veh, true)
            local dx, dy, dz = a.x - b.x, a.y - b.y, a.z - b.z
            if dx * dx + dy * dy + dz * dz > EL.RELEASE_M * EL.RELEASE_M then
                EL.release()
                return
            end
        end

        if not PED.IS_PED_IN_ANY_VEHICLE(me, false)
            and PAD.IS_DISABLED_CONTROL_JUST_PRESSED(0, EL.INPUT_ENTER) and locked then
            EL.pressMs = now
        end
        if EL.pressMs > 0 then
            if now - EL.pressMs > EL.PRESS_MS then
                EL.pressMs = 0
            elseif not locked and Natives.InvokeInt(EL.N_TRYING, me) == 0 then
                local seat = VEHICLE.GET_PED_IN_VEHICLE_SEAT(h.veh, -1, false) == 0 and -1 or -2
                TASK.TASK_ENTER_VEHICLE(me, h.veh, 10000, seat, 2.0, 1, 0, false)
                EL.pressMs = 0
            end
        end
        return
    end

    if PED.IS_PED_IN_ANY_VEHICLE(me, false) then return end
    if now - EL.lastScan < EL.SCAN_MS then return end
    EL.lastScan = now

    local veh = EL.findTarget(me, pid)
    if not veh then return end
    Natives.InvokeVoid(EL.N_LOCK_FOR, veh, pid, false)
    EL.held = {
        veh = veh,
        model = ENTITY.GET_ENTITY_MODEL(veh) & 0xFFFFFFFF,
        sentMs = now,
    }
end

centralOnTick(FeatureMgr.AddFeature(H.ENTER_LOCKED, "Enter Locked Vehicles",
    eFeatureType.Toggle,
    "Allows you to enter other players locked personal vehicles.",
    EL.tick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    EL.release()
end)
end)()

;(function()

local roadFeel = {
    coastHash = H.NATURAL_COASTING,
    brakeHash = H.STOPPED_BRAKE_LIGHTS,
    handling = nil,
    changed = false,
    vehicle = 0,
    brakeVehicle = 0,
    brakeForced = false,
    candidateVehicle = 0,
    vehicleReadyAt = 0,
    VEHICLE_INIT_MS = IS_ENHANCED and 500 or 300,
    FREEWHEEL_FLAG = 0x100,
    HANDLING_FLAGS = 0x128,
    WHEEL_HANDLING = 0x120,
    WHEEL_VEHICLE = 0x128,
    layouts = {
        { array = 0xC30, count = 0xC38 },
        { array = 0xC20, count = 0xC28 },
        { array = 0xBC8, count = 0xBD0 },
        { array = 0xBB0, count = 0xBB8 },
    },
    ROAD_MODEL_TESTS = {
        0x7F6DB52EEFC96DF8,
        0xB50C0B0CEDC6CE84,
        0xBF94DD42F63BDED2,
        0x39DAC362EE65FA28,
        0xA1A9FC1C76A6730D,
    },
}

local function pointerOK(v)
    return type(v) == "number" and v > 0x10000 and v < 0x800000000000
end

local function readLong(addr)
    local v = Memory.ReadLong(addr)
    if pointerOK(v) then return v end
end

local function driverVehicle()
    if not isPlayerReady() or NETWORK.NETWORK_IS_IN_SPECTATOR_MODE() then return nil end
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
    if not ped or ped == 0 or not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then return nil end
    local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if not veh or veh == 0 or not ENTITY.DOES_ENTITY_EXIST(veh) then return nil end
    if VEHICLE.GET_PED_IN_VEHICLE_SEAT(veh, -1, false) ~= ped then return nil end
    return veh
end

local function handlingFor(veh)
    local object = GTA.GetLocalVehicle()
    if not object then return nil end
    local handle = GTA.PointerToHandle(object)
    if handle and handle ~= 0 and handle ~= veh then return nil end
    local vehAddr = object:GetAddress()
    if not pointerOK(vehAddr) then return nil end

    for _, layout in ipairs(roadFeel.layouts) do
        local count = Memory.ReadInt(vehAddr + layout.count)
        local array = readLong(vehAddr + layout.array)
        if count >= 2 and count <= 16 and array then
            local wheel = readLong(array)
            if wheel and readLong(wheel + roadFeel.WHEEL_VEHICLE) == vehAddr then
                local handling = readLong(wheel + roadFeel.WHEEL_HANDLING)
                if handling then return handling end
            end
        end
    end
end

local function isRoadModel(veh)
    local model = ENTITY.GET_ENTITY_MODEL(veh)
    if not model or model == 0 then return false end
    for _, hash in ipairs(roadFeel.ROAD_MODEL_TESTS) do
        if Natives.InvokeBool(hash, model) then return true end
    end
    return false
end

local function restoreCoasting()
    if roadFeel.changed and roadFeel.handling then
        local addr = roadFeel.handling + roadFeel.HANDLING_FLAGS
        Memory.WriteInt(addr, Memory.ReadInt(addr) & ~roadFeel.FREEWHEEL_FLAG)
    end
    roadFeel.handling, roadFeel.changed, roadFeel.vehicle = nil, false, 0
end

local function coastingTick(f)
    if scriptUnloading or ShouldUnload() or not f:IsToggled() then
        restoreCoasting()
        return
    end

    local veh = driverVehicle()
    if not veh or not isRoadModel(veh) then
        roadFeel.candidateVehicle, roadFeel.vehicleReadyAt = 0, 0
        restoreCoasting()
        return
    end

    if veh ~= roadFeel.candidateVehicle then
        roadFeel.candidateVehicle = veh
        roadFeel.vehicleReadyAt = Time.GetEpocheMs() + roadFeel.VEHICLE_INIT_MS
        restoreCoasting()
        return
    end
    if Time.GetEpocheMs() < roadFeel.vehicleReadyAt then return end

    local handling = veh and handlingFor(veh) or nil
    if not handling then
        restoreCoasting()
        return
    end
    if handling ~= roadFeel.handling then restoreCoasting() end

    roadFeel.handling, roadFeel.vehicle = handling, veh
    local addr = handling + roadFeel.HANDLING_FLAGS
    local flags = Memory.ReadInt(addr)
    if (flags & roadFeel.FREEWHEEL_FLAG) == 0 then
        Memory.WriteInt(addr, flags | roadFeel.FREEWHEEL_FLAG)
        roadFeel.changed = true
    end
end

local function releaseForcedBrake()
    if roadFeel.brakeForced and roadFeel.brakeVehicle ~= 0
       and ENTITY.DOES_ENTITY_EXIST(roadFeel.brakeVehicle) then
        VEHICLE.SET_VEHICLE_BRAKE(roadFeel.brakeVehicle, false)
    end
    roadFeel.brakeVehicle, roadFeel.brakeForced = 0, false
end

local function stoppedBrakeLightsTick(f)
    if not f:IsToggled() or scriptUnloading then
        releaseForcedBrake()
        return
    end
    local veh = driverVehicle()
    if roadFeel.brakeForced and veh ~= roadFeel.brakeVehicle then
        releaseForcedBrake()
    end

    local pedalDown = PAD.IS_CONTROL_PRESSED(0, 71)
                   or PAD.IS_CONTROL_PRESSED(0, 72)
    if veh and ENTITY.GET_ENTITY_SPEED(veh) < 0.25 and not pedalDown then
        VEHICLE.SET_VEHICLE_BRAKE(veh, true)
        Natives.InvokeVoid(0x92B35082E0B42F66, veh, true)
        roadFeel.brakeVehicle, roadFeel.brakeForced = veh, true
    else
        releaseForcedBrake()
    end
end

centralOnTick(FeatureMgr.AddFeature(roadFeel.coastHash, "Natural Coasting",
    eFeatureType.Toggle,
    "Removes GTA's slight automatic braking when you release the accelerator.",
    coastingTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)

centralOnTick(FeatureMgr.AddFeature(roadFeel.brakeHash, "Brake Lights While Stopped",
    eFeatureType.Toggle,
    "Keeps your brake lights illuminated while your vehicle is stopped.",
    stoppedBrakeLightsTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    restoreCoasting()
    releaseForcedBrake()
end)

end)()


aggroNpcs = {
    H_TASK_COMBAT_PED         = 0xF166E48407BAC484,
    H_CLEAR_PED_TASKS         = 0xE1EF3C1216AFF2CD,
    H_IS_ENTITY_DEAD          = 0x5F9532F3B5CC2551,
    H_SET_COMBAT_ATTRS        = 0x9F7794730795E019,
    H_SET_COMBAT_ABILITY      = 0xC7622C0D36B2FDA8,
    H_SET_COMBAT_MOVEMENT     = 0x4D9CA1009AFBD057,
    H_SET_COMBAT_RANGE        = 0x3C606747B23E497B,
    H_SET_KEEP_TASK           = 0x971D38760FBC02EF,
    H_SET_TARGET_LOSS         = 0x0703B9079823DA4A,
    H_BLOCK_NONTEMP           = 0x9F8AA94D6D97DBF4,
    H_SET_ACCURACY            = 0x7AEFB85C1D49DEB6,
    H_SET_SHOOT_RATE          = 0x614DA022990752DC,
    H_SET_FIRING_PATTERN      = 0x9AC577F5A12AD8A9,
    H_SET_NO_DELAY_SHOT       = 0xA52D5247A4227E14,
    H_REGISTER_TARGET         = 0x2F25D9AEFA34FBA2,
    H_GIVE_WEAPON             = 0xBF0FD6E56C964FCB,
    H_REMOVE_WEAPON           = 0x4899CB088EDF59B8,
    H_GET_SELECTED_WEAPON     = 0x0A6DB4965674D243,
    H_NET_HAS_CONTROL         = 0x01BF60A500E28887,
    H_NET_REQ_CONTROL         = 0xB69317BF5E782347,
    H_NET_REQ_CONTROL_ID      = 0xA670B3662FAFFBD0,
    H_NET_ID_FROM_ENTITY      = 0xA11700682F3AD45C,
    H_NET_ENTITY_NETWORKED    = 0xC7827959479DCC78,
    H_NET_ID_CAN_MIGRATE      = 0x299EEB23175895FC,
    H_GET_NEARBY_PEDS         = 0x23F8F5FC7E8C4A6B,
    H_GET_PED_IN_SEAT         = 0xBB40DD2270B65366,
    H_IS_PED_A_PLAYER         = 0x12534C348C6CB68B,
    H_SET_DRIVER_AGGRESSIVE   = 0xA731F608CA104E3C,
    H_IS_PLANE                = 0xA0948AB42D7BA0DE,
    H_IS_HELI                 = 0xDCE4334788AF94EA,
    H_TASK_PLANE_MISSION      = 0x23703CD154E83B88,
    H_TASK_HELI_MISSION       = 0xDAD029E187A2BEB4,
    H_NET_SESSION_STARTED     = 0x9DE624D2FC4B603F,
    H_IS_ENTITY_A_PED         = 0x524AC5ECEA15343E,
    H_GET_PED_REL_GROUP       = 0x7DBDD04862D95F04,
    H_SET_PED_REL_GROUP       = 0xC80A74AC829DDD92,
    H_SET_REL_BETWEEN         = 0xBF25EB89375A37AD,
    H_ADD_REL_GROUP           = 0xF372BC22FCB88606,
    H_SET_CAN_ATTACK_FRIENDLY = 0xB3B1CB349FF9C75D,
    H_IS_PED_IN_COMBAT        = 0x4859F1FC66A6278E,
    H_GET_CLOSEST_PED         = 0xC33AB876A77F8164,
    H_GET_CLOSEST_VEHICLE     = 0xF73EB622C4F1689B,
    H_GET_RANDOM_VEHICLE      = 0x386F6CE5BAF6091C,
    H_GET_MAX_PASSENGERS      = 0xA7C4F2C6E744A550,

    REL_IGNORE  = 2,
    REL_RESPECT = 0,
    AGGRO_GROUP = Utils.Joaat("VIBE_AGGRO_NPCS") & 0xFFFFFFFF,
    groupReady  = false,

    ATTRS = { 1, 2, 5, 13, 21, 46, 52, 58 },

    COMBAT_FLAGS = 67108864,
    THREAT_FLAGS = 16,
    MISSION_ATTACK = 6,
    pistolHash    = Utils.Joaat("WEAPON_PISTOL") & 0xFFFFFFFF,
    unarmedHash   = Utils.Joaat("WEAPON_UNARMED") & 0xFFFFFFFF,
    fullAutoHash  = Utils.Joaat("FIRING_PATTERN_FULL_AUTO"),

    state    = {},
    SCAN_MS  = 400,
    ON_FOOT_REARM_MS = 1500,
    VEHICLE_REARM_MS = 8000,
    RANGE_SQ = 130.0 * 130.0,

    DIAG = VIBESCRIPT_LOADER == true,

    H_RAND_PED_AT_COORD = 0x876046A8E3A4B71C,
    H_IS_PED_HUMAN      = 0xB980061DA992779D,
    NEARBY_CAP = 256,
    nearbyBuf  = nil,
    EXPAND_SEEDS = 16,
    GRID_HALF     = 3,
    GRID_STEP     = 35.0,
    GRID_RADIUS   = 25.0,
    GRID_Z_RADIUS = 45.0,
    VEHICLE_FLAGS = 127,
    closestBuf    = nil,

    cachedPeds       = {},
    cachedPedSet     = {},
    cacheLastRefresh = 0,
    CACHE_REFRESH_MS = 500,
}

function aggroNpcs.iv(hash, ...)
    return Natives.InvokeVoid(hash, ...)
end
function aggroNpcs.ib(hash, ...)
    return Natives.InvokeBool(hash, ...)
end
function aggroNpcs.ii(hash, ...)
    return Natives.InvokeInt(hash, ...)
end

function aggroNpcs.ensureGroup(targetPed)
    local A = aggroNpcs
    if not A.groupReady then
        local ptr = Memory.Alloc(8)
        if ptr and ptr ~= 0 then
            Memory.WriteInt(ptr, 0)
            A.ib(A.H_ADD_REL_GROUP, "VIBE_AGGRO_NPCS", ptr)
            local made = Memory.ReadInt(ptr) & 0xFFFFFFFF
            Memory.Free(ptr)
            if made ~= 0 then A.AGGRO_GROUP = made end
            A.groupReady = true
        end
    end

    A.iv(A.H_SET_REL_BETWEEN, A.REL_RESPECT, A.AGGRO_GROUP, A.AGGRO_GROUP)
    local targetGroup = A.ii(A.H_GET_PED_REL_GROUP, targetPed) & 0xFFFFFFFF
    if targetGroup ~= 0 and targetGroup ~= A.AGGRO_GROUP then
        A.iv(A.H_SET_REL_BETWEEN, A.REL_IGNORE, A.AGGRO_GROUP, targetGroup)
    end
end

function aggroNpcs.setCanMigrate(ent, canMigrate)
    local A = aggroNpcs
    if not A.ib(A.H_NET_ENTITY_NETWORKED, ent) then return end
    local netId = A.ii(A.H_NET_ID_FROM_ENTITY, ent)
    if netId and netId ~= 0 then
        A.iv(A.H_NET_ID_CAN_MIGRATE, netId, canMigrate)
    end
end

function aggroNpcs.refreshCachedPeds()
    local A = aggroNpcs
    local now = MISC.GET_GAME_TIMER()
    if (now - A.cacheLastRefresh) < A.CACHE_REFRESH_MS then return end
    A.cacheLastRefresh = now

    A.cachedPeds = {}
    A.cachedPedSet = {}

    local localPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
    local count = PoolMgr.GetMaxPedCount() or 0
    for i = 0, count - 1 do
        local ped = PoolMgr.GetPed(i)
        if ped and ped ~= 0 and ped ~= -1 and ped ~= localPed
            and not A.cachedPedSet[ped] then
            A.cachedPedSet[ped] = true
            A.cachedPeds[#A.cachedPeds + 1] = ped
        end
    end
end

function aggroNpcs.controlOrRequest(ent)
    local A = aggroNpcs
    if not ENTITY.DOES_ENTITY_EXIST(ent) then return false end
    if not A.ib(A.H_NET_SESSION_STARTED) then return true end
    if A.ib(A.H_NET_HAS_CONTROL, ent) then return true end

    local netId = 0
    if A.ib(A.H_NET_ENTITY_NETWORKED, ent) then
        netId = A.ii(A.H_NET_ID_FROM_ENTITY, ent) or 0
        if netId ~= 0 then
            A.ib(A.H_NET_REQ_CONTROL_ID, netId)
        end
    end
    A.ib(A.H_NET_REQ_CONTROL, ent)
    return A.ib(A.H_NET_HAS_CONTROL, ent)
end

function aggroNpcs.taskVehMission(driver, veh, targetPed)
    local A = aggroNpcs
    local mdl = ENTITY.GET_ENTITY_MODEL(veh)
    if A.ib(A.H_IS_PLANE, mdl) then
        A.iv(A.H_TASK_PLANE_MISSION, driver, veh, 0, targetPed,
            0.0, 0.0, 0.0, A.MISSION_ATTACK, 400.0, 0.0, 0.0, 80.0, 50.0, false)
    elseif A.ib(A.H_IS_HELI, mdl) then
        A.iv(A.H_TASK_HELI_MISSION, driver, veh, 0, targetPed,
            0.0, 0.0, 0.0, A.MISSION_ATTACK, 100.0, 40.0, -1.0, 100, 50, -1.0, 0)
    else
        A.iv(A.H_TASK_COMBAT_PED, driver, targetPed, A.COMBAT_FLAGS, A.THREAT_FLAGS)
    end
end

function aggroNpcs.taskPed(ped, targetPed, rec)
    local A = aggroNpcs
    rec = rec or {}
    A.iv(A.H_REGISTER_TARGET, ped, targetPed)

    if PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
        if veh ~= 0 and ENTITY.DOES_ENTITY_EXIST(veh) then
            local driver = A.ii(A.H_GET_PED_IN_SEAT, veh, -1, false)
            if driver == ped then
                if rec.vehicle and rec.vehicle ~= veh
                    and ENTITY.DOES_ENTITY_EXIST(rec.vehicle)
                    and A.ib(A.H_NET_HAS_CONTROL, rec.vehicle) then
                    A.setCanMigrate(rec.vehicle, true)
                end
                if A.controlOrRequest(veh) then
                    A.setCanMigrate(veh, false)
                    rec.vehicle = veh
                    rec.vehicleControlled = true
                end
                A.iv(A.H_SET_DRIVER_AGGRESSIVE, ped, 1.0)
                A.taskVehMission(ped, veh, targetPed)
            else
                A.iv(A.H_TASK_COMBAT_PED, ped, targetPed,
                    A.COMBAT_FLAGS, A.THREAT_FLAGS)
            end
            return
        end
    end

    if rec.vehicle and ENTITY.DOES_ENTITY_EXIST(rec.vehicle)
        and A.ib(A.H_NET_HAS_CONTROL, rec.vehicle) then
        A.setCanMigrate(rec.vehicle, true)
    end
    rec.vehicle = nil
    rec.vehicleControlled = false
    A.iv(A.H_TASK_COMBAT_PED, ped, targetPed, A.COMBAT_FLAGS, A.THREAT_FLAGS)
end

function aggroNpcs.maintainDriverVehicle(ped, rec)
    local A = aggroNpcs
    if not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        if rec.vehicle and ENTITY.DOES_ENTITY_EXIST(rec.vehicle)
            and A.ib(A.H_NET_HAS_CONTROL, rec.vehicle) then
            A.setCanMigrate(rec.vehicle, true)
        end
        rec.vehicle, rec.vehicleControlled = nil, false
        return false, false, false
    end

    local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if not veh or veh == 0 or not ENTITY.DOES_ENTITY_EXIST(veh) then
        rec.vehicle, rec.vehicleControlled = nil, false
        return false, false, false
    end
    local driver = A.ii(A.H_GET_PED_IN_SEAT, veh, -1, false)
    if driver ~= ped then return false, false, false end

    if rec.vehicle and rec.vehicle ~= veh and ENTITY.DOES_ENTITY_EXIST(rec.vehicle)
        and A.ib(A.H_NET_HAS_CONTROL, rec.vehicle) then
        A.setCanMigrate(rec.vehicle, true)
    end
    local hadControl = rec.vehicle == veh and rec.vehicleControlled == true
    rec.vehicle = veh
    if A.controlOrRequest(veh) then
        A.setCanMigrate(veh, false)
        rec.vehicleControlled = true
        return not hadControl, false, true
    end
    rec.vehicleControlled = false
    return false, true, true
end

function aggroNpcs.armPed(ped, targetPed, rec)
    local A = aggroNpcs
    rec = rec or {}

    A.setCanMigrate(ped, false)

    rec.originalGroup = rec.originalGroup
        or (A.ii(A.H_GET_PED_REL_GROUP, ped) & 0xFFFFFFFF)
    A.iv(A.H_SET_PED_REL_GROUP,       ped, A.AGGRO_GROUP)
    A.iv(A.H_SET_CAN_ATTACK_FRIENDLY, ped, false, false)
    A.iv(A.H_BLOCK_NONTEMP,           ped, true)
    A.iv(A.H_SET_KEEP_TASK,           ped, true)
    A.iv(A.H_SET_COMBAT_ABILITY,      ped, 2)
    A.iv(A.H_SET_COMBAT_MOVEMENT,     ped, 2)
    A.iv(A.H_SET_COMBAT_RANGE,        ped, 3)
    A.iv(A.H_SET_TARGET_LOSS,         ped, 1)
    A.iv(A.H_SET_NO_DELAY_SHOT,       ped)
    for _, attr in ipairs(A.ATTRS) do
        A.iv(A.H_SET_COMBAT_ATTRS, ped, attr, true)
    end
    A.iv(A.H_SET_ACCURACY,       ped, 60)
    A.iv(A.H_SET_SHOOT_RATE,     ped, 1000)
    A.iv(A.H_SET_FIRING_PATTERN, ped, A.fullAutoHash)

    local cur = A.ii(A.H_GET_SELECTED_WEAPON, ped) & 0xFFFFFFFF
    if cur == A.unarmedHash then
        A.iv(A.H_GIVE_WEAPON, ped, A.pistolHash, 9999, false, true)
        rec.gaveWeapon = true
    end

    A.taskPed(ped, targetPed, rec)
    rec.configured = true
end

function aggroNpcs.release(pid)
    local A = aggroNpcs
    local st = A.state[pid]
    A.state[pid] = nil
    if not st then return end
    for ped, rec in pairs(st.peds) do
        if ENTITY.DOES_ENTITY_EXIST(ped)
            and A.ib(A.H_IS_ENTITY_A_PED, ped)
            and A.ib(A.H_NET_HAS_CONTROL, ped) then
            A.iv(A.H_CLEAR_PED_TASKS, ped)
            A.iv(A.H_SET_KEEP_TASK, ped, false)
            A.iv(A.H_BLOCK_NONTEMP, ped, false)
            if type(rec) == "table" and rec.originalGroup and rec.originalGroup ~= 0 then
                A.iv(A.H_SET_PED_REL_GROUP, ped, rec.originalGroup)
            end
            if type(rec) == "table" and rec.gaveWeapon then
                A.iv(A.H_REMOVE_WEAPON, ped, A.pistolHash)
            end
            if type(rec) == "table" and rec.vehicle
                and ENTITY.DOES_ENTITY_EXIST(rec.vehicle)
                and A.ib(A.H_NET_HAS_CONTROL, rec.vehicle) then
                A.setCanMigrate(rec.vehicle, true)
            end
            A.setCanMigrate(ped, true)
        end
    end
end

function aggroNpcs.collectNearby(centerPed, set)
    local A = aggroNpcs
    if not centerPed or centerPed == 0 then return 0 end
    if not A.nearbyBuf then
        A.nearbyBuf = Memory.Alloc(8 + A.NEARBY_CAP * 8)
        if not A.nearbyBuf or A.nearbyBuf == 0 then A.nearbyBuf = nil; return 0 end
    end
    local buf = A.nearbyBuf
    Memory.WriteInt(buf, A.NEARBY_CAP)
    local count = A.ii(A.H_GET_NEARBY_PEDS, centerPed, buf, -1) or 0
    if count <= 0 then return 0 end
    if count > A.NEARBY_CAP then count = A.NEARBY_CAP end
    for i = 1, count do
        local h = Memory.ReadInt(buf + 8 + (i - 1) * 8)
        if h and h ~= 0 and h ~= -1 and h ~= centerPed then set[h] = true end
    end
    return count
end

function aggroNpcs.collectSpatial(cx, cy, cz, set, phase)
    local A = aggroNpcs
    if not A.closestBuf then
        A.closestBuf = Memory.Alloc(8)
        if not A.closestBuf or A.closestBuf == 0 then A.closestBuf = nil end
    end

    local p = (phase or 0) % 4
    local sx = (p == 1 or p == 3) and (A.GRID_STEP * 0.5) or 0.0
    local sy = (p == 2 or p == 3) and (A.GRID_STEP * 0.5) or 0.0
    local nRandom, nClosest, nVehicles, nOccupants = 0, 0, 0, 0
    local vehicles = {}

    local function addVehicle(veh)
        if not veh or veh == 0 or veh == -1 or vehicles[veh]
            or not ENTITY.DOES_ENTITY_EXIST(veh) then return end
        vehicles[veh] = true
        nVehicles = nVehicles + 1
        local maxPassengers = A.ii(A.H_GET_MAX_PASSENGERS, veh) or 0
        maxPassengers = math.max(0, math.min(maxPassengers, 31))
        for seat = -1, maxPassengers - 1 do
            local occupant = A.ii(A.H_GET_PED_IN_SEAT, veh, seat, false)
            if occupant and occupant ~= 0 and occupant ~= -1 and not set[occupant] then
                set[occupant] = true
                nOccupants = nOccupants + 1
            end
        end
    end

    local randomPed = A.ii(A.H_RAND_PED_AT_COORD, cx + 0.0, cy + 0.0, cz + 0.0,
        A.GRID_STEP * A.GRID_HALF, A.GRID_STEP * A.GRID_HALF,
        A.GRID_Z_RADIUS, -1)
    if randomPed and randomPed ~= 0 and randomPed ~= -1 then
        set[randomPed] = true
        nRandom = 1
    end

    for gx = -A.GRID_HALF, A.GRID_HALF do
        for gy = -A.GRID_HALF, A.GRID_HALF do
            local qx = cx + gx * A.GRID_STEP + sx
            local qy = cy + gy * A.GRID_STEP + sy
            if A.closestBuf then
                Memory.WriteInt(A.closestBuf, 0)
                local found = A.ib(A.H_GET_CLOSEST_PED,
                    qx + 0.0, qy + 0.0, cz + 0.0, A.GRID_RADIUS,
                    true, true, A.closestBuf, false, true, -1)
                if found then
                    local closest = Memory.ReadInt(A.closestBuf)
                    if closest and closest ~= 0 and closest ~= -1 and not set[closest] then
                        set[closest] = true
                        nClosest = nClosest + 1
                    end
                end
            end

            addVehicle(A.ii(A.H_GET_CLOSEST_VEHICLE,
                qx + 0.0, qy + 0.0, cz + 0.0, A.GRID_RADIUS,
                0, A.VEHICLE_FLAGS))
            addVehicle(A.ii(A.H_GET_RANDOM_VEHICLE,
                qx + 0.0, qy + 0.0, cz + 0.0, A.GRID_RADIUS,
                0, A.VEHICLE_FLAGS))
        end
    end
    return nRandom, nClosest, nVehicles, nOccupants
end

function aggroNpcs.collectEnhancedNear(targetPed, tpos, phase)
    local A = aggroNpcs
    local candidates = {}
    local nRandom, nClosest, nVehicles, nOccupants =
        A.collectSpatial(tpos.x, tpos.y, tpos.z, candidates, phase)
    local nNearby = A.collectNearby(targetPed, candidates)
    local seeds = {}
    for ped in pairs(candidates) do
        if ENTITY.DOES_ENTITY_EXIST(ped) and A.ib(A.H_IS_ENTITY_A_PED, ped) then
            seeds[#seeds + 1] = ped
        end
    end
    for i = 1, math.min(#seeds, A.EXPAND_SEEDS) do
        A.collectNearby(seeds[i], candidates)
    end

    local out = {}
    for ped in pairs(candidates) do out[#out + 1] = ped end
    return out, nRandom, nClosest, nNearby, nVehicles, nOccupants
end

function aggroNpcs.runStep(f)
    local A = aggroNpcs
    local pid = f:GetPlayerIndex()
    if not isPlayerReady() or not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then return false end

    local targetPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not targetPed or targetPed == 0 or not ENTITY.DOES_ENTITY_EXIST(targetPed) then return true end

    local st = A.state[pid]
    if not st then
        st = { peds = {}, lastDiag = 0, lastScan = 0, sourceCount = 0,
            scanPhase = 0, randomSeeds = 0, closestSeeds = 0, nearbySeeds = 0,
            vehicleSeeds = 0, occupantSeeds = 0 }
        A.state[pid] = st
    end

    local now = MISC.GET_GAME_TIMER()
    local tpos = ENTITY.GET_ENTITY_COORDS(targetPed, false)
    if not tpos then return true end
    A.ensureGroup(targetPed)

    if (now - st.lastScan) >= A.SCAN_MS then
        st.lastScan = now
        local pedList
        if IS_ENHANCED then
            pedList, st.randomSeeds, st.closestSeeds, st.nearbySeeds,
                st.vehicleSeeds, st.occupantSeeds =
                A.collectEnhancedNear(targetPed, tpos, st.scanPhase)
            st.scanPhase = (st.scanPhase + 1) % 4
        else
            A.refreshCachedPeds()
            pedList = A.cachedPeds
            st.randomSeeds, st.closestSeeds, st.nearbySeeds,
                st.vehicleSeeds, st.occupantSeeds = 0, 0, 0, 0, 0
        end
        st.sourceCount = #pedList

        for _, ped in ipairs(pedList) do
            if ped ~= targetPed and ENTITY.DOES_ENTITY_EXIST(ped)
                and not A.ib(A.H_IS_ENTITY_DEAD, ped, false)
                and not A.ib(A.H_IS_PED_A_PLAYER, ped)
                and A.ib(A.H_IS_PED_HUMAN, ped) then
                local pp = ENTITY.GET_ENTITY_COORDS(ped, false)
                local dx, dy, dz = pp.x - tpos.x, pp.y - tpos.y, pp.z - tpos.z
                if (dx * dx + dy * dy + dz * dz) <= A.RANGE_SQ and not st.peds[ped] then
                    st.peds[ped] = { configured = false, controlled = false,
                        lastTask = 0 }
                end
            end
        end
    end

    if st.targetPed ~= targetPed then
        st.targetPed = targetPed
        for _, rec in pairs(st.peds) do rec.lastTask = 0 end
    end

    local tracked, owned, waiting, armed, retasked, fighting = 0, 0, 0, 0, 0, 0
    local driverOwned, driverWaiting = 0, 0
    for ped, rec in pairs(st.peds) do
        tracked = tracked + 1
        if not ENTITY.DOES_ENTITY_EXIST(ped)
            or not A.ib(A.H_IS_ENTITY_A_PED, ped)
            or A.ib(A.H_IS_PED_A_PLAYER, ped)
            or A.ib(A.H_IS_ENTITY_DEAD, ped, false) then
            if rec.vehicle and ENTITY.DOES_ENTITY_EXIST(rec.vehicle)
                and A.ib(A.H_NET_HAS_CONTROL, rec.vehicle) then
                A.setCanMigrate(rec.vehicle, true)
            end
            st.peds[ped] = nil
            goto continue
        end

        if not A.controlOrRequest(ped) then
            rec.controlled = false
            waiting = waiting + 1
            goto continue
        end

        owned = owned + 1
        A.setCanMigrate(ped, false)
        local gainedVehicle, waitingVehicle, isDriver =
            A.maintainDriverVehicle(ped, rec)
        if isDriver then
            if waitingVehicle then driverWaiting = driverWaiting + 1
            else driverOwned = driverOwned + 1 end
        end
        if not rec.configured or not rec.controlled then
            A.armPed(ped, targetPed, rec)
            rec.lastTask = now
            armed = armed + 1
        else
            A.iv(A.H_BLOCK_NONTEMP, ped, true)
            A.iv(A.H_SET_KEEP_TASK, ped, true)
            A.iv(A.H_SET_CAN_ATTACK_FRIENDLY, ped, false, false)
            A.iv(A.H_SET_COMBAT_ATTRS, ped, 5, true)
            A.iv(A.H_SET_COMBAT_ATTRS, ped, 13, true)
            A.iv(A.H_SET_COMBAT_ATTRS, ped, 58, true)
            if (A.ii(A.H_GET_PED_REL_GROUP, ped) & 0xFFFFFFFF) ~= A.AGGRO_GROUP then
                A.iv(A.H_SET_PED_REL_GROUP, ped, A.AGGRO_GROUP)
            end

            if gainedVehicle then
                A.taskPed(ped, targetPed, rec)
                rec.lastTask = now
                retasked = retasked + 1
            elseif A.ib(A.H_IS_PED_IN_COMBAT, ped, targetPed) then
                fighting = fighting + 1
            else
                local settleMs = PED.IS_PED_IN_ANY_VEHICLE(ped, false)
                    and A.VEHICLE_REARM_MS or A.ON_FOOT_REARM_MS
                if (now - (rec.lastTask or 0)) >= settleMs then
                    A.taskPed(ped, targetPed, rec)
                    rec.lastTask = now
                    retasked = retasked + 1
                end
            end
        end
        rec.controlled = true
        ::continue::
    end

    if logging.enabled and A.DIAG and (now - (st.lastDiag or 0)) >= 2000 then
        st.lastDiag = now
        logf("[AggroDiag] edition=%s src=%d tracked=%d owned=%d waiting=%d armed=%d fighting=%d retask=%d rand=%d closest=%d near=%d vehicles=%d occupants=%d driverOwned=%d driverWait=%d",
            IS_ENHANCED and "Enhanced" or "Legacy", st.sourceCount or 0,
            tracked, owned, waiting, armed, fighting, retasked,
            st.randomSeeds or 0, st.closestSeeds or 0,
            st.nearbySeeds or 0, st.vehicleSeeds or 0,
            st.occupantSeeds or 0, driverOwned, driverWaiting)
    end
    return true
end

function aggroNpcs.runLoop(f)
    local pid = f:GetPlayerIndex()
    telemetryCountToggleEdge("AggressiveNPCs", pid, f:IsToggled())
    while f:IsToggled() and not ShouldUnload() do
        local ok, keepGoing = pcall(aggroNpcs.runStep, f)
        if not ok then
            logf("[AggroDiag] loop fault: %s", tostring(keepGoing))
            break
        end
        if not keepGoing then break end
        Script.Yield(250)
    end
    telemetryCountToggleEdge("AggressiveNPCs", pid, false)
    if ShouldUnload() then
        aggroNpcs.state[pid] = nil
        return
    end
    if aggroNpcs.state[pid] then aggroNpcs.release(pid) end
end

