local function themeGlyphs(label)
    if not utf8.len(label) then return { label } end
    local glyphs = {}
    for _, cp in utf8.codes(label) do
        glyphs[#glyphs + 1] = utf8.char(cp)
    end
    if #glyphs == 0 then glyphs = { label } end
    return glyphs
end

