Theme.labels = {}
for i, id in ipairs(Theme.order) do Theme.labels[i] = Theme.defs[id].name end

function Theme.index()
    for i, id in ipairs(Theme.order) do if id == Theme.active then return i - 1 end end
    return 0
end

function Theme.select(i0)
    local id = Theme.order[i0 + 1]
    if id and id ~= Theme.active then
        Theme.active = id
        FileMgr.WriteFileContent(Theme.file, id, false)
    end
end

function Theme.apply()
    Theme._boxDepth = 0
    Theme._inTab = true
    Theme._pending = {}
    local def = Theme.defs[Theme.active] or Theme.defs.none
    local cols = def.colors
    if type(cols) == "function" then cols = cols() end
    local vars = def.vars
    if type(vars) == "function" then vars = vars() end
    local nc = 0
    if cols then
        for idx, c in pairs(cols) do
            ImGui.PushStyleColor(idx, c[1] / 255, c[2] / 255, c[3] / 255, (c[4] or 255) / 255)
            nc = nc + 1
        end
    end
    local nv = 0
    if vars then
        for idx, val in pairs(vars) do
            if type(val) == "table" then ImGui.PushStyleVar(idx, val[1], val[2])
            else ImGui.PushStyleVar(idx, val) end
            nv = nv + 1
        end
    end
    Theme._nc, Theme._nv = nc, nv
    if def.tabBg then def.tabBg() end
end

function Theme.restore()
    Theme._inTab = false
    local def = Theme.defs[Theme.active]
    local p   = Theme._pending
    if p and def and def.boxBg and not scriptUnloading then
        for i = 1, #p do
            local e = p[i]
            if not e.done and e.ow and e.ow > 1 then
                local h  = Theme._boxH[e.key]
                local th = Theme._boxTitleH[e.key]
                if not h or h <= 1 then h = 160 end
                if not th or th <= 1 then
                    local _, lh = ImGui.CalcTextSize("A")
                    th = math.floor((lh or 14) * 2.2)
                end
                def.boxBg(e.ox, e.oy, e.ox + e.ow, e.oy + h)
                if def.boxTitle and not e.unicodeTitle then
                    def.boxTitle(e.label, e.ox, e.oy, e.ox + e.ow, e.oy + th)
                end
            end
        end
        if def.boxTitleUnicode then
            for i = 1, #p do
                local e = p[i]
                if e.unicodeTitle and e.ow and e.ow > 1 then
                    local th = Theme._boxTitleH[e.key]
                    if not th or th <= 1 then
                        local _, lh = ImGui.CalcTextSize("A")
                        th = math.floor((lh or 14) * 2.2)
                    end
                    def.boxTitleUnicode(e.label, e.key, e.ox, e.oy, e.ox + e.ow,
                        e.oy + th, e.vpTop, e.vpBot)
                end
            end
        end
    end
    Theme._pending = nil
    if (Theme._nc or 0) > 0 then ImGui.PopStyleColor(Theme._nc) end
    if (Theme._nv or 0) > 0 then ImGui.PopStyleVar(Theme._nv) end
    Theme._nc, Theme._nv = 0, 0
end

Theme._sepH = {}
function Theme.sep(i)
    local _, y0 = ImGui.GetCursorScreenPos()
    ImGui.Separator()
    local _, y1 = ImGui.GetCursorScreenPos()
    local adv, full = y1 - y0, Theme._sepH[i]
    if not full or adv > full then
        Theme._sepH[i] = adv
    elseif full - adv > 0.5 then
        ImGui.SetCursorPosY(ImGui.GetCursorPosY() + (full - adv))
    end
end

if FileMgr.DoesFileExist(Theme.file) then
    local c = FileMgr.ReadFileContent(Theme.file)
    if c then
        c = c:gsub("%s+", "")
        if Theme.defs[c] then Theme.active = c end
    end
end

do
    local _beginBox = ClickGUI.BeginCustomChildWindow
    local _endBox   = ClickGUI.EndCustomChildWindow

    Theme._boxH = {}
    Theme._boxTitleH = {}

    ClickGUI.BeginCustomChildWindow = function(label, ...)
        local def   = Theme.defs[Theme.active]
        local outer = Theme._inTab and not scriptUnloading
                      and (Theme._boxDepth or 0) == 0 and def and def.boxBg
        local unicodeTitle = outer and type(label) == "string"
                             and label:find("[\128-\255]") ~= nil
        local ox, oy, ow, vpTop, vpBot, boxKey, pend
        if outer then
            boxKey = ImGui.GetID(label)
            ox, oy = ImGui.GetCursorScreenPos()
            ow = ImGui.GetContentRegionAvail()
            local _,  wy = ImGui.GetWindowPos()
            local _,  wh = ImGui.GetWindowSize()
            vpTop, vpBot = wy, wy + wh
            local h = Theme._boxH[boxKey]
            if h and ox and ow and ow > 1 and h > 1 then
                def.boxBg(ox, oy, ox + ow, oy + h)
            end
            pend = {
                ox = ox, oy = oy, ow = ow, key = boxKey, label = label,
                unicodeTitle = unicodeTitle, vpTop = vpTop, vpBot = vpBot,
            }
            local plist = Theme._pending
            if plist then plist[#plist + 1] = pend end
        end

        local hideHdr = outer and def and def.boxTitle
        if hideHdr then ImGui.PushStyleColor(ImGuiCol.Text, 0, 0, 0, 0) end
        local ok = _beginBox(label, ...)
        if hideHdr then ImGui.PopStyleColor(1) end
        if ok then
            Theme._boxDepth = (Theme._boxDepth or 0) + 1
            if outer and ox then
                local ix, iy = ImGui.GetWindowPos()
                local _,  ih = ImGui.GetWindowSize()
                local pad = ix - ox
                if pad < 0 then pad = 0 end
                local bh = (iy + ih + pad) - oy
                if bh > 1 then
                    Theme._boxH[boxKey] = bh
                    Theme._boxTitleH[boxKey] = iy - oy
                    local cy1 = math.max(oy, vpTop or oy)
                    local cy2 = math.min(oy + bh, vpBot or (oy + bh))
                    if cy2 > cy1 then
                        ImGui.PushClipRect(ox, cy1, ox + ow, cy2, false)
                        def.boxBg(ox, oy, ox + ow, oy + bh)
                        if def.boxTitle and not unicodeTitle then
                            def.boxTitle(label, ox, oy, ox + ow, iy)
                        end
                        ImGui.PopClipRect()
                        local vTop = vpTop or -1e9
                        local vBot = vpBot or  1e9
                        if pend and (iy + ih) > vTop and iy < vBot then
                            pend.done = true
                        end
                    end
                end
            end
        end
        return ok
    end

    ClickGUI.EndCustomChildWindow = function(...)
        if (Theme._boxDepth or 0) > 0 then Theme._boxDepth = Theme._boxDepth - 1 end
        return _endBox(...)
    end

    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
        ClickGUI.BeginCustomChildWindow = _beginBox
        ClickGUI.EndCustomChildWindow   = _endBox
    end)
end

EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
    if scriptUnloading then return end
    local scanReady = scanDoctor.gate()
    if scanReady and settings.pendingAction then
        local action = settings.pendingAction
        settings.pendingAction = nil
        Script.QueueJob(action)
    end
    if settings._kbReloadAt and Time.GetEpocheMs() >= settings._kbReloadAt then
        settings._kbReloadAt = nil
        settings.loadKeybinds()
        settings._kbReady = true
    end
    settings.maybeSnapshotKeybinds()
end)

