local ladderFeatures = {}
for pid = 0, 31 do ladderFeatures[pid] = FeatureMgr.GetFeature(H.INFINITE_LADDER, pid) end
P.syncLadder = function()
    for pid = 0, 31 do
        local f = ladderFeatures[pid]
        local on = f ~= nil and f:IsToggled() or false
        telemetryCountToggleEdge("InfiniteLadderClimb", pid, on)
        local S = P.slots[pid .. ":" .. ladderMode]
        if not on and S and (S.wanted or busy(S)) and not S.stopRequested then requestStop(S)
        elseif on and (not S or not S.wanted) then
            f:SetBoolValue(false)
        end
    end
end
P.renderAll = function()
    ClickGUI.RenderFeature(itemHash)
    ClickGUI.RenderFeature(allAddHash)
    ImGui.SameLine()
    ClickGUI.RenderFeature(allRemoveHash)
end
local function startAll()
    local batch = P.pendingAll
    P.pendingAll = nil
    if not batch then return end
    if not ib(N.inSession) then return report("Join GTA Online before starting.") end
    local localPid = GTA.GetLocalPlayerId()
    for pid = 0, 31 do
        if pid ~= localPid and ib(N.connected, pid) then
            local S = slotFor(pid, batch.mode)
            if not (S.wanted and (S.rig or S.job or S.startRequested or S.respawn or S.retryAt)) then
                local target = targetSnapshot(pid)
                if target then
                    S.wanted = true
                    queueStart(S)
                    S.allBatch = batch
                end
            end
        end
    end
end
local function inNetworkContext(work)
    local entered = false
    Script.ExecuteAsScript("freemode", function() entered = true; work() end)
    return entered
end
P.tick = function()
    if P.unloading then return end
    local any = P.pendingAll ~= nil
    for _, S in pairs(P.slots) do if busy(S) then any = true; break end end
    if not any then return end
    P.frame = P.frame + 1
    if not inNetworkContext(function()
        startAll()
        local work = {}
        for _, S in pairs(P.slots) do if busy(S) then work[#work + 1] = S end end
        for _, S in ipairs(work) do tick(S) end
    end) then
        P.pendingAll = nil
        for _, S in pairs(P.slots) do
            local live = S.rig ~= nil or S.job ~= nil or S.cleaning
            requestStop(S)
            S.stopRequested = live
        end
    end
end
P.demoStart = function(pid, choice, prepare)
    local mode = demoModes[choice + 1]
    if P.unloading or not mode then return false, "Invalid attachment demo request." end
    local S = slotFor(pid, mode)
    S.demoPrepare, S.demoError, S.demoFit = prepare, nil, nil
    S.wanted = true
    queueStart(S)
    return true
end
P.demoStop = function(pid, choice)
    for index, mode in pairs(demoModes) do
        if (choice == nil and interactiveChoices[index - 1]) or index == (choice or -2) + 1 then
            local S = P.slots[pid .. ":" .. mode]
            if S and (S.wanted or (busy(S) and not S.stopRequested and not S.cleaning)) then requestStop(S) end
        end
    end
end
P.demoBusy = function(pid, choice)
    for index, mode in pairs(demoModes) do
        if (choice == nil and interactiveChoices[index - 1]) or index == (choice or -2) + 1 then
            local S = P.slots[pid .. ":" .. mode]
            if S and busy(S) then return true end
        end
    end
    return false
end
P.demoState = function(pid, choice)
    local mode = demoModes[choice + 1]
    local S = mode and P.slots[pid .. ":" .. mode]
    if not S then return { phase = "stopped", busy = false } end
    local r = S.rig
    local phase = (S.cleaning or S.stopRequested) and "stopping"
        or (r and r.payload and r.helper and r.helper.sceneActive and r.visibilityConfirmed and "attached")
        or (r and "settling") or (S.respawn and "respawning")
        or (busy(S) and "loading") or "stopped"
    return { phase = phase, busy = not not busy(S), error = S.demoError or S.retryError, rig = r }
end
ensureScopeSync()
P.reset = function()
    P.pendingAll, P.scopeStates = nil, {}
    if P.unloading then return end
    for _, S in pairs(P.slots) do requestStop(S) end
end
P.unload = function()
    if P.unloading then return end
    P.reset()
    P.unloading = true
    local function remaining(cleaning)
        for _, S in pairs(P.slots) do
            if S.rig or S.job or (cleaning and S.cleaning) then return true end
        end
        return false
    end
    if remaining(true) and not inNetworkContext(function()
        for _, S in pairs(P.slots) do
            if S.rig or S.job or S.cleaning then cleanup(S) end
        end
    end) then
        Logger.LogError(P.prefix .. "Unload removal: freemode script context is unavailable.")
    end
    removeVisibilitySync()
    if P.scopeHook then EventMgr.RemoveHandler(P.scopeHook); P.scopeHook = nil end
    P.scopeStates = {}
    if remaining(false) then
        Logger.LogError(P.prefix .. "Unload could not finish removing owned attachment resources.")
    else
        if P.deletePtr then Memory.Free(P.deletePtr); P.deletePtr = nil end
    end
end
end)()
centralOnTick(FeatureMgr.AddFeature(VIBE_FH("PlayerAttachmentsRunner"),
    "##PlayerAttachmentsRunner", eFeatureType.Toggle, "", function()
        if scriptUnloading or VIBE_UNLOADING then return end
        playerAttachments.syncLadder()
        playerAttachments.tick()
    end)):SetNoCallbackOnPress(true):SetSaveable(false):SetSearchable(false):SetVisible(false):Toggle(true)

;(function()
