    ClickGUI.RenderFeature(H.FUCK_VEHICLE, pid)
    ClickGUI.RenderFeature(H.RIDE_PLAYER, pid)
    ClickGUI.RenderFeature(H.RAPE_PLAYER, pid)
    ClickGUI.RenderFeature(H.INFINITE_LADDER, pid)
end
centralOnTick(FeatureMgr.AddFeature(VIBE_FH("CuratedAttachmentsRunner"), "##CuratedAttachmentsRunner", eFeatureType.Toggle,
    "", function() C.tick() end)):SetNoCallbackOnPress(true):SetSaveable(false):SetSearchable(false):SetVisible(false):Toggle(true)
end)()

;(function()
