    if not top then return nil, "Top test incomplete." end
    if not top.hit or top.normal.z < .7 then return nil, "No flat ledge top within reach." end
    if top.pos.z < wall.pos.z - .05 then return nil, "Top is below the wall hit (overhang)." end
    local rise = top.pos.z - feet
    if rise < .4 then return nil, ("Ledge only %.2fm above feet; just land."):format(rise) end
    if rise > maxRise() then return nil, ("Ledge %.2fm above feet; out of reach."):format(rise) end
    local fx, fy = wall.pos.x + nx * .25, wall.pos.y + ny * .25
    local up = shape(point(fx, fy, math.min(p.z, top.pos.z)), point(fx, fy, top.pos.z + .6), ped)
    if not up or up.hit then return nil, "Something blocks the climb above you." end
    local ex, ey = tx - nx * .25, ty - ny * .25
    local over = shape(point(fx, fy, top.pos.z + .6), point(ex, ey, top.pos.z + .6), ped)
    if not over or over.hit then return nil, "Something blocks the way over the edge." end
    local room = shape(point(ex, ey, top.pos.z + .45), point(ex, ey, top.pos.z + 1.55), ped, .28)
    if not room or room.hit then return nil, "No standing room on top." end
    return {
        start = p, final = point(ex, ey, top.pos.z + S.footOffset), top = top.pos.z,
        wall = wall.pos, nx = nx, ny = ny, rise = rise,
        heading = math.deg((math.atan2 or math.atan)(nx, -ny)),
    }, ("Ledge %.2fm above feet."):format(rise)
end

local function release(m, ped)
    if B(0x1F0B79228E461EC9, ped, DICT, m.clip.name, 3) then
        V(0x97FF36A1D40EA00A, ped, DICT, m.clip.name, -4.0)
    end
    S.mantle, S.cooldown = nil, now() + 400
end
local function start(ped, at, c)
    local clip, p0 = choose(c.rise)
    local speed = 1.2
    local rad = math.rad(c.heading)
    local cs, sn = math.cos(rad), math.sin(rad)
    local function world(r) return point(r.x * cs - r.y * sn, r.x * sn + r.y * cs, r.z) end
    local r0 = world(pathAt(clip, p0))
    local ux, uy = -c.nx, -c.ny
    local ax, ay = c.start.x - r0.x, c.start.y - r0.y
    local free = .55 + (ax - c.final.x) * ux + (ay - c.final.y) * uy
    local depth = math.max(EDGE_DEPTH, math.min(.9, free))
    ax, ay = ax + ux * (depth - free), ay + uy * (depth - free)
    local room = shape(point(ax, ay, c.top + .45), point(ax, ay, c.top + 1.55), ped, .28)
    if not room or room.hit then
        ax, ay = ax + ux * (.55 - depth), ay + uy * (.55 - depth)
    end
    local az = c.final.z
    local o = world(pathAt(clip, 0))
    V(0xAAA34F8A7CB32098, ped)
    V(0x1C99BB7B6E96D16F, ped, .0, .0, .0)
    V(0x83CDB10EA29B370B, ped, DICT, clip.name, ax + o.x + .0, ay + o.y + .0, az + o.z + .0,
        .0, .0, c.heading + .0, 8.0, -4.0, -1, ANIM_FLAGS, p0 + .0, 2, 0)
    S.mantle = { ped = ped, at = at, clip = clip, speed = speed,
        started = false, duration = clip.duration * (1 - p0) / speed }
end
local function drive(ped, at)
    local m = S.mantle
    if m.ped ~= ped or not B(0x7239B21A38F536BA, ped) or B(0x3317DEDB88C95038, ped, true)
        or B(0x47E4E977581C5B55, ped) then
        S.mantle, S.cooldown = nil, at + 400
        return
    end
    local elapsed = (at - m.at) / 1000
    local done = elapsed > m.duration + 1
    if B(0x1F0B79228E461EC9, ped, DICT, m.clip.name, 3) then
        if not m.started then
            m.started = true
            V(0x28D1A16553C51776, ped, DICT, m.clip.name, m.speed + .0)
        end
        done = done or F(0x346D81500D088F42, ped, DICT, m.clip.name) >= .99
    elseif m.started then
        done = true
    elseif elapsed > .5 then
        S.mantle, S.cooldown = nil, at + 400
        return
    end
    if done then release(m, ped) end
end
local function tick()
    if S.unloaded or scriptUnloading or VIBE_UNLOADING then return end
    if not S.features.assist:IsToggled() then
        if S.mantle then
            local ped = I(0xD80958FC74E988A6)
            if ped == S.mantle.ped and B(0x7239B21A38F536BA, ped) then release(S.mantle, ped)
            else S.mantle = nil end
        end
        return
    end
    if S.failed then return end
    local at, ped = now(), I(0xD80958FC74E988A6)
    if S.mantle then drive(ped, at); return end
    if ped ~= S.ped then S.ped, S.footAt = ped, 0 end
    if ped == 0 or not B(0x7239B21A38F536BA, ped) then return end
    if not buildClips() then return end
    if #S.clips == 0 then
        S.failed = true
        VIBE_LOG_ERROR("[AirborneMantle] No mantle clips loaded; toggle it again to retry.")
        return
    end
    local state = states(ped)
    if GUI.IsOpen() or B(0xB0034A223497FFCB) or (legacy and B(0xB118AF58B5F332A1)) then return end
    if not eligible(ped) then return end
    if not airborne(state) and not state.climb and not state.vault then learnFeet(ped, at) end
    if at < S.cooldown or state.climb or state.vault or not airborne(state) then return end
    local jump = B(0xF3A21BCD95725A4A, 0, 22) or B(0xE2587F8CBBD87B1D, 0, 22)
    if not jump then return end
    local c = ledge(ped)
    if c then start(ped, at, c) end
end
S.features.assist = FeatureMgr.AddFeature(H.AIRBORNE_MANTLE, "Airborne Mantle", eFeatureType.Toggle,
    "Hold jump while airborne near a ledge to mantle onto it.", function(f)
        if f:IsToggled() then
            S.failed = false
            if S.clips and #S.clips == 0 then S.clips = nil end
        end
    end):SetSaveable(false):SetDefaultValue(false):Reset()
function S.render()
    ClickGUI.RenderFeature(H.AIRBORNE_MANTLE)
end
function S.reset()
    S.features.assist:Reset()
    S.failed = false
end
function S.unload()
    S.unloaded, S.mantle = true, nil
    if S.buffer and S.buffer ~= 0 then Memory.Free(S.buffer) end
    S.buffer = nil
end
Script.RegisterLooped(function()
    local ok, err = pcall(tick)
    if not ok and not S.failed then
        S.failed, S.mantle = true, nil
        VIBE_LOG_ERROR("[AirborneMantle] Stopped after an error; toggle it again to retry: " .. tostring(err))
    end
    Script.Yield(0)
end)
EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, S.unload)
end)()


rideAnimalMenu = {
    interactionScript = Utils.Joaat("am_pi_menu"),
    interactionOpenLocal = IS_ENHANCED and 1796 or 1779,
    lastScriptState = nil,
    controlsBlocked = false,
}

function rideAnimalMenuOpen()
    if GUI.IsOpen() or HUD.IS_PAUSE_MENU_ACTIVE() then return true end
    local open = ScriptLocal.GetInt(
        rideAnimalMenu.interactionScript, rideAnimalMenu.interactionOpenLocal)
    if open ~= rideAnimalMenu.lastScriptState then
        rideAnimalMenu.lastScriptState = open
    end
    if open ~= nil and open ~= 0 then return true end

    local attackEnabled = Natives.InvokeBool(0x1CEA6BFDF248E5D9, 0, 24)
    local aimEnabled = Natives.InvokeBool(0x1CEA6BFDF248E5D9, 0, 25)
    local controlsBlocked = attackEnabled == false and aimEnabled == false
    if controlsBlocked ~= rideAnimalMenu.controlsBlocked then
        rideAnimalMenu.controlsBlocked = controlsBlocked
    end
    return controlsBlocked
end

