local SPINE_FALLBACKS = { 0x60F1, 0x60F0, 0x60F2, 0x5C01, 0xE0FD }
local REL_COMPANION, REL_RESPECT, REL_NEUTRAL = 0, 1, 3
local CLIMB_SEAT_BACK = 0.45
local CLIMB_RETURN_AFTER = 150
local CLIMB_RETURN_MS = 300
local MOUNT_MISSING_GRACE_MS = 1500
local DELETE_CONFIRM_MS = 2000
