    GET_SECONDARY_RGB = 0x8389CD56CA8072DC,
    SET_PRIMARY_RGB = 0x7141766F91D15BEA,
    SET_SECONDARY_RGB = 0x36CED73BFED89754,
    CLEAR_PRIMARY_RGB = 0x55E1D2758F34E437,
    CLEAR_SECONDARY_RGB = 0x5FFBDEEC3E8E2009,
    SET_MOD_KIT     = 0x1F2AA07F00B3217A,
    GET_LIVERY      = 0x2BB9230590DA5E8A,
