local function saveSettings()
    local wrote = (function()
        local lines = { "# VibeScript Settings" }

        for _, entry in ipairs(SAVEABLE_TOGGLES) do
            local name, hash = entry[1], entry[2]
            local feat = FeatureMgr.GetFeature(hash)
            if feat then
                local enabled = feat:IsToggled()
                if chatTranslate and hash == H.CHAT_TRANSLATE_IN then
                    enabled = chatTranslate.desiredIncoming
                elseif chatTranslate and hash == H.CHAT_TRANSLATE_OUT then
                    enabled = chatTranslate.desiredOutgoing
                end
                lines[#lines + 1] = ("T:%s=%d"):format(name, enabled and 1 or 0)
            end
        end

        for _, entry in ipairs(SAVEABLE_SLIDERS) do
            local name, hash, vtype = entry[1], entry[2], entry[3]
            local feat = FeatureMgr.GetFeature(hash)
            if feat then
                if vtype == "int" then
                    lines[#lines + 1] = ("I:%s=%d"):format(name, feat:GetIntValue())
                else
                    lines[#lines + 1] = ("F:%s=%.6f"):format(name, feat:GetFloatValue())
                end
            end
        end

        for _, entry in ipairs(SAVEABLE_COMBOS) do
            local name, hash, count = entry[1], entry[2], entry[3]
            local feat = FeatureMgr.GetFeature(hash)
            if feat and count then
                local bits = {}
                for i = 0, count - 1 do
                    bits[i + 1] = feat:IsListIndexToggled(i) and "1" or "0"
                end
                lines[#lines + 1] = ("C:%s=%s"):format(name, table.concat(bits))
            end
        end

        do
            local pick = FeatureMgr.GetFeature(H.FORCE_ACTION_ALL_PICK):GetListIndex() or 0
            local action = forceActions.actions[pick + 1] or forceActions.actions[1]
            lines[#lines + 1] = "V:forceActionAll=" .. action[2]
        end

        lines[#lines + 1] = ("V:classIdx=%d"):format(vehGun.classIdx)
        lines[#lines + 1] = ("V:lazerExpTagIdx=%d"):format(lazerExpTag.idx)
        lines[#lines + 1] = ("V:vehIdx=%d"):format(vehGun.vehIdx)
        lines[#lines + 1] = ("V:rewindVK=%d"):format(rewindState.rewindVK)
        lines[#lines + 1] = ("V:rewindCtrl=%d"):format(rewindState.controlId)
        lines[#lines + 1] = ("V:superDriveVK=%d"):format(superDriveKey.vk)
        lines[#lines + 1] = ("V:superDriveCtrl=%d"):format(superDriveKey.controlId)
        lines[#lines + 1] = ("V:wheelieVK=%d"):format(wheelie.vk)
        lines[#lines + 1] = ("V:wheelieCtrl=%d"):format(wheelie.controlId)
        lines[#lines + 1] = ("V:titanCannonVK=%d"):format(titanCannonCycle.vk)
        lines[#lines + 1] = ("V:titanCannonCtrl=%d"):format(titanCannonCycle.controlId)
        lines[#lines + 1] = ("V:titanCannonHops=%d"):format(titanCannonCycle.shuffleHops or 2)
        lines[#lines + 1] = ("V:titanCannonDelay=%d"):format(titanCannonCycle.shuffleDelayMs or 1500)
        lines[#lines + 1] = ("V:titanCannonTarget=%d"):format(titanCannonCycle.targetGunnerSeat or titanCannonCycle.DEFAULT_TARGET)
        lines[#lines + 1] = ("V:titanCannonExit=%d"):format(titanCannonCycle.exitTargetSeat or titanCannonCycle.DEFAULT_EXIT)
        lines[#lines + 1] = ("V:consoleLines=%d"):format(console.maxLines)
        lines[#lines + 1] = ("V:exemptFriends=%d"):format(
            lockOntoPlayers.sessionExemptAllies and 1 or 0)
        lines[#lines + 1] = ("V:radioPickerUsed=%d"):format(radioCtl.pickerUsed and 1 or 0)
        lines[#lines + 1] = ("V:aptTeleportIdx=%d"):format(aptTeleport.getIdx(H.APT_TP_PICK))
        lines[#lines + 1] = ("V:aptTeleportPlIdx=%d"):format(aptTeleport.getIdx(H.APT_TP_PL_PICK))
        local cmType = FeatureMgr.GetFeature(H.COUNTERMEASURE_TYPE)
        if cmType then
            lines[#lines + 1] = ("V:countermeasureType=%d"):format(cmType:GetListIndex())
        end
        local cmDirection = FeatureMgr.GetFeature(H.COUNTERMEASURE_DIRECTION)
        if cmDirection then
            lines[#lines + 1] = ("V:countermeasureDirection=%d"):format(cmDirection:GetListIndex())
        end
        local expType = FeatureMgr.GetFeature(H.EXP_BULLETS_TAG)
        if expType then
            lines[#lines + 1] = ("V:expBulletsTagIdx=%d"):format(expType:GetListIndex())
        end
        if soundSpam then
            lines[#lines + 1] = ("V:soundSpamAllIdx=%d"):format(
                soundSpam.getIdx(H.SOUND_PICK_ALL))
        end
        lines[#lines + 1] = ("V:customCamModeId=%s"):format(customCam.getModeId())
        lines[#lines + 1] = ("V:musicalHornSong=%d"):format(musicalHorns.getSongIndex())
        if countryFinder then
            local sel = {}
            for cc in pairs(countryFinder.selected) do sel[#sel + 1] = cc end
            table.sort(sel)
            lines[#lines + 1] = ("V:countrySel=%s"):format(#sel > 0 and table.concat(sel, ",") or "-")
        end
        local lm = LoadoutMgr.save()
        lines[#lines + 1] = ("V:lmPreview=%d"):format(lm.preview)
        lines[#lines + 1] = ("V:lmRestoreOnRespawn=%d"):format(lm.restoreOnRespawn)

        lines[#lines + 1] = ("V:rideAnimalModel=%s"):format(rideAnimal.encodeModel())
        lines[#lines + 1] = ("V:rideAnimalTune=%s"):format(rideAnimal.encodeTune())

        if chatTranslate then
            lines[#lines + 1] = ("V:chatTranslate=%s"):format(chatTranslate.encode())
        end

        if chatCommands then
            lines[#lines + 1] = ("V:ccConfig=%s"):format(chatCommands.encode())
            lines[#lines + 1] = ("V:spawnVehModel=%s"):format(chatCommands.vehPick.model)
        end

        local content = table.concat(lines, "\n")
        return FileMgr.WriteFileContent(settings.file, content, false)
    end)()

    if wrote then
        settings.status = T("Settings saved.")
        GUI.AddToast("VibeScript", T("Settings saved."), 3000)
    else
        settings.status = T("Save failed: %s"):format(settings.file)
        logErr("Save settings failed: could not write " .. settings.file)
    end
end

local function loadSettings()
    if not FileMgr.DoesFileExist(settings.file) then
        settings.status = T("No saved settings found.")
        GUI.AddToast("VibeScript", T("No saved settings found."), 3000)
        return
    end

    local ok, err = pcall(function()
        local content = FileMgr.ReadFileContent(settings.file)
        if not content or #content == 0 then
            error("Settings file is empty")
        end

        local toggleMap = {}
        local floatMap  = {}
        local intMap    = {}
        local comboMap  = {}
        local valueMap  = {}

        for line in content:gmatch("[^\r\n]+") do
            if line:sub(1, 1) ~= "#" then
                local prefix, rest = line:match("^(%a):(.+)$")
                if prefix and rest then
                    local key, val = rest:match("^(.-)=(.+)$")
                    if key and val then
                        if prefix == "T" then
                            toggleMap[key] = val == "1"
                        elseif prefix == "F" then
                            floatMap[key] = tonumber(val)
                        elseif prefix == "I" then
                            intMap[key] = tonumber(val)
                        elseif prefix == "C" then
                            comboMap[key] = val
                        elseif prefix == "V" then
                            valueMap[key] = val
                        end
                    end
                end
            end
        end

        if toggleMap["LUA_RickRollHorn"] then
            toggleMap["LUA_MusicalHorns"] = true
            log("[Settings] LUA_RickRollHorn=1 migrated to LUA_MusicalHorns")
        end

        if valueMap["forceActionAll"] then
            for i, action in ipairs(forceActions.actions) do
                if action[2] == valueMap["forceActionAll"] then
                    FeatureMgr.GetFeature(H.FORCE_ACTION_ALL_PICK):SetListIndex(i - 1)
                    break
                end
            end
        end

        lockOntoPlayers.sessionExemptAllies = valueMap["exemptFriends"] ~= "0"
        if chatCommands then
            chatCommands.loadPersistent(valueMap["ccConfig"])
        elseif valueMap["ccConfig"] and chatCommands then
            chatCommands.decode(valueMap["ccConfig"])
        end
        if valueMap["chatTranslate"] and chatTranslate then
            chatTranslate.decode(valueMap["chatTranslate"])
        end
        if valueMap["rideAnimalModel"] or valueMap["rideAnimalTune"] then
            rideAnimal.decode(valueMap["rideAnimalModel"], valueMap["rideAnimalTune"])
        end
        if valueMap["spawnVehModel"] and chatCommands then
            chatCommands.setPickedVehicle(valueMap["spawnVehModel"])
        end
        if valueMap["classIdx"] then vehGun.classIdx = tonumber(valueMap["classIdx"]) or 1 end
        if valueMap["vehIdx"]   then vehGun.vehIdx   = tonumber(valueMap["vehIdx"])   or 1 end
        if valueMap["lazerExpTagIdx"] then
            local i = tonumber(valueMap["lazerExpTagIdx"])
            if i and i >= 1 and i <= #lazerExpTag.labels then
                lazerExpTag.idx = i
            end
        end
        if valueMap["rewindVK"] then
            local vk = tonumber(valueMap["rewindVK"])
            if vk and vk >= 1 and vk <= 255 then
                rewindState.rewindVK = vk
                local kf = FeatureMgr.GetFeature(H.REWIND_KEY)
                if kf then kf:SetIntValue(vk) end
            end
        end
        if valueMap["rewindCtrl"] then
            local id = tonumber(valueMap["rewindCtrl"])
            if id and id >= 0 and id <= 350 then
                rewindState.controlId = id
            end
        end
        if valueMap["superDriveVK"] then
            local vk = tonumber(valueMap["superDriveVK"])
            if vk and vk >= 1 and vk <= 255 then
                superDriveKey.vk = vk
            end
        end
        if valueMap["superDriveCtrl"] then
            local id = tonumber(valueMap["superDriveCtrl"])
            if id and id >= 0 and id <= 350 then
                superDriveKey.controlId = id
            end
        end
        if valueMap["wheelieVK"] then
            local vk = tonumber(valueMap["wheelieVK"])
            if vk and vk >= 1 and vk <= 255 then
                wheelie.vk = vk
            end
        end
        if valueMap["wheelieCtrl"] then
            local id = tonumber(valueMap["wheelieCtrl"])
            if id and id >= 0 and id <= 350 then
                wheelie.controlId = id
            end
        end
        if valueMap["titanCannonVK"] then
            local vk = tonumber(valueMap["titanCannonVK"])
            if vk and vk >= 1 and vk <= 255 then
                titanCannonCycle.vk = vk
            end
        end
        if valueMap["titanCannonCtrl"] then
            local id = tonumber(valueMap["titanCannonCtrl"])
            if id and id >= 0 and id <= 350 then
                titanCannonCycle.controlId = id
            end
        end
        if valueMap["titanCannonHops"] then
            local h = tonumber(valueMap["titanCannonHops"])
            if h and h >= 1 and h <= 3 then titanCannonCycle.shuffleHops = h end
        end
        if valueMap["titanCannonDelay"] then
            local d = tonumber(valueMap["titanCannonDelay"])
            if d and d >= 250 and d <= 3000 then titanCannonCycle.shuffleDelayMs = d end
        end
        if valueMap["titanCannonTarget"] then
            local t = tonumber(valueMap["titanCannonTarget"])
            if t and (t == 2 or t == 3 or t == 4) then titanCannonCycle.targetGunnerSeat = t end
        end
        if valueMap["titanCannonExit"] then
            local e = tonumber(valueMap["titanCannonExit"])
            if e and (e == 0 or e == 1) then titanCannonCycle.exitTargetSeat = e end
        end
        if valueMap["consoleLines"] then
            local n = tonumber(valueMap["consoleLines"])
            if n then console.maxLines = math.max(50, math.min(n, console.MAX_LINES_CAP)) end
        end
        if valueMap["radioPickerUsed"] == "1" and radioCtl then radioCtl.pickerUsed = true end
        if valueMap["aptTeleportIdx"] then
            aptTeleport.setIdx(H.APT_TP_PICK, tonumber(valueMap["aptTeleportIdx"]))
        end
        if valueMap["aptTeleportPlIdx"] then
            aptTeleport.setIdx(H.APT_TP_PL_PICK, tonumber(valueMap["aptTeleportPlIdx"]))
        end
        if soundSpam and valueMap["soundSpamAllIdx"] then
            soundSpam.setIdx(H.SOUND_PICK_ALL, tonumber(valueMap["soundSpamAllIdx"]),
                soundSpam.sessionCues)
        end
        if valueMap["customCamModeId"] then
            customCam.setModeId(valueMap["customCamModeId"])
        elseif valueMap["customCamMode2"] then
            local old = tonumber(valueMap["customCamMode2"])
            customCam.setMode(old and customCam.MODE_REMAP_V2[old] or nil)
        elseif valueMap["customCamMode"] then
            local old = tonumber(valueMap["customCamMode"])
            customCam.setMode(old and customCam.MODE_REMAP_V1[old] or nil)
        end
        if valueMap["musicalHornSong"] then
            musicalHorns.setSongIndex(tonumber(valueMap["musicalHornSong"]))
        end
        if valueMap["lmPreview"]    then LoadoutMgr.load("preview",   tonumber(valueMap["lmPreview"]))    end
        if valueMap["lmRestoreOnRespawn"] then LoadoutMgr.load("restoreOnRespawn", tonumber(valueMap["lmRestoreOnRespawn"])) end

        if valueMap["countrySel"] then
            local sel = {}
            if valueMap["countrySel"] ~= "-" then
                for cc in valueMap["countrySel"]:gmatch("%u%u") do sel[cc] = true end
            end
            if countryFinder then
                countryFinder.selected = sel
            else
                settings._pendingCountrySel = sel
            end
        end

        settings.pendingAction = function()
            for _, entry in ipairs(SAVEABLE_TOGGLES) do
                local name, hash = entry[1], entry[2]
                local feat = FeatureMgr.GetFeature(hash)
                if feat and toggleMap[name] ~= nil then
                    local shouldBeOn = toggleMap[name]
                    if chatTranslate and hash == H.CHAT_TRANSLATE_IN then
                        chatTranslate.desiredIncoming = shouldBeOn
                    elseif chatTranslate and hash == H.CHAT_TRANSLATE_OUT then
                        chatTranslate.desiredOutgoing = shouldBeOn
                    end
                    if chatTranslate and not (chatTranslate.desiredIncoming or chatTranslate.desiredOutgoing) then
                        chatTranslate.recovery = nil
                    end
                    if feat:IsToggled() ~= shouldBeOn then
                        feat:Toggle()
                    end
                end
            end

            for _, entry in ipairs(SAVEABLE_SLIDERS) do
                local name, hash, vtype = entry[1], entry[2], entry[3]
                local feat = FeatureMgr.GetFeature(hash)
                if feat then
                    local applied = false
                    if vtype == "int" and intMap[name] then
                        feat:SetIntValue(intMap[name])
                        applied = true
                    elseif vtype == "float" and floatMap[name] then
                        feat:SetFloatValue(floatMap[name])
                        applied = true
                    end
                    if applied and not CENTRAL_TICK.isTick[hash] then
                        local cb = CENTRAL_TICK.cb[hash]
                        if cb then cb(feat) end
                    end
                end
            end

            for _, entry in ipairs(SAVEABLE_COMBOS) do
                local name, hash, count = entry[1], entry[2], entry[3]
                local feat = FeatureMgr.GetFeature(hash)
                local bits = comboMap[name]
                if feat and count and bits and #bits == count then
                    for i = 0, count - 1 do
                        feat:ToggleListIndex(i, bits:sub(i + 1, i + 1) == "1")
                    end
                end
            end

            local cmType = FeatureMgr.GetFeature(H.COUNTERMEASURE_TYPE)
            local cmTypeIdx = tonumber(valueMap["countermeasureType"])
            if cmType and cmTypeIdx then
                cmType:SetListIndex(math.max(0, math.min(2, math.floor(cmTypeIdx))))
            end
            local cmDirection = FeatureMgr.GetFeature(H.COUNTERMEASURE_DIRECTION)
            local cmDirectionIdx = tonumber(valueMap["countermeasureDirection"])
            if cmDirection and cmDirectionIdx then
                cmDirection:SetListIndex(math.max(0, math.min(4, math.floor(cmDirectionIdx))))
            end
            local expType = FeatureMgr.GetFeature(H.EXP_BULLETS_TAG)
            local expTypeIdx = tonumber(valueMap["expBulletsTagIdx"])
            if expType and expTypeIdx then
                expType:SetListIndex(math.max(0, math.min(
                    #playerState.expBulletNames - 1, math.floor(expTypeIdx))))
            end
        end
    end)

    if ok then
        settings.status = T("Settings loaded.")
        GUI.AddToast("VibeScript", T("Settings loaded."), 3000)
    else
        settings.status = T("Load failed: %s"):format(tostring(err))
        logErr("Load settings failed: " .. tostring(err))
    end
end

local function restoreDefaults()
    settings.pendingAction = function()
        lockOntoPlayers.sessionExemptAllies = true
        resetAll()
        vehGun.classIdx = 1
        vehGun.vehIdx = 1
        console.enabled = false
    end
    settings.status = T("Defaults restored. Saved config kept.")
