countermeasures.projectilePoolCount = function()
    if not noclipRockets or not noclipRockets.resolvePool
       or not noclipRockets.resolvePool() then return nil end
    local base = noclipRockets.poolElems
    if not base or base == 0 then return nil end
    local count = Memory.ReadInt(base + noclipRockets.COUNT_OFF)
    if type(count) ~= "number" or count < 0
       or count > noclipRockets.MAX_SLOTS then return nil end
    return count
end

countermeasures.projectilePoolSnapshot = function()
    local s = countermeasures
    if not noclipRockets or not noclipRockets.resolvePool
       or not noclipRockets.resolvePool() then return nil, nil end
    local base = noclipRockets.poolElems
    if not base or base == 0 then return nil, nil end
    local count = Memory.ReadInt(base + noclipRockets.COUNT_OFF)
    if type(count) ~= "number" or count < 0
       or count > noclipRockets.MAX_SLOTS then return nil, nil end
    local live, ordered = {}, {}
    for i = 0, count - 1 do
        local addr = Memory.ReadLong(base + i * 8)
        if addr and addr ~= 0 then
            live[addr] = true
            ordered[#ordered + 1] = addr
        end
    end
    return live, ordered
end

countermeasures.pruneTrackedFlares = function(live)
    local s, kept = countermeasures, {}
    if not live then live = s.projectilePoolSnapshot() end
    if not live then return end
    for i = 1, #s.trackedFlares do
        local addr = s.trackedFlares[i]
        if live[addr] then kept[#kept + 1] = addr end
    end
    s.trackedFlares = kept
end

countermeasures.captureNewFlare = function(before)
    if not before then return end
    local s = countermeasures
    local live, ordered = s.projectilePoolSnapshot()
    if not live then return end
    s.pruneTrackedFlares(live)
    for i = 1, #ordered do
        local addr = ordered[i]
        if not before[addr] then
            s.trackedFlares[#s.trackedFlares + 1] = addr
            s.calibrateWeaponOffset(addr, s.u32(s.FLARE_WEAPON))
            return
        end
    end
end

countermeasures.destroyOldestTrackedFlare = function()
    local s = countermeasures
    local live = s.projectilePoolSnapshot()
    if not live then return false end
    s.pruneTrackedFlares(live)
    local addr = table.remove(s.trackedFlares, 1)
    if not addr or not live[addr] then return false end

    local vtable = Memory.ReadLong(addr)
    if not vtable or vtable == 0 then return false end
    local destroyFn = Memory.ReadLong(vtable + (IS_ENHANCED and 0x4C8 or 0x4D8))
    if not destroyFn or destroyFn == 0 then return false end
    Memory.LuaCallCFunction(destroyFn, addr)
    return true
end

countermeasures.clearFlares = function()
    Natives.InvokeVoid(0xFC52E0F37E446528, countermeasures.FLARE_WEAPON, false)
end

countermeasures.restoreChaff = function()
    local c = countermeasures.chaff
    countermeasures.chaff = nil
    if not c or not c.original then return end
    local phys = GTA.HandleToPointer(c.veh)
    if not phys then return end
    local addr = phys:GetAddress()
    if not addr or addr == 0 or addr ~= c.addr then return end
    if Memory.ReadByte(addr + lockOntoPlayers.OFF_VEH_ALLOW_HOMING_LOCKON) == 0 then
        Natives.InvokeVoid(0x1DDA078D12879EEE, c.veh, true, false)
    end
end

countermeasures.playChaffFx = function(veh)
    local pos = ENTITY.GET_ENTITY_COORDS(veh, true)
