    Natives.InvokeBool(0xF56B8137DF10135D,
        countermeasures.CHAFF_FX, pos.x, pos.y, pos.z,
        0.0, 180.0, 0.0, 5.0, true, true, true, false)
end

countermeasures.deployChaff = function(veh, now)
    local s = countermeasures
    local phys = GTA.HandleToPointer(veh)
    local addr = phys and phys:GetAddress() or nil
    if not addr or addr == 0 then return end

    if s.chaff and (s.chaff.veh ~= veh or s.chaff.addr ~= addr) then
        s.restoreChaff()
    end
    if s.chaff then
        s.chaff.untilAt = now + s.CHAFF_MS
    else
        local original = Memory.ReadByte(addr + lockOntoPlayers.OFF_VEH_ALLOW_HOMING_LOCKON) ~= 0
        s.chaff = { veh = veh, addr = addr, original = original, untilAt = now + s.CHAFF_MS }
        if original then
            Natives.InvokeVoid(0x1DDA078D12879EEE, veh, false, false)
        end
    end

    AUDIO.PLAY_SOUND_FROM_ENTITY(-1, "chaff_released", veh,
        "DLC_SM_Countermeasures_Sounds", true, 0)
    STREAMING.REQUEST_NAMED_PTFX_ASSET(s.CHAFF_ASSET)
    if STREAMING.HAS_NAMED_PTFX_ASSET_LOADED(s.CHAFF_ASSET) then
        s.playChaffFx(veh)
        s.chaffFx = nil
    else
        s.chaffFx = { veh = veh, deadline = now + 3000 }
    end
end

countermeasures.flareVector = function(direction, shot, count)
    local pair = math.floor((shot - 1) / 2)
    local side = ((shot - 1) % 2 == 0) and -1.0 or 1.0
    local spread = 2.5 + pair * 0.65
    if direction == 0 then
        return side * spread, -8.0, 0.0
    elseif direction == 1 then
        return side * 8.0, -1.0 - pair * 0.35, 0.0
    elseif direction == 2 then
        return side * spread, -3.0, -8.0
    elseif direction == 3 then
        return side * spread, -3.0, 8.0
    end
    local angle = (shot - 1) * (math.pi * 2.0 / math.max(1, count))
    local z = (((shot - 1) % 3) - 1) * 5.0
    return math.cos(angle) * 7.0, math.sin(angle) * 7.0, z
end

countermeasures.startFlares = function(veh, count, direction, now)
    local s = countermeasures
    s.flare = {
        veh = veh,
        count = count,
        direction = direction,
        shot = 1,
        nextAt = now,
        loadDeadline = now + 3000,
        sounding = false,
    }
    STREAMING.REQUEST_MODEL(s.FLARE_MODEL)
    s.modelHeld = true
end

countermeasures.stepFlares = function(now)
    local s, f = countermeasures, countermeasures.flare
    if not f then return end
    if not ENTITY.DOES_ENTITY_EXIST(f.veh) then
        s.flare = nil
        s.releaseModel()
        return
    end
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
    if VEHICLE.GET_PED_IN_VEHICLE_SEAT(f.veh, -1, false) ~= ped then
        s.flare = nil
        s.releaseModel()
        return
    end
    if not STREAMING.HAS_MODEL_LOADED(s.FLARE_MODEL) then
        if now >= f.loadDeadline then
            s.flare = nil
            s.releaseModel()
            GUI.AddToast("VibeScript", T("Countermeasure flare model did not load."), 3000)
        else
            STREAMING.REQUEST_MODEL(s.FLARE_MODEL)
        end
        return
    end
    if now < f.nextAt then return end
    if not f.sounding then
        AUDIO.PLAY_SOUND_FROM_ENTITY(-1, "flares_released", f.veh,
            "DLC_SM_Countermeasures_Sounds", true, 0)
        f.sounding = true
    end

    local x, y, z = s.flareVector(f.direction, f.shot, f.count)
    local from = ENTITY.GET_ENTITY_COORDS(f.veh, true)
    local target = ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(f.veh, x, y, z)
    local poolCount = s.projectilePoolCount()
    if poolCount and poolCount >= s.PROJECTILE_POOL_MAX then
        if not f.waitingForSlot then
            if not s.destroyOldestTrackedFlare() then s.clearFlares() end
            f.waitingForSlot = true
        end
        return
    end
    f.waitingForSlot = false
    local before = s.projectilePoolSnapshot()
    MISC.SHOOT_SINGLE_BULLET_BETWEEN_COORDS(
        from.x, from.y, from.z, target.x, target.y, target.z,
        1, true, s.FLARE_WEAPON, ped, true, true, 1.0)
    s.captureNewFlare(before)

    f.shot = f.shot + 1
    if f.shot > f.count then
        s.flare = nil
        s.releaseModel()
    else
        f.nextAt = now + s.FLARE_GAP_MS
    end
end

countermeasures.beginPending = function(now)
    local s = countermeasures
    if not s.pending then return end
    local isAuto = s.pendingAuto
    s.pending = false
    s.pendingAuto = false
    if not isAuto and isGameChatOpen() then return end

    if s.flare then
        s.flare = nil
        s.releaseModel()
    end

    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
    if not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        GUI.AddToast("VibeScript", T("Enter a vehicle before deploying countermeasures."), 2500)
        return
    end
    local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if veh == 0 or VEHICLE.GET_PED_IN_VEHICLE_SEAT(veh, -1, false) ~= ped then
        GUI.AddToast("VibeScript", T("You must be driving or piloting the vehicle."), 2500)
        return
    end

    local typeFeature = FeatureMgr.GetFeature(H.COUNTERMEASURE_TYPE)
    local countFeature = FeatureMgr.GetFeature(H.COUNTERMEASURE_COUNT)
    local directionFeature = FeatureMgr.GetFeature(H.COUNTERMEASURE_DIRECTION)
    local kind = typeFeature and (typeFeature:GetListIndex() or 0) or 0
    local count = countFeature and (countFeature:GetIntValue() or 4) or 4
    local direction = directionFeature and (directionFeature:GetListIndex() or 0) or 0
    count = math.max(1, math.min(20, count))

    telemetryCountAction("DeployCountermeasure")
    if kind == 1 or kind == 2 then s.deployChaff(veh, now) end
    if kind == 0 or kind == 2 then s.startFlares(veh, count, direction, now) end
end

countermeasures.WEAPON_OFF_MIN = 0x100
countermeasures.WEAPON_OFF_MAX = 0x800
countermeasures.WEAPON_OFF_TRIES = 12

countermeasures.looksLikePointer = function(p)
    return type(p) == "number" and p > 0x10000 and p < 0x7FFFFFFFFFFF and p % 4 == 0
end

countermeasures.calibrateWeaponOffset = function(addr, knownHash)
    local s = countermeasures
    if s.weaponHashOff or not addr or addr == 0 then return end
    if s.weaponHashTries >= s.WEAPON_OFF_TRIES then return end
    s.weaponHashTries = s.weaponHashTries + 1

    local found = nil
    for off = s.WEAPON_OFF_MIN, s.WEAPON_OFF_MAX, 8 do
        local hash = Memory.ReadUInt(addr + off)
        if s.u32(hash) == knownHash
           and s.looksLikePointer(Memory.ReadLong(addr + off - 8)) then
            local owner = Memory.ReadLong(addr + off + 8)
            if owner == 0 or s.looksLikePointer(owner) then
                if found then
                    logf("[Countermeasures] weapon offset ambiguous (+0x%X and +0x%X); "
                        .. "not latching", found, off)
                    return
                end
                found = off
            end
        end
    end

    if found then
        s.weaponHashOff = found
        logf("[Countermeasures] weapon hash offset calibrated at +0x%X on attempt %d",
            found, s.weaponHashTries)
    elseif s.weaponHashTries >= s.WEAPON_OFF_TRIES then
        logf("[Countermeasures] weapon hash offset not found after %d flare(s); "
            .. "auto-deploy continues on geometry alone", s.weaponHashTries)
    end
end

countermeasures.projectileWeaponHash = function(addr)
    local s = countermeasures
    local off = s.weaponHashOff
    if not off then return nil end
    if not s.looksLikePointer(Memory.ReadLong(addr + off - 8)) then return nil end
    return s.u32(Memory.ReadUInt(addr + off))
end

countermeasures.entityAddress = function(handle)
    if not handle or handle == 0 then return nil end
    local phys = GTA.HandleToPointer(handle)
    if not phys then return nil end
    local addr = phys:GetAddress()
    if type(addr) ~= "number" or addr == 0 then return nil end
    return addr
end

countermeasures.projectileOwner = function(addr)
    local s = countermeasures
    if not s.weaponHashOff then return nil end
    local owner = Memory.ReadLong(addr + s.weaponHashOff + 8)
    if not owner or owner == 0 then return nil end
    return owner
end

countermeasures.isInboundThreat = function(addr, target, vehVel)
    local s = countermeasures
    local projectile = CPhysical.FromAddress(addr)
    if not projectile then return false end
    local pos, vel = projectile.Position, projectile:GetVelocity()
    if not pos or not vel then return false end

    local tx, ty, tz = target.x - pos.x, target.y - pos.y, target.z - pos.z
    local dist = math.sqrt(tx * tx + ty * ty + tz * tz)
    if dist < s.AUTO_MIN_DIST or dist > s.AUTO_SCAN_RADIUS then return false end

    local vx, vy, vz = vel.x - vehVel.x, vel.y - vehVel.y, vel.z - vehVel.z
    local speed = math.sqrt(vx * vx + vy * vy + vz * vz)
    if speed < s.AUTO_MIN_SPEED then return false end
    local closing = (vx * tx + vy * ty + vz * tz) / dist
    if closing <= 0 or closing / speed < s.AUTO_MIN_AIM_COS then return false end
    if dist / closing > s.AUTO_MAX_TTI then return false end
    return true, dist, closing
end

countermeasures.scanInboundMissiles = function(ped, veh, now)
    local s = countermeasures
    local live, ordered = s.projectilePoolSnapshot()
    if not live then
        if not s.poolWarned then
            s.poolWarned = true
            logf("[Countermeasures] auto-deploy inactive: ms_projectiles unresolved")
        end
        return
    end

    for addr in pairs(s.autoSeen) do
        if not live[addr] then s.autoSeen[addr] = nil end
    end
    if now - s.autoLastDeploy < s.AUTO_COOLDOWN_MS then return end

    local mine = {}
    for i = 1, #s.trackedFlares do mine[s.trackedFlares[i]] = true end
    local pedAddr = s.entityAddress(ped)
    local vehAddr = s.entityAddress(veh)
    local target = ENTITY.GET_ENTITY_COORDS(veh, true)
    local vehVel = ENTITY.GET_ENTITY_VELOCITY(veh)

    for i = 1, #ordered do
        local addr = ordered[i]
        if not s.autoSeen[addr] and not mine[addr] then
            local owner = s.projectileOwner(addr)
            if owner == nil or (owner ~= pedAddr and owner ~= vehAddr) then
                local threat, dist, closing = s.isInboundThreat(addr, target, vehVel)
                if threat then
                    s.autoSeen[addr] = true
                    s.autoLastDeploy = now
                    s.pending = true
                    s.pendingAuto = true
                    local hash = s.projectileWeaponHash(addr)
                    logf("[Countermeasures] auto-deploy: %s at %.0fm closing %.0f m/s",
                        hash and ("weapon 0x%08X%s"):format(hash,
                            s.AUTO_MISSILE_HASHES[hash] and "" or " (unlisted)")
                            or "unidentified projectile",
                        dist, closing)
                    return
                end
            end
        end
    end
end

countermeasures.onTick = function(f)
    if not f:IsToggled() then return end
    local s = countermeasures
    local now = MISC.GET_GAME_TIMER()
    local deployKeys = settings.kbReadKeys(HotKeyMgr.GetHotKeys(H.COUNTERMEASURE_DEPLOY))
    local deployKeyDown = false
    for i = 1, #deployKeys do
        if isAnyKeyDown(deployKeys[i]) then deployKeyDown = true; break end
    end
    if s.hotkeyBlocked then
        s.pending = false
        if not deployKeyDown then s.hotkeyBlocked = false end
    elseif s.pending and deployKeyDown then
        s.hotkeyBlocked = true
    end
    local auto = FeatureMgr.GetFeature(H.COUNTERMEASURE_AUTO)
    if auto and auto:IsToggled() then
        local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
        local veh = ped ~= 0 and PED.GET_VEHICLE_PED_IS_IN(ped, false) or 0
        if veh ~= 0 and VEHICLE.GET_PED_IN_VEHICLE_SEAT(veh, -1, false) == ped then
            s.scanInboundMissiles(ped, veh, now)
        else
            s.autoSeen = {}
        end
    elseif next(s.autoSeen) ~= nil then
        s.autoSeen = {}
    end
    if s.chaff and now >= s.chaff.untilAt then s.restoreChaff() end
    if s.chaffFx then
        if not ENTITY.DOES_ENTITY_EXIST(s.chaffFx.veh) or now >= s.chaffFx.deadline then
            s.chaffFx = nil
        elseif STREAMING.HAS_NAMED_PTFX_ASSET_LOADED(s.CHAFF_ASSET) then
            s.playChaffFx(s.chaffFx.veh)
            s.chaffFx = nil
        else
            STREAMING.REQUEST_NAMED_PTFX_ASSET(s.CHAFF_ASSET)
        end
    end
    s.beginPending(now)
    s.stepFlares(now)
end

