EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    countermeasures.pending = false
    countermeasures.pendingAuto = false
    countermeasures.flare = nil
    countermeasures.restoreChaff()
    countermeasures.releaseModel()
end)

turnSignals = {
    runnerHash = VIBE_FH("TurnSignalsRunner"),
    H_SET_INDICATOR = 0xB5D45264751B7DF0,
    H_GEN_DIRECTIONS = 0xF90125F1F79ECDF8,
    H_WAYPOINT_ACTIVE = 0x1DD1F58F493F1DA5,
    H_FIRST_BLIP = 0x1BEDE233E6CD2A1F,
    H_BLIP_COORD = 0xFA7C7F0AADF25D09,
    BLIP_WAYPOINT = 8,

    DIR_LEFT = 3, DIR_RIGHT = 4,
    DIR_UNKNOWN = 0, DIR_WRONG_WAY = 1,

    LEAD_SECONDS = 3.5, LEAD_MIN = 30.0, LEAD_MAX = 90.0,
    POLL_MS = 200,

    SAMPLE_MS = 100,
    TURN_START_DEG = 22.0,
    TURN_DONE_DEG  = 40.0,
    STEADY_RATE    = 20.0,
    STEADY_MS      = 500,
    COUNTER_DEG    = 55.0,
    ABORT_METRES   = 200.0,

    veh = 0,
    mode = "none",
    autoSide = nil,
    lastL = false, lastR = false, lastH = false,
    appliedMode = nil, appliedVeh = 0, appliedAt = 0,
    nextPollAt = 0, gpsMiss = 0, autoVeto = nil,
    lastDir = nil, dirLogAt = 0, armSide = nil, armAgree = 0,
    nextSampleAt = 0, sampledAt = 0,
    armHeading = nil, lastHeading = nil, lastPos = nil,
    travelled = 0.0, turnBegun = false, steadyMs = 0,
    cleared = false,
    usedManual = false,
    buf = Memory.Alloc(24),
}

function turnSignals.angDiff(a, b)
    local d = (a - b) % 360.0
    if d > 180.0 then d = d - 360.0 end
    return d
end

function turnSignals.apply(now)
    local s = turnSignals
    if s.veh == 0 or not ENTITY.DOES_ENTITY_EXIST(s.veh) then return end
    if s.mode == s.appliedMode and s.veh == s.appliedVeh and now < s.appliedAt + 500 then return end
    local left  = s.mode == "left"  or s.mode == "hazard"
    local right = s.mode == "right" or s.mode == "hazard"
    Natives.InvokeVoid(s.H_SET_INDICATOR, s.veh, 1, left)
    Natives.InvokeVoid(s.H_SET_INDICATOR, s.veh, 0, right)
    s.appliedMode, s.appliedVeh, s.appliedAt = s.mode, s.veh, now
end

function turnSignals.clear(veh)
    if veh == 0 or not ENTITY.DOES_ENTITY_EXIST(veh) then return end
    Natives.InvokeVoid(turnSignals.H_SET_INDICATOR, veh, 1, false)
    Natives.InvokeVoid(turnSignals.H_SET_INDICATOR, veh, 0, false)
end

function turnSignals.setMode(mode, now)
    local s = turnSignals
    if s.mode == mode then return end
    s.mode = mode
    if mode ~= "left" and mode ~= "right" then
        s.autoSide, s.armHeading = nil, nil
        return
    end
    s.armHeading = (s.veh ~= 0) and ENTITY.GET_ENTITY_HEADING(s.veh) or nil
    s.lastHeading = s.armHeading
    s.lastPos = (s.veh ~= 0) and ENTITY.GET_ENTITY_COORDS(s.veh, true) or nil
    s.travelled, s.turnBegun, s.steadyMs, s.gpsMiss = 0.0, false, 0, 0
    s.sampledAt, s.nextSampleAt = now, now + s.SAMPLE_MS
end

function turnSignals.syncToggles(fl, fr, fh)
    local s = turnSignals
    local L, R, HZ = s.mode == "left", s.mode == "right", s.mode == "hazard"
    if fl:IsToggled() ~= L then fl:Toggle(L) end
    if fr:IsToggled() ~= R then fr:Toggle(R) end
    if fh:IsToggled() ~= HZ then fh:Toggle(HZ) end
    s.lastL, s.lastR, s.lastH = L, R, HZ
end

function turnSignals.readToggles(fl, fr, fh, now)
    local s = turnSignals
    local L, R, HZ = fl:IsToggled(), fr:IsToggled(), fh:IsToggled()
    local mode
    if HZ and not s.lastH then mode = "hazard"
    elseif L and not s.lastL then mode = "left"
    elseif R and not s.lastR then mode = "right"
    elseif HZ then mode = "hazard"
    elseif L then mode = "left"
    elseif R then mode = "right"
    else mode = "none" end
    if mode ~= s.mode then
        if mode ~= "none" then s.usedManual = true end
        if s.autoSide and mode == "none" then s.autoVeto = s.autoSide end
        turnSignals.setMode(mode, now)
        s.autoSide = nil
    end
    turnSignals.syncToggles(fl, fr, fh)
end

function turnSignals.pollRoute()
    local s = turnSignals
    if not Natives.InvokeBool(s.H_WAYPOINT_ACTIVE) then return nil, 0.0, true end
    local blip = Natives.InvokeInt(s.H_FIRST_BLIP, s.BLIP_WAYPOINT)
    if not blip or blip == 0 then return nil, 0.0, true end
    local c = V3.New(Natives.InvokeV3(s.H_BLIP_COORD, blip))
    if not c then return nil, 0.0, true end
    Memory.WriteInt(s.buf, s.DIR_UNKNOWN)
    Memory.WriteFloat(s.buf + 16, 0.0)
    Natives.InvokeVoid(s.H_GEN_DIRECTIONS, c.x, c.y, c.z, 0, s.buf, s.buf + 8, s.buf + 16)
    local dir = Memory.ReadInt(s.buf) or s.DIR_UNKNOWN
    local dist = Memory.ReadFloat(s.buf + 16) or 0.0
    local nowMs = MISC.GET_GAME_TIMER()
    if dir ~= s.lastDir and nowMs >= s.dirLogAt then
        logf("[TurnSignals] route direction %s -> %d at %.0fm",
            tostring(s.lastDir), dir, dist)
        s.lastDir, s.dirLogAt = dir, nowMs + 1000
    end
    if dir == s.DIR_UNKNOWN or dir == s.DIR_WRONG_WAY then return nil, dist, false end
    if dir == s.DIR_LEFT then return "left", dist, true end
    if dir == s.DIR_RIGHT then return "right", dist, true end
    return nil, dist, true
end

function turnSignals.trackTurn(now)
    local s = turnSignals
    if s.mode ~= "left" and s.mode ~= "right" then return false end
    if s.veh == 0 or not s.armHeading then return false end
    if now < s.nextSampleAt then return false end
    local dt = (now - s.sampledAt) / 1000.0
    s.sampledAt, s.nextSampleAt = now, now + s.SAMPLE_MS
    if dt <= 0.0 then return false end

    local h = ENTITY.GET_ENTITY_HEADING(s.veh)
    local pos = ENTITY.GET_ENTITY_COORDS(s.veh, true)
    if s.lastPos then
        local dx, dy = pos.x - s.lastPos.x, pos.y - s.lastPos.y
        s.travelled = s.travelled + math.sqrt(dx * dx + dy * dy)
    end
    s.lastPos = pos
    local rate = math.abs(turnSignals.angDiff(h, s.lastHeading)) / dt
    s.lastHeading = h
    local swing = turnSignals.angDiff(h, s.armHeading)
    if s.mode == "right" then swing = -swing end

    s.swing = swing
    if swing >= s.TURN_START_DEG then s.turnBegun = true end
    if swing <= -s.COUNTER_DEG then return "counter-steered" end
    if not s.turnBegun then
        if s.travelled >= s.ABORT_METRES then return "never turned" end
        return nil
    end
    if rate < s.STEADY_RATE then
        s.steadyMs = s.steadyMs + math.floor(dt * 1000.0)
    else
        s.steadyMs = 0
    end
    if s.steadyMs >= s.STEADY_MS and swing >= s.TURN_DONE_DEG then return "turn complete" end
    return nil
end

function turnSignals.wasUsed()
    return turnSignals.usedManual == true
end

function turnSignals.onTick(f)
    if not f:IsToggled() then return end
    local s = turnSignals
    if ShouldUnload() or scriptUnloading then
        if not s.cleared then
            turnSignals.clear(s.veh)
            s.cleared = true
        end
        return
    end
    local fl = FeatureMgr.GetFeature(H.SIGNAL_LEFT)
    local fr = FeatureMgr.GetFeature(H.SIGNAL_RIGHT)
    local fh = FeatureMgr.GetFeature(H.SIGNAL_HAZARD)
    if not (fl and fr and fh) then return end
    local now = MISC.GET_GAME_TIMER()

    local ped = PLAYER.PLAYER_PED_ID()
    local cur = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    local driving = cur ~= 0 and VEHICLE.GET_PED_IN_VEHICLE_SEAT(cur, -1, false) == ped
    if driving and cur ~= s.veh then
        turnSignals.clear(s.veh)
        s.veh = cur
        s.appliedMode, s.appliedVeh = nil, 0
        turnSignals.setMode("none", now)
    elseif s.veh ~= 0 and not ENTITY.DOES_ENTITY_EXIST(s.veh) then
        s.veh = 0
        s.appliedMode, s.appliedVeh = nil, 0
        turnSignals.setMode("none", now)
    end

    turnSignals.readToggles(fl, fr, fh, now)

    local auto = FeatureMgr.GetFeature(H.SIGNAL_AUTO)
    if auto and auto:IsToggled() and driving and s.mode ~= "hazard" then
        if now >= s.nextPollAt then
            s.nextPollAt = now + s.POLL_MS
            local side, dist, known = turnSignals.pollRoute()
            if not known then
                s.gpsMiss = 0
            else
                if s.autoSide then
                    if side == s.autoSide then
                        s.gpsMiss = 0
                    elseif side then
                        logf("[TurnSignals] auto %s -> %s: route changed sides at %.0fm",
                            s.autoSide, side, dist)
                        turnSignals.setMode(side, now)
                        s.autoSide = side
                        turnSignals.syncToggles(fl, fr, fh)
                        s.gpsMiss = 0
                    else
                        s.gpsMiss = s.gpsMiss + 1
                        if s.gpsMiss >= 2 and s.travelled >= 15.0 then
                            logf("[TurnSignals] auto %s cancelled: junction passed after %.0fm",
                                s.autoSide, s.travelled)
                            turnSignals.setMode("none", now)
                            turnSignals.syncToggles(fl, fr, fh)
                        end
                    end
                end
                if s.autoVeto and side ~= s.autoVeto then s.autoVeto = nil end
                if side and side == s.armSide then s.armAgree = s.armAgree + 1
                elseif side then s.armSide, s.armAgree = side, 1
                else s.armSide, s.armAgree = nil, 0 end
                if side and s.armAgree >= 2 and not s.autoVeto and s.mode == "none" then
                    local speed = ENTITY.GET_ENTITY_SPEED(s.veh) or 0.0
                    local lead = math.min(s.LEAD_MAX, math.max(s.LEAD_MIN, speed * s.LEAD_SECONDS))
                    if dist > 0.0 and dist <= lead then
                        logf("[TurnSignals] auto %s: junction in %.0fm (lead %.0fm at %.0f km/h)",
                            side, dist, lead, speed * 3.6)
                        turnSignals.setMode(side, now)
                        s.autoSide = side
                        turnSignals.syncToggles(fl, fr, fh)
                    end
                end
            end
        end
    elseif s.autoSide then
        turnSignals.setMode("none", now)
        turnSignals.syncToggles(fl, fr, fh)
    end

    local why = turnSignals.trackTurn(now)
    if why then
        logf("[TurnSignals] %s cancelled: %s (%.0f deg over %.0fm)",
            s.mode, why, s.swing or 0.0, s.travelled)
        turnSignals.setMode("none", now)
        turnSignals.syncToggles(fl, fr, fh)
    end
    turnSignals.apply(now)
end

FeatureMgr.AddFeature(H.SIGNAL_LEFT, "Left Turn Signal", eFeatureType.Toggle,
    "Flashes the left indicators on the vehicle you are driving. Bind a hotkey to flick it on from behind the wheel. It cancels itself once you have finished the turn, and stays on the car after you get out. Only visible to you.")
    :SetSaveable(false)

FeatureMgr.AddFeature(H.SIGNAL_RIGHT, "Right Turn Signal", eFeatureType.Toggle,
    "Flashes the right indicators on the vehicle you are driving. Bind a hotkey to flick it on from behind the wheel. It cancels itself once you have finished the turn, and stays on the car after you get out. Only visible to you.")
    :SetSaveable(false)

FeatureMgr.AddFeature(H.SIGNAL_HAZARD, "Hazard Lights", eFeatureType.Toggle,
    "Flashes all four indicators together. Stays on until you turn it off and is never canceled for you. Needs the engine running to light up. Only visible to you.")
    :SetSaveable(false)

FeatureMgr.AddFeature(H.SIGNAL_AUTO, "Automatic Signals", eFeatureType.Toggle,
    "Signals your turns for you while a waypoint is set. Reads the GPS route ahead and switches the correct indicator on a few seconds before each junction, then cancels it once the turn is done. Hazards and a signal you set by hand both take priority.")
    :SetSaveable(false)

centralOnTick(FeatureMgr.AddFeature(turnSignals.runnerHash,
    "##TurnSignalsRunner", eFeatureType.Toggle, "", turnSignals.onTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
    :SetSearchable(false)
    :SetVisible(false)
FeatureMgr.GetFeature(turnSignals.runnerHash):Toggle(true)

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    turnSignals.mode = "none"
    turnSignals.autoSide = nil
end)




