scanDoctor.register("PMI", { probe = function()
    local t = patchFn and patchFn.proxMine
    if not t then return nil end
    local defs = IS_ENHANCED and t.ENHANCED_SITES or t.LEGACY_SITES
    local seen = {}
    for i = 1, #defs do
        local aob = defs[i].AOB
        if not seen[aob] then
            seen[aob] = true
            if not scanDoctor.scanOk(aob) then return false end
        end
    end
    return true
end })

scanDoctor.register("WPI", { probe = function()
    local t = patchFn and patchFn.wpInsideInterior
    if not t then return nil end
    local sites = IS_ENHANCED and t.ENHANCED_SITES or t.LEGACY_SITES
    if not sites or #sites == 0 then return nil end
    for _, s in ipairs(sites) do
        if not scanDoctor.scanOk(s.AOB) then return false end
    end
    return true
end })

