    if not IS_ENHANCED then
        for _, modrm in ipairs({ 0x78, 0x79, 0x7A, 0x7B, 0x7D, 0x7E, 0x7F }) do
            if scanDoctor.scanOk(("81 %02X 10 29 2A 82 E2 ? ? 38 05 ? ? ? ? B8"):format(modrm)) then
                return true
            end
        end
        return false
    end
    for _, modrm in ipairs({ 0x78, 0x79, 0x7A, 0x7B, 0x7D, 0x7E, 0x7F }) do
        if scanDoctor.scanOk(("81 %02X 10 29 2A 82 E2"):format(modrm)) then return true end
    end
    for _, modrm in ipairs({ 0xB8, 0xB9, 0xBA, 0xBB, 0xBD, 0xBE, 0xBF }) do
        if scanDoctor.scanOk(("81 %02X 10 00 00 00 29 2A 82 E2"):format(modrm)) then return true end
    end
    return false
end })

