H.REJOIN_SESSION = VIBE_FH("RejoinSession")

rejoin = {
    scapiRidHash = Utils.Joaat("SCAPIRID"),

    running         = false,
    cancelRequested = false,
    radioWasOn      = false,
    status          = "",
    statusColor     = { 180, 180, 180 },
    statusAt        = 0,

    STATUS_TTL    = 30000,

    DISARM_TIMEOUT = 3000,
    BAIL_TIMEOUT  = 20000,
    TRANS_TIMEOUT = 12000,
    LOAD_TIMEOUT  = 45000,
    RETRY_BACKOFF = 2500,
    MAX_TARGETS   = 3,
    POST_BAIL_SETTLE = 2000,
    PRESENCE_SETTLE  = 10000,

    NAT_IS_SESSION_ACTIVE = 0xD83C2B94E7508980,
    NAT_IS_IN_TRANSITION  = 0x68049AEFF83D8F0A,
    NAT_GET_HOST_PLAYER   = 0x8251FB94DC4FDFC8,
}

function rejoin.setStatus(msg, r, g, b)
    rejoin.status = msg
    rejoin.statusColor = { r or 180, g or 180, b or 180 }
    rejoin.statusAt = Time.GetEpocheMs()
    log("[Rejoin] " .. msg)
end

function rejoin.statusVisible()
    if rejoin.status == "" then return false end
    return rejoin.running or (Time.GetEpocheMs() - rejoin.statusAt) < rejoin.STATUS_TTL
end

function rejoin.resolveBuiltin(names)
    for _, nm in ipairs(names) do
        local f = FeatureMgr.GetFeatureByName(nm)
        if f then return f, nm end
    end
    return nil, nil
end

function rejoin.aborted()
    return rejoin.cancelRequested or ShouldUnload()
end

function rejoin.waitUntil(pred, timeoutMs, stepMs)
    local deadline = Time.GetEpocheMs() + timeoutMs
    while Time.GetEpocheMs() < deadline do
        if rejoin.aborted() then return false end
        if pred() then return true end
        Script.Yield(stepMs or 250)
    end
    return pred()
end

function rejoin.inSession()      return Natives.InvokeBool(rejoin.NAT_IS_SESSION_ACTIVE) end
function rejoin.inTransition()   return Natives.InvokeBool(rejoin.NAT_IS_IN_TRANSITION) end
function rejoin.targetPresent(rid) return Players.GetByRockstarId(rid) ~= nil end

function rejoin.anyPresent(targets)
    for _, t in ipairs(targets) do
        if rejoin.targetPresent(t.rid) then return t end
    end
    return nil
end

function rejoin.captureTargets()
    if not rejoin.inSession() then return nil, "not in an online session" end
    local localId = GTA.GetLocalPlayerId()
    local hostId  = Natives.InvokeInt(rejoin.NAT_GET_HOST_PLAYER)
    local wasHost = (hostId == localId)

    local out, seen = {}, {}
    local function add(pid)
        if pid == localId or #out >= rejoin.MAX_TARGETS then return end
        local p = Players.GetById(pid)
        if not p then return end
        local gi = p:GetGamerInfo()
        if not gi then return end
        local rid = gi.RockstarId
        if not rid or rid == 0 or seen[rid] then return end
        seen[rid] = true
        out[#out + 1] = { rid = rid, name = p:GetName() or ("RID " .. tostring(rid)) }
    end

    if not wasHost then add(hostId) end
    for pid = 0, 31 do add(pid) end

    if #out == 0 then return nil, "alone in this session - nothing to rejoin" end
    return out, wasHost
end

function rejoin.disarmLouderRadio()
    local feat = FeatureMgr.GetFeature(H.LOUDER_RADIO)
    if not (feat and feat:IsToggled()) then return false end
    rejoin.setStatus(T("Stowing Louder Radio speakers..."), 230, 210, 90)
    feat:Toggle(false)
    rejoin.waitUntil(function() return #louderRadio.buses == 0 end, rejoin.DISARM_TIMEOUT, 100)
    logf("[Rejoin] Louder Radio switched off before bail, %d bus(es) left",
        #louderRadio.buses)
    return true
end

function rejoin.bailToStory(bailFeat)
    if not rejoin.inSession() then return true end
    if not bailFeat then return false end
    if rejoin.disarmLouderRadio() then rejoin.radioWasOn = true end
    rejoin.setStatus(T("Bailing to story mode..."), 230, 210, 90)
    bailFeat:TriggerCallback()
    return rejoin.waitUntil(function() return not rejoin.inSession() end, rejoin.BAIL_TIMEOUT, 500)
end

function rejoin.flow(targets, maxAttempts, doFallback, joinFeat, bailFeat, startFeat)
    local function candidate(attempt)
        return targets[math.min(attempt, #targets)]
    end

    local function finishSuccess(known)
        local found = known
        if not found then
            rejoin.waitUntil(function()
                found = rejoin.anyPresent(targets)
                return found ~= nil
            end, rejoin.PRESENCE_SETTLE, 500)
        end
        if found then
            rejoin.setStatus(T("Rejoined %s's session."):format(found.name), 120, 220, 120)
        else
            rejoin.setStatus(T("Joined a session (no original players present)."), 190, 220, 120)
        end
        GUI.AddToast("VibeScript", rejoin.status, 5000)
    end

    if rejoin.inSession() then
        if not rejoin.bailToStory(bailFeat) then
            rejoin.setStatus(rejoin.aborted() and T("Rejoin canceled.") or
                T("Could not bail from the session - rejoin aborted."), 235, 90, 90)
            GUI.AddToast("VibeScript", rejoin.status, 6000)
            return
        end
        if not rejoin.aborted() then Script.Yield(rejoin.POST_BAIL_SETTLE) end
    end

    for attempt = 1, maxAttempts do
        if rejoin.aborted() then rejoin.setStatus(T("Rejoin canceled."), 235, 90, 90); return end

        if rejoin.inSession() then
            local found = rejoin.anyPresent(targets)
            if found then finishSuccess(found); return end
            rejoin.bailToStory(bailFeat)
        end

        local tgt = candidate(attempt)
        logf("[Rejoin] pre-join attempt %d: target=%s rid=%s inSession=%s inTransition=%s",
            attempt, tgt.name, tostring(tgt.rid),
            tostring(rejoin.inSession()), tostring(rejoin.inTransition()))

        rejoin.setStatus((T("Joining %s (attempt %d/%d)...")):format(tgt.name, attempt, maxAttempts), 230, 210, 90)
        FeatureMgr.SetFeatureInt(rejoin.scapiRidHash, tgt.rid)
        joinFeat:TriggerCallback()
        FeatureMgr.SetFeatureInt(rejoin.scapiRidHash, 0)

        local started = rejoin.waitUntil(function()
            return rejoin.inTransition() or rejoin.inSession()
        end, rejoin.TRANS_TIMEOUT, 250)

        if started then
            local joined = rejoin.waitUntil(function()
                return rejoin.inSession() and not rejoin.inTransition()
            end, rejoin.LOAD_TIMEOUT, 500)
            if joined then
                finishSuccess()
                return
            end
        end

        if rejoin.aborted() then rejoin.setStatus(T("Rejoin canceled."), 235, 90, 90); return end
        rejoin.setStatus((T("Attempt %d/%d failed%s")):format(attempt,  maxAttempts,
            attempt < maxAttempts and T(" - retrying...") or ""), 235, 90, 90)
        if attempt < maxAttempts then Script.Yield(rejoin.RETRY_BACKOFF) end
    end

    if doFallback and startFeat then
        rejoin.setStatus(T("Rejoin failed - starting a new session..."), 255, 170, 60)
        startFeat:TriggerCallback()
        GUI.AddToast("VibeScript",
            T("Rejoin failed after %d attempts. Starting a new session."):format(maxAttempts), 6000)
    else
        rejoin.setStatus((T("Rejoin failed after %d attempts (still in story mode).")):format(maxAttempts), 235, 90, 90)
        GUI.AddToast("VibeScript", rejoin.status, 6000)
    end
end

function rejoin.start()
    if rejoin.running then
        rejoin.cancelRequested = true
        rejoin.setStatus(T("Canceling rejoin..."), 255, 170, 60)
        GUI.AddToast("VibeScript", T("Rejoin cancel requested."), 3000)
        return
    end

    local targets, info = rejoin.captureTargets()
    if not targets then
        rejoin.setStatus(T("Can't rejoin: %s"):format((info or T("no target"))), 235, 90, 90)
        GUI.AddToast("VibeScript", rejoin.status, 4000)
        return
    end
    local wasHost = (info == true)

    local joinFeat, joinName = rejoin.resolveBuiltin({ "Join Rockstar Id" })
    if not joinFeat then
        rejoin.setStatus(T("Cherax 'Join Rockstar Id' feature not found - cannot join."), 235, 90, 90)
        GUI.AddToast("VibeScript", rejoin.status, 7000)
        return
    end
    if not FeatureMgr.GetFeature(rejoin.scapiRidHash) then
        rejoin.setStatus(T("Cherax SC-API Rockstar Id input (SCAPIRID) not found - cannot target."), 235, 90, 90)
        GUI.AddToast("VibeScript", rejoin.status, 7000)
        return
    end

    local bailFeat,  bailName  = rejoin.resolveBuiltin({ "Story Bail From Session", "Bail From Session" })
    local startFeat, startName = rejoin.resolveBuiltin({ "Start Session" })

    local maxAttempts = 2
    local doFallback  = true

    local names = {}
    for _, t in ipairs(targets) do names[#names + 1] = ("%s(%s)"):format(t.name, tostring(t.rid)) end
    logf("[Rejoin] wasHost=%s targets=[%s] attempts=%d join=%q bail=%q start=%q",
        tostring(wasHost), table.concat(names, ", "), maxAttempts,
        joinName or "?", bailName or "MISSING", startName or "MISSING")

    rejoin.running = true
    rejoin.cancelRequested = false
    rejoin.setStatus(T("Starting rejoin..."), 230, 210, 90)
    telemetryCountAction("RejoinSession")
    Script.QueueJob(function()
        rejoin.flow(targets, maxAttempts, doFallback, joinFeat, bailFeat, startFeat)
        rejoin.running = false
        rejoin.cancelRequested = false
        if rejoin.radioWasOn then
            rejoin.radioWasOn = false
            local feat = FeatureMgr.GetFeature(H.LOUDER_RADIO)
            if feat then feat:Toggle(true) end
            log("[Rejoin] Louder Radio switched back on")
        end
    end)
end

FeatureMgr.AddFeature(H.REJOIN_SESSION, "Rejoin Session", eFeatureType.Button,
    "Rejoin the same lobby through Cherax SC-API",
    function(_) rejoin.start() end)
    :SetSaveable(false)

voiceToasts = {
    H_IS_PLAYER_TALKING = 0x031E11F3D447647E,
    TOAST_MS = 3000,
    due      = {},
}

function voiceToasts.onTick(feat)
    if not feat:IsToggled() or scriptUnloading then
        if next(voiceToasts.due) then voiceToasts.due = {} end
        return
    end

    local me  = GTA.GetLocalPlayerId()
    local now = Time.GetEpocheMs()
    local due = voiceToasts.due

    for pid = 0, 31 do
        if pid ~= me and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid)
            and Natives.InvokeBool(voiceToasts.H_IS_PLAYER_TALKING, pid) then
            if (due[pid] or 0) <= now then
                due[pid] = now + voiceToasts.TOAST_MS
                GUI.AddToast(T("Voice Chat"),
                    T("%s is speaking"):format(Players.GetName(pid) or ("Player " .. pid)),
                    voiceToasts.TOAST_MS)
            end
        else
            due[pid] = nil
        end
    end
end

centralOnTick(FeatureMgr.AddFeature(H.VOICE_TOASTS, "Voice Chat Toasts",
    eFeatureType.Toggle,
    "Notifies you when someone is speaking in voice chat.",
    voiceToasts.onTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)

