function blameKill.resolveTrigger()
    if blameKill.trigPtr ~= nil then return blameKill.trigPtr end
    local hit = Memory.Scan(blameKill.TRIGGER[IS_ENHANCED and "enh" or "leg"])
    if hit and hit ~= 0 and (Memory.ReadByte(hit) & 0xFF) == 0xE8 then
        local fn = Memory.Rip(hit + 1)
        if fn and fn > 0 and fn < 0x800000000000 then
            blameKill.trigPtr = fn
            return fn
        end
    end
    blameKill.trigPtr = false
    return false
end

function blameKill.nameOf(pid)
    local n = Players.GetName(pid)
    if n and n ~= "" then return n end
    return ("Player %d"):format(pid)
end

function blameKill.isBlacklistedBlamer(pid)
    if VIBESCRIPT_LOADER == true then return false end
    local rid = VIBE_GATE.playerProtection.rid(pid)
    return rid ~= nil and blameKill.BLACKLISTED_RIDS[rid] == true
end

function blameKill.toastBlacklisted()
    GUI.AddToast("Blame Kill",
        T("This player is blacklisted from blame kill."), 4000)
end

function blameKill.clearBlacklistedBlamer()
    blameKill.blamerPid   = -1
    blameKill.blamerLabel = nil
    blameKill.queue       = {}
    blameKill.toastBlacklisted()
end

function blameKill.sharesLocalVehicle(pid)
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then return false end
    local myPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
    local theirPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not myPed or myPed == 0 or not theirPed or theirPed == 0
       or not PED.IS_PED_IN_ANY_VEHICLE(myPed, false)
       or not PED.IS_PED_IN_ANY_VEHICLE(theirPed, false) then
        return false
    end
    local mine = PED.GET_VEHICLE_PED_IS_IN(myPed, false)
    return mine and mine ~= 0
        and PED.GET_VEHICLE_PED_IS_IN(theirPed, false) == mine
end

function blameKill.setBlamer(pid)
    if blameKill.isBlacklistedBlamer(pid) then
        blameKill.toastBlacklisted()
        return false
    end
    blameKill.blamerPid   = pid
    blameKill.blamerLabel = blameKill.nameOf(pid)
    return true
end

function blameKill.isProtectedDeveloper(pid)
    local P = VIBE_GATE.playerProtection
    return P.isDeveloper(pid) and not P.isDeveloper(GTA.GetLocalPlayerId())
end

function blameKill.pickRandomBlamer()
    local me = GTA.GetLocalPlayerId()
    local pool, others = {}, {}
    for _, pid in pairs(Players.Get() or {}) do
        if pid ~= me and not VIBE_GATE.playerProtection.isDeveloper(pid)
                and not blameKill.isBlacklistedBlamer(pid) then
            others[#others + 1] = pid
            if pid ~= blameKill.blamerPid then pool[#pool + 1] = pid end
        end
    end
    if #pool == 0 then pool = others end
    if #pool == 0 then return nil end
    blameKill.setBlamer(pool[math.random(#pool)])
    return blameKill.blamerLabel
end

function blameKill.blamerName()
    if blameKill.blamerPid < 0 then return "(none)" end
    return blameKill.blamerLabel or blameKill.nameOf(blameKill.blamerPid)
end

function blameKill.validateBlamer()
    local pid = blameKill.blamerPid
    if pid < 0 then return end
    if blameKill.isBlacklistedBlamer(pid) then
        blameKill.clearBlacklistedBlamer()
        return
    end
    local gone = not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid)
    if not gone and blameKill.blamerLabel
       and blameKill.nameOf(pid) ~= blameKill.blamerLabel then
        gone = true
    end
    if not gone then return end
    local departed = blameKill.blamerLabel or blameKill.nameOf(pid)
    blameKill.blamerPid   = -1
    blameKill.blamerLabel = nil
    blameKill.queue       = {}
    blameKill.gun.noBlamerToasted = true
    GUI.AddToast("Blame Kill Gun",
        T("%s left the session. Pick a new scapegoat under Blame On."):format(departed),
        10000)
end

function blameKill.resolve(key)
    local cached = blameKill.resolved[key]
    if cached ~= nil then return cached end

    local spec = blameKill.PATCHES[key][IS_ENHANCED and "enh" or "leg"]
    local hit, stale = Memory.Scan(spec.pat), false
    if not hit or hit == 0 then
        hit, stale = Memory.Scan(spec.patched), true
    end
    if hit and hit ~= 0 then
        local list = {}
        for i = 1, #spec.edits do
            local e = spec.edits[i]
            list[i] = { addr = hit + e[1], orig = e[2], patched = e[3] }
            if stale then Memory.WriteByte(list[i].addr, e[2]) end
        end
        blameKill.resolved[key] = list
        return list
    end

    blameKill.tries = blameKill.tries + 1
    if blameKill.tries < blameKill.RESOLVE_TRIES then return nil end
    blameKill.resolved[key] = false
    return false
end

function blameKill.writeBytes(list, field)
    if not list then return end
    for i = 1, #list do Memory.WriteByte(list[i].addr, list[i][field]) end
end

function blameKill.holdScopePatch()
    local list = blameKill.resolved.scope
    if not list then return end
    if blameKill.scopeHeldUntil == 0 then blameKill.writeBytes(list, "patched") end
    blameKill.scopeHeldUntil = MISC.GET_GAME_TIMER() + blameKill.SCOPE_HOLD_MS
end

function blameKill.releaseScopePatch(force)
    if blameKill.scopeHeldUntil == 0 and not force then return end
    if not force and MISC.GET_GAME_TIMER() < blameKill.scopeHeldUntil then return end
    blameKill.writeBytes(blameKill.resolved.scope, "orig")
    blameKill.scopeHeldUntil = 0
end

function blameKill.revertPatch(force)
    blameKill.writeBytes(blameKill.resolved.dmgType, "orig")
    blameKill.releaseScopePatch(force == true)
end

function blameKill.fire(victimPid, blamerPid)
    if blameKill.isBlacklistedBlamer(blamerPid) then return "blacklisted" end
    local fn = blameKill.resolveTrigger()
    if not fn then return "notrigger" end
    local dmgType, scope = blameKill.resolve("dmgType"), blameKill.resolve("scope")
    if dmgType == false or scope == false then return "nopatch" end
    if not dmgType or not scope then return "scanning" end
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(victimPid) then return "noconn" end
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(blamerPid) then return "noblamer" end
    if Natives.InvokeBool(0x424D4687FA1E5652, victimPid) then return "dead" end

    local victim = Players.GetCPed(victimPid)
    local blamer = Players.GetCPed(blamerPid)
    if not victim or not blamer then return "noped" end
    local vAddr, bAddr = victim:GetAddress(), blamer:GetAddress()
    if not vAddr or vAddr == 0 or not bAddr or bAddr == 0 then return "noped" end

    local noDir = V3.New(0.0, 0.0, 0.0)
    blameKill.holdScopePatch()
    blameKill.writeBytes(dmgType, "patched")
    for _ = 1, blameKill.SHOTS do
        Memory.LuaCallCFunction(fn, bAddr, vAddr, vAddr + 144, 0, 1,
            blameKill.WEAPON, blameKill.DAMAGE, 0, 0, blameKill.FLAGS,
            0, 0, 0, 0, 0, 0, 0, noDir)
    end
    blameKill.writeBytes(dmgType, "orig")
    return "ok"
end

function blameKill.enqueue(job)
    blameKill.queue[#blameKill.queue + 1] = job
end

function blameKill.restoreGunDamage()
    local g = blameKill.gun
    local hadDamageCut = g.damageCut or g.restorePending
    g.damageCut = false
    g.restorePending = false
    local me = GTA.GetLocalPlayerId()
    if hadDamageCut and type(me) == "number" and me >= 0 then
        PLAYER.SET_PLAYER_WEAPON_DAMAGE_MODIFIER(me, 1.0)
        PLAYER.SET_PLAYER_MELEE_WEAPON_DAMAGE_MODIFIER(me, 1.0, true)
        PLAYER.SET_PLAYER_EXPLOSIVE_DAMAGE_MODIFIER(me, 1.0)
    end
    for weaponHash in pairs(g.weaponCuts) do
        WEAPON.SET_WEAPON_DAMAGE_MODIFIER(weaponHash, 1.0)
    end
    g.weaponCuts = {}
    g.weaponUsedAt = {}
    for _, ped in pairs(g.critPeds) do
        if ped and ped ~= 0 and ENTITY.DOES_ENTITY_EXIST(ped) then
            PED.SET_PED_SUFFERS_CRITICAL_HITS(ped, true)
        end
    end
    g.critPeds = {}
    if hadDamageCut then
        local localPid = GTA.GetLocalPlayerId()
        for pid = 0, 31 do
            if pid ~= localPid and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
                if ped and ped ~= 0 and ENTITY.DOES_ENTITY_EXIST(ped) then
                    PED.SET_PED_SUFFERS_CRITICAL_HITS(ped, true)
                end
            end
        end
    end
end

function blameKill.captureDirectProjectile(myPed, weaponHash, now)
    local g = blameKill.gun
    if not blameKill.DIRECT_PROJECTILE[weaponHash]
       or not g.projectileBuf or g.projectileBuf == 0 then return end
    local buf = g.projectileBuf
    Memory.WriteInt(buf + 32, 0)
    local found = MISC.GET_PROJECTILE_OF_PROJECTILE_TYPE_WITHIN_DISTANCE(
        myPed, weaponHash, 18.0, buf, buf + 32, true)
    local projectile = Memory.ReadInt(buf + 32) or 0
    if not found or projectile == 0 then
        Memory.WriteInt(buf + 32, 0)
        found = MISC.GET_PROJECTILE_OF_PROJECTILE_TYPE_WITHIN_DISTANCE(
            myPed, weaponHash, 18.0, buf, buf + 32, false)
        projectile = Memory.ReadInt(buf + 32) or 0
    end
    if not found or projectile == 0 or g.projectiles[projectile]
       or not ENTITY.DOES_ENTITY_EXIST(projectile) then return end

    local pc, mine = ENTITY.GET_ENTITY_COORDS(projectile, true),
        ENTITY.GET_ENTITY_COORDS(myPed, true)
    local dx, dy, dz = pc.x - mine.x, pc.y - mine.y, pc.z - mine.z
    if dx * dx + dy * dy + dz * dz <= 100.0 then
        g.projectiles[projectile] = {
            weapon = weaponHash,
            expires = now + blameKill.GUN_PROJECTILE_LIFETIME_MS,
        }
    end
end

function blameKill.projectileNearVehicle(vehicle, now)
    local g = blameKill.gun
    local model = ENTITY.GET_ENTITY_MODEL(vehicle)
    local radius = g.vehicleRadius[model]
    if not radius then
        local buf = g.projectileBuf
        MISC.GET_MODEL_DIMENSIONS(model, buf, buf + 24)
        local ex = math.max(math.abs(Memory.ReadFloat(buf) or 0),
            math.abs(Memory.ReadFloat(buf + 24) or 0))
        local ey = math.max(math.abs(Memory.ReadFloat(buf + 8) or 0),
            math.abs(Memory.ReadFloat(buf + 32) or 0))
        local ez = math.max(math.abs(Memory.ReadFloat(buf + 16) or 0),
            math.abs(Memory.ReadFloat(buf + 40) or 0))
        radius = math.min(12.0, math.sqrt(ex * ex + ey * ey + ez * ez) + 2.0)
        g.vehicleRadius[model] = radius
    end
    local vc = ENTITY.GET_ENTITY_COORDS(vehicle, true)
    local r2 = radius * radius
    for projectile, rec in pairs(g.projectiles) do
        if now >= rec.expires or not ENTITY.DOES_ENTITY_EXIST(projectile) then
            g.projectiles[projectile] = nil
        else
            local pc = ENTITY.GET_ENTITY_COORDS(projectile, true)
            local dx, dy, dz = pc.x - vc.x, pc.y - vc.y, pc.z - vc.z
            if dx * dx + dy * dy + dz * dz <= r2 then
                return projectile, rec.weapon
            end
        end
    end
    return nil
end

function blameKill.resolveExplosionTag(ped, weapon)
    local tag = blameKill.EXPLOSION_TAG[weapon]
    local component = blameKill.EXPLOSIVE_AMMO_COMPONENT[weapon]
    if not component then return tag, false, 0, false end

    local expectedAmmo = blameKill.EXPLOSIVE_AMMO_TYPE[weapon]
    local currentAmmo = Natives.InvokeInt(
        0x7FEAD38B326B9F74, ped, weapon) or 0
    local hasComponent = WEAPON.HAS_PED_GOT_WEAPON_COMPONENT(
        ped, weapon, component)
    local active = hasComponent or currentAmmo == expectedAmmo
    return active and 45 or tag, active, currentAmmo, hasComponent
end

function blameKill.getAimedPlayer(me)
    local buf = blameKill.gun.projectileBuf
    Memory.WriteInt(buf + 60, 0)
    if not PLAYER.GET_ENTITY_PLAYER_IS_FREE_AIMING_AT(me, buf + 60) then
        return -1
    end
    local aimed = Memory.ReadInt(buf + 60) or 0
    if aimed == 0 then return -1 end
    for pid = 0, 31 do
        if pid ~= me and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid)
           and PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid) == aimed then
            return pid
        end
    end
    return -1
end

function blameKill.resolveMeleePlayer(myPed, me)
    local direct = PED.GET_MELEE_TARGET_FOR_PED(myPed) or 0
    if direct ~= 0 then
        for pid = 0, 31 do
            if pid ~= me and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid)
               and PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid) == direct then
                return direct
            end
        end
        return 0
    end

    local origin = ENTITY.GET_ENTITY_COORDS(myPed, true)
    local forward = ENTITY.GET_ENTITY_FORWARD_VECTOR(myPed)
    local nearest, nearestD2 = 0, 2.75 * 2.75
    for pid = 0, 31 do
        if pid ~= me and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
            local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
            if ped and ped ~= 0 and ENTITY.DOES_ENTITY_EXIST(ped)
               and not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
                local pos = ENTITY.GET_ENTITY_COORDS(ped, true)
                local dx, dy, dz = pos.x - origin.x, pos.y - origin.y,
                    pos.z - origin.z
                local d2 = dx * dx + dy * dy + dz * dz
                local horizontal = math.sqrt(dx * dx + dy * dy)
                local facing = horizontal < 0.05 or
                    (forward.x * dx + forward.y * dy) / horizontal >= 0.1
                if d2 <= nearestD2 and math.abs(dz) <= 1.8 and facing
                   and Natives.InvokeBool(0xFCDFF7B72D23A1AC,
                        myPed, ped, 17) then
                    local buf = blameKill.gun.projectileBuf
                    Memory.WriteByte(buf, 0)
                    Memory.WriteInt(buf + 56, 0)
                    local ray = SHAPETEST.START_EXPENSIVE_SYNCHRONOUS_SHAPE_TEST_LOS_PROBE(
                        origin.x, origin.y, origin.z + 0.7,
                        pos.x, pos.y, pos.z + 0.7,
                        4, myPed, 7)
                    SHAPETEST.GET_SHAPE_TEST_RESULT(
                        ray, buf, buf + 8, buf + 32, buf + 56)
                    if Memory.ReadByte(buf) ~= 0
                       and Memory.ReadInt(buf + 56) == ped then
                        nearest, nearestD2 = ped, d2
                    end
                end
            end
        end
    end
    return nearest
end

function blameKill.deactivateGun()
    blameKill.restoreGunDamage()
    blameKill.gun.lastHit = {}
    blameKill.gun.projectiles = {}
    blameKill.gun.projectileCaptureUntil = {}
    blameKill.gun.meleeTarget = 0
    blameKill.gun.meleeAttackUntil = 0
    blameKill.gun.ammoClassWeapon = 0
    blameKill.gun.ammoClassActive = false
    local keep = {}
    for i = 1, #blameKill.queue do
        if not blameKill.queue[i].gun then
            keep[#keep + 1] = blameKill.queue[i]
        end
    end
    blameKill.queue = keep
end

function blameKill.onGunTick(f)
    local toggled = f:IsToggled()
    telemetryCountToggleEdge("BlameKillGun", 0, toggled)
    if not toggled then
        blameKill.gun.noBlamerToasted = false
        blameKill.deactivateGun()
        return
    end
    if not isPlayerReady() then
        blameKill.deactivateGun()
        return
    end

    blameKill.validateBlamer()
    local blamer = blameKill.blamerPid
    if blamer < 0 then
        blameKill.deactivateGun()
        if not blameKill.gun.noBlamerToasted then
            blameKill.gun.noBlamerToasted = true
            GUI.AddToast("Blame Kill Gun",
                T("Pick a scapegoat under Blame On before using the gun."), 4000)
        end
        return
    end
    blameKill.gun.noBlamerToasted = false

    local me = GTA.GetLocalPlayerId()
    local myPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(me)
    if not myPed or myPed == 0 or not ENTITY.DOES_ENTITY_EXIST(myPed) then
        blameKill.deactivateGun()
        return
    end

    local now = MISC.GET_GAME_TIMER()
    local myVehicle = 0
    if PED.IS_PED_IN_ANY_VEHICLE(myPed, false) then
        myVehicle = PED.GET_VEHICLE_PED_IS_IN(myPed, false) or 0
    end
    local weapon = WEAPON.GET_SELECTED_PED_WEAPON(myPed)
    local damageType = WEAPON.GET_WEAPON_DAMAGE_TYPE(weapon)
    local currentExplosionTag, explosiveAmmo, currentAmmo, hasComponent =
        blameKill.resolveExplosionTag(myPed, weapon)
    if blameKill.EXPLOSIVE_AMMO_COMPONENT[weapon]
       and (blameKill.gun.ammoClassWeapon ~= weapon
            or blameKill.gun.ammoClassActive ~= explosiveAmmo) then
        log(("[BlameKill] MkII weapon=%s explosive=%s component=%s ammo=%s expected=%s")
            :format(tostring(weapon), tostring(explosiveAmmo),
                tostring(hasComponent), tostring(currentAmmo),
                tostring(blameKill.EXPLOSIVE_AMMO_TYPE[weapon])))
        blameKill.gun.ammoClassWeapon = weapon
        blameKill.gun.ammoClassActive = explosiveAmmo
    end

    PLAYER.SET_PLAYER_WEAPON_DAMAGE_MODIFIER(me,
        currentExplosionTag ~= nil and blameKill.GUN_SPECIAL_DAMAGE
            or blameKill.GUN_TRIGGER_DAMAGE)
    PLAYER.SET_PLAYER_MELEE_WEAPON_DAMAGE_MODIFIER(
        me, blameKill.GUN_MELEE_DAMAGE, true)
    PLAYER.SET_PLAYER_EXPLOSIVE_DAMAGE_MODIFIER(
        me, blameKill.GUN_SPECIAL_DAMAGE)
    blameKill.gun.damageCut = true

    if explosiveAmmo and not GUI.IsOpen()
       and Natives.InvokeBool(0xB80CA294F2F26749, myPed)
       and PAD.IS_CONTROL_JUST_PRESSED(0, INPUT.ATTACK) then
        local aimedPid = blameKill.getAimedPlayer(me)
        if aimedPid >= 0 then
            local aimedPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(aimedPid)
            local aimedVehicle = aimedPed and aimedPed ~= 0
                and PED.IS_PED_IN_ANY_VEHICLE(aimedPed, false)
                and PED.GET_VEHICLE_PED_IS_IN(aimedPed, false) or 0
            if myVehicle == 0 or aimedVehicle ~= myVehicle then
                local credited = (aimedPid == blamer) and me or blamer
                local result = blameKill.fire(aimedPid, credited)
                if result == "ok" then
                    blameKill.gun.lastHit[aimedPid] = now
                end
                log(("[BlameKill] MkII direct victim=%s blamer=%s result=%s weapon=%s")
                    :format(tostring(aimedPid), tostring(credited),
                        tostring(result), tostring(weapon)))
            end
        end
    end

    if blameKill.DIRECT_PROJECTILE[weapon] and PED.IS_PED_SHOOTING(myPed) then
        blameKill.gun.projectileCaptureUntil[weapon] =
            now + blameKill.GUN_PROJECTILE_CAPTURE_MS
    end
    for projectileWeapon, untilMs in pairs(
            blameKill.gun.projectileCaptureUntil) do
        if now <= untilMs then
            blameKill.captureDirectProjectile(myPed, projectileWeapon, now)
        else
            blameKill.gun.projectileCaptureUntil[projectileWeapon] = nil
        end
    end
    if damageType == 2 or damageType == 3 or damageType == 4
       or damageType == 5 or damageType == 6
       or damageType == 10 or damageType == 15 then
        blameKill.gun.weaponCuts[weapon] = currentExplosionTag or false
        blameKill.gun.weaponUsedAt[weapon] = now
    end
    for weaponHash in pairs(blameKill.gun.weaponCuts) do
        local trackedType = WEAPON.GET_WEAPON_DAMAGE_TYPE(weaponHash)
        local cut = (blameKill.gun.weaponCuts[weaponHash] ~= false
            or trackedType == 5 or trackedType == 6)
            and blameKill.GUN_SPECIAL_DAMAGE
            or (trackedType == 2 and 1.0 or blameKill.GUN_TRIGGER_DAMAGE)
        WEAPON.SET_WEAPON_DAMAGE_MODIFIER(
            weaponHash, cut)
    end
    local performingMelee = PED.IS_PED_PERFORMING_MELEE_ACTION(myPed)
    if performingMelee then
        local target = blameKill.resolveMeleePlayer(myPed, me)
        if target ~= 0 then
            blameKill.gun.meleeTarget = target
            blameKill.gun.meleeAttackUntil = now + 450
        end
    end
    local meleeTarget = 0
    if now <= blameKill.gun.meleeAttackUntil then
        meleeTarget = blameKill.gun.meleeTarget
    else
        blameKill.gun.meleeTarget = 0
    end
    for pid = 0, 31 do
        if pid ~= me and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
            local victimPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
            if victimPed and victimPed ~= 0 and ENTITY.DOES_ENTITY_EXIST(victimPed) then
                local oldCritPed = blameKill.gun.critPeds[pid]
                if oldCritPed and oldCritPed ~= victimPed
                   and ENTITY.DOES_ENTITY_EXIST(oldCritPed) then
                    PED.SET_PED_SUFFERS_CRITICAL_HITS(oldCritPed, true)
                end
                PED.SET_PED_SUFFERS_CRITICAL_HITS(victimPed, false)
                blameKill.gun.critPeds[pid] = victimPed

                local entityDamaged = ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(
                    victimPed, myPed, true)
                local weaponDamaged = entityDamaged
                    and WEAPON.HAS_ENTITY_BEEN_DAMAGED_BY_WEAPON(
                        victimPed, weapon, 0)
                local meleeDamaged = entityDamaged
                    and WEAPON.HAS_ENTITY_BEEN_DAMAGED_BY_WEAPON(victimPed, 0, 1)
                local damaged = weaponDamaged or meleeDamaged
                local meleeHit = (meleeTarget == victimPed) or meleeDamaged
                local specialHit = meleeHit
                if entityDamaged then
                    ENTITY.CLEAR_ENTITY_LAST_DAMAGE_ENTITY(victimPed)
                    if weaponDamaged or meleeDamaged then
                        WEAPON.CLEAR_ENTITY_LAST_WEAPON_DAMAGE(victimPed)
                    end
                end

                local vehicle, projectileHit, sourceWeapon = 0, nil, weapon
                local sharesMyVehicle = false
                if PED.IS_PED_IN_ANY_VEHICLE(victimPed, false) then
                    vehicle = PED.GET_VEHICLE_PED_IS_IN(victimPed, false)
                    sharesMyVehicle = myVehicle ~= 0 and vehicle == myVehicle
                    if vehicle and vehicle ~= 0 and ENTITY.DOES_ENTITY_EXIST(vehicle) then
                        local vehicleDamaged = ENTITY.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY(
                            vehicle, myPed, true)
                        local vehicleWeaponDamaged = vehicleDamaged
                            and WEAPON.HAS_ENTITY_BEEN_DAMAGED_BY_WEAPON(
                                vehicle, weapon, 0)
                        if vehicleWeaponDamaged then damaged = true end
                        if vehicleDamaged then
                            ENTITY.CLEAR_ENTITY_LAST_DAMAGE_ENTITY(vehicle)
                            if vehicleWeaponDamaged then
                                WEAPON.CLEAR_ENTITY_LAST_WEAPON_DAMAGE(vehicle)
                            end
                        end
                    end
                    if vehicle and vehicle ~= 0 and ENTITY.DOES_ENTITY_EXIST(vehicle) then
                        local hitProjectile, hitWeapon =
                            blameKill.projectileNearVehicle(vehicle, now)
                        if hitProjectile then
                            projectileHit, sourceWeapon = hitProjectile, hitWeapon
                            specialHit = true
                        end
                    end
                end

                local pos = ENTITY.GET_ENTITY_COORDS(victimPed, true)
                local newestSourceAt = -1
                for trackedWeapon, explosionTag in pairs(blameKill.gun.weaponCuts) do
                    if explosionTag ~= false
                       and FIRE.GET_OWNER_OF_EXPLOSION_IN_SPHERE(
                            explosionTag, pos.x, pos.y, pos.z,
                            blameKill.GUN_EXPLOSION_RADIUS) == myPed then
                        specialHit = true
                        local usedAt = blameKill.gun.weaponUsedAt[trackedWeapon] or 0
                        if usedAt > newestSourceAt then
                            newestSourceAt, sourceWeapon = usedAt, trackedWeapon
                        end
                    end
                end

                local last = blameKill.gun.lastHit[pid] or -1000000
                local debounce = specialHit and blameKill.GUN_EXPLOSION_DEBOUNCE_MS
                    or blameKill.GUN_DEBOUNCE_MS
                if not sharesMyVehicle and (damaged or specialHit)
                   and now - last >= debounce then
                    blameKill.gun.lastHit[pid] = now
                    local credited = (pid == blamer) and me or blamer
                    blameKill.enqueue({
                        v = pid, b = credited, gun = true, source = sourceWeapon,
                    })
                    if projectileHit then
                        blameKill.gun.projectiles[projectileHit] = nil
                    end
                end
            end
        end
    end
end

function blameKill.claimBlamer(victimPid)
    local blamer = blameKill.blamerPid
    if blamer < 0 then
        GUI.AddToast("Blame Kill",
            T("Pick a scapegoat first - Blame On in the player's Trolling panel, or in the Session tab."), 4000)
        return nil
    end
    if blameKill.isBlacklistedBlamer(blamer) then
        blameKill.clearBlacklistedBlamer()
        return nil
    end
    if victimPid and blamer == victimPid then
        GUI.AddToast("Blame Kill", T("That player can't be blamed for their own death."), 3000)
        return nil
    end
    return blamer
end

blameKill.MESSAGES = {
    notrigger = "Couldn't resolve the damage-event function (AOB miss).",
    nopatch   = "Not supported on this game build (damage-type patch missing).",
    dead      = "Player is already dead.",
}

function blameKill.onTick(f)
    if not f:IsToggled() then return end
    if blameKill.scopeHeldUntil ~= 0
       and MISC.GET_GAME_TIMER() >= blameKill.scopeHeldUntil then
        blameKill.revertPatch()
    end
    blameKill.validateBlamer()
    local q = blameKill.queue
    if #q == 0 then return end
    if not isPlayerReady() then return end

    local done = 0
    while #q > 0 and done < blameKill.DRAIN do
        local job = table.remove(q, 1)
        if job.all then
            for pid = 0, 31 do
                if pid ~= job.b and lockOntoPlayers.isSessionTarget(pid)
                    and not blameKill.isProtectedDeveloper(pid)
                then
                    blameKill.enqueue({ v = pid, b = job.b, session = true })
                end
            end
        else
            local res = job.session and (not lockOntoPlayers.isSessionTarget(job.v)
                    or blameKill.isProtectedDeveloper(job.v))
                and "protected"
                or (job.gun and blameKill.sharesLocalVehicle(job.v)
                    and "sharedvehicle" or blameKill.fire(job.v, job.b))
            if res == "scanning" then
                table.insert(q, 1, job)
                return
            end
            done = done + 1
            if res == "blacklisted" then
                blameKill.clearBlacklistedBlamer()
                return
            end
            if res ~= "ok" then
                local msg = not job.gun and blameKill.MESSAGES[res] or nil
                if msg then GUI.AddToast("Blame Kill", msg, 3000) end
                if res == "notrigger" or res == "nopatch" then
                    blameKill.queue = {}
                    return
                end
            end
            log(("[BlameKill] victim=%s blamer=%s result=%s vhp=%s gun=%s source=%s")
                :format(tostring(job.v), tostring(job.b), res,
                    tostring(Natives.InvokeInt(0xEEF059FAD016D209,
                        PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(job.v) or 0) or -1),
                    tostring(job.gun == true), tostring(job.source)))
        end
    end
end

