    :SetNoCallbackOnPress(true)
    :SetSaveable(false)

centralOnTick(FeatureMgr.AddFeature(H.BLAME_RUNNER, "##BlameKillRunner",
    eFeatureType.Toggle, "", blameKill.onTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
FeatureMgr.GetFeature(H.BLAME_RUNNER):Toggle()

function blameKill.onUnload()
    blameKill.restoreGunDamage()
    if blameKill.gun.projectileBuf and blameKill.gun.projectileBuf ~= 0 then
        Memory.Free(blameKill.gun.projectileBuf)
        blameKill.gun.projectileBuf = 0
    end
    blameKill.revertPatch(true)
end
EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, blameKill.onUnload)

scanDoctor.register("BK-TRIG", { sig = function()
    return blameKill.TRIGGER[IS_ENHANCED and "enh" or "leg"] end })
scanDoctor.register("BK-DMG", { sig = function()
    return blameKill.PATCHES.dmgType[IS_ENHANCED and "enh" or "leg"].pat end })
scanDoctor.register("BK-SCOPE", { sig = function()
    return blameKill.PATCHES.scope[IS_ENHANCED and "enh" or "leg"].pat end })

