            { "Takedown Rear Dog", "ACT_takedown_rear_dog", "Takedown", kind="AT_FROM_ON_FOOT AT_MELEE", weapons="RWT_ANY", clips="creatures@rottweiler@melee@streamed_core@ / takedown_from_back", results="AR_takedown_rear_dog", effects="DAR_stealth_kill" },
            { "Takedown Rear Dog Retriever", "ACT_takedown_rear_dog_retriever", "Takedown", kind="AT_FROM_ON_FOOT AT_MELEE", weapons="RWT_ANY", clips="creatures@retriever@melee@streamed_core@ / takedown_from_back", results="AR_takedown_rear_dog_retriever", effects="DAR_stealth_kill" },
            { "Takedown Rear Knife A", "ACT_takedown_rear_knife_a", "Takedown", kind="AT_FROM_ON_FOOT AT_MELEE", weapons="RWT_KNIFE", clips="melee@knife@streamed_core / plyr_knife_rear_takedown", results="AR_takedown_rear_knife", effects="DAR_stealth_kill" },
            { "Takedown Rear Knife B", "ACT_takedown_rear_knife_b", "Takedown", kind="AT_FROM_ON_FOOT AT_MELEE", weapons="RWT_KNIFE", clips="melee@knife@streamed_variations / plyr_knife_rear_takedown_variation_a", results="AR_takedown_rear_knife_b", effects="DAR_stealth_kill" },
            { "Takedown Rear Knife C", "ACT_takedown_rear_knife_c", "Takedown", kind="AT_FROM_ON_FOOT AT_MELEE", weapons="RWT_KNIFE", clips="melee@knife@streamed_variations / plyr_knife_rear_takedown_variation_b", results="AR_takedown_rear_knife_c", effects="DAR_stealth_kill" },
            { "Takedown Rear Psycho", "ACT_takedown_rear_psycho", "Psycho", kind="AT_FROM_ON_FOOT AT_MELEE", weapons="RWT_MELEE_FIST RWT_UNARMED", clips="melee@unarmed@streamed_core_psycho / plyr_psycho_rear_takedown", results="AR_takedown_rear_psycho", effects="DAR_stealth_kill" },
            { "Takedown Rear Psycho B", "ACT_takedown_rear_psycho_b", "Psycho", kind="AT_FROM_ON_FOOT AT_MELEE", weapons="RWT_MELEE_FIST RWT_UNARMED", clips="melee@unarmed@streamed_core_psycho / plyr_psycho_rear_takedown_b", results="AR_takedown_rear_psycho_b", effects="DAR_stealth_kill" },
            { "Tiger Shark Attack", "ACT_tiger_shark_attack", "Animal", kind="AT_MELEE AT_FROM_ON_FOOT", weapons="RWT_ANY", clips="creatures@shark@melee@streamed_core@ / attack", results="AR_tiger_shark_attack", effects="DAR_shark_bite" },
            { "Walking No Target", "ACT_walking_no_target", "Attack", kind="AT_FROM_ON_FOOT", weapons="RWT_HATCHET RWT_KNIFE RWT_MACHETE RWT_MELEE_FIST RWT_ONE_HANDED_CLUB_NO_HATCHET RWT_TWO_HANDED_CLUB RWT_UNARMED", clips="anim@melee@machete@streamed_core / plyr_walking_attack_a; melee@knife@streamed_core / plyr_walking_attack_a; melee@large_wpn@streamed_core / plyr_walking_attack; melee@small_wpn@streamed_core / plyr_walking_attack_a; melee@unarmed@streamed_core / walking_punch_no_target", results="AR_walking_no_target AR_walking_no_target_bat AR_walking_no_target_knife AR_walking_no_target_machete AR_walking_no_target_small_wpn", effects="DAR_bat DAR_heavy_cardinal DAR_knife DAR_small_wpn" },
            { "Walking Target Ai", "ACT_walking_target_AI", "Attack", kind="AT_FROM_ON_FOOT AT_MELEE", weapons="RWT_HATCHET RWT_KNIFE RWT_MACHETE RWT_MELEE_FIST RWT_ONE_HANDED_CLUB_NO_HATCHET RWT_TWO_HANDED_CLUB RWT_UNARMED", clips="anim@melee@machete@streamed_core / plyr_walking_attack_a; melee@knife@streamed_core / plyr_walking_attack_a; melee@large_wpn@streamed_core / plyr_walking_attack; melee@small_wpn@streamed_core / plyr_walking_attack_a; melee@unarmed@streamed_core / walking_punch", results="AR_walking AR_walking_bat AR_walking_knife AR_walking_machete AR_walking_small_wpn", effects="DAR_bat DAR_heavy_cardinal DAR_knife DAR_small_wpn" },
            { "Walking Target Ai Zombie", "ACT_walking_target_AI_zombie", "Zombie", kind="AT_FROM_ON_FOOT AT_MELEE", weapons="RWT_HATCHET RWT_KNIFE RWT_MACHETE RWT_MELEE_FIST RWT_ONE_HANDED_CLUB_NO_HATCHET RWT_TWO_HANDED_CLUB RWT_UNARMED", clips="anim@melee@machete@streamed_core / plyr_walking_attack_a; clipset@anim@ingame@melee@unarmed@streamed_core_zombie / walking_punch; melee@knife@streamed_core / plyr_walking_attack_a; melee@large_wpn@streamed_core / plyr_walking_attack; melee@small_wpn@streamed_core / plyr_walking_attack_a", results="AR_walking_bat AR_walking_knife AR_walking_machete AR_walking_small_wpn AR_walking_zombie", effects="DAR_bat DAR_heavy_cardinal DAR_knife DAR_small_wpn" },
            { "Walking Target Player", "ACT_walking_target_player", "Attack", kind="AT_FROM_ON_FOOT", weapons="RWT_HATCHET RWT_KNIFE RWT_MACHETE RWT_MELEE_FIST RWT_ONE_HANDED_CLUB_NO_HATCHET RWT_TWO_HANDED_CLUB RWT_UNARMED", clips="anim@melee@machete@streamed_core / plyr_walking_attack_a; melee@knife@streamed_core / plyr_walking_attack_a; melee@large_wpn@streamed_core / plyr_walking_attack; melee@small_wpn@streamed_core / plyr_walking_attack_a; melee@unarmed@streamed_core / walking_punch", results="AR_walking AR_walking_bat AR_walking_knife AR_walking_machete AR_walking_small_wpn", effects="DAR_bat DAR_heavy_cardinal DAR_knife DAR_small_wpn" },
            { "Walking Target Player Zombie", "ACT_walking_target_player_zombie", "Zombie", kind="AT_FROM_ON_FOOT", weapons="RWT_HATCHET RWT_KNIFE RWT_MACHETE RWT_MELEE_FIST RWT_ONE_HANDED_CLUB_NO_HATCHET RWT_TWO_HANDED_CLUB RWT_UNARMED", clips="anim@melee@machete@streamed_core / plyr_walking_attack_a; clipset@anim@ingame@melee@unarmed@streamed_core_zombie / walking_punch; melee@knife@streamed_core / plyr_walking_attack_a; melee@large_wpn@streamed_core / plyr_walking_attack; melee@small_wpn@streamed_core / plyr_walking_attack_a", results="AR_walking_bat AR_walking_knife AR_walking_machete AR_walking_small_wpn AR_walking_zombie", effects="DAR_bat DAR_heavy_cardinal DAR_knife DAR_small_wpn" },
        },
        messages = {
            busy = "Wait a moment before forcing another action.",
            identity = "This player's identity is unavailable.",
            changed = "The selected player left or changed.",
            self_target = "This action only supports other players.",
            notready = "Wait until you are in an active session.",
            me_missing = "Your character is unavailable. Wait until you have spawned.",
            other_missing = "The other player must be streamed in.",
            me_dead = "You are dead. Wait until you have respawned.",
            other_dead = "The other player is dead. Wait until they have respawned.",
            other_vehicle = "The other player is in a vehicle. They must exit it first.",
            other_standing = "The other player is not standing. Wait until they are back on their feet.",
            noped = "The target must be streamed in.",
            notrigger = "Couldn't resolve the damage-event function.",
        },
    }
    forceActions = A
    VIBE_TR.reg("Force actions")
    for _, message in pairs(A.messages) do VIBE_TR.reg(message) end

    function A.identity(pid)
        local player = Players.GetById(pid)
        local info = player and player:GetGamerInfo()
        local rid = info and math.tointeger(info.RockstarId or 0)
        return rid and rid > 0 and rid or nil
    end

    function A.toast(result, blockers)
        if result == "blocked" then
            local messages = {}
            for _, reason in ipairs(blockers) do messages[#messages + 1] = T(A.messages[reason]) end
            GUI.AddToast(T("Force actions"), table.concat(messages, "\n"), 3000)
            return
        end
        if A.messages[result] then
            GUI.AddToast(T("Force actions"), T(A.messages[result]), 3000)
        end
    end

    function A.enqueue(pid)
        if scriptUnloading or A.stopped then return end
        if A.pending[pid] or Time.GetEpocheMs() < (A.nextSend[pid] or 0) then
            A.toast("busy"); return
        end
        local rid = A.identity(pid)
        if not rid then A.toast("identity"); return end
        local picker = FeatureMgr.GetFeature(H.FORCE_ACTION_PICK)
        local action = A.actions[(picker:GetListIndex() or 0) + 1] or A.actions[1]
        A.pending[pid] = { pid = pid, rid = rid, action = action }
        telemetryCountAction("ForceAction" .. action[3])
    end

    function A.countLoops()
        for pid = 0, 31 do
            local f = FeatureMgr.GetFeature(H.FORCE_ACTION_LOOP, pid)
            telemetryCountToggleEdge("ForceActionLoop", pid, f ~= nil and f:IsToggled())
        end
    end

    function A.stopLoop(pid)
        if not A.loops[pid] then return end
        A.loops[pid] = nil
        local f = FeatureMgr.GetFeature(H.FORCE_ACTION_LOOP, pid)
        if f then f:SetBoolValue(false) end
    end

    function A.toggleLoop(f)
        local pid = f:GetPlayerIndex()
        if not f:IsToggled() then A.loops[pid] = nil; return end
        if scriptUnloading or A.stopped then f:SetBoolValue(false); return end
        local rid = A.identity(pid)
        if not rid then f:SetBoolValue(false); A.toast("identity"); return end
        f:SetBoolValue(true)
        A.loops[pid] = { pid = pid, rid = rid }
    end

    function A.enqueueAll()
        if scriptUnloading or A.stopped then return end
        local picker = FeatureMgr.GetFeature(H.FORCE_ACTION_ALL_PICK)
        A.allRequest = A.actions[(picker:GetListIndex() or 0) + 1] or A.actions[1]
        telemetryCountAction("ForceActionAll")
    end

    function A.reset()
        A.pending, A.loops, A.nextSend = {}, {}, {}
        A.allPending, A.allRequest, A.allCursor = {}, nil, -1
        A.filter, A.allFilter = "", ""
        FeatureMgr.GetFeature(H.FORCE_ACTION_ALL_LOOP):SetBoolValue(false)
        FeatureMgr.GetFeature(H.FORCE_ACTION_ALL_PICK):SetListIndex(0)
    end

    function A.sessionJob(now)
        local looping = FeatureMgr.GetFeature(H.FORCE_ACTION_ALL_LOOP):IsToggled()
        if not looping and not A.allRequest and next(A.allPending) == nil then return end
        if not isPlayerReady() then return end
        if A.allRequest then
            local action = A.allRequest
            A.allRequest = nil
            for pid = 0, 31 do
                if lockOntoPlayers.isSessionTarget(pid) then
                    local rid = A.identity(pid)
                    if rid then A.allPending[pid] = { pid = pid, rid = rid, action = action, session = true } end
                end
            end
        end
        for offset = 1, 32 do
            local pid = (A.allCursor + offset) % 32
            if not lockOntoPlayers.isSessionTarget(pid) then
                A.allPending[pid] = nil
            elseif now >= (A.nextSend[pid] or 0) then
                local job = A.allPending[pid]
                if job then
                    A.allPending[pid] = nil
                elseif looping then
                    local rid = A.identity(pid)
                    local picker = FeatureMgr.GetFeature(H.FORCE_ACTION_ALL_PICK)
                    if rid then job = { pid = pid, rid = rid, session = true, looped = true,
                        action = A.actions[(picker:GetListIndex() or 0) + 1] or A.actions[1] } end
                end
                if job then A.allCursor = pid; return job end
            end
        end
    end

    function A.blocker(ped, who)
        if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then return who .. "_missing" end
        if Natives.InvokeBool(0x3317DEDB88C95038, ped, true) then return who .. "_dead" end
        if who == "me" then return end
        if who == "other" and PED.IS_PED_IN_ANY_VEHICLE(ped, true) then return who .. "_vehicle" end
        if Natives.InvokeBool(0x47E4E977581C5B55, ped)
            or Natives.InvokeBool(0xCEDABC5900A0BF97, ped)
            or Natives.InvokeBool(0xFB92A102F1C4DFA3, ped)
            or Natives.InvokeBool(0x60DFD0691A170B88, ped, false) then return who .. "_standing" end
    end

    function A.pointer(addr)
        return type(addr) == "number" and addr > 0x10000 and addr < 0x800000000000
    end

    A.HELD = {}
    for held, names in pairs({
        ["RWT_KNIFE"] = "WEAPON_KNIFE WEAPON_BOTTLE WEAPON_DAGGER WEAPON_SWITCHBLADE",
        ["RWT_ONE_HANDED_CLUB RWT_ONE_HANDED_CLUB_NO_HATCHET"] = "WEAPON_NIGHTSTICK WEAPON_HAMMER "
            .. "WEAPON_CROWBAR WEAPON_CANDYCANE WEAPON_FLASHLIGHT WEAPON_WRENCH WEAPON_STUNROD",
        ["RWT_ONE_HANDED_CLUB RWT_HATCHET"] = "WEAPON_HATCHET WEAPON_BATTLEAXE WEAPON_STONE_HATCHET",
        ["RWT_TWO_HANDED_CLUB"] = "WEAPON_BAT WEAPON_GOLFCLUB WEAPON_POOLCUE",
        ["RWT_MACHETE"] = "WEAPON_MACHETE",
        ["RWT_MELEE_FIST"] = "WEAPON_KNUCKLE",
        ["RWT_ONE_HANDED_GUN RWT_TWO_HANDED_GUN RWT_PISTOL"] = "GROUP_PISTOL GROUP_SMG GROUP_RIFLE "
            .. "GROUP_MG GROUP_SHOTGUN GROUP_SNIPER GROUP_HEAVY GROUP_STUNGUN GROUP_TRANQILIZER "
            .. "GROUP_DIGISCANNER GROUP_HACKINGDEVICE GROUP_METALDETECTOR",
        ["RWT_THROWN"] = "GROUP_THROWN",
        ["RWT_THROWN_SPECIAL"] = "GROUP_PETROLCAN GROUP_FIREEXTINGUISHER",
    }) do
        for name in names:gmatch("%S+") do A.HELD[Utils.Joaat(name) & 0xFFFFFFFF] = held end
    end

    function A.sampleView(now)
        if A.viewPid == nil or now - (A.viewAt or 0) > 500 then A.viewState = nil; return end
        local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(A.viewPid)
        if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then A.viewState = nil; return end
        local held
        if Natives.InvokeInt(0x3B390A939AF0B5FC, ped, 0) == 0 then
            held = "RWT_UNARMED"
        else
            local weapon = Natives.InvokeInt(0x0A6DB4965674D243, ped) & 0xFFFFFFFF
            held = A.HELD[weapon] or (weapon ~= 0
                and A.HELD[Natives.InvokeInt(0xC3287EE3050FB74C, weapon) & 0xFFFFFFFF])
                or nil
        end
        local swimming = Natives.InvokeBool(0x9DE327631295B4C2, ped)
        A.viewState = { pid = A.viewPid, held = held, swimming = swimming }
    end

    function A.unplayable(action, state)
        if action.swim ~= state.swimming then
            return state.swimming and T("Won't play while they are swimming.")
                or T("Won't play unless they are swimming.")
        end
        if not state.held or action.weaponSet.RWT_ANY then return end
        for held in state.held:gmatch("%S+") do
            if action.weaponSet[held] then return end
        end
        return state.held == "RWT_UNARMED" and T("Won't play while they are unarmed.")
            or T("Won't play with the weapon they are holding.")
    end

    function A.fire(job)
        if not isPlayerReady() then return "notready" end
        local me = GTA.GetLocalPlayerId()
        if job.pid == me then return "self_target" end
        if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(job.pid)
            or A.identity(job.pid) ~= job.rid then return "changed" end
        local myPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(me)
        local theirPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(job.pid)
        local blockers = {}
        local mine, theirs = A.blocker(myPed, "me"), A.blocker(theirPed, "other")
        if mine then blockers[#blockers + 1] = mine end
        if theirs then blockers[#blockers + 1] = theirs end
        if #blockers > 0 then return "blocked", blockers end
        local actor = Players.GetCPed(me)
        local target = Players.GetCPed(job.pid)
        local actorAddr = actor and actor:GetAddress()
        local targetAddr = target and target:GetAddress()
        if not A.pointer(actorAddr) or not A.pointer(targetAddr) then return "noped" end
        local fn = blameKill.resolveTrigger()
        if not fn then return "notrigger" end
        Memory.LuaCallCFunction(fn, actorAddr, targetAddr, targetAddr + 144, 0, 1,
            A.weapon, 0.0, 0, 0, A.flags, A.parentResult, 0, job.action.definition,
            0, 0, 0, 0, V3.New(0.0, 0.0, 0.0))
        return "ok"
    end

    function A.onTick(f)
        if scriptUnloading or A.stopped or ShouldUnload() then
            A.pending = {}; A.loops = {}; A.allPending = {}; A.allRequest = nil; return
        end
        if not f:IsToggled() then return end
        A.countLoops()
        local now = Time.GetEpocheMs()
        A.sampleView(now)
        local _, job = next(A.pending)
        for pid, loop in pairs(A.loops) do
            if not FeatureMgr.GetFeature(H.FORCE_ACTION_LOOP, pid):IsToggled() then
                A.loops[pid] = nil
            elseif not job and now >= (A.nextSend[pid] or 0) then
                local picker = FeatureMgr.GetFeature(H.FORCE_ACTION_PICK)
                job = { pid = pid, rid = loop.rid, looped = true,
                    action = A.actions[(picker:GetListIndex() or 0) + 1] or A.actions[1] }
            end
        end
        if not job then job = A.sessionJob(now) end
        if not job then return end
        if not job.session then A.pending[job.pid] = nil end
        A.nextSend[job.pid] = now + 1000
        local result, blockers = A.fire(job)
        if (result == "changed" or result == "self_target") and not job.session then
            A.stopLoop(job.pid)
        elseif result == "notrigger" then
            VIBE_LOG_ERROR("[ForceActions] " .. A.messages.notrigger)
            for pid in pairs(A.loops) do A.stopLoop(pid) end
            FeatureMgr.GetFeature(H.FORCE_ACTION_ALL_LOOP):SetBoolValue(false)
            A.allPending, A.allRequest = {}, nil
        end
        if not job.looped or result == "changed" or result == "self_target"
            or result == "notrigger" then
            if not job.session or result == "notrigger" then A.toast(result, blockers) end
        end
    end

    A.CATEGORIES = { "Attacks", "Takedowns", "Dodges", "Hit Reactions",
        "Taken Down", "Animals", "Zombie", "Psycho", "Swimming" }
    function A.category(action)
        local n = action[2]:lower()
        local function has(word) return n:find(word, 1, true) ~= nil end
        if action.clips:lower():find("creatures@", 1, true) then return "Animals" end
        if has("zombie") then return "Zombie" end
        if has("psycho") then return "Psycho" end
        if has("swim") then return "Swimming" end
        local hit = has("hitby") or has("recoil")
        if has("takedown") or has("stealth") then
            return hit and "Taken Down" or "Takedowns"
        end
        if hit then return "Hit Reactions" end
        if has("dodge") or has("counter") then return "Dodges" end
        return "Attacks"
    end

    local names, rank = {}, {}
    for i, category in ipairs(A.CATEGORIES) do rank[category] = i end
    for i, action in ipairs(A.actions) do
        names[i] = action[1]
        action.definition = Utils.Joaat(action[2]) & 0xFFFFFFFF
        action.category = A.category(action)
        action.swim = action.kind:find("AT_SWIMMING", 1, true) ~= nil
        action.weaponSet = {}
        for weapon in action.weapons:gmatch("%S+") do action.weaponSet[weapon] = true end
        action.find = table.concat({ action[1], action[2], action.category, action.kind,
            action.weapons, action.clips, action.results, action.effects }, " "):lower()
    end
    A.order = {}
    for i = 1, #A.actions do A.order[i] = i end
    table.sort(A.order, function(a, b)
        local ra, rb = rank[A.actions[a].category], rank[A.actions[b].category]
        if ra ~= rb then return ra < rb end
        return a < b
    end)
    A.groups = {}
    for _, category in ipairs(A.CATEGORIES) do A.groups[category] = {} end
    for _, i in ipairs(A.order) do
        local members = A.groups[A.actions[i].category]
        members[#members + 1] = i
    end
    H.FORCE_ACTION_PICK = VIBE_FH("ForceActionPick")
    H.FORCE_ACTION_FIRE = VIBE_FH("ForceActionFire")
    FeatureMgr.AddFeature(H.FORCE_ACTION_PICK, "Action", eFeatureType.Combo,
        "Choose the action to force on this player.")
        :SetList(TLIST(names)):SetListIndex(0):SetSaveable(false):SetVisible(false):SetSearchable(false)
    for _, hash in ipairs(FeatureMgr.AddPlayerFeature(H.FORCE_ACTION_FIRE, "Force action", eFeatureType.Button,
        "Makes this player perform the selected action. Both players must be standing and the target streamed in. Some actions depend on what the target is doing: unarmed players won't respond to armed actions, armed players won't respond to unarmed actions, and swimming actions only work on swimming players.",
        function(f) A.enqueue(f:GetPlayerIndex()) end)) do
        FeatureMgr.GetFeature(hash):SetSaveable(false)
    end
    H.FORCE_ACTION_LOOP = VIBE_FH("ForceActionLoop")
    for _, hash in ipairs(FeatureMgr.AddPlayerFeature(H.FORCE_ACTION_LOOP, "Loop", eFeatureType.Toggle,
        "Repeat the selected action on this player once per second.",
        A.toggleLoop)) do
        FeatureMgr.GetFeature(hash):SetSaveable(false)
    end
    H.FORCE_ACTION_ALL_PICK = VIBE_FH("ForceActionAllPick")
    H.FORCE_ACTION_ALL_FIRE = VIBE_FH("ForceActionAllFire")
    H.FORCE_ACTION_ALL_LOOP = VIBE_FH("ForceActionAllLoop")
    FeatureMgr.AddFeature(H.FORCE_ACTION_ALL_PICK, "Session action", eFeatureType.Combo,
        "Choose the action to force on eligible players in the session.")
        :SetList(TLIST(names)):SetListIndex(0):SetSaveable(true):SetVisible(false):SetSearchable(false)
    FeatureMgr.AddFeature(H.FORCE_ACTION_ALL_FIRE, "Force action on all", eFeatureType.Button,
        "Makes eligible players perform the selected action.",
        A.enqueueAll):SetSaveable(false)
    FeatureMgr.AddFeature(H.FORCE_ACTION_ALL_LOOP, "Loop all", eFeatureType.Toggle,
        "Repeat the selected action on eligible session players, at most once per player per second.")
        :SetSaveable(true)
    H.FORCE_ACTIONS_RUNNER = VIBE_FH("ForceActionsRunner")
    centralOnTick(FeatureMgr.AddFeature(H.FORCE_ACTIONS_RUNNER, "##ForceActionsRunner",
        eFeatureType.Toggle, "", A.onTick))
        :SetNoCallbackOnPress(true):SetSaveable(false):SetSearchable(false):SetVisible(false)
    FeatureMgr.GetFeature(H.FORCE_ACTIONS_RUNNER):Toggle(true)

    function A.matches(action, query)
        for word in tostring(query or ""):lower():gmatch("%S+") do
            if not action.find:find(word, 1, true) then return false end
        end
        return true
    end

    function A.filtered(query)
        local indices = {}
        for _, i in ipairs(A.order) do
            if A.matches(A.actions[i], query) then indices[#indices + 1] = i end
        end
        return indices
    end

    function A.render(playerId)
        local session = playerId == nil
        local filterKey = session and "allFilter" or "filter"
        local picker = FeatureMgr.GetFeature(session and H.FORCE_ACTION_ALL_PICK or H.FORCE_ACTION_PICK)
        local index = picker:GetListIndex() or 0
        local selected = A.actions[index + 1] or A.actions[1]
        local state
        if not session then
            A.viewPid, A.viewAt = playerId, Time.GetEpocheMs()
            state = A.viewState and A.viewState.pid == playerId and A.viewState or nil
        end
        local r, g, b, a = ImGui.GetStyleColorVec4(ImGuiCol.Text)
        ImGui.SetNextItemWidth(-1)
        A[filterKey] = ImGui.InputTextWithHint("##force_actions_search",
            T("Search"), A[filterKey]) or ""
        local chosen
        local function row(i)
            local action = A.actions[i]
            local label = T(action[1])
            local width = ImGui.GetContentRegionAvail()
            local why = state and A.unplayable(action, state)
            if why then ImGui.PushStyleColor(ImGuiCol.Text, r, g, b, a * 0.45) end
            if ImGui.Selectable(label .. "##" .. action[2], i - 1 == index)
                and i - 1 ~= index then
                chosen = i - 1
            end
            if why then
                ImGui.PopStyleColor(1)
                if ImGui.IsItemHovered() then ImGui.SetTooltip(label .. "\n" .. why) end
            else
                Widget.overflowTooltip(label, width)
            end
        end
        ImGui.BeginChild("##force_actions_list", -1, 130, true, 0)
        if A[filterKey]:match("%S") then
            local indices = A.filtered(A[filterKey])
            for _, i in ipairs(indices) do row(i) end
            if #indices == 0 then ImGui.TextDisabled(T("No matching actions")) end
        else
            for g, group in ipairs(A.CATEGORIES) do
                local members = A.groups[group]
                if selected.category == group then
                    ImGui.SetNextItemOpen(true, ImGuiCond.Once)
                end
                if ImGui.TreeNode("force_group_" .. g, T(group) .. (" (%d)"):format(#members)) then
                    for _, i in ipairs(members) do row(i) end
                    ImGui.TreePop()
                end
            end
        end
        ImGui.EndChild()
        if chosen then
            picker:SetListIndex(chosen)
            selected = A.actions[chosen + 1]
        end
        if session then
            ClickGUI.RenderFeature(H.FORCE_ACTION_ALL_FIRE)
            ImGui.SameLine()
            ClickGUI.RenderFeature(H.FORCE_ACTION_ALL_LOOP)
        else
            ClickGUI.RenderFeature(H.FORCE_ACTION_FIRE, playerId)
            ImGui.SameLine()
            ClickGUI.RenderFeature(H.FORCE_ACTION_LOOP, playerId)
        end
    end
    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
        A.stopped = true; A.pending = {}; A.loops = {}; A.allPending = {}; A.allRequest = nil
    end)
end

do
    H.DMG_EV_LOOP   = VIBE_FH("DamageEventsLoop")
    H.DMG_EV_RUN    = VIBE_FH("DamageEventsRunner")

    damageEvents = {
        pending = {}, nextSend = {}, loops = {}, last = {}, stopped = false,
        MELEE_FLAGS = 2 | 16 | 4096 | 131072 | 524288,
        FORCE_MELEE_DAMAGE = 8,
        STUN_FLAGS = 16 | 524288,
        UNARMED = Utils.sJoaat("weapon_unarmed"),
        STUNGUN = Utils.sJoaat("weapon_stungun_mp"),
        STUN_DAMAGE = 20.0,
        GROUP_UNARMED = Utils.Joaat("GROUP_UNARMED") & 0xFFFFFFFF,
        GROUP_MELEE = Utils.Joaat("GROUP_MELEE") & 0xFFFFFFFF,
        KNUCKLE = Utils.Joaat("WEAPON_KNUCKLE") & 0xFFFFFFFF,
        ARMED_FALLBACK = "ACT_hitby_front_no_melee_plyr_still",
        PARENTS = {
            AR_forward_short  = { damage = 25, force = true },
            AR_forward_medium = { damage = 25, force = true },
            AR_running        = { damage = 25, force = true },
            AR_heavy_1a       = { damage = 25, force = true },
            AR_heavy_1b       = { damage = 25, force = true },
            AR_kick_close     = { damage = 31, force = true },
            AR_shove          = { damage = 0, force = false },
            AR_running_shove  = { damage = 0, force = true },
        },
        MOVES = {
            { "Punch", "Punch", variants = {
                { "AR_forward_short", "ACT_hitby_forward_short", "any" },
                { "AR_forward_medium", "ACT_hitby_forward_medium", "any" },
                { "AR_running", "ACT_hitby_running", "any" },
                { "AR_heavy_1a", "ACT_hitby_heavy_1a", "fist" },
                { "AR_heavy_1b", "ACT_hitby_heavy_1b", "fist" },
            } },
            { "Shove", "Shove", onFoot = true, variants = {
                { "AR_shove", "ACT_hitby_armed_melee_front_melee", "any" },
                { "AR_shove", "ACT_hitby_armed_melee_left", "any" },
                { "AR_shove", "ACT_hitby_armed_melee_right", "any" },
                { "AR_shove", "ACT_hitby_armed_melee_back", "any" },
                { "AR_running_shove", "ACT_hitby_running_shove", "any" },
            } },
            { "Kick", "Kick", variants = {
                { "AR_kick_close", "ACT_hitby_kick_close", "melee" },
            } },
            { "Daze", "Daze", noFallback = true, variants = {
                { "AR_forward_short", "ACT_hitby_daze_a", "fist" },
                { "AR_forward_short", "ACT_hitby_daze_b", "fist" },
                { "AR_forward_short", "ACT_hitby_daze_c", "fist" },
                { "AR_forward_short", "ACT_hitby_daze_d", "fist" },
            } },
            { "Knockdown", "Knockdown", variants = {
                { "AR_forward_medium", "ACT_hitby_any_unarmed_ragdoll", "any" },
            } },
            { "Stun", "Stun", stun = true },
            { "RagdollRequest", "Ragdoll", request = true },
        },
        cycle = {},
        ragPtr = nil,
        RAG_TRIG = {
            enh = "56 57 48 83 EC 28 89 CE 48 8B 0D ? ? ? ? B2 01 E8 ? ? ? ? 0F B6 05 ? ? ? ? 48 8B 0D ? ? ? ? 48 C1 C1 ? 48 8B 05 ? ? ? ? 48 31 C8 80 E1 1F 80 C1 ? 48 D3 C0 48 C1 C0 20 48 F7 D0 0F B6 0D ? ? ? ? F6 C1 01 B9 00 00 00 00 48 0F 45 C8 BA 38 00 00 00 E8 ? ? ? ? 48 89 C7 48 C7 44 24 20 00 00 00 00 48 89 C1 66 BA 18 00",
            leg = "74 10 48 8B 82 D0 00 00 00 0F B7 48 0A E8 ? ? ? ? 48 8B 4B 20",
            legCall = 13,
        },
        messages = {
            busy = "Wait a moment before sending another hit.",
            identity = "This player's identity is unavailable.",
            changed = "The selected player left or changed.",
            self_target = "This action only supports other players.",
            notready = "Wait until you are in an active session.",
            me_missing = "Your character is unavailable. Wait until you have spawned.",
            other_missing = "The other player must be streamed in.",
            me_dead = "You are dead. Wait until you have respawned.",
            other_dead = "The other player is dead. Wait until they have respawned.",
            other_vehicle = "Shove only works on players on foot.",
            other_standing = "The other player is not standing. Wait until they are back on their feet.",
            other_armed = "Daze only works on unarmed players.",
            noped = "The target must be streamed in.",
            notrigger = "Couldn't resolve the damage-event function.",
            noragdoll = "Couldn't resolve the ragdoll-request function (AOB miss).",
        },
    }

    VIBE_TR.reg("Damage Events")
    for _, message in pairs(damageEvents.messages) do VIBE_TR.reg(message) end
    scanDoctor.register("DMG-RAGDOLL", { sig = scanDoctor.fieldSig(damageEvents, "RAG_TRIG", "leg", "enh") })

    damageEvents.fallback = Utils.Joaat(damageEvents.ARMED_FALLBACK) & 0xFFFFFFFF
    for _, move in ipairs(damageEvents.MOVES) do
        move.actionKey = "DamageEvent" .. move[1]
        move.hash = VIBE_FH(move.actionKey)
        for _, v in ipairs(move.variants or {}) do
            v.parent = Utils.Joaat(v[1]) & 0xFFFFFFFF
            v.reaction = Utils.Joaat(v[2]) & 0xFFFFFFFF
            v.strike = damageEvents.PARENTS[v[1]]
        end
    end

    function damageEvents.nextVariant(pid, move)
        if move.stun then return nil end
        local seen = damageEvents.cycle[pid] or {}
        damageEvents.cycle[pid] = seen
        local i = (seen[move[1]] or 0) % #move.variants + 1
        seen[move[1]] = i
        return move.variants[i]
    end

    function damageEvents.identity(pid)
        local player = Players.GetById(pid)
        local info = player and player:GetGamerInfo()
        local rid = info and math.tointeger(info.RockstarId or 0)
        return rid and rid > 0 and rid or nil
    end

    function damageEvents.toast(result, blockers)
        if result == "blocked" then
            local messages = {}
            for _, reason in ipairs(blockers) do messages[#messages + 1] = T(damageEvents.messages[reason]) end
            GUI.AddToast(T("Damage Events"), table.concat(messages, "\n"), 3000)
            return
        end
        if damageEvents.messages[result] then
            GUI.AddToast(T("Damage Events"), T(damageEvents.messages[result]), 3000)
        end
    end

    function damageEvents.enqueue(pid, move)
        if scriptUnloading or damageEvents.stopped then return end
        if damageEvents.pending[pid] or Time.GetEpocheMs() < (damageEvents.nextSend[pid] or 0) then
            damageEvents.toast("busy"); return
        end
        local rid = damageEvents.identity(pid)
        if not rid then damageEvents.toast("identity"); return end
        damageEvents.pending[pid] = { pid = pid, rid = rid, move = move }
        damageEvents.last[pid] = move
        telemetryCountAction(move.actionKey)
    end

    function damageEvents.stopLoop(pid)
        if not damageEvents.loops[pid] then return end
        damageEvents.loops[pid] = nil
        local f = FeatureMgr.GetFeature(H.DMG_EV_LOOP, pid)
        if f then f:SetBoolValue(false) end
    end

    function damageEvents.toggleLoop(f)
        local pid = f:GetPlayerIndex()
        if not f:IsToggled() then damageEvents.loops[pid] = nil; return end
        if scriptUnloading or damageEvents.stopped then f:SetBoolValue(false); return end
        local rid = damageEvents.identity(pid)
        if not rid then f:SetBoolValue(false); damageEvents.toast("identity"); return end
        if not damageEvents.loops[pid] then
            local move = damageEvents.last[pid] or damageEvents.MOVES[1]
            telemetryCountAction(move.actionKey)
        end
        f:SetBoolValue(true)
        damageEvents.loops[pid] = { pid = pid, rid = rid }
    end

    function damageEvents.blocker(ped, who, onFoot)
        if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then return who .. "_missing" end
        if Natives.InvokeBool(0x3317DEDB88C95038, ped, true) then return who .. "_dead" end
        if who == "me" or not onFoot then return end
        if PED.IS_PED_IN_ANY_VEHICLE(ped, true) then return who .. "_vehicle" end
        if Natives.InvokeBool(0x47E4E977581C5B55, ped)
            or Natives.InvokeBool(0xCEDABC5900A0BF97, ped)
            or Natives.InvokeBool(0xFB92A102F1C4DFA3, ped)
            or Natives.InvokeBool(0x60DFD0691A170B88, ped, false) then return who .. "_standing" end
    end

    function damageEvents.pointer(addr)
        return type(addr) == "number" and addr > 0x10000 and addr < 0x800000000000
    end

    function damageEvents.objectId(pid)
        local ped = Players.GetCPed(pid)
        return ped and ped.NetObject and math.tointeger(ped.NetObject.ObjectID)
    end

    function damageEvents.resolveRagdoll()
        if damageEvents.ragPtr ~= nil then return damageEvents.ragPtr end
        local sig = damageEvents.RAG_TRIG[IS_ENHANCED and "enh" or "leg"]
        local hit = Memory.Scan(sig)
        local fn = false
        if hit and hit ~= 0 then
            if IS_ENHANCED then
                fn = hit
            else
                local e8 = hit + damageEvents.RAG_TRIG.legCall
                if (Memory.ReadByte(e8) & 0xFF) == 0xE8 then fn = Memory.Rip(e8 + 1) end
            end
        end
        if not damageEvents.pointer(fn) then fn = false end
        damageEvents.ragPtr = fn
        return fn
    end

    function damageEvents.fits(variant, ped)
        if variant[3] == "any" then return true end
        local weapon = WEAPON.GET_SELECTED_PED_WEAPON(ped) & 0xFFFFFFFF
        local group = WEAPON.GET_WEAPONTYPE_GROUP(weapon) & 0xFFFFFFFF
        return group == damageEvents.GROUP_UNARMED or weapon == damageEvents.KNUCKLE
            or (variant[3] == "melee" and group == damageEvents.GROUP_MELEE)
    end

    function damageEvents.fire(job)
        if not isPlayerReady() then return "notready" end
        local me = GTA.GetLocalPlayerId()
        if job.pid == me then return "self_target" end
        if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(job.pid)
            or damageEvents.identity(job.pid) ~= job.rid then return "changed" end
        local onFoot = job.move.onFoot == true
        local theirPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(job.pid)
        local blockers = {}
        local mine
        if not job.move.request then
            local myPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(me)
            mine = damageEvents.blocker(myPed, "me", onFoot)
        end
        local theirs = damageEvents.blocker(theirPed, "other", onFoot)
        if mine then blockers[#blockers + 1] = mine end
        if theirs then blockers[#blockers + 1] = theirs end
        if #blockers > 0 then return "blocked", blockers end
        if job.move.request then
            local id = damageEvents.objectId(job.pid)
            if not id or id == 0 then return "noped" end
            local trig = damageEvents.resolveRagdoll()
            if not trig then return "noragdoll" end
            Memory.LuaCallCFunction(trig, id)
            return "ok"
        end
        local actor = Players.GetCPed(me)
        local target = Players.GetCPed(job.pid)
        local actorAddr = actor and actor:GetAddress()
        local targetAddr = target and target:GetAddress()
        if not damageEvents.pointer(actorAddr) or not damageEvents.pointer(targetAddr) then return "noped" end
        local fn = blameKill.resolveTrigger()
        if not fn then return "notrigger" end
        if job.move.stun then
            Memory.LuaCallCFunction(fn, actorAddr, targetAddr, targetAddr + 144, 0, 1,
                damageEvents.STUNGUN, damageEvents.STUN_DAMAGE, 0, 0, damageEvents.STUN_FLAGS,
                0, 0, 0, 0, 0, 0, 0, V3.New(0.0, 0.0, 0.0))
        else
            local seen = damageEvents.cycle[job.pid] or {}
            local peek = job.move.variants[(seen[job.move[1]] or 0) % #job.move.variants + 1]
            local fits = damageEvents.fits(peek, theirPed)
            if not fits and job.move.noFallback then return "blocked", { "other_armed" } end
            local variant = damageEvents.nextVariant(job.pid, job.move)
            local reaction = variant.reaction
            if not fits then reaction = damageEvents.fallback end
            local damage = variant.strike.damage + 0.0
            local flags = damageEvents.MELEE_FLAGS
            if variant.strike.force then flags = flags | damageEvents.FORCE_MELEE_DAMAGE end
            Memory.LuaCallCFunction(fn, actorAddr, targetAddr, targetAddr + 144, 0, 1,
                damageEvents.UNARMED, damage, 0, 0, flags,
                variant.parent, 0, reaction, 0, 0, 0, 0, V3.New(0.0, 0.0, 0.0))
        end
        return "ok"
    end

    function damageEvents.onTick(f)
        if scriptUnloading or damageEvents.stopped or ShouldUnload() then
            damageEvents.pending = {}; damageEvents.loops = {}; return
        end
        if not f:IsToggled() then return end
        if next(damageEvents.pending) == nil and next(damageEvents.loops) == nil then return end
        local now = Time.GetEpocheMs()
        local _, job = next(damageEvents.pending)
        for pid, loop in pairs(damageEvents.loops) do
            if not FeatureMgr.GetFeature(H.DMG_EV_LOOP, pid):IsToggled() then
                damageEvents.loops[pid] = nil
            elseif not job and now >= (damageEvents.nextSend[pid] or 0) then
                job = { pid = pid, rid = loop.rid, looped = true,
                    move = damageEvents.last[pid] or damageEvents.MOVES[1] }
            end
        end
        if not job then return end
        damageEvents.pending[job.pid] = nil
        damageEvents.nextSend[job.pid] = now + (job.looped and 1000 or 400)
        local result, blockers = damageEvents.fire(job)
        if result == "changed" or result == "self_target" then
            damageEvents.stopLoop(job.pid)
        elseif result == "notrigger" or result == "noragdoll" then
            VIBE_LOG_ERROR("[DamageEvents] " .. damageEvents.messages[result])
            for pid in pairs(damageEvents.loops) do damageEvents.stopLoop(pid) end
        end
        if result ~= "ok" and (not job.looped or result == "changed" or result == "self_target"
            or result == "notrigger" or result == "noragdoll") then
            damageEvents.toast(result, blockers)
        end
    end

    for _, move in ipairs(damageEvents.MOVES) do
        local description = ({
            Punch = "Punch this player.",
            Shove = "Shove this player.",
            Kick = "Kick this player.",
            Daze = "Leave this player dazed and stumbling.",
            Knockdown = "Ragdoll this player.",
            Stun = "Tase this player.",
            RagdollRequest = "Ragdoll this player.",
        })[move[1]]
        for _, hash in ipairs(FeatureMgr.AddPlayerFeature(move.hash, move[2], eFeatureType.Button,
            description, function(f) damageEvents.enqueue(f:GetPlayerIndex(), move) end)) do
            FeatureMgr.GetFeature(hash):SetSaveable(false)
        end
    end

    for _, hash in ipairs(FeatureMgr.AddPlayerFeature(H.DMG_EV_LOOP, "Loop", eFeatureType.Toggle,
        "Repeat the last hit sent to this player once per second.",
        damageEvents.toggleLoop)) do
        FeatureMgr.GetFeature(hash):SetSaveable(false)
    end

    centralOnTick(FeatureMgr.AddFeature(H.DMG_EV_RUN, "##DamageEventsRunner",
        eFeatureType.Toggle, "", damageEvents.onTick))
        :SetNoCallbackOnPress(true):SetSaveable(false):SetSearchable(false):SetVisible(false)
    FeatureMgr.GetFeature(H.DMG_EV_RUN):Toggle(true)

    damageEvents.ROWS = {
        { "Punch", "Kick", "Shove" },
        { "Daze", "Stun", "RagdollRequest" },
        { "Knockdown" },
    }

    damageEvents.byKey = {}
    for _, move in ipairs(damageEvents.MOVES) do damageEvents.byKey[move[1]] = move end

    function damageEvents.render(playerId)
        for _, row in ipairs(damageEvents.ROWS) do
            for i, key in ipairs(row) do
                if i > 1 then ImGui.SameLine() end
                ClickGUI.RenderFeature(damageEvents.byKey[key].hash, playerId)
            end
        end
        ImGui.SameLine()
        ClickGUI.RenderFeature(H.DMG_EV_LOOP, playerId)
    end

    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
        damageEvents.stopped = true; damageEvents.pending = {}; damageEvents.loops = {}
    end)
end

H.SILENT_KILL     = VIBE_FH("SilentKill")
H.SILENT_KILL_ALL = VIBE_FH("SilentKillAll")
H.SILENT_RUNNER   = VIBE_FH("SilentKillRunner")

silentKill = {
    queue = {},
    TAG   = 59,
    DRAIN = 6,
}

function silentKill.fire(victimPid)
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(victimPid) then return "noconn" end
    if Natives.InvokeBool(0x424D4687FA1E5652, victimPid) then return "dead" end
    local victim = Players.GetCPed(victimPid)
    if not victim then return "noped" end
    local pos = victim.Position
    if not pos then return "noped" end

    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(victimPid)
    if not ped or ped == 0 then return "noped" end
    FIRE.ADD_OWNED_EXPLOSION(ped, pos.x, pos.y, pos.z,
        silentKill.TAG, 1.0, false, true, 0.0)
    return "ok"
end

function silentKill.onTick(f)
    if not f:IsToggled() or scriptUnloading then return end
    local q = silentKill.queue
    if #q == 0 then return end
    if not isPlayerReady() then return end

    local done = 0
    while #q > 0 and done < silentKill.DRAIN do
        local job = table.remove(q, 1)
        if job.all then
            for pid = 0, 31 do
                if lockOntoPlayers.isSessionTarget(pid) then
                    q[#q + 1] = { v = pid, session = true }
                end
            end
        else
            local res = job.session and not lockOntoPlayers.isSessionTarget(job.v)
                and "protected" or silentKill.fire(job.v)
            done = done + 1
            log(("[SilentKill] victim=%s result=%s"):format(tostring(job.v), res))
        end
    end
end

for _, hash in ipairs(FeatureMgr.AddPlayerFeature(
    H.SILENT_KILL, "Silent Kill", eFeatureType.Button,
    "Kills this player silently.",
    function(f)
        silentKill.queue[#silentKill.queue + 1] = { v = f:GetPlayerIndex() }
        telemetryCountAction("SilentKill")
    end)) do
    FeatureMgr.GetFeature(hash):SetSaveable(false)
end

FeatureMgr.AddFeature(H.SILENT_KILL_ALL, "Silent Kill All", eFeatureType.Button,
    "Kills every other player in the session silently.",
    function(_)
        silentKill.queue[#silentKill.queue + 1] = { all = true }
        telemetryCountAction("SilentKillAll")
    end)
    :SetSaveable(false)

centralOnTick(FeatureMgr.AddFeature(H.SILENT_RUNNER, "##SilentKillRunner",
    eFeatureType.Toggle, "", silentKill.onTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
FeatureMgr.GetFeature(H.SILENT_RUNNER):Toggle()

function blameKill.renderBlamerCombo(suffix)
    ImGui.SetNextItemWidth(-((ImGui.CalcTextSize("Blame On") or 0) + 18))
    if Widget.beginCombo(T("Blame On") .. "##bk" .. suffix, blameKill.blamerName()) then
        local me = GTA.GetLocalPlayerId()
        for _, pid in pairs(Players.Get() or {}) do
            if pid ~= me then
                local isCur = (pid == blameKill.blamerPid)
                if ImGui.Selectable(
                        ("%s##bk%s%d"):format(blameKill.nameOf(pid), suffix, pid),
                        isCur) and not isCur then
                    blameKill.setBlamer(pid)
                end
            end
        end
        Widget.endCombo()
    end
end



;(function()

soundSpam = {
