local function activeCap()
    return state.experimental and HARD_CAP or GROUP_SLOTS
end

local function boardingForced()
    return state.cabinPack
end

local boardForcedByUs = false

local function syncBoardingLock()
    local forced = boardingForced()
    local want

    if forced and not state.instantBoard then
        boardForcedByUs, want = true, true
    elseif not forced and boardForcedByUs then
        boardForcedByUs, want = false, false
    else
        return
    end

    state.instantBoard = want
    local f = FeatureMgr.GetFeature(VIBE_FH("BG_InstantBoard"))
    if f then f:SetBoolValue(want) end
end

local function instantBoardOn()
    return state.instantBoard or boardingForced()
end

local function toast(msg, ms)
    GUI.AddToast(SCRIPT_NAME, tostring(msg), ms or 2500, eToastPos.TOP_RIGHT)
end

local LOG_KEEP = 40
local logBuf = {}

local function log(msg)
    if not logging.enabled or not RS.logOn or #guards == 0 then return end
    local text = tostring(msg)
    VIBE_LOG_INFO("[" .. SCRIPT_NAME .. "] " .. text)
    logBuf[#logBuf + 1] = text
    if #logBuf > LOG_KEEP then table.remove(logBuf, 1) end
end

local function logf(fmt, ...)
    log(string.format(fmt, ...))
end

local function logErr(msg)
    local text = tostring(msg)
    Logger.LogError("[" .. SCRIPT_NAME .. "] " .. text)
    logBuf[#logBuf + 1] = "ERROR: " .. text
    if #logBuf > LOG_KEEP then table.remove(logBuf, 1) end
end

local function logDrain(msg)
    local text = tostring(msg)
    if logging.enabled then VIBE_LOG_INFO("[" .. SCRIPT_NAME .. "] " .. text) end
    logBuf[#logBuf + 1] = text
    if #logBuf > LOG_KEEP then table.remove(logBuf, 1) end
end

