    [0xDD5DF8D9] = true, [0xCD274149] = true,
    [1737195953] = true, [1317494643] = true, [1141786504] = true,
    [2227010557] = true, [4192643659] = true, [1703483498] = true,
    [2460120199] = true, [4191993645] = true, [3638508604] = true,
    [2343591895] = true, [3756226112] = true, [419712736] = true,
    [2484171525] = true, [940833800] = true, [3670016037] = true,
    [2481070269] = true, [741814745] = true, [4256991824] = true,
    [2694266206] = true, [615608432] = true, [600439132] = true,
    [1233104067] = true, [4159824478] = true, [126349499] = true,
