function POSE.key(h)
    h = h and math.tointeger(h)
    return h and (h & 0xFFFFFFFF) or nil
end

for _, dict in ipairs(POSE.SEATS) do
    local k = POSE.key(joaat("clipset@" .. dict))
    if k then POSE.byHash[k] = dict end
    k = POSE.key(joaat(dict))
    if k then POSE.byHash[k] = dict end
end
for name, dict in pairs(POSE.ALIASES) do
    local k = POSE.key(joaat(name))
    if k then POSE.byHash[k] = dict end
end
for h, dict in pairs(POSE.SEEN) do
    POSE.byHash[h] = dict
end

function POSE.toLocal(veh, wx, wy, wz)
    if not wx then return nil end
    local vx, vy, vz = Natives.InvokeV3(N.GET_ENTITY_COORDS, veh, true)
    if not vx then return nil end
    local hdg = Natives.InvokeFloat(N.GET_ENTITY_HEADING, veh)
    if not hdg then return nil end

    local r = math.rad(hdg)
    local c, s = math.cos(r), math.sin(r)
    local dx, dy = wx - vx, wy - vy
    return dx * c + dy * s, dy * c - dx * s, (wz or vz) - vz
end


function POSE.forSeat(veh, seat, ped)
    if not veh or veh == 0 or not seat then return POSE.SIT_DICT, POSE.SIT end

    local h = POSE.key(Natives.InvokeInt(N.GET_IN_VEHICLE_CLIPSET_HASH_FOR_SEAT, veh, seat))
    if not h or h == 0 then return POSE.SIT_DICT, POSE.SIT end

    local dict  = POSE.byHash[h]
    local model = POSE.key(Natives.InvokeInt(N.GET_ENTITY_MODEL, veh)) or 0

    POSE.logged = POSE.logged or {}
    local key = string.format("%x:%d", model, seat)
    if not POSE.logged[key] then
        POSE.logged[key] = true
        local where = ""
        if ped and ped ~= 0 then
            local wx, wy, wz = Natives.InvokeV3(N.GET_WORLD_POSITION_OF_ENTITY_BONE, ped, 0)
            local lx, ly, lz = POSE.toLocal(veh, wx, wy, wz)
            if lx then
                where = string.format(" at local (%.2f,%.2f,%.2f)", lx, ly, lz)
            end
        end
        logf("pose: model 0x%08X seat %d clipset 0x%08X -> %s%s",
            model, seat, h, dict or "UNMAPPED, using the cabin idle", where)
    end

    if dict then return dict, POSE.CLIPS[dict] or POSE.SIT end
    return POSE.SIT_DICT, POSE.SIT
end

function POSE.hold(bg)
    local dict = bg.poseDict or POSE.SIT_DICT
    local clip = bg.poseClip or POSE.SIT

    if not Natives.InvokeBool(N.HAS_ANIM_DICT_LOADED, dict) then
        Natives.InvokeVoid(N.REQUEST_ANIM_DICT, dict)
        POSE.warnAt = POSE.warnAt or {}
        local now = nowMs()
        if (now - (POSE.warnAt[dict] or 0)) > 10000 then
            POSE.warnAt[dict] = now
            if Natives.InvokeBool(N.DOES_ANIM_DICT_EXIST, dict) then
                logf("pose: '%s' still streaming", dict)
            else
                logf("pose: '%s' DOES NOT EXIST; falling back to the seated pose", dict)
                bg.poseDict, bg.poseClip = POSE.SIT_DICT, POSE.SIT
            end
        end
        return
    end
    if Natives.InvokeBool(N.IS_ENTITY_PLAYING_ANIM, bg.handle, dict, clip, 3) then return end

    Natives.InvokeVoid(N.TASK_PLAY_ANIM, bg.handle,
        dict, clip,
        8.0, -8.0, -1, 1 | 8, 0.0, false, false, false)
end

function POSE.stop(bg)
    Natives.InvokeVoid(N.STOP_ANIM_TASK, bg.handle,
        bg.poseDict or POSE.SIT_DICT, bg.poseClip or POSE.SIT, -8.0)
    bg.poseDict, bg.poseClip = nil, nil
end


local function detachChildrenOf(parent)
    if not parent or parent == 0 then return end
    for _, kid in ipairs(guards) do
        if kid.handle ~= parent and entityExists(kid.handle) then
            local att = 0
            att = Natives.InvokeInt(N.GET_ENTITY_ATTACHED_TO, kid.handle) or 0
            if att == parent then
                kid.cpPacked, kid.cpHost, kid.cpAnimAt = false, nil, nil
                Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, kid.handle,
                    PCF.ATTACHED_TO_VEHICLE, false)
                Natives.InvokeVoid(N.DETACH_ENTITY, kid.handle, true, true)
                Natives.InvokeVoid(N.SET_ENTITY_COLLISION, kid.handle, true, true)
                POSE.stop(kid)
            end
        end
    end
end

local function releaseGuard(bg)
    if not entityExists(bg.handle) and bg.netId and bg.netId ~= 0 then
        local restored = Natives.InvokeInt(N.NET_TO_PED, bg.netId) or 0
        if restored ~= 0 and entityExists(restored)
           and (not bg.modelHash
                or Natives.InvokeInt(N.GET_ENTITY_MODEL, restored) == bg.modelHash) then
            local old = bg.handle
            bg.handle = restored
            if baseHealth[old] then
                baseHealth[restored], baseHealth[old] = baseHealth[old], nil
            end
        else
            removeBlipSafe(bg.blip)
            bg.blip = 0
            if RS.ragdollOwned then RS.ragdollOwned[bg.handle] = nil end
            baseHealth[bg.handle] = nil
            return true
        end
    end
    detachChildrenOf(bg.handle)
    if bg.cpPacked then
        bg.cpPacked, bg.cpHost = false, nil
        Natives.InvokeVoid(N.DETACH_ENTITY, bg.handle, true, true)
    end
    POSE.stop(bg)
    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, bg.handle,
        PCF.ATTACHED_TO_VEHICLE, false)
    removeBlipSafe(bg.blip)
    bg.blip = 0
    if RS.ragdollOwned then RS.ragdollOwned[bg.handle] = nil end
    baseHealth[bg.handle] = nil
    despawnPed(bg.handle, bg.netId)
    return not entityExists(bg.handle)
end

local function deleteGuard(target)
    if not target then return end
    for i, bg in ipairs(guards) do
        if bg == target then
            if releaseGuard(bg) then
                table.remove(guards, i)
            else
                bg.deletePending, bg.dead = true, true
                logf("delete pending: ped=%d netId=%s", bg.handle, tostring(bg.netId))
            end
            return
        end
    end
end

local function deleteAll()
    local count = #guards
    local pending = 0
    for i = #guards, 1, -1 do
        local bg = guards[i]
        if releaseGuard(bg) then
            table.remove(guards, i)
        else
            bg.deletePending, bg.dead = true, true
            pending = pending + 1
        end
    end
    if pending > 0 then
        logf("Delete All: %d deleted, %d pending retry", count - pending, pending)
        toast(T("Deleting %s guards (%s retrying)"):format(count, pending))
    else
        toast(T("Deleted %s guards"):format(count))
    end
end

local function abandonCorpse(bg)
    detachChildrenOf(bg.handle)
    if bg.cpPacked then
        bg.cpPacked, bg.cpHost = false, nil
        Natives.InvokeVoid(N.DETACH_ENTITY, bg.handle, true, true)
    end
    removeBlipSafe(bg.blip)
    bg.blip = 0
    if RS.ragdollOwned then RS.ragdollOwned[bg.handle] = nil end
    baseHealth[bg.handle] = nil
    bg.enteringVeh = false

    if not entityExists(bg.handle) then return end

    RS.asFreemode(function()
        if bg.netId then
            Natives.InvokeVoid(N.SET_NETWORK_ID_CAN_MIGRATE, bg.netId, true)
        end
        Memory.WriteInt(PTR.delete, bg.handle)
        Natives.InvokeVoid(N.SET_PED_AS_NO_LONGER_NEEDED, PTR.delete)
    end)
end

local function cleanupDead()
    for i = #guards, 1, -1 do
        local bg = guards[i]

        if bg.deletePending then
            bg.deleteSince = bg.deleteSince or nowMs()
            if releaseGuard(bg) then
                logf("delete retry complete: ped=%d", bg.handle or 0)
                table.remove(guards, i)
                if maintCursor > i then maintCursor = maintCursor - 1 end
            elseif nowMs() - bg.deleteSince > 10000 then
                logErr(string.format("delete gave up after 10s: %s ped=%d exists=%s",
                    tostring(bg.name), bg.handle or 0,
                    tostring(entityExists(bg.handle))))
                removeBlipSafe(bg.blip)
                bg.blip = 0
                baseHealth[bg.handle] = nil
                table.remove(guards, i)
                if maintCursor > i then maintCursor = maintCursor - 1 end
            elseif not bg.deleteRetryLogAt
                or (nowMs() - bg.deleteRetryLogAt) > 5000 then
                bg.deleteRetryLogAt = nowMs()
                logf("delete retry waiting: ped=%d netId=%s",
                    bg.handle or 0, tostring(bg.netId))
            end
        elseif not entityExists(bg.handle) then
            local now = nowMs()
            local restored = 0

            if bg.netId and bg.netId ~= 0 then
                restored = Natives.InvokeInt(N.NET_TO_PED, bg.netId) or 0
                if restored ~= 0 and entityExists(restored) and bg.modelHash
                   and Natives.InvokeInt(N.GET_ENTITY_MODEL, restored) ~= bg.modelHash then
                    restored = 0
                end
            end

            if restored ~= 0 and entityExists(restored) then
                local old = bg.handle
                bg.handle, bg.missingAt = restored, nil
                if baseHealth[old] then
                    baseHealth[restored], baseHealth[old] = baseHealth[old], nil
                end
                if bg.blip == 0
                   or not Natives.InvokeBool(0xA6DB27D19ECBB7DA, bg.blip) then
                    bg.blip = Natives.InvokeInt(N.ADD_BLIP_FOR_ENTITY, restored) or 0
                end
                logf("roster restore: netId=%d oldPed=%d newPed=%d",
                    bg.netId, old or 0, restored)
            else
                bg.missingAt = bg.missingAt or now
                if bg.netId and bg.netId ~= 0 then
                    Natives.InvokeVoid(N.SET_NETWORK_ID_ALWAYS_EXISTS_FOR_PLAYER,
                        bg.netId, myId(), true)
                    Natives.InvokeVoid(N.SET_NETWORK_ID_CAN_MIGRATE, bg.netId, false)
                end
                if (now - bg.missingAt) >= 15000 then
                    logErr(string.format("roster remove: %s vanished (netId=%s, last seen "
                        .. "%.0fm away at z=%.1f)", tostring(bg.name), tostring(bg.netId),
                        bg.lastDist or -1, bg.lastZ or 0.0))
                    removeBlipSafe(bg.blip)
                    bg.blip = 0
                    baseHealth[bg.handle] = nil
                    table.remove(guards, i)
                    if maintCursor > i then maintCursor = maintCursor - 1 end
                end
            end
        else
            bg.missingAt = nil
            local d = Natives.InvokeBool(N.IS_ENTITY_DEAD, bg.handle, false)
            if d then
                logf("roster remove: ped=%d reason=confirmed-dead", bg.handle)
                bg.dead = true
                abandonCorpse(bg)
                table.remove(guards, i)
                if maintCursor > i then maintCursor = maintCursor - 1 end
            end
        end
    end
    if maintCursor < 1 then maintCursor = 1 end
end



local function isEnteringVehicle(handle)
    local r = false
    r = Natives.InvokeBool(N.IS_PED_GETTING_INTO_A_VEHICLE, handle)
    return r
end

local seatCapCache = { veh = 0, cap = 0 }

local function seatCap(veh)
    if seatCapCache.veh == veh and veh ~= 0 then return seatCapCache.cap end

    local maxPass = 0
    maxPass = Natives.InvokeInt(N.GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS, veh) or 0

    local modelSeats = 0
    local model = Natives.InvokeInt(N.GET_ENTITY_MODEL, veh)
    if model and model ~= 0 then
        modelSeats = Natives.InvokeInt(N.GET_VEHICLE_MODEL_NUMBER_OF_SEATS, model) or 0
    end

    local cap = maxPass
    if modelSeats > 0 and (modelSeats - 1) < cap then cap = modelSeats - 1 end
    if cap < 0 then cap = 0 end

    seatCapCache.veh, seatCapCache.cap = veh, cap
    logf("seat capacity: maxPassengers=%d modelSeats=%d -> using %d",
        maxPass, modelSeats, cap)
    return cap
end

local function seatOccupier(veh, seat)
    local occ = 0
    occ = Natives.InvokeInt(N.GET_PED_IN_VEHICLE_SEAT, veh, seat, false) or 0
    return occ
end

function RS.seatedSet(veh)
    local set = {}
    if not veh or veh == 0 then return set end
    for s = 0, seatCap(veh) - 1 do
        local occ = seatOccupier(veh, s)
        if occ ~= 0 then set[occ] = s end
    end
    return set
end

function RS.occupantSet(veh)
    local set = {}
    if not veh or veh == 0 then return set end
    for s = -1, seatCap(veh) - 1 do
        local occ = seatOccupier(veh, s)
        if occ ~= 0 then set[occ] = true end
    end
    return set
end

local RAGDOLL_BLOCK_ALL = 0x3FFFF

function RS.ragdollLock(ped)
    Natives.InvokeVoid(N.SET_PED_CAN_BE_KNOCKED_OFF_VEHICLE, ped, 1)
    Natives.InvokeVoid(N.SET_PED_CAN_RAGDOLL, ped, false)
    Natives.InvokeVoid(N.SET_PED_CAN_RAGDOLL_FROM_PLAYER_IMPACT, ped, false)
    for _, flag in ipairs(PCF.RAGDOLL_LOCK_FLAGS) do
        Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, ped, flag, true)
    end
    Natives.InvokeVoid(N.SET_PED_RAGDOLL_ON_COLLISION, ped, false)
    Natives.InvokeVoid(N.SET_RAGDOLL_BLOCKING_FLAGS, ped, RAGDOLL_BLOCK_ALL)
end

function RS.ragdollApply(ped, packed)
    RS.ragdollOwned = RS.ragdollOwned or {}
    if state.cabinPack or packed or state.noRagdoll then
        RS.ragdollLock(ped)
        RS.ragdollOwned[ped] = true
        return
    end

    RS.ragdollOwned[ped] = nil
    Natives.InvokeVoid(N.SET_PED_CAN_BE_KNOCKED_OFF_VEHICLE, ped, 0)
    Natives.InvokeVoid(N.SET_PED_CAN_RAGDOLL, ped, true)
    Natives.InvokeVoid(N.SET_PED_CAN_RAGDOLL_FROM_PLAYER_IMPACT, ped, true)
    for _, flag in ipairs(PCF.RAGDOLL_LOCK_FLAGS) do
        Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, ped, flag, false)
    end
    Natives.InvokeVoid(N.CLEAR_RAGDOLL_BLOCKING_FLAGS, ped, RAGDOLL_BLOCK_ALL)
end



local function seatState(handle, veh, vx, vy, vz)
    if veh == 0 then return nil end

    local sitting = false
    sitting = Natives.InvokeBool(N.IS_PED_SITTING_IN_VEHICLE, handle, veh)
    if not sitting then return nil end

    local attachedTo = 0
    attachedTo = Natives.InvokeInt(N.GET_ENTITY_ATTACHED_TO, handle) or 0
    if attachedTo ~= veh then return "phantom" end

    if vx then
        local bx, by, bz = Natives.InvokeV3(N.GET_ENTITY_COORDS, handle, true)
        if bx then
            local dx, dy, dz = bx - vx, by - vy, bz - vz
            if dz < -PHANTOM_DROP then return "phantom" end
            if (dx * dx + dy * dy) > (PHANTOM_DIST * PHANTOM_DIST) then return "phantom" end
        end
    end
    return "aboard"
end


local STRANDED_MS = 6000

local function ejectFromSeats(why)
    local n, ejected = 0, 0

    local veh = Natives.InvokeInt(N.GET_VEHICLE_PED_IS_IN, myPed(), false) or 0
    local aboard = RS.seatedSet(veh)

    for _, bg in ipairs(guards) do
        if entityExists(bg.handle) then
            bg.enteringVeh = false
            if veh ~= 0 and aboard[bg.handle] then
                Natives.InvokeVoid(N.CLEAR_PED_TASKS_IMMEDIATELY, bg.handle)
                ejected = ejected + 1
            end
            n = n + 1
        end
    end

    logf("seat eject (%s): %d guard(s) reset, %d ejected from seats", why, n, ejected)
    return n
end


local function seatHeldBy(veh, handle, maxSeats)
    for seat = 0, maxSeats - 1 do
        if seatOccupier(veh, seat) == handle then return seat end
    end
    return nil
end





RS.FAR_RETURN_M, RS.NEAR_RETURN_M = 40.0, 20.0
RS.SCRIPT_TASK_GO_TO_ENTITY = joaat("SCRIPT_TASK_GO_TO_ENTITY")
RS.SCRIPT_TASK_FOLLOW = joaat("SCRIPT_TASK_FOLLOW_TO_OFFSET_OF_ENTITY")

function RS.controlCheck(bg, now)
    local owned = Natives.InvokeBool(N.NETWORK_HAS_CONTROL_OF_ENTITY, bg.handle)
    if owned then
        if bg.lostControlAt then
            logf("control: regained %s after %dms (%d request(s))", bg.name,
                now - bg.lostControlAt, bg.controlAsks or 0)
            pinToNetwork(bg)
            bg.lostControlAt, bg.controlAsks = nil, 0
        end
        return true
    end
    if not bg.lostControlAt then
        bg.lostControlAt, bg.controlAsks = now, 0
        local gx, gy, gz = Natives.InvokeV3(N.GET_ENTITY_COORDS, bg.handle, true)
        local near, nearD = "none", -1
        local me = myId()
        for i = 0, 31 do
            if i ~= me and Natives.InvokeBool(N.NETWORK_IS_PLAYER_ACTIVE, i) and gx then
                local ped = Natives.InvokeInt(N.GET_PLAYER_PED, i) or 0
                local x, y, z = Natives.InvokeV3(N.GET_ENTITY_COORDS, ped, true)
                if x then
                    local d = math.sqrt((x - gx) ^ 2 + (y - gy) ^ 2 + (z - gz) ^ 2)
                    if nearD < 0 or d < nearD then
                        nearD = d
                        near = tostring(Natives.InvokeString(N.GET_PLAYER_NAME, i))
                    end
                end
            end
        end
        local obj = GTA.HandleToPointer(bg.handle)
        local netObj = obj and obj.NetObject
        local ownerId = netObj and netObj.PlayerId or -1
        local owner = ownerId >= 0
            and tostring(Natives.InvokeString(N.GET_PLAYER_NAME, ownerId)) or "?"
        if VIBESCRIPT_VERBOSE == true then logErr(string.format("control: lost %s (netId=%s) to %s (player %d), nearest "
            .. "other player %s at %.0fm", tostring(bg.name), tostring(bg.netId), owner,
            ownerId, near, nearD)) end
    end
    if now - (bg.controlAskAt or 0) >= 500 then
        bg.controlAskAt = now
        bg.controlAsks = (bg.controlAsks or 0) + 1
        Natives.InvokeVoid(N.NETWORK_REQUEST_CONTROL_OF_ENTITY, bg.handle)
    end
    return false
end

function RS.returnFar(bg, pPed, px, py, pz, now)
    local gx, gy, gz = Natives.InvokeV3(N.GET_ENTITY_COORDS, bg.handle, true)
    if not gx or not px then return false end
    local d2 = (gx - px) ^ 2 + (gy - py) ^ 2 + (gz - pz) ^ 2
    if not bg.returning then
        if d2 <= RS.FAR_RETURN_M ^ 2 then return false end
    elseif d2 <= RS.NEAR_RETURN_M ^ 2 then
        logf("return: %s back within %.0fm after %d order(s)", bg.name,
            RS.NEAR_RETURN_M, bg.returnTries or 0)
        bg.returning, bg.returnTries = nil, 0
        bg.followKey, bg.followAt = nil, 0
        return false
    end

    local status = Natives.InvokeInt(N.GET_SCRIPT_TASK_STATUS, bg.handle,
        RS.SCRIPT_TASK_GO_TO_ENTITY)
    if status == 0 or status == 1 or status == 2 then return true end
    if bg.returning and now - (bg.returnAt or 0) < 1000 then return true end

    Natives.InvokeVoid(N.TASK_GO_TO_ENTITY, bg.handle, pPed, -1,
        RS.NEAR_RETURN_M - 5.0, 3.0, 0.0, 0)
    bg.returning, bg.returnAt = true, now
    bg.returnTries = (bg.returnTries or 0) + 1
    if bg.returnTries <= 3 then
        logf("return: %s ordered back from %.0fm (order %d, last status %d)", bg.name,
            math.sqrt(d2), bg.returnTries, status)
    end
    return true
end

local function refreshFollow(bg, slot, total, formValue, pPed, now, justLeftCombat)
    local key = string.format("%d:%d:%d", formValue, slot, total)
    local fresh = (bg.followKey ~= key) or justLeftCombat or (bg.followAt or 0) == 0
    local due = fresh or now >= (bg.followAt or 0)

    if not due then return end

    local ox, oy = formationOffset(slot, total, formValue)

    if not fresh then
        local wx, wy = Natives.InvokeV3(N.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS,
            pPed, ox, oy, 0.0)
        local gx, gy = Natives.InvokeV3(N.GET_ENTITY_COORDS, bg.handle, true)
        if wx and gx then
            local dx, dy = wx - gx, wy - gy
            if (dx * dx + dy * dy) < 4.0 then
                bg.followAt = now + FOLLOW_REFRESH_MS
                return
            end
        end
    end

    bg.followKey = key
    bg.followAt = now + FOLLOW_REFRESH_MS

    Natives.InvokeVoid(N.TASK_FOLLOW_TO_OFFSET_OF_ENTITY,
        bg.handle, pPed, ox, oy, 0.0, 2.0, -1, 0.5, true)
    bg.followIssuedAt = now
end


local CABIN = {
    veh = 0, spotFor = 0, spotAt = nil, spotSeat = nil,
    count = 0, logAt = 0, sweepAt = 0,

    BONES = {
        { "seat_pside_f",  0 },
        { "seat_pside_r",  2 }, { "seat_dside_r", 1 },
        { "seat_pside_r1" },    { "seat_dside_r1" },
        { "seat_pside_r2" },    { "seat_dside_r2" },
    },
    ANIM_MS = 1000,
    PER_PASS = 4,
    RETRY_MS = 400,
    RETRY_MAX_MS = 4000,

    holdUntil = 0,
    SWAP_HOLD_MS    = 900,

    STRANDED_NEAR_M = 10.0,
    STRANDED_SLOW   = 3.0,
    STRANDED_STILL  = 0.5,

    VEH_BUDGET = 5,
    PED_BUDGET = 7,
    SWEEP_MS = 250,
    SETTLE_MS = 1500,
    cap = {},
}

function CABIN.spot(veh)
    if CABIN.spotFor == veh and CABIN.spotAt then
        local s = CABIN.spotAt
        return s[1], s[2], s[3]
    end

    local spot, spotSeat = nil, nil
    for _, entry in ipairs(CABIN.BONES) do
        local name, seat = entry[1], entry[2]
        local idx = Natives.InvokeInt(N.GET_ENTITY_BONE_INDEX_BY_NAME, veh, name) or -1
        if idx >= 0 then
            local wx, wy, wz = Natives.InvokeV3(N.GET_WORLD_POSITION_OF_ENTITY_BONE, veh, idx)
            if wx then
                local ox, oy, oz = POSE.toLocal(veh, wx, wy, wz)
                if ox then
                    spot, spotSeat = { ox, oy, oz }, seat
                    logf("cabin: riders pinned to %s (seat %s) on vehicle %d at (%.2f,%.2f,%.2f)",
                        name, seat and tostring(seat) or "?", veh, ox, oy, oz)
                    break
                end
            end
        end
    end
    if not spot then
        spot = { 0.0, 0.0, 0.2 }
        logf("cabin: no passenger seat bone on vehicle %d, using the origin", veh)
    end

    CABIN.spotAt, CABIN.spotFor, CABIN.spotSeat = spot, veh, spotSeat
    return spot[1], spot[2], spot[3]
end

function CABIN.attached(handle, host)
    if not host or host == 0 then return false end
    return (Natives.InvokeInt(N.GET_ENTITY_ATTACHED_TO, handle) or 0) == host
end

function CABIN.buildHosts(veh, maxSeats)
    CABIN.spot(veh)
    local hosts = { { h = veh, veh = true, seat = CABIN.spotSeat } }
    local occupants, seated = 0, {}

    for seat = -1, maxSeats - 1 do
        local occ = seatOccupier(veh, seat)
        if occ ~= 0 then
            occupants = occupants + 1
            seated[occ] = true
            if seat >= 0 then hosts[#hosts + 1] = { h = occ, seat = seat } end
        end
    end

    local vehRoom = CABIN.VEH_BUDGET - occupants
    if vehRoom < 0 then vehRoom = 0 end
    hosts[1].seed = vehRoom

    return hosts, occupants, seated
end

function CABIN.hostSpot(veh, host)
    if host == veh then return CABIN.spot(veh) end
    return 0.0, 0.0, 0.0
end

function CABIN.pose(bg, now)
    if (now - (bg.cpAnimAt or 0)) < CABIN.ANIM_MS then return end
    bg.cpAnimAt = now

    RS.ragdollLock(bg.handle)
    Natives.InvokeVoid(N.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, bg.handle, true)
    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, bg.handle,
        PCF.DISABLE_EXPLOSION_REACTIONS, true)
    POSE.hold(bg)
end

function CABIN.attach(bg, veh, entry, now)
    local h    = bg.handle
    local host = entry.h

    if host == h then
        logErr("cabin: refused to attach guard " .. tostring(h) .. " to itself")
        bg.cpNextAt = now + CABIN.RETRY_MAX_MS
        return false
    end

    Natives.InvokeVoid(N.NETWORK_REQUEST_CONTROL_OF_ENTITY, h)
    Natives.InvokeVoid(N.CLEAR_PED_TASKS_IMMEDIATELY, h)
    if (Natives.InvokeInt(N.GET_ENTITY_ATTACHED_TO, h) or 0) ~= 0 then
        Natives.InvokeVoid(N.DETACH_ENTITY, h, true, true)
    end
    RS.ragdollLock(h)
    Natives.InvokeVoid(N.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, h, true)
    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, h, PCF.ATTACHED_TO_VEHICLE, true)
    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, h, PCF.DISABLE_EXPLOSION_REACTIONS, true)
    Natives.InvokeVoid(N.SET_ENTITY_COLLISION, h, false, false)

    local ox, oy, oz = CABIN.hostSpot(veh, host)
    Natives.InvokeVoid(N.ATTACH_ENTITY_TO_ENTITY,
        h, host, -1,
        ox, oy, oz,
        0.0, 0.0, 0.0,
        false,
        false,
        false,
        false,
        2,
        true,
        false)

    if CABIN.attached(h, host) then
        bg.cpPacked, bg.cpHost = true, host
        bg.rideState = true
        bg.cpFails, bg.cpNextAt, bg.cpAnimAt = 0, 0, 0
        bg.cpPinnedAt = now
        local occupant = host
        if host == veh then
            occupant = entry.seat and seatOccupier(veh, entry.seat) or 0
        end
        bg.poseDict, bg.poseClip = POSE.forSeat(veh, entry.seat, occupant)
        logf("cabin: pinned to %s %d (seat %s) -> %s",
            host == veh and "vehicle" or "host", host,
            entry.seat and tostring(entry.seat) or "?", bg.poseDict)
        CABIN.pose(bg, now)
        return true
    end

    CABIN.defuse(h)

    bg.cpFails = (bg.cpFails or 0) + 1
    local wait = CABIN.RETRY_MS * (2 ^ math.min(bg.cpFails, 4))
    if wait > CABIN.RETRY_MAX_MS then wait = CABIN.RETRY_MAX_MS end
    bg.cpNextAt = now + wait
    return false
end

function CABIN.ptrOk(p)
    if type(p) ~= "number" then return false end
    return p > 0x10000 and p < 0x7FFFFFFFFFFF
end

function CABIN.defuse(handle)
    local obj = GTA.HandleToPointer(handle)
    if not obj then return end

    local base = obj
    if type(base) ~= "number" then base = obj:GetAddress() end
    if not CABIN.ptrOk(base) then return end

    local list = Memory.ReadLong(base + 0x50)
    if not CABIN.ptrOk(list) then return end
    local ext = Memory.ReadLong(list + 0x48)
    if not CABIN.ptrOk(ext) then return end

    if Memory.ReadLong(ext + 0x00) ~= 0 then return false end

    local flags = Memory.ReadInt(ext + 0x5C)
    if not flags then return false end
    if (flags & 0xF) ~= 0 then
        Memory.WriteInt(ext + 0x5C, flags & ~0xF)
        logf("cabin: cleared attach state %d on parentless rider %d",
            flags & 0xF, handle)
        return true
    end
    return false
end

function CABIN.sweep(now)
    if (now - (CABIN.sweepAt or 0)) < CABIN.SWEEP_MS then return end
    CABIN.sweepAt = now

    local fixed = 0
    for _, bg in ipairs(guards) do
        if entityExists(bg.handle) then
            if CABIN.defuse(bg.handle) then
                bg.cpPacked, bg.cpHost = false, nil
                bg.cpFails, bg.cpNextAt, bg.cpAnimAt = 0, 0, 0
                CABIN.unride(bg, true)
                Natives.InvokeVoid(N.CLEAR_PED_TASKS, bg.handle)
                fixed = fixed + 1
            end
        end
    end
    if fixed > 0 then
        logf("cabin: repaired %d parentless rider(s)", fixed)
    end
end

function CABIN.unride(bg, force)
    if not (force or bg.rideState) then return end
    bg.rideState = nil
    if not entityExists(bg.handle) then return end

    POSE.stop(bg)
    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, bg.handle, PCF.ATTACHED_TO_VEHICLE, false)
    Natives.InvokeVoid(N.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, bg.handle, false)
    Natives.InvokeVoid(N.SET_ENTITY_COLLISION, bg.handle, true, true)
    RS.ragdollApply(bg.handle, false)
end

function CABIN.release(bg, dropIdx, vx, vy, vz)
    if not bg.cpPacked then
        if not entityExists(bg.handle) then return false end
        CABIN.unride(bg)
        local defused = CABIN.defuse(bg.handle)
        local att = Natives.InvokeInt(N.GET_ENTITY_ATTACHED_TO, bg.handle) or 0
        if not defused then
            if att == 0 then return false end
            if Natives.InvokeBool(N.IS_PED_IN_ANY_VEHICLE, bg.handle, false) then
                return false
            end
            logf("cabin: stale pin, guard attached to %d with cpPacked=false; releasing",
                att)
        end
    end
    bg.cpPacked, bg.cpHost = false, nil
    bg.cpFails, bg.cpNextAt, bg.cpAnimAt = 0, 0, 0

    if not entityExists(bg.handle) then return true end

    CABIN.defuse(bg.handle)

    CABIN.unride(bg, true)
    Natives.InvokeVoid(N.DETACH_ENTITY, bg.handle, true, true)
    Natives.InvokeVoid(N.CLEAR_PED_TASKS, bg.handle)

    if vx then
        local ox, oy = ringSlot(dropIdx, 3.0, FORM_SPACING)
        local tx, ty = vx + ox, vy + oy
        Natives.InvokeVoid(N.SET_ENTITY_COORDS, bg.handle,
            tx, ty, groundZ(tx, ty, vz), false, false, false, false)
        Natives.InvokeVoid(N.SET_ENTITY_VELOCITY, bg.handle, 0.0, 0.0, 0.0)
    end
    return true
end

function CABIN.releaseAll(why, veh)
    local ownsState = (veh == nil)
    veh = veh or CABIN.veh
    local alive = veh ~= 0 and entityExists(veh)

    local vx, vy, vz
    if alive then vx, vy, vz = Natives.InvokeV3(N.GET_ENTITY_COORDS, veh, true) end

    local dropped = 0
    for _, bg in ipairs(guards) do
        if CABIN.release(bg, dropped, vx, vy, vz) then
            dropped = dropped + 1
        end
    end

    if ownsState then CABIN.veh = 0 end
    CABIN.spotAt, CABIN.spotFor, CABIN.spotSeat, CABIN.count = nil, 0, nil, 0
    CABIN.cap = {}
    if dropped > 0 then logf("cabin: released %d rider(s) (%s)", dropped, why) end
    return dropped
end

function CABIN.evacuate(veh, why)
    if not veh or veh == 0 or not entityExists(veh) then return 0 end

    local vx, vy, vz = Natives.InvokeV3(N.GET_ENTITY_COORDS, veh, true)
    local out, stale = 0, 0

    local aboard = RS.seatedSet(veh)

    for _, bg in ipairs(guards) do
        if entityExists(bg.handle) and not bg.dead then
            local st = aboard[bg.handle] and seatState(bg.handle, veh, vx, vy, vz) or nil
            if st == "phantom" then
                Natives.InvokeVoid(N.CLEAR_PED_TASKS_IMMEDIATELY, bg.handle)
                bg.enteringVeh = false
                stale = stale + 1
                logf("evac: guard %d held a seat it was not sitting in; slot released",
                    bg.handle)
            else
                local wasRider = CABIN.release(bg, out)

                local inSeat = (st == "aboard")
                local entering = not inSeat and isEnteringVehicle(bg.handle)

                if inSeat or entering then
                    CABIN.unride(bg, true)
                    Natives.InvokeVoid(N.CLEAR_PED_TASKS_IMMEDIATELY, bg.handle)
                    bg.enteringVeh = false
                end

                if wasRider or inSeat or entering then
                    local ox, oy = ringSlot(out, 3.0, FORM_SPACING)
                    local tx, ty = vx + ox, vy + oy
                    Natives.InvokeVoid(N.SET_ENTITY_COORDS, bg.handle,
                        tx, ty, groundZ(tx, ty, vz), false, false, false, false)
                    Natives.InvokeVoid(N.SET_ENTITY_VELOCITY, bg.handle, 0.0, 0.0, 0.0)
                    bg.followAt = 0
                    out = out + 1
                    logf("evac: guard %d out (rider=%s seat=%s door=%s)", bg.handle,
                        tostring(wasRider), tostring(inSeat), tostring(entering))
                end
            end
        end
    end

    CABIN.veh = 0
    CABIN.spotAt, CABIN.spotFor, CABIN.spotSeat, CABIN.count = nil, 0, nil, 0
    CABIN.cap = {}
    if out > 0 then logf("cabin: put %d guard(s) out of vehicle %d (%s)", out, veh, why) end
    return out, stale
end

function CABIN.pass(pPed, now)
    CABIN.sweep(now)

    if not state.cabinPack then
        if CABIN.veh ~= 0 then CABIN.releaseAll("toggled off") end
        return
    end

    local veh = 0
    if Natives.InvokeBool(N.IS_PED_IN_ANY_VEHICLE, pPed, false) then
        veh = Natives.InvokeInt(N.GET_VEHICLE_PED_IS_IN, pPed, false) or 0
    end

    if veh ~= CABIN.veh then
        local old = CABIN.veh
        CABIN.veh = veh
        CABIN.releaseAll(veh == 0 and "left the vehicle" or "vehicle changed", old)
    end
    if veh == 0 or #guards == 0 then return end

    if now < CABIN.holdUntil then return end

    local maxSeats = seatCap(veh)
    local hosts, occupants, seatedSet = CABIN.buildHosts(veh, maxSeats)

    local budget = CABIN.PER_PASS
    local seat, packed, held = 0, 0, {}
    local pending, lost = nil, nil

    local hostOk = {}
    for _, e in ipairs(hosts) do hostOk[e.h] = true end

    for _, bg in ipairs(guards) do
        if entityExists(bg.handle) and not bg.dead and not bg.animal
           and not isEnteringVehicle(bg.handle) then
            if bg.cpHost and hostOk[bg.cpHost] and CABIN.attached(bg.handle, bg.cpHost) then
                bg.cpPacked = true
                held[bg.cpHost] = (held[bg.cpHost] or 0) + 1
                CABIN.pose(bg, now)
                packed = packed + 1
            elseif seatedSet[bg.handle] then
                bg.cpPacked, bg.cpHost = false, nil
                CABIN.unride(bg)
            else
                if bg.cpPacked and bg.cpHost then
                    CABIN.defuse(bg.handle)
                    if entityExists(bg.cpHost) and hostOk[bg.cpHost] then
                        lost = lost or {}
                        lost[#lost + 1] = { h = bg.cpHost, g = bg.handle,
                                            known = CABIN.cap[bg.cpHost] ~= nil,
                                            age = now - (bg.cpPinnedAt or now) }
                    end
                end
                bg.cpPacked, bg.cpHost = false, nil
                CABIN.unride(bg)
                pending = pending or {}
                pending[#pending + 1] = bg
            end
        end
    end
    CABIN.count = packed

    if lost then
        for _, e in ipairs(lost) do
            if e.age < CABIN.SETTLE_MS then
                local room = held[e.h] or 0
                if (CABIN.cap[e.h] or math.huge) > room then
                    CABIN.cap[e.h] = room
                    logf("cabin: host %d full at %d rider(s) (pin died after %dms)",
                        e.h, room, e.age)
                end
            end
        end
    end

    if not pending then return end

    local hostIdx = 1
    for _, bg in ipairs(pending) do
        if budget <= 0 then break end

        local seated = false
        while seat < maxSeats do
            if seatOccupier(veh, seat) == 0 then
                CABIN.unride(bg)
                RS.ragdollLock(bg.handle)
                Natives.InvokeVoid(N.SET_PED_INTO_VEHICLE, bg.handle, veh, seat)
                bg.enteringVeh, bg.noSeat, bg.warpTries = false, false, 0
                seat, seated = seat + 1, true
                budget = budget - 1
                hosts, occupants = CABIN.buildHosts(veh, maxSeats)
                hostIdx = 1
                break
            end
            seat = seat + 1
        end

        if not seated and now >= (bg.cpNextAt or 0) then
            local host = nil
            local scan = hostIdx
            while scan <= #hosts do
                local candidate = hosts[scan]
                local limit = CABIN.cap[candidate.h]
                    or candidate.seed or CABIN.PED_BUDGET
                if (held[candidate.h] or 0) >= limit
                    or not entityExists(candidate.h) then
                    scan = scan + 1
                    hostIdx = scan
                elseif candidate.h == bg.handle then
                    scan = scan + 1
                else
                    host = candidate
                    break
                end
            end

            if not host then break end

            if CABIN.attach(bg, veh, host, now) then
                held[host.h] = (held[host.h] or 0) + 1
                CABIN.count = CABIN.count + 1
            end
            budget = budget - 1
        end
    end

    if CABIN.count > 0 and (now - CABIN.logAt) > 5000 then
        CABIN.logAt = now
        local room = 0
        for _, e in ipairs(hosts) do
            room = room + (CABIN.cap[e.h] or e.seed or CABIN.PED_BUDGET)
        end
        logf("cabin: %d seat(s) %d occupied, %d rider(s) on %d host(s), room for %d",
            maxSeats, occupants, CABIN.count, #hosts, room)
    end
end


