    VIBE_TR.trackList(VIBE_FH("BG_Weapon2"), WEAPON2_NAMES)
    VIBE_TR.trackList(VIBE_FH("BG_Formation"), FORMATION_NAMES)
    for _, h in ipairs({ "LUA_BG_TgtPlayer", "LUA_BG_TgtNpc", "LUA_BG_TgtGang" }) do
        VIBE_TR.trackList(joaat(h), TGT.LEVEL_NAMES)
    end
    local f = FeatureMgr.GetFeature(VIBE_FH("BG_Model"))
