    local f = FeatureMgr.GetFeature(VIBE_FH("BG_Weapon"))
    if f then f:SetList(TLIST(WEAPON_NAMES)); f:SetListIndex(state.weaponIdx) end
    local f = FeatureMgr.GetFeature(VIBE_FH("BG_Weapon2"))
    if f then f:SetList(TLIST(WEAPON2_NAMES)); f:SetListIndex(0) end
    local f = FeatureMgr.GetFeature(VIBE_FH("BG_Formation"))
    if f then f:SetList(TLIST(FORMATION_NAMES)); f:SetListIndex(0) end
    for _, r in ipairs({ { "LUA_BG_TgtPlayer", TGT.PLAYER }, { "LUA_BG_TgtNpc", TGT.NPC },
                         { "LUA_BG_TgtGang", TGT.GANG } }) do
        local f = FeatureMgr.GetFeature(joaat(r[1]))
        if f then f:SetList(TLIST(TGT.LEVEL_NAMES)); f:SetListIndex(TGT.level(r[2])) end
    end

    local defaults = {
        { "LUA_BG_CabinPack",    state.cabinPack },
        { "LUA_BG_InstantBoard", state.instantBoard },
        { "LUA_BG_Experimental", state.experimental },
        { "LUA_BG_Preview",      state.showPreview },
        { "LUA_BG_DisableFriendOrgTargeting", state.disableFriendOrgTargeting },
        { "LUA_BG_NoRagdoll", state.noRagdoll },
        { "LUA_BG_NeverWanted", state.neverWanted },
    }
    for _, d in ipairs(defaults) do
        local id = d[1]:match("^LUA_(.+)$")
        local ft = id and FeatureMgr.GetFeature(VIBE_FH(id)) or nil
        if not ft then ft = FeatureMgr.GetFeature(joaat(d[1])) end
        if ft then ft:SetBoolValue(d[2]) end
    end

    refreshConfigList()
    logf("Feature init complete (infinite passengers %s)",
        state.cabinPack and "ON" or "OFF")
end)


local function panel(id, title, body)
    ImGui.PushID(id)
    if ClickGUI.BeginCustomChildWindow(T(title)) then
        body()
        ClickGUI.EndCustomChildWindow()
    end
    ImGui.PopID()
end

local function twoColumn(id, left, right)
    if ImGui.BeginTable(id, 2, ImGuiTableFlags.SizingStretchSame) then
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0)
        left()
        ImGui.TableSetColumnIndex(1)
        right()
        ImGui.EndTable()
    end
end

local function feat(name)
    local id = name:match("^LUA_(.+)$")
    local hash = id and VIBE_FH(id) or nil
    if not hash or not FeatureMgr.GetFeature(hash) then hash = joaat(name) end
    ClickGUI.RenderFeature(hash)
end

local function experimentalHint()
    if not ImGui.IsItemHovered() then return end
    if #guards + state.pedCount <= GROUP_SLOTS then return end

    if state.experimental then
        ImGui.SetTooltip(
            T("Past %s is EXPERIMENTAL\n\nThe engine ped group holds %s. Beyond that,\nguards follow on explicit tasks and ride attached to vehicles\nrather than sitting in seats."):format(GROUP_SLOTS, GROUP_SLOTS))
    else
        ImGui.SetTooltip(
            T("Capped at %s bodyguards\n\nThe engine ped group holds %s, and every\nguard sits in a real seat. Turn on Experimental Mode\nto spawn more."):format(GROUP_SLOTS, GROUP_SLOTS))
    end
end

local function modelTree()
    local changed = false
    ImGui.SetNextItemWidth(-1)
    modelFilter = ImGui.InputTextWithHint("##bg_modelsearch", T("Search models"),
        modelFilter) or ""
    local needle = modelFilter:lower():match("^%s*(.-)%s*$") or ""

    local function row(ci, mi, m)
        local sel = (state.catIdx == ci - 1 and state.modelIdx == mi - 1)
        if ImGui.Selectable(m.n .. "##bg" .. ci .. "_" .. mi, sel) and not sel then
            state.catIdx, state.modelIdx = ci - 1, mi - 1
            changed = true
        end
    end

    if ImGui.BeginChild("bg_modeltree", 0, 260, true) then
        if needle ~= "" then
            if modelSearch.needle ~= needle then
                modelSearch.needle, modelSearch.rows = needle, {}
                for ci, cat in ipairs(MODELS) do
                    for mi, m in ipairs(cat) do
                        if m.n:find(needle, 1, true) then
                            modelSearch.rows[#modelSearch.rows + 1] = {ci=ci, mi=mi, model=m}
                        end
                    end
                end
            end
            Widget.clippedRows(#modelSearch.rows, 260, function(index)
                local match = modelSearch.rows[index]
                row(match.ci, match.mi, match.model)
            end)
        else
            for ci, cat in ipairs(MODELS) do
                if state.catIdx == ci - 1 then
                    ImGui.SetNextItemOpen(true, ImGuiCond.Once)
                end
                if ImGui.TreeNode(("bg_cat%s"):format(ci),
                        (CATEGORIES[ci] or "?") .. " (" .. #cat .. ")") then
                    Widget.clippedRows(#cat, 260, function(mi) row(ci, mi, cat[mi]) end)
                    ImGui.TreePop()
                end
            end
        end
    end

    ImGui.EndChild()

    if changed then
        local cf = FeatureMgr.GetFeature(VIBE_FH("BG_Category"))
        if cf then cf:SetListIndex(state.catIdx) end
        local mf = FeatureMgr.GetFeature(VIBE_FH("BG_Model"))
        if mf then
            mf:SetList(TLIST(MODEL_NAMES[state.catIdx + 1] or {}))
            mf:SetListIndex(state.modelIdx)
        end
    end
end

