function sessionBrowser.log(message, ...)
    if not sessionBrowser.verbose then return end
    if select("#", ...) > 0 then message = message:format(...) end
    VIBE_LOG_INFO("[VibeScript Browser] " .. tostring(message))
end

function sessionBrowser.logError(message, ...)
    if select("#", ...) > 0 then message = message:format(...) end
    Logger.LogError("[VibeScript Browser] " .. tostring(message))
end

function sessionBrowser.toast(text, ms)
    GUI.AddToast("Session Browser", text, ms or 5000, eToastPos.TOP_RIGHT)
end


function sessionBrowser.resolveAddresses()
    if sessionBrowser.addr then return sessionBrowser.addr end

    local presencePat = sessionBrowser.AOB.presence[IS_ENHANCED and "enh" or "leg"]
    local detailPat = sessionBrowser.AOB.queryDetail[IS_ENHANCED and "enh" or "leg"]
    if not presencePat or not detailPat then
        return nil, "no signature for this game edition"
    end

    local presence = Memory.Scan(presencePat)
    if not presence or presence == 0 then
        return nil, "GetSessionByGamerHandle AOB was not found"
    end

    local queryDetail = Memory.Scan(detailPat)
    if not queryDetail or queryDetail == 0 then
        return nil, "rlSessionManager::QueryDetail AOB was not found"
    end

    sessionBrowser.addr = { presence = presence, queryDetail = queryDetail }
    sessionBrowser.log("Resolved presence=0x%X queryDetail=0x%X", presence, queryDetail)
    return sessionBrowser.addr
end

function sessionBrowser.allocBuffers(owner)
    owner = owner or sessionBrowser
    if owner.buf then return owner.buf end

    local sb = sessionBrowser
    local buf = {}
    local specs = {
        { "handles",     sb.MAX_BATCH * sb.GAMER_HANDLE_SIZE },
        { "queryData",   sb.MAX_BATCH * sb.QUERY_DATA_SIZE },
        { "infos",       sb.MAX_BATCH * sb.SESSION_INFO_SIZE },
        { "details",     sb.MAX_BATCH * sb.SESSION_DETAIL_SIZE },
        { "resultCount", 4 },
        { "status",      sb.NET_STATUS_SIZE },
        { "detailCount",  4 },
        { "detailStatus", sb.NET_STATUS_SIZE },
        { "noTarget", 0x20 },
    }

    for _, spec in ipairs(specs) do
        local name, size = spec[1], spec[2]
        local ptr = Memory.Alloc(size)
        if not ptr or ptr == 0 then
            sb.logError("Buffer allocation failed for %s", name)
            for _, allocated in pairs(buf) do
                if allocated and allocated ~= 0 then Memory.Free(allocated) end
            end
            return nil, "failed to allocate the " .. name .. " buffer"
        end
        buf[name] = ptr
    end
    Memory.MemSet(buf.noTarget, 0, 0x20)

    sb.log("Buffers handles=0x%X queryData=0x%X infos=0x%X details=0x%X",
        buf.handles, buf.queryData, buf.infos, buf.details)
    owner.buf = buf
    return buf
end

function sessionBrowser.allocJoinBuffers()
    if sessionBrowser.joinBuf then return sessionBrowser.joinBuf end

    local sb = sessionBrowser
    local buf = {}
    local specs = {
        { "handles",     sb.MAX_BATCH * sb.GAMER_HANDLE_SIZE },
        { "queryData",   sb.MAX_BATCH * sb.QUERY_DATA_SIZE },
        { "resultCount", 4 },
        { "status",      sb.NET_STATUS_SIZE },
    }

    for _, spec in ipairs(specs) do
        local name, size = spec[1], spec[2]
        local ptr = Memory.Alloc(size)
        if not ptr or ptr == 0 then
            sb.logError("Join buffer allocation failed for %s", name)
            for _, allocated in pairs(buf) do
                if allocated and allocated ~= 0 then Memory.Free(allocated) end
            end
            return nil, "failed to allocate the join " .. name .. " buffer"
        end
        buf[name] = ptr
    end

    sb.log("Join buffers handles=0x%X queryData=0x%X", buf.handles, buf.queryData)
    sb.joinBuf = buf
    return buf
end


function sessionBrowser.readAsciiz(address, maxLen)
    local out = {}
    for i = 0, maxLen - 1 do
        local b = Memory.ReadUByte(address + i)
        if b == 0 then break end
        if b < 0x20 or b > 0x7E then return nil end
        out[#out + 1] = string.char(b)
    end
    if #out == 0 then return nil end
    return table.concat(out)
end

function sessionBrowser.hexDump(address, length)
    local parts = {}
    for i = 0, length - 1 do
        parts[#parts + 1] = ("%02X"):format(Memory.ReadUByte(address + i))
    end
    return table.concat(parts, " ")
end

function sessionBrowser.copyBlock(dst, src, size)
    for offset = 0, size - 4, 4 do
        Memory.WriteInt(dst + offset, Memory.ReadInt(src + offset))
    end
end

function sessionBrowser.zeroBlock(ptr, size)
    Memory.MemSet(ptr, 0, size)
end

function sessionBrowser.awaitStatus(statusPtr, timeoutMs, label)
    local started = Time.GetEpocheMs()
    local state = Memory.ReadInt(statusPtr)
    local warned = false
    while state == sessionBrowser.NET_STATUS_PENDING do
        if ShouldUnload() or scriptUnloading then
            sessionBrowser.logError("%s abandoned: unloading with a task pending", label)
            return nil, nil
        end
        if not warned and Time.GetEpocheMs() - started > timeoutMs then
            sessionBrowser.logError("%s timed out after %dms", label, timeoutMs)
            warned = true
        end
        Script.Yield(50)
        state = Memory.ReadInt(statusPtr)
    end
    return state, Memory.ReadInt(statusPtr + 4)
end

sessionBrowser.POLL_MS = 25

function sessionBrowser.pollTask(task)
    if scriptUnloading or ShouldUnload() then return false end
    local state = Memory.ReadInt(task.status)
    if state == sessionBrowser.NET_STATUS_PENDING then
        if Time.GetEpocheMs() - task.started <= task.timeoutMs then return false end
        if not task.timeoutLogged then
            sessionBrowser.logError("%s timed out after %dms; waiting for the engine "
                .. "to release its buffers", task.label, task.timeoutMs)
            task.timeoutLogged = true
        end
        return false
    end
    task.state, task.code = state, Memory.ReadInt(task.status + 4)
    return true
end

function sessionBrowser.awaitTask(task)
    while not sessionBrowser.pollTask(task) do
        if ShouldUnload() or scriptUnloading then
            sessionBrowser.logError("%s abandoned: unloading with a task pending", task.label)
            return false
        end
        Script.Yield(sessionBrowser.POLL_MS)
    end
    return task.state ~= nil
end

sessionBrowser.DISC_STATE_MASK = 0x3C000
sessionBrowser.DISC_ID_MASK    = 0xFFFFFFFF & ~sessionBrowser.DISC_STATE_MASK

function sessionBrowser.decodeDiscriminator(value)
    value = math.tointeger(value) or 0
    return {
        port       = value & 0xFF,
        version    = (value >> 8) & 0xF,
        build      = (value >> 12) & 0x3,
        badSport   = ((value >> 14) & 1) == 1,
        visible    = ((value >> 15) & 1) == 1,
        inProgress = ((value >> 16) & 1) == 1,
        freeAim    = ((value >> 17) & 1) == 1,
        user       = (value >> 18) & 0x3FFF,
    }
end

function sessionBrowser.discIdentity(value)
    return (math.tointeger(value) or 0) & sessionBrowser.DISC_ID_MASK
end

function sessionBrowser.discMismatch(rowDisc, selfDisc)
    local sb = sessionBrowser
    if not rowDisc or rowDisc == 0 or not selfDisc or selfDisc == 0 then return nil end
    if sb.discIdentity(rowDisc) == sb.discIdentity(selfDisc) then return nil end
    local them, us = sb.decodeDiscriminator(rowDisc), sb.decodeDiscriminator(selfDisc)
    if them.build ~= us.build then return "build" end
    if them.version ~= us.version then return "title update" end
    if them.port ~= us.port then return "port" end
    return "content"
end

function sessionBrowser.rowIncompatible(row)
    return sessionBrowser.discMismatch(row.disc, sessionBrowser.selfDisc)
end

sessionBrowser.RETAG_INTERVAL_MS = 1000
sessionBrowser.retagAt = 0

sessionBrowser.LIVE_SETTLE_SAMPLES = 3
sessionBrowser.liveSettle = { value = nil, stable = 0 }

function sessionBrowser.applyLive(row)
    local sb = sessionBrowser
    local players = math.tointeger(Natives.InvokeInt(sb.N.GET_NUM_CONNECTED_PLAYERS) or 0) or 0
    if players <= 0 or players > sb.SESSION_SLOTS then return end

    local settle = sb.liveSettle
    if settle.value ~= players then
        settle.value, settle.stable = players, 1
    elseif settle.stable < sb.LIVE_SETTLE_SAMPLES then
        settle.stable = settle.stable + 1
    end
    if settle.stable < sb.LIVE_SETTLE_SAMPLES then return end

    row.players = players
    row.seenAt = Time.GetEpoche()
    row.live = true

    local idx = math.tointeger(Natives.InvokeInt(sb.N.GET_HOST_PLAYER_INDEX) or -1) or -1
    if idx < 0 then return end
    local info = Players.GetById(idx)
    info = info and info:GetGamerInfo()
    if not info then return end
    local rid = math.tointeger(info.RockstarId or 0) or 0
    if rid > 0 then row.hostRid = rid end
    local name = info.Name
    if type(name) ~= "string" then name = Players.GetName(idx) end
    if type(name) == "string" and name ~= "" then row.hostName = name end
end

function sessionBrowser.retagOwn()
    local sb = sessionBrowser
    local total = 0
    for _, store in pairs(sb.resultStore) do total = total + #store end
    if total == 0 then return end

    if not Natives.InvokeBool(sb.N.IS_SESSION_ACTIVE) then
        sb.liveSettle.value, sb.liveSettle.stable = nil, 0
        for _, store in pairs(sb.resultStore) do
            for i = 1, #store do
                store[i].isOwn = false
                store[i].live = false
            end
        end
        return
    end

    local here = {}
    for playerId = 0, 31 do
        local player = Players.GetById(playerId)
        local info = player and player:GetGamerInfo()
        local rid = math.tointeger((info and info.RockstarId) or 0) or 0
        if rid > 0 then here[rid] = true end
    end

    local best, bestScore = nil, 0
    for _, rows in pairs(sb.resultStore) do
        for i = 1, #rows do
            local row = rows[i]
            row.isOwn = false
            row.live = false
            local score = (row.hostRid and here[row.hostRid]) and 2 or 0
            if row.members then
                for _, rid in ipairs(row.members) do
                    if here[rid] then score = score + 1 end
                end
            end
            if score > bestScore then best, bestScore = row, score end
        end
    end
    if bestScore >= 2 then
        best.isOwn = true
        sb.applyLive(best)
        sb.noteSelfDisc(best.disc)

        if best.hostRid and best.hostRid ~= 0 then
            for _, rows in pairs(sb.resultStore) do
                for i = 1, #rows do
                    local row = rows[i]
                    if row ~= best and not row.twinLogged
                            and row.hostRid == best.hostRid then
                        row.twinLogged = true
                        sb.logError("Twin row for the session we are in: host=%s "
                            .. "rid=%d | twin token=0x%X id=%s players=%s vs "
                            .. "winner token=0x%X id=%s players=%s",
                            tostring(best.hostName), best.hostRid,
                            row.token or 0, tostring(row.sessionId),
                            tostring(row.players), best.token or 0,
                            tostring(best.sessionId), tostring(best.players))
                    end
                end
            end
        end
    end
end

CENTRAL_TICK.single[#CENTRAL_TICK.single + 1] = { fn = function()
    local sb = sessionBrowser
    if not sb.supported then return end
    local now = Time.GetEpocheMs()
    if now < sb.retagAt then return end
    sb.retagAt = now + sb.RETAG_INTERVAL_MS
    sb.retagOwn()
end }

sessionBrowser.countryRenderMode = false

function sessionBrowser.rowCountryMatches(row)
    local map = countryFinder.byRid
    if not map then return nil end
    local seen, ccOrder, ccCount, n = {}, {}, {}, 0
    local function consider(rid)
        rid = math.tointeger(rid or 0) or 0
        if rid <= 0 or seen[rid] then return end
        seen[rid] = true
        local cc = map[rid]
        if cc then
            n = n + 1
            if ccCount[cc] then
                ccCount[cc] = ccCount[cc] + 1
            else
                ccCount[cc] = 1
                ccOrder[#ccOrder + 1] = cc
            end
        end
    end
    consider(row.hostRid)
    if row.members then
        for _, rid in ipairs(row.members) do consider(rid) end
    end
    if n == 0 then return nil end
    table.sort(ccOrder, function(a, b) return ccCount[a] > ccCount[b] end)
    return { n = n, ccs = ccOrder }
end

function sessionBrowser.noteSelfDisc(disc)
    local sb = sessionBrowser
    disc = math.tointeger(disc)
    if not disc or disc == 0 then return end
    local id = sb.discIdentity(disc)
    if sb.selfDisc and sb.discIdentity(sb.selfDisc) == id then return end
    sb.selfDisc = disc
    local d = sb.decodeDiscriminator(disc)
    sb.log("Own pool identity: 0x%08X (build %d, title update %d, port 0x%02X, "
        .. "content 0x%04X)", id, d.build, d.version, d.port, d.user)
end

sessionBrowser.JOIN_CONFIRM_MS = 90000
sessionBrowser.JOIN_CONFIRM_POLL_MS = 500

function sessionBrowser.confirmJoinedDisc(rid, disc)
    local sb = sessionBrowser
    if not rid or not disc or disc == 0 then return end
    if sb.discIdentity(disc) == sb.discIdentity(sb.selfDisc or 0) then return end

    Script.QueueJob(function()
        local deadline = Time.GetEpocheMs() + sb.JOIN_CONFIRM_MS
        while Time.GetEpocheMs() < deadline do
            if ShouldUnload() or scriptUnloading then return end
            Script.Yield(sb.JOIN_CONFIRM_POLL_MS)
            if Natives.InvokeBool(sb.N.IS_SESSION_ACTIVE)
                    and not Natives.InvokeBool(sb.N.IS_IN_TRANSITION) then
                for playerId = 0, 31 do
                    local player = Players.GetById(playerId)
                    local info = player and player:GetGamerInfo()
                    if math.tointeger((info and info.RockstarId) or 0) == rid then
                        sb.noteSelfDisc(disc)
                        return
                    end
                end
            end
        end
        sb.log("Join confirmation timed out for RID %d; identity not adopted", rid)
    end)
end

function sessionBrowser.readHostNat(info)
    local nat = math.tointeger(Memory.ReadInt(info + sessionBrowser.SI_HOST_NAT))
    if not nat or nat < 0 or nat > 3 then return nil end
    return nat
end

function sessionBrowser.looksLikeFreeroamBlob(blob, layout)
    local noProp = 0
    for i = 0, 31 do
        if Memory.ReadUByte(blob + layout.propIds + i) == 0xFF then
            noProp = noProp + 1
        end
    end
    return noProp >= 4, noProp
end

function sessionBrowser.findUserData(detailBase, cal)
    local sb = sessionBrowser
    if sb.udOffset then return sb.udOffset end

    local candidates = {}
    if cal and cal.privSlots then
        candidates[#candidates + 1] = { cal.privSlots + sb.UD_SIZE_FROM_PRIV, "privSlots" }
    end
    candidates[#candidates + 1] =
        { sb.SESSION_DETAIL_SIZE - sb.UD_TAIL_BYTES, "detail tail" }

    local known = false
    for _, c in ipairs(candidates) do
        local off, why = c[1], c[2]
        local size = Memory.ReadUShort(detailBase + off)
        if size == sb.UD_SIZE_ACTIVITY then known = true end
        local layout = size and sb.UD_LAYOUT[size]
        if layout then
            local ok, noProp = sb.looksLikeFreeroamBlob(detailBase + off + 2, layout)
            if ok then
                sb.udOffset = off
                sb.log("Session user data located via %s at +0x%X "
                    .. "(size=0x%X, %d/32 property slots empty)", why, off, size, noProp)
                return off
            end
        end
    end
    return nil, known
end

function sessionBrowser.readUserData(detailBase, cal)
    local sb = sessionBrowser
    local off, known = sb.findUserData(detailBase, cal)
    if not off then
        if not known then sb.diagUserData(detailBase, cal) end
        return nil
    end

    local size = Memory.ReadUShort(detailBase + off)
    local layout = size and sb.UD_LAYOUT[size]
    if not layout then return nil end

    local blob = detailBase + off + 2
    if not sb.looksLikeFreeroamBlob(blob, layout) then return nil end

    local out = {}
    local bosses = Memory.ReadUByte(blob + layout.numBosses)
    if bosses and bosses >= 0 and bosses <= sb.SESSION_SLOTS then
        out.bosses = bosses
    end
    local away = Memory.ReadUByte(blob + layout.transition)
    if away and away >= 0 and away <= sb.SESSION_SLOTS then
        out.transitionPlayers = away
    end
    local flags = Memory.ReadUByte(blob + layout.flags) or 0
    out.closedFriends = (flags & sb.UD_FLAG_CLOSED_FRIENDS) ~= 0
    out.crewSession = (flags & sb.UD_FLAG_CLOSED_CREW) ~= 0
    if layout.hostFlags then
        out.hostFlags = Memory.ReadInt(blob + layout.hostFlags)
        if out.hostFlags ~= nil then out.closedCrew = (out.hostFlags & 0x20) ~= 0 end
    else
        out.closedCrew = out.crewSession
    end
    return out
end

function sessionBrowser.diagUserData(detailBase, cal)
    local sb = sessionBrowser
    sb.udDiagLeft = sb.udDiagLeft or 3
    if sb.udDiagLeft <= 0 then return end
    sb.udDiagLeft = sb.udDiagLeft - 1

    local tailOff = sb.SESSION_DETAIL_SIZE - sb.UD_TAIL_BYTES
    local privOff = cal and cal.privSlots and (cal.privSlots + sb.UD_SIZE_FROM_PRIV)
    sb.logError("Session user data NOT located. privSlots=+0x%X -> size u16=%s | "
        .. "detail tail +0x%X -> size u16=%s",
        cal and cal.privSlots or -1,
        privOff and tostring(Memory.ReadUShort(detailBase + privOff)) or "n/a",
        tailOff, tostring(Memory.ReadUShort(detailBase + tailOff)))

    local from = math.min(privOff or tailOff, tailOff) - 0x10
    if from < 0 then from = 0 end
    for line = 0, 5 do
        local at = from + line * 16
        if at + 16 > sb.SESSION_DETAIL_SIZE then break end
        local parts = {}
        for i = 0, 15 do
            parts[#parts + 1] = ("%02X"):format(Memory.ReadUByte(detailBase + at + i) or 0)
        end
        sb.logError("  +0x%03X  %s", at, table.concat(parts, " "))
    end
end

function sessionBrowser.getBossLimit()
    local sb = sessionBrowser
    if sb.bossLimit then return sb.bossLimit end

    local slot = sb.BOSS_LIMIT_GLOBAL[IS_ENHANCED and "enh" or "leg"]
    if not slot then return nil end

    local v = math.tointeger(ScriptGlobal.GetInt(slot))
    if v and v > 0 and v <= sb.SESSION_SLOTS then
        sb.bossLimit = v
        sb.log("Freemode organisation limit = %d (global %d)", v, slot)
        return v
    end
    return nil
end

function sessionBrowser.bossLimitForDisplay()
    return sessionBrowser.bossLimit
end


function sessionBrowser.rememberRid(rid, name, src, lastSeen)
    rid = math.tointeger(rid)
    if not rid or rid <= 0 then return false end

    src = src or "own"
    lastSeen = math.tointeger(lastSeen or 0) or 0
    if lastSeen <= 0 and src ~= "tracker" then lastSeen = Time.GetEpoche() end

    local entry = sessionBrowser.known[rid]
    if entry then
        if name and name ~= "" and name ~= entry.name then entry.name = name end
        if lastSeen > (entry.lastSeen or 0) then entry.lastSeen = lastSeen end
        if src == "own" then
            if entry.src ~= "own" then
                sessionBrowser.knownOwn = sessionBrowser.knownOwn + 1
                sessionBrowser.knownTracker = sessionBrowser.knownTracker - 1
            end
            entry.src = "own"
            sessionBrowser.knownDirty = true
        end
        return false
    end

    sessionBrowser.known[rid] =
        { rid = rid, name = name or "", lastSeen = lastSeen, src = src }
    if src == "own" then
        sessionBrowser.knownOwn = sessionBrowser.knownOwn + 1
        sessionBrowser.knownDirty = true
    else
        sessionBrowser.knownTracker = sessionBrowser.knownTracker + 1
    end
    return true
end

function sessionBrowser.loadRidsFrom(path)
    if not FileMgr.DoesFileExist(path) then return 0 end
    local content = FileMgr.ReadFileContent(path)
    if not content then return 0 end

    local loaded = 0
    for line in tostring(content):gmatch("[^\r\n]+") do
        local rid, name, seen = line:match("^(%d+),([^,]*),(%d+)$")
        if rid then
            rid = math.tointeger(rid)
            if rid and rid > 0 and not sessionBrowser.known[rid] then
                sessionBrowser.known[rid] = {
                    rid = rid,
                    name = name or "",
                    lastSeen = math.tointeger(seen) or 0,
                    src = "own",
                }
                sessionBrowser.knownOwn = sessionBrowser.knownOwn + 1
                loaded = loaded + 1
            end
        end
    end
    return loaded
end

function sessionBrowser.loadRids()
    local loaded = sessionBrowser.loadRidsFrom(sessionBrowser.PATH_RIDS)
    local migrated = sessionBrowser.loadRidsFrom(sessionBrowser.PATH_RIDS_LEGACY)
    if migrated > 0 then sessionBrowser.knownDirty = true end
    sessionBrowser.log("Loaded %d known RIDs (%d migrated)", loaded + migrated, migrated)
    return loaded + migrated
end

function sessionBrowser.saveRids()
    if not sessionBrowser.knownDirty then return end

    local rows = {}
    for _, entry in pairs(sessionBrowser.known) do
        if entry.src == "own" then
            local name = tostring(entry.name or ""):gsub("[,\r\n]", " ")
            rows[#rows + 1] = ("%d,%s,%d"):format(entry.rid, name, entry.lastSeen or 0)
        end
    end
    table.sort(rows)

    local ok = FileMgr.WriteFileContent(sessionBrowser.PATH_RIDS,
        table.concat(rows, "\n"), false)
    if ok then
        sessionBrowser.knownDirty = false
        sessionBrowser.log("Saved %d known RIDs", #rows)
    else
        sessionBrowser.logError("Failed to write %s", sessionBrowser.PATH_RIDS)
    end
end

function sessionBrowser.parseTracker(content)
    local keys = {}
    local pos = 1
    while true do
        local keyStart, keyEnd, rid = content:find('"(%d+)"%s*:%s*{', pos)
        if not keyStart then break end
        keys[#keys + 1] = { rid = rid, from = keyEnd + 1, keyStart = keyStart }
        pos = keyEnd + 1
    end

    local records = {}
    for i = 1, #keys do
        local stop = keys[i + 1] and (keys[i + 1].keyStart - 1) or #content
        local slice = content:sub(keys[i].from, stop)
        records[#records + 1] = {
            rid = keys[i].rid,
            name = slice:match('"name"%s*:%s*"([^"]*)"'),
            lastSeen = slice:match('"last_seen"%s*:%s*(%d+)'),
            ip = slice:match('"ip"%s*:%s*"([^"]*)"'),
        }
    end
    return records
end

function sessionBrowser.importTracker()
    local totalAdded, totalSeen = 0, 0
    local summary = {}

    for _, source in ipairs(sessionBrowser.trackerFiles) do
        if source.enabled then
            local path = sessionBrowser.PATH_TRACKER .. "\\" .. source.file
            local content = FileMgr.DoesFileExist(path)
                and FileMgr.ReadFileContent(path) or nil
            if not content or content == "" then
                summary[#summary + 1] = source.label .. "=missing"
            else
                local records = sessionBrowser.parseTracker(tostring(content))
                local added = 0
                for _, record in ipairs(records) do
                    local rid = math.tointeger(record.rid)
                    if sessionBrowser.rememberRid(rid, record.name, "tracker",
                            record.lastSeen) then
                        added = added + 1
                    end
                end
                totalAdded = totalAdded + added
                totalSeen = totalSeen + #records
                summary[#summary + 1] = ("%s=%d/%d"):format(source.label, added, #records)
            end
        end
    end

    sessionBrowser.log("PlayerTracker import: %d new from %d records (%s)",
        totalAdded, totalSeen, table.concat(summary, " "))
    return totalAdded, totalSeen
end

function sessionBrowser.localRid()
    local player = Players.GetById(GTA.GetLocalPlayerId())
    local info = player and player:GetGamerInfo()
    local rid = info and math.tointeger(info.RockstarId or 0) or nil
    if rid and rid > 0 then return rid end
    return nil
end

function sessionBrowser.sessionRids(excludeRid)
    local out = {}
    for playerId = 0, 31 do
        if #out >= sessionBrowser.MAX_BATCH then break end
        local player = Players.GetById(playerId)
        local info = player and player:GetGamerInfo()
        local rid = math.tointeger((info and info.RockstarId) or 0) or 0
        if rid > 0 and rid ~= excludeRid then out[#out + 1] = rid end
    end
    return out
end

function sessionBrowser.harvestSession()
    local added = 0
    for playerId = 0, 31 do
        local player = Players.GetById(playerId)
        if player then
            local info = player:GetGamerInfo()
            local rid = info and math.tointeger(info.RockstarId or 0) or nil
            if rid and rid > 0 then
                local name = info.Name
                if type(name) ~= "string" then name = Players.GetName(playerId) end
                if sessionBrowser.rememberRid(rid, name) then added = added + 1 end
            end
        end
    end
    return added
end

function sessionBrowser.harvestFriends()
    local count = Natives.InvokeInt(sessionBrowser.N.GET_FRIEND_COUNT) or 0
    local added, online = 0, 0

    for i = 0, count - 1 do
        local buffer = GamerHandleBuffer.New()
        if buffer then
            Natives.InvokeVoid(sessionBrowser.N.HANDLE_FROM_FRIEND, i,
                buffer:GetBuffer(), sessionBrowser.SCRIPT_GAMER_HANDLE_WORDS)
            local handle = buffer:ToHandle()
            if handle and handle:IsValid() then
                local rid = math.tointeger(handle.RockstarId or 0)
                if rid and rid > 0 then
                    local name = Natives.InvokeString(sessionBrowser.N.GET_FRIEND_NAME, i)
                    if sessionBrowser.rememberRid(rid, name) then added = added + 1 end
                    if Natives.InvokeBool(sessionBrowser.N.IS_FRIEND_INDEX_ONLINE, i) then
                        online = online + 1
                    end
                end
            end
        end
    end

    sessionBrowser.log("Friends harvested: total=%d new=%d online=%d", count, added, online)
    return added, count, online
end

function sessionBrowser.buildScanList(limit)
    local sb = sessionBrowser
    local discovery = sb.localDiscovery
    local list = {}
    for _, entry in pairs(sb.known) do list[#list + 1] = entry end
    table.sort(list, function(a, b)
        if limit then
            local aa = discovery.attempted[a.rid] or 0
            local bb = discovery.attempted[b.rid] or 0
            if aa ~= bb then return aa < bb end
        end
        if a.lastSeen ~= b.lastSeen then return a.lastSeen > b.lastSeen end
        return a.rid < b.rid
    end)
    if not limit then return list end

    limit = math.max(1, math.tointeger(limit) or #list)
    discovery.pass = discovery.pass + 1
    local out = {}
    for i = 1, math.min(limit, #list) do
        local entry = list[i]
        out[#out + 1] = entry
        discovery.attempted[entry.rid] = discovery.pass
    end
    return out
end

function sessionBrowser.touchLiveRid(rid, seenAt)
    rid = math.tointeger(rid or 0)
    local entry = rid and sessionBrowser.known[rid] or nil
    if not entry then return false end
    seenAt = math.tointeger(seenAt or Time.GetEpoche()) or 0
    if seenAt <= (entry.lastSeen or 0) then return false end
    entry.lastSeen = seenAt
    if entry.src == "own" then sessionBrowser.knownDirty = true end
    return true
end

function sessionBrowser.knownCounts()
    return sessionBrowser.knownOwn, sessionBrowser.knownTracker
end

function sessionBrowser.ensureInit()
    if sessionBrowser.booted then return end
    sessionBrowser.booted = true
    if not sessionBrowser.supported then return end
    sessionBrowser.loadRids()
    sessionBrowser.importTracker()
end


function sessionBrowser.presenceSubmit(rids, pbuf)
    local sb = sessionBrowser
    local addr = sb.addr
    local buf = pbuf or sb.buf
    local n = #rids
    if n == 0 then return nil end

    sb.zeroBlock(buf.handles, n * sb.GAMER_HANDLE_SIZE)
    for i = 1, n do
        local base = buf.handles + (i - 1) * sb.GAMER_HANDLE_SIZE
        Memory.WriteLong(base, rids[i])
        Memory.WriteByte(base + 8, sb.RL_SERVICE_SC)
    end

    if sb.verbose then
        local echoed = {}
        for i = 1, n do
            local base = buf.handles + (i - 1) * sb.GAMER_HANDLE_SIZE
            echoed[#echoed + 1] = ("%s(%s)->%d/svc%d"):format(
                tostring(rids[i]), math.type(rids[i]) or type(rids[i]),
                Memory.ReadLong(base), Memory.ReadUByte(base + 8))
        end
        sb.log("Presence submitting %d: %s", n, table.concat(echoed, " "))
        sb.log("Presence handle[0] bytes: %s", sb.hexDump(buf.handles, 16))
    end

    sb.zeroBlock(buf.queryData, n * sb.QUERY_DATA_SIZE)
    Memory.WriteInt(buf.resultCount, 0)
    sb.zeroBlock(buf.status, sb.NET_STATUS_SIZE)

    Memory.LuaCallCFunction(addr.presence,
        0, buf.handles, n, buf.queryData, n, buf.resultCount, buf.status)

    return {
        status = buf.status, started = Time.GetEpocheMs(),
        timeoutMs = 20000, label = "presence resolve", n = n,
        buf = buf,
    }
end

function sessionBrowser.presenceCollect(task)
    if scriptUnloading or ShouldUnload() then return {} end
    local sb = sessionBrowser
    local buf = task.buf or sb.buf
    local n = task.n
    local state, code = task.state, task.code
    if state == nil then return {} end

    local resolved = Memory.ReadInt(buf.resultCount) or 0
    if resolved < 0 or resolved > n then
        sb.logError("Rejecting invalid presence result count %d for %d handles", resolved, n)
        return {}
    end
    if state ~= sb.NET_STATUS_SUCCEEDED then
        sb.logError("Presence resolve failed: state=%d code=%d count=%d",
            state, code, resolved)
        return {}
    end
    sb.log("Presence resolve: requested=%d resolved=%d state=%d code=%d",
        n, resolved, state, code)

    if resolved == 0 then
        local echoed, withSession = 0, 0
        for i = 0, n - 1 do
            local entry = buf.queryData + i * sb.QUERY_DATA_SIZE
            if Memory.ReadLong(entry + sb.QD_HANDLE) ~= 0 then
                echoed = echoed + 1
            end
            if Memory.ReadLong(entry + sb.QD_SESSION_INFO + sb.SI_SESSION_ID) ~= 0 then
                withSession = withSession + 1
            end
        end

        if withSession > 0 then
            sb.logError("Presence reported count=0 but %d slots carry a real "
                .. "session id; the result-count pointer is being misread", withSession)
            sb.log("Presence result[0] bytes: %s", sb.hexDump(buf.queryData, 48))
        elseif echoed == n then
            sb.presenceProven = true
            sb.log("Presence OK: all %d gamer handle(s) echoed back with every "
                .. "session info empty - the call is correct and none of those "
                .. "accounts is in a session presence advertises (offline, out "
                .. "of session, or solo)", n)
        elseif sb.verbose then
            sb.logError("Presence wrote back only %d of %d gamer handles (empty "
                .. "batch, or the call is not reaching the result array)", echoed, n)
            sb.log("Presence result[0] bytes: %s", sb.hexDump(buf.queryData, 48))
        end
    else
        sb.presenceProven = true
    end

    local out = {}
    for i = 0, resolved - 1 do
        local entry = buf.queryData + i * sb.QUERY_DATA_SIZE
        local info = entry + sb.QD_SESSION_INFO
        if Memory.ReadLong(info + sb.SI_SESSION_ID) ~= 0 then
            out[#out + 1] = {
                viaRid    = Memory.ReadLong(entry + sb.QD_HANDLE),
                info      = info,
                sessionId = Memory.ReadLong(info + sb.SI_SESSION_ID),
                token     = Memory.ReadLong(info + sb.SI_TOKEN),
                hostRid   = Memory.ReadLong(info + sb.SI_HOST_RID),
            }
        end
    end
    return out
end

function sessionBrowser.resolveBatch(rids, pbuf)
    local task = sessionBrowser.presenceSubmit(rids, pbuf)
    if not task then return {} end
    if not sessionBrowser.awaitTask(task) then return {} end
    return sessionBrowser.presenceCollect(task)
end


function sessionBrowser.sanityCheckBody()
    local sb = sessionBrowser
    local fails, checks = 0, 0
    local function check(ok, fmt, ...)
        checks = checks + 1
        if not ok then fails = fails + 1 end
        sb.log("  [%s] " .. fmt, ok and "PASS" or "FAIL", ...)
    end

    sb.log("---- sanity check begin ----")
    if not Natives.InvokeBool(sb.N.IS_SESSION_ACTIVE) then
        sb.toast(T("Sanity check needs you in an online session."), 7000)
        return
    end
    if sb.state.busy or sb.joinBusy then
        sb.toast(T("Sanity check: a scan is running, try again when it finishes."), 7000)
        return
    end
    if not sb.resolveAddresses() or not sb.allocBuffers() then
        sb.toast(T("Sanity check: addresses/buffers unavailable. See log."), 8000)
        return
    end

    local localRid = sb.localRid()
    if not localRid then
        sb.toast(T("Sanity check: your own RID is unreadable. See log."), 8000)
        return
    end

    local solo = Natives.InvokeBool(sb.N.SESSION_IS_SOLO)
    local priv = Natives.InvokeBool(sb.N.SESSION_IS_PRIVATE)
    local closedF = Natives.InvokeBool(sb.N.SESSION_IS_CLOSED_FRIENDS)
    local closedC = Natives.InvokeBool(sb.N.SESSION_IS_CLOSED_CREW)
    local visible = Natives.InvokeBool(sb.N.SESSION_IS_VISIBLE)
    sb.log("  session: solo=%s private=%s closedFriends=%s closedCrew=%s visible=%s "
        .. "inTransition=%s activity=%s", tostring(solo), tostring(priv),
        tostring(closedF), tostring(closedC), tostring(visible),
        tostring(Natives.InvokeBool(sb.N.IS_IN_TRANSITION)),
        tostring(Natives.InvokeBool(sb.N.IS_ACTIVITY_SESSION)))

    local mates = sb.sessionRids(localRid)
    local mine = sb.resolveBatch({ localRid })
    local from = "your own RID"
    if #mine == 0 and #mates > 0 then
        sb.log("  own RID resolved nothing; trying %d session-mate(s)", #mates)
        mine = sb.resolveBatch(mates)
        from = ("%d session-mate(s)"):format(#mates)
    end
    check(#mine >= 1, "presence resolved %s -> %d session(s)", from, #mine)

    if #mine == 0 then
        local why
        if solo or priv then
            why = "this is a solo session (1 private slot, 0 public). rage does not "
                .. "publish a single-player private session's info to presence at "
                .. "all, so nothing can resolve it."
        elseif #mates == 0 then
            why = "you are the only player here and presence is carrying no session "
                .. "for you yet."
        elseif not visible then
            why = "this session is not visible to matchmaking, so presence is not "
                .. "advertising it."
        else
            why = ("neither you nor %d other player(s) in this lobby resolve, so "
                .. "presence is not carrying this session"):format(#mates)
                .. (closedF and " (closed friends)" or closedC and " (closed crew)" or "")
                .. "."
        end
        sb.log("  presence advertises no session for this lobby: %s", why)
        sb.log("---- sanity check end: could not run ----")
        sb.toast(T("Sanity check could not run: %s Run it from a public lobby."):format(why), 15000)
        return
    end

    sb.cal = nil
    sb.udOffset = nil
    local task = sb.detailSubmit({ mine[1] })
    if not task or not sb.awaitTask(task) then
        sb.log("  own session cannot be queried: rage strips a session we are "
            .. "already in from QueryDetail, so the checks below have no row to run "
            .. "against. Not a decode fault.")
        sb.toast(T("Sanity check stops here: the game refuses a detail query for a session you are in, so your current lobby cannot be measured. Presence resolved fine."), 12000)
        return
    end
    local rows = sb.detailCollect(task)
    check(#rows == 1, "your own host answered QueryDetail -> %d row(s)", #rows)
    if #rows ~= 1 then
        sb.toast(T("Sanity check FAILED at QueryDetail. See log."), 9000)
        return
    end
    local row = rows[1]
    local cal = sb.cal
    sb.log("  offsets: sessionInfo=+0x%X hostHandle=+0x%X hostName=+0x%X nameSpan=%d "
        .. "pub=+0x%X priv=+0x%X attrIds=%s userData=%s",
        cal.sessionInfo, cal.hostHandle, cal.hostName, cal.nameSpan, cal.pubSlots,
        cal.privSlots, cal.attrIds and ("+0x%X"):format(cal.attrIds) or "none",
        sb.udOffset and ("+0x%X"):format(sb.udOffset) or "none")

    local connected = Natives.InvokeInt(sb.N.GET_NUM_CONNECTED_PLAYERS) or 0
    check(math.abs(row.players - connected) <= 1,
        "player count: QueryDetail %d (%d public + %d private) vs the game's %d",
        row.players, row.publicSlots, row.privateSlots, connected)

    check(row.maxPlayers == sb.SESSION_SLOTS,
        "capacity: %s advertised (expected %d)",
        tostring(row.maxPlayers), sb.SESSION_SLOTS)

    local hostIdx = Natives.InvokeInt(sb.N.GET_HOST_PLAYER_INDEX)
    local hostPlayer = hostIdx and hostIdx >= 0 and Players.GetById(hostIdx)
    local hostInfo = hostPlayer and hostPlayer:GetGamerInfo()
    local trueHost = hostInfo and math.tointeger(hostInfo.RockstarId or 0) or nil
    if trueHost and trueHost > 0 then
        check(row.hostRid == trueHost, "host RID: decoded %s, game says %s (%s)",
            tostring(row.hostRid), tostring(trueHost), tostring(row.hostName))
    else
        sb.log("  [skip] host RID: the game did not report a host player index")
    end

    check(row.purpose == sb.SP_FREEROAM and row.gameMode == sb.GAMEMODE_FREEROAM
        and not row.isJob,
        "classified as freeroam: purpose=%s gameMode=%s activity=%s/%s isJob=%s",
        tostring(row.purpose), tostring(row.gameMode), tostring(row.activityType),
        tostring(row.activityId), tostring(row.isJob))

    check(row.bosses ~= nil, "freemode user data decoded (bosses=%s, away in jobs=%s, "
        .. "closed friends=%s, closed crew=%s)", tostring(row.bosses),
        tostring(row.awayInJobs), tostring(row.closedFriends), tostring(row.closedCrew))
    if row.awayInJobs then
        check(row.awayInJobs <= row.players,
            "away-in-jobs %d fits inside the %d in the session", row.awayInJobs, row.players)
    end

    if row.visible == nil then
        check(false, "visible bit: not decoded (no discriminator)")
    elseif row.visible == visible then
        check(true, "visible bit: decoded %s, game agrees", tostring(row.visible))
    else
        sb.log("  [warn] visible bit: decoded %s but the game says %s - expected "
            .. "while session attributes are locked, suspicious otherwise",
            tostring(row.visible), tostring(visible))
    end
    sb.log("  closed: %s (friends=%s crew=%s)",
        tostring(sb.rowIsClosed(row)), tostring(row.closedFriends),
        tostring(row.closedCrew))

    check(row.region ~= nil and row.freeAim ~= nil,
        "region/aim decoded: region=%s (%s) freeAim=%s", tostring(row.region),
        row.region and (sb.REGION_NAME[row.region] or "?") or "?", tostring(row.freeAim))

    sb.log("---- sanity check end: %d of %d passed ----", checks - fails, checks)
    if fails == 0 then
        sb.toast((T("Sanity check PASSED (%d/%d). Counts, host, purpose and the freemode blob all agree with the game.")):format(checks, checks), 10000)
    else
        sb.toast((T("Sanity check: %d of %d checks FAILED - see the log. Recalibrate and run it again.")):format(fails, checks), 12000)
    end
end

function sessionBrowser.sanityCheck()
    local prev = sessionBrowser.verbose
    sessionBrowser.verbose = true
    sessionBrowser.sanityCheckBody()
    sessionBrowser.verbose = prev
end


function sessionBrowser.findAttrs(detailBase, sessionInfoOff)
    local sb = sessionBrowser
    local from = sessionInfoOff + sb.SESSION_INFO_SIZE
    local to = sb.SESSION_DETAIL_SIZE - sb.MM_IDS_TO_MASK - 4
    for off = from, to, 4 do
        if Memory.ReadInt(detailBase + off) == sb.MM_ATTR.DISCRIMINATOR then
            local attrs = off - sb.MM_ATTRS_TO_IDS
            local count = Memory.ReadInt(detailBase + attrs + 4)
            local maxPub = Memory.ReadInt(detailBase + attrs + sb.SC_ATTRS_TO_MAXPUB)
            local maxPriv = Memory.ReadInt(detailBase + attrs + sb.SC_ATTRS_TO_MAXPRIV)
            if count >= 1 and count <= sb.MM_MAX_ATTRS
                    and maxPub >= 1 and maxPub <= 32
                    and maxPriv >= 0 and maxPriv <= 32
                    and (maxPub + maxPriv) <= 32 then
                return {
                    ids       = off,
                    count     = count,
                    maxPub    = attrs + sb.SC_ATTRS_TO_MAXPUB,
                    maxPriv   = attrs + sb.SC_ATTRS_TO_MAXPRIV,
                    configEnd = attrs + sb.SC_ATTRS_TO_END,
                }
            end
        end
    end
    return nil
end

function sessionBrowser.readAttrs(detailBase, cal)
    if not cal.attrIds then return nil end
    local out = {}
    for i = 0, cal.attrCount - 1 do
        local id = Memory.ReadInt(detailBase + cal.attrIds + i * 4)
        if id ~= 0 then
            out[id] = Memory.ReadInt(detailBase + cal.attrIds
                + sessionBrowser.MM_IDS_TO_VALS + i * 4)
        end
    end
    return out
end

function sessionBrowser.rowIsClosed(row)
    if row.visible == false then return true end
    return row.closedFriends == true or row.closedCrew == true or row.crewSession == true
end

function sessionBrowser.closedLabel(row)
    if row.closedFriends then return T("Friends only") end
    if row.closedCrew then return T("Closed Crew Session") end
    if row.crewSession then return T("Crew Session") end
    if row.visible == false then return T("Closed / private") end
    return nil
end

function sessionBrowser.rowIsJob(row)
    local sb = sessionBrowser
    if row.purpose ~= nil and row.purpose ~= sb.SP_FREEROAM then return true end
    if row.gameMode ~= nil and row.gameMode ~= sb.GAMEMODE_FREEROAM then return true end
    if (row.activityType or 0) ~= 0 or (row.activityId or 0) ~= 0 then return true end
    return false
end

function sessionBrowser.decodeRow(base, cal)
    local sb = sessionBrowser
    local info = base + cal.sessionInfo
    local pub = Memory.ReadInt(base + cal.pubSlots)
    local priv = Memory.ReadInt(base + cal.privSlots)
    local row = {
        token        = Memory.ReadLong(info + sb.SI_TOKEN),
        sessionId    = Memory.ReadLong(info + sb.SI_SESSION_ID),
        hostRid      = Memory.ReadLong(base + cal.hostHandle),
        hostName     = sb.readAsciiz(base + cal.hostName, 17) or "?",
        publicSlots  = pub,
        privateSlots = priv,
        players      = pub,
        seenAt       = Time.GetEpoche(),
        natType      = sb.readHostNat(info),
    }

    if cal.maxPubSlots then
        row.maxPublic = Memory.ReadInt(base + cal.maxPubSlots)
        row.maxPrivate = Memory.ReadInt(base + cal.maxPrivSlots)
        row.maxPlayers = row.maxPublic + row.maxPrivate
    end

    if cal.attrIds then
        local mode = Memory.ReadUShort(base + cal.attrIds + sb.MM_IDS_TO_GAMEMODE)
        local purpose = Memory.ReadUShort(base + cal.attrIds + sb.MM_IDS_TO_PURPOSE)
        if mode and mode <= 0xFF then row.gameMode = mode end
        if purpose and purpose <= sb.SP_MAX then row.purpose = purpose end
    end

    local attrs = sb.readAttrs(base, cal)
    if attrs then
        row.region = attrs[sb.MM_ATTR.REGION]
        local disc = attrs[sb.MM_ATTR.DISCRIMINATOR]
        if disc then
            row.disc = disc & 0xFFFFFFFF
            local bits = sb.decodeDiscriminator(disc)
            row.visible = bits.visible
            row.badSport = bits.badSport
            row.inProgress = bits.inProgress
            row.freeAim = bits.freeAim
        end
        local aim = attrs[sb.MM_ATTR.AIM_TYPE]
        if aim then row.freeAim = aim ~= 0 end
        row.activityType = attrs[sb.MM_ATTR.ACTIVITY_TYPE]
        row.activityId = attrs[sb.MM_ATTR.ACTIVITY_ID]
    end

    local ud = sb.readUserData(base, cal)
    if ud then
        row.bosses = ud.bosses
        row.awayInJobs = ud.transitionPlayers
        row.closedFriends = ud.closedFriends
        row.closedCrew = ud.closedCrew
        row.crewSession = ud.crewSession
        row.hostFlags = ud.hostFlags
    end

    row.isJob = sb.rowIsJob(row)
    return row
end

function sessionBrowser.identity(s)
    local id = s.sessionId
    if id and id ~= 0 then return id end
    return s.token
end

function sessionBrowser.calibrate(detailBase, expectedTokens)
    local sb = sessionBrowser

    local sessionInfoOff
    for off = 0, sb.SESSION_DETAIL_SIZE - 8, 4 do
        local value = Memory.ReadLong(detailBase + off)
        if value ~= 0 and expectedTokens[value] then
            sessionInfoOff = off - sb.SI_TOKEN
            break
        end
    end
    if not sessionInfoOff or sessionInfoOff < 0 then
        return nil, "could not locate m_SessionInfo (no submitted token matched)"
    end

    local hostRid = Memory.ReadLong(detailBase + sessionInfoOff + sb.SI_HOST_RID)
    if hostRid == 0 then
        return nil, "embedded m_SessionInfo carries no host RID to anchor on"
    end

    local cfg = sb.findAttrs(detailBase, sessionInfoOff)
    local searchFrom
    if cfg then
        searchFrom = cfg.configEnd
    else
        searchFrom = sessionInfoOff + sb.SESSION_INFO_SIZE
        sb.log("rlSessionConfig not located: falling back to an unanchored "
            .. "m_HostHandle search; slot counts from this calibration are suspect")
    end

    local candidates = 0
    local lastReason = "no copy of the host RID after rlSessionConfig"

    for off = searchFrom, sb.SESSION_DETAIL_SIZE - 8, 4 do
        if Memory.ReadLong(detailBase + off) == hostRid then
            candidates = candidates + 1

            local nameOff = off + sb.GAMER_HANDLE_SIZE
            local hostName = sb.readAsciiz(detailBase + nameOff, 17)
            if not hostName then
                lastReason = ("candidate +0x%X: m_HostName is not printable ASCII")
                    :format(off)
            else
                for _, nameSpan in ipairs({ 20, 16 }) do
                    local pubOff = nameOff + nameSpan
                    local privOff = pubOff + 4
                    if privOff + 4 <= sb.SESSION_DETAIL_SIZE then
                        local pub = Memory.ReadInt(detailBase + pubOff)
                        local priv = Memory.ReadInt(detailBase + privOff)
                        local maxPub = cfg and Memory.ReadInt(detailBase + cfg.maxPub) or 32
                        local maxPriv = cfg and Memory.ReadInt(detailBase + cfg.maxPriv) or 32
                        if pub >= 0 and pub <= maxPub and priv >= 0 and priv <= maxPriv
                                and (pub + priv) >= 1 then
                            local cal = {
                                sessionInfo  = sessionInfoOff,
                                hostHandle   = off,
                                hostName     = nameOff,
                                nameSpan     = nameSpan,
                                pubSlots     = pubOff,
                                privSlots    = privOff,
                                attrIds      = cfg and cfg.ids or nil,
                                attrCount    = cfg and cfg.count or nil,
                                maxPubSlots  = cfg and cfg.maxPub or nil,
                                maxPrivSlots = cfg and cfg.maxPriv or nil,
                            }
                            sb.log("Calibrated rlSessionDetail: sessionInfo=+0x%X "
                                .. "hostHandle=+0x%X hostName=+0x%X nameSpan=%d pub=+0x%X "
                                .. "priv=+0x%X (candidate %d, sample host=%s players=%d/%d)",
                                cal.sessionInfo, cal.hostHandle, cal.hostName, cal.nameSpan,
                                cal.pubSlots, cal.privSlots, candidates, hostName, pub + priv,
                                maxPub + maxPriv)
                            return cal
                        end
                    end
                end
                lastReason = ("candidate +0x%X (host=%s): slot counts implausible")
                    :format(off, hostName)
            end
        end
    end

    return nil, ("%s (%d host-RID candidates examined)"):format(lastReason, candidates)
end



function sessionBrowser.resolveFinder()
    local sb = sessionBrowser
    if sb.finderAddr then return sb.finderAddr end

    local findPat = sb.AOB.sessionFinderFind[IS_ENHANCED and "enh" or "leg"]
    local refPat = sb.AOB.networkSessionRef[IS_ENHANCED and "enh" or "leg"]
    if not findPat or not refPat then
        return nil, "no finder signature for this game edition"
    end

    local find = Memory.Scan(findPat)
    if not find or find == 0 then
        return nil, "rlSessionFinder::Find AOB was not found"
    end

    local ref = Memory.Scan(refPat)
    if not ref or ref == 0 then
        return nil, "CNetworkSession global-reference AOB was not found"
    end
    local slot = Memory.Rip(ref + sb.SESSION_REF_RIP[IS_ENHANCED and "enh" or "leg"])
    if not slot or slot == 0 then
        return nil, "CNetworkSession global slot RIP target was null"
    end

    sb.finderAddr = { find = find, sessionSlot = slot }
    sb.log("Resolved find=0x%X sessionSlot=0x%X", find, slot)
    return sb.finderAddr
end

function sessionBrowser.allocFinderBuffers()
    local sb = sessionBrowser
    if sb.finderBuf then return sb.finderBuf end

    local buf = {}
    local specs = {
        { "results", sb.FINDER.MAXRESULTS * sb.SESSION_DETAIL_SIZE },
        { "count",   4 },
        { "status",  sb.NET_STATUS_SIZE },
        { "template", sb.FINDER.RMF_SIZE },
        { "filter",   sb.FINDER.RMF_SIZE },
    }
    for _, spec in ipairs(specs) do
        local name, size = spec[1], spec[2]
        local ptr = Memory.Alloc(size)
        if not ptr or ptr == 0 then
            for _, allocated in pairs(buf) do
                if allocated and allocated ~= 0 then Memory.Free(allocated) end
            end
            return nil, "failed to allocate finder " .. name .. " buffer"
        end
        buf[name] = ptr
    end
    sb.log("Finder buffers results=0x%X filter=0x%X", buf.results, buf.filter)
    sb.finderBuf = buf
    return buf
end

function sessionBrowser.liveFilter(session)
    local sb, F = sessionBrowser, sessionBrowser.FINDER

    local function inspect(ngf, source)
        if not ngf or ngf == 0 then return nil, ("live %s filter pointer is null"):format(source) end
        local rmf = ngf + F.NGF_TO_FILTER
        local filterId  = Memory.ReadInt(rmf + F.RMF_FILTER_ID)
        local condCount = Memory.ReadInt(rmf + F.RMF_CONDITION_COUNT)
        local packed    = Memory.ReadInt(rmf + F.RMF_GAME_MODE)

        if condCount < 1 or condCount > 32
                or (filterId & 0xFFFFFFFF) == F.INVALID_FILTER_ID then
            return nil, ("live %s filter looks unbuilt (id=0x%X conds=%d)")
                :format(source, filterId & 0xFFFFFFFF, condCount)
        end

        return {
            addr = rmf,
            source = source,
            filterId = filterId & 0xFFFFFFFF,
            condCount = condCount,
            gameMode = packed & 0xFFFF,
            purpose = (packed >> 16) & 0xFFFF,
        }
    end

    local query = Memory.ReadLong(session + F.OFF_MMQ_STANDARD + F.MMQ_TO_PFILTER)
    local live, queryErr = inspect(query, "query")
    if live then return live end

    local ctor = session + F.OFF_CTOR_FILTER
    local fallback, ctorErr = inspect(ctor, "ctor")
    if fallback then return fallback end
    return nil, ("%s; %s"):format(tostring(queryErr), tostring(ctorErr))
end

function sessionBrowser.ensureTemplate(session, force)
    local sb, F = sessionBrowser, sessionBrowser.FINDER
    if sb.template and sb.template.valid and not force then
        return sb.template
    end

    local live, err = sb.liveFilter(session)
    if not live then return nil, err end

    sb.copyBlock(sb.finderBuf.template, live.addr, F.RMF_SIZE)

    local drift = sb.validateTemplate(sb.finderBuf.template)

    sb.template = {
        valid = true,
        source = live.source,
        filterId = live.filterId,
        condCount = live.condCount,
        gameMode = live.gameMode,
        purpose = live.purpose,
        capturedAt = Time.GetEpoche(),
        drift = (#drift > 0) and drift or nil,
    }
    sb.log("Template captured from %s filter: id=0x%X conds=%d gameMode=%d purpose=%d",
        live.source, live.filterId, live.condCount, live.gameMode, live.purpose)
    if #drift > 0 then
        sb.logError("Filter structure DRIFTED from baseline (%d issue(s)): %s",
            #drift, table.concat(drift, "; "))
    else
        sb.log("Filter structure matches baseline.")
    end
    return sb.template
end

function sessionBrowser.filterConditions(rmf)
    local sb, F = sessionBrowser, sessionBrowser.FINDER
    local condCount = Memory.ReadInt(rmf + F.RMF_CONDITION_COUNT)
    local attrCount = Memory.ReadInt(rmf + F.RMF_ATTR_COUNT)
    if condCount < 0 or condCount > 32 then condCount = 0 end
    if attrCount < 0 or attrCount > 8 then attrCount = 0 end

    local attrIds = {}
    for i = 0, attrCount - 1 do
        attrIds[i] = Memory.ReadInt(rmf + F.RMF_ATTR_IDS + i * 4) & 0xFFFFFFFF
    end

    local mask = Memory.ReadInt(rmf + F.RMF_COND_MASK)
    local conds = {}
    for c = 0, condCount - 1 do
        local attrIdx = Memory.ReadInt(rmf + F.RMF_COND_ATTR_IDX + c * 4)
        conds[c] = {
            attrIdx = attrIdx,
            attrId  = attrIds[attrIdx],
            op      = Memory.ReadInt(rmf + F.RMF_OPERATORS + c * 4) & 0xFFFFFFFF,
            paramId = Memory.ReadInt(rmf + F.RMF_PARAM_IDS + c * 4) & 0xFFFFFFFF,
            value   = Memory.ReadInt(rmf + F.RMF_COND_VALS + c * 4),
            set     = (mask & (1 << c)) ~= 0,
        }
    end
    return { condCount = condCount, attrCount = attrCount, attrIds = attrIds,
             mask = mask, conds = conds }
end

function sessionBrowser.dumpFilter(rmf, label)
    local sb = sessionBrowser
    local p = sb.filterConditions(rmf)
    sb.logError("%s: %d conditions, %d session attrs, mask=0x%X",
        label or "filter", p.condCount, p.attrCount, p.mask)
    for c = 0, p.condCount - 1 do
        local cd = p.conds[c]
        sb.logError("  cond[%d] attrId=0x%X op=0x%X paramId=0x%X value=%d set=%s",
            c, cd.attrId or 0, cd.op, cd.paramId, cd.value, tostring(cd.set))
    end
end

function sessionBrowser.validateTemplate(rmf)
    local sb = sessionBrowser
    local B = sb.FILTER_BASELINE
    local p = sb.filterConditions(rmf)
    local drift = {}

    if p.condCount ~= B.condCount then
        drift[#drift + 1] = ("condCount %d, expected %d"):format(p.condCount, B.condCount)
    end
    for c, exp in pairs(B.conds) do
        local got = p.conds[c]
        if not got then
            drift[#drift + 1] = ("cond[%d] missing"):format(c)
        elseif got.attrId ~= exp.attrId then
            drift[#drift + 1] = ("cond[%d] attrId 0x%X, expected 0x%X")
                :format(c, got.attrId or 0, exp.attrId)
        elseif got.op ~= exp.op then
            drift[#drift + 1] = ("cond[%d] op 0x%X, expected 0x%X")
                :format(c, got.op, exp.op)
        end
    end
    if not sb.findConditionByAttr(rmf, sb.MM_ATTR.REGION) then
        drift[#drift + 1] = "region condition not found (region search would no-op)"
    end
    return drift
end

function sessionBrowser.findConditionByAttr(rmf, attrId)
    local sb = sessionBrowser
    local p = sb.filterConditions(rmf)
    for c = 0, p.condCount - 1 do
        if p.conds[c].attrId == attrId then return c end
    end
    return nil
end

function sessionBrowser.setFilterRegion(rmf, regionId)
    local sb, F = sessionBrowser, sessionBrowser.FINDER
    local c = sb.findConditionByAttr(rmf, sb.MM_ATTR.REGION)
    if not c then return false, "no region condition in this filter" end

    local mask = Memory.ReadInt(rmf + F.RMF_COND_MASK)
    if regionId == nil then
        mask = mask & ~(1 << c)
    else
        Memory.WriteInt(rmf + F.RMF_COND_VALS + c * 4, regionId)
        mask = mask | (1 << c)
    end
    Memory.WriteInt(rmf + F.RMF_COND_MASK, mask)
    return true, c
end

function sessionBrowser.prepareWorkingFilter()
    local sb, F = sessionBrowser, sessionBrowser.FINDER
    sb.copyBlock(sb.finderBuf.filter, sb.finderBuf.template, F.RMF_SIZE)

    local region = sb.opt.fRegion
    if region ~= nil and region >= 0 then
        local ok, info = sb.setFilterRegion(sb.finderBuf.filter, region)
        if ok then
            sb.log("Search constrained to region %d (condition %d)", region, info)
        else
            sb.logError("Region constraint skipped: %s", tostring(info))
        end
    end

    return sb.finderBuf.filter
end

function sessionBrowser.calibrateNoToken(detailBase)
    local sb = sessionBrowser

    local cfg = sb.findAttrs(detailBase, 0)
    if not cfg then
        return nil, "could not locate rlSessionConfig (no discriminator)"
    end
    local configStart = (cfg.ids - sb.MM_ATTRS_TO_IDS) - 0x0C
    local sessionInfoOff = configStart - sb.SESSION_INFO_SIZE
    if sessionInfoOff < 0 then
        return nil, "derived m_SessionInfo offset is negative"
    end
    local hostRid = Memory.ReadLong(detailBase + sessionInfoOff + sb.SI_HOST_RID)
    if hostRid == 0 then
        return nil, "derived m_SessionInfo carries no host RID"
    end

    for off = cfg.configEnd, sb.SESSION_DETAIL_SIZE - 8, 4 do
        if Memory.ReadLong(detailBase + off) == hostRid then
            local nameOff = off + sb.GAMER_HANDLE_SIZE
            local hostName = sb.readAsciiz(detailBase + nameOff, 17)
            if hostName then
                for _, nameSpan in ipairs({ 20, 16 }) do
                    local pubOff = nameOff + nameSpan
                    local privOff = pubOff + 4
                    if privOff + 4 <= sb.SESSION_DETAIL_SIZE then
                        local pub = Memory.ReadInt(detailBase + pubOff)
                        local priv = Memory.ReadInt(detailBase + privOff)
                        local maxPub = Memory.ReadInt(detailBase + cfg.maxPub)
                        local maxPriv = Memory.ReadInt(detailBase + cfg.maxPriv)
                        if pub >= 0 and pub <= maxPub and priv >= 0 and priv <= maxPriv
                                and (pub + priv) >= 1 then
                            local cal = {
                                sessionInfo  = sessionInfoOff,
                                hostHandle   = off,
                                hostName     = nameOff,
                                nameSpan     = nameSpan,
                                pubSlots     = pubOff,
                                privSlots    = privOff,
                                attrIds      = cfg.ids,
                                attrCount    = cfg.count,
                                maxPubSlots  = cfg.maxPub,
                                maxPrivSlots = cfg.maxPriv,
                            }
                            sb.log("Finder calibration (token-free): sessionInfo=+0x%X "
                                .. "hostHandle=+0x%X host=%s players=%d/%d",
                                sessionInfoOff, off, hostName, pub + priv, maxPub + maxPriv)
                            return cal
                        end
                    end
                end
            end
        end
    end
    return nil, "no host-handle candidate matched after rlSessionConfig"
end

function sessionBrowser.buildFindRows(got)
    local sb = sessionBrowser
    if not sb.bossLimit then sb.getBossLimit() end
    local fbuf = sb.finderBuf
    if got <= 0 then return {} end

    local cal = sb.cal
    if not cal or not cal.attrIds then
        local lastErr
        for i = 0, got - 1 do
            local c, e = sb.calibrateNoToken(fbuf.results + i * sb.SESSION_DETAIL_SIZE)
            if c then
                cal = c
                sb.cal = c
                sb.calibrationError = nil
                break
            end
            lastErr = e
        end
        if not cal then
            sb.calibrationError = lastErr
            return {}
        end
    end

    local rows = {}
    for i = 0, got - 1 do
        local base = fbuf.results + i * sb.SESSION_DETAIL_SIZE
        local row = sb.decodeRow(base, cal)
        if row.players >= 0 and row.players <= sb.SESSION_SLOTS then
            rows[#rows + 1] = row
            sb.rememberRid(row.hostRid, row.hostName)
        else
            sb.logError("Discarding implausible finder row token=0x%X players=%d",
                row.token, row.players)
        end
    end
    return rows
end

function sessionBrowser.runFind()
    local sb, F = sessionBrowser, sessionBrowser.FINDER

    if sb.state.busy then
        sb.toast(T("A scan is already running."))
        return
    end
    if not sb.finderSupported then
        sb.toast(T("Native Scan has no signature for this game edition."), 6000)
        return
    end
    if not Natives.InvokeBool(sb.N.IS_SIGNED_ONLINE) then
        sb.toast(T("Sign in to Rockstar services first."), 6000)
        return
    end
    if not Natives.InvokeBool(sb.N.IS_SESSION_ACTIVE) then
        sb.toast(T("Join a session first: the game needs a live matchmaking filter for us to reuse."), 7000)
        return
    end

    sb.verbose = true

    local addr, err = sb.resolveFinder()
    if not addr then
        sb.logError("Finder resolve failed: %s", tostring(err))
        sb.toast(T("Finder unavailable: %s"):format(tostring(err)), 8000)
        return
    end
    local fbuf, berr = sb.allocFinderBuffers()
    if not fbuf then
        sb.toast(T("Finder unavailable: %s"):format(tostring(berr)), 8000)
        return
    end

    local session = Memory.ReadLong(addr.sessionSlot)
    if not session or session == 0 then
        sb.toast(T("CNetworkSession pointer is null."), 6000)
        return
    end
    if (Memory.ReadInt(session + F.OFF_IS_INIT) & 1) == 0 then
        sb.toast(T("Network session is not initialized yet."), 6000)
        return
    end

    local tpl, terr = sb.ensureTemplate(session)
    if not tpl then
        sb.logError("Template capture failed: %s", tostring(terr))
        sb.toast(T("No usable filter yet: %s"):format(tostring(terr)), 8000)
        return
    end

    if not sb.finderDumped then
        sb.dumpFilter(sb.finderBuf.template, "template filter")
        sb.finderDumped = true
    end
    local workFilter = sb.prepareWorkingFilter()

    local regionLabel = (sb.opt.fRegion ~= nil and sb.opt.fRegion >= 0)
        and (sb.REGION_NAME[sb.opt.fRegion] or ("region " .. sb.opt.fRegion))
        or "any (global)"

    local earlyOut = Memory.ReadInt(session + F.OFF_EARLYOUT) or 0
    if earlyOut < 1 or earlyOut > F.MAXRESULTS then earlyOut = F.MAXRESULTS end

    sb.state.busy = true
    sb.state.phase = "matchmaking"
    sb.state.progress = ""
    sb.state.frac = 0

    sb.log("Find: session=0x%X template=%s id=0x%X conds=%d region=%s earlyOut=%d",
        session, tpl.source, tpl.filterId, tpl.condCount, regionLabel, earlyOut)

    sb.zeroBlock(fbuf.results, F.MAXRESULTS * sb.SESSION_DETAIL_SIZE)
    Memory.WriteInt(fbuf.count, 0)
    sb.zeroBlock(fbuf.status, sb.NET_STATUS_SIZE)

    Memory.LuaCallCFunction(addr.find,
        0, F.NETMODE, F.CHANNEL, F.NUMGAMERS, workFilter,
        fbuf.results, F.MAXRESULTS, earlyOut, fbuf.count, fbuf.status)

    local state, code = sb.awaitStatus(fbuf.status, 30000, "matchmaking find")
    if state == nil then
        sb.state.busy = false
        sb.state.phase = "idle"
        return
    end

    local got = Memory.ReadInt(fbuf.count) or 0
    if state ~= sb.NET_STATUS_SUCCEEDED then
        sb.logError("Find failed: state=%d code=%d results=%d", state, code, got)
        sb.toast(T("Matchmaking find failed (state %d, code %d). See log."):format(state, code), 8000)
        sb.state.busy = false
        sb.state.phase = "idle"
        return
    end
    sb.log("Find OK: %d session(s) returned", got)

    if got > 0 then
        sb.log("Find result[0] first 0x60 bytes: %s", sb.hexDump(fbuf.results, 0x60))
    end

    local rows = sb.buildFindRows(got)
    table.sort(rows, function(a, b)
        if a.players ~= b.players then return a.players > b.players end
        return (a.hostName or "") < (b.hostName or "")
    end)

    sb.activeMode = "browser"
    sb.countryScanActive = false
    sb.state.results = rows
    sb.resultStore.browser = rows
    sb.state.scanned = got
    sb.state.answered = sb.listableCount(rows)
    sb.state.lastScan = Time.GetEpoche()
    sb.state.phase = "idle"
    sb.state.progress = ""
    sb.state.busy = false

    if #rows > 0 then
        sb.toast(T("Native Scan: %d lobbies, %d parsed."):format(got, #rows), 6000)
    elseif got > 0 then
        sb.toast((T("Native Scan returned %d sessions but none parsed; see log for the raw dump.")):format(got), 8000)
    else
        sb.toast(T("Native Scan succeeded but matchmaking returned no sessions right now. Try again shortly."), 8000)
    end
end


function sessionBrowser.detailSubmit(sessions, pbuf)
    local sb = sessionBrowser
    local addr = sb.addr
    local buf = pbuf or sb.buf
    local n = #sessions
    if n == 0 then return nil end

    local expectedTokens = {}
    sb.zeroBlock(buf.infos, n * sb.SESSION_INFO_SIZE)
    for i = 1, n do
        sb.copyBlock(buf.infos + (i - 1) * sb.SESSION_INFO_SIZE,
            sessions[i].info, sb.SESSION_INFO_SIZE)
        expectedTokens[sessions[i].token] = sessions[i]
    end

    sb.zeroBlock(buf.details, n * sb.SESSION_DETAIL_SIZE)
    Memory.WriteInt(buf.detailCount, 0)
    sb.zeroBlock(buf.detailStatus, sb.NET_STATUS_SIZE)

    if IS_ENHANCED then
        Memory.LuaCallCFunction(addr.queryDetail,
            sb.QD_NETMODE, sb.QD_CHANNEL, 0, 0, 0, sb.QD_SOLICITED, sb.QD_QUERY_TYPE,
            buf.noTarget, buf.infos, n, buf.details, buf.detailCount, buf.detailStatus)
    else
        Memory.LuaCallCFunction(addr.queryDetail,
            sb.QD_NETMODE, sb.QD_CHANNEL, 0, 0, 0, sb.QD_SOLICITED, sb.QD_QUERY_TYPE,
            buf.infos, n, buf.details, buf.detailCount, buf.detailStatus)
    end

    return {
        status = buf.detailStatus, started = Time.GetEpocheMs(),
        timeoutMs = 30000, label = "detail query", n = n,
        expectedTokens = expectedTokens, buf = buf,
    }
end

function sessionBrowser.detailCollect(task)
    if scriptUnloading or ShouldUnload() then return {} end
    local sb = sessionBrowser
    if not sb.bossLimit then sb.getBossLimit() end
    local buf = task.buf or sb.buf
    local n = task.n
    local expectedTokens = task.expectedTokens
    local state, code = task.state, task.code
    if state == nil then return {} end

    local got = Memory.ReadInt(buf.detailCount) or 0
    if state ~= sb.NET_STATUS_SUCCEEDED then
        sb.log("Detail query ended state=%d code=%d with %d of %d answered; %s",
            state, code, got, n,
            got > 0 and "keeping the partial results" or "no results returned")
    else
        sb.log("Detail query: submitted=%d answered=%d", n, got)
    end
    if got <= 0 then return {} end
    if got > n then
        sb.logError("Detail query reported %d results for %d submitted; clamping", got, n)
        got = n
    end

    if not sb.cal or not sb.cal.attrIds then
        local best, fallback, lastErr
        for i = 0, got - 1 do
            local cal, err = sb.calibrate(buf.details + i * sb.SESSION_DETAIL_SIZE,
                expectedTokens)
            if cal then
                if cal.attrIds then best = cal; break end
                fallback = fallback or cal
            else
                lastErr = err
            end
        end
        local chosen = best or fallback
        if chosen then
            sb.cal = chosen
            sb.calibrationError = nil
        end
        if not sb.cal then
            sb.calibrationError = lastErr
            return {}
        end
    end

    local cal = sb.cal
    local rows = {}
    for i = 0, got - 1 do
        local base = buf.details + i * sb.SESSION_DETAIL_SIZE
        local row = sb.decodeRow(base, cal)
        local source = expectedTokens[row.token]
        if not source then
            sb.logError("Discarding substituted detail reply: token=0x%X was never "
                .. "submitted (host=%s, claims %d players)", row.token,
                tostring(row.hostName), row.players)
        elseif source.sessionId and source.sessionId ~= 0
            and row.sessionId ~= source.sessionId then
            sb.logError("Discarding detail reply with mismatched session identity")
        elseif row.players < 0 or row.players > sb.SESSION_SLOTS then
            sb.logError("Discarding implausible row token=0x%X players=%d",
                row.token, row.players)
        else
            row.viaRid = source.viaRid
            row.isOwn = source.isOwn or false
            row.members = source.members
            rows[#rows + 1] = row
            sb.rememberRid(row.hostRid, row.hostName)
        end
    end
    return rows
end


function sessionBrowser.rowHasMemberHandle(row)
    if not row.members then return false end
    for _, rid in ipairs(row.members) do
        if rid ~= row.hostRid then return true end
    end
    return false
end

function sessionBrowser.isListable(row)
    local sb = sessionBrowser
    if (row.maxPublic or 0) < sb.PLAYER_CAP
        or row.maxPublic > sb.SESSION_SLOTS then return false end
    if sb.rowIsJob(row) then return false end
    if sb.rowIsClosed(row) then return false end
    if sb.rowIncompatible(row) then return false end
    if (row.awayInJobs or 0) > 0 and not sb.rowHasMemberHandle(row) then return false end
    return true
end

function sessionBrowser.listableCount(rows)
    local n = 0
    for _, row in ipairs(rows or {}) do
        if sessionBrowser.isListable(row) then n = n + 1 end
    end
    return n
end

function sessionBrowser.matchesSearch(row)
    local sb, opt = sessionBrowser, sessionBrowser.opt
    if row.isOwn then return true end
    if row.players < opt.fMinPlayers then return false end
    if opt.fMaxPlayers < sb.PLAYER_CAP and row.players > opt.fMaxPlayers then
        return false
    end
    if opt.fRegion >= 0 and row.region ~= nil and row.region ~= opt.fRegion then
        return false
    end
    if opt.fAim ~= 0 and row.freeAim ~= nil and row.freeAim ~= (opt.fAim == 1) then
        return false
    end
    return true
end

function sessionBrowser.passesFilter(row)
    return sessionBrowser.isListable(row) and sessionBrowser.matchesSearch(row)
end

function sessionBrowser.sortedResults(rows, countryMode)
    local sb, snap = sessionBrowser, {}
    for i = 1, #rows do snap[i] = rows[i] end
    local country = (countryMode ~= nil) and countryMode or sb.countryScanActive
    if country then
        for i = 1, #snap do
            local m = sb.rowCountryMatches(snap[i])
            snap[i]._known = m and m.n or 0
        end
    end
    table.sort(snap, function(a, b)
        if a.players ~= b.players then return a.players > b.players end
        if country and (a._known or 0) ~= (b._known or 0) then
            return (a._known or 0) > (b._known or 0)
        end
        return a.hostName < b.hostName
    end)

    local pinKey, pinIndex = sb.state.hoveredResultKey, sb.state.hoveredResultIndex
    if pinKey and pinIndex then
        for i, row in ipairs(snap) do
            if sb.identity(row) == pinKey then
                table.remove(snap, i)
                local insertAt, visible = #snap + 1, 0
                for j, candidate in ipairs(snap) do
                    if sb.passesFilter(candidate) then
                        visible = visible + 1
                        if visible == pinIndex then
                            insertAt = j
                            break
                        end
                    end
                end
                table.insert(snap, insertAt, row)
                break
            end
        end
    end
    return snap
end

sessionBrowser.CACHE_TTL_SEC = 1800

function sessionBrowser.pruneCaches()
    local sb = sessionBrowser
    local cutoff = Time.GetEpoche() - sb.CACHE_TTL_SEC
    for key, row in pairs(sb.rowCache) do
        if (row.seenAt or 0) < cutoff then sb.rowCache[key] = nil end
    end
    for key, at in pairs(sb.cooldown) do
        if at < cutoff then sb.cooldown[key] = nil end
    end
end

function sessionBrowser.batchSize()
    local size = math.tointeger(sessionBrowser.opt.batchSize) or 1
    if size < 1 then size = 1 end
    if size > sessionBrowser.MAX_BATCH then size = sessionBrowser.MAX_BATCH end
    return size
end

function sessionBrowser.chunk(list, size)
    local chunks, current = {}, {}
    for i = 1, #list do
        current[#current + 1] = list[i]
        if #current == size then
            chunks[#chunks + 1] = current
            current = {}
        end
    end
    if #current > 0 then chunks[#chunks + 1] = current end
    return chunks
end

function sessionBrowser.runScan(providedRids, isCountryScan)
    local sb = sessionBrowser
    local localScan = providedRids == nil and not isCountryScan
    if sb.state.busy then
        sb.toast(T("A scan is already running."))
        return
    end
    sb.countryScanActive = isCountryScan and true or false
    sb.activeMode = isCountryScan and "country" or "browser"
    if sb.joinBusy then
        sb.toast(T("A lobby check is running, try again in a moment."), 5000)
        return
    end

    if not Natives.InvokeBool(sb.N.IS_SIGNED_ONLINE) then
        sb.toast(T("Sign in to Rockstar services first."), 6000)
        return
    end

    local addr, addrErr = sb.resolveAddresses()
    if not addr then
        sb.logError("Address resolution failed: %s", tostring(addrErr))
        sb.toast(T("Unavailable: %s"):format(tostring(addrErr)), 8000)
        return
    end

    local buf, bufErr = sb.allocBuffers()
    if not buf then
        sb.toast(T("Unavailable: %s"):format(tostring(bufErr)), 8000)
        return
    end

    sb.state.busy = true
    sb.state.stopRequested = false
    sb.state.phase = "seeding"
    sb.state.progress = ""
    sb.state.frac = 0
    sb.pruneCaches()

    local rids
    if providedRids then
        rids = {}
        for i = 1, #providedRids do rids[i] = { rid = providedRids[i] } end
    else
        if sb.opt.seedSession then sb.harvestSession() end
        if sb.opt.seedFriends then sb.harvestFriends() end
        if sb.opt.seedTracker then sb.importTracker() end
        rids = sb.buildScanList(sb.opt.maxRids)
    end
    if #rids == 0 then
        sb.state.busy = false
        sb.state.phase = "idle"
        sb.toast(providedRids and T("VibeNet returned no RIDs yet. Try again shortly.")
            or T("No RIDs to scan. Play a session or add friends first."), 7000)
        return
    end

    local ownRid = sb.localRid()
    if ownRid then
        local present = false
        for i = 1, #rids do
            if rids[i].rid == ownRid then
                present = true
                break
            end
        end
        if not present then table.insert(rids, 1, { rid = ownRid }) end
    end

    if localScan then telemetryCountAction("LocalScan") end
    sb.log("Scan starting: %d RIDs, batch=%d", #rids, sb.batchSize())
    if sb.verbose then
        local head = {}
        for i = 1, math.min(#rids, 12) do
            head[#head + 1] = ("%d(%s)"):format(rids[i].rid, rids[i].name or "")
        end
        sb.log("Scan list head: %s", table.concat(head, " "))
    end

    sb.state.phase = "resolving"
    sb.state.results = {}
    sb.resultStore[sb.activeMode] = sb.state.results
    sb.state.answered = 0
    sb.state.scanned = 0
    local ridValues = {}
    for i = 1, #rids do ridValues[i] = rids[i].rid end

    local localRid = sb.localRid()
    local unique = {}
    local rows = {}
    local detailQueue, qHead = {}, 1
    local uniqueCount, skipped, cached, seenLocal = 0, 0, 0, 0

    local function releaseOwnedSessions()
        for _, session in ipairs(detailQueue) do
            if session.owned and session.info and session.info ~= 0 then
                Memory.Free(session.info)
                session.info = 0
                session.owned = false
            end
        end
    end

    local function publish()
        local snap = sb.sortedResults(rows)
        if localScan then
            for _, row in ipairs(snap) do
                sb.localDiscovery.lobbies[sb.identity(row)] = true
            end
        end
        sb.state.results = snap
        sb.resultStore[sb.activeMode] = snap
        sb.state.answered = sb.listableCount(snap)
    end

    local function takeGroup()
        local group, size = {}, sb.batchSize()
        while qHead <= #detailQueue and #group < size do
            group[#group + 1] = detailQueue[qHead]
            qHead = qHead + 1
        end
        return group
    end

    local function intake(sessions)
        local seenAt = Time.GetEpoche()
        for _, session in ipairs(sessions) do
            sb.touchLiveRid(session.viaRid, seenAt)
            sb.touchLiveRid(session.hostRid, seenAt)
            local key = sb.identity(session)
            local stored = unique[key]
            if stored then
                if localRid and session.viaRid == localRid then stored.isOwn = true end
                if #stored.members < sb.MAX_BATCH and session.viaRid
                        and session.viaRid > 0 then
                    stored.members[#stored.members + 1] = session.viaRid
                end
            else
                uniqueCount = uniqueCount + 1
                if localRid and session.viaRid == localRid then session.isOwn = true end
                session.members = (session.viaRid and session.viaRid > 0)
                    and { session.viaRid } or {}
                unique[key] = session
                local last = sb.cooldown[key]
                if localScan and sb.localDiscovery.lobbies[key] then
                    seenLocal = seenLocal + 1
                elseif not localScan and last and (Time.GetEpoche() - last) < sb.opt.cooldownSec then
                    skipped = skipped + 1
                    local prev = sb.rowCache[key]
                    if prev then
                        cached = cached + 1
                        prev.isOwn = prev.isOwn or session.isOwn or false
                        local have = {}
                        for _, rid in ipairs(session.members) do have[rid] = true end
                        for _, rid in ipairs(prev.members or {}) do
                            if not have[rid] and #session.members < sb.MAX_BATCH then
                                have[rid] = true
                                session.members[#session.members + 1] = rid
                            end
                        end
                        prev.members = session.members
                        if prev.isOwn then sb.noteSelfDisc(prev.disc) end
                        rows[#rows + 1] = prev
                    end
                else
                    local owned = Memory.Alloc(sb.SESSION_INFO_SIZE)
                    if owned and owned ~= 0 then
                        sb.copyBlock(owned, session.info, sb.SESSION_INFO_SIZE)
                        session.info = owned
                        session.owned = true
                        detailQueue[#detailQueue + 1] = session
                    end
                end
            end
        end
        sb.state.scanned = uniqueCount
        publish()
    end

    local presenceBatches = sb.chunk(ridValues, sb.batchSize())
    local pTask, pSent, pDone = nil, 0, 0
    local dTask, dGroup = nil, nil
    local nextPresenceAt, nextDetailAt = 0, 0

    while true do
        if ShouldUnload() or scriptUnloading then
            releaseOwnedSessions()
            sb.state.busy = false
            return
        end
        local now = Time.GetEpocheMs()
        local stopping = sb.state.stopRequested

        if not stopping and not pTask and pSent < #presenceBatches and now >= nextPresenceAt then
            pSent = pSent + 1
            pTask = sb.presenceSubmit(presenceBatches[pSent])
        end
        if not stopping and not dTask and now >= nextDetailAt then
            local queued = #detailQueue - qHead + 1
            local presenceLive = pTask ~= nil or pSent < #presenceBatches
            if queued >= sb.batchSize() or (queued > 0 and not presenceLive) then
                dGroup = takeGroup()
                dTask = sb.detailSubmit(dGroup)
                if not dTask then dGroup = nil end
            end
        end

        if not pTask and not dTask and (stopping
                or (pSent >= #presenceBatches and qHead > #detailQueue)) then
            break
        end

        Script.Yield(sb.POLL_MS)

        if ShouldUnload() or scriptUnloading then
            releaseOwnedSessions()
            sb.state.busy = false
            return
        end

        if pTask and sb.pollTask(pTask) then
            local sessions = sb.presenceCollect(pTask)
            pTask, pDone = nil, pDone + 1
            nextPresenceAt = Time.GetEpocheMs() + sb.opt.batchDelayMs
            if not sb.state.stopRequested then intake(sessions) end
        end

        if dTask and sb.pollTask(dTask) then
            local answered = {}
            for _, row in ipairs(sb.detailCollect(dTask)) do
                if row.isOwn then sb.noteSelfDisc(row.disc) end
                rows[#rows + 1] = row
                local key = sb.identity(row)
                answered[key] = true
                sb.cooldown[key] = Time.GetEpoche()
                sb.rowCache[key] = row
            end
            for _, session in ipairs(dGroup) do
                if session.isOwn and not answered[sb.identity(session)] then
                    local prev = sb.rowCache[sb.identity(session)]
                    if prev then
                        prev.isOwn = true
                        sb.applyLive(prev)
                        rows[#rows + 1] = prev
                    end
                end
                if session.owned then
                    Memory.Free(session.info)
                    session.info = 0
                    session.owned = false
                end
            end
            dTask, dGroup = nil, nil
            nextDetailAt = Time.GetEpocheMs() + sb.opt.batchDelayMs
            publish()
        end

        if sb.state.stopRequested then
            sb.state.phase = "stopping"
            sb.state.progress = T("Stopping...")
        elseif pDone < #presenceBatches then
            sb.state.phase = "resolving"
            sb.state.progress = ("presence %d/%d - %d lobbies")
                :format(pDone, #presenceBatches, #rows)
            sb.state.frac = pDone / #presenceBatches
        else
            sb.state.phase = "querying"
            sb.state.progress = ("hosts - %d lobbies"):format(#rows)
            sb.state.frac = 1
        end
    end

    local stopped = sb.state.stopRequested
    if stopped then releaseOwnedSessions() end
    if skipped > 0 then
        sb.log("Skipped %d sessions still inside the %ds cooldown (%d republished "
            .. "from the last reply)", skipped, sb.opt.cooldownSec, cached)
    end
    publish()

    sb.state.lastScan = Time.GetEpoche()
    sb.state.phase = "idle"
    sb.state.progress = ""
    sb.state.busy = false
    sb.state.stopRequested = false
    sb.saveRids()

    if stopped then
        sb.toast(T("Scan stopped."), 4000)
        return
    end

    if #rows == 0 and uniqueCount == 0 and sb.presenceProven then
        sb.toast(T("Presence works, but none of those %s accounts are in a session right now. Try more RIDs or scan while more people are online."):format(#ridValues), 9000)
    end

    local incompat, clusters, order = 0, {}, {}
    for i = 1, #rows do
        if sb.rowIncompatible(rows[i]) then incompat = incompat + 1 end
        local disc = rows[i].disc
        if disc then
            local id = sb.discIdentity(disc)
            if not clusters[id] then
                clusters[id] = { n = 0, disc = disc }
                order[#order + 1] = id
            end
            clusters[id].n = clusters[id].n + 1
        end
    end
    if #order > 0 then
        table.sort(order, function(a, b) return clusters[a].n > clusters[b].n end)
        local ref = sb.selfDisc and sb.discIdentity(sb.selfDisc) or nil
        sb.log("Pool identities across %d rows (%d distinct):", #rows, #order)
        for _, id in ipairs(order) do
            local d = sb.decodeDiscriminator(clusters[id].disc)
            sb.log("  0x%08X x%-4d build=%d titleUpdate=%2d port=0x%02X "
                .. "content=0x%04X%s", id, clusters[id].n, d.build, d.version,
                d.port, d.user, (ref == id) and "   <- ours" or "")
        end
        if not ref then
            sb.log("  no reference yet: join one lobby from this list and the "
                .. "identity that accepted us becomes it.")
        end
    end

    local byRegion, mine = {}, nil
    for i = 1, #rows do
        local key = rows[i].region or -1
        byRegion[key] = (byRegion[key] or 0) + 1
        if rows[i].isOwn then mine = rows[i].region end
    end
    local spread = {}
    for region, n in pairs(byRegion) do spread[#spread + 1] = { r = region, n = n } end
    table.sort(spread, function(a, b) return a.n > b.n end)
    for _, e in ipairs(spread) do
        sb.log("  region %-10s x%-4d (%d%%)%s",
            (e.r >= 0 and (sb.REGION_SHORT[e.r] or e.r)) or "unknown",
            e.n, math.floor(e.n * 100 / #rows + 0.5),
            (mine ~= nil and e.r == mine) and "   <- ours" or "")
    end

    sb.log("Scan complete: %d sessions found, %d rows (%d cached)",
        uniqueCount, #rows, cached)
    local listable = sb.listableCount(rows)
    if localScan then
        sb.toast(("Local Scan: %d new lobbies; %d previously returned lobbies skipped.")
            :format(listable, seenLocal), 6000)
        return
    end
    sb.toast(T("Scan done: %d lobbies of %d found%s."):format(listable,
        uniqueCount,
        (cached > 0) and (T(", %d still in cooldown")):format(cached) or ""), 6000)
end


sessionBrowser.bench = {
    running    = false,
    phase      = "",
    rows       = {},
    verdict    = nil,
    delayNote  = nil,
    poolSizes  = { 32, 64, 128, 256, 512, 1024, 2048 },
    batchSizes = { 1, 2, 4, 8, 16 },
    delays     = { 0, 50, 100, 250 },
    batchPool  = 48,
    delayPool  = 256,
    repeats    = 1,
}

function sessionBrowser.bench.measure(ridList, batch, delayMs)
    local sb = sessionBrowser
    if batch < 1 then batch = 1 end
    if batch > sb.MAX_BATCH then batch = sb.MAX_BATCH end
    local delay = delayMs or sb.opt.batchDelayMs

    local unique, uniqueCount, hits = {}, 0, 0
    local started = Time.GetEpocheMs()
    for _, group in ipairs(sb.chunk(ridList, batch)) do
        if ShouldUnload() or scriptUnloading then return nil end
        for _, session in ipairs(sb.resolveBatch(group)) do
            hits = hits + 1
            local key = sb.identity(session)
            if not unique[key] then
                unique[key] = true
                uniqueCount = uniqueCount + 1
            end
        end
        Script.Yield(delay)
    end
    return { ms = Time.GetEpocheMs() - started, hits = hits, unique = uniqueCount }
end

function sessionBrowser.bench.judge()
    local sb, bench = sessionBrowser, sessionBrowser.bench
    local one, full
    for _, row in ipairs(bench.rows) do
        if row.kind == "batch" then
            if row.batch == 1 then one = row end
            if row.batch == sb.MAX_BATCH then full = row end
        end
    end
    if not (one and full) then return nil end

    if one.hits == 0 and full.hits == 0 then
        return { lossy = false, text = T("Inconclusive: nobody in any of the sampled "
            .. "%d lobbies was in a session this run. Re-run when more players are "
            .. "online."):format(one.rids) }
    end

    local lossy = one.hits > (full.hits + 1) * 1.5
    return {
        lossy = lossy,
        text = lossy
            and T("Batching is LOSSY: batch 1 found %d in-session hits vs %d at batch %d "
                 .. "on the SAME %d RIDs. Batch>1 is dropping handles - scan at batch 1 "
                 .. "for full coverage (slower), or fix the batch result collection.")
                 :format(one.hits, full.hits, sb.MAX_BATCH, one.rids)
            or  T("Batching is SOUND: batch 1 found %d hits vs %d at batch %d on the SAME "
                 .. "%d RIDs. Keep batch %d - same coverage for ~%dx fewer round trips.")
                 :format(one.hits, full.hits, sb.MAX_BATCH, one.rids, sb.MAX_BATCH, sb.MAX_BATCH),
    }
end

function sessionBrowser.bench.judgeDelay()
    local bench = sessionBrowser.bench
    local fast, slow
    for _, row in ipairs(bench.rows) do
        if row.kind == "delay" then
            if row.batch >= 0 and row.label == "delay 0"   then fast = row end
            if row.label == "delay 250" then slow = row end
        end
    end
    if not (fast and slow) then return nil end
    if fast.hits == 0 and slow.hits == 0 then return nil end

    local saved = (slow.ms - fast.ms) / 1000
    if fast.hits >= slow.hits * 0.9 then
        return T("Delay is free time: 0ms found %d hits vs %d at 250ms on the same %d "
            .. "RIDs, and ran %.1fs faster. Cutting the batch delay speeds scans with "
            .. "no coverage loss."):format(fast.hits, slow.hits, fast.rids, saved)
    end
    return T("Delay earns coverage: 0ms found only %d hits vs %d at 250ms (server "
        .. "throttling the fast pass). Keep some batch delay."):format(fast.hits, slow.hits)
end

function sessionBrowser.bench.run()
    local sb, bench = sessionBrowser, sessionBrowser.bench
    if bench.running or sb.state.busy then
        sb.toast(T("A scan or benchmark is already running."))
        return
    end
    if not Natives.InvokeBool(sb.N.IS_SIGNED_ONLINE) then
        sb.toast(T("Sign in to Rockstar services first."), 6000)
        return
    end
    local addr = sb.resolveAddresses()
    local buf = addr and sb.allocBuffers()
    if not addr or not buf then
        sb.toast(T("Benchmark unavailable: addresses/buffers not ready."), 8000)
        return
    end

    local corpus = {}
    for _, entry in ipairs(sb.buildScanList(nil)) do corpus[#corpus + 1] = entry.rid end
    if #corpus == 0 then
        sb.toast(T("Benchmark: the RID pool is empty. Play a session or add RIDs first."), 8000)
        return
    end

    bench.running = true
    bench.rows = {}
    bench.verdict = nil
    bench.delayNote = nil
    sb.state.busy = true
    sb.state.phase = "benchmark"
    sb.state.frac = 0

    local function slice(n)
        n = math.min(n, #corpus)
        local out = {}
        for i = 1, n do out[i] = corpus[i] end
        return out
    end

    local function record(fmt, value, kind, list, batch, delayMs)
        local label = fmt:format(value)
        local reps = math.max(1, bench.repeats)
        local ms, hits, unique = 0, 0, 0
        for r = 1, reps do
            bench.phase = ("%s b%d  pass %d/%d"):format(label, batch, r, reps)
            sb.state.progress = bench.phase
            local m = bench.measure(list, batch, delayMs)
            if not m then return false end
            ms, hits, unique = ms + m.ms, hits + m.hits, unique + m.unique
        end
        bench.rows[#bench.rows + 1] = {
            label = label, disp = T(fmt):format(value),
            kind = kind, rids = #list, batch = batch,
            ms = ms // reps, hits = hits // reps, unique = unique // reps,
        }
        sb.log("Bench %-10s rids=%d batch=%2d delay=%s -> %5dms  hits=%d unique=%d",
            label, #list, batch, delayMs and tostring(delayMs) or "def",
            ms // reps, hits // reps, unique // reps)
        return true
    end

    sb.log("---- benchmark begin (%d RIDs in pool) ----", #corpus)
    local ok = true

    local lastEff = -1
    for _, pool in ipairs(bench.poolSizes) do
        local eff = math.min(pool, #corpus)
        if eff ~= lastEff then
            lastEff = eff
            if not record("pool %d", eff, "pool", slice(eff), sb.MAX_BATCH) then
                ok = false break
            end
        end
    end

    if ok then
        local batchList = slice(bench.batchPool)
        for _, batch in ipairs(bench.batchSizes) do
            if not record("batch %d", batch, "batch", batchList, batch) then
                ok = false break
            end
        end
    end

    if ok then
        local delayList = slice(bench.delayPool)
        for _, d in ipairs(bench.delays) do
            if not record("delay %d", d, "delay", delayList, sb.MAX_BATCH, d) then break end
        end
    end

    bench.verdict = bench.judge()
    bench.delayNote = bench.judgeDelay()
    if bench.verdict then sb.log("Bench verdict: %s", bench.verdict.text) end
    if bench.delayNote then sb.log("Bench delay: %s", bench.delayNote) end
    sb.log("---- benchmark end ----")

    bench.phase = ""
    bench.running = false
    sb.state.busy = false
    sb.state.phase = "idle"
    sb.state.progress = ""
    sb.toast(T("Benchmark complete - see the RID Pool panel."), 6000)
end

function sessionBrowser.bench.render()
    local sb, bench = sessionBrowser, sessionBrowser.bench
    ImGui.Separator()
    ImGui.Text(T("Benchmark"))
    ImGui.PushTextWrapPos(0)
    ImGui.TextDisabled(T("Sweeps pool size (coverage), batch size (round trips) and batch delay (idle) over one snapshot of the pool and times each. Presence only, sets no cooldown. Runs for a few minutes - batch 1 is one round trip per RID."))
    ImGui.PopTextWrapPos()

    bench.batchPool = ImGui.SliderInt(TL("Batch-sweep RIDs"), bench.batchPool, 8, 96)
    if ImGui.IsItemHovered() then
        ImGui.SetTooltip(T("RIDs the batch-size comparison resolves each pass. Bigger = steadier numbers but a longer run (batch 1 does one round trip per RID)."))
    end
    bench.delayPool = ImGui.SliderInt(TL("Delay-sweep RIDs"), bench.delayPool, 32, 512)
    if ImGui.IsItemHovered() then
        ImGui.SetTooltip(T("RIDs the batch-delay comparison resolves at each idle value (0/50/100/250ms). Bigger = a clearer throttling signal, longer run."))
    end
    bench.repeats = ImGui.SliderInt(TL("Repeats (averaged)"), bench.repeats, 1, 3)

    if bench.running then
        ImGui.Text(T("Running: %s"):format(bench.phase))
    elseif ImGui.Button(TL("Run benchmark"), ImGui.GetContentRegionAvail(), 0) then
        Script.QueueJob(bench.run)
    end

    if #bench.rows > 0 and ImGui.BeginTable("##VS_BenchTable", 5, 0) then
        local heads = { T("Config"), T("RIDs"), T("Time"), T("Hits"), T("Sessions") }
        for _, h in ipairs(heads) do ImGui.TableSetupColumn(h, 0) end
        ImGui.TableNextRow()
        for _, h in ipairs(heads) do
            ImGui.TableNextColumn()
            ImGui.TextDisabled(h)
        end
        for _, row in ipairs(bench.rows) do
            ImGui.TableNextRow()
            ImGui.TableNextColumn() ImGui.Text(row.disp or row.label)
            ImGui.TableNextColumn() ImGui.Text(tostring(row.rids))
            ImGui.TableNextColumn() ImGui.Text(T("%.1fs"):format(row.ms / 1000))
            ImGui.TableNextColumn() ImGui.Text(tostring(row.hits))
            ImGui.TableNextColumn() ImGui.Text(tostring(row.unique))
        end
        ImGui.EndTable()
    end

    if bench.verdict and bench.verdict.text then
        ImGui.PushTextWrapPos(0)
        if bench.verdict.lossy then
            ImGui.TextColored(1.0, 0.55, 0.35, 1.0, bench.verdict.text)
        else
            ImGui.TextColored(0.5, 0.9, 0.5, 1.0, bench.verdict.text)
        end
        ImGui.PopTextWrapPos()
    end

    if bench.delayNote then
        ImGui.PushTextWrapPos(0)
        ImGui.TextColored(0.55, 0.8, 1.0, 1.0, bench.delayNote)
        ImGui.PopTextWrapPos()
    end
end


function sessionBrowser.sectionHeader(text, note)
    text, note = T(text), note and T(note) or note
    local x0 = ImGui.GetCursorPosX()
    local availW = ImGui.GetContentRegionAvail()
    ImGui.Dummy(1, 2)
    ImGui.TextColored(0.60, 0.72, 1.00, 1.00, text)
    if note and note ~= "" then
        local noteW = ImGui.CalcTextSize(note)
        ImGui.SameLine()
        ImGui.SetCursorPosX(x0 + availW - noteW)
        ImGui.TextDisabled(note)
    end
    ImGui.Separator()
end

function sessionBrowser.scanLocked(mode)
    local sb = sessionBrowser
    return sb.state.busy and sb.activeMode ~= mode
end

function sessionBrowser.requestStop(mode)
    local sb = sessionBrowser
    if not sb.state.busy or sb.activeMode ~= mode then
        return
    end
    sb.state.stopRequested = true
    sb.state.phase = "stopping"
    sb.state.progress = T("Stopping...")
end

function sessionBrowser.pushDim()
    ImGui.PushStyleColor(ImGuiCol.Button,        0.20, 0.21, 0.25, 0.65)
    ImGui.PushStyleColor(ImGuiCol.ButtonHovered, 0.20, 0.21, 0.25, 0.65)
    ImGui.PushStyleColor(ImGuiCol.ButtonActive,  0.20, 0.21, 0.25, 0.65)
    ImGui.PushStyleColor(ImGuiCol.Text,          0.52, 0.54, 0.60, 1.00)
end

function sessionBrowser.popDim()
    ImGui.PopStyleColor(4)
end

function sessionBrowser.dimButton(label, w, h, dim)
    local sb = sessionBrowser
    if dim then sb.pushDim() end
    local clicked = ImGui.Button(label, w, h)
    if dim then sb.popDim() end
    return clicked and not dim
end

function sessionBrowser.renderControls()
    local sb = sessionBrowser
    local fullW = ImGui.GetContentRegionAvail()
    local BTN_H = 30
    local half = math.floor((fullW - 8) / 2)

    local own, tracker = sb.knownCounts()
    local status = T("Pool %d RIDs      %d found      %d answered")
        :format(own + tracker, sb.state.scanned, sb.state.answered)
    if sb.presenceProven then status = status .. T("      presence ok") end
    ImGui.TextDisabled(status)
    if sb.calibrationError and not sb.cal then
        ImGui.PushTextWrapPos(0)
        ImGui.TextColored(1.0, 0.4, 0.4, 1.0,
            T("Detail layout not calibrated: %s"):format(tostring(sb.calibrationError)))
        ImGui.PopTextWrapPos()
    end
    if sb.template and sb.template.drift then
        ImGui.PushTextWrapPos(0)
        ImGui.TextColored(1.0, 0.7, 0.3, 1.0,
            T("Filter schema drifted from baseline; region search may be off. ")
            .. table.concat(sb.template.drift, "; "))
        ImGui.PopTextWrapPos()
    end

    if sb.state.busy and sb.activeMode == "browser" then
        local frac = sb.state.frac or 0
        local text = ("%s - %s"):format(sb.state.phase, sb.state.progress ~= ""
            and sb.state.progress or ("%d%%"):format(math.floor(frac * 100 + 0.5)))
        ImGui.ProgressBar(frac, fullW, BTN_H, text)
    else
        local nButtons = (sb.supported and 1 or 0) + (sb.finderSupported and 1 or 0)
            + ((sb.supported and not vibenet.consentPending) and 1 or 0)
        local btnW = math.floor((fullW - 8 * (nButtons - 1)) / math.max(nButtons, 1))
        local locked = sb.scanLocked("browser")
        if sb.supported then
            if vibenet.consentPending then
                ImGui.PushTextWrapPos(0)
                ImGui.TextColored(0.55, 0.8, 1.0, 1.0, T("VibeNet - shared matchmaking"))
                ImGui.Text(T("VibeNet pools the Rockstar IDs of the players in your session together with other VibeScript users, and hands you a batch of recent IDs to scan for populated lobbies. Share yours to use it?"))
                ImGui.PopTextWrapPos()
                if ImGui.Button(TL("Share & enable"), half, 0) then
                    vibenet.setOptIn(true)
                    vibenet.consentPending = false
                    vibenet.startScan()
                end
                ImGui.SameLine()
                if ImGui.Button(TL("No thanks"), ImGui.GetContentRegionAvail(), 0) then
                    vibenet.consentPending = false
                end
            else
                local left = vibenet.cooldownLeft()
                local pressed = vibenet.scanning and true or false
                local fetching = vibenet.fetching and true or false
                local label = (left > 0)
                    and T("VibeNet Scan   %ds"):format(math.ceil(left / 1000))
                    or T("VibeNet Scan")
                local lit = locked and 0.30
                    or (pressed and 0.55 or ((left > 0) and 0.42 or 1.0))
                local bw, bh, FONT = btnW, BTN_H, 1.15
                local function ci(v)
                    v = math.floor(v + 0.5)
                    return (v < 0) and 0 or (v > 255) and 255 or v
                end
                local function rainbow(hh)
                    local r, g, b = ImGui.ColorConvertHSVtoRGB(hh % 1.0, 1.0, 1.0)
                    return r * 255, g * 255, b * 255
                end
                local bx, by = ImGui.GetCursorScreenPos()
                local clicked = ImGui.InvisibleButton("##vibenetscan", bw, bh)
                local hov = ImGui.IsItemHovered() and true or false
                local x1b, y1b = bx + bw, by + bh
                local tt = ImGui.GetTime()
                local pulse = pressed and 0 or (0.5 + 0.5 * math.sin(tt * 3.2))
                local r, g, b = rainbow(tt * 0.30)
                if pressed then r, g, b = 105, 105, 112 end
                local sink = pressed and 1 or 0
                local base = pressed and 10 or (26 + (hov and 18 or 0) + math.floor(pulse * 12))
                ImGui.AddRectFilled(bx + sink, by + sink, x1b - sink, y1b - sink,
                    base, base, base + 8, 255, 5)
                ImGui.AddRect(bx - 2, by - 2, x1b + 2, y1b + 2, ci(r), ci(g), ci(b),
                    ci((40 + pulse * 110) * lit), 7, 0, 3)
                ImGui.AddRect(bx, by, x1b, y1b, ci(r * lit), ci(g * lit), ci(b * lit), 255, 5, 0, 2)
                local lr = ci((r + (255 - r) * 0.55) * lit)
                local lg = ci((g + (255 - g) * 0.55) * lit)
                local lb = ci((b + (255 - b) * 0.55) * lit)
                ImGui.SetWindowFontScale(FONT)
                local tw, fh = ImGui.CalcTextSize(label)
                ImGui.AddText(math.floor((bx + x1b) * 0.5 - tw * 0.5) + sink,
                    by + math.floor((bh - fh) * 0.5) + sink, label, lr, lg, lb, 255)
                ImGui.SetWindowFontScale(1.0)

                if clicked and not pressed and not locked then
                    vibenet.onScanButton()
                end
                if hov then
                    ImGui.SetTooltip(locked
                        and T("A Countries search is running - it finishes first.")
                        or (fetching
                        and T("Fetching RIDs from VibeNet...")
                        or (pressed
                        and T("Finishing the last scan - the cooldown starts when it does.")
                        or (T("(Better Results) Scans thousands of recent RID's shared by other VibeScript users for maximum results.")))))
                end
                ImGui.SameLine()
            end
        end

        if sb.supported then
            local w = sb.finderSupported and btnW or ImGui.GetContentRegionAvail()
            if sb.dimButton(T("Local Scan"), w, BTN_H, locked) then
                Script.QueueJob(sb.runScan)
            end
            if ImGui.IsItemHovered() then
                ImGui.SetTooltip(locked
                    and T("A Countries search is running - it finishes first.")
                    or (T("Finds sessions using only your local player lists, including modders, friends, saved, and recent players")))
            end
            if sb.finderSupported then ImGui.SameLine() end
        end
        if sb.finderSupported then
            if sb.dimButton("Native Scan", ImGui.GetContentRegionAvail(), BTN_H, locked) then
                Script.QueueJob(sb.runFind)
            end
            if ImGui.IsItemHovered() then
                ImGui.SetTooltip(locked
                    and T("A Countries search is running - it finishes first.")
                    or (T("Calls rlSessionFinder::Find with the game's own live matchmaking filter, into our own buffers. Finds public lobbies the native way, no RID pool required. Uses the region picked above. Read-only on game state.")))
            end
        end
        if not sb.supported then
            ImGui.PushTextWrapPos(0)
            ImGui.TextDisabled(T("Peer scan has no signature on this edition."))
            ImGui.PopTextWrapPos()
        end
    end
end

function sessionBrowser.renderSources()
    local sb = sessionBrowser

    sb.opt.maxRids = ImGui.SliderInt(TL("RIDs per scan"), sb.opt.maxRids, 16, 2048)
    if ImGui.IsItemHovered() then
        ImGui.SetTooltip(T("Local Scan rotates through the entire RID pool and skips lobbies returned by earlier Local Scans until script reload. A scan can return no new lobbies. Costs ~one network round trip per batchSize RIDs."))
    end
    sb.opt.batchSize = ImGui.SliderInt(TL("Batch size"), sb.opt.batchSize, 1, sb.MAX_BATCH)
    if ImGui.IsItemHovered() then
        ImGui.SetTooltip(T("RIDs per engine call. The benchmark's batch sweep proved batching resolves every handle (identical coverage at 1 and 16), so 16 is the fast choice - ~16x fewer round trips than 1."))
    end
    sb.opt.batchDelayMs = ImGui.SliderInt(TL("Batch delay (ms)"), sb.opt.batchDelayMs, 0, 500)
    if ImGui.IsItemHovered() then
        ImGui.SetTooltip(T("Wait between round trips. Lower = faster scans; raise it only if the delay sweep shows the server throttling low-delay passes."))
    end
    sb.opt.cooldownSec = ImGui.SliderInt(TL("Re-query cooldown (s)"), sb.opt.cooldownSec, 0, 600)
    if ImGui.IsItemHovered() then
        ImGui.SetTooltip("Applies to VibeNet and country scans. Local Scan skips previously returned lobbies until script reload.")
    end

    ImGui.Separator()

    sb.opt.seedSession = ImGui.Checkbox(TL("Seed from current session"), sb.opt.seedSession)
    sb.opt.seedFriends = ImGui.Checkbox(TL("Seed from friends"), sb.opt.seedFriends)
    sb.opt.seedTracker = ImGui.Checkbox(TL("Seed from Cherax PlayerTracker"), sb.opt.seedTracker)
    if sb.opt.seedTracker then
        ImGui.Indent(12)
        for _, source in ipairs(sb.trackerFiles) do
            source.enabled = ImGui.Checkbox(source.file, source.enabled)
        end
        ImGui.Unindent(12)
    end

    ImGui.Separator()

    ImGui.Text(T("Add RID(s)"))
    ImGui.SetNextItemWidth(-70)
    sb.ui.ridInput = ImGui.InputText("##browser_rid_add", sb.ui.ridInput)
    ImGui.SameLine()
    if ImGui.Button(TL("Add RIDs"), 60, 0) then
        local added = 0
        for rid in tostring(sb.ui.ridInput):gmatch("%d+") do
            if sb.rememberRid(rid, "manual") then added = added + 1 end
        end
        sb.saveRids()
        sb.ui.ridInput = ""
        sb.toast(T("Added %d RIDs."):format(added))
    end

    sb.verbose = ImGui.Checkbox(TL("Verbose logging"), sb.verbose)

    ImGui.Separator()

    if ImGui.Button(TL("Recalibrate"), 110, 0) then
        sb.cal = nil
        sb.calibrationError = nil
        sb.cooldown = {}
        sb.rowCache = {}
        sb.udOffset = nil
        sb.addr = nil
        sb.toast(T("Layout calibration, addresses and host cooldowns cleared. Scan again."))
    end
    if ImGui.IsItemHovered() then
        ImGui.SetTooltip(T("Forget the derived rlSessionDetail offsets so the next scan works them out again. Use it if rows report nonsense counts or names."))
    end
    ImGui.SameLine()
    if ImGui.Button(TL("Sanity check"), 120, 0) then
        Script.QueueJob(sb.sanityCheck)
    end
    if ImGui.IsItemHovered() then
        ImGui.SetTooltip(T("Re-derives the layout and checks every decoded field against the session you are in: player count vs the game's own, capacity, host RID vs the real host, freeroam-vs-job classification, and the freemode blob. Run it from freemode."))
    end
    if sb.finderSupported then
        ImGui.SameLine()
        if ImGui.Button(TL("Re-snapshot filter"), 140, 0) then
            Script.QueueJob(function()
                if not sb.finderSupported then return end
                local addr = sb.resolveFinder()
                local buf = sb.allocFinderBuffers()
                local session = addr and buf and Memory.ReadLong(addr.sessionSlot)
                if not session or session == 0 then
                    sb.toast(T("Re-snapshot: no live session."), 6000)
                    return
                end
                local tpl, terr = sb.ensureTemplate(session, true)
                if tpl then
                    sb.finderDumped = false
                    sb.toast(T("Filter template re-captured (id=0x%X, %d conds)."):format(tpl.filterId, tpl.condCount), 6000)
                else
                    sb.toast(T("Re-snapshot failed: %s"):format(tostring(terr)), 8000)
                end
            end)
        end
    end

    sb.bench.render()
end

function sessionBrowser.fmtSlider(id, value, lo, hi, fmt, width)
    ImGui.SetNextItemWidth(width)
    return ImGui.SliderInt(id, value, lo, hi, fmt)
end

function sessionBrowser.renderFilters()
    local sb = sessionBrowser
    local clearW = math.floor(ImGui.CalcTextSize("Clear") + 20)
    local stopW = math.floor(ImGui.CalcTextSize(T("Stop Scan")) + 20)
    local optOutW = math.floor(ImGui.CalcTextSize("Opt Out") + 20)

    if ImGui.BeginTable("##VS_FilterTop", 3, ImGuiTableFlags.SizingStretchSame) then
        ImGui.TableNextRow()

        ImGui.TableSetColumnIndex(0)
        ImGui.SetNextItemWidth(ImGui.GetContentRegionAvail())
        sb.ui.regionSel = Widget.combo("##fregion", sb.ui.regionSel, sb.ui.regionItems,
            #sb.ui.regionItems)
        sb.opt.fRegion = sb.ui.regionIds[sb.ui.regionSel + 1] or -1

        ImGui.TableSetColumnIndex(1)
        ImGui.SetNextItemWidth(ImGui.GetContentRegionAvail())
        sb.ui.aimSel = Widget.combo("##faim", sb.ui.aimSel, sb.ui.aimItems, #sb.ui.aimItems)
        sb.opt.fAim = sb.ui.aimSel

        ImGui.TableSetColumnIndex(2)
        if ImGui.Button(TL("Clear"), clearW, 0) then
            sb.ui.regionSel = 0
            sb.ui.aimSel = 0
            sb.opt.fMinPlayers = 0
            sb.opt.fMaxPlayers = sb.PLAYER_CAP
        end
        if sb.state.busy and sb.activeMode == "browser" then
            ImGui.SameLine()
            if ImGui.Button(TL("Stop Scan"), stopW, 0) then
                sb.requestStop("browser")
            end
        end
        if vibenet.optIn and not sb.state.busy and not vibenet.scanning then
            ImGui.SameLine()
            if ImGui.Button(TL("Opt Out"), optOutW, 0) then
                vibenet.setOptIn(false)
                vibenet.consentPending = false
                sb.toast(T("Opted out of VibeNet. Your RIDs are no longer shared."), 5000)
            end
            if ImGui.IsItemHovered() then
                ImGui.SetTooltip(T("Stops sharing Rockstar IDs with VibeNet."))
            end
        end

        ImGui.EndTable()
    end

    if ImGui.BeginTable("##VS_FilterPlayers", 2, ImGuiTableFlags.SizingStretchSame) then
        ImGui.TableNextRow()

        ImGui.TableSetColumnIndex(0)
        sb.opt.fMinPlayers = sb.fmtSlider("##fmin", sb.opt.fMinPlayers,
            0, sb.PLAYER_CAP, "min %d", ImGui.GetContentRegionAvail())

        ImGui.TableSetColumnIndex(1)
        sb.opt.fMaxPlayers = sb.fmtSlider("##fmax", sb.opt.fMaxPlayers,
            1, sb.PLAYER_CAP, "max %d", ImGui.GetContentRegionAvail())
        if sb.opt.fMaxPlayers < sb.opt.fMinPlayers then
            sb.opt.fMaxPlayers = sb.opt.fMinPlayers
        end

        ImGui.EndTable()
    end
end

function sessionBrowser.verifyJoinTarget(row)
    local sb = sessionBrowser

    if not sb.resolveAddresses() then
        return row.hostRid, nil
    end
    local jbuf = sb.allocJoinBuffers()
    if not jbuf then
        return row.hostRid, nil
    end

    local cands, seen = {}, {}
    local function add(rid)
        rid = math.tointeger(rid or 0) or 0
        if rid > 0 and not seen[rid] and #cands < sb.MAX_BATCH then
            seen[rid] = true
            cands[#cands + 1] = rid
        end
    end
    add(row.hostRid)
    if row.members then
        for _, rid in ipairs(row.members) do add(rid) end
    end
    if #cands == 0 then return row.hostRid, nil end

    local got = sb.resolveBatch(cands, jbuf)
    if #got == 0 then
        return nil, "Could not re-check that lobby - presence returned nothing. Rescan."
    end

    local want = sb.identity(row)

    local viaHost, viaMember
    for _, session in ipairs(got) do
        if sb.identity(session) == want then
            if session.viaRid == row.hostRid then
                viaHost = session
            elseif not viaMember then
                viaMember = session
            end
        end
    end

    local session = viaMember or viaHost
    if session then
        local freshHost = session.hostRid
        local note
        if freshHost and freshHost ~= 0 and row.hostRid and row.hostRid ~= 0 then
            if freshHost ~= row.hostRid then
                note = viaHost
                    and "This lobby migrated - the host you saw is still in it, but no longer hosting."
                    or "Host left and the lobby migrated; joining through a player still in there."
            end
        elseif session.token ~= row.token then
            note = "Host left and the lobby migrated; joining through a player still in there."
        end
        return session.viaRid, note, session
    end

    sb.logError("No join handle left: host=%s token=0x%X, all %d known player(s) "
        .. "resolved to another session", tostring(row.hostName), row.token, #cands)
    return nil, ("None of the %d player(s) we knew in that lobby are still in it - "
        .. "no way in from here. Rescan."):format(#cands), nil, true
end

function sessionBrowser.refreshRow(row, session)
    local sb = sessionBrowser
    if sb.state.busy then return false end
    local task = sb.detailSubmit({ session })
    if not task or not sb.awaitTask(task) then return false end
    local was = sb.identity(row)
    for _, fresh in ipairs(sb.detailCollect(task)) do
        if sb.identity(fresh) == was then
            for k, v in pairs(fresh) do
                if k ~= "members" and k ~= "viaRid" and k ~= "isOwn" then row[k] = v end
            end
            local now = sb.identity(row)
            if now ~= was then
                sb.cooldown[was] = nil
                sb.rowCache[was] = nil
            end
            sb.cooldown[now] = Time.GetEpoche()
            sb.rowCache[now] = row
            return true
        end
    end
    return false
end

function sessionBrowser.dropRow(row)
    local sb = sessionBrowser
    local key = sb.identity(row)
    if key ~= nil then
        sb.cooldown[key] = nil
        sb.rowCache[key] = nil
    end
    for mode, store in pairs(sb.resultStore) do
        local snap = {}
        for _, r in ipairs(store) do
            if r ~= row then snap[#snap + 1] = r end
        end
        sb.resultStore[mode] = snap
        if mode == sb.activeMode then
            sb.state.results = snap
            sb.state.answered = sb.listableCount(snap)
        end
    end
end

function sessionBrowser.joinLobby(row)
    local sb = sessionBrowser
    if not row or not row.hostRid or row.hostRid == 0 then
        sb.toast(T("This lobby has no readable host RID to join."), 5000)
        return
    end
    local mismatch = sb.rowIncompatible(row)
    if mismatch then
        sb.toast((T("That lobby is on a different %s - the host would refuse the join.")):format(mismatch), 7000)
        return
    end
    local joinFeat = rejoin.resolveBuiltin({ "Join Rockstar Id" })
    if not joinFeat then
        sb.toast(T("Cherax 'Join Rockstar Id' feature not found - cannot join."), 7000)
        return
    end
    if not FeatureMgr.GetFeature(rejoin.scapiRidHash) then
        sb.toast(T("Cherax SC-API Rockstar Id input not found - cannot join."), 7000)
        return
    end
    if sb.joinBusy then
        sb.toast(T("Already checking a lobby."), 4000)
        return
    end
    sb.toast(T("Confirming session still exists..."), 3000)
    Script.QueueJob(function()
        sb.joinBusy = true
        sb.joinRun(row, joinFeat)
        sb.joinBusy = false
    end)
end

function sessionBrowser.joinRun(row, joinFeat)
    local sb = sessionBrowser
    local rid, note, session, expired = sb.verifyJoinTarget(row)
    if not rid then
        if expired then sb.dropRow(row) end
        sb.toast(note or T("That lobby is gone. Rescan."), 6000)
        return
    end
    if session then sb.refreshRow(row, session) end

    if note then
        sb.toast(note, 7000)
    else
        sb.toast(T("Joining %s..."):format(tostring(row.hostName or rid)), 4000)
    end

    if ShouldUnload() or scriptUnloading then return end

    FeatureMgr.SetFeatureInt(rejoin.scapiRidHash, math.tointeger(rid) or 0)
    joinFeat:TriggerCallback()
    FeatureMgr.SetFeatureInt(rejoin.scapiRidHash, 0)

    sb.confirmJoinedDisc(math.tointeger(rid), row.disc)
end

function sessionBrowser.displayCap(row)
    return row.maxPlayers and sessionBrowser.PLAYER_CAP or nil
end

function sessionBrowser.fillColor(players, maxPlayers)
    local p = (maxPlayers and maxPlayers > 0) and (players / maxPlayers) or 0
    if p >= 0.75 then return { 120, 225, 130 } end
    if p >= 0.40 then return { 235, 205,  95 } end
    return { 165, 170, 185 }
end

;(function()
    local ps = { input = "", matches = {}, records = {}, busy = false, matching = 0, onlineNames = {},
