            tonumber(y), tonumber(m), tonumber(d), tonumber(hour), tonumber(minute), tonumber(second),
            tonumber((fraction .. "000"):sub(1, 3)))
    end
    function ps.closeLog(file, item)
        local from = math.max(0, item.offset - 65536)
        local data = item.offset > from and file:seek("set", from) and file:read(item.offset - from) or ""
        local last
        for stamp in ("\n" .. data):gmatch("\n%[(%d+%-%d+%-%d+ %d+:%d+:%d+%.%d+)%]") do last = stamp end
        last = last and ps.normalStamp(last)
        if not last then
            for _, rec in pairs(item.entries) do
                if rec.latest and (not last or rec.latest > last) then last = rec.latest end
            end
