        end
        rec.names = rec.names or {}
        if name ~= "" then
            local alias = rec.names[name] or { first = stamp, last = stamp }
            rec.names[name] = alias
            if stamp < alias.first then alias.first = stamp end
            if stamp > alias.last then alias.last = stamp end
        end
