                for _=1,reasons do
                    local reason,n,first,last;reason,n,first,last,pos=string.unpack("<s4I4s4s4",body,pos)
                    assert(#reason>0 and #reason<=200 and n>0 and #first<=64 and #last<=64 and first<=last
