        return item
    end
    function store.frame(kind,body)
        return string.pack("<BI4",kind,#body)..body..string.pack("<I4",(~#body)&0xFFFFFFFF)
    end
    function ps.loadBinaryHistory(path)
        return withFile(path or ps.binaryHistoryPath,"rb",function(file)
            if file:read(#store.magic)~=store.magic then return nil,"Unknown binary history version" end
            local generation=file:read(8)
            if not generation or #generation~=8 then return nil,"Missing binary generation" end
            local state={generation=string.unpack("<I8",generation),files={},updates=0,validBytes=#store.magic+8}
            local checkpoint=false
            while true do
                local prefix=file:read(5)
                if not prefix then break end
                local tag,size,body,tail,item,why
                if #prefix==5 then tag,size=string.unpack("<BI4",prefix) end
                if (tag==1 or tag==2) and size<=store.maxFrame then body=file:read(size) end
                if body and #body==size then tail=file:read(4) end
