    function store.equal(expected,actual)
        if store.count(expected)~=store.count(actual) then return false,"History source count changed during verification" end
        for path,item in pairs(expected) do
            local other=actual[path]
            if not other then return false,"History source missing after write" end
            if not (item.offset==other.offset and (item.cutSize or 0)==other.cutSize
                and (item.head or "")==other.head and item.endStamp==other.endStamp
                and (item.indexedArchive==true)==other.indexedArchive) then
                return false,"History metadata changed after write"
            end
            if not ((item.eventsReady==true)==(other.eventsReady==true)
                and (item.eventsUnavailable==true)==(other.eventsUnavailable==true)
                and (item.eventOffset or 0)==(other.eventOffset or 0) and item.edition==other.edition
                and (item.kicksReady==true)==(other.kicksReady==true)
                and (item.attacksReady==true)==(other.attacksReady==true)) then
