            end
            if store.count(item.entries)~=store.count(other.entries) then return false,"History player count changed after write" end
            for rid,rec in pairs(item.entries) do
                local copy=other.entries[rid]
                if not copy then return false,"History player missing after write" end
                for _,key in ipairs({"name","joins","leaves","join","leave"}) do
                    if (rec[key] or (key=="name" and "" or nil))~=copy[key] then return false,"History field changed after write: "..key end
                end
                if store.count(rec.names)~=store.count(copy.names) then return false,"History alias count changed after write" end
                for name,dates in pairs(rec.names or {}) do
                    local d=copy.names[name]
                    if not d or d.first~=dates.first or d.last~=dates.last then return false,"History alias changed after write" end
                end
                if #(rec.hostKicks or {})~=#(copy.hostKicks or {}) then return false,"Host kick count changed after write" end
                for i,stamp in ipairs(rec.hostKicks or {}) do
                    if stamp~=copy.hostKicks[i] then return false,"Host kick changed after write" end
                end
                if store.count(rec.attacks)~=store.count(copy.attacks) then return false,"Attack reason count changed after write" end
                for reason,row in pairs(rec.attacks or {}) do
                    local c=copy.attacks[reason]
                    if not c or c.count~=row.count or c.first~=row.first or c.last~=row.last then return false,"Attack changed after write" end
                end
                if #(rec.events or {})~=#(copy.events or {}) then return false,"Encounter count changed after write" end
                for i,event in ipairs(rec.events or {}) do
                    for _,key in ipairs({"stamp","kind","name","ip","via","peer"}) do
                        if event[key]~=copy.events[i][key] then return false,"Encounter field changed after write: "..key end
                    end
                    if i%32==0 then store.step() end
                end
                store.step()
            end
        end
        return true
    end
    function store.promote()
        local copied=withFile(store.pending,"rb",function(input)
            return withFile(ps.binaryHistoryPath,"wb",function(output)
                while true do
                    local body=input:read(65536); if not body then break end
                    if not output:write(body) then return false end
                    store.step()
                end
                return output:flush() and true
            end)
        end)
        if not copied then return false,"Could not promote binary history checkpoint" end
        local same=withFile(store.pending,"rb",function(input)
            return withFile(ps.binaryHistoryPath,"rb",function(output)
                while true do
                    local body=input:read(65536)
                    if body~=output:read(65536) then return false end
                    if not body then return true end
                    store.step()
                end
            end)
        end)
        if not same then return false,"Promoted binary history verification failed" end
        FileMgr.DeleteFile(store.pending)
        return true
    end
    function store.checkpoint()
        local h=ps.history
        h.phase,h.phaseDone,h.phaseTotal="Saving history",0,store.count(h.files)
        local generation=(h.generation or 0)+1
        local written,why=withFile(store.pending,"wb",function(file)
            if not file:write(store.magic..string.pack("<I8",generation)) then return false end
            local count=0
            for _,item in pairs(h.files) do
                local body,tooBig=store.encode(item)
                if not body then return false,tooBig end
                if not file:write(store.frame(1,body)) then return false end
                count=count+1
                h.phaseDone=count; store.step()
            end
            return file:write(store.frame(2,string.pack("<I4",count))) and file:flush() and true
        end)
        if not written then return false,why or "Could not write binary history checkpoint" end
        h.phase,h.phaseDone,h.phaseTotal="Verifying history",0,1
        local checked
        checked,why=ps.loadBinaryHistory(store.pending)
        if not checked or checked.tail then return false,"Binary history verification failed: "..tostring(why) end
        local ok
        ok,why=store.equal(h.files,checked.files)
        if not ok then return false,why end
        h.phase="Finishing history cache"
        ok,why=store.promote()
        if not ok then return false,why end
        h.generation,h.cacheBytes,h.baseBytes=generation,checked.bytes,checked.bytes
        h.needsCheckpoint,h.cacheTail,h.dirty,h.cacheUpdates=false,false,{},0
        return true
    end
    function ps.restoreHistory()
        local h=ps.history
        if h.storageLoaded then return true end
        local main,mainError=ps.loadBinaryHistory(ps.binaryHistoryPath)
        local pending=ps.loadBinaryHistory(store.pending)
        if pending and not pending.tail and pending.updates==0 and (not main or pending.generation>=main.generation) then
            local promoted,why=store.promote()
            if not promoted then return false,why end
            main=pending
        elseif main and FileMgr.DoesFileExist(store.pending) then FileMgr.DeleteFile(store.pending) end
        if main then
            h.files,h.generation,h.cacheBytes,h.baseBytes=main.files,main.generation,main.bytes,main.baseBytes
            h.cacheTail,h.cacheUpdates=main.tail,main.updates
        elseif FileMgr.DoesFileExist(ps.binaryHistoryPath) then
            return false,"Binary history unavailable: "..tostring(mainError)
        else
            h.needsCheckpoint=true
        end
        h.firstRun=not main
        h.dirty={}; h.storageLoaded=true
        h.indexEpoch=(h.indexEpoch or 0)+1; h.indexFiles=nil
        return true
    end
    function ps.saveHistoryFile(item,head)
        item.head=head or item.head or ""
        ps.history.files[item.path]=item
        ps.history.dirty=ps.history.dirty or {}; ps.history.dirty[item.path]=true
        ps.history.eventRevision=(ps.history.eventRevision or 0)+1
    end
    function ps.flushHistory()
        local h=ps.history
        if not h.storageLoaded then return true end
        if h.needsCheckpoint or h.cacheTail or (h.cacheBytes or 0)>(h.baseBytes or 0)+math.max(4*1048576,(h.baseBytes or 0)//2)
            or (h.cacheUpdates or 0)>1024 then return store.checkpoint() end
        if not next(h.dirty or {}) then return true end
        local frames={}
        for path in pairs(h.dirty) do
            local body,why=store.encode(h.files[path])
            if not body then return false,why end
            frames[#frames+1]=store.frame(1,body)
        end
        local before=withFile(ps.binaryHistoryPath,"rb",function(file) return file:seek("end") end)
        if before~=h.cacheBytes then return store.checkpoint() end
        h.cacheTail=true
        local appended=withFile(ps.binaryHistoryPath,"ab",function(file)
            for _,frame in ipairs(frames) do
                if not file:write(frame) then return false end
                store.step()
            end
            return file:flush() and true
        end)
        if not appended then return false,"Could not append binary history" end
        local verified=withFile(ps.binaryHistoryPath,"rb",function(file)
            if not file:seek("set",before) then return false end
            for _,frame in ipairs(frames) do
                if file:read(#frame)~=frame then return false end
                store.step()
            end
            return true
        end)
        if not verified then return false,"Binary history append verification failed" end
        for _,frame in ipairs(frames) do h.cacheBytes=h.cacheBytes+#frame end
        h.cacheUpdates=(h.cacheUpdates or 0)+#frames
        h.cacheTail,h.dirty=false,{}
        return true
    end
    function ps.indexHistoryItem(item)
        local h,path=ps.history,item.path
        h.byRid,h.nameMap,h.pathNames,h.pathRids=h.byRid or {},h.nameMap or {},h.pathNames or {},h.pathRids or {}
        local previousRids=h.pathRids[path] or {}
        h.archiveCount=(h.archiveCount or 0)-(previousRids.archive and 1 or 0)
        h.archiveCutCount=(h.archiveCutCount or 0)-(previousRids.cut and 1 or 0)
        h.archiveSkippedBytes=(h.archiveSkippedBytes or 0)-(previousRids.skipped or 0)
        for _,rid in ipairs(previousRids) do
            local sources=h.byRid[rid]
            if sources then sources[path]=nil; if not next(sources) then h.byRid[rid]=nil end end
            if _%32==0 then store.step() end
        end
        local previous=h.pathNames[path] or {}
        for i=1,#previous,2 do
            local key,rid=previous[i],previous[i+1]
            local row=h.nameMap[key]
            local account=row and row[rid]
            if account then
                account.refs=account.refs-1
                if account.refs==0 then row[rid]=nil end
                if not next(row) then h.nameMap[key]=nil end
            end
            if i%64==1 then store.step() end
        end
        local aliases,rids={},{}
        for rid,rec in pairs(item.entries) do
            local sources=h.byRid[rid] or {}; h.byRid[rid]=sources; sources[path]=item
            rids[#rids+1]=rid
            local seen={}
            local function add(name)
                if type(name)~="string" or name=="" then return end
                local key=name:lower(); if seen[key] then return end; seen[key]=true
                local row=h.nameMap[key]
                if not row then
                    row={}; h.nameMap[key]=row; h.nameVersion=(h.nameVersion or 0)+1
                    if not h.nameKeySet or not h.nameKeySet[key] then h.nameKeysDirty=true end
                end
                local account=row[rid] or {refs=0,name=name}; row[rid]=account; account.refs=account.refs+1
                aliases[#aliases+1]=key; aliases[#aliases+1]=rid
            end
            add(rec.name); for name in pairs(rec.names or {}) do add(name) end
            if #rids%32==0 then store.step() end
        end
        rids.archive=item.indexedArchive==true and path~=root.."\\Cherax.log"
        rids.cut=rids.archive and (item.cutSize or 0)>item.offset
        rids.skipped=rids.cut and item.cutSize-item.offset or 0
        h.archiveCount=h.archiveCount+(rids.archive and 1 or 0)
        h.archiveCutCount=h.archiveCutCount+(rids.cut and 1 or 0)
        h.archiveSkippedBytes=h.archiveSkippedBytes+rids.skipped
        h.pathNames[path],h.pathRids[path]=aliases,rids
    end
    function ps.ensureHistoryIndex()
        local h=ps.history
        while h.indexBuilding do
            if ShouldUnload() or scriptUnloading then return end
            Script.Yield(0)
        end
        if h.indexFiles==h.files then return end
        h.indexBuilding=true
        local files,epoch=h.files,h.indexEpoch
        h.byRid,h.nameMap,h.pathNames,h.pathRids={},{},{},{}
        h.archiveCount,h.archiveCutCount,h.archiveSkippedBytes=0,0,0
        h.nameKeysDirty,h.nameKeys,h.nameKeySet=true,nil,nil
        for _,item in pairs(files) do
            ps.indexHistoryItem(item)
            if h.phase=="Building player index" then h.phaseDone=h.phaseDone+1 end
            store.step()
        end
        h.indexFiles=h.indexEpoch==epoch and h.files==files and files or nil
        h.indexBuilding=false
        if h.indexFiles~=h.files then ps.ensureHistoryIndex() end
    end
    function ps.historySources(rid)
        local h=ps.history
        return h.indexFiles==h.files and (h.byRid[rid] or {}) or h.files
    end
    function ps.retainLive(item)
        if not item or item.offset==0 or not next(item.entries) then return end
        local hash=0xCBF29CE484222325
        for i=1,#(item.head or "") do hash=(hash~item.head:byte(i))*0x100000001B3 end
        local path=ps.cacheDir..("\\retained-live-%016X-%d.log"):format(hash,item.offset)
        if ps.history.files[path] then return end
        local copy={path=path,offset=item.offset,cutSize=item.cutSize,head=item.head,endStamp=item.endStamp or "",
            indexedArchive=true,entries=item.entries,eventsReady=item.eventsReady,eventOffset=item.eventOffset,
            eventsUnavailable=not item.eventsReady,edition=item.edition,kicksReady=item.kicksReady,
            attacksReady=item.attacksReady}
        ps.saveHistoryFile(copy,copy.head); ps.indexHistoryItem(copy)
    end
    function ps.memo(kind, rid, build)
        local h, m = ps.history, ps.memoState
        if not m or m.history ~= h or m.files ~= h.files or m.index ~= h.indexFiles
            or m.revision ~= h.eventRevision or m.records ~= ps.records
            or m.current ~= ps.current or m.live ~= ps.liveDetections then
            m = { history = h, files = h.files, index = h.indexFiles, revision = h.eventRevision,
                records = ps.records, current = ps.current, live = ps.liveDetections, values = {} }
            ps.memoState = m
        end
        local byRid = m.values[kind] or {}; m.values[kind] = byRid
        local value = byRid[rid]
        if value == nil then value = build(); byRid[rid] = value end
        return value
    end
    function ps.historyFor(rid)
        return ps.memo("history", rid, function() return ps.buildHistoryFor(rid) end)
    end
    function ps.buildHistoryFor(rid)
        local out = {}
        for _, item in pairs(ps.historySources(rid)) do
            local rec = item.entries[rid]
            if rec then
                if rec.latest and (not out.latest or rec.latest > out.latest) then
                    out.latest, out.name = rec.latest, rec.name
                end
                if rec.join and (not out.join or rec.join > out.join) then
                    out.join = rec.join
                end
                if rec.leave and (not out.leave or rec.leave > out.leave) then
                    out.leave = rec.leave
                end
                for _, stamp in ipairs(rec.hostKicks or {}) do
                    out.kickStamps = out.kickStamps or {}
                    if not out.kickStamps[stamp] then
                        out.kickStamps[stamp] = true
                        out.hostKicks = (out.hostKicks or 0) + 1
                        if not out.lastHostKick or stamp > out.lastHostKick then out.lastHostKick = stamp end
                        if not out.firstHostKick or stamp < out.firstHostKick then out.firstHostKick = stamp end
                    end
                end
            end
        end
        return out
    end
    function ps.namesFor(rid)
        return ps.memo("names", rid, function() return ps.buildNamesFor(rid) end)
    end
    function ps.buildNamesFor(rid)
        local names = {}
        local function add(name, first, last, source)
            if type(name) ~= "string" or name == "" then return end
            local row = names[name] or {name=name,sources={}}
            names[name] = row
            row.sources[source] = true
            if first and (not row.first or first < row.first) then row.first = first end
            if last and (not row.last or last > row.last) then row.last = last end
        end
        local function stamp(epoch)
            epoch = math.tointeger(tonumber(epoch) or 0)
            return epoch and epoch > 0 and epoch <= 4102444800
                and os.date("%Y-%m-%d %H:%M:%S.000",epoch) or nil
        end
        for path, item in pairs(ps.historySources(rid)) do
            local rec = item.entries[rid]
            if rec then
                for name, alias in pairs(rec.names or {}) do add(name,alias.first,alias.last,path) end
            end
        end
        local rec = ps.records[rid]
        if rec then
            add(rec.name,nil,stamp(rec.lastSeen),"Known player record")
            for source, data in pairs(rec.sources or {}) do
                if type(data)=="table" then add(data.name,nil,stamp(data.last_seen),source) end
            end
        end
        if ps.current and ps.current.rid==rid and ps.current.name then
            local time=stamp(ps.current.seenAt)
            add(ps.current.name,time,time,"Current lobby")
        end
        local rows={}
        for _, row in pairs(names) do rows[#rows+1]=row end
        table.sort(rows,function(a,b)
            if (a.last or "")~=(b.last or "") then return (a.last or "")>(b.last or "") end
            return a.name<b.name
        end)
        return rows
    end
    function ps.stampEpoch(stamp)
        local y, m, d, hour, minute, second = stamp:match("^(%d+)%-(%d+)%-(%d+) (%d+):(%d+):(%d+)")
        if not y then return nil end
        return os.time({ year = tonumber(y), month = tonumber(m), day = tonumber(d),
            hour = tonumber(hour), min = tonumber(minute), sec = tonumber(second) })
    end
    function ps.duration(seconds)
        if not seconds or seconds < 0 then return nil end
        seconds = math.floor(seconds)
        local days, hours = seconds // 86400, (seconds % 86400) // 3600
        local minutes, rest = (seconds % 3600) // 60, seconds % 60
        if days > 0 then return T("%dd %dh"):format(days, hours) end
        if hours > 0 then return T("%dh %dm"):format(hours, minutes) end
        if minutes > 0 then return T("%dm %ds"):format(minutes, rest) end
        return T("%ds"):format(rest)
    end
    function ps.formatTime(epoch, dayOnly, includeYear)
        local t = os.date("*t", epoch)
        local text = os.date("%b ", epoch) .. t.day
        if dayOnly or includeYear or t.year ~= os.date("*t").year then text = text .. ", " .. t.year end
        if dayOnly then return text end
        return ("%s, %d:%02d %s"):format(text, (t.hour - 1) % 12 + 1, t.min, T(t.hour < 12 and "AM" or "PM"))
    end
    function ps.timeAgo(stamp, largestOnly)
        local epoch = stamp and ps.stampEpoch(stamp)
        return epoch and ps.agoText(os.time() - epoch, largestOnly)
    end
    function ps.agoText(seconds, largestOnly)
        seconds = math.max(0, seconds)
        local days, hours, minutes = seconds // 86400, (seconds % 86400) // 3600, (seconds % 3600) // 60
        local text
        if days > 0 then
            text = T("%dd"):format(days)
            if hours > 0 and not largestOnly then text = T("%dd %dh"):format(days, hours) end
        elseif hours > 0 then
            text = T("%dh"):format(hours)
            if minutes > 0 and not largestOnly then text = T("%dh %dm"):format(hours, minutes) end
        elseif minutes > 0 then text = T("%dm"):format(minutes)
        else return T("Just now") end
        return T("%s ago"):format(text)
    end
    function ps.logEdition(head)
        local edition = ("\n" .. head):match("\n%[[^\r\n]+%] %[INFO%] Loading Cherax v%S+ (%u%u)%s")
        return edition == "LE" and "Legacy" or edition == "EE" and "Enhanced" or nil
    end
    function ps.pairEncounters(events)
        table.sort(events, function(a, b)
            if a.stamp ~= b.stamp then return a.stamp < b.stamp end
            return a.kind < b.kind
        end)
        local rows, open = {}, nil
        for _, event in ipairs(events) do
            if open and open.edition and event.edition and open.edition ~= event.edition then
                rows[#rows + 1], open = open, nil
            end
            if event.kind == "Player Joined" then
                if open then rows[#rows + 1] = open end
                open = { join = event.stamp, name = event.name, edition = event.edition,
                    ip = event.ip, via = event.via, peer = event.peer }
            elseif open then
                open.leave, open.name = event.stamp, open.name ~= "" and open.name or event.name
                open.edition = open.edition or event.edition
                if not open.via then open.ip, open.via, open.peer = event.ip, event.via, event.peer end
                rows[#rows + 1], open = open, nil
            else
                rows[#rows + 1] = { leave = event.stamp, name = event.name, edition = event.edition,
                    ip = event.ip, via = event.via, peer = event.peer }
            end
        end
        if open then rows[#rows + 1] = open end
        local total = 0
        for _, row in ipairs(rows) do
            if row.join and row.leave then
                local from, to = ps.stampEpoch(row.join), ps.stampEpoch(row.leave)
                if from and to and to >= from then row.seconds = to - from; total = total + row.seconds end
            end
        end
        for i = 1, #rows // 2 do rows[i], rows[#rows + 1 - i] = rows[#rows + 1 - i], rows[i] end
        return rows, total
    end
    function ps.loadEncounters(rid, swap)
        local enc={rid=rid,busy=true,rows={},joins=0,leaves=0,done=0,total=0,readBytes=0,totalBytes=0,
            revision=ps.history.eventRevision or 0}
        if swap then ps.encountersNext=enc else ps.encounters,ps.encountersNext=enc,nil end
        Script.QueueJob(function()
            ;(function()
                local events,paths={},{}
                for path,item in pairs(ps.historySources(rid)) do
                    if item.entries[rid] then paths[#paths+1]=path end
                end
                table.sort(paths);enc.total=#paths
                local function current() return ps.encounters==enc or ps.encountersNext==enc end
                for index,path in ipairs(paths) do
                    if not current() or ShouldUnload() or scriptUnloading then return end
                    local item=ps.history.files[path]
                    local rec=item and item.entries[rid] or {}
                    if item and not item.eventsReady then enc.partial=true end
                    local last
                    for i,event in ipairs(rec.events or {}) do
                        last=event
                        if #events<20000 then
                            events[#events+1]={stamp=event.stamp,kind=event.kind,name=event.name,edition=item.edition,
                                ip=event.ip,via=event.via,peer=event.peer}
                        else enc.capped=true end
                        if i%32==0 then store.step() end
                    end
                    if last and item and item.endStamp and item.endStamp~="" and last.kind=="Player Joined" then
                        if #events<20000 then
                            events[#events+1]={stamp=item.endStamp>last.stamp and item.endStamp or last.stamp,
                                kind="Player Left",name=last.name,edition=item.edition}
                        else enc.capped=true end
                    end
                    enc.done=index;store.step()
                end
                if not current() then return end
                local unique,seen={},{}
                for _,event in ipairs(events) do
                    local key=event.stamp..event.kind
                    if not seen[key] then seen[key]=event;unique[#unique+1]=event
                    else
                        seen[key].edition=seen[key].edition or event.edition
                        if not seen[key].via then seen[key].ip,seen[key].via,seen[key].peer=event.ip,event.via,event.peer end
                    end
                end
                for _,event in ipairs(unique) do
                    if event.kind=="Player Joined" then enc.joins=enc.joins+1 else enc.leaves=enc.leaves+1 end
                end
                enc.rows,enc.seconds=ps.pairEncounters(unique)
                enc.ips=ps.encounterIPs(enc.rows)
            end)()
            if ps.encountersNext==enc then
                ps.encountersNext=nil
                if ps.encounters and ps.encounters.rid==rid then enc.busy,ps.encounters=false,enc end
            elseif ps.encounters==enc then enc.busy=false end
        end)
    end
    function ps.startHistory(origin)
        local h = ps.history
        if h.busy then return end
        h.origin = origin
        h.busy, h.stop, h.done, h.bytes, h.cached, h.failed = true, false, 0, 0, 0, 0
        h.cutShort, h.skippedBytes, h.firstRun = 0, 0, false
        h.phase,h.phaseDone,h.phaseTotal="Restoring saved history",0,0
        h.progress=0
        h.status = "Discovering local Cherax logs..."
        Script.QueueJob(function()
            local ok, err = (function()
                FileMgr.CreateDir(ps.cacheDir)
                local restored, why = ps.restoreHistory()
                if not restored then return false, why end
                h.phase,h.phaseDone,h.phaseTotal="Building player index",0,store.count(h.files)
                ps.ensureHistoryIndex()
                h.cached,h.cutShort,h.skippedBytes=h.archiveCount or 0,h.archiveCutCount or 0,h.archiveSkippedBytes or 0
                local paths, seen = { root .. "\\Cherax.log" }, {}
                seen[paths[1]:lower()] = true
                for _, path in pairs(FileMgr.FindFiles(root .. "\\Logs", ".log", true) or {}) do
                    path = path:gsub("/", "\\")
                    if path:lower():match("cherax%.log$") and not seen[path:lower()] then
                        seen[path:lower()]=true
                        local item=h.files[path]
                        if not item or not item.indexedArchive or not item.eventsReady or not item.kicksReady
                            or not item.attacksReady then
                            paths[#paths+1]=path
                            if item and item.indexedArchive then
                                h.cached=h.cached-1
                                if (item.cutSize or 0)>item.offset then
                                    h.cutShort=h.cutShort-1;h.skippedBytes=h.skippedBytes-(item.cutSize-item.offset)
                                end
                            end
                        end
                    end
                end
                table.sort(paths, function(a, b)
                    if a == root .. "\\Cherax.log" then return true end
                    if b == root .. "\\Cherax.log" then return false end
                    local function dateKey(path)
                        local m, d, y, hour, minute, second = path:match(
                            "(%d%d)%-(%d%d)%-(%d%d%d%d)%-(%d%d)%-(%d%d)%-(%d%d) Cherax%.log$")
                        return y and (y .. m .. d .. hour .. minute .. second) or path
                    end
                    return dateKey(a) > dateKey(b)
                end)
                h.total = #paths
                h.phase,h.phaseDone,h.phaseTotal="Importing encounter history",0,#paths
                for _, path in ipairs(paths) do
                    if h.stop or ShouldUnload() or scriptUnloading then break end
                    local indexed = h.files[path]
                    if path ~= root .. "\\Cherax.log" and indexed and indexed.indexedArchive and indexed.eventsReady
                        and indexed.kicksReady and indexed.attacksReady then
                        h.cached = h.cached + 1
                        if (indexed.cutSize or 0) > indexed.offset then
                            h.cutShort = h.cutShort + 1
                            h.skippedBytes = h.skippedBytes + indexed.cutSize - indexed.offset
                        end
                    else
                        local file = io.open(path, "rb")
                        h.file = file
                        local size = file and file:seek("end")
                        if not size then h.failed = h.failed + 1
                        else
                            file:seek("set", 0)
                            local head = file:read(4096) or ""
                            local item = h.files[path]
                            local initialHead=item and item.head
                            local headMatches=item and (item.head==head or type(item.head)=="string"
                                and #item.head<4096 and head:sub(1,#item.head)==item.head)
                            if not item or item.offset > size or not headMatches then
                                ps.retainLive(item)
                                item = { path = path, offset = 0, entries = {},eventsReady=true,eventOffset=0,kicksReady=true,
                                    attacksReady=true }
                            end
                            item.head = head
                            local initialOffset = item.offset
                            local initialEventOffset=item.eventOffset
                            item.eventsUnavailable=nil
                            item.edition=item.edition or ps.logEdition(head)
                            local readOffset=item.offset
                            local initialCut = item.cutSize or 0
                            local cachedCut = item.cutSize == size and item.cutSize > 0
                                and size - item.offset >= ps.CRASH_TAIL_MIN
                            if item.offset == size or cachedCut then h.cached = h.cached + 1 end
                            h.files[path] = item
                            local backfilled = false
                            local needKicks, needAttacks = not item.kicksReady, not item.attacksReady
                            if needKicks or needAttacks then
                                local kickFound, attackFound, at, rest = {}, {}, 0, ""
                                local seeked = file:seek("set", 0)
                                if not seeked then h.failed = h.failed + 1 end
                                while seeked and at < item.offset and not h.stop and not ShouldUnload() and not scriptUnloading do
                                    local chunk = file:read(math.min(ps.HISTORY_READ_BYTES, item.offset - at))
                                    if not chunk then break end
                                    at, h.bytes = at + #chunk, h.bytes + #chunk
                                    local data = rest .. chunk
                                    local last = at >= item.offset and #data or data:match("^.*()\n")
                                    if last then
                                        if needKicks then ps.scanHostKicks(data, last, item, kickFound) end
                                        if needAttacks then ps.scanAttacks(data, last, item, attackFound, false) end
                                        rest = data:sub(last + 1)
                                    else rest = data end
                                    if #rest > 65536 then rest = rest:sub(-4096) end
                                    h.status = ("History %d/%d: kicks and attacks %.1f / %.1f MB; %.1f MB read this pass"):format(
                                        h.done + 1, h.total, at / 1048576, item.offset / 1048576, h.bytes / 1048576)
                                    store.step()
                                end
                                if at >= item.offset then
                                    if needKicks then
                                        for rid, stamps in pairs(kickFound) do item.entries[rid].hostKicks = stamps end
                                        item.kicksReady = true
                                    end
                                    if needAttacks then
                                        for rid, byReason in pairs(attackFound) do item.entries[rid].attacks = byReason end
                                        item.attacksReady = true
                                    end
                                    backfilled = true
                                end
                            end
                            local seeked = file:seek("set", readOffset)
                            if not seeked then h.failed = h.failed + 1 end
                            local tail, consumed = "", readOffset
                            local cutoff = cachedCut
                            local skipCrashTail = size >= ps.CRASH_TAIL_MIN
                            if not cachedCut then item.cutSize = 0 end
                            while seeked and consumed < size and not cutoff and not h.stop and not ShouldUnload() and not scriptUnloading do
                                local chunk = file:read(math.min(ps.HISTORY_READ_BYTES, size - consumed))
                                if not chunk then h.failed = h.failed + 1; break end
                                if consumed==0 then item.edition=ps.logEdition(chunk) or item.edition end
                                consumed, h.bytes = consumed + #chunk, h.bytes + #chunk
                                local dataStart = consumed - #chunk - #tail
                                local data = tail .. chunk
                                local exception = skipCrashTail and data:find("EXCEPTION BEGIN", 1, true)
                                if exception and size - (dataStart + exception - 1) >= ps.CRASH_TAIL_MIN then
                                    data = data:sub(1, exception - 1)
                                    cutoff, item.cutSize = true, size
                                end
                                local last = data:match("^.*()\n")
                                if last then
                                    local start,parsed = 1,0
                                    while true do
                                        local mark = data:find("[Player ", start, true)
                                        if not mark or mark > last then break end
                                        local stop = data:find("\n", mark, true)
                                        if not stop then break end
                                        local lineStart = mark
                                        while lineStart > 1 and data:byte(lineStart - 1) ~= 10 do lineStart = lineStart - 1 end
                                        ps.logEvent(data:sub(lineStart, stop - 1),item.entries,item)
                                        start = stop + 1
                                        parsed=parsed+1
                                        if parsed%32==0 then store.step() end
                                    end
                                    if item.kicksReady then
                                        local found = {}
                                        if ps.scanHostKicks(data, last, item, found) > 0 then
                                            for rid, stamps in pairs(found) do
                                                local rec = item.entries[rid]
                                                rec.hostKicks = rec.hostKicks or {}
                                                for _, stamp in ipairs(stamps) do
                                                    rec.hostKicks[#rec.hostKicks + 1] = stamp
                                                end
                                            end
                                        end
                                    end
                                    if item.attacksReady then
                                        local found = {}
                                        ps.scanAttacks(data, last, item, found, true)
                                        for rid, byReason in pairs(found) do
                                            local rec = item.entries[rid]
                                            rec.attacks = rec.attacks or {}
                                            for reason, row in pairs(byReason) do
                                                local old = rec.attacks[reason]
                                                if not old then rec.attacks[reason] = row
                                                else
                                                    old.count = old.count + row.count
                                                    if row.first < old.first then old.first = row.first end
                                                    if row.last > old.last then old.last = row.last end
                                                end
                                            end
                                        end
                                    end
                                    tail = data:sub(last + 1)
                                    item.eventOffset=dataStart+last
                                    item.offset = math.max(initialOffset,item.eventOffset)
                                else tail = data end
                                if #tail > 65536 then tail = tail:sub(-4096) end
                                h.status = ("History %d/%d: %.1f / %.1f MB; %.1f MB read this pass"):format(
                                    h.done + 1, h.total, consumed / 1048576, size / 1048576, h.bytes / 1048576)
                                h.fileName, h.fileBytes, h.fileSize = path:match("([^\\]+)$"), consumed, size
                                store.step()
                            end
                            if (item.eventOffset or 0)>=item.offset then item.eventsReady=true end
                            if cutoff then
                                h.cutShort = h.cutShort + 1
                                h.skippedBytes = h.skippedBytes + math.max(0, size - item.offset)
                            end
                            local closedNow = false
                            if path ~= root .. "\\Cherax.log" and not item.endStamp
                                and (consumed >= size or cutoff)
                                and not h.stop and not ShouldUnload() and not scriptUnloading then
                                ps.closeLog(file, item)
                                closedNow = true
                            end
                            local wasIndexed = item.indexedArchive
                            if path ~= root .. "\\Cherax.log" and (consumed >= size or cutoff)
                                and not h.stop and not ShouldUnload() and not scriptUnloading then
                                item.indexedArchive = true
                            end
                            if (item.offset ~= initialOffset or not indexed or (item.cutSize or 0) ~= initialCut
                                or initialHead~=head or closedNow or item.indexedArchive ~= wasIndexed
                                or initialEventOffset~=item.eventOffset or backfilled)
                                and not ShouldUnload() and not scriptUnloading then
                                ps.saveHistoryFile(item, head)
                                ps.indexHistoryItem(item)
                            end
                        end
                        if file then file:close(); h.file = nil end
                    end
                    h.fileName, h.fileBytes, h.fileSize = nil, nil, nil
                    h.done = h.done + 1
                    h.phaseDone=h.done
                    store.step()
                end
                if ShouldUnload() or scriptUnloading then return true end
                local flushed, why = ps.flushHistory()
                if not flushed then return false, why end
                h.status = ("%s: %d/%d active logs, %d cached, %d read/cache failures. %.1f MB read; %d crash tails omitted (%.1f GB, partial history)."):format(
                    h.stop and "Stopped (partial history)" or "History pass complete", h.done, h.total,
                    h.cached, h.failed, h.bytes / 1048576, h.cutShort, h.skippedBytes / 1073741824)
                return true
            end)()
            if h.file then h.file:close(); h.file = nil end
            h.busy = false
            if ok and not h.stop and h.failed==0 then h.progress=1 end
            if ps.nameQuery then ps.refreshMatches(ps.nameQuery) end
            if not ok then h.status = "History failed: " .. tostring(err) end
        end)
    end
    function ps.decodeJson(text)
        if type(text) ~= "string" then return nil, "expected JSON text" end
        local pos, parseValue, err = text:sub(1, 3) == "\239\187\191" and 4 or 1, nil, nil
        local escapes = { ['"']='"', ['\\']='\\', ['/']='/', b='\b', f='\f', n='\n', r='\r', t='\t' }
        local function fail(message) err = err or ("JSON %s at byte %d"):format(message, pos) end
        local function space()
            local _, last = text:find("^[ \t\r\n]*", pos)
            pos = last + 1
        end
        local function unicode()
            local digits = text:sub(pos, pos + 3)
            if not digits:match("^%x%x%x%x$") then return fail("invalid unicode escape") end
            pos = pos + 4
            return tonumber(digits, 16)
        end
        local function stringValue()
            pos = pos + 1
            local out = {}
            while pos <= #text do
                local c = text:sub(pos, pos); pos = pos + 1
                if c == '"' then return table.concat(out) end
                if c == '\\' then
                    local e = text:sub(pos, pos); pos = pos + 1
                    if escapes[e] then out[#out + 1] = escapes[e]
                    elseif e == 'u' then
                        local code = unicode()
                        if not code then return end
                        if code >= 0xD800 and code <= 0xDBFF then
                            if text:sub(pos, pos + 1) ~= '\\u' then return fail("missing low surrogate") end
                            pos = pos + 2
                            local low = unicode()
                            if not low then return end
                            if low < 0xDC00 or low > 0xDFFF then return fail("invalid low surrogate") end
                            code = 0x10000 + (code - 0xD800) * 0x400 + low - 0xDC00
                        elseif code >= 0xDC00 and code <= 0xDFFF then return fail("unpaired surrogate") end
                        out[#out + 1] = utf8.char(code)
                    else return fail("invalid escape") end
                else
                    if c:byte() < 32 then return fail("control character in string") end
                    out[#out + 1] = c
                end
            end
            return fail("unterminated string")
        end
        local function container(object, depth)
            pos = pos + 1
            local result, closing = {}, object and '}' or ']'
            space()
            if text:sub(pos, pos) == closing then pos = pos + 1; return result end
            while true do
                local key = #result + 1
                if object then
                    if text:sub(pos, pos) ~= '"' then return fail("expected object key") end
                    key = stringValue()
                    if err then return end
                    space()
                    if text:sub(pos, pos) ~= ':' then return fail("expected colon") end
                    pos = pos + 1
                end
                local value = parseValue(depth + 1)
                if err then return end
                result[key] = value; space()
                local c = text:sub(pos, pos); pos = pos + 1
                if c == closing then return result end
                if c ~= ',' then return fail("expected comma or closing bracket") end
                space()
            end
        end
        parseValue = function(depth)
            if depth > 128 then return fail("nesting limit exceeded") end
            space()
            local c = text:sub(pos, pos)
            if c == '"' then return stringValue() end
            if c == '{' or c == '[' then return container(c == '{', depth) end
            for token, value in pairs({ ['true']=true, ['false']=false, ['null']='null' }) do
                if text:sub(pos, pos + #token - 1) == token then
                    pos = pos + #token
                    if token == 'null' then return nil end
                    return value
                end
            end
            local first, last = text:find("^%-?%d+%.?%d*[eE]?[+%-]?%d*", pos)
            if first then
                local token = text:sub(first, last)
                local value = tonumber(token)
                if not value then return fail("invalid number") end
                pos = last + 1
                return value
            end
            return fail("unexpected token")
        end
        local result = parseValue(0)
        if err then return nil, err end
        space()
        if pos <= #text then fail("trailing content"); return nil, err end
        return result
    end
    function ps.presence(rids)
        local sb = sessionBrowser
        local wait = 1000
        while true do
            local task = sb.presenceSubmit(rids, ps.buf)
            if not task or not sb.awaitTask(task) then return nil, "Presence interrupted" end
            if task.state == sb.NET_STATUS_SUCCEEDED then return sb.presenceCollect(task) end
            if VIBESCRIPT_VERBOSE == true then VIBE_LOG_ERROR(("[PlayerSearch] presence failed for %d rid(s) (state %s, code %s); retrying in %dms"):format(
                #rids, tostring(task.state), tostring(task.code), wait)) end
            Script.Yield(wait)
            if ShouldUnload() or scriptUnloading then return nil, "Presence interrupted" end
            if ps.stop then return {} end
            wait = math.min(wait * 2, 30000)
        end
    end
    function ps.refreshRecords()
        local sb = sessionBrowser
        sb.ensureInit()
        sb.harvestSession()
        sb.harvestFriends()
        ps.records, ps.warnings = {}, {}
        for rid, rec in pairs(sb.known) do
            ps.records[rid] = { rid = rid, name = rec.name, lastSeen = rec.lastSeen, sources = {} }
        end
        for _, source in ipairs(sb.trackerFiles) do
            local path = sb.PATH_TRACKER .. "\\" .. source.file
            if FileMgr.DoesFileExist(path) then
                local records, parseError = ps.decodeJson(FileMgr.ReadFileContent(path))
                if type(records) == "table" then
                    for key, data in pairs(records) do
                        local rid = math.tointeger(key)
                        if rid and rid > 0 and type(data) == "table" then
                            local rec = ps.records[rid] or { rid = rid, sources = {} }
                            ps.records[rid] = rec
                            rec.sources[source.file] = data
                            if type(data.name) == "string" and (not rec.lastSeen
                                or (tonumber(data.last_seen) or 0) >= rec.lastSeen) then rec.name = data.name end
                            rec.lastSeen = math.max(rec.lastSeen or 0, tonumber(data.last_seen) or 0)
                        end
                    end
                else ps.warnings[#ps.warnings + 1] = source.file .. " could not be parsed: " .. clean(parseError or "not a JSON object") end
            end
        end
    end
    ps.dpPrev, ps.dpCur = {}, {}
    function ps.nameScore(name, query, pattern, bytes)
        if name == query then return 0 end
        local at = name:find(query, 1, true)
        if at == 1 then return 1 end
        if at then return 2 end
        if pattern then return name:find(pattern) and 3 or nil end
        local m = #query
        if m >= 3 then
            local pos = 1
            for i = 1, m do
                pos = name:find(query:sub(i, i), pos, true)
                if not pos then break end
                pos = pos + 1
            end
            if pos then return 4 end
        end
        local allowed = m >= 8 and 2 or m >= 4 and 1 or 0
        if allowed == 0 or #name < m - allowed then return nil end
        local prev, cur = ps.dpPrev, ps.dpCur
        for i = 0, m do prev[i] = i end
        local best = m
        for j = 1, #name do
            local c = name:byte(j)
            cur[0] = 0
            for i = 1, m do
                local value = prev[i - 1] + (bytes[i] == c and 0 or 1)
                local up, left = prev[i] + 1, cur[i - 1] + 1
                if up < value then value = up end
                if left < value then value = left end
                cur[i] = value
            end
            if cur[m] < best then best = cur[m] end
            prev, cur = cur, prev
        end
        return best <= allowed and 4 + best or nil
    end
    function ps.lowerNameBound(keys,query)
        local left,right=1,#keys+1
        while left<right do
            local mid=(left+right)//2
            if keys[mid]<query then left=mid+1 else right=mid end
        end
        return left
    end
    function ps.nameIndexes()
        ps.ensureHistoryIndex()
        local h=ps.history
        if h.nameKeysDirty then
            local keys,keySet,version={},{},h.nameVersion
            for key in pairs(h.nameMap) do keys[#keys+1]=key; keySet[key]=true end
            table.sort(keys)
            h.nameKeys,h.nameKeySet=keys,keySet
            h.nameKeysDirty=h.nameVersion~=version
        end
        if ps.recordIndexRecords~=ps.records then
            local map,records={},ps.records
            local function add(rid,name)
                if type(name)~="string" or name=="" then return end
                local key=name:lower(); local row=map[key] or {}; map[key]=row
                row[rid]=row[rid] or {name=name}
            end
            for rid,rec in pairs(records) do
                add(rid,rec.name)
                for _,data in pairs(rec.sources or {}) do if type(data)=="table" then add(rid,data.name) end end
                store.step()
            end
            local keys={}; for key in pairs(map) do keys[#keys+1]=key end; table.sort(keys)
            ps.recordNameMap,ps.recordNameKeys,ps.recordIndexRecords=map,keys,records
        end
        return {{keys=ps.recordNameKeys,map=ps.recordNameMap},{keys=h.nameKeys,map=h.nameMap}}
    end
    function ps.findNames(input,onPrefix,isStale)
        local found,seen,scores={},{},{}
        local query=input:lower()
        local pattern
        if query:find("[%*%?]") then
            pattern=query:gsub("[%^%$%(%)%%%.%[%]%+%-]","%%%0"):gsub("%*",".-"):gsub("%?",".")
        end
        local bytes,indexes,visited={query:byte(1,-1)},ps.nameIndexes(),0
        local function sort(rows)
            table.sort(rows,function(a,b)
                if a.score~=b.score then return a.score<b.score end
                if #a.name~=#b.name then return #a.name<#b.name end
                return a.rid<b.rid
            end)
        end
        local function add(key,row,prefix)
            if not row then return end
            local score=scores[key]
            if score==nil then
                score=prefix and (key==query and 0 or 1) or ps.nameScore(key,query,pattern,bytes) or false
                scores[key]=score
            end
            if score then
                for rid,account in pairs(row) do
                    local entry=seen[rid]
                    if not entry then
                        entry={rid=rid,name=account.name,score=score}; seen[rid]=entry; found[#found+1]=entry
                    elseif score<entry.score then entry.score,entry.name=score,account.name end
                end
            end
            visited=visited+1
            if visited%32==0 then store.step() end
        end
        if not pattern then
            for _,index in ipairs(indexes) do
                for i=ps.lowerNameBound(index.keys,query),#index.keys do
                    local key=index.keys[i]; if key:sub(1,#query)~=query then break end
                    add(key,index.map[key],true)
                    if isStale and isStale() then return {} end
                end
            end
            sort(found)
            if onPrefix then
                local ready={}; for i,row in ipairs(found) do ready[i]=row end
                onPrefix(ready)
            end
            if #found>50 then return found end
        end
        for _,index in ipairs(indexes) do
            for _,key in ipairs(index.keys) do
                if scores[key]==nil then add(key,index.map[key],false)
                else add(key,index.map[key],not pattern and key:sub(1,#query)==query) end
                if isStale and isStale() then return {} end
            end
        end
        sort(found); return found
    end
    function ps.refreshMatches(query)
        ps.matching = ps.matching + 1
        ps.matchVersion=(ps.matchVersion or 0)+1
        local version=ps.matchVersion
        local matches=ps.findNames(query,function(ready)
            if ps.nameQuery==query and ps.matchVersion==version then ps.matches=ready end
        end,function() return ps.nameQuery~=query or ps.matchVersion~=version end)
        ps.matching = ps.matching - 1
        if ps.nameQuery == query and ps.matchVersion==version then ps.matches = matches end
    end
    ps.sessionRows = {}
    function ps.enrichLocal(result, rid)
        local sb = sessionBrowser
        if not sb.supported or not Natives.InvokeBool(sb.N.IS_SIGNED_ONLINE) then return "offline" end
        if not sb.resolveAddresses() then return "no addresses" end
        local buf = sb.allocBuffers(ps)
        if not buf then return "no buffers" end
        ps.buf = buf
        local target
        for _, session in ipairs(ps.presence({rid}) or {}) do if session.viaRid == rid then target = session; break end end
        if not target or not target.sessionId or target.sessionId == 0 then return "no presence" end
        result.sessionId = target.sessionId
        local cached = ps.sessionRows[target.sessionId] or sb.rowCache[target.sessionId]
        if not cached then return "no cached host row" end
        if cached.hostRid ~= result.row.hostRid then return "cached row has another host" end
        for _, key in ipairs({"region", "natType", "maxPublic", "maxPrivate"}) do
            if result.row[key] == nil then result.row[key] = cached[key] end
        end
        return "ok"
    end
    function ps.scanMembers(result)
        local sb, pool, seen = sessionBrowser, {}, { [result.rid] = true }
        local function add(rid)
            if rid and rid > 0 and not seen[rid] and #pool < 300 then
                pool[#pool + 1], seen[rid] = rid, true
            end
        end
        add(result.hostRid)
        for _, rid in ipairs(sb.sessionRids()) do add(rid) end
        for _, rec in ipairs(sb.buildScanList(300)) do add(rec.rid) end
        result.rosterBusy, result.checked, result.rosterTotal = true, 0, #pool
        local confirmed = { [result.rid] = true }
        for _, batch in ipairs(sb.chunk(pool, sb.batchSize())) do
            if ps.stop or ShouldUnload() or scriptUnloading then break end
            local requested = {}
            for _, rid in ipairs(batch) do requested[rid] = true end
            local task = sb.presenceSubmit(batch, ps.buf)
            if not task or not sb.awaitTask(task) or task.state ~= sb.NET_STATUS_SUCCEEDED then
                result.rosterIncomplete = true
                VIBE_LOG_ERROR("[PlayerSearch] known lobby players presence request failed; retaining partial list")
                break
            end
            if ps.stop or ShouldUnload() or scriptUnloading then break end
            for _, session in ipairs(sb.presenceCollect(task)) do
                local rid = session.viaRid
                if requested[rid] and not confirmed[rid] and session.sessionId == result.sessionId then
                    result.members[#result.members + 1], confirmed[rid] = rid, true
                end
            end
            result.checked = result.checked + #batch
            Script.Yield(sb.opt.batchDelayMs or 50)
        end
        result.rosterIncomplete = result.rosterIncomplete or result.checked < #pool
        result.rosterBusy = false
    end
    function ps.inspect(rid)
        ps.fetchProfile(rid)
        if ps.busy then
            ps.pendingRid, ps.pendingSearch, ps.stop = rid, nil, true
            ps.status = "Switching player after the pending request finishes..."
            return
        end
        ps.busy, ps.error, ps.busySince = true, nil, Time.GetEpocheMs()
        if not ps.result or ps.result.rid ~= rid then ps.result = nil end
        ps.current, ps.liveDetections = nil, { rid = rid, rows = {} }
        ps.selected = rid
        Script.QueueJob(function()
            local sb = sessionBrowser
            local err = (function()
                ps.refreshLive(rid)
                local localResult = ps.localSession(rid)
                if localResult then
                    ps.result = localResult
                    ps.status = ""
                    ps.enrichLocal(localResult, rid)
                    return
                end
                ps.status = "Resolving player presence..."
                if not sb.supported then return "Presence unavailable for this edition" end
                if not Natives.InvokeBool(sb.N.IS_SIGNED_ONLINE) then return "Sign in to Rockstar services first" end
                local addr, why = sb.resolveAddresses()
                if not addr then return tostring(why) end
                local buf, bufWhy = sb.allocBuffers(ps)
                if not buf then return tostring(bufWhy) end
                ps.buf = buf
                local sessions, presenceError = ps.presence({rid})
                if not sessions then return presenceError end
                if ps.stop then ps.status = "Lookup stopped."; return end
                local target
                for _, session in ipairs(sessions) do if session.viaRid == rid then target = session; break end end
                local result = { rid = rid, seenAt = Time.GetEpoche(), members = {} }
                ps.result = result
                if not target then
                    ps.status = "No advertised session: offline, solo, out of session, or unavailable."
                    return
                end
                result.sessionId, result.hostRid = target.sessionId, target.hostRid
                result.members[1] = rid
                target.members = { rid }
                ps.status = "Presence found; querying the session host..."
                result.detailPending = true
                local task = sb.detailSubmit({ target }, ps.buf)
                if not task or not sb.awaitTask(task) then return "Host query interrupted" end
                for _, row in ipairs(sb.detailCollect(task)) do
                    if row.sessionId == result.sessionId then
                        result.row, ps.sessionRows[row.sessionId] = row, row
                        break
                    end
                end
                result.detailPending = false
                ps.scanMembers(result)
                ps.status = "Search complete. Presence and history are snapshots."
                if not result.row then ps.status = ps.status .. " Host detail unavailable; lobby type/count unknown." end
            end)()
            ps.busy, ps.stop = false, false
            if ps.result and ps.result.rid == rid then ps.result.rosterBusy = false end
            if err then
                ps.status = "Search failed: " .. err; ps.error = T("Lookup failed: %s"):format(err)
                VIBE_LOG_ERROR("[PlayerSearch] lookup failed: " .. err)
            end
            local input, nextRid = ps.pendingSearch, ps.pendingRid
            ps.pendingSearch, ps.pendingRid = nil, nil
            if not ShouldUnload() and not scriptUnloading then
                if input then ps.input = input; ps.search()
                elseif nextRid then ps.inspect(nextRid) end
            end
        end)
    end
    ps.SC_NAME_BOX, ps.SC_SEARCH, ps.SC_RESULTS, ps.SC_COPY = 1418003384, 135319631, 463146006, 267315836
    local function listKey(list) return table.concat(list or {}, "\n") end
    function ps.onlineSearch(query)
        local online = { query = query, busy = true, names = {}, rids = {} }
        ps.online = online
        Script.QueueJob(function()
            local started = Time.GetEpocheMs()
            local err = (function()
                local box, button = FeatureMgr.GetFeature(ps.SC_NAME_BOX), FeatureMgr.GetFeature(ps.SC_SEARCH)
                local results = FeatureMgr.GetFeature(ps.SC_RESULTS)
                if not (box and button and results) then return "Cherax's player search was not found." end
                local before = listKey(results:GetList())
                local limit = (tostring(box:GetStringValue()):lower() == query:lower() and before ~= "") and 1500 or 8000
                box:SetStringValue(query)
                button:OnClick()
                while ps.online == online and Time.GetEpocheMs() - started < limit
                    and not ShouldUnload() and not scriptUnloading do
                    if listKey(results:GetList()) ~= before then break end
                    Script.Yield(50)
                end
                if ps.online ~= online then return end
                for index, name in ipairs(results:GetList() or {}) do online.names[index] = tostring(name) end
            end)()
            if ps.online ~= online then return end
            online.busy = false
            online.error = err
            if err then VIBE_LOG_ERROR(("[PlayerSearch] online query %q failed: %s"):format(query, err)) end
        end)
    end
    function ps.resolveOnline(online, index)
        if online.resolving then return end
        if online.rids[index] then ps.inspect(online.rids[index]); return end
        online.resolving, online.error, online.clipAt, online.clipTries = index, nil, nil, 0
        online.savedClip = tostring(ImGui.GetClipboardText() or "")
        Script.QueueJob(function()
            local err = (function()
                local results, copy = FeatureMgr.GetFeature(ps.SC_RESULTS), FeatureMgr.GetFeature(ps.SC_COPY)
                if not (results and copy) then return "Cherax's player search was not found." end
                if (results:GetList() or {})[index] ~= online.names[index] then
                    return "Cherax's search list changed. Search again."
                end
                results:SetListIndex(index - 1)
                Script.Yield(50)
                online.copyAt = Time.GetEpocheMs()
                copy:OnClick()
            end)()
            if not err then online.clipAt = Time.GetEpocheMs() + 150; return end
            online.resolving, online.error = nil, err
            VIBE_LOG_ERROR(("[PlayerSearch] online resolve name=%q index=%d failed: %s"):format(
                tostring(online.names[index]), index, tostring(err)))
        end)
    end
    function ps.readOnlineClip(online)
        local index = online.resolving
        if not index or not online.clipAt or Time.GetEpocheMs() < online.clipAt then return end
        online.clipTries = online.clipTries + 1
        local clip = tostring(ImGui.GetClipboardText() or "")
        local rid = math.tointeger(tonumber(clip:match("^%s*(%d+)%s*$")))
        if (not rid or rid <= 0 or clip == online.savedClip) and online.clipTries < 4 then
            online.clipAt = Time.GetEpocheMs() + 200
            return
        end
        if clip ~= online.savedClip then ImGui.SetClipboardText(online.savedClip) end
        online.resolving, online.clipAt, online.savedClip = nil, nil, nil
        if not rid or rid <= 0 then online.error = "Cherax did not return a Rockstar ID."; return end
        online.rids[index] = rid
        ps.onlineNames[rid] = online.names[index]
        if ps.online == online then ps.inspect(rid) end
    end
    EventMgr.RegisterHandler(eLuaEvent.ON_NOTIFICATION, function(...)
        local online = ps.online
        if not (online and online.copyAt) then return false end
        if Time.GetEpocheMs() - online.copyAt > 2000 then online.copyAt = nil; return false end
        local first, second = ...
        local title, text
        if type(first) == "table" then
            title = first.title or first.Title or first.name
            text = first.message or first.Message or first.text or first.Text
        else
            title, text = first, second
        end
        local joined = (tostring(title or "") .. " " .. tostring(text or "")):lower()
        if not joined:find("rockstar id", 1, true) then return false end
        online.copyAt = nil
        return true
    end)
    function ps.search()
        ps.error = nil
        local input = ps.input:match("^%s*(.-)%s*$")
        if input == "" then return end
        if ps.busy then
            ps.pendingSearch, ps.pendingRid, ps.stop = input, nil, true
            ps.status = "New search queued; finishing the pending request..."
            return
        end
        telemetryCountAction("PlayerSearch")
        ps.startHistory("search")
        Script.QueueJob(function()
            ps.refreshRecords()
            if input:match("^%d+$") then
                ps.nameQuery, ps.online = nil, nil
                local rid = math.tointeger(input)
                if rid and rid > 0 then ps.matches = {}; ps.inspect(rid)
                else ps.error = T("Invalid Rockstar ID.") end
            else
                ps.selected, ps.result = nil, nil
                ps.nameQuery, ps.matches = input, {}
                ps.onlineSearch(input)
                ps.refreshMatches(input)
                ps.status = "Select a known-name match; refresh matches as history is indexed."
            end
        end)
    end
    function ps.lobbyLabel(row)
        if row.localLabel then return row.localLabel end
        if row.maxPublic == 0 then return "Invite Only" end
        if sessionBrowser.rowIsJob(row) then return "Activity / non-freemode reported" end
        if row.closedCrew then return "Closed Crew Session" end
        if row.closedFriends then return "Friends Only" end
        if row.crewSession then return "Crew Session" end
        if row.visible == false then return "Access unconfirmed" end
        if row.visible == true and (row.maxPublic or 0) >= sessionBrowser.PLAYER_CAP
            and row.maxPublic <= sessionBrowser.SESSION_SLOTS then return "Public session" end
        return "Lobby type unconfirmed"
    end
    function ps.localSession(rid)
        local sb = sessionBrowser
        if not Natives.InvokeBool(sb.N.IS_SESSION_ACTIVE) then return nil end
        local members, names, slots, found = {}, {}, {}, false
        local bosses, away = 0, 0
        for pid=0,31 do
            local ok, info = pcall(function()
                if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then return end
                local player = Players.GetById(pid)
                local gamer = player and player:GetGamerInfo()
                local id = gamer and math.tointeger(gamer.RockstarId or 0)
                if id and id > 0 then return {rid=id,name=player:GetName()} end
            end)
            if ok and info then
                slots[pid], names[info.rid] = info.rid, info.name
                members[#members+1] = info.rid
                if info.rid==rid then found=true end
                if getOrgBoss(pid) == pid then bosses = bosses + 1 end
                if Natives.InvokeBool(sb.N.PLAYER_STARTED_TRANSITION, pid) then away = away + 1 end
            end
        end
        if not found then return nil end
        local hostPid=Natives.InvokeInt(sb.N.GET_HOST_PLAYER_INDEX)
        local hostRid=slots[hostPid]
        local players=Natives.InvokeInt(sb.N.GET_NUM_CONNECTED_PLAYERS)
        if not players or players<1 or players>32 then players=#members end
        local row={players=players,hostRid=hostRid,hostName=hostRid and names[hostRid],live=true,
            visible=Natives.InvokeBool(sb.N.SESSION_IS_VISIBLE),
            closedFriends=Natives.InvokeBool(sb.N.SESSION_IS_CLOSED_FRIENDS),
            closedCrew=Natives.InvokeBool(sb.N.SESSION_IS_CLOSED_CREW),bosses=bosses,awayInJobs=away}
        row.crewSession = row.closedCrew
        if row.crewSession then
            row.closedCrew = Natives.InvokeInt(sb.N.SESSION_UNIQUE_CREW_LIMIT) <= 1
        end
        local aim = Natives.InvokeInt(sb.N.HOST_AIM_PREFERENCE)
        if aim and aim >= 0 and aim <= 3 then row.freeAim = aim >= 2 end
        if Natives.InvokeBool(sb.N.IS_ACTIVITY_SESSION) then row.localLabel="Activity session"
        elseif Natives.InvokeBool(sb.N.SESSION_IS_SOLO) then row.localLabel="Solo session"
        elseif row.closedFriends then row.localLabel="Friends-only session"
        elseif row.closedCrew then row.localLabel="Closed Crew Session"
        elseif row.crewSession then row.localLabel="Crew Session"
        elseif Natives.InvokeBool(sb.N.SESSION_IS_PRIVATE) then row.localLabel="Private session"
        elseif row.visible then row.localLabel="Public session"
        else row.localLabel="Session access unconfirmed" end
        return {rid=rid,seenAt=Time.GetEpoche(),row=row,hostRid=hostRid,
            members=members,memberNames=names,localSession=true,checked=0}
    end
    function ps.normalizeDetections(raw)
        local rows, byName = {}, {}
        local function add(name, count, lastTime)
            if type(name) ~= "string" or name == "" then return end
            local row = { name = name, count = tonumber(count), lastTime = tonumber(lastTime) }
            local old = byName[name]
            if old then
                if old.count or row.count then old.count = math.max(old.count or 0, row.count or 0) end
                if old.lastTime or row.lastTime then old.lastTime = math.max(old.lastTime or 0, row.lastTime or 0) end
            else rows[#rows + 1], byName[name] = row, row end
        end
        local function record(value, key)
            if type(value) == "string" then add(value)
            elseif type(value) == "number" then
                if type(key) == "string" and key ~= "count" and key ~= "lastTime"
                    and key ~= "last_time" then add(key, value) end
            elseif type(value) == "table" then
                local name = value.name or value.reason or value.detection or value[1]
                if type(name) ~= "string" and type(key) == "string" then name = key end
                add(name, value.count or value[2], value.lastTime or value.last_time or value[3])
            end
        end
        if type(raw) == "string" then add(raw)
        elseif type(raw) == "table" then
            if type(raw.name or raw.reason or raw.detection) == "string"
                or (type(raw[1]) == "string" and (raw[2] == nil or type(raw[2]) == "number")
                    and (raw[3] == nil or type(raw[3]) == "number")) then record(raw)
            else for key, value in pairs(raw) do record(value, key) end end
        end
        table.sort(rows, function(a, b) return a.name:lower() < b.name:lower() end)
        return rows
    end
    function ps.refreshLive(rid)
        local ok, current = pcall(function()
            local player = Players.GetByRockstarId(rid)
            return player and { rid = rid, name = player:GetName(), pid = player.PlayerId } or { rid = rid }
        end)
        ps.current = ok and current or { rid = rid, error = tostring(current) }
        ps.current.seenAt = Time.GetEpoche()
        local snapshot = { rid = rid, rows = {}, seenAt = Time.GetEpoche() }
        local raw, count, lastTime = ModderDB.GetModderDetections(rid)
        if type(raw) == "string" and type(count) == "number" then raw = {raw, count, lastTime} end
        snapshot.rows = ps.normalizeDetections(raw)
        if raw ~= nil and type(raw) ~= "table" and type(raw) ~= "string" then
            snapshot.error = "Cherax returned an unsupported detection format."
        end
        ps.liveDetections = snapshot
    end
