    local function date(value, includeYear)
        local epoch = math.tointeger(tonumber(value) or 0)
        if epoch and epoch > 0 and epoch <= 4102444800 then return ps.formatTime(epoch, false, includeYear) end
        return value ~= nil and clean(value) or "Unknown"
    end
    local function logDate(value, dayOnly)
        local epoch = value and ps.stampEpoch(value)
        if epoch then return ps.formatTime(epoch, dayOnly) end
        return value and (value:gsub("%.%d+$", "")) or "Not found yet"
    end
    local function logDateAgo(value, largestOnly)
        local ago = ps.timeAgo(value, largestOnly)
        return ago and ("%s (%s)"):format(logDate(value), ago) or logDate(value)
    end
    local function fields(id, values)
        local valueX
        if ImGui.BeginTable(id, 2, ImGuiTableFlags.SizingStretchProp) then
            ImGui.TableSetupColumn("Label", FIXED)
            ImGui.TableSetupColumn("Value", STRETCH)
            for _, item in ipairs(values) do
                ImGui.TableNextRow()
                ImGui.TableSetColumnIndex(0); muted(T(item[1]))
                ImGui.TableSetColumnIndex(1)
                valueX = valueX or ImGui.GetCursorPosX()
                local full = clean(item[2] ~= nil and item[2] or T("Unknown"))
                local display = full
                if item[4] then
                    local available = math.max(0, ImGui.GetContentRegionAvail() - 4)
                    if ImGui.CalcTextSize(display) > available then
                        for _, candidate in ipairs(item[4]) do
                            candidate = clean(candidate)
                            display = candidate
                            if ImGui.CalcTextSize(candidate) <= available then break end
                        end
                    end
                end
                wrapped(display, item[3])
            end
            ImGui.EndTable()
        end
        return valueX
    end
    function ps.ipFor(rec)
        local direct, other
        for _, data in pairs(rec and rec.sources or {}) do
            local raw = type(data) == "table" and type(data.ip) == "string" and data.ip or ""
            local seen = tonumber(data.last_seen) or 0
            local isDirect = raw:match("^%d+%.%d+%.%d+%.%d+%s*%(Direct%)$") ~= nil
            if isDirect and (not direct or seen > direct.seen) then direct = { ip = raw, seen = seen }
            elseif not isDirect and raw:match("^%d+%.%d+%.%d+%.%d+") and (not other or seen > other.seen) then
                other = { ip = raw, seen = seen }
            end
        end
        if direct then return direct.ip, true end
        return other and other.ip, false
    end
    function ps.parseAddress(line)
        local ip, via, rest = line:match("| %d+ | (%d+%.%d+%.%d+%.%d+) %((%a+)(.-)%)%s*$")
        if not ip then return nil end
        return ip, via, via == "Peer" and rest:match("^ | (.+)$") or nil
    end
    function ps.isPublicIP(ip)
        local a, b, c, d = tostring(ip or ""):match("^(%d+)%.(%d+)%.(%d+)%.(%d+)$")
        a, b, c, d = tonumber(a), tonumber(b), tonumber(c), tonumber(d)
        if not d or a > 255 or b > 255 or c > 255 or d > 255 then return false end
        return not (a == 0 or a == 10 or a == 127 or a >= 224 or (a == 100 and b >= 64 and b <= 127)
            or (a == 169 and b == 254) or (a == 172 and b >= 16 and b <= 31) or (a == 192 and b == 168))
    end
    function ps.encounterIPs(rows)
        local list, byIP = { hidden = 0 }, {}
        for _, row in ipairs(rows) do
            if row.via == "Direct" and ps.isPublicIP(row.ip) then
                local item = byIP[row.ip]
                if not item then
                    item = { ip = row.ip, sessions = 0 }
                    byIP[row.ip], list[#list + 1] = item, item
                end
                item.sessions = item.sessions + 1
                local stamp = row.join or row.leave
                if stamp and (not item.last or stamp > item.last) then item.last = stamp end
            elseif row.via then list.hidden = list.hidden + 1 end
        end
        table.sort(list, function(a, b) return (a.last or "") > (b.last or "") end)
        return list
    end
    ps.geo = { cache = {}, queue = {}, queued = {}, sent = {}, pausedUntil = 0, failures = 0 }
    ps.GEO_URL = "http://ip-api.com/batch?fields=status,query,country,regionName,city,isp,org,as,mobile,proxy,hosting"
    ps.GEO_PER_MINUTE = 14
    function ps.readLines(path, fn)
        local file = io.open(path, "rb")
        if not file then return end
        local text = file:read("a") or ""
        file:close()
        for line in text:gmatch("[^\r\n]+") do
            local f = {}
            for value in (line .. "|"):gmatch("(.-)|") do f[#f + 1] = value end
            fn(f)
        end
    end
    function ps.loadGeo()
        local g = ps.geo
        if g.loaded then return end
        g.loaded = true
        ps.readLines(ps.cacheDir .. "\\ip_geo.tsv", function(f)
            if ps.isPublicIP(f[1]) then
                g.cache[f[1]] = { country = f[2], region = f[3], city = f[4], isp = f[5], org = f[6], as = f[7],
                    mobile = f[8] == "1", proxy = f[9] == "1", hosting = f[10] == "1", failed = f[11] == "1" }
            end
        end)
        ps.readLines(ps.cacheDir .. "\\ipapi_limits.txt", function(f)
            g.pausedUntil, g.failures = tonumber(f[1]) or 0, tonumber(f[2]) or 0
            for t in (f[3] or ""):gmatch("%d+") do g.sent[#g.sent + 1] = tonumber(t) end
        end)
    end
    function ps.saveGeo(limitsOnly)
        local g = ps.geo
        FileMgr.CreateDir(ps.cacheDir)
        local function write(name, text)
            local file = io.open(ps.cacheDir .. "\\" .. name, "wb")
            if file then file:write(text); file:close() end
        end
        local sent = {}
        for i, t in ipairs(g.sent) do sent[i] = ("%d"):format(math.floor(t)) end
        write("ipapi_limits.txt", ("%d|%d|%s"):format(math.floor(g.pausedUntil), g.failures, table.concat(sent, ",")))
        if limitsOnly then return end
        local lines = {}
        local function field(value) return (clean(value):gsub("|", "/")) end
        local function flag(value) return value and "1" or "0" end
        for ip, geo in pairs(g.cache) do
            lines[#lines + 1] = table.concat({ ip, field(geo.country), field(geo.region), field(geo.city),
                field(geo.isp), field(geo.org), field(geo.as), flag(geo.mobile), flag(geo.proxy),
                flag(geo.hosting), flag(geo.failed) }, "|")
        end
        table.sort(lines)
        write("ip_geo.tsv", table.concat(lines, "\n"))
    end
    function ps.geoWait(now)
        local g, recent = ps.geo, {}
        for _, t in ipairs(g.sent) do
            if now - t < 61000 then recent[#recent + 1] = t end
        end
        g.sent = recent
        local wait = math.max(0, g.pausedUntil - now)
        if #recent >= ps.GEO_PER_MINUTE then
            wait = math.max(wait, recent[#recent - ps.GEO_PER_MINUTE + 1] + 61000 - now)
        end
        return wait
    end
    function ps.queueGeo(ips)
        local g = ps.geo
        for index = #ips, 1, -1 do
            local ip = ips[index].ip
            if not g.cache[ip] and not g.queued[ip] then
                g.queued[ip] = true
                table.insert(g.queue, 1, ip)
            end
        end
        if g.busy or #g.queue == 0 then return end
        g.busy = true
        Script.QueueJob(function()
            ps.runGeo()
            g.busy, g.lookingUp, g.waitUntil = false, nil, nil
        end)
    end
    function ps.runGeo()
        local g = ps.geo
        ps.loadGeo()
        while #g.queue > 0 and not ShouldUnload() and not scriptUnloading do
            local batch, rest = {}, {}
            for _, ip in ipairs(g.queue) do
                if g.cache[ip] then g.queued[ip] = nil
                elseif #batch < 100 then batch[#batch + 1] = ip
                else rest[#rest + 1] = ip end
            end
            local now = Time.GetEpocheMs()
            local wait = #batch > 0 and ps.geoWait(now) or 0
            if wait > 0 then
                g.queue, g.waitUntil = batch, now + wait
                for _, ip in ipairs(rest) do g.queue[#g.queue + 1] = ip end
                Script.Yield(math.min(wait, 5000))
            else
                g.queue, g.waitUntil = rest, nil
                if #batch == 0 then break end
                g.sent[#g.sent + 1] = now
                ps.saveGeo(true)
                local quoted = {}
                for i, ip in ipairs(batch) do quoted[i] = '"' .. ip .. '"' end
                g.lookingUp = #batch
                local body = ps.scGet(ps.GEO_URL, nil, "[" .. table.concat(quoted, ",") .. "]")
                g.lookingUp = nil
                local results = body and body:find("^%s*%[") and ps.decodeJson(body)
                if type(results) ~= "table" then
                    g.failures = g.failures + 1
                    g.pausedUntil = Time.GetEpocheMs() + (g.failures >= 3 and 3600 or 61) * 1000
                    for index = #batch, 1, -1 do table.insert(g.queue, 1, batch[index]) end
                    ps.saveGeo(true)
                    VIBE_LOG_ERROR(("[PlayerSearch] ip-api batch of %d refused (strike %d); paused %ds"):format(
                        #batch, g.failures, g.failures >= 3 and 3600 or 61))
                else
                    g.failures = 0
                    for _, r in ipairs(results) do
                        if type(r) == "table" and type(r.query) == "string" then
                            g.cache[r.query] = { country = r.country or "", region = r.regionName or "",
                                city = r.city or "", isp = r.isp or "", org = r.org or "", as = r.as or "",
                                mobile = r.mobile == true, proxy = r.proxy == true, hosting = r.hosting == true,
                                failed = r.status ~= "success" }
                        end
                    end
                    for _, ip in ipairs(batch) do g.queued[ip] = nil end
                    ps.saveGeo()
                end
            end
        end
    end
    function ps.connectionType(geo)
        local operator = KICKER.hostingOperator(geo)
        if operator then return T("VPN / hosting"), true, T("Known VPN or hosting operator: %s"):format(operator) end
        if geo.hosting then return T("Hosting"), true, T("ip-api flags this address as a datacenter.") end
        if geo.proxy then return T("VPN / proxy"), true, T("ip-api flags this address as a VPN or proxy.") end
        if geo.mobile then return T("Mobile"), false, T("ip-api flags this address as a mobile carrier.") end
        return T("Residential"), false, T("No VPN, proxy or hosting match.")
    end
    function ps.clip(text, max)
        local length = utf8.len(text)
        if length and length > max then return text:sub(1, utf8.offset(text, max) - 1) .. "…", true end
        return text, false
    end
    function ps.fit(text, width)
        if width <= 0 or ImGui.CalcTextSize(text) <= width then return text, false end
        for count = (utf8.len(text) or #text) - 1, 1, -1 do
            local cut = ps.clip(text, count)
            if ImGui.CalcTextSize(cut) <= width then return cut, true end
        end
        return "…", true
    end
    function ps.addressText(row)
        if row.via == "Direct" then return row.ip end
        if row.via == "Peer" and row.peer then return T("Via %s"):format(row.peer) end
        if row.via == "Relay" then return T("Relay") end
        return T("Unknown")
    end
    function ps.geoStatus()
        local g, now = ps.geo, Time.GetEpocheMs()
        if g.lookingUp then return T("Looking up %d IP(s) with ip-api.com"):format(g.lookingUp) end
        if g.pausedUntil > now and #g.queue > 0 then
            return T("ip-api.com refused the request; retrying in %s"):format(ps.duration((g.pausedUntil - now) / 1000))
        end
        if g.waitUntil and g.waitUntil > now and #g.queue > 0 then
            return T("Waiting %s for the ip-api.com rate limit"):format(ps.duration((g.waitUntil - now) / 1000))
        end
    end
    function ps.detectionRows(rec, rid)
        return ps.memo("detections", rid, function() return ps.buildDetectionRows(rec, rid) end)
    end
    function ps.buildDetectionRows(rec, rid)
        local combined = {}
        for _, data in pairs(rec and rec.sources or {}) do
            if type(data) == "table" then
                for _, det in ipairs(ps.normalizeDetections(data.detections)) do combined[#combined+1] = det end
            end
        end
        local snapshot = ps.liveDetections and ps.liveDetections.rid == rid and ps.liveDetections
        for _, det in ipairs(snapshot and snapshot.rows or {}) do combined[#combined+1] = det end
        local hist = ps.historyFor(rid)
        local hostKick = T("Host kicked you")
        if hist.hostKicks then
            combined[#combined+1] = { name = hostKick, count = hist.hostKicks,
                lastTime = hist.lastHostKick and ps.stampEpoch(hist.lastHostKick) }
        end
        local rows, firsts = ps.normalizeDetections(combined), ps.attackFirsts(rid)
        for _, det in ipairs(rows) do
            local first = det.name == hostKick and hist.firstHostKick or firsts[det.name:lower()]
            det.firstTime = first and ps.stampEpoch(first)
        end
        return rows
    end
    function ps.canJoin(result)
        return result ~= nil and result == ps.result and result.rid == ps.selected
            and result.sessionId ~= nil and not result.localSession
            and (not ps.busy or result.rosterBusy) and not ps.pendingSearch and not ps.pendingRid
            and not ps.joinQueued and not sessionBrowser.joinBusy
    end
    function ps.joinSelected(result)
        if not ps.canJoin(result) then return end
        ps.joinQueued = true
        Script.QueueJob(function()
            ps.joinQueued = false
            if ShouldUnload() or scriptUnloading or not ps.canJoin(result) then return end
            local feature = rejoin.resolveBuiltin({"Join Rockstar Id"})
            if not feature then
                GUI.AddToast(T("Player History"), T("Cherax 'Join Rockstar Id' feature not found - cannot join."), 5000)
                return
            end
            if not FeatureMgr.GetFeature(rejoin.scapiRidHash) then
                GUI.AddToast(T("Player History"), T("Cherax SC-API Rockstar Id input not found - cannot join."), 5000)
                return
            end
            FeatureMgr.SetFeatureInt(rejoin.scapiRidHash, result.rid)
            feature:TriggerCallback()
            FeatureMgr.SetFeatureInt(rejoin.scapiRidHash, 0)
        end)
    end
    ps.CRED_SIG = IS_ENHANCED
        and { aob = "48 69 C0 48 10 00 00 48 8D 0D ? ? ? ? 48 01 C8 48 05 70 01 00 00 C3", disp = 10, nextAt = 14, add = 0x170 }
        or  { aob = "48 8D 05 ? ? ? ? 48 8B D3 48 8D 4C 24 ? 48 69 D2 48 10 00 00", disp = 3, nextAt = 7, add = 0 }
    scanDoctor.register("SC-CRED", { sig = scanDoctor.fieldSig(ps, "CRED_SIG", "aob", "aob") })
    ps.TICKET_MAX, ps.WINDOW = 0x200, 0x10000
    ps.PROFILE_URL = "https://scui.rockstargames.com/api/friend/getprofile"
    ps.profiles = {}
    ps.avatarDir = ps.cacheDir .. "\\Avatars"
    for _, path in ipairs(FileMgr.FindFiles(ps.avatarDir, ".img", false) or {}) do FileMgr.DeleteFile(path) end
    ps.credBaseScanned = false

    function ps.credBase()
        if not ps.credBaseScanned then
            ps.credBaseScanned = true
            local hit = Memory.Scan(ps.CRED_SIG.aob)
            if hit and hit ~= 0 then
                ps.credBaseAddr = hit + ps.CRED_SIG.nextAt + Memory.ReadInt(hit + ps.CRED_SIG.disp) + ps.CRED_SIG.add
            end
        end
        return ps.credBaseAddr
    end

    function ps.readTicket(addr)
        local out = {}
        for i = 0, ps.TICKET_MAX - 1 do
            local c = Memory.ReadUByte(addr + i) or 0
            if c == 0 then break end
            if not string.char(c):match("[%w%+/=_%-]") then return nil end
            out[#out + 1] = string.char(c)
        end
        if #out < 64 or #out >= ps.TICKET_MAX then return nil end
        return table.concat(out)
    end

    function ps.ticketCandidates(base, own)
        local rids, runs, start = {}, {}, nil
        for off = -ps.WINDOW, ps.WINDOW - 8, 4 do
            if Memory.ReadLong(base + off) == own then rids[#rids + 1] = off end
            if off % 0x1000 == 0 then Script.Yield(0) end
        end
        for off = -ps.WINDOW, ps.WINDOW do
            local c = Memory.ReadUByte(base + off) or 0
            local b64 = (c >= 48 and c <= 57) or (c >= 65 and c <= 90) or (c >= 97 and c <= 122)
                or c == 43 or c == 47 or c == 61 or c == 45 or c == 95
            if b64 and not start then start = off
            elseif not b64 and start then
                if c == 0 and off - start >= 128 and off - start < ps.TICKET_MAX then
                    local near = math.huge
                    for _, r in ipairs(rids) do near = math.min(near, math.abs(r - start)) end
                    runs[#runs + 1] = { at = start, near = near }
                end
                start = nil
            end
            if off % 0x1000 == 0 then Script.Yield(0) end
        end
        table.sort(runs, function(a, b) return a.near < b.near end)
        return runs, #rids
    end

    function ps.scGet(url, ticket, body)
        local h
        local ok = pcall(function()
            h = Curl.Easy()
            h:Setopt(eCurlOption.CURLOPT_URL, url)
            h:Setopt(eCurlOption.CURLOPT_USERAGENT, "Mozilla/5.0")
            if body then
                h:Setopt(eCurlOption.CURLOPT_CUSTOMREQUEST, "POST")
                h:Setopt(eCurlOption.CURLOPT_POSTFIELDS, body)
                h:AddHeader("Content-Type: application/json")
            end
            if ticket then h:AddHeader(('Authorization: SCAUTH val="%s"'):format(ticket)) end
            h:AddHeader("X-Requested-With: XMLHttpRequest")
            h:AddHeader("Accept: application/json")
            h:Perform()
        end)
        if not ok or not h then return nil, "request failed" end
        local deadline = Time.GetEpocheMs() + 15000
        while true do
            local polled, finished = pcall(function() return h:GetFinished() end)
            if not polled then return nil, "poll failed" end
            if finished then break end
            if Time.GetEpocheMs() >= deadline or scriptUnloading then return nil, "timed out" end
            Script.Yield(50)
        end
        local got, code, resp = pcall(function() return h:GetResponse() end)
        if not got or code ~= 0 then return nil, "no response" end
        return tostring(resp or "")
    end

    function ps.downloadAvatar(rid, url)
        if type(url) ~= "string" or not url:find("^https?://") then return end
        local h
        local ok = pcall(function()
            h = Curl.Easy()
            h:Setopt(eCurlOption.CURLOPT_URL, url)
            h:Setopt(eCurlOption.CURLOPT_USERAGENT, "Mozilla/5.0")
            h:Perform()
        end)
        if not ok or not h then return end
        local deadline = Time.GetEpocheMs() + 15000
        while true do
            local polled, finished = pcall(function() return h:GetFinished() end)
            if not polled then return end
            if finished then break end
            if Time.GetEpocheMs() >= deadline or scriptUnloading then return end
            Script.Yield(50)
        end
        local got, code, body = pcall(function() return h:GetResponse() end)
        if not got or code ~= 0 or type(body) ~= "string" or #body < 128 then return end
        local path = ps.avatarDir .. "\\" .. rid .. ".img"
        local wrote = false
        pcall(function()
            FileMgr.CreateDir(ps.avatarDir)
            local f = io.open(path, "wb")
            if f then f:write(body); f:close(); wrote = true end
        end)
        return wrote and path or nil
    end

    ps.SEARCH_URL = "https://scui.rockstargames.com/api/friend/accountsearch"
    function ps.searchPrivate(rid, account, ticket)
        local names, seen = {}, {}
        local function add(name)
            if type(name) == "string" and name ~= "" and not seen[name:lower()] and #names < 3 then
                seen[name:lower()] = true
                names[#names + 1] = name
            end
        end
        add(account.Name)
        for _, row in ipairs(ps.namesFor(rid)) do add(row.name) end
        for _, name in ipairs(names) do
            if scriptUnloading then return end
            local body = ('{"env":"prod","title":"gta5","version":11,"searchNickname":"%s","pageIndex":0}')
                :format((name:gsub('[\\"]', "\\%0")))
            local resp, err = ps.scGet(ps.SEARCH_URL, ticket, body)
            if not resp then
                VIBE_LOG_ERROR(("[PlayerSearch] private search rid=%d failed: %s"):format(rid, tostring(err)))
            end
            local decoded = ps.decodeJson(resp)
            local accounts = type(decoded) == "table" and type(decoded.Accounts) == "table" and decoded.Accounts or {}
            for _, row in ipairs(accounts) do
                if math.tointeger(tonumber(row.RockstarId)) == rid then
                    local crew = type(row.Crew) == "table" and row.Crew or nil
                    if crew and crew.Name then
                        account.PrimaryClanId, account.PrimaryClanName = crew.Id, crew.Name
                        account.PrimaryClanTag, account.PrimaryClanRankOrder = crew.Tag, crew.RankOrder
                        account.PrimaryClanColor = crew.Color
                    end
                    account.searchAvatarUrl = row.AvatarUrl
                    return
                end
            end
        end
    end

    function ps.fetchProfile(rid)
        local existing = ps.profiles[rid]
        if existing and existing.state ~= "error" then return end
        ps.profiles[rid] = { state = "loading" }
        Script.QueueJob(function()
            local prof = ps.profiles[rid]
            if not prof or scriptUnloading then return end
            ;(function()
                local own = sessionBrowser.localRid()
                if not own then prof.state, prof.error = "error", "Go online to load profiles."; return end
                local base = ps.credBase()
                if not base then prof.state, prof.error = "error", "Sign-in ticket not found on this build."; return end
                local runs, ridCount = ps.ticketCandidates(base, own)
                if ridCount == 0 then prof.state, prof.error = "error", "Could not read the sign-in ticket."; return end
                local body = ('{"RockstarId":"%d"}'):format(rid)
                local resp, used, usedTicket
                for attempt = 1, 3 do
                    local tickets, last = 0, "no ticket"
                    for i = 1, math.min(#runs, 6) do
                        if scriptUnloading then return end
                        local ticket = ps.readTicket(base + runs[i].at)
                        if ticket then
                            tickets = tickets + 1
                            local got, why = ps.scGet(ps.PROFILE_URL, ticket, body)
                            if got and (got:find('"Accounts"', 1, true) or got:find("RockstarAccount", 1, true)) then
                                resp, used, usedTicket = got, i, ticket; break
                            end
                            last = got and ("%d bytes: %s"):format(#got, got:sub(1, 160):gsub("%s+", " ")) or why
                        end
                    end
                    if resp then break end
                    if VIBESCRIPT_VERBOSE == true then VIBE_LOG_ERROR(("[PlayerSearch] profile rid=%d attempt %d/3: no candidate accepted (%d tried, %d tickets, %d id copies), last reply: %s"):format(
                        rid, attempt, math.min(#runs, 6), tickets, ridCount, tostring(last))) end
                    if attempt < 3 then Script.Yield(1500 * attempt) end
                    if scriptUnloading then return end
                end
                if not resp then
                    prof.state, prof.error = "error", "Rockstar did not return this profile."
                    return
                end
                local decoded = ps.decodeJson(resp)
                local account = decoded and decoded.Accounts and decoded.Accounts[1]
                    and decoded.Accounts[1].RockstarAccount
                if type(account) ~= "table" then prof.state, prof.error = "error", "Profile reply could not be read."; return end
                account.LinkedAccounts = decoded.Accounts[1].LinkedAccounts
                if account.ProfileHidden then ps.searchPrivate(rid, account, usedTicket) end
                prof.data, prof.state = account, "ready"
                local avatarUrl = account.ProfileHidden and account.searchAvatarUrl or not account.ProfileHidden and account.AvatarUrl
                if type(avatarUrl) == "string" then
                    local path = ps.downloadAvatar(rid, avatarUrl)
                    if path and ps.profiles[rid] == prof then prof.avatarPath = path end
                end
            end)()
        end)
    end

    function ps.hexColor(text)
        local r, g, b = tostring(text or ""):match("^#(%x%x)(%x%x)(%x%x)$")
        if not r then return nil end
        return { tonumber(r, 16) / 255, tonumber(g, 16) / 255, tonumber(b, 16) / 255, 1.0 }
    end
    ps.MONTHS = { "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" }
    function ps.isoDay(text)
        local y, m, d = tostring(text or ""):match("^(%d+)%-(%d+)%-(%d+)")
        y, m, d = tonumber(y), tonumber(m), tonumber(d)
        if not y or y < 1990 or not ps.MONTHS[m] or not d then return nil end
        return ("%s %d, %d"):format(T(ps.MONTHS[m]), d, y)
    end
    function ps.utcEpoch(text)
        local y, m, d, hour, minute, second = tostring(text or ""):match("^(%d+)%-(%d+)%-(%d+)T(%d+):(%d+):(%d+)")
        y, m, d = tonumber(y), tonumber(m), tonumber(d)
        if not y or y < 1990 or not ps.MONTHS[m] then return nil end
        if m <= 2 then y = y - 1 end
        local yoe = y % 400
        local doy = (153 * ((m + 9) % 12) + 2) // 5 + d - 1
        local days = (y // 400) * 146097 + yoe * 365 + yoe // 4 - yoe // 100 + doy - 719468
        return days * 86400 + tonumber(hour) * 3600 + tonumber(minute) * 60 + tonumber(second)
    end
    function ps.lastSeen(a)
        local newest
        for _, g in ipairs(type(a.GamesOwned) == "table" and a.GamesOwned or {}) do
            local epoch = ps.utcEpoch(g.LastSeen)
            if epoch and (not newest or epoch > newest) then newest = epoch end
        end
        return newest
    end
    function ps.lastOnline(rid, a)
        local day = ps.lastSeen(a)
        local latest = ps.historyFor(rid).latest
        local ours = latest and ps.stampEpoch(latest)
        if ours and (not day or ours >= day) then return ours, true end
        return day, false
    end
    function ps.lastOnlineText(epoch, precise)
        if precise then
            local age = os.time() - epoch
            return age < 60 and T("last seen online just now") or T("last seen online %s"):format(ps.agoText(age))
        end
        local days = ps.utcEpoch(os.date("%Y-%m-%dT00:00:00")) // 86400 - epoch // 86400
        return days <= 0 and T("last seen online today") or days == 1 and T("last seen online yesterday")
            or T("last seen online %d days ago"):format(days)
    end
