        [1] = "Xbox 360", [2] = "PlayStation 3", [3] = "PlayStation", [4] = "Xbox",
        [8] = "PC", [11] = "PlayStation 4", [12] = "Xbox One", [18] = "Nintendo Switch",
        [20] = "PlayStation 5", [21] = "Xbox Series X|S", [22] = "PC Enhanced",
        [102] = "App Store", [1023] = "Google Play",
