    ps.LANGUAGE_NAMES = {
        en="English", de="German", fr="French", es="Spanish", it="Italian",
        ja="Japanese", ko="Korean", pl="Polish", pt="Portuguese", ru="Russian",
        zh="Chinese", ["zh-cn"]="Chinese (Simplified)", ["zh-tw"]="Chinese (Traditional)",
        ["pt-br"]="Portuguese (Brazil)", ar="Arabic", cs="Czech", da="Danish",
        nl="Dutch", fi="Finnish", el="Greek", hu="Hungarian", no="Norwegian",
        nb="Norwegian", ro="Romanian", sv="Swedish", th="Thai", tr="Turkish", uk="Ukrainian",
    }
