    function ps.language(code)
        if type(code) ~= "string" or code:match("^%s*$") then return nil end
        local key = code:match("^%s*(.-)%s*$"):lower():gsub("_", "-")
        local name = ps.LANGUAGE_NAMES[key] or ps.LANGUAGE_NAMES[key:match("^[^-]+")]
        return name and T(name) or key:upper()
    end

    function ps.avatarHandle(prof)
        if not prof.avatarPath then return nil end
        if not prof.avatarTex and not prof.avatarTried then
            prof.avatarTried = true
            local ok, id = pcall(Texture.LoadTexture, prof.avatarPath)
            if ok and id and id ~= 0 then prof.avatarTex = id end
        end
        if not prof.avatarTex then return nil end
        local valid, handle = false, nil
        pcall(function() valid = Texture.IsTextureValid(prof.avatarTex) end)
        if not valid then return nil end
        pcall(function() handle = Texture.GetTexture(prof.avatarTex):GetCurrent() end)
        return handle
    end

    function ps.presenceState(rid)
        local r = ps.result
        if not r or r.rid ~= rid then return nil end
        if r.sessionId or (r.row and r.row.live) then return "online" end
        if ps.busy then return nil end
        return "offline"
    end

    function ps.renderProfile(rid)
        local prof = ps.profiles[rid]
        if not prof then return end
        if prof.state == "loading" then wrapped(ps.spin("Loading Social Club profile"), MUTED); return end
        if prof.state == "error" then wrapped(T(prof.error or "Profile unavailable."), MUTED); return end
        local a = prof.data
        local x0, y0 = ImGui.GetCursorPosX(), ImGui.GetCursorPosY()
        local since = ps.isoDay(a.CreatedDate)
        local presence = a.ProfileHidden and ps.presenceState(rid)
        local lines = a.ProfileHidden and (a.PrimaryClanTag and 3 or 2) + (presence and 1 or 0) or since and 4 or 3
        local SIZE = (lines - 1) * ImGui.GetTextLineHeightWithSpacing() + ImGui.GetTextLineHeight()
        local sx, sy = ImGui.GetCursorScreenPos()
        local handle = ps.avatarHandle(prof)
        if handle then
            pcall(function() ImGui.AddImageRotated(handle, sx + SIZE / 2, sy + SIZE / 2, SIZE, SIZE, 0.0, 255) end)
        else
            ImGui.AddRectFilled(sx, sy, sx + SIZE, sy + SIZE, 40, 40, 52, 255, 8)
            local initial = tostring(a.Name or "?"):sub(1, 1):upper()
            ImGui.SetWindowFontScale(2.0)
            local w = ImGui.CalcTextSize(initial)
            ImGui.AddText(sx + (SIZE - w) / 2, sy + SIZE / 2 - 14, initial, 200, 200, 210, 255)
            ImGui.SetWindowFontScale(1.0)
        end
        local tx = x0 + SIZE + 16
        local function statusDot(online)
            local dx, dy = ImGui.GetCursorScreenPos()
            local dot = online and {70, 210, 90} or {255, 186, 89}
            ImGui.AddRectFilled(dx, dy + 4, dx + 10, dy + 14, dot[1], dot[2], dot[3], 255, 5)
            ImGui.SetCursorPosX(tx + 16)
        end
        ImGui.SetCursorPosY(y0)
        ImGui.SetCursorPosX(tx)
        if a.ProfileHidden then
            colored(T("Private profile"), AMBER)
            ImGui.SetCursorPosX(tx)
            if a.PrimaryClanTag then
                colored("[" .. a.PrimaryClanTag .. "]", ps.hexColor(a.PrimaryClanColor) or VALUE)
                ImGui.SameLine(); wrapped(a.PrimaryClanName or T("Crew"))
                ImGui.SetCursorPosX(tx)
            end
            if presence then
                local online = presence == "online"
                local lastSeen, precise
                if not online then lastSeen, precise = ps.lastOnline(rid, a) end
                statusDot(online)
                if lastSeen then
                    colored(T("Offline"), AMBER)
                    ImGui.SameLine()
                    wrapped(ps.lastOnlineText(lastSeen, precise), MUTED)
                else wrapped(T(online and "Online" or "Offline"), online and GREEN or AMBER) end
                ImGui.SetCursorPosX(tx)
            end
            wrapped(T("This player hides their Social Club details."), MUTED)
            if ImGui.GetCursorPosY() < y0 + SIZE + 6 then ImGui.SetCursorPosY(y0 + SIZE + 6) end
            ImGui.SetCursorPosX(x0)
            return
        end
        if a.PrimaryClanTag then
            colored("[" .. a.PrimaryClanTag .. "]", ps.hexColor(a.PrimaryClanColor) or VALUE)
            ImGui.SameLine(); wrapped(a.PrimaryClanName or T("Crew"))
        else muted(T("No crew")) end
        ImGui.SetCursorPosX(tx)
        local game = a.IsOnline and type(a.OnlineGames) == "table" and a.OnlineGames[1]
        statusDot(a.IsOnline)
        local lastSeen, precise
        if not a.IsOnline then lastSeen, precise = ps.lastOnline(rid, a) end
        if game then
            wrapped(T("%s on %s"):format(game.TitleFriendlyName or "?", game.PlatformFriendlyName or "?"), GREEN)
        elseif lastSeen then
            colored(T("Offline"), AMBER)
            ImGui.SameLine()
            wrapped(ps.lastOnlineText(lastSeen, precise), MUTED)
        else wrapped(T(a.IsOnline and "Online" or "Offline"), a.IsOnline and GREEN or AMBER) end
        ImGui.SetCursorPosX(tx)
        local country = a.CountryCode and (countryFinder.NAMES[a.CountryCode] or a.CountryCode)
        local countryText = country or T("Country hidden")
        local language = ps.language(a.LanguageCode)
        if language then countryText = countryText .. (" (%s)"):format(language) end
        wrapped(countryText)
        ImGui.SetCursorPosX(tx)
        if since then muted(T("Member since")); ImGui.SameLine(); wrapped(since, TEAL) end
        if ImGui.GetCursorPosY() < y0 + SIZE + 6 then ImGui.SetCursorPosY(y0 + SIZE + 6) end
        ImGui.SetCursorPosX(x0)
    end

    function ps.renderProfileDetails(a)
        local function yes(v) return v == nil and T("Unknown") or T(v and "Yes" or "No") end
        if ImGui.CollapsingHeader(TL("Social Club profile")) then
            local profile = {
                {"Name", a.Name},
                {"Display name", a.DisplayName ~= a.Name and a.DisplayName or nil},
                {"Status", (a.Status and a.Status ~= "") and a.Status or nil},
                {"Crew", a.PrimaryClanName and ("%s [%s]"):format(a.PrimaryClanName, a.PrimaryClanTag or "")},
                {"Crew rank", a.PrimaryClanName and a.PrimaryClanRankOrder and tostring(a.PrimaryClanRankOrder)},
                {"Country", a.CountryCode and ("%s (%s)"):format(countryFinder.NAMES[a.CountryCode] or a.CountryCode, a.CountryCode)},
                {"Language", ps.language(a.LanguageCode)},
                {"Member since", ps.isoDay(a.CreatedDate), TEAL},
                {"Mutual friends", a.MutualFriendCount and tostring(a.MutualFriendCount)},
                {"Relationship", a.Relationship},
            }
            local social = {
                {"Friends", a.FriendsHidden and T("Hidden") or (a.FriendCount and tostring(a.FriendCount))},
                {"Profile hidden", yes(a.ProfileHidden)},
                {"Friends hidden", yes(a.FriendsHidden)},
                {"Wall hidden", yes(a.WallHidden)},
                {"Gamertag", a.IsGamertagHidden and T("Hidden") or a.Gamertag},
                {"Allows wall posts", yes(a.AllowWallPost)},
                {"Allows stat compare", yes(a.AllowStatCompare)},
            }
            local groups = {profile, social}
            local labelWidth = 0
            for index, values in ipairs(groups) do
                local shown = {}
                for _, item in ipairs(values) do
                    if item[2] ~= nil then
