    function ps.renderSession(rid, rec, result)
        local hist, row = ps.historyFor(rid), result and result.row
        local current = ps.current and ps.current.rid == rid and ps.current
        local prof = ps.profiles[rid]
        local profileName = prof and prof.state == "ready" and prof.data and prof.data.Name
        if type(profileName) ~= "string" or not profileName:find("%S") then profileName = nil end
        local namePending = not prof or prof.state == "loading"
        local headerTable = ImGui.BeginTable("##ps_identity", 2, ImGuiTableFlags.SizingStretchProp)
        if headerTable then
            ImGui.TableSetupColumn("Identity", STRETCH)
            ImGui.TableSetupColumn("Actions", FIXED)
            ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
        end
        ImGui.SetWindowFontScale(1.4)
        wrapped(namePending and ps.spin("Loading Social Club profile") or profileName
            or (current and current.name) or (rec and rec.name) or hist.name or ps.onlineNames[rid]
            or T("Unknown player"), namePending and MUTED or DISPLAY_NAME)
        ImGui.SetWindowFontScale(1.0)
        muted(T("Rockstar ID")); ImGui.SameLine()
        ImGui.Selectable(tostring(rid).."##ps_copy_rid", false, 0, (ImGui.CalcTextSize(tostring(rid))), 0)
        if ImGui.IsItemClicked(0) then
            ImGui.SetClipboardText(tostring(rid))
            GUI.AddToast(T("Player History"), T("Rockstar ID copied"), 2000)
        end
        if headerTable then ImGui.TableSetColumnIndex(1) end
        local actionW = 0
        for _, label in ipairs({"Join", "Refresh"}) do
            actionW = math.max(actionW, ImGui.CalcTextSize(T(label)) + 16)
        end
        if sessionBrowser.dimButton(TL("Join"),actionW,0,not ps.canJoin(result)) then ps.joinSelected(result) end
        ImGui.SameLine()
        if ImGui.Button(TL("Refresh"),actionW,0) and not ps.refreshQueued then
            ps.refreshQueued = true
            Script.QueueJob(function()
                ps.refreshQueued = false
                if ps.selected ~= rid or ps.pendingSearch
                    or (ps.pendingRid and ps.pendingRid ~= rid) then return end
                ps.refreshRecords()
                ps.startHistory()
                ps.profiles[rid] = nil
                ps.inspect(rid)
            end)
        end
        if headerTable then ImGui.EndTable() end
        ImGui.Spacing()
        ps.renderProfile(rid)
        local online = result and (result.localSession == true or result.sessionId ~= nil)
        local presencePending = ps.busy and not result
        local sessionPending = ps.busy and (not result or result.detailPending)
        local status = result and result.localSession and T("In your lobby")
            or online and T("Online") or presencePending and ps.spin("Checking presence")
            or result and T("Offline / not in a session") or T("Online status unknown")
        local hostRid = row and row.hostRid or result and result.hostRid
        local hostRec = hostRid and (ps.records[hostRid] or sessionBrowser.known[hostRid])
        local host = row and row.hostName or hostRec and hostRec.name or hostRid and tostring(hostRid)
        local detections, reasons = ps.detectionRows(rec, rid), {}
        local snapshot = ps.liveDetections and ps.liveDetections.rid==rid and ps.liveDetections
        for _, det in ipairs(detections) do reasons[#reasons+1] = det.name end
        local lobby = row and ps.lobbyLabel(row)
        local ip, ipDirect = ps.ipFor(rec)
        local resolving = sessionPending and ps.spin("Resolving")
        local loadingHistory = ps.history.busy and ps.spin("Loading history")
        local sessionValues = {{"Status", status, online and GREEN or presencePending and MUTED or AMBER},
            {"Session", lobby and T(lobby) or resolving or online and T("Details unavailable") or T("Unknown"),
                lobby and LOBBY_TONE[lobby] or resolving and MUTED},
            {"Players", row and row.players and (row.maxPublic and (row.players.." / "..row.maxPublic) or tostring(row.players)) or resolving or T("Unknown"),
                not (row and row.players) and resolving and MUTED},
            {"Session host", host or resolving or T("Unknown"), not host and resolving and MUTED}}
        local historyValues = {
            {"Last joined you", hist.join and logDateAgo(hist.join) or loadingHistory or T("No recorded encounter"), hist.join and TEAL or MUTED,
                hist.join and {logDateAgo(hist.join, true), logDate(hist.join)}},
            {"Last left you", hist.leave and logDateAgo(hist.leave) or loadingHistory or T("No leave recorded"), hist.leave and TEAL or MUTED,
                hist.leave and {logDateAgo(hist.leave, true), logDate(hist.leave)}},
            {"IPv4", ip or T("Not recorded"), not ipDirect and MUTED},
            {"Modder reasons", #reasons>0 and table.concat(reasons, ", ") or T(snapshot and snapshot.error and "Records unavailable" or "None recorded"), #reasons>0 and AMBER}}
        local labelWidth = 0
        for _, values in ipairs({sessionValues, historyValues}) do
            for _, item in ipairs(values) do labelWidth = math.max(labelWidth, ImGui.CalcTextSize(T(item[1]))) end
        end
        local columns = ImGui.GetContentRegionAvail() >= math.max(600, 2 * (labelWidth + 180))
            and ImGui.BeginTable("##ps_overview", 2, ImGuiTableFlags.SizingStretchSame)
        if columns then ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0) end
        section(T("Current session"), VALUE)
        fields("##ps_session_summary", sessionValues)
        if columns then ImGui.TableSetColumnIndex(1) end
        section(T("History & records"), VALUE)
        fields("##ps_history_summary", historyValues)
        if columns then ImGui.EndTable() end
        ImGui.Spacing()
        if row and ImGui.CollapsingHeader(TL("Session details")) then
            local settings, identifiers = {}, {}
            local function add(values,label,value) if value~=nil then values[#values+1]={label,value} end end
            local region = sessionBrowser.REGION_NAME and sessionBrowser.REGION_NAME[row.region]
            add(settings,"Region", region and T(region) or row.region)
            local nat = sessionBrowser.NAT_NAME and sessionBrowser.NAT_NAME[row.natType]
            add(settings,"Host NAT", nat and T(nat) or row.natType)
            if row.freeAim~=nil then add(settings,"Aim", T(row.freeAim and "Free aim" or "Assisted aim")) end
            add(identifiers,"Host Rockstar ID", hostRid); add(identifiers,"Session ID", result.sessionId)
            add(identifiers,"CEO/MC Bosses",row.bosses)
            local function halfWidth(values)
                local label, value = 0, 0
                for _, item in ipairs(values) do
                    label = math.max(label, ImGui.CalcTextSize(T(item[1])))
                    value = math.max(value, ImGui.CalcTextSize((clean(item[2]))))
                end
                return label + value + 32
            end
            local detailColumns = ImGui.GetContentRegionAvail() >= 2 * math.max(halfWidth(settings), halfWidth(identifiers))
                and ImGui.BeginTable("##ps_session_detail_columns", 2, ImGuiTableFlags.SizingStretchSame)
            if detailColumns then
                ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
                fields("##ps_session_settings",settings)
                ImGui.TableSetColumnIndex(1)
                fields("##ps_session_identifiers",identifiers)
                ImGui.EndTable()
            else
                for _, item in ipairs(identifiers) do settings[#settings+1] = item end
                fields("##ps_session_settings",settings)
            end
            ps.renderMembers(result, hostRid)
        end
        return detections
    end
    function ps.renderMembers(result, hostRid)
        section(T("Known lobby players"))
        if not result.localSession then
            muted(T("Known players found in this session; list may be incomplete."))
        end
        if result.rosterBusy then
            muted(ps.spin("Checking known players") .. (" (%d / %d)"):format(result.checked or 0, result.rosterTotal or 0))
        elseif result.rosterIncomplete then
            muted(T("Check stopped; showing confirmed players only."))
        end
        if ImGui.BeginTable("##ps_members", 2, LIST_FLAGS) then
            ImGui.TableSetupColumn(T("Name"), STRETCH)
            ImGui.TableSetupColumn(T("Rockstar ID"), FIXED)
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0); muted(T("Name"))
            ImGui.TableSetColumnIndex(1); muted(T("Rockstar ID"))
            for _, member in ipairs(result.members or {}) do
                local known = ps.records[member] or sessionBrowser.known[member]
                local name = result.memberNames and result.memberNames[member]
                    or known and known.name or ps.onlineNames[member] or T("Unknown player")
                ImGui.TableNextRow()
                ImGui.TableSetColumnIndex(0); wrapped(name)
                if member == hostRid then ImGui.SameLine(); muted(T("[Session Host]")) end
                ImGui.TableSetColumnIndex(1); muted(tostring(member))
            end
            ImGui.EndTable()
        end
    end
    function ps.renderDetections(detections)
