                for _,det in ipairs(detections) do
                    ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0); wrapped(det.name)
                    ImGui.TableSetColumnIndex(1); muted(det.count or "—")
                    ImGui.TableSetColumnIndex(2); muted(det.firstTime and date(det.firstTime, true) or T("Unknown"))
                    ImGui.TableSetColumnIndex(3); muted(det.lastTime and date(det.lastTime, true) or T("Unknown"))
                end
                ImGui.EndTable()
            end
