    function ps.attackFirsts(rid)
        local firsts = {}
        for _, item in pairs(ps.historySources(rid)) do
            local rec = item.entries[rid]
            for reason, attack in pairs(rec and rec.attacks or {}) do
                local key = reason:lower()
                if not firsts[key] or attack.first < firsts[key] then firsts[key] = attack.first end
            end
        end
        return firsts
    end
    function ps.attacksFor(rid, detections)
        local held = ps.memo("attacks", rid, function() return {} end)
        if held.detections ~= detections or not held.rows then
            held.detections, held.rows = detections, ps.buildAttacksFor(rid, detections)
        end
        return held.rows
    end
    function ps.buildAttacksFor(rid, detections)
        local byHead = {}
        for _, item in pairs(ps.historySources(rid)) do
            local rec = item.entries[rid]
            if rec and rec.attacks then
                local key = item.head or item.path
                local held = byHead[key]
                if not held or item.offset > held.offset then byHead[key] = item end
            end
        end
        local known = {}
        for _, det in ipairs(detections or {}) do known[det.name:lower()] = true end
        local rows, byReason = {}, {}
        for _, item in pairs(byHead) do
            for reason, attack in pairs(item.entries[rid].attacks) do
                if not known[reason:lower()] then
                    local row = byReason[reason]
                    if not row then
                        row = { reason = reason, count = 0 }
                        byReason[reason], rows[#rows + 1] = row, row
                    end
                    row.count = row.count + attack.count
                    if not row.last or attack.last > row.last then row.last = attack.last end
                    if not row.first or attack.first < row.first then row.first = attack.first end
                end
            end
        end
        table.sort(rows, function(a, b)
            if a.count ~= b.count then return a.count > b.count end
            return a.reason < b.reason
        end)
        return rows
    end
    function ps.renderAttacks(rid, detections)
        local rows = ps.attacksFor(rid, detections)
        if #rows > 0 and ImGui.CollapsingHeader(TL("Attack details")) then
            ps.renderUpdating()
            if ImGui.BeginTable("##ps_attacks", 4, LIST_FLAGS) then
                for index, label in ipairs({"Attack", "Count", "First recorded", "Last recorded"}) do
                    ImGui.TableSetupColumn(T(label), index == 1 and STRETCH or FIXED)
                end
                ImGui.TableNextRow()
                for index, label in ipairs({"Attack", "Count", "First recorded", "Last recorded"}) do ImGui.TableSetColumnIndex(index-1); muted(T(label)) end
                for _, row in ipairs(rows) do
                    ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
                    wrapped(ps.OWN_ATTACKS[row.reason] and T(row.reason) or row.reason)
                    ImGui.TableSetColumnIndex(1); muted(tostring(row.count))
                    ImGui.TableSetColumnIndex(2); muted(logDate(row.first))
                    ImGui.TableSetColumnIndex(3); muted(logDate(row.last))
                end
                ImGui.EndTable()
            end
        end
    end
    ps.listSizes = {}
    function ps.listHeight(id, rows, visible)
        local size = ps.listSizes[id]
        local row = size and size.rows > 0 and size.height / size.rows or 26
        return math.min(visible, rows) * row + (size and 0 or 8)
    end
    function ps.measureList(id, rows, startY)
        ps.listSizes[id] = { rows = rows, height = ImGui.GetCursorPosY() - startY }
    end
    function ps.historyReadable()
        local h = ps.history
        return h.storageLoaded and h.indexFiles == h.files
    end
    function ps.renderUpdating()
        if ps.history.busy then muted(ps.spin("Updating history")) end
    end
    function ps.renderEncounters(rid)
        local enc = ps.encounters and ps.encounters.rid == rid and ps.encounters
        local now = Time.GetEpocheMs()
        if enc and not enc.busy and not ps.encountersNext
            and (enc.revision or 0)~=(ps.history.eventRevision or 0)
            and now-(ps.encountersTriedAt or 0)>=2000 then
            ps.encountersTriedAt = now
            ps.loadEncounters(rid, true)
        end
        if not next(ps.history.files) and not ps.history.busy then
            muted(T("No logs indexed yet. Run a search first.")); return
        end
        if not enc then
            if not ps.historyReadable() then muted(T("Loading history…")); return end
            ps.loadEncounters(rid)
            enc = ps.encounters
        end
        ps.renderUpdating()
        if enc.busy then
            muted(T("Preparing encounter details…"))
            return
        end
        local x0, top, availW = ImGui.GetCursorPosX(), ImGui.GetCursorPosY(), ImGui.GetContentRegionAvail()
        local function reloadButton()
            local bottom = ImGui.GetCursorPosY()
            ImGui.SetCursorPos(x0 + math.max(0, availW - 160), top)
            local clicked = ImGui.Button(TL("Reload encounters"), 160, 0)
            if ImGui.GetCursorPosY() < bottom then ImGui.SetCursorPosY(bottom) end
            if clicked then ps.loadEncounters(rid) end
            return clicked
        end
        if enc.partial then wrapped(T("Some older encounter details are unavailable. Existing history summaries are preserved."),AMBER) end
        if #enc.rows == 0 then muted(T("No encounters found in the indexed logs.")); reloadButton(); return end
        fields("##ps_encounter_totals", {
            {"Sessions together", tostring(#enc.rows), TEAL},
            {"Total time together", ps.duration(enc.seconds) or T("Unknown")}})
        if reloadButton() then return end
        if enc.capped then muted(T("Event list was capped; some encounters are missing.")) end
        local total = #enc.rows
        if enc.hasNameChanges == nil then
            local firstName
            enc.hasNameChanges = false
            for _, row in ipairs(enc.rows) do
                local name = clean(row.name)
                if name ~= "" then
                    if firstName and name ~= firstName then enc.hasNameChanges = true; break end
                    firstName = name
                end
            end
        end
        local labels = {"Joined", "Left", "Time", "Version", "IP"}
        if enc.hasNameChanges then labels[#labels + 1] = "Name" end
        if ps.encounterColumnCount ~= #labels then
            ps.encounterColumns = nil
            ps.encounterColumnCount = #labels
        end
        if not enc.cells then
            enc.cells, enc.widths, enc.measured = {}, {}, 0
            for index, label in ipairs(labels) do enc.widths[index] = ImGui.CalcTextSize(T(label)) end
        end
        local function rowCells(index)
            local cells = enc.cells[index]
            if cells then return cells end
            local row = enc.rows[index]
            cells = { row.join and logDate(row.join) or T("Before the logs"),
                row.leave and logDate(row.leave) or T("No leave recorded"),
                ps.duration(row.seconds) or T("Unknown"), T(row.edition or "Unknown"), ps.addressText(row) }
            if enc.hasNameChanges then cells[6] = clean(row.name and row.name ~= "" and row.name or T("Unknown")) end
            for column = 1, #labels - 1 do
                enc.widths[column] = math.max(enc.widths[column], ImGui.CalcTextSize(cells[column]))
            end
            enc.cells[index] = cells
            return cells
        end
        local measureTo = math.min(total, enc.measured + 300)
        for index = enc.measured + 1, measureTo do rowCells(index) end
        enc.measured = measureTo
        local columns = ps.encounterColumns
        local origin = ImGui.GetCursorScreenPos() - ImGui.GetCursorPosX()
        local headerY = ImGui.GetCursorPosY()
        for index, label in ipairs(labels) do
            local x = columns and columns[index] and columns[index] - origin
            if index == 1 then
                if x then ImGui.SetCursorPosX(x) end
            elseif x and x > 0 then ImGui.SameLine(x)
            else ImGui.SameLine() end
            muted(T(label))
        end
        ImGui.SetCursorPosY(headerY + ImGui.GetTextLineHeight() + 2)
        ImGui.Separator()
        local VISIBLE = 10
        local clip = total > VISIBLE
        local rowH = enc.rowH or ps.encounterRowH or 26
        local childH = clip and VISIBLE * rowH + 8 or ps.listHeight("encounters", total, VISIBLE)
        if ImGui.BeginChild("##ps_encounter_list", 0, childH, false, 0) then
            local first, last = 1, total
            if clip then
                first = math.max(1, math.floor(ImGui.GetScrollY() / rowH) - 1)
                last = math.min(total, first + VISIBLE + 4)
                ImGui.Dummy(1, (first - 1) * rowH)
            end
            for index = first, last do rowCells(index) end
            local startY, firstY, lastY = ImGui.GetCursorPosY(), nil, nil
            if ImGui.BeginTable("##ps_encounter_rows", #labels, LIST_FLAGS) then
                for index, label in ipairs(labels) do
                    ImGui.TableSetupColumn(T(label), index == #labels and STRETCH or FIXED)
                end
                columns = {}
                ps.encounterColumns = columns
                local function cell(column, top, draw, text, color)
                    ImGui.TableSetColumnIndex(column)
                    if top then columns[column + 1] = (ImGui.GetCursorScreenPos()) end
                    draw(text, color)
                    if top and column < #labels - 1 then
                        ImGui.SameLine()
                        ImGui.Dummy(math.max(0, enc.widths[column + 1] - ImGui.CalcTextSize(text)), 1)
                    end
                end
                for index = first, last do
                    local cells, top = enc.cells[index], index == first
                    ImGui.TableNextRow()
                    ImGui.TableSetColumnIndex(0)
                    if index == first then firstY = ImGui.GetCursorPosY() end
                    if index == last then lastY = ImGui.GetCursorPosY() end
                    cell(0, top, colored, cells[1], VALUE)
                    for column = 2, 5 do cell(column - 1, top, muted, cells[column]) end
                    if enc.hasNameChanges then cell(5, top, colored, cells[6], VALUE) end
                end
                ImGui.EndTable()
                if not clip then ps.measureList("encounters", total, startY) end
                if not enc.rowH and firstY and lastY and last > first and lastY > firstY then
                    enc.rowH = (lastY - firstY) / (last - first)
                    ps.encounterRowH = enc.rowH
                end
            end
            if clip then ImGui.Dummy(1, (total - last) * rowH) end
        end
        ImGui.EndChild()
        ps.renderEncounterIPs(enc)
    end
    function ps.renderEncounterIPs(enc)
        local ips = enc.ips or {}
        section(T("IP addresses"))
        if #ips == 0 then
            wrapped(T("No direct IP recorded. Relay and peer connections hide the player's IP."), MUTED)
            return
        end
        if not enc.geoQueued then enc.geoQueued = true; ps.queueGeo(ips) end
        local labels = {"IP", "Count", "Last seen", "Connection", "Location", "ISP"}
        local function cell(column, text, color, tip)
            ImGui.TableSetColumnIndex(column)
            colored(text, color)
            if tip and ImGui.IsItemHovered() then ImGui.SetTooltip(tip) end
        end
        local function rowCells(item)
            local geo = ps.geo.cache[item.ip]
            local key = geo and not geo.failed and geo or false
            if item.cells and item.cellsGeo == key then return item.cells end
            local cells = { sessions = tostring(item.sessions),
                last = item.last and logDate(item.last, true) or T("Unknown") }
            if key then
                local full, short = {}, {}
                for _, part in ipairs({geo.city, geo.region, geo.country}) do
                    if part and part ~= "" and part ~= full[#full] then full[#full + 1] = part end
                end
                for _, part in ipairs({geo.city ~= "" and geo.city or geo.region, geo.country}) do
                    if part and part ~= "" and part ~= short[#short] then short[#short + 1] = part end
                end
                local placeCut
                cells.place, placeCut = ps.clip(#short > 0 and table.concat(short, ", ") or T("Unknown"), 22)
                cells.placeTip = (placeCut or #full > #short) and table.concat(full, ", ") or nil
                cells.isp = geo.isp ~= "" and geo.isp or geo.org ~= "" and geo.org or T("Unknown")
                cells.kind, cells.flagged, cells.reason = ps.connectionType(geo)
            end
            item.cells, item.cellsGeo = cells, key
            return cells
        end
        local function drawRow(item, index)
            local cells = rowCells(item)
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0)
            if index then ips.rowTops[index] = ImGui.GetCursorPosY() end
            cell(0, item.ip, VALUE)
            cell(1, cells.sessions, MUTED)
            cell(2, cells.last, MUTED)
            if cells.isp then
                cell(3, cells.kind, cells.flagged and AMBER or GREEN, cells.reason)
                cell(4, cells.place, VALUE, cells.placeTip)
                ImGui.TableSetColumnIndex(5)
                local width = ImGui.GetContentRegionAvail()
                if cells.ispWidth ~= width then
                    cells.ispWidth = width
                    cells.ispShort, cells.ispCut = ps.fit(cells.isp, width)
                end
                cell(5, cells.ispShort, VALUE, cells.ispCut and cells.isp or nil)
            else
                ImGui.TableSetColumnIndex(3)
                muted(ps.geo.queued[item.ip] and ps.spin("Looking up") or T("Unavailable"))
            end
        end
        local VISIBLE = 10
        local clip = #ips > VISIBLE
        local rowH = ips.rowH or ps.ipRowH or 26
        local child = clip and ImGui.BeginChild("##ps_encounter_ips_list", 0, (VISIBLE + 1) * rowH + 8, false, 0)
        if (not clip or child) and ImGui.BeginTable("##ps_encounter_ips", #labels, LIST_FLAGS) then
            for index, label in ipairs(labels) do
                ImGui.TableSetupColumn(T(label), index == #labels and STRETCH or FIXED)
            end
            ImGui.TableNextRow()
            for index, label in ipairs(labels) do ImGui.TableSetColumnIndex(index - 1); muted(T(label)) end
            if clip then
                local first = math.max(1, math.floor(ImGui.GetScrollY() / rowH) - 1)
                local last = math.min(#ips, first + VISIBLE + 4)
                local function spacer(height)
                    ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0); ImGui.Dummy(1, height)
                end
                ips.rowTops = {}
                spacer((first - 1) * rowH)
                for index = first, last do drawRow(ips[index], index) end
                spacer((#ips - last) * rowH)
                local top, bottom = ips.rowTops[first], ips.rowTops[last]
                if not ips.rowH and top and bottom and last > first and bottom > top then
                    ips.rowH = (bottom - top) / (last - first)
                    ps.ipRowH = ips.rowH
                end
            else
                for _, item in ipairs(ips) do drawRow(item) end
            end
            ImGui.EndTable()
        end
        if clip then ImGui.EndChild() end
        if ips.hidden > 0 then
            wrapped(T("%d other session(s) went through a relay or another player, which hides the IP."):format(ips.hidden), MUTED)
        end
        local status = ps.geoStatus()
        if status then wrapped(status, MUTED) end
    end
    function ps.renderHistory(rid, rec, detections)
        local hist = ps.historyFor(rid)
        if (hist.join or hist.leave) and ImGui.CollapsingHeader(TL("Encounter details")) then
            ps.renderEncounters(rid)
        end
        local prof = ps.profiles[rid]
        if prof and prof.state == "ready" then ps.renderProfileDetails(prof.data) end
        ps.renderDetections(detections)
        ps.renderAttacks(rid, detections)
        local names = ps.namesFor(rid)
        if #names>1 and ImGui.CollapsingHeader(TL("Name history")) then
            if ImGui.BeginTable("##ps_names",3,LIST_FLAGS) then
                for index,label in ipairs({"Name","First record","Last record"}) do
                    ImGui.TableSetupColumn(T(label), index==1 and STRETCH or FIXED)
                end
                ImGui.TableNextRow()
                for index,label in ipairs({"Name","First record","Last record"}) do ImGui.TableSetColumnIndex(index-1); muted(T(label)) end
                for _,name in ipairs(names) do
                    ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0); wrapped(name.name)
                    ImGui.TableSetColumnIndex(1); muted(name.first and logDate(name.first, true) or T("Unknown"))
                    ImGui.TableSetColumnIndex(2); muted(name.last and logDate(name.last, true) or T("Unknown"))
                end
                ImGui.EndTable()
            end
        end
    end
    local historyProgressRanges={
        ["Restoring saved history"]={0,0.10},
        ["Building player index"]={0.10,0.15},
        ["Importing encounter history"]={0.15,0.85},
        ["Saving history"]={0.85,0.93},
        ["Verifying history"]={0.93,0.98},
        ["Finishing history cache"]={0.98,0.99},
    }
    function ps.historyProgress()
        local h=ps.history
        if not h.busy then return h.progress or 0 end
        local done,total=h.phaseDone or 0,h.phaseTotal or 0
        local fraction=total>0 and done/total or 0
        if h.phase=="Importing encounter history" and total>0 then
            fraction=((h.done or 0)+(h.fileSize and h.fileSize>0 and math.min(1,(h.fileBytes or 0)/h.fileSize) or 0))/total
        end
        local range=historyProgressRanges[h.phase] or {0,0}
        if h.firstRun then
            if h.phase=="Restoring saved history" or h.phase=="Building player index" then range={0,0}
            elseif h.phase=="Importing encounter history" then range={0,0.85} end
        end
        local progress=range[1]+(range[2]-range[1])*math.max(0,math.min(1,fraction))
        h.progress=math.max(h.progress or 0,math.min(0.99,progress))
        return h.progress
    end
    function ps.renderHistoryStatus(origin)
        local h = ps.history
        if h.origin ~= origin then return end
        if h.busy then
            local fraction=ps.historyProgress()
            local label=("%s - %d%%"):format(T(h.phase or "Restoring saved history"),math.floor(fraction*100))
            ImGui.ProgressBar(fraction,ImGui.GetContentRegionAvail(),18,label)
            wrapped(T(h.firstRun
                and "One-time history setup. Future searches only process new log data. Available players can be selected."
                or "Encounter history is updating in the background. Available players can be selected."), MUTED)
        elseif h.status:find("failed:",1,true) then colored(T("History unavailable. Search again to retry."),AMBER) end
    end
