    function ps.searchRows(online)
        local rows, byRid, byName = {}, {}, {}
        local function add(row)
            rows[#rows + 1] = row
            if row.rid then byRid[row.rid] = row end
            local key = row.name:lower()
            if byName[key] then byName[key] = false
            elseif byName[key] == nil then byName[key] = row end
        end
        for index, rec in ipairs(ps.matches) do
            if index > 50 then break end
            add({name=rec.name, rid=rec.rid})
        end
        if online then
            for index, name in ipairs(online.names) do
                local rid = online.rids[index]
                local row = rid and byRid[rid] or not rid and byName[name:lower()]
                if not row then add({name=name, rid=rid, onlineIndex=index}) end
            end
        end
        return rows
    end
    function ps.renderSearchResults()
        local online = ps.online
        if online and online.query ~= ps.nameQuery then online = nil end
        if online then ps.readOnlineClip(online) end
        local rows = ps.searchRows(online)
        section(T("Search results"))
        if online and online.busy then muted(T("Searching Social Club…")) end
        if online and online.error then colored(T(online.error), AMBER) end
        if ps.matching > 0 then muted(T("Looking for matches…")) end
        if #rows == 0 then
            if not (ps.history.busy or ps.matching > 0 or online and (online.busy or online.error)) then
                muted(T("No players found. Try a Rockstar ID."))
            end
            return
        end
        if ImGui.BeginChild("##ps_search_list", 0, ps.listHeight("search", #rows, 6), false, 0) then
            local startY = ImGui.GetCursorPosY()
            if ImGui.BeginTable("##ps_search_results", 3, LIST_FLAGS) then
                ImGui.TableSetupColumn(T("Player"), STRETCH)
                ImGui.TableSetupColumn(T("History"), FIXED)
                ImGui.TableSetupColumn(T("Rockstar ID"), FIXED)
                for index, row in ipairs(rows) do
                    local rid = row.rid
                    ImGui.TableNextRow(); ImGui.TableSetColumnIndex(0)
                    ImGui.PushStyleColor(ImGuiCol.Header,1,1,1,0.10)
                    ImGui.PushStyleColor(ImGuiCol.HeaderHovered,1,1,1,0.06)
                    ImGui.PushStyleColor(ImGuiCol.HeaderActive,1,1,1,0.14)
                    ImGui.PushStyleVar(ImGuiStyleVar.ItemSpacing,0,0)
                    local label = clean(row.name)
                    ImGui.Selectable(label.."##ps_search_"..index, rid ~= nil and ps.selected == rid, 0,
                        (ImGui.CalcTextSize(label)), 0)
                    local clicked = ImGui.IsItemClicked(0)
                    ImGui.PopStyleVar(1); ImGui.PopStyleColor(3)
                    if clicked and not (rid and ps.selected == rid) then
                        if rid then ps.inspect(rid)
                        else ps.resolveOnline(online, row.onlineIndex) end
                    end
                    ImGui.TableSetColumnIndex(1)
                    local hist = rid and ps.historyFor(rid)
                    if hist and (hist.join or hist.leave) then
                        colored(T("Seen together"), TEAL)
                        if ImGui.IsItemHovered() then ImGui.SetTooltip(T("Previously shared a session with you.")) end
                    end
                    ImGui.TableSetColumnIndex(2)
                    muted(rid and tostring(rid) or online and online.resolving == row.onlineIndex and T("Looking up…") or "")
                end
                ImGui.EndTable()
                ps.measureList("search", #rows, startY)
            end
        end
        ImGui.EndChild()
        if #ps.matches > 50 then muted(T("Showing 50 matches. Narrow the name for more.")) end
    end
    function ps.render()
        ImGui.PushID("PlayerHistory")
        if ClickGUI.BeginCustomChildWindow(T("Search players")) then
            muted(T("Rockstar ID or known player name"))
            local width = ImGui.GetContentRegionAvail()
            local showStop = ps.busy and Time.GetEpocheMs() - (ps.busySince or 0) >= 1500
            ImGui.SetNextItemWidth(math.max(120,width-(showStop and 200 or 115)))
            local entered
            ps.input, entered = ImGui.InputText("##ps_query",ps.input,
                ImGuiInputTextFlags.AutoSelectAll | ImGuiInputTextFlags.EnterReturnsTrue)
            ImGui.SameLine()
            local clicked = ImGui.Button(TL("Search"),100,0)
            if entered or clicked then ps.search() end
            if showStop then
                ImGui.SameLine()
                if ImGui.Button(TL("Stop"),70,0) then ps.pendingSearch,ps.pendingRid,ps.stop=nil,nil,true end
            end
            if ps.error then colored(ps.error,AMBER) end
            if ps.nameQuery then
                ps.renderSearchResults()
            end
            ps.renderHistoryStatus("search")
            ClickGUI.EndCustomChildWindow()
        end
        local rid = ps.selected
        if rid and ClickGUI.BeginCustomChildWindow(T("Player details")) then
            local rec = ps.records[rid]
            local result = ps.result and ps.result.rid==rid and ps.result or nil
            ps.renderHistory(rid,rec,ps.renderSession(rid,rec,result))
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.PopID()
    end
end)()

function VIBE_GATE.executableRanges()
    local base = Memory.GetBaseAddress(IS_ENHANCED and "GTA5_Enhanced.exe" or "GTA5.exe")
    if not base or base == 0 then base = Memory.GetBaseAddress() end
    if not base or base == 0 then return nil, "game module base not found" end

    local pe = base + (Memory.ReadUInt(base + 0x3C) or 0)
    if Memory.ReadUInt(pe) ~= 0x4550 then return nil, "PE header not readable" end
    local nSec = Memory.ReadUShort(pe + 6)
    local secTab = pe + 24 + Memory.ReadUShort(pe + 20)

    local out = {}
    for i = 0, nSec - 1 do
        local s = secTab + i * 40
        if (Memory.ReadUInt(s + 36) & 0x20000000) ~= 0 then
            local vsize = Memory.ReadUInt(s + 8)
            local vaddr = Memory.ReadUInt(s + 12)
            out[#out + 1] = {
                bodyFrom = base + vaddr,
                bodyTo = base + vaddr + vsize,
                from = base + vaddr + vsize,
                to = base + vaddr + math.floor((vsize + 0xFFF) / 0x1000) * 0x1000,
            }
        end
    end
    return out
end

