;(function()
    local root = FileMgr.GetMenuRootPath()
    local directory = root .. "\\Lua\\VibeScript\\PlayerNotes\\"
    local records, byName, loadedAt = {}, {}, nil
    local anchor, line, attached
    VIBE_TR.regList({"Player Notes..."})

    local function hoveredRid()
        local list = FeatureMgr.GetFeature(0xD048D7BC)
        local index = list and list:GetListIndex()
        local entry = index and index >= 0 and (list:GetList() or {})[index + 1]
        if not entry then return end
        local clock = Time.GetEpocheMs()
        if not loadedAt or clock - loadedAt >= 10000 then
            byName, loadedAt = {}, clock
            local path = root .. "\\PlayerTracker\\SavedPlayers.json"
            if FileMgr.DoesFileExist(path) then
                local saved = playerSearch.decodeJson(FileMgr.ReadFileContent(path))
                if type(saved) == "table" then
                    for key, data in pairs(saved) do
                        local rid = math.tointeger(key)
                        if rid and rid > 0 and type(data) == "table" and type(data.name) == "string" then
                            local name, seen = data.name:lower(), tonumber(data.last_seen) or 0
                            if not byName[name] or seen > byName[name].seen then
                                byName[name] = { rid = tostring(rid), seen = seen }
                            end
                        end
                    end
                end
            end
        end
        local name = tostring(entry):gsub("%s*%b[]%s*$", ""):lower()
        return byName[name] and byName[name].rid
    end

    local function save(rid, record)
        FileMgr.CreateDir(root .. "\\Lua\\VibeScript")
        FileMgr.CreateDir(directory)
        record.retryAt = Time.GetEpocheMs() + 2000
        record.dirty = not FileMgr.WriteFileContent(directory .. rid .. ".txt", record.text, false)
        if record.dirty and not record.warned then
            record.warned = true
            VIBE_LOG_ERROR(("[PlayerNotes] Local save failed for %s; will retry"):format(rid))
        elseif not record.dirty then record.warned = nil end
    end

    local function draw()
        local rid = hoveredRid()
        if not rid then return end
        local record = records[rid]
        if not record then
            local path = directory .. rid .. ".txt"
            local text = ""
            if FileMgr.DoesFileExist(path) then
                text = FileMgr.ReadFileContent(path)
                if type(text) ~= "string" then return end
            end
            record = { text = text }
            records[rid] = record
        end
        local width = ImGui.GetContentRegionAvail()
        ImGui.SetNextItemWidth(width)
        local text = ImGui.InputTextWithHint("##SavedPlayerNotes" .. rid, T("Player Notes..."), record.text, 0)
        if type(text) == "string" and text ~= record.text then
            if not record.counted then
                record.counted = true
                telemetryCountAction("PlayerNoteEdit")
            end
            record.text, record.dirty = text, true
            save(rid, record)
        end
    end

    local function attach()
        local copy = FeatureMgr.GetFeature(0x212B76BD)
        if not copy then return end
        local nextAction
        for _, feature in pairs(FeatureMgr.GetAllFeatures()) do
            if type(feature) == "number" then feature = FeatureMgr.GetFeature(feature) end
            if feature and feature:GetId() > copy:GetId() and not feature:IsPlayerFeature()
                and (not nextAction or feature:GetId() < nextAction:GetId()) then nextAction = feature end
        end
        if not nextAction or nextAction:GetName(false) ~= "Remove Player" then
            if VIBESCRIPT_VERBOSE == true then VIBE_LOG_ERROR("[PlayerNotes] Saved popup Remove Player anchor not found") end
            return
        end
        anchor = nextAction
        line = FeatureMgr.AddFeature(VIBE_FH("SavedPlayerNotes"), "##SavedPlayerNotes",
            eFeatureType.Custom, "", draw, false)
            :SetNoCallbackOnPress(true):SetSaveable(false):SetSearchable(false)
        anchor:AddRenderAfter(line)
    end

    EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
        if scriptUnloading then return end
        if not attached then attached = true; attach() end
        local clock = Time.GetEpocheMs()
        for rid, record in pairs(records) do
            if record.dirty and clock >= record.retryAt then save(rid, record) end
        end
    end)
    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
        for rid, record in pairs(records) do if record.dirty then save(rid, record) end end
        if anchor and line then anchor:RemoveRenderAfter(line) end
    end)
end)()


