    return (tostring(entry):gsub("%s*%b[]%s*$", ""))
end

local function parseTracker(content)
    local keys, pos = {}, 1
    while true do
        local ks, ke, rid = content:find('"(%d+)"%s*:%s*{', pos)
        if not ks then break end
        keys[#keys + 1] = { rid = rid, from = ke + 1, ks = ks }
        pos = ke + 1
    end
    local byName = {}
    for i, k in ipairs(keys) do
        local stop = keys[i + 1] and (keys[i + 1].ks - 1) or #content
        local slice = content:sub(k.from, stop)
        local name = (slice:match('"name"%s*:%s*"([^"]*)"') or ""):lower()
        local seen = math.tointeger(slice:match('"last_seen"%s*:%s*(%d+)') or 0) or 0
        local prev = byName[name]
        if name ~= "" and (not prev or seen > prev.seen) then
            byName[name] = { rid = math.tointeger(k.rid), seen = seen }
        end
    end
    return byName
end

function ptx.fileRid(fileName, name)
    local f = ptx.files[fileName]
    if not f or now() - f.loadedAt > FILE_RELOAD_MS then
        f = { byName = {}, loadedAt = now() }
        ptx.files[fileName] = f
        local path = TRACKER_DIR .. fileName
        local content = FileMgr.DoesFileExist(path) and FileMgr.ReadFileContent(path)
        if content then f.byName = parseTracker(tostring(content)) end
    end
    local rec = f.byName[name:lower()]
    return rec and rec.rid
end

function ptx.loadFriends()
    local sb = sessionBrowser
    local byName = {}
    local count = Natives.InvokeInt(sb.N.GET_FRIEND_COUNT) or 0
    for i = 0, count - 1 do
        local buffer = GamerHandleBuffer.New()
        if buffer then
            Natives.InvokeVoid(sb.N.HANDLE_FROM_FRIEND, i, buffer:GetBuffer(), sb.SCRIPT_GAMER_HANDLE_WORDS)
            local handle = buffer:ToHandle()
            local rid = handle and handle:IsValid() and math.tointeger(handle.RockstarId or 0)
            local name = Natives.InvokeString(sb.N.GET_FRIEND_NAME, i)
            if rid and rid > 0 and name and name ~= "" then byName[name:lower()] = rid end
        end
    end
    return byName
end

function ptx.friendRid(name)
    local fr = ptx.friends
    if not fr.busy and (not fr.loadedAt or now() - fr.loadedAt > FRIEND_RELOAD_MS) then
        fr.busy = true
        Script.QueueJob(function()
            fr.byName = ptx.loadFriends()
            fr.loadedAt, fr.busy = now(), false
        end)
    end
    return fr.byName[name:lower()]
end

function ptx.hovered(p)
    local list = FeatureMgr.GetFeature(p.list)
    local idx = list and list:GetListIndex()
    if not idx or idx < 0 then return nil end
    local entry = (list:GetList() or {})[idx + 1]
    if not entry then return nil end
    local name = bareName(entry)
    local rid
    if p.friends then rid = ptx.friendRid(name) else rid = ptx.fileRid(p.file, name) end
    return { name = name, rid = rid }
end

function ptx.lookup(rid, entry)
    local sb = sessionBrowser
    local mine = playerSearch.localSession(rid)
    if mine then
        entry.players, entry.max, entry.state = mine.row.players, sb.SESSION_SLOTS, "done"
        return true
    end
    if not sb.supported or not Natives.InvokeBool(sb.N.IS_SIGNED_ONLINE) then
        entry.state = "unavailable"
        return true
    end
    local addr, why = sb.resolveAddresses()
    if not addr then return nil, why end
    local buf, bufWhy = sb.allocBuffers(ptx)
    if not buf then return nil, bufWhy end

    local task = sb.presenceSubmit({ rid }, buf)
    if not task or not sb.awaitTask(task) then return nil, "presence interrupted" end
    if task.state ~= sb.NET_STATUS_SUCCEEDED then
        return nil, ("presence failed (state %s, code %s)"):format(tostring(task.state), tostring(task.code))
    end
    local target
    for _, session in ipairs(sb.presenceCollect(task)) do
        if session.viaRid == rid then target = session; break end
    end
    if not target then
        entry.state = "none"
        return true
    end
    target.members = { rid }
    local detail = sb.detailSubmit({ target }, buf)
    if not detail or not sb.awaitTask(detail) then return nil, "host query interrupted" end
    for _, row in ipairs(sb.detailCollect(detail)) do
        if row.sessionId == target.sessionId then
            local max = row.maxPlayers
            entry.players, entry.max = row.players, (max and max > 0) and max or nil
            break
        end
    end
    entry.state = entry.players and "done" or "unknown"
    return true
end

function ptx.request(rid)
    local t = now()
    if rid ~= ptx.hoverRid then ptx.hoverRid, ptx.hoverAt = rid, t end
    local entry = ptx.lookups[rid]
    if entry and (entry.state == "loading"
            or t - entry.at < (entry.state == "done" and FRESH_MS or RETRY_MS)) then
        return
    end
    if ptx.busy or t - ptx.hoverAt < SETTLE_MS then return end

    ptx.busy = true
    entry = entry or {}
    entry.state, entry.at = "loading", t
    ptx.lookups[rid] = entry
    Script.QueueJob(function()
        local ok, why = ptx.lookup(rid, entry)
        entry.at = now()
        ptx.busy = false
        if not ok then
            entry.state = "error"
            VIBE_LOG_ERROR(("[PlayerTracker] lobby lookup for rid %d failed: %s"):format(rid, tostring(why)))
        end
    end)
end

function ptx.value(p, h)
    if not h then return "-" end
    if not h.rid then
        local fr = ptx.friends
        if p.friends and (fr.busy or not fr.loadedAt) then return nil end
        return "-"
    end
    local entry = ptx.lookups[h.rid]
    if not entry then return nil end
    if entry.players and (entry.state == "done" or entry.state == "loading") then
        return entry.max and ("%d/%d"):format(entry.players, entry.max) or tostring(entry.players)
    end
    if entry.state == "loading" then return nil end
    if entry.state == "none" then return T("None") end
    if entry.state == "unavailable" then return T("Unavailable") end
    return T("Unknown")
end

function ptx.openHistory(p, h)
    local query = h.rid and tostring(h.rid) or h.name
    telemetryCountAction("TrackerVibeHistory")
    playerSearch.input = query
    playerSearch.search()
    VIBE_NAV.open({ ["Session"] = true, ["Player Search/History"] = true })
end

local BUTTON_COLS = { ImGuiCol.Button, ImGuiCol.ButtonHovered, ImGuiCol.ButtonActive }

function ptx.pushButtonTheme()
    local def = Theme.defs[Theme.active] or Theme.defs.none
    local cols = def.colors
    if type(cols) == "function" then cols = cols() end
    local n = 0
    for _, idx in ipairs(BUTTON_COLS) do
        local c = cols and cols[idx]
        if c then
            ImGui.PushStyleColor(idx, c[1] / 255, c[2] / 255, c[3] / 255, (c[4] or 255) / 255)
            n = n + 1
        end
    end
    return n
end

function ptx.drawCount(p)
    local h = ptx.hovered(p)
    if h and h.rid then ptx.request(h.rid) end
    local value = ptx.value(p, h)
    local x0 = ImGui.GetCursorPosX()
    local availW = ImGui.GetContentRegionAvail()
    ImGui.Text(T("Players:"))
    ImGui.SameLine()
    local w
    if value then
        w = ImGui.CalcTextSize(value)
    else
        local base = T("Resolving") .. " "
        value = base .. SPINNER[(now() // SPIN_MS) % #SPINNER + 1]
        w = 0
        for _, frame in ipairs(SPINNER) do
            w = math.max(w, (ImGui.CalcTextSize(base .. frame)))
        end
    end
    ImGui.SetCursorPosX(x0 + availW - w)
    ImGui.Text(value)
end

function ptx.drawHistory(p)
    local h = ptx.hovered(p)
    local pushed = ptx.pushButtonTheme()
    local clicked = ImGui.Button(TL("Check Vibe History") .. "##ptx" .. p.label, 0, 0)
    if pushed > 0 then ImGui.PopStyleColor(pushed) end
    if clicked and h then ptx.openHistory(p, h) end
end

function ptx.countAnchor(anchor)
    local lastId, found = -1, nil
    local anchorId = anchor:GetId()
    local previousBlock = -1
    for _, popup in ipairs(ptx.popups) do
        local final = FeatureMgr.GetFeature(popup.anchor)
        local id = final and final:GetId()
        if id and id < anchorId then previousBlock = math.max(previousBlock, id) end
    end
    for _, feature in pairs(FeatureMgr.GetAllFeatures()) do
        if type(feature) == "number" then feature = FeatureMgr.GetFeature(feature) end
        if feature and feature:GetName(false) == "Join" and not feature:IsPlayerFeature() then
            local id = feature:GetId()
            if id > previousBlock and id < anchorId and id > lastId then lastId, found = id, feature end
        end
    end
    return found
end

function ptx.addLine(p, suffix, draw, description)
    return FeatureMgr.AddFeature(VIBE_FH("PlayerTrackerExtras" .. p.label .. suffix),
        "##PlayerTrackerExtras" .. p.label .. suffix, eFeatureType.Custom, description,
        function() draw(p) end, false)
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)
        :SetSearchable(false)
end

function ptx.attach()
    for _, p in ipairs(ptx.popups) do
        local anchor = FeatureMgr.GetFeature(p.anchor)
        if anchor then
            p.line = ptx.addLine(p, "", ptx.drawHistory, HISTORY_DESCRIPTION)
            anchor:AddRenderAfter(p.line)
            p.anchorFeat = anchor
            local countAnchor = ptx.countAnchor(anchor)
            if countAnchor then
                p.countLine = ptx.addLine(p, "Count", ptx.drawCount, "")
                countAnchor:AddRenderBefore(p.countLine)
                p.countAnchorFeat = countAnchor
            else
                if VIBESCRIPT_VERBOSE == true then VIBE_LOG_ERROR(("[PlayerTracker] %s popup: standalone Join anchor not found"):format(p.label)) end
            end
        else
            if VIBESCRIPT_VERBOSE == true then VIBE_LOG_ERROR(("[PlayerTracker] %s popup: anchor 0x%08X not found"):format(p.label, p.anchor)) end
        end
    end
end

ptx.playerLines = {}

function ptx.openPlayer(pid)
    local player = Players.GetById(pid)
    local info = player and player:GetGamerInfo()
    local rid = info and math.tointeger(info.RockstarId or 0)
    if not rid or rid <= 0 then
        VIBE_LOG_ERROR(("[PlayerTracker] Check Vibe History from player tab: pid %d has no Rockstar ID"):format(pid))
        return
    end
    ptx.openHistory({ label = "Player tab pid " .. pid }, { name = player:GetName(), rid = rid })
end

function ptx.drawPlayerButton(pid)
    local pushed = ptx.pushButtonTheme()
    local clicked = ImGui.Button(TL("Check Vibe History") .. "##ptxpid" .. pid, 0, 0)
    if pushed > 0 then ImGui.PopStyleColor(pushed) end
    if clicked then ptx.openPlayer(pid) end
end

function ptx.attachPlayerTab()
    for _, f in pairs(FeatureMgr.GetAllFeatures()) do
        if type(f) ~= "number" and f:GetName(false) == "Copy Rockstar Id" and f:IsPlayerFeature() then
            local pid = f:GetArrayIndex()
            if pid >= 0 and pid < 32 then
                local line = FeatureMgr.AddFeature(VIBE_FH("PlayerTabVibeHistory" .. pid),
                    "##PlayerTabVibeHistory" .. pid, eFeatureType.Custom, HISTORY_DESCRIPTION,
                    function() ptx.drawPlayerButton(pid) end, false)
                    :SetNoCallbackOnPress(true)
                    :SetSaveable(false)
                    :SetSearchable(false)
                f:AddRenderAfter(line)
                ptx.playerLines[#ptx.playerLines + 1] = { anchor = f, line = line }
            end
        end
    end
    if #ptx.playerLines == 0 then
        if VIBESCRIPT_VERBOSE == true then VIBE_LOG_ERROR("[PlayerTracker] player tab: Copy Rockstar Id anchor not found") end
    end
end

EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
    if ptx.attached or scriptUnloading then return end
    ptx.attached = true
    ptx.attach()
    ptx.attachPlayerTab()
end)

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    for _, p in ipairs(ptx.popups) do
        if p.anchorFeat and p.line then p.anchorFeat:RemoveRenderAfter(p.line) end
        if p.countAnchorFeat and p.countLine then p.countAnchorFeat:RemoveRenderBefore(p.countLine) end
    end
    for _, l in ipairs(ptx.playerLines) do l.anchor:RemoveRenderAfter(l.line) end
end)

end)()

function sessionBrowser.renderResults(mode)
    local sb = sessionBrowser
    mode = (mode == "country") and "country" or "browser"
    local rows = sb.resultStore[mode] or {}
    sb.countryRenderMode = (mode == "country")
    local mineBusy = sb.state.busy and sb.activeMode == mode

    local shown, hidden, incompat = 0, 0, 0
    local filtered = {}
    for _, row in ipairs(rows) do
        if sb.rowIncompatible(row) then
            incompat = incompat + 1
        elseif sb.isListable(row) then
            if sb.matchesSearch(row) then
                shown = shown + 1
                filtered[shown] = row
            else hidden = hidden + 1 end
        end
    end
    local note = (hidden > 0) and ("%d shown, %d hidden"):format(shown, hidden)
        or ("%d shown"):format(shown)
    if incompat > 0 then note = note .. (", %d other build"):format(incompat) end
    sb.sectionHeader(T("LOBBIES"), note)

    if #rows == 0 then
        if mineBusy then
            ImGui.TextColored(0.55, 0.8, 1.0, 1.0,
                T("Scanning - lobbies appear here as hosts answer..."))
        elseif mode == "country" then
            ImGui.TextDisabled(T("No results yet - pick countries, then press Search."))
        else
            ImGui.TextDisabled(T("No results yet - press VibeNet Scan or Local Scan."))
        end
        return
    end

    if shown == 0 then
        ImGui.PushTextWrapPos(0)
        if hidden > 0 then
            ImGui.TextDisabled(T("All %d lobbies are hidden by the filters."):format(hidden))
        elseif incompat > 0 and incompat == #rows then
            ImGui.TextDisabled((T("All %d lobbies found are running a different game build and would refuse the join. Scan again - the shared pool carries players from both builds.")):format(incompat))
        end
        ImGui.PopTextWrapPos()
        return
    end

    local function clamp255(v)
        v = math.floor(v + 0.5)
        return (v < 0) and 0 or (v > 255) and 255 or v
    end

    local _, availY = ImGui.GetContentRegionAvail()
    if not availY or availY < 140 then availY = 140 end
    if ImGui.BeginChild("##BrowserResults", -1, availY, false, 0) then
        local H, JW, JH = 50, 74, 30
        local availW = ImGui.GetContentRegionAvail()
        local hoverChanged = false
        local spacing = ImGui.GetTextLineHeightWithSpacing() - ImGui.GetTextLineHeight()
        local stride = H + spacing
        local first = math.min(shown, math.max(1,
            math.floor((ImGui.GetScrollY() - ImGui.GetCursorPosY()) / stride) + 1))
        local last = math.min(shown, first + math.ceil(availY / stride) + 1)
        if first > 1 then ImGui.Dummy(1, (first - 1) * stride - spacing) end

        for visibleIndex = first, last do
            local row = filtered[visibleIndex]
            local sx, sy = ImGui.GetCursorScreenPos()
            local wx, wy = ImGui.GetCursorPosX(), ImGui.GetCursorPosY()
            local x2, y2 = sx + availW, sy + H
            local hover = ImGui.IsMouseHoveringRect(sx, sy, x2, y2)
            if hover and (mineBusy or sb.state.hoveredResultKey) then
                local key = sb.identity(row)
                if key ~= sb.state.hoveredResultKey then
                    sb.state.hoveredResultKey = key
                    sb.state.hoveredResultIndex = visibleIndex
                    hoverChanged = true
                end
            end

            local bg = hover and 46 or 30
            ImGui.AddRectFilled(sx, sy, x2, y2, bg - 4, bg - 8, bg + 6, 240, 8)
            ImGui.AddRect(sx, sy, x2, y2, 255, 255, 255, hover and 40 or 16, 8, 0, 1)

            local rc = (row.region and sb.REGION_COLOR[row.region])
                or sb.REGION_COLOR_UNKNOWN
            ImGui.AddRectFilled(sx, sy + 2, sx + 4, y2 - 2, rc[1], rc[2], rc[3], 255, 2)

            local cap = sb.displayCap(row)
            local fc = sb.fillColor(row.players, cap)
            local px = sx + 16
            ImGui.SetWindowFontScale(1.15)
            local cnt = cap and ("%d / %d"):format(row.players, cap)
                or tostring(row.players)
            ImGui.AddText(px, sy + 7, cnt, fc[1], fc[2], fc[3], 255)
            ImGui.SetWindowFontScale(1.0)
            local barW = 96
            ImGui.AddRectFilled(px, sy + 31, px + barW, sy + 36, 64, 64, 78, 255, 2)
            if cap and cap > 0 then
                local fw = math.floor(barW * math.min(1, row.players / cap))
                if fw > 0 then
                    ImGui.AddRectFilled(px, sy + 31, px + fw, sy + 36, fc[1], fc[2], fc[3], 255, 2)
                end
            end

            local hx = sx + 132
            ImGui.SetWindowFontScale(1.12)
            ImGui.AddText(hx, sy + 6, tostring(row.hostName or "?"), 240, 240, 245, 255)
            local hw = ImGui.CalcTextSize(tostring(row.hostName or "?"))
            ImGui.SetWindowFontScale(1.0)

            if row.isOwn then
                local tag, tx = "YOUR LOBBY", hx + hw + 12
                local tw, tth = ImGui.CalcTextSize(tag)
                local top, ht = sy + 6, 17
                ImGui.AddRectFilled(tx, top, tx + tw + 12, top + ht, 90, 200, 110, 60, 4)
                ImGui.AddText(tx + 6, top + (ht - tth) * 0.5, tag, 150, 235, 165, 255)
            end

            local age = Time.GetEpoche() - (row.seenAt or 0)
            local ageTxt = row.live and T("LIVE")
                or (age < 5) and T("now")
                or (age < 90) and T("%ds ago"):format(age)
                or T("%dm ago"):format(math.floor(age / 60))
            local ageW = ImGui.CalcTextSize(ageTxt)
            local rightEdge = sx + availW - JW - 20
            if row.live then
                ImGui.AddText(rightEdge - ageW, sy + 8, ageTxt, 150, 235, 165, 255)
            else
                ImGui.AddText(rightEdge - ageW, sy + 8, ageTxt, 150, 150, 165, 255)
            end

            local function chip(cx, text, r, g, b)
                local tw, tth = ImGui.CalcTextSize(text)
                local w, top, ht = tw + 12, sy + 27, 18
                if cx + w > rightEdge then return cx end
                ImGui.AddRectFilled(cx, top, cx + w, top + ht, r, g, b, 45, 4)
                ImGui.AddRect(cx, top, cx + w, top + ht, r, g, b, 150, 4, 0, 1)
                ImGui.AddText(cx + 6, top + (ht - tth) * 0.5, text,
                    clamp255(r + (255 - r) * 0.45),
                    clamp255(g + (255 - g) * 0.45),
                    clamp255(b + (255 - b) * 0.45), 255)
                return cx + w + 6
            end
            local cx = hx
            local cmatch = sb.countryRenderMode and sb.rowCountryMatches(row)
            if cmatch then
                for i = 1, math.min(#cmatch.ccs, 3) do
                    cx = chip(cx, cmatch.ccs[i], 150, 200, 255)
                end
                if #cmatch.ccs > 3 then cx = chip(cx, "+", 150, 200, 255) end
                if cmatch.n > 1 then
                    cx = chip(cx, ("%d known"):format(cmatch.n), 150, 235, 165)
                end
            else
                local regName = row.region and (sb.REGION_SHORT[row.region]
                    or ("R" .. row.region)) or "?"
                cx = chip(cx, regName, rc[1], rc[2], rc[3])
            end
            if row.isJob then
                local why = "JOB"
                if row.purpose and row.purpose ~= sb.SP_FREEROAM then
                    why = (sb.PURPOSE_NAME[row.purpose] or "JOB"):upper()
                elseif row.gameMode and row.gameMode ~= sb.GAMEMODE_FREEROAM then
                    why = T("MODE %s"):format(row.gameMode)
                end
                cx = chip(cx, why, 255, 120, 90)
            end
            local closed = sb.closedLabel(row)
            if closed then cx = chip(cx, closed, 255, 190, 90) end
            if row.freeAim ~= nil then
                if row.freeAim then cx = chip(cx, T("Free aim"), 120, 210, 255)
                else cx = chip(cx, T("Assisted"), 255, 175, 90) end
            end
            if row.natType then
                local nc = sb.NAT_COLOR[row.natType]
                cx = chip(cx, T(sb.NAT_NAME[row.natType]), nc[1], nc[2], nc[3])
            end
            if row.bosses and row.bosses > 0 then
                local limit = sb.bossLimitForDisplay()
                local br, bg, bb = 200, 165, 255
                local label
                if limit then
                    if row.bosses > limit then br, bg, bb = 255, 130, 120 end
                    label = T("%d/%d bosses"):format(row.bosses, limit)
                else
                    label = T("%d bosses"):format(row.bosses)
                end
                cx = chip(cx, label, br, bg, bb)
            end
            if row.badSport then chip(cx, T("Bad sport"), 255, 110, 110) end

            ImGui.SetCursorPosX(wx + availW - JW - 12)
            ImGui.SetCursorPosY(wy + (H - JH) * 0.5)
            ImGui.PushStyleColor(ImGuiCol.Button, 0.20, 0.62, 0.30, 0.95)
            ImGui.PushStyleColor(ImGuiCol.ButtonHovered, 0.26, 0.78, 0.38, 1.0)
            ImGui.PushStyleColor(ImGuiCol.ButtonActive, 0.16, 0.52, 0.26, 1.0)
            if ImGui.Button(T("Join") .. "##join" .. row.token, JW, JH) then
                sb.joinLobby(row)
            end
            ImGui.PopStyleColor(3)

            ImGui.SetCursorPosX(wx)
            ImGui.SetCursorPosY(wy)
            ImGui.Dummy(availW, H)
        end
        if last < shown then ImGui.Dummy(1, (shown - last) * stride - spacing) end
        if hoverChanged then
            local snap = sb.sortedResults(rows, mode == "country")
            sb.resultStore[mode] = snap
            if mode == sb.activeMode then sb.state.results = snap end
        end
    end
    ImGui.EndChild()
end



function sessionBrowser.renderTab()
    local sb = sessionBrowser
    sb.ensureInit()

    if not sb.supported and not sb.finderSupported then
        ImGui.PushID("BrowserUnsupported")
        if ClickGUI.BeginCustomChildWindow(T("Session Browser")) then
            ImGui.PushTextWrapPos(0)
            ImGui.TextColored(1.0, 0.55, 0.35, 1.0, T("Unsupported on this build."))
            ImGui.Text(T("No signature resolved for this edition."))
            ImGui.PopTextWrapPos()
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.PopID()
        return
    end

    ImGui.PushID("BrowserPanel")
    if ClickGUI.BeginCustomChildWindow(T("Session Browser")) then
        sb.renderFilters()
        sb.renderControls()
        ClickGUI.EndCustomChildWindow()
    end
    ImGui.PopID()

    ImGui.PushID("BrowserResults")
    sb.renderResults("browser")
    ImGui.PopID()
end

