function VIBE_NAV.beginTab(english)
    local want = VIBE_NAV.want
    if want and want[english] then
        want[english] = nil
        if os.clock() <= VIBE_NAV.expires then
            local _, selected = ImGui.BeginTabItem(TL(english), true, ImGuiTabItemFlags.SetSelected)
            logf("[Nav] selected tab '%s'", english)
            return selected
        end
    end
    return ImGui.BeginTabItem(TL(english))
end

