                                if isAnyKeyDown(vk) then rs.captureHeld[vk] = true end
                            end
                            rs.captureState = true
                        elseif rs.captureState then
                            ImGui.Text(T(">> Press a key... <<"))
                            for vk = 1, 255 do
                                local down = isAnyKeyDown(vk)
