                                    rs.captureHeld[vk] = nil
                                end
                                if not rs.captureHeld[vk] and down then
                                    rs.rewindVK = vk
                                    if keyFeat then keyFeat:SetIntValue(vk) end
                                    rs.captureState = nil
                                    rs.captureHeld = nil
                                    break
                                end
                            end
                        else
                            if ImGui.Button(TL("Change"), 80, 0) then
                                rs.captureState = "snapshot"
                            end
                            ImGui.SameLine()
                            ImGui.Text(T("Rewind Key: ") .. (rs.VK_NAMES[rs.rewindVK] or (T("Key 0x%02X")):format(rs.rewindVK)))
                            ImGui.SameLine()
                            if ImGui.SmallButton(TL("Reset")) then
                                rs.rewindVK = rs.VK_BACKSPACE
                                if keyFeat then keyFeat:SetIntValue(rs.VK_BACKSPACE) end
                            end
                        end

                        ImGui.PushItemWidth(120)
                        if Widget.beginCombo(T("Rewind Button"), controllerButtonName(rs.controlId)) then
                            for _, btn in ipairs(CONTROLLER_BUTTONS) do
                                if ImGui.Selectable(T(btn.name) .. "##cb" .. btn.id,
