    local vx, vy = ImGui.GetCursorScreenPos()
    ImGui.TextColored(0, 0, 0, 0, versionText)
    local vt = ImGui.GetTime()
    for i = 1, #versionText do
        local ch  = versionText:sub(i, i)
        local hue = (vt * 0.25 + (i - 1) * 0.09) % 1.0
        local rr, gg, bb = ImGui.ColorConvertHSVtoRGB(hue, 0.85, 1.0)
        ImGui.AddText(vx, vy, ch,
            math.floor(rr * 255 + 0.5), math.floor(gg * 255 + 0.5), math.floor(bb * 255 + 0.5), 255)
        vx = vx + ImGui.CalcTextSize(ch)
    end
