ClickGUI.AddTab(VIBE_NAV.title, VIBE_NAV.render)

EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
    local pending = VIBE_NAV.pending
    if not pending or VIBE_UNLOADING then return end
    if os.clock() > VIBE_NAV.expires then
        VIBE_NAV.pending, VIBE_NAV.want = nil, nil
        logf("[Nav] VibeScript tab activation timed out")
        return
    end
    if not GUI.IsOpen() or ClickGUI.GetActiveMenuTab() ~= ClickTab.LuaTab then
        pending.frames = 0
        return
    end
    if pending.recreated then return end
    pending.frames = pending.frames + 1
    if pending.frames < 3 then return end

    local previous = VIBE_NAV.title
    VIBE_NAV.generation = VIBE_NAV.generation + 1
    VIBE_NAV.title = "VibeScript##vibe_nav_" .. VIBE_NAV.generation
    pending.recreated = true
    ClickGUI.RemoveTab(previous)
    ClickGUI.AddTab(VIBE_NAV.title, VIBE_NAV.render)
    VIBE_NAV.expires = os.clock() + 3
    logf("[Nav] Requested VibeScript tab activation: %s", VIBE_NAV.title)
end)

