        ImGui.PushID("TAB_PlayerFriendly")
        if ImGui.BeginTabItem(TL("Friendly")) then
            local fl = ImGuiTableFlags.SizingStretchSame

            if ImGui.BeginTable("##VS_PlayerFriendlyColumns", 2, fl) then
                ImGui.TableNextRow()

                ImGui.TableSetColumnIndex(0)

                ImGui.PushID("PlayerProtection")
                if ClickGUI.BeginCustomChildWindow(T("Protection")) then
                    ClickGUI.RenderFeature(H.GIVE_OTR, playerId)
                    ClickGUI.RenderFeature(H.AUTO_HEAL, playerId)
                    ClickGUI.RenderFeature(H.NEVER_WANTED, playerId)
                    ClickGUI.RenderFeature(H.VEH_GOD, playerId)
                    ClickGUI.RenderFeature(H.VEH_NO_LOCKON, playerId)
                    ClickGUI.EndCustomChildWindow()
                end
                ImGui.PopID()

                ImGui.PushID("PlayerEnginePower")
                if ClickGUI.BeginCustomChildWindow(T("Engine Multiplier")) then
                    ClickGUI.RenderFeature(H.PLAYER_SPEED, playerId)
                    ClickGUI.RenderFeature(H.PLAYER_SPEED_MULT, playerId)
                    ClickGUI.RenderFeature(H.PLAYER_SPEED_AUTO, playerId)
                    ClickGUI.RenderFeature(H.PLAYER_SPEED_SYNC, playerId)
                    ClickGUI.EndCustomChildWindow()
                end
                ImGui.PopID()

                ImGui.TableSetColumnIndex(1)

                ImGui.PushID("PlayerVehicleGun")
                if ClickGUI.BeginCustomChildWindow(T("Weapons")) then
                    ClickGUI.RenderFeature(H.VEH_GUN_TARGET, playerId)
                    ClickGUI.RenderFeature(H.HORN_ROCKETS, playerId)
                    ClickGUI.RenderFeature(H.EXP_BULLETS, playerId)
                    ClickGUI.RenderFeature(H.EXP_BULLETS_TAG)
                    ClickGUI.EndCustomChildWindow()
                end
                ImGui.PopID()

                ImGui.PushID("PlayerMessaging")
                if ClickGUI.BeginCustomChildWindow(T("Messaging")) then
                    local cur = FeatureMgr.GetFeatureString(H.SMS_MSG, playerId) or ""
                    local overLimit = #cur > 60
                    if overLimit then ImGui.PushStyleColor(ImGuiCol.Text, 1.0, 0.35, 0.35, 1.0) end
                    ImGui.SetNextItemWidth(-1)
                    local hint = T("Type an SMS (max 60)...")
                    local newText, submitted = ImGui.InputTextWithHint("##sms_msg_" .. playerId,
                        #cur > #hint and "" or hint, cur,
                        ImGuiInputTextFlags.AutoSelectAll | ImGuiInputTextFlags.EnterReturnsTrue)
                    if overLimit then ImGui.PopStyleColor() end
                    if newText ~= cur then
                        FeatureMgr.GetFeature(H.SMS_MSG, playerId):SetStringValue(newText)
                        FeatureMgr.GetFeature(H.SMS_STATUS, playerId):SetStringValue("")
                    end
                    if #newText > 60 then
                        ImGui.PushTextWrapPos(0)
                        ImGui.TextColored(255, 170, 60, 255,
                            T("Over 60 characters (%d) - shorten to send"):format( #newText))
                        ImGui.PopTextWrapPos()
                    else
                        if submitted then FeatureMgr.GetFeature(H.SMS_SEND, playerId):OnClick() end
                        ClickGUI.RenderFeature(H.SMS_SEND, playerId)
                        ImGui.SameLine()
                        ClickGUI.RenderFeature(H.SMS_KEEP_TEXT)
                        local note = FeatureMgr.GetFeatureString(H.SMS_STATUS, playerId) or ""
                        if note ~= "" then
                            ImGui.PushTextWrapPos(0)
                            ImGui.TextColored(255, 90, 90, 255, note)
                            ImGui.PopTextWrapPos()
                        end
                    end
                    ClickGUI.EndCustomChildWindow()
                end
                ImGui.PopID()

                ImGui.PushID("PlayerSpawnVehicle")
                if ClickGUI.BeginCustomChildWindow(T("Spawn Vehicle")) then
                    chatCommands.renderVehPicker(playerId)
                    ClickGUI.RenderFeature(H.SPAWN_VEH_GOD)
                    ClickGUI.RenderFeature(H.SPAWN_VEH_UPGRADE)
                    ClickGUI.RenderFeature(H.SPAWN_VEH, playerId)
                    ClickGUI.EndCustomChildWindow()
                end
                ImGui.PopID()

                ImGui.EndTable()
            end

            ImGui.EndTabItem()
        end
        ImGui.PopID()

        if VIBESCRIPT_LOADER then
            ImGui.PushID("TAB_PlayerTesting")
            if ImGui.BeginTabItem(TL("Testing")) then
                if DEV.renderTestingTab then DEV.renderTestingTab(playerId) end
                ImGui.EndTabItem()
            end
            ImGui.PopID()
        end

        ImGui.EndTabBar()
    end

    ImGui.PopID()
    Theme.restore()
end)
end

