for _, r in ipairs(forceGuard.RULES) do
    local rule = { animalSelf = r.animalSelf, animalOther = r.animalOther }
    if r.parents then
        rule.parents = {}
        for _, ar in ipairs(r.parents) do rule.parents[Utils.Joaat(ar) & 0xFFFFFFFF] = ar end
    end
    forceGuard.rules[Utils.Joaat(r[1]) & 0xFFFFFFFF] = rule
end

function forceGuard.parse(buf)
    local fw, aw = 25, 5
    local bdt = blameDetect
    if bdt.layout and bdt.LAYOUTS[bdt.layout] then
        fw, aw = bdt.LAYOUTS[bdt.layout][1], bdt.LAYOUTS[bdt.layout][2]
    end
    buf:Seek(0)
    local ev = { dtype = buf:ReadUns(2) }
    buf:ReadUns(32)
    local override = buf:ReadBool()
    buf:ReadBool() buf:ReadBool() buf:ReadBool()
    buf:ReadUns(fw)
    if not buf:ReadBool() then return nil end
    ev.result  = buf:ReadUns(32)
    ev.meleeId = buf:ReadUns(16)
    local fr, ok = buf:ReadUns(32)
    if not ok or fr == 0 then return nil end
    ev.forced = fr
    if override then buf:ReadUns(17) end
    if buf:ReadBool() then buf:ReadUns(aw) end
    if buf:ReadBool() then buf:ReadUns(16) buf:ReadUns(16) buf:ReadUns(16) end
    if ev.dtype == bdt.DAMAGE_PLAYER then
        buf:ReadUns(32)
        buf:ReadBool()
    else
        ev.parentID = buf:ReadUns(13)
    end
    local hit, okHit = buf:ReadUns(13)
    if okHit then ev.hitID = hit end
    return ev
end

function forceGuard.onNetEvent(sender, eventId, buf)
    if not forceGuard.on or scriptUnloading or eventId ~= 6 or not sender or not buf then
        return false
    end
    local block = false
    ;(function()
        local ev = forceGuard.parse(buf)
        local action = ev and forceGuard.byId[ev.forced]
        if not action then return end
        local spid = sender.PlayerId

        local victim = blameDetect.resolveObj(ev.hitID)
        local ours = not victim or victim.owner == forceGuard.mePid

        local ax, ay, az
        if ev.parentID then
            local p = blameDetect.resolveObj(ev.parentID)
            if p then ax, ay, az = p.x, p.y, p.z end
        else
            local ped = Players.GetCPed(spid)
            local pos = ped and ped.Position
            if pos then ax, ay, az = pos.x, pos.y, pos.z end
        end
        local dist
        if ax and victim and victim.x then
            local dx, dy, dz = ax - victim.x, ay - victim.y, az - victim.z
            dist = math.sqrt(dx * dx + dy * dy + dz * dz)
        end

        local victimPid = victim and victim.playerPed and victim.owner
            or (not victim and forceGuard.mePid) or nil
        local rule = forceGuard.rules[ev.forced]
        local why
        if not action.kind:find("AT_HIT_REACTION", 1, true) then
            why = "not a hit reaction (" .. action.kind .. ")"
        elseif rule and rule.animalSelf and victimPid and forceGuard.human[victimPid] then
            why = "animal-only reaction on a human"
        elseif rule and rule.animalOther and ev.dtype == blameDetect.DAMAGE_PLAYER
                and forceGuard.human[spid] then
            why = "needs an animal attacker"
        elseif rule and rule.parents and not rule.parents[ev.result] then
            why = ("reaction to a move that was not sent (result 0x%08X)"):format(ev.result)
        elseif dist and dist > forceGuard.REACH_M then
            why = ("hit reaction from %.0fm"):format(dist)
        end
        if not why then return end

        block = ours
        if #forceGuard.queue < forceGuard.QUEUE_CAP then
            forceGuard.queue[#forceGuard.queue + 1] = {
                at = os.clock() * 1000, pid = spid, name = blameDetect.name(spid),
                victim = victim and victim.playerPed and blameDetect.name(victim.owner),
                ours = ours, action = action, forced = ev.forced,
                meleeId = ev.meleeId, result = ev.result, dist = dist, why = why,
            }
        end
    end)()
    buf:Seek(0)
    return block
end

function forceGuard.report(h)
    local name = h.name or ("player " .. tostring(h.pid))
    local key = tostring(h.pid) .. ":" .. name
    local rec = forceGuard.seen[key]
    if not rec then
        rec = { toastAt = -math.huge }
        forceGuard.seen[key] = rec
    end
    if h.ours then
        VIBE_LOG_INFO(("[Force Animation Protection] Blocked %s from %s."):format(h.action[1], name))
    else
        VIBE_LOG_INFO(("[Force Animation Protection] Detected %s from %s targeting %s.")
            :format(h.action[1], name, h.victim or "an NPC"))
    end
    if not rec.flagged then
        rec.flagged = true
        ModderDB.AddModderByPlayerId(h.pid, forceGuard.REASON)
    end
    if h.ours and h.at - rec.toastAt >= forceGuard.REPEAT_MS then
        rec.toastAt = h.at
        GUI.AddToast(T("Force Animation Protection"),
            T("Blocked %s from %s."):format(T(h.action[1]), name),
            6000, eToastPos.TOP_RIGHT)
    end
end

function forceGuard.tick(f)
    forceGuard.on = f:IsToggled() and not scriptUnloading
    forceGuard.mePid = GTA.GetLocalPlayerId()
    local now = MISC.GET_GAME_TIMER()
    if forceGuard.on and now - forceGuard.humanAt >= 500 then
        forceGuard.humanAt = now
        for pid = 0, 31 do
            local ped = NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid)
                and PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid) or 0
            forceGuard.human[pid] = ped ~= 0
                and Natives.InvokeBool(0xB980061DA992779D, ped) or nil
        end
    end
    for _ = 1, 4 do
        local h = table.remove(forceGuard.queue, 1)
        if not h then break end
        forceGuard.report(h)
    end
end

centralOnTick(FeatureMgr.AddFeature(H.FORCE_GUARD, "Force Animation Protection",
    eFeatureType.Toggle,
    "Stops other players from forcing you to attack, dodge or react. Shows who tried it and marks them as a modder.",
    forceGuard.tick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false):Toggle(true)

forceGuard.evId = EventMgr.RegisterHandler(eLuaEvent.NET_EVENT, forceGuard.onNetEvent)

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    forceGuard.on = false
    if forceGuard.evId then
        EventMgr.RemoveHandler(forceGuard.evId)
        forceGuard.evId = nil
    end
    forceGuard.queue = {}
end)

