    local base = Memory.GetBaseAddress()
    if not base or base == 0 or Memory.ReadUShort(base) ~= 0x5A4D then return end
    local offset = Memory.ReadUInt(base + 0x3C)
    if not offset or offset < 0x40 or offset > 0x1000 then return end
    local pe = base + offset
    if Memory.ReadUInt(pe) ~= 0x4550 or Memory.ReadUShort(pe + 4) ~= 0x8664
        or Memory.ReadUShort(pe + 24) ~= 0x20B then return end
    local profile = G.profiles[Memory.ReadUInt(pe + 8)]
    if not profile then return end
    local size = Memory.ReadUInt(pe + 24 + 56)
    if not size or math.max(profile.rva + 256, profile.lookup + 64, profile.scenes + 64 * 0x280) >= size then return end
    local index = 0
    for byte in profile.bytes:gmatch("%x%x") do
        if Memory.ReadUByte(base + profile.rva + index) ~= tonumber(byte, 16) then return end
        index = index + 1
    end
    return base + profile.rva, base, profile
end
function G.scanExisting()
    local _, base, profile = G.resolveTrigger()
    if not base or not profile then return end
    local i = 0
    for byte in profile.lookupBytes:gmatch("%x%x") do
        if Memory.ReadUByte(base + profile.lookup + i) ~= tonumber(byte, 16) then return end
        i = i + 1
    end
    for slot = 0, 63 do
        local p = base + profile.scenes + slot * 0x280
        local rig = Memory.ReadUByte(p + 0x24A) == 1 and rigs[Memory.ReadUInt(p + 0x240)]
        if rig and Memory.ReadUInt(p + 4) == rig.clip and Memory.ReadUByte(p + 0x248) == 0
            and Memory.ReadUByte(p + 0x249) == 0
            and (rig.rider or (Memory.ReadUInt(p + 0x254) == 0 and Memory.ReadUByte(p + 0x238) == 0
            and Memory.ReadUByte(p + 0x239) == 1 and Memory.ReadUInt(p + 0x14) == 16388)) then
            local scene = Memory.ReadUInt(p + 0x200)
            local h = { scene = scene, started = Memory.ReadUInt(p + 0x208), rider = rig.rider,
                helper = Memory.ReadUShort(p), anchor = Memory.ReadUShort(p + 0x230) }
            local onlyHelper = Memory.ReadUInt(p + 0x1D0) == 0
            for n = 1, 9 do if Memory.ReadUShort(p + n * 0x24) ~= 0 then onlyHelper = false end end
            for n = 0, 4 do if Memory.ReadUShort(p + 0x168 + n * 0x14) ~= 0 then onlyHelper = false end end
            if onlyHelper and scene < 2048 and h.helper ~= 0 and h.anchor ~= 0 and h.helper ~= h.anchor then
                capture(h, scene >> 6, true)
            end
        end
    end
end
local function trackPart(root, entity)
    local net = entity and entity.NetObject
    if not net or net.IsRemote ~= true or net.PlayerId ~= root.pid then return end
    local address = entity:GetAddress()
    if not address or address == 0 or (net.ObjectType ~= 5 and not (net.ObjectType == 6 and address == root.hp)) then return end
    local id = net.ObjectID
    if type(id) ~= "number" or id <= 0 or id >= 8192 then return end
    local old = G.parts[id]
    if old and old.root == root and old.address == address and old.kind == net.ObjectType then return end
    if not G.parts[id] and G.partCount >= 256 then return end
    if not G.parts[id] then G.partCount = G.partCount + 1 end
    G.parts[id] = { root = root, address = address, id = id, kind = net.ObjectType }
end
function G.suppressEntities()
    G.hidden = 0
    if G.rootCount == 0 and G.partCount == 0 then return end
    for id, root in pairs(G.roots) do
        local victim, ap, hp = resolve(root, root.pid)
        if root.removalPending and not victim then
            local a, h = NetworkObjectMgr.GetNetworkObject(root.anchor, true), NetworkObjectMgr.GetNetworkObject(id, true)
            local ae, he = a and a:GetEntity(), h and h:GetEntity()
            if a and a.ObjectType == 11 and a.PlayerId == root.victim and ae and ae:GetAddress() == root.ap
                and h and h.ObjectType == 6 and h.PlayerId == G.localPid and h.IsRemote == false
                and he and he:GetAddress() == root.hp then victim, ap, hp = root.victim, root.ap, root.hp end
        end
        if victim ~= root.victim or ap ~= root.ap or hp ~= root.hp
            or identity(root.pid) ~= root.senderRID or identity(root.victim) ~= root.victimRID then
            G.roots[id], G.rootCount = nil, G.rootCount - 1
        else
            local helper = NetworkObjectMgr.GetNetworkObject(id, true):GetEntity()
            trackPart(root, helper)
            local ext = helper:GetAttachmentExtension()
            local child, seen = ext and ext.AttachChild, {}
            for _ = 1, 32 do
                if not child then break end
                local address = child:GetAddress()
                if not address or seen[address] then break end
                seen[address] = true
                local link = child:GetAttachmentExtension()
                if link and link.AttachParent and link.AttachParent:GetAddress() == hp then trackPart(root, child) end
                child = link and link.AttachSibling
            end
        end
    end
    local ped = Natives.InvokeInt(0x50FAC3A3E030A6E1, G.localPid)
    for id, part in pairs(G.parts) do
        local net = NetworkObjectMgr.GetNetworkObject(id, true)
        local entity = net and net:GetEntity()
        local remote = net and net.IsRemote == true and net.PlayerId == part.root.pid
        local adopted = net and part.removalRequested and net.IsRemote == false and net.PlayerId == G.localPid
            and entity and GTA.PointerToHandle(entity) == part.removalHandle
        if (G.roots[part.root.helper] ~= part.root and not part.root.cleanupRetired) or not net
            or not (remote or adopted) or net.ObjectType ~= part.kind
            or not entity or entity:GetAddress() ~= part.address
            or (not adopted and (identity(part.root.pid) ~= part.root.senderRID or identity(part.root.victim) ~= part.root.victimRID)) then
            G.parts[id], G.partCount = nil, G.partCount - 1
        else
            local handle = GTA.PointerToHandle(entity)
            if part.handle and handle ~= part.handle then
                G.parts[id], G.partCount = nil, G.partCount - 1
            elseif handle and handle ~= 0 then
                part.handle = handle
                Natives.InvokeVoid(0xE135A9FF3F5D05D8, handle)
                if ped and ped ~= 0 then Natives.InvokeVoid(0xA53ED5520C07654A, handle, ped, true) end
                G.hidden = G.hidden + 1
            end
        end
    end
end
function G.onNode(_, _, _, meta, nodes)
    if not G.on or scriptUnloading or not meta or meta.IsRemote ~= true then return true end
    local block = (function()
        local part = G.parts[meta.ObjectID]
        if part and (G.roots[part.root.helper] == part.root or part.root.cleanupRetired) and meta.PlayerId == part.root.pid
            and meta.ObjectType == part.kind then
            local net = NetworkObjectMgr.GetNetworkObject(meta.ObjectID, true)
            local entity = net and net:GetEntity()
            if entity and net.IsRemote == true and net.PlayerId == part.root.pid and net.ObjectType == part.kind
                and entity and entity:GetAddress() == part.address
                and identity(part.root.pid) == part.root.senderRID
                and identity(part.root.victim) == part.root.victimRID then return true end
        end
        if meta.ObjectType ~= 5 then return false end
        for _, node in ipairs(nodes or {}) do
            if node:GetNodeType() == eSyncDataNode.CPhysicalAttachDataNode then
                local attach = node:As("CPhysicalAttachDataNode")
                local root = attach and attach.attached == true and G.roots[attach.attachedObjectID]
                if root and root.pid == meta.PlayerId then
                    local victim, ap, hp = resolve(root, root.pid)
                    if victim == root.victim and ap == root.ap and hp == root.hp
                        and identity(root.pid) == root.senderRID and identity(root.victim) == root.victimRID then
                        local net = NetworkObjectMgr.GetNetworkObject(meta.ObjectID, true)
                        trackPart(root, net and net:GetEntity())
                        return true
                    end
                end
            end
        end
        return false
    end)()
    if block then G.syncBlocked = G.syncBlocked + 1; return false end
    return true
end
local function removalEntity(job)
    local root = job.part.root
    local net = NetworkObjectMgr.GetNetworkObject(job.part.id, true)
    local entity = net and net:GetEntity()
    if not net or not entity or entity:GetAddress() ~= job.part.address or net.ObjectType ~= job.part.kind
        or GTA.PointerToHandle(entity) ~= job.handle then return end
    if job.part.removalRequested and net.IsRemote == false and net.PlayerId == G.localPid then return net, true end
    if identity(root.pid) ~= root.senderRID or identity(root.victim) ~= root.victimRID then return end
    local anchor = NetworkObjectMgr.GetNetworkObject(root.anchor, true)
    local ae = anchor and anchor:GetEntity()
    if not anchor or anchor.ObjectType ~= 11 or anchor.PlayerId ~= root.victim
        or not ae or ae:GetAddress() ~= root.ap then return end
    if net.IsRemote == true and net.PlayerId == root.pid then return net, false end
end
function G.removeRigEntities()
    local at = clock()
    local job = G.removal
    if not job then
        local selected
        for _, part in pairs(G.parts) do
            if not part.removalTried and (part.kind == 5 or part.kind == 6) then
                if not selected or part.kind == 5 then selected = part end
            end
        end
        if not selected then G.removalStatus = G.removalResult or "No unprocessed confirmed rig entities."; return end
        local net = NetworkObjectMgr.GetNetworkObject(selected.id, true)
        local entity = net and net:GetEntity()
        if not entity or entity:GetAddress() ~= selected.address then return end
        local handle = GTA.PointerToHandle(entity)
        if not handle or handle == 0 then return end
        job = { part = selected, handle = handle, started = at, nextAt = at }
        selected.removalHandle = handle
        selected.removalTried, selected.root.cleanupRetired = true, true
        G.removal = job
    end
    if at - job.started > 5000 then
        G.removal, G.removalStatus = nil, "Removal timed out; local suppression retained."
        G.removalResult = G.removalStatus
        return
    end
    if job.submitted then
        local net = NetworkObjectMgr.GetNetworkObject(job.part.id, true)
        local entity = net and net:GetEntity()
        if not entity or entity:GetAddress() ~= job.part.address then
            G.removalGone = G.removalGone + 1
            G.removal, G.removalStatus = nil, "Removed locally; remote removal still requires confirmation."
            G.removalResult = G.removalStatus
        end
        return
    end
    local net, owned = removalEntity(job)
    if not net then G.removal, G.removalStatus = nil, "Rig identity changed; removal cancelled."; return end
    if owned and not job.ownedAt then job.ownedAt = at end
    if at < G.nextRemovalAt or at < job.nextAt then return end
    if owned then
        if at - job.ownedAt < 500 then return end
        if not Natives.InvokeBool(0x01BF60A500E28887, job.handle) then return end
        G.nextRemovalAt = at + 250
        job.submitted = true
        NetworkObjectMgr.UnregisterNetworkObject(net, 1, false, true)
        G.removalSubmitted = G.removalSubmitted + 1
        G.removalStatus = "Network unregistration submitted; remote outcome unverified."
        log("[Attachment Protection] Requested attachment removal (unconfirmed).")
        return
    end
    local pending = net.PendingPlayerId
    if pidValid(pending) and pending ~= G.localPid then return end
    G.nextRemovalAt, job.nextAt = at + 250, at + 500
    job.part.removalRequested = true
    if job.part.kind == 6 then job.part.root.removalPending = true end
    if not job.requested then
        job.requested = true
        Natives.InvokeBool(0xA670B3662FAFFBD0, job.part.id)
        Natives.InvokeBool(0xB69317BF5E782347, job.handle)
        G.removalStatus = "Requested control of confirmed rig entity."
    elseif not job.changedOwner then
        local player = Players.GetById(G.localPid)
        if not player then return end
        job.changedOwner = true
        NetworkObjectMgr.ChangeOwner(net, player, 0)
        G.removalStatus = "Ownership change attempted; waiting for confirmed local control."
    end
end
local function clear()
    G.queue, G.recent, G.notices = {}, {}, {}
    G.nextReportAt = 0
    G.roots, G.parts = {}, {}
    G.rootCount, G.partCount, G.hidden, G.nextScan = 0, 0, 0, 0
    G.removal, G.nextRemovalAt = nil, 0
end
function G.tick(f)
    local wasOn = G.on
    G.on = f:IsToggled() and not scriptUnloading and Natives.InvokeBool(0x9DE624D2FC4B603F)
    G.localPid = GTA.GetLocalPlayerId()
    if not G.on then
        clear()
        G.status = f:IsToggled() and "Waiting for GTA Online." or "Attachment protection is off."
        return
    end
    if not wasOn then
        log("[Attachment Protection] Enabled.")
    end
    local at = clock()
    if at >= G.nextScan then G.nextScan = at + 500; G.scanExisting() end
    G.suppressEntities()
    G.removeRigEntities()
    G.status = "Attachment protection is active."
    if #G.queue == 0 or at < G.nextReportAt then return end
    local h = table.remove(G.queue, 1)
    if at - h.at > 1500 then return end
    ;(function()
        local victim, ap, hp = resolve(h, h.pid)
        if victim ~= h.victim or ap ~= h.ap or hp ~= h.hp
            or not h.senderRID or not h.victimRID or identity(h.pid) ~= h.senderRID
            or identity(h.victim) ~= h.victimRID then return end
        local name = Players.GetName(h.pid) or ("Player " .. h.pid)
        local move = h.rider or "Attachment"
        local notice = G.notices[h.pid]
        if not notice or notice.rid ~= h.senderRID then
            notice = { rid = h.senderRID, moves = {} }
            G.notices[h.pid] = notice
        end
        local rec = notice.moves[move]
        if not rec then
            rec = { toastAt = -math.huge }
            notice.moves[move] = rec
        end
        if not rec.flagged then
            rec.flagged = true
            ModderDB.AddModderByPlayerId(h.pid, move)
        end
        if at - rec.toastAt >= 10000 then
            rec.toastAt = at
            VIBE_LOG_INFO(("[Attachment Protection] Blocked %s from %s."):format(move, name))
            GUI.AddToast(T("Attachment Protection"), T("Blocked %s from %s."):format(T(move), name),
                6000, eToastPos.TOP_RIGHT)
        end
        Natives.InvokeVoid(0xC254481A4574CB2F, h.scene)
        if h.rider then
            local fn = G.resolveTrigger()
            if not fn then
                G.stopUnavailable = true
                VIBE_LOG_ERROR("[Attachment Protection] Could not stop the attachment for everyone. This game version is unsupported.")
                return
            end
            G.nextReportAt = at + 250
            Memory.LuaCallCFunction(fn, h.scene)
            G.stopsSent = G.stopsSent + 1
            log(("[Attachment Protection] Requested removal of %s from %s (unconfirmed).")
                :format(h.rider, name))
        end
    end)()
end
centralOnTick(FeatureMgr.AddFeature(H.ATTACH_GUARD, "Attachment Protection", eFeatureType.Toggle,
    "Blocks unwanted attachments and players riding on you. Shows who tried it and marks them as a modder.", G.tick))
    :SetNoCallbackOnPress(true):SetSaveable(false):Toggle(true)
function G.render()
    ClickGUI.RenderFeature(H.ATTACH_GUARD)
end
G.event = EventMgr.RegisterHandler(eLuaEvent.NET_EVENT, G.onEvent)
G.nodeEvent = EventMgr.RegisterHandler(eLuaEvent.CAN_APPLY_NODE_DATA, G.onNode)
EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    G.on = false
    if G.event then EventMgr.RemoveHandler(G.event); G.event = nil end
    if G.nodeEvent then EventMgr.RemoveHandler(G.nodeEvent); G.nodeEvent = nil end
    clear()
end)
end)()

;(function()

local aimAlerts = {
    hash = H.TARGET_ALERTS,

    POLL_MS   = 200,
    TOAST_MS  = 5000,
    EV_START_PROJECTILE = 18,
    INVALID_OBJ_ID = 8191,
    DRAIN     = 8,
    QUEUE_CAP = 32,

    nextPoll  = 0,
    aimSaid   = {},
    lockSaid  = {},
    fireSaid  = {},
    queue     = {},
    myPedAddr = 0,
    myVehAddr = 0,
    evId      = nil,
    sawEvent  = false,
    warnedWire = false,
}

local function alert(pid, fmt)
    local name = Players.GetName(pid) or ("player " .. tostring(pid))
    Logger.Log(eLogColor.YELLOW, "[VibeScript] Targeting Alerts: " .. fmt:format(name))
    GUI.AddToast("VibeScript", T(fmt):format(name),
        aimAlerts.TOAST_MS, eToastPos.TOP_RIGHT)
end

local function mark(tbl, pid, now, fmt)
    local last = tbl[pid]
    if last and (now - last) < aimAlerts.TOAST_MS then return end
    tbl[pid] = now
    alert(pid, fmt)
end

local function entityAddr(id)
    local o = NetworkObjectMgr.GetNetworkObject(id, true)
    if not o then return nil end
    local e = o:GetEntity()
    if not e then return nil end
    local a = e:GetAddress()
    if not a or a == 0 then return nil end
    return a
end

local function onNetEvent(sender, eventId, buf)
    if scriptUnloading or not sender or not buf then return false end
    if eventId ~= aimAlerts.EV_START_PROJECTILE then return false end

    if not aimAlerts.sawEvent then
        aimAlerts.sawEvent = true
        logf("[TargetingAlerts] network hook active; first START_PROJECTILE from player %s",
            tostring(sender.PlayerId))
    end

    local myPedAddr, myVehAddr = aimAlerts.myPedAddr, aimAlerts.myVehAddr
    if myPedAddr == 0 and myVehAddr == 0 then return false end

    local owner = buf:ReadUns(13)
    buf:ReadUns(32)
    buf:ReadUns(32)
    buf:ReadUns(32) buf:ReadUns(32) buf:ReadUns(32)
    local target, ok = buf:ReadUns(13)
    if not ok or not owner then return false end
    if owner == aimAlerts.INVALID_OBJ_ID
       or target == aimAlerts.INVALID_OBJ_ID then return false end

    if not entityAddr(owner) then
        if not aimAlerts.warnedWire then
            aimAlerts.warnedWire = true
            logf("[TargetingAlerts] START_PROJECTILE owner id %d does not resolve; "
                .. "event id or wire layout moved (missile line is off)", owner)
        end
        return false
    end

    local taddr = entityAddr(target)
    if not taddr then return false end
    if taddr ~= myPedAddr and taddr ~= myVehAddr then return false end

    if #aimAlerts.queue < aimAlerts.QUEUE_CAP then
        aimAlerts.queue[#aimAlerts.queue + 1] = sender.PlayerId
    end
    return false
end

local function poll(now)
    local me = GTA.GetLocalPlayerId()
    local myPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(me)
    if myPed == 0 or not ENTITY.DOES_ENTITY_EXIST(myPed) then return end

    local myVeh = 0
    if PED.IS_PED_IN_ANY_VEHICLE(myPed, false) then
        myVeh = PED.GET_VEHICLE_PED_IS_IN(myPed, false) or 0
        if myVeh ~= 0 and not ENTITY.DOES_ENTITY_EXIST(myVeh) then myVeh = 0 end
    end

    local pedPtr = GTA.HandleToPointer(myPed)
    aimAlerts.myPedAddr = pedPtr and pedPtr:GetAddress() or 0
    if myVeh ~= 0 then
        local vehPtr = GTA.HandleToPointer(myVeh)
        aimAlerts.myVehAddr = vehPtr and vehPtr:GetAddress() or 0
    else
        aimAlerts.myVehAddr = 0
    end

    local lockedOnto = 0
    if myVeh ~= 0 then
        lockedOnto = VEHICLE.GET_VEHICLE_HOMING_LOCKEDONTO_STATE(myVeh) or 0
    end

    local aimers, nAimers, named = {}, 0, false
    for pid = 0, 31 do
        if pid ~= me and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
            local aiming = PLAYER.IS_PLAYER_TARGETTING_ENTITY(pid, myPed)
                        or PLAYER.IS_PLAYER_FREE_AIMING_AT_ENTITY(pid, myPed)
            if not aiming and myVeh ~= 0 then
                aiming = PLAYER.IS_PLAYER_TARGETTING_ENTITY(pid, myVeh)
                      or PLAYER.IS_PLAYER_FREE_AIMING_AT_ENTITY(pid, myVeh)
            end

            local locking = false
            local theirPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
            if theirPed ~= 0 and PED.IS_PED_IN_ANY_VEHICLE(theirPed, false) then
                local theirVeh = PED.GET_VEHICLE_PED_IS_IN(theirPed, false) or 0
                if theirVeh ~= 0
                   and VEHICLE.GET_VEHICLE_HOMING_LOCKON_STATE(theirVeh) >= 1 then
                    Memory.WriteInt(autoLockBuf, 0)
                    if VEHICLE.GET_VEHICLE_LOCK_ON_TARGET(theirVeh, autoLockBuf) then
                        local tgt = Memory.ReadInt(autoLockBuf)
                        if tgt ~= 0 and (tgt == myPed
                           or (myVeh ~= 0 and tgt == myVeh)) then
                            locking = true
                        end
                    end
                end
            end

            if locking then
                named = true
                aimAlerts.aimSaid[pid] = now
                mark(aimAlerts.lockSaid, pid, now, "%s is locking on")
            elseif aiming then
                nAimers = nAimers + 1
                aimers[nAimers] = pid
            end
        end
    end

    if lockedOnto >= 1 and not named and nAimers == 1 then
        local pid = aimers[1]
        aimAlerts.aimSaid[pid] = now
        mark(aimAlerts.lockSaid, pid, now, "%s is locking on")
        return
    end
    for i = 1, nAimers do
        mark(aimAlerts.aimSaid, aimers[i], now, "%s is aiming at you")
    end
end

aimAlerts.clear = function()
    aimAlerts.aimSaid, aimAlerts.lockSaid = {}, {}
    aimAlerts.fireSaid, aimAlerts.queue = {}, {}
end

aimAlerts.unhook = function()
    if not aimAlerts.evId then return end
    EventMgr.RemoveHandler(aimAlerts.evId)
    aimAlerts.evId = nil
    aimAlerts.clear()
    aimAlerts.myPedAddr, aimAlerts.myVehAddr = 0, 0
end

local function aimAlertsOnTick(f)
    if scriptUnloading or not f:IsToggled() then
        aimAlerts.unhook()
        return
    end
    if not aimAlerts.evId then
        aimAlerts.evId = EventMgr.RegisterHandler(eLuaEvent.NET_EVENT, onNetEvent)
    end
    if not isPlayerReady() then return end

    local now = MISC.GET_GAME_TIMER()

    for _ = 1, aimAlerts.DRAIN do
        local pid = table.remove(aimAlerts.queue, 1)
        if not pid then break end
        mark(aimAlerts.fireSaid, pid, now, "%s shot missiles at you")
    end

    if now < aimAlerts.nextPoll then return end
    aimAlerts.nextPoll = now + aimAlerts.POLL_MS
    poll(now)
end

centralOnTick(FeatureMgr.AddFeature(aimAlerts.hash, "Targeting Alerts",
    eFeatureType.Toggle,
    "Toasts when a player aims at you, locks on, or fires missiles at you.",
    aimAlertsOnTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)

EventMgr.RegisterHandler(eLuaEvent.ON_SESSION_CHANGE, function()
    aimAlerts.clear()
end)

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, aimAlerts.unhook)

end)()

local telemetry = {
    BEAT_URL     = "https://api.vibescript.cc/beat",
    INTERVAL_SEC = 90,
    WARMUP_SEC   = 10,
    REQUEST_TIMEOUT_MS = 15000,
    UNLOAD_WAIT_MS = 2000,
    ENABLED      = true,
    SALT         = "bladscript-telemetry-v1",
    _timedOut    = {},
    _inflight    = nil,
}

function telemetry.applyBeatInterval(response)
    if telemetry._intervalConfigured then return end
    if type(response) ~= "string" or not response:find('"beat_interval_sec"%s*:') then return end
    local seconds = tonumber(response:match('"beat_interval_sec"%s*:%s*(%d+)%s*[,}]'))
    if not seconds or seconds < 30 or seconds > 180 then
        VIBE_LOG_ERROR("[Telemetry] Invalid server beat interval; keeping current cadence")
        return
    end
    telemetry.INTERVAL_SEC = seconds
    telemetry._intervalConfigured = true
end

local TELEMETRY_FEATURES = {
    H.RAPID_FIRE,       H.ONFOOT_RAPID,     H.ONFOOT_HOMING_SPAM, H.ROCKET_SPEED,     H.INFINITE_RANGE,   H.INSTANT_ROCKET,
    H.INSTANT_LOCKON,   H.AUTO_LOCKON_FIRE, H.GRAVITY_GUN,      H.GRAV_CONTRIVED,
