local function telemetryJsonStr(s)
    s = s:gsub('\\', '\\\\'):gsub('"', '\\"'):gsub('\n', '\\n'):gsub('\r', '\\r'):gsub('\t', '\\t')
    return '"' .. s .. '"'
end

local function telemetryJsonEncode(v)
    local t = type(v)
    if t == "nil"     then return "null" end
    if t == "boolean" then return v and "true" or "false" end
    if t == "number"  then
        if v ~= v or v == math.huge or v == -math.huge then return "null" end
        if math.type(v) == "integer" then
            return string.format("%d", v)
        end
        if v == math.floor(v) and math.abs(v) < 1e15 then
            return string.format("%d", v)
        end
        return string.format("%.14g", v)
    end
    if t == "string"  then return telemetryJsonStr(v) end
    if t == "table"   then
        local parts = {}
        for k, val in pairs(v) do
            parts[#parts + 1] = telemetryJsonStr(tostring(k)) .. ":" .. telemetryJsonEncode(val)
        end
        return "{" .. table.concat(parts, ",") .. "}"
    end
    return "null"
end

local function telemetryHash(inputStr)
    local h = 2166136261
    local s = telemetry.SALT .. inputStr
    for i = 1, #s do
        h = (h ~ s:byte(i)) * 16777619 & 0xFFFFFFFF
    end
    return string.format("%08x", h)
end

local function telemetryBuildUid()
    return telemetryHash(tostring(Cherax.GetUID()))
end

local function telemetryFeatureBitmap()
    local lo, hi, extra = 0, 0, 0
    for i, hash in ipairs(TELEMETRY_FEATURES) do
        local on
        if not hash then
            on = false
        elseif hash == H.SUPER_MELEE then
            on = (FeatureMgr.GetFeatureInt(H.SUPER_MELEE) or 0) > 0
        elseif hash == H.PLAYER_SPEED_AUTO then
            local sp = playerState.vehAuthor.specByName["EnginePower"]
            on = sp and sp.everUsed
        elseif hash == H.RADIO_PICKER then
            on = radioCtl.pickerUsed
        elseif hash == H.BODYGUARDS then
            on = Bodyguards.wasUsed()
        elseif hash == H.BODYGUARDS_PACK then
            on = Bodyguards.packUsed()
        elseif hash == H.BODYGUARDS_OVER_7 then
            on = Bodyguards.over7Used()
        elseif hash == H.BODYGUARDS_ANIMALS then
            on = Bodyguards.animalsUsed()
        elseif hash == H.TURN_SIGNALS then
            on = turnSignals.wasUsed()
        elseif hash == H.COUNTRY_FINDER then
            on = countryFinder.wasUsed()
        elseif hash == H.LOADOUT_MGR then
            on = LoadoutMgr.wasUsed()
        elseif hash == H.CHAT_TRANSLATE then
            local inFeat = FeatureMgr.GetFeature(H.CHAT_TRANSLATE_IN)
            local outFeat = FeatureMgr.GetFeature(H.CHAT_TRANSLATE_OUT)
            on = (inFeat and inFeat:IsToggled()) or (outFeat and outFeat:IsToggled())
        elseif hash == H.RAPE_PLAYER then
            on = rapePlayer ~= nil and rapePlayer.wasUsed()
        elseif hash == H.PLAYER_ATTACHMENTS then
            on = playerAttachments ~= nil and playerAttachments.everUsed == true
        elseif hash == H.RIDE_PLAYER or hash == H.INFINITE_LADDER
            or hash == H.FLOAT_PLAYER or hash == H.FUCK_VEHICLE or hash == H.FUCK_THEIR_GUNS then
            on = false
            for pid = 0, 31 do
                local feat = FeatureMgr.GetFeature(hash, pid)
                if feat and feat:IsToggled() then on = true; break end
            end
        else
            local feat = FeatureMgr.GetFeature(hash)
            on = feat and feat:IsToggled()
        end
        if on then
            local bit = i - 1
            if bit < 53 then
                lo = lo | (1 << bit)
            elseif bit < 106 then
                hi = hi | (1 << (bit - 53))
            else
                extra = extra | (1 << (bit - 106))
            end
        end
    end
    return lo, hi, extra
end

local function telemetryCheraxVersion()
    local v = tostring(Cherax.GetVersion() or "?")
    local b = tostring(Cherax.GetBuild() or "?")
    return v .. "." .. b
end

local function telemetryGetIgn()
    local ign = ""
    local pid = GTA.GetLocalPlayerId()
    if pid and pid >= 0 then
        local name = PLAYER.GET_PLAYER_NAME(pid)
        if name and name ~= "" and name ~= "**Invalid**" and name ~= "NONE" then
            ign = tostring(name):sub(1, 32)
        end
    end
    return ign
end

telemetry._uid        = telemetryBuildUid()
telemetry._cuid       = math.tointeger(Cherax.GetUID() or 0) or 0
telemetry._battleye   = (Cherax.GetEdition():find("BE") ~= nil) and 1 or 0
telemetry._firstBeatSent = false
local telemetrySessionSeed = table.concat({
    telemetry._uid, tostring(os.time()), tostring(os.clock()), tostring({}),
}, ":")
telemetry._sessionId = telemetryHash(telemetrySessionSeed .. ":a")
                    .. telemetryHash(telemetrySessionSeed .. ":b")
telemetry._nextSeq = 1
telemetry._pendingBeat = nil

local TELEMETRY_FEATURE_LAYOUT = 4

local function telemetryBuildBody(counts, seq, firstBeat)
    local featuresLo, featuresHi, featuresExtra = telemetryFeatureBitmap()
    local payload = {
        uid            = telemetry._uid,
        cuid           = telemetry._cuid,
        rid            = sessionBrowser.localRid(),
        version        = VIBE_VERSION,
        variant        = IS_ENHANCED and "enhanced" or "legacy",
        battleye       = telemetry._battleye,
        cherax         = telemetryCheraxVersion(),
        features       = featuresLo,
        features_hi    = featuresHi,
        features_extra = featuresExtra,
        feature_layout = TELEMETRY_FEATURE_LAYOUT,
        ign            = telemetryGetIgn(),
        loader         = VIBESCRIPT_LOADER and 1 or 0,
        first_beat     = firstBeat and 1 or 0,
        session_id    = telemetry._sessionId,
        seq            = seq,
        beat_interval_sec = telemetry.INTERVAL_SEC,
        counts         = counts,
    }
    if DEV.telemetryFields then DEV.telemetryFields(payload) end
    telemetry._lastPayload = payload
    return telemetryJsonEncode(payload)
end

function telemetry.startPost(url, userAgent, body, noProgress)
    local h
    local ok = pcall(function()
        h = Curl.Easy()
        if noProgress then h:Setopt(eCurlOption.CURLOPT_NOPROGRESS, 1) end
        h:Setopt(eCurlOption.CURLOPT_URL, url)
        h:Setopt(eCurlOption.CURLOPT_CUSTOMREQUEST, "POST")
        h:Setopt(eCurlOption.CURLOPT_USERAGENT, userAgent)
        h:Setopt(eCurlOption.CURLOPT_POSTFIELDS, body)
        h:AddHeader("Content-Type: application/json")
        h:Perform()
    end)
    return ok and h or nil
end

local function telemetryBeatOnce()
    if not telemetry.ENABLED or telemetry._finalSent then return end
    for i = #telemetry._timedOut, 1, -1 do
        local finished = false
        pcall(function() finished = telemetry._timedOut[i]:GetFinished() end)
        if finished then table.remove(telemetry._timedOut, i) end
    end
    if not telemetry._pendingBeat then
        local counts = TELEMETRY_ACTIONS
        TELEMETRY_ACTIONS = {}
        local seq = telemetry._nextSeq
        telemetry._nextSeq = seq + 1
        local firstBeat = not telemetry._firstBeatSent
        telemetry._pendingBeat = {
            body = telemetryBuildBody(counts, seq, firstBeat),
            firstBeat = firstBeat,
        }
        if DEV.telemetryCaptured then DEV.telemetryCaptured() end
    end
    local pending = telemetry._pendingBeat

    local h = telemetry.startPost(telemetry.BEAT_URL, "BladScript-Telemetry/1.0", pending.body)
    if not h then return end
    telemetry._inflight = h
    local deadline = Time.GetEpocheMs() + telemetry.REQUEST_TIMEOUT_MS
    while true do
        local polled, finished = pcall(function() return h:GetFinished() end)
        if not polled then telemetry._inflight = nil; return end
        if finished then break end
        if Time.GetEpocheMs() >= deadline then
            telemetry._inflight = nil
            telemetry._timedOut[#telemetry._timedOut + 1] = h
            return
        end
        Script.Yield()
    end
    telemetry._inflight = nil
    local responseOk = false
    local banned = false
    pcall(function()
        local response = select(2, h:GetResponse())
        responseOk = type(response) == "string"
                 and response:find('"ok":true', 1, true) ~= nil
        if responseOk then telemetry.applyBeatInterval(response) end
        banned = type(response) == "string"
             and response:find('"ban":1', 1, true) ~= nil
        if DEV.telemetryResponse then DEV.telemetryResponse(response) end
    end)
    if banned then
        telemetry._banned = true
        GUI.AddToast("VibeScript",
            T("You have been banned from using VibeScript."), 10000, eToastPos.TOP_RIGHT)
        SetShouldUnload()
        return
    end
    if responseOk then
        if pending.firstBeat then telemetry._firstBeatSent = true end
        telemetry._pendingBeat = nil
    end
end

Script.RegisterLooped(function()
    Script.Yield((telemetry._firstBeatSent and telemetry.INTERVAL_SEC or telemetry.WARMUP_SEC) * 1000)
    if scriptUnloading then return end
    telemetryBeatOnce()
end)

vibenet = {
    CONTRIBUTE_URL = "https://api.vibescript.cc/vibenet/contribute",
    SCAN_URL       = "https://api.vibescript.cc/vibenet/scan",
    WARMUP_SEC     = 20,
    nextPollSec    = 600,
    POST_TIMEOUT_MS = 15000,
    SCAN_COOLDOWN_MS   = 30000,
    maxRidsPerPost = 1000,
    SAMPLE_SEC     = 15,
    JOIN_POLL_MS   = 30000,
    bodyBudget     = 64000,
    OPTIN_FILE     = settings.dir .. "\\vibenet.cfg",

    optIn          = false,
    consentPending = false,
    backoff        = false,
    lastScan       = 0,
    scanning       = false,
    sessionSeen    = {},
    joinPending    = {},
    _warmed        = false,
    _timedOut      = {},
    _inflight      = {},
}

function vibenet.loadOptIn()
    if not FileMgr.DoesFileExist(vibenet.OPTIN_FILE) then vibenet.optIn = false return end
    local content = FileMgr.ReadFileContent(vibenet.OPTIN_FILE)
    local value = content and tostring(content):match("^(%d+)%s*$") or nil
    vibenet.optIn = value == "1" or value == "2"
end

function vibenet.setOptIn(on)
    vibenet.optIn = on and true or false
    FileMgr.WriteFileContent(vibenet.OPTIN_FILE, vibenet.optIn and "1" or "0", false)
end

vibenet.loadOptIn()

function vibenet.post(url, body)
    for i = #vibenet._timedOut, 1, -1 do
        local finished = false
        pcall(function() finished = vibenet._timedOut[i]:GetFinished() end)
        if finished then table.remove(vibenet._timedOut, i) end
    end
    local h = telemetry.startPost(url, "VibeNet/1.0", body)
    if not h then return nil end
    vibenet._inflight[h] = true
    local deadline = Time.GetEpocheMs() + vibenet.POST_TIMEOUT_MS
    while not h:GetFinished() do
        if Time.GetEpocheMs() >= deadline then
            vibenet._inflight[h] = nil
            vibenet._timedOut[#vibenet._timedOut + 1] = h
            return nil
        end
        Script.Yield()
    end
    vibenet._inflight[h] = nil
    local response
    pcall(function()
        response = select(2, h:GetResponse())
    end)
    return response
end

function vibenet.notePlayer(pid, localId, now)
    local player = Players.GetById(pid)
    if not player then return end
    local info = player:GetGamerInfo()
    local rid = info and math.tointeger(info.RockstarId or 0) or nil
    if not rid or rid <= 0 then return end
    local ip, cc
    local addr = pid ~= localId and Players.GetNetAddress(pid) or nil
    if addr and addr.Type == 1 then
        ip = vibenet.publicIpv4(tostring(Players.GetIPString(pid) or "")
            :match("^(%d+%.%d+%.%d+%.%d+)"))
    end
    if ip then
        local ipInfo = Players.GetIPInfo(pid)
        cc = ipInfo and tostring(ipInfo.countryCode or ""):upper() or ""
        if not cc:match("^[A-Z][A-Z]$") or cc == "NA" then cc = nil end
    end
    local prev = vibenet.sessionSeen[rid]
    if not prev or now > prev.seen or (ip and prev.ip ~= ip) or (cc and prev.cc ~= cc) then
        vibenet.sessionSeen[rid] = {
            ip = ip or (prev and prev.ip), cc = cc or (prev and prev.cc),
            seen = now,
            ipSeen = ip and now or (prev and prev.ipSeen) or 0,
        }
    end
    return vibenet.sessionSeen[rid]
end

function vibenet.sampleSession()
    local localId = GTA.GetLocalPlayerId()
    local now = Time.GetEpoche()
    for pid = 0, 31 do vibenet.notePlayer(pid, localId, now) end
end

function vibenet.pollJoins()
    local nowMs, now = Time.GetEpocheMs(), Time.GetEpoche()
    local localId = GTA.GetLocalPlayerId()
    for pid, deadline in pairs(vibenet.joinPending) do
        if nowMs >= deadline or not Players.GetById(pid) then
            vibenet.joinPending[pid] = nil
        else
            local addr = Players.GetNetAddress(pid)
            local entry = addr and vibenet.notePlayer(pid, localId, now) or nil
            if addr and (addr.Type ~= 1 or (entry and entry.ip and entry.cc)) then
                vibenet.joinPending[pid] = nil
            end
        end
    end
end

EventMgr.RegisterHandler(eLuaEvent.ON_PLAYER_JOIN, function(playerId)
    if not vibenet.optIn then return end
    vibenet.notePlayer(playerId, GTA.GetLocalPlayerId(), Time.GetEpoche())
    if playerId ~= GTA.GetLocalPlayerId() then
        vibenet.joinPending[playerId] = Time.GetEpocheMs() + vibenet.JOIN_POLL_MS
    end
end)

Script.RegisterLooped(function()
    Script.Yield(1000)
    if scriptUnloading or not next(vibenet.joinPending) then return end
    local ok, err = pcall(vibenet.pollJoins)
    if not ok and not vibenet._joinWarned then
        vibenet._joinWarned = true
        sessionBrowser.logError("VibeNet join capture crashed: %s", tostring(err))
    end
end)

function vibenet.seenRows(confirmed, budget)
    local rows = {}
    for _, rid in ipairs(confirmed) do
        local live = vibenet.sessionSeen[rid]
        if live and live.seen > 0 then
            local row = ("[%d,%d]"):format(rid, live.seen)
            if #row + 1 > budget then break end
            budget = budget - #row - 1
            rows[#rows + 1] = row
        end
    end
    return rows
end

function vibenet.drainSession(cap, noSample)
    if not noSample then vibenet.sampleSession() end
    local out, countries, ips, drained = {}, {}, {}, {}
    for rid, e in pairs(vibenet.sessionSeen) do
        if #out >= cap then break end
        out[#out + 1] = rid
        drained[rid] = e
        if e.cc then countries[#countries + 1] = ('[%d,"%s"]'):format(rid, e.cc) end
        if e.ip then ips[#ips + 1] = ('[%d,"%s",%d]'):format(rid, e.ip, e.ipSeen or 0) end
    end
    return out, countries, ips, drained
end

function vibenet.publicIpv4(value)
    local a, b, c, d = tostring(value or ""):match(
        "^(%d+)%.(%d+)%.(%d+)%.(%d+)$")
    a, b, c, d = tonumber(a), tonumber(b), tonumber(c), tonumber(d)
    if not a or a > 255 or b > 255 or c > 255 or d > 255 then return nil end
    if a == 0 or a == 10 or a == 127 or a >= 224 then return nil end
    if a == 100 and b >= 64 and b <= 127 then return nil end
    if a == 169 and b == 254 then return nil end
    if a == 172 and b >= 16 and b <= 31 then return nil end
    if a == 192 and b == 168 then return nil end
    if a == 192 and b == 0 and (c == 0 or c == 2) then return nil end
    if a == 198 and (b == 18 or b == 19 or b == 51 and c == 100) then return nil end
    if a == 203 and b == 0 and c == 113 then return nil end
    return ("%d.%d.%d.%d"):format(a, b, c, d)
end

function vibenet.buildContribution(variant, confirmed, countries, ips)
    local body = string.format(
        '{"uid":"%s","variant":"%s","sighting_times":1,"confirmed":[%s],'
            .. '"countries":[%s],"direct_ips":[%s]',
        telemetry._uid, variant, table.concat(confirmed, ","),
        table.concat(countries, ","), table.concat(ips, ","))
    local seenRows = vibenet.seenRows(confirmed, vibenet.bodyBudget - #body - 16)
    body = body .. ',"seen":[' .. table.concat(seenRows, ",") .. ']}'
    sessionBrowser.log("VibeNet contribution: %d session players, %d countries, %d IPs, "
        .. "%d seen, %d bytes", #confirmed, #countries, #ips, #seenRows, #body)
    return body
end

function vibenet.unloadContribution()
    if not vibenet.optIn or vibenet.backoff then return nil end
    local confirmed, countries, ips = vibenet.drainSession(vibenet.maxRidsPerPost, true)
    if #confirmed == 0 then return nil end
    return vibenet.buildContribution(IS_ENHANCED and "enhanced" or "legacy",
        confirmed, countries, ips)
end

function vibenet.contributeOnce()
    if not vibenet.optIn then return end
    if not Natives.InvokeBool(sessionBrowser.N.IS_SIGNED_ONLINE) then return end
    local confirmed, countries, ips, drained = vibenet.drainSession(vibenet.maxRidsPerPost)
    if #confirmed == 0 then return end

    local body = vibenet.buildContribution(IS_ENHANCED and "enhanced" or "legacy",
        confirmed, countries, ips)
    local resp = vibenet.post(vibenet.CONTRIBUTE_URL, body)
    if type(resp) ~= "string" then return end

    local nextPoll = resp:match('"next_poll_sec"%s*:%s*(%d+)')
    if nextPoll then vibenet.nextPollSec = math.max(60, math.tointeger(nextPoll) or 600) end
    local maxRids = math.tointeger(tonumber(resp:match('"max_rids"%s*:%s*(%d+)')))
    if maxRids and maxRids > 0 then
        if maxRids ~= vibenet.maxRidsPerPost then
            sessionBrowser.log("VibeNet contribution limit: %d RIDs per post", maxRids)
        end
        vibenet.maxRidsPerPost = maxRids
        vibenet.bodyBudget = math.max(64000, 64 * maxRids)
    end

    if resp:find('"throttled":true', 1, true) or resp:find('"enabled":0', 1, true) then
        vibenet.backoff = true
        return
    end
    if resp:find('"ok":true', 1, true) then
        vibenet.backoff = false
        for rid, e in pairs(drained) do
            if vibenet.sessionSeen[rid] == e then vibenet.sessionSeen[rid] = nil end
        end
    end
end

function vibenet.requestScan()
    local variant = IS_ENHANCED and "enhanced" or "legacy"
    local body = string.format('{"uid":"%s","variant":"%s"}', telemetry._uid, variant)
    local resp = vibenet.post(vibenet.SCAN_URL, body)
    if type(resp) ~= "string" then return nil, "no response from VibeNet" end
    if resp:find('"enabled":0', 1, true) then return nil, "VibeNet is temporarily disabled" end

    local rids = {}
    local section = resp:match('"rids"%s*:%s*%[(.-)%]')
    if section then
        for rid in section:gmatch("%d+") do
            local n = math.tointeger(rid)
            if n and n > 0 then rids[#rids + 1] = n end
        end
    end
    return rids
end

function vibenet.onScanButton()
    if not vibenet.optIn then
        vibenet.consentPending = true
        return
    end
    vibenet.startScan()
end

function vibenet.cooldownLeft()
    if vibenet.lastScan <= 0 then return 0 end
    local left = vibenet.SCAN_COOLDOWN_MS - (Time.GetEpocheMs() - vibenet.lastScan)
    return (left > 0) and left or 0
end

function vibenet.startScan()
    if sessionBrowser.state.busy or vibenet.scanning then
        sessionBrowser.toast(T("A scan is already running."))
        return
    end
    local left = vibenet.cooldownLeft()
    if left > 0 then
        sessionBrowser.toast(T("VibeNet cooldown: %ds left."):format(
            math.ceil(left / 1000)), 4000)
        return
    end
    vibenet.scanning = true
    Script.QueueJob(function()
        ;(function()
            sessionBrowser.toast(T("VibeNet: fetching recent RIDs..."), 4000)
            vibenet.fetching = true
            local rids, rerr = vibenet.requestScan()
            vibenet.fetching = false
            if not rids then
                sessionBrowser.toast(T("VibeNet: %s"):format(tostring(rerr or "no RIDs")), 6000)
                return
            end
            if #rids == 0 then
                sessionBrowser.toast(T("VibeNet returned no RIDs yet. Try again shortly."), 6000)
                return
            end
            sessionBrowser.toast(T("VibeNet: scanning %d RIDs..."):format(#rids), 4000)
            sessionBrowser.runScan(rids)
        end)()
        vibenet.lastScan = Time.GetEpocheMs()
        vibenet.scanning = false
        vibenet.fetching = false
    end)
end

Script.RegisterLooped(function()
    local wait = vibenet._warmed and vibenet.nextPollSec or vibenet.WARMUP_SEC
    if vibenet.backoff then wait = wait * 2 end
    local ok, err
    local deadline = Time.GetEpocheMs() + wait * 1000
    while true do
        local left = deadline - Time.GetEpocheMs()
        if left <= 0 then break end
        Script.Yield(math.min(left, vibenet.SAMPLE_SEC * 1000))
        if scriptUnloading then return end
        if vibenet.optIn then
            ok, err = pcall(vibenet.sampleSession)
            if not ok and not vibenet._sampleWarned then
                vibenet._sampleWarned = true
                sessionBrowser.logError("VibeNet session sample crashed: %s", tostring(err))
            end
        end
    end
    vibenet._warmed = true
    if scriptUnloading then return end
    ok, err = pcall(vibenet.contributeOnce)
    if not ok then
        sessionBrowser.logError("VibeNet contribution crashed: %s", tostring(err))
    end
end)

function telemetry.finalSends(reason)
    if not telemetry.ENABLED or telemetry._banned or telemetry._finalSent then return end
    telemetry._finalSent = true
    local started = Time.GetEpocheMs()
    local deadline = started + telemetry.UNLOAD_WAIT_MS
    local function settled(h)
        local polled, finished = pcall(function() return h:GetFinished() end)
        return not polled or finished
    end
    local function acked(h)
        local yes = false
        pcall(function()
            local response = select(2, h:GetResponse())
            yes = type(response) == "string" and response:find('"ok":true', 1, true) ~= nil
        end)
        return yes
    end

    local pending, beat = telemetry._pendingBeat, telemetry._inflight
    if pending and beat then
        while not settled(beat) and Time.GetEpocheMs() < deadline do end
        if not settled(beat) or acked(beat) then pending = nil end
    end

    local sends = {}
    if pending then
        sends[#sends + 1] = { what = "Retried beat", url = telemetry.BEAT_URL .. "?final=1",
            ua = "BladScript-Telemetry/1.0", body = pending.body }
    end
    local last = telemetry._lastPayload
    if last then
        local payload = {}
        for k, v in pairs(last) do payload[k] = v end
        payload.seq = telemetry._nextSeq
        telemetry._nextSeq = payload.seq + 1
        payload.counts = TELEMETRY_ACTIONS
        TELEMETRY_ACTIONS = {}
        payload.first_beat = 0
        payload.unload = 1
        if DEV.telemetryFields then DEV.telemetryFields(payload) end
        sends[#sends + 1] = { what = "Unload beat", url = telemetry.BEAT_URL .. "?final=1",
            ua = "BladScript-Telemetry/1.0", body = telemetryJsonEncode(payload) }
    end
    local contribution = vibenet.unloadContribution()
    if contribution then
        sends[#sends + 1] = { what = "Final VibeNet contribution", url = vibenet.CONTRIBUTE_URL .. "?final=1",
            ua = "VibeNet/1.0", body = contribution }
    end

    for _, s in ipairs(sends) do
        s.h = telemetry.startPost(s.url, s.ua, s.body, true)
        if not s.h then VIBE_LOG_ERROR("[Telemetry] " .. s.what .. ": curl refused the request") end
    end
    local others = {}
    if telemetry._inflight then others[#others + 1] = telemetry._inflight end
    for _, h in ipairs(telemetry._timedOut) do others[#others + 1] = h end
    for _, h in ipairs(vibenet._timedOut) do others[#others + 1] = h end
    for h in pairs(vibenet._inflight) do others[#others + 1] = h end
    local open = true
    while open and Time.GetEpocheMs() < deadline do
        open = false
        for _, s in ipairs(sends) do
            if s.h and not s.doneAt then
                if settled(s.h) then s.doneAt = Time.GetEpocheMs() else open = true end
            end
        end
        for _, h in ipairs(others) do
            if not settled(h) then open = true end
        end
    end

    for _, s in ipairs(sends) do
        if s.h then
            local code, response
            if s.doneAt then pcall(function() code, response = s.h:GetResponse() end) end
            if not s.doneAt then
                VIBE_LOG_ERROR(("[Telemetry] %s (%s) still sending after %dms; dropped")
                    :format(s.what, reason, Time.GetEpocheMs() - started))
            elseif tonumber(code) == 0 and (response == nil or response == "") then
                devLog(("[Telemetry] %s (%s) delivered in %dms"):format(s.what, reason, s.doneAt - started))
            else
                VIBE_LOG_ERROR(("[Telemetry] %s (%s) failed after %dms: curl %s, reply %s"):format(
                    s.what, reason, s.doneAt - started, tostring(code), tostring(response):sub(1, 120)))
            end
        end
    end
end

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function() telemetry.finalSends("unload") end)

telemetry.EXIT_BODIES = (function()
    local set = {}
    for _, label in ipairs({ "WARNING_EXIT_SESSION_SHUTDOWN", "WARNING_EXIT_GAME" }) do
        set[Utils.Joaat(label) & 0xFFFFFFFF] = true
    end
    return set
end)()
Script.RegisterLooped(function()
    Script.Yield(50)
    if scriptUnloading or telemetry._finalSent then return end
    if not Natives.InvokeBool(0xE18B138FABC53103) then return end
    local body = Natives.InvokeInt(0x81DF9ABA6C83DFF9) & 0xFFFFFFFF
    if telemetry.EXIT_BODIES[body] then telemetry.finalSends("game exit") end
end)

