function countryFinder.name(cc)
    return T(countryFinder.NAMES[cc] or cc)
end

function countryFinder.loadCache()
    if countryFinder.cache then return end
    countryFinder.cache = {}
    if not FileMgr.DoesFileExist(countryFinder.CACHE_FILE) then return end
    local content = FileMgr.ReadFileContent(countryFinder.CACHE_FILE)
    if type(content) ~= "string" then return end
    for line in content:gmatch("[^\r\n]+") do
        local cc, at, list = line:match("^(%u%u)|(%d+)|(.*)$")
        if cc then
            local rids = {}
            for rid in list:gmatch("%d+") do
                local n = math.tointeger(rid)
                if n and n > 0 then rids[#rids + 1] = n end
            end
            countryFinder.cache[cc] = { at = tonumber(at) or 0, rids = rids }
        end
    end
end

function countryFinder.saveCache()
    if not countryFinder.cache then return end
    local lines = {}
    for cc, e in pairs(countryFinder.cache) do
        lines[#lines + 1] = ("%s|%d|%s"):format(cc, e.at or 0, table.concat(e.rids or {}, ","))
    end
    FileMgr.WriteFileContent(countryFinder.CACHE_FILE, table.concat(lines, "\n"), false)
end

function countryFinder.fetchCounts()
    local body = string.format('{"uid":"%s"}', telemetry._uid or "")
    local resp = vibenet.post(countryFinder.COUNTS_URL, body)
    if type(resp) ~= "string" then return nil end
    if resp:find('"enabled":0', 1, true) then return nil end
    local counts = {}
    local section = resp:match('"counts"%s*:%s*{(.-)}')
    if section then
        for cc, n in section:gmatch('"(%u%u)"%s*:%s*(%d+)') do
            counts[cc] = tonumber(n)
        end
    end
    return counts
end

function countryFinder.ensureCounts()
    if not vibenet.optIn then return end
    if countryFinder.countsBusy then return end
    local now = Time.GetEpoche()
    if countryFinder.counts and (now - countryFinder.countsAt) < countryFinder.TTL_SEC then return end
    countryFinder.countsBusy = true
    Script.QueueJob(function()
        local c = countryFinder.fetchCounts()
        if c then
            countryFinder.counts = c
            countryFinder.countsAt = Time.GetEpoche()
            local n = 0
            for _ in pairs(c) do n = n + 1 end
            sessionBrowser.log("Country counts: %d countries", n)
        end
        countryFinder.countsBusy = false
    end)
end

function countryFinder.fetchByCountry(ccList)
    local quoted = {}
    for _, cc in ipairs(ccList) do quoted[#quoted + 1] = '"' .. cc .. '"' end
    local body = string.format('{"uid":"%s","countries":[%s]}',
        telemetry._uid or "", table.concat(quoted, ","))
    local resp = vibenet.post(countryFinder.BY_COUNTRY_URL, body)
    if type(resp) ~= "string" then return nil end
    if resp:find('"enabled":0', 1, true) then return nil end
    if resp:find('"throttled":true', 1, true) then return nil end
    local grouped = {}
    for cc, list in resp:gmatch('"(%u%u)"%s*:%s*%[(.-)%]') do
        local rids = {}
        for rid in list:gmatch("%d+") do
            local n = math.tointeger(rid)
            if n and n > 0 then rids[#rids + 1] = n end
        end
        grouped[cc] = rids
    end
    return grouped
end

function countryFinder.doSearch()
    local sb = sessionBrowser
    countryFinder.loadCache()
    local now = Time.GetEpoche()

    local selected = {}
    for cc in pairs(countryFinder.selected) do selected[#selected + 1] = cc end
    if #selected == 0 then
        sb.toast(T("Pick at least one country first."), 4000)
        return
    end
    table.sort(selected)

    local stale = {}
    for _, cc in ipairs(selected) do
        local e = countryFinder.cache[cc]
        if not e or (now - (e.at or 0)) >= countryFinder.TTL_SEC then
            stale[#stale + 1] = cc
        end
    end

    if #stale > 0 then
        sb.toast(T("Countries: fetching %d..."):format(#stale), 4000)
        local grouped = {}
        for i = 1, #stale, countryFinder.MAX_PER_REQUEST do
            local part = countryFinder.fetchByCountry(
                table.move(stale, i, math.min(i + countryFinder.MAX_PER_REQUEST - 1, #stale), 1, {}))
            if not part then grouped = nil; break end
            for cc, rids in pairs(part) do grouped[cc] = rids end
        end
        if not grouped then
            sb.toast(T("Countries: no response - using cached results."), 5000)
        else
            for _, cc in ipairs(stale) do
                countryFinder.cache[cc] = { at = now, rids = grouped[cc] or {} }
            end
            countryFinder.saveCache()
        end
    end

    local byRid, rids = {}, {}
    for _, cc in ipairs(selected) do
        local e = countryFinder.cache[cc]
        if e and e.rids then
            for _, rid in ipairs(e.rids) do
                if not byRid[rid] then
                    byRid[rid] = cc
                    rids[#rids + 1] = rid
                    if #rids >= countryFinder.MAX_RIDS then break end
                end
            end
        end
        if #rids >= countryFinder.MAX_RIDS then break end
    end

    countryFinder.byRid = byRid
    countryFinder.status = (T("%d RIDs across %d %s (%d fetched fresh)")):format(
        #rids,  #selected,  #selected == 1 and T("country") or T("countries"),  #stale)
    sb.log("Country search: %d countries, %d RIDs, %d fetched fresh",
        #selected, #rids, #stale)

    if #rids == 0 then
        sb.toast(T("No geolocated RIDs for that selection yet."), 6000)
        return
    end

    sb.runScan(rids, true)
end

function countryFinder.startSearch()
    local sb = sessionBrowser
    if next(countryFinder.selected) == nil then
        sb.toast(T("Pick at least one country first."), 4000)
        return
    end
    countryFinder.used = true
    telemetryCountAction("CountrySearch")
    countryFinder.searching = true
    Script.QueueJob(function()
        countryFinder.doSearch()
        countryFinder.lastSearch = Time.GetEpocheMs()
        countryFinder.searching = false
    end)
end

function countryFinder.onSearchButton()
    local sb = sessionBrowser
    if next(countryFinder.selected) == nil then
        sb.toast(T("Pick at least one country first."), 4000)
        return
    end
    if sb.state.busy or countryFinder.searching then
        sb.toast(T("A scan is already running."))
        return
    end
    local left = countryFinder.SEARCH_COOLDOWN_MS - (Time.GetEpocheMs() - countryFinder.lastSearch)
    if countryFinder.lastSearch > 0 and left > 0 then
        sb.toast(T("Cooldown: %ds left."):format(math.ceil(left / 1000)), 3000)
        return
    end
    countryFinder.startSearch()
end

function countryFinder.orderedList()
    local counts = countryFinder.counts or {}
    local list = {}
    for cc, n in pairs(counts) do list[#list + 1] = { cc = cc, n = n } end
    for cc in pairs(countryFinder.selected) do
        if not counts[cc] then list[#list + 1] = { cc = cc, n = 0 } end
    end
    table.sort(list, function(a, b)
        if a.n ~= b.n then return a.n > b.n end
        return countryFinder.name(a.cc) < countryFinder.name(b.cc)
    end)
    return list
end

function countryFinder.renderControls()
    local sb = sessionBrowser

    if not vibenet.optIn then
        ImGui.PushTextWrapPos(0)
        ImGui.TextColored(0.55, 0.8, 1.0, 1.0, T("VibeNet - shared matchmaking"))
        ImGui.Text(T("VibeNet pools the Rockstar IDs of the players in your session together with other VibeScript users, and hands you a batch of recent IDs to scan for populated lobbies. Share yours to use it?"))
        ImGui.PopTextWrapPos()
        local halfW = math.floor((ImGui.GetContentRegionAvail() - 8) / 2)
        if ImGui.Button(T("Share & enable") .. "##cf_optin", halfW, 0) then
            vibenet.setOptIn(true)
            vibenet.consentPending = false
            countryFinder.ensureCounts()
        end
        ImGui.SameLine()
        if ImGui.Button(T("No thanks") .. "##cf_optout", ImGui.GetContentRegionAvail(), 0) then
            vibenet.setOptIn(false)
        end
        return
    end

    local nSel = 0
    for _ in pairs(countryFinder.selected) do nSel = nSel + 1 end

    local preview = (nSel == 0) and T("Select countries...")
        or (nSel == 1 and T("1 country selected")
                       or T("%d countries selected"):format(nSel))

    ImGui.SetNextItemWidth(ImGui.GetContentRegionAvail())
    if Widget.beginCombo("##cf_countries", preview) then
        ImGui.SetNextItemWidth(-1)
        countryFinder.filter = select(1, ImGui.InputText("##cf_filter", countryFinder.filter, 0))
        local f = tostring(countryFinder.filter or ""):lower()
        if countryFinder.counts == nil then
            ImGui.TextDisabled(T("Loading countries..."))
        else
            local all = ImGui.Button(T("Select all") .. "##cf_all", 0, 0)
            ImGui.SameLine()
            local clear = ImGui.Button(T("Clear") .. "##cf_clear", 0, 0)
            for _, item in ipairs(countryFinder.orderedList()) do
                local cc = item.cc
                local nm = countryFinder.name(cc)
                if f == "" or nm:lower():find(f, 1, true) or cc:lower():find(f, 1, true) then
                    if all then countryFinder.selected[cc] = true end
                    if clear then countryFinder.selected[cc] = nil end
                    local isSel = countryFinder.selected[cc] == true
                    local nowSel = ImGui.Checkbox(
                        (T("%s  (%d)") .. "##cf_%s"):format(nm, item.n, cc), isSel)
                    if nowSel ~= isSel then
                        countryFinder.selected[cc] = nowSel or nil
                    end
                end
            end
        end
        Widget.endCombo()
    end

    if sb.state.busy and sb.activeMode == "country" then
        local fullW = ImGui.GetContentRegionAvail()
        local frac = sb.state.frac or 0
        local text = ("%s - %s"):format(sb.state.phase, sb.state.progress ~= ""
            and sb.state.progress or ("%d%%"):format(math.floor(frac * 100 + 0.5)))
        ImGui.ProgressBar(frac, fullW, 30, text)
    elseif ImGui.BeginTable("##cf_buttons", 2, ImGuiTableFlags.SizingStretchSame) then
        local locked = sb.scanLocked("country")
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0)
        local label = T("Search")
        if countryFinder.searching then
            label = T("Scanning...")
        elseif locked then
            label = T("Scan running")
        else
            local left = countryFinder.SEARCH_COOLDOWN_MS
                - (Time.GetEpocheMs() - countryFinder.lastSearch)
            if countryFinder.lastSearch > 0 and left > 0 then
                label = T("Search (%ds)"):format(math.ceil(left / 1000))
            end
        end
        if sb.dimButton(label .. "##cf_search", ImGui.GetContentRegionAvail(), 0, locked) then
            countryFinder.onSearchButton()
        end
        if locked and ImGui.IsItemHovered() then
            ImGui.SetTooltip(T("A Browser scan is running - it finishes first."))
        end
        ImGui.TableSetColumnIndex(1)
        if ImGui.Button(TL("Clear selection"), ImGui.GetContentRegionAvail(), 0) then
            countryFinder.selected = {}
        end
        ImGui.EndTable()
    end

    if countryFinder.status ~= "" then
        ImGui.TextDisabled(countryFinder.status)
    elseif countryFinder.counts then
        local k = 0
        for _ in pairs(countryFinder.counts) do k = k + 1 end
        ImGui.TextDisabled(T("%d countries available. Pick some, then Search."):format(k))
    end
end

function countryFinder.renderTab()
    local sb = sessionBrowser
    sb.ensureInit()

    if not sb.supported then
        ImGui.PushID("CountryFinderUnsupported")
        if ClickGUI.BeginCustomChildWindow(T("Country Specific Session Browser")) then
            ImGui.PushTextWrapPos(0)
            ImGui.TextColored(1.0, 0.55, 0.35, 1.0,
                T("The Country Finder needs the peer scan, which has no signature on this build."))
            ImGui.PopTextWrapPos()
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.PopID()
        return
    end

    countryFinder.ensureCounts()

    ImGui.PushID("CountryFinderPanel")
    if ClickGUI.BeginCustomChildWindow(T("Country Specific Session Browser")) then
        ImGui.PushTextWrapPos(0)
        ImGui.TextDisabled(T("Disclaimer: Finds players from selected countries in random sessions. For the majority of countries, especially small ones, lobbies may only have at most a few known players per session. The game does not have dedicated lobbies for every country. Dataset grows over time."))
        ImGui.PopTextWrapPos()
        ImGui.Dummy(1, 4)
        countryFinder.renderControls()
        Theme.sep(7)
        local countryScanBusy = sb.state.busy and sb.activeMode == "country"
        if countryScanBusy
                and ImGui.BeginTable("##cf_bottom_actions", 2, ImGuiTableFlags.SizingStretchSame) then
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0)
            ClickGUI.RenderFeature(H.COUNTRY_NOTIFY)
            ImGui.TableSetColumnIndex(1)
            local stopW = math.floor(ImGui.CalcTextSize(T("Stop Scan")) + 20)
            local stopX = ImGui.GetCursorPosX()
                + math.max(0, ImGui.GetContentRegionAvail() - stopW)
            ImGui.SetCursorPosX(stopX)
            if ImGui.Button(TL("Stop Scan"), stopW, 0) then
                sb.requestStop("country")
            end
            ImGui.EndTable()
        else
            ClickGUI.RenderFeature(H.COUNTRY_NOTIFY)
        end
        ClickGUI.EndCustomChildWindow()
    end
    ImGui.PopID()

    local store = sb.resultStore.country
    local mineBusy = sb.state.busy and sb.activeMode == "country"
    if not mineBusy and #store > 0 then
        store = sb.sortedResults(store, true)
        sb.resultStore.country = store
        if sb.activeMode == "country" then sb.state.results = store end
    end
    ImGui.PushID("CountryFinderResults")
    sb.renderResults("country")
    ImGui.PopID()
end

