chatCommands.vehByName = {}
for i = 1, #VEH_NAMES do
    chatCommands.vehByName[VEH_NAMES[i]] = Utils.Joaat(VEH_NAMES[i])
end

function chatCommands.buildDisplayNames()
    if chatCommands.dispName then return end
    chatCommands.dispName = {}
    Script.QueueJob(function()
        local map, n = {}, 0
        for i = 1, #VEH_NAMES do
            if scriptUnloading then return end
            local hash  = chatCommands.vehByName[VEH_NAMES[i]]
            local label = Natives.InvokeString(N_DISPLAY_NAME, hash)
            if type(label) == "string" and label ~= "" then
                local disp = GTA.GetLabelText(label)
                if type(disp) == "string" and disp ~= "" and disp ~= "NULL" then
                    map[disp:lower()] = hash
                end
            end
            n = n + 1
            if n % 120 == 0 then Script.Yield() end
        end
        chatCommands.dispName = map
    end)
end

function chatCommands.resolveVehicle(text)
    local q = text:lower():gsub("%s+", "")
    if q == "" then return nil end
    local exact = chatCommands.vehByName[q]
    if exact then return exact, q end
    local live = Utils.Joaat(q)
    if Natives.InvokeBool(N_IS_MODEL_IN_CDIMAGE, live)
        and Natives.InvokeBool(N_IS_MODEL_A_VEHICLE, live) then
        return live, q
    end
    for i = 1, #VEH_NAMES do
        if VEH_NAMES[i]:sub(1, #q) == q then
            return chatCommands.vehByName[VEH_NAMES[i]], VEH_NAMES[i]
        end
    end
    for i = 1, #VEH_NAMES do
        if VEH_NAMES[i]:find(q, 1, true) then
            return chatCommands.vehByName[VEH_NAMES[i]], VEH_NAMES[i]
        end
    end
    if chatCommands.dispName then
        local d = chatCommands.dispName[text:lower()]
        if d then return d, text:lower() end
        for disp, hash in pairs(chatCommands.dispName) do
            if disp:find(text:lower(), 1, true) then return hash, disp end
        end
    end
    return nil
end

function chatCommands.resolveVehicleChain(text, maxVehicles)
    local q = tostring(text or ""):match("^%s*(.-)%s*$") or ""
    local hash, name = chatCommands.resolveVehicle(q)
    if hash then return { { hash = hash, name = name or q:lower() } } end

    local vehicles, skipped = {}, 0
    for token in q:gmatch("%S+") do
        if maxVehicles and #vehicles >= maxVehicles then
            skipped = skipped + 1
        else
            hash, name = chatCommands.resolveVehicle(token)
            if not hash then return nil, "unknown vehicle '" .. token .. "'" end
            vehicles[#vehicles + 1] = { hash = hash, name = name or token:lower() }
        end
    end
    if #vehicles == 0 then return nil, "unknown vehicle" end
    return vehicles, nil, skipped
end

function chatCommands.giveReward(pid, rewardName)
    local fn = playerState.autoHeal.trigger()
    if not fn then return false end
    Memory.LuaCallCFunction(fn, 1 << pid, Utils.sJoaat(rewardName))
    return true
end

function chatCommands.giveHeal(pid)
    return chatCommands.giveReward(pid, "REWARD_HEALTH")
        and chatCommands.giveReward(pid, "REWARD_ARMOUR")
end

local SNACK_PICKUPS = {
    { "PICKUP_HEALTH_SNACK", "prop_choc_pq",          30 },
    { "PICKUP_CUSTOM_SCRIPT", "prop_choc_ego",        15 },
    { "PICKUP_CUSTOM_SCRIPT", "prop_choc_meto",        5 },
    { "PICKUP_CUSTOM_SCRIPT", "prop_ecola_can",       10 },
