}

function chatCommands.giveSnacks(pid)
    local ped = Natives.InvokeInt(N_GET_PLAYER_PED, pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then
        return false, "player is out of scope"
    end
    local models = {}
    for _, def in ipairs(SNACK_PICKUPS) do
        local model = Utils.Joaat(def[2])
        models[#models + 1] = model
        Natives.InvokeVoid(N_REQUEST_MODEL, model)
    end
    local waited = 0
    while waited < 3000 do
        local ready = true
        for _, model in ipairs(models) do
            if not Natives.InvokeBool(N_HAS_MODEL_LOADED, model) then
                ready = false
                break
            end
        end
        if ready then break end
        Script.Yield(50)
        waited = waited + 50
    end
    for _, model in ipairs(models) do
        if not Natives.InvokeBool(N_HAS_MODEL_LOADED, model) then
            for _, release in ipairs(models) do
                Natives.InvokeVoid(N_MODEL_NO_LONGER, release)
            end
            return false, "snack models did not load"
        end
    end

    chatCommands.giveReward(pid, "REWARD_HEALTH")
    Script.Yield(150)

    local pos = ENTITY.GET_ENTITY_COORDS(ped, true)
    local pickups = {}
    local poolFull = false
    Script.ExecuteAsScript("freemode", function()
        for i, def in ipairs(SNACK_PICKUPS) do
            if not Natives.InvokeBool(N_CAN_REGISTER_PICKUPS, 1) then
                poolFull = true
                break
            end
            local angle = (i - 1) * (math.pi * 2 / #SNACK_PICKUPS)
            local pickup = Natives.InvokeInt(N_CREATE_AMBIENT_PICKUP,
                Utils.Joaat(def[1]),
                pos.x + math.cos(angle) * 0.18,
                pos.y + math.sin(angle) * 0.18,
                pos.z + 0.12,
                0, def[3], models[i], true, false)
            if pickup and pickup ~= 0 then pickups[#pickups + 1] = pickup end
        end
    end)
    for _, model in ipairs(models) do
        Natives.InvokeVoid(N_MODEL_NO_LONGER, model)
    end
    if #pickups == 0 then
        return false, poolFull and "network pickup pool is full"
            or "snack pickups could not be created"
    end

    Script.QueueJob(function()
        Script.Yield(15000)
        Script.ExecuteAsScript("freemode", function()
            for _, pickup in ipairs(pickups) do
                if Natives.InvokeBool(N_DOES_PICKUP_EXIST, pickup) then
                    Natives.InvokeVoid(N_REMOVE_PICKUP, pickup)
                end
            end
        end)
    end)
    if #pickups ~= #SNACK_PICKUPS then
        VIBE_LOG_ERROR(("[ChatCommands] snacks for pid=%d: created %d/%d pickups"):format(pid, #pickups, #SNACK_PICKUPS))
    end
    return true
end

