    { "REWARD_AMMO_PIPEBOMB", 5, 15 },
    { "REWARD_AMMO_PROXMINE", 1, 10 },
    { "REWARD_AMMO_SNOWBALL", 3, 10 },
}

function chatCommands.giveAmmo(pid)
    local sent = 0
    for _, entry in ipairs(chatCommands.AMMO_REWARDS) do
        for _ = 1, math.ceil(entry[3] / entry[2]) do
            if not chatCommands.giveReward(pid, entry[1]) then return false end
            sent = sent + 1
            if sent % 5 == 0 then Script.Yield(50) end
        end
    end
    return true
end

function chatCommands.spawnFor(pid, hash, ownerCommand, row)
    local ped = Natives.InvokeInt(N_GET_PLAYER_PED, pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then return false, "no ped" end

    local pos = ENTITY.GET_ENTITY_COORDS(ped, true)
    local fwd = ENTITY.GET_ENTITY_FORWARD_VECTOR(ped)
    local heading = ENTITY.GET_ENTITY_HEADING(ped) or 0.0
    local z = pos.z + 1.0

    Natives.InvokeVoid(N_REQUEST_MODEL, hash)
    local waited = 0
    while not Natives.InvokeBool(N_HAS_MODEL_LOADED, hash) and waited < 3000 do
        Script.Yield(50); waited = waited + 50
        if scriptUnloading then
            Natives.InvokeVoid(N_MODEL_NO_LONGER, hash)
            return false, "unloading"
        end
    end
    if not Natives.InvokeBool(N_HAS_MODEL_LOADED, hash) then
        Natives.InvokeVoid(N_MODEL_NO_LONGER, hash)
        return false, "model load timeout"
    end

    if not chatCommands.dimBuf then chatCommands.dimBuf = Memory.Alloc(48) end
    local buf = chatCommands.dimBuf
    MISC.GET_MODEL_DIMENSIONS(hash, buf, buf + 24)
    local halfW = math.max(Memory.ReadFloat(buf + 24) - Memory.ReadFloat(buf), 1.0) * 0.5
    local ahead = math.max(-Memory.ReadFloat(buf + 8) + chatCommands.SPAWN_ROW_GAP, 6.0)
    local lateral = 0.0
    if row then
        if not row.right then
            row.right, row.left = halfW, -halfW
        elseif row.right <= -row.left then
            lateral = row.right + chatCommands.SPAWN_ROW_GAP + halfW
            row.right = lateral + halfW
        else
            lateral = row.left - chatCommands.SPAWN_ROW_GAP - halfW
            row.left = lateral - halfW
        end
    end
    local x = pos.x + fwd.x * ahead + fwd.y * lateral
    local y = pos.y + fwd.y * ahead - fwd.x * lateral

    Natives.InvokeVoid(N_REQUEST_COLLISION, x, y, z)

    chatCommands.makeSpawnRoom(pid, ownerCommand)
    local netUsed = louderRadio.netVehicleCount()
    local netMax = NETWORK.GET_MAX_NUM_NETWORK_VEHICLES() or 0
    if netMax > 0 and netUsed > 0
        and netUsed + chatCommands.SPAWN_NET_HEADROOM >= netMax then
        Natives.InvokeVoid(N_MODEL_NO_LONGER, hash)
        VIBE_LOG_ERROR(("[ChatCommands] refused vehicle 0x%08X: network pool headroom (%d/%d)"):format(hash & 0xFFFFFFFF, netUsed, netMax))
        return false, "network vehicle pool is busy"
    end

    local veh, entry, networked, released = 0, nil, false, false
    Script.ExecuteAsScript("freemode", function()
        veh = Natives.InvokeInt(N_CREATE_VEHICLE, hash,
            x + 0.0, y + 0.0, z + 0.0, heading, true, false, false) or 0
        if veh == 0 then return end
        entry = chatCommands.trackSpawn(pid, veh)
        networked = Natives.InvokeBool(N_REGISTER_NETWORKED, veh)
        if networked then
            local netId = Natives.InvokeInt(N_NET_ID_FROM_ENTITY, veh)
            if netId and netId ~= 0 then
                Natives.InvokeVoid(N_ID_CAN_MIGRATE, netId, true)
            end
            Natives.InvokeBool(N_SET_VEH_ON_GROUND, veh, 5.0)
            released = UnloadReap.release(veh)
        end
        if not released then
            if not chatCommands.delBuf then chatCommands.delBuf = Memory.AllocInt() end
            Memory.WriteInt(chatCommands.delBuf, veh)
            ENTITY.DELETE_ENTITY(chatCommands.delBuf)
        end
    end)

    Natives.InvokeVoid(N_MODEL_NO_LONGER, hash)

    if veh == 0 then
        VIBE_LOG_ERROR(("[ChatCommands] networked CREATE_VEHICLE returned 0 for 0x%08X "
            .. "(tracked=%d, vehicles=%d/%d, netVehicles=%d/%d)"):format(hash & 0xFFFFFFFF, chatCommands.spawnCount(),
            PoolMgr.GetCurrentVehicleCount(), PoolMgr.GetMaxVehicleCount(),
            louderRadio.netVehicleCount(), NETWORK.GET_MAX_NUM_NETWORK_VEHICLES()))
        return false, "create returned 0"
    end

    if not released then
        chatCommands.untrackSpawn(pid, entry)
        if ENTITY.DOES_ENTITY_EXIST(veh) then chatCommands.deleteVehicle(entry) end
        VIBE_LOG_ERROR(("[ChatCommands] vehicle 0x%08X %s (vehicles=%d/%d, netVehicles=%d/%d)"):format(hash & 0xFFFFFFFF,
            networked and "networked but mission release failed" or "created but not networked",
            PoolMgr.GetCurrentVehicleCount(), PoolMgr.GetMaxVehicleCount(),
            louderRadio.netVehicleCount(), NETWORK.GET_MAX_NUM_NETWORK_VEHICLES()))
        return false, networked and "mission ownership release failed"
            or "network registration failed"
    end
    entry.pop = UnloadReap.popOf(veh)
    entry.released = true

    return true, nil, veh
end

function chatCommands.trackSpawn(pid, veh)
    local list = chatCommands.spawned[pid]
    if not list then list = {}; chatCommands.spawned[pid] = list end
    local entry = {
        handle = veh,
        addr   = UnloadReap.addrOf(veh),
        pop    = UnloadReap.popOf(veh),
        kind   = "vehicle",
        at     = Time.GetEpocheMs(),
    }
    list[#list + 1] = entry
    return entry
end

function chatCommands.untrackSpawn(pid, entry)
    local list = chatCommands.spawned[pid]
    if not list then return end
    for i = #list, 1, -1 do
        if list[i] == entry then
            table.remove(list, i)
            break
        end
    end
    if #list == 0 then chatCommands.spawned[pid] = nil end
end

function chatCommands.deleteVehicle(entry)
    if type(entry) ~= "table" then return end
    local handle = entry.handle
    if not handle or handle == 0 or not ENTITY.DOES_ENTITY_EXIST(handle) then
        if not entry.released then UnloadReap.mark(entry.addr, entry.pop, entry.kind) end
        return
    end
    local liveAddr = UnloadReap.addrOf(handle)
    if entry.addr and liveAddr ~= entry.addr then
        local marked, reason = UnloadReap.mark(entry.addr, entry.pop, entry.kind)
        if not marked then
            VIBE_LOG_ERROR(("[ChatCommands] recycled spawn handle %d: mark failed: %s")
                :format(handle, tostring(reason)))
        end
        return
    end
    if not chatCommands.delBuf then chatCommands.delBuf = Memory.AllocInt() end
    local buf = chatCommands.delBuf
    NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(handle)
    ENTITY.SET_ENTITY_AS_MISSION_ENTITY(handle, true, true)
    if NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(handle) then
        NETWORK.NETWORK_UNREGISTER_NETWORKED_ENTITY(handle)
    end
    Memory.WriteInt(buf, handle)
    ENTITY.DELETE_ENTITY(buf)
    if ENTITY.DOES_ENTITY_EXIST(handle) then
        Memory.WriteInt(buf, handle)
        ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED(buf)
    end
    if ENTITY.DOES_ENTITY_EXIST(handle) then
        UnloadReap.mark(entry.addr, entry.pop, entry.kind)
    end
end

function chatCommands.spawnCount()
    local n = 0
    for _, list in pairs(chatCommands.spawned) do n = n + #list end
    return n
end

function chatCommands.evictOldestSpawn(pid)
    local bestList, bestIndex, bestAt
    for owner, list in pairs(chatCommands.spawned) do
        if pid == nil or owner == pid then
            for i, entry in ipairs(list) do
                if not bestAt or entry.at < bestAt then
                    bestList, bestIndex, bestAt = list, i, entry.at
                end
            end
        end
    end
    if not bestList then return false end
    local entry = table.remove(bestList, bestIndex)
    chatCommands.deleteVehicle(entry)
    return true
end

function chatCommands.makeSpawnRoom(pid, ownerCommand)
    local mine = chatCommands.spawned[pid]
    while not ownerCommand and mine and #mine >= chatCommands.SPAWN_CAP do
        if not chatCommands.evictOldestSpawn(pid) then break end
    end

    local maxNet = NETWORK.GET_MAX_NUM_NETWORK_VEHICLES() or 0
    local cap = maxNet > 0
        and math.max(1, math.floor(maxNet * chatCommands.SPAWN_NET_SHARE))
        or chatCommands.SPAWN_CAP
    while chatCommands.spawnCount() >= cap do
        if not chatCommands.evictOldestSpawn(nil) then break end
    end
end

function chatCommands.explode(pid)
    local ped = Natives.InvokeInt(N_GET_PLAYER_PED, pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then return false end
    local pos = ENTITY.GET_ENTITY_COORDS(ped, true)
    local myPed = Natives.InvokeInt(N_GET_PLAYER_PED, GTA.GetLocalPlayerId())
    FIRE.ADD_OWNED_EXPLOSION(myPed, pos.x, pos.y, pos.z, 4, 1.0, true, false, 1.0)
    return true
end

function chatCommands.clearWanted(pid)
    if pid == GTA.GetLocalPlayerId() then
        Natives.InvokeVoid(0xB302540597885499, pid)
        return true
    end
    return playerState.neverWanted.sendRemote(pid)
end

function chatCommands.upgrade(pid)
    if PLAYER.IS_REMOTE_PLAYER_IN_NON_CLONED_VEHICLE(pid) then
        return false, "vehicle is too far away"
    end
    local veh = chatCommands.currentVehicle(pid)
    if not veh then return false, "not in a vehicle / out of scope" end

    if not playerState.speed.requestControl(veh) then
        local w = 0
        while not NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(veh) and w < 1500 do
            playerState.speed.requestControl(veh); Script.Yield(100); w = w + 100
        end
    end
    chatCommands.maxMods(veh)
    return true
end

function chatCommands.currentVehicle(pid)
    local ped = Natives.InvokeInt(N_GET_PLAYER_PED, pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then return nil end
    if not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then return nil end
    local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if not veh or veh == 0 or not ENTITY.DOES_ENTITY_EXIST(veh) then return nil end
    return veh
end

function chatCommands.maxMods(veh)
    Natives.InvokeVoid(0x1F2AA07F00B3217A, veh, 0)
    Natives.InvokeVoid(0x2A1F4F37F95BAD08, veh, 18, true)
    Natives.InvokeVoid(0x2A1F4F37F95BAD08, veh, 22, true)
    Natives.InvokeVoid(0x57C51E6BAD752696, veh, 1)
    Natives.InvokeVoid(0xEB9DC3C7D8596C46, veh, false)
    for slot = 0, 49 do
        if slot ~= 48 then
            local count = Natives.InvokeInt(0xE38E9162A2500646, veh, slot) or 0
            if count > 0 then
                Natives.InvokeVoid(0x6AF0636DDEDCB6DD, veh, slot, count - 1, true)
            end
        end
    end
end

chatCommands.VEH_PICK_DEFAULT = "adder"
chatCommands.vehPick = {
    model = chatCommands.VEH_PICK_DEFAULT, filter = "", cats = nil, cat = nil, building = false,
    forceOpen = {}, labelPress = {},
}

function chatCommands.setPickedVehicle(model)
    local vp = chatCommands.vehPick
    model = tostring(model or ""):lower()
    if not chatCommands.vehByName[model] then return end
    vp.model, vp.cat = model, nil
    for ci, cat in ipairs(vp.cats or {}) do
        for _, r in ipairs(cat.rows) do
            if r.model == model then vp.cat = ci end
        end
    end
end

function chatCommands.buildVehCatalog()
    local vp = chatCommands.vehPick
    if vp.cats or vp.building then return end
    vp.building = true
    Script.QueueJob(function()
        local byClass = {}
        for i = 1, #VEH_NAMES do
            if scriptUnloading then return end
            local model = VEH_NAMES[i]
            local hash = chatCommands.vehByName[model]
            if Natives.InvokeBool(N_IS_MODEL_IN_CDIMAGE, hash)
                and Natives.InvokeBool(N_IS_MODEL_A_VEHICLE, hash) then
                local class = Natives.InvokeInt(0xDEDF1C8BD47C2200, hash) or -1
                local disp
                local label = Natives.InvokeString(N_DISPLAY_NAME, hash)
                if type(label) == "string" and label ~= "" then disp = GTA.GetLabelText(label) end
                if type(disp) ~= "string" or disp == "" or disp == "NULL" then disp = model end
                local rows = byClass[class]
                if not rows then rows = {}; byClass[class] = rows end
                rows[#rows + 1] = {
                    model = model,
                    label = ("%s (%s)"):format(disp, model),
                    find  = (disp .. " " .. model):lower(),
                }
            end
            if i % 60 == 0 then Script.Yield() end
        end
        local classes = {}
        for class in pairs(byClass) do classes[#classes + 1] = class end
        table.sort(classes)
        local cats = {}
        for _, class in ipairs(classes) do
            local rows = byClass[class]
            table.sort(rows, function(a, b) return a.find < b.find end)
            local name = GTA.GetLabelText(("VEH_CLASS_%d"):format(class))
            if type(name) ~= "string" or name == "" or name == "NULL" then
                name = T("Class %d"):format(class)
            end
            cats[#cats + 1] = { name = name, rows = rows }
            for _, r in ipairs(rows) do
                if r.model == vp.model then vp.cat = #cats end
            end
        end
        vp.cats = cats
        vp.building = false
    end)
end

function chatCommands.renderVehPicker(playerId)
    local vp = chatCommands.vehPick
    if not vp.cats then
        chatCommands.buildVehCatalog()
        ImGui.TextColored(150, 150, 150, 255, T("Loading vehicles..."))
        return
    end
    ImGui.SetNextItemWidth(-1)
    vp.filter = ImGui.InputTextWithHint("##sv_search", T("Search vehicles"), vp.filter) or ""
    local needle = vp.filter:lower():match("^%s*(.-)%s*$") or ""

    local function row(ci, r)
        local width = ImGui.GetContentRegionAvail()
        if ImGui.Selectable(r.label .. "##sv_" .. r.model, r.model == vp.model) then
            vp.model, vp.cat = r.model, ci
        end
        if ImGui.IsItemHovered() and ImGui.IsMouseDoubleClicked(0) then
            vp.model, vp.cat = r.model, ci
            FeatureMgr.GetFeature(H.SPAWN_VEH, playerId):OnClick()
        end
        Widget.overflowTooltip(r.label, width)
    end

    if ImGui.BeginChild("sv_modeltree", 0, 130, true) then
        if needle ~= "" then
            if vp.searchNeedle ~= needle or vp.searchCats ~= vp.cats then
                vp.searchNeedle, vp.searchCats, vp.searchRows = needle, vp.cats, {}
                for ci, cat in ipairs(vp.cats) do
                    for _, r in ipairs(cat.rows) do
                        if r.find:find(needle, 1, true) then
                            vp.searchRows[#vp.searchRows + 1] = {ci=ci, row=r}
                        end
                    end
                end
            end
            Widget.clippedRows(#vp.searchRows, 130, function(index)
                local match = vp.searchRows[index]
                row(match.ci, match.row)
            end)
        else
            for ci, cat in ipairs(vp.cats) do
                local forced = vp.forceOpen[ci]
                if forced ~= nil then
                    ImGui.SetNextItemOpen(forced, ImGuiCond.Always)
                    vp.forceOpen[ci] = nil
                elseif vp.cat == ci then
                    ImGui.SetNextItemOpen(true, ImGuiCond.Once)
                end
                local open = ImGui.TreeNodeEx(("sv_cat%d"):format(ci),
                    ImGuiTreeNodeFlags.SpanAvailWidth | ImGuiTreeNodeFlags.OpenOnArrow,
                    ("%s (%d)"):format(cat.name, #cat.rows))
                local mouseX, mouseY = ImGui.GetMousePos()
                local itemX, itemY = ImGui.GetItemRectMin()
                local itemX2, itemY2 = ImGui.GetItemRectMax()
                local overLabel = mouseX >= itemX + ImGui.GetTreeNodeToLabelSpacing()
                    and mouseX <= itemX2 and mouseY >= itemY and mouseY <= itemY2
                if overLabel and ImGui.IsMouseClicked(0, false) then
                    vp.labelPress[ci] = not open
                end
                local requested = vp.labelPress[ci]
                if requested ~= nil and ImGui.IsMouseReleased(0) then
                    if overLabel then vp.forceOpen[ci] = requested end
                    vp.labelPress[ci] = nil
                end
                if open then
                    Widget.clippedRows(#cat.rows, 130, function(index) row(ci, cat.rows[index]) end)
                    ImGui.TreePop()
                end
            end
        end
    end
    ImGui.EndChild()
end

function chatCommands.giftPicked(pid)
    local model = chatCommands.vehPick.model
    local name = Players.GetName(pid) or tostring(pid)
    local hash = chatCommands.vehByName[model] or Utils.Joaat(model)
    local ok, why, veh = chatCommands.spawnFor(pid, hash, true)
    if not ok then
        GUI.AddToast("VibeScript", T("Spawn Vehicle failed: %s"):format(tostring(why)), 4000)
        return
    end
    telemetryCountAction("SpawnVehicle")
    local god = FeatureMgr.GetFeature(H.SPAWN_VEH_GOD):IsToggled()
    local upgrade = FeatureMgr.GetFeature(H.SPAWN_VEH_UPGRADE):IsToggled()
    local control, reg = true, "-"
    if god or upgrade then
        local waited = 0
        control = playerState.vehAuthor.takeControl(veh, true)
        while not control and waited < 1500 do
            Script.Yield(100); waited = waited + 100
            control = playerState.vehAuthor.takeControl(veh, true)
        end
        if upgrade then chatCommands.maxMods(veh) end
        if god then
            playerState.vehAuthor.applyVehGod(veh)
            reg = playerState.vehAuthor.registerForSync(veh, true)
        end
    end
    GUI.AddToast("VibeScript", T("Spawned %s for %s."):format(model, name), 3000)
end

for _, hash in ipairs(FeatureMgr.AddPlayerFeature(
    H.SPAWN_VEH, "Spawn Vehicle", eFeatureType.Button,
    "Spawns the selected vehicle in front of this player.",
    function(f)
        local pid = f:GetPlayerIndex()
        if not VibeJobLock.take("SpawnVehicle", 8000) then
            GUI.AddToast("VibeScript", T("Spawn Vehicle is already working; wait for it to finish."), 3000)
            return
        end
        Script.QueueJob(function()
            chatCommands.giftPicked(pid)
            VibeJobLock.release("SpawnVehicle")
        end)
    end)) do
