local function isButtonFeatureType(featureType)
    if featureType == eFeatureType.Button or featureType == 0 then return true end
    local text = tostring(featureType):lower()
    return text == "button" or text:match("%.button$") ~= nil
end

local function getFeatureName(feature)
    local name = feature:GetName(false)
    if type(name) == "string" then
        name = name:match("^(.-)##") or name
        name = name:match("^%s*(.-)%s*$") or name
        return name
    end
    return nil
end

local function isVibeFeatureHash(hash)
    if type(hash) ~= "number" then return false end
    if VIBE_GATE.hashes[hash] == true then return true end
    local unsigned = hash % 0x100000000
    local signed = unsigned >= 0x80000000 and (unsigned - 0x100000000) or unsigned
    return VIBE_GATE.hashes[unsigned] == true or VIBE_GATE.hashes[signed] == true
end

