function chatCommands.queueBuiltin(nameOrHash, pid, playerFeature, expectedName)
    chatCommands.builtinQ[#chatCommands.builtinQ + 1] = {
        key = nameOrHash, pid = pid, playerFeature = playerFeature ~= false,
        expectedName = expectedName,
    }
end

function chatCommands.resolveBuiltin(key, pid, playerFeature)
    if type(key) == "number" then
        if playerFeature == false then return FeatureMgr.GetFeature(key) end
        return FeatureMgr.GetFeature(key, pid)
    end
    if playerFeature == false then return FeatureMgr.GetFeature(key) end
    local f = FeatureMgr.GetFeatureByName(tostring(key), pid)
    if f then return f end
    return FeatureMgr.GetFeature(Utils.Joaat((tostring(key):gsub("%s+", ""))), pid)
end

EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
    if scriptUnloading or #chatCommands.builtinQ == 0 then return end
    local job = table.remove(chatCommands.builtinQ, 1)
    if not job then return end
    if job.playerFeature and not NETWORK.NETWORK_IS_PLAYER_CONNECTED(job.pid) then return end
    local f = chatCommands.resolveBuiltin(job.key, job.pid, job.playerFeature)
    if f and job.expectedName then
        local featureType = f:GetType()
        if not isButtonFeatureType(featureType)
            or getFeatureName(f) ~= job.expectedName then return end
    end
    if f then
        f:OnClick()
    else
        VIBE_LOG_ERROR(("[ChatCommands] built-in %s not found for pid=%d"):format(tostring(job.key), job.pid))
    end
end)

function chatCommands.def(key, name, tier, aliases, arg, run)
    local d = {
        key = key, name = name, tier = tier, on = true,
        aliases = aliases, arg = arg, run = run,
        defTier = tier, defAliases = { table.unpack(aliases) },
        seq = #chatCommands.order + 1,
    }
    chatCommands.commands[key] = d
    chatCommands.order[#chatCommands.order + 1] = key
    return d
end

chatCommands.def("spawn", "Spawn vehicle", SAFE, { "spawn", "s" }, "vehicle",
    function(pid, arg, ownerCommand)
        local maxVehicles
        if not ownerCommand then maxVehicles = chatCommands.SPAWN_CAP end
        local vehicles, why, skipped = chatCommands.resolveVehicleChain(arg, maxVehicles)
        if not vehicles then return false, why end

        local spawned, row, handles = {}, {}, {}
        for _, vehicle in ipairs(vehicles) do
            local ok, veh
            ok, why, veh = chatCommands.spawnFor(pid, vehicle.hash, ownerCommand, row)
            if not ok then
                if #spawned > 0 then
                    return false, ("spawned %d, then failed: %s"):format(#spawned, tostring(why))
                end
                return false, why
            end
            chatCommands.maxMods(veh)
            spawned[#spawned + 1] = vehicle.name
            handles[#handles + 1] = veh
        end

        local warning = (skipped or 0) > 0
            and (" Ignored %d extra vehicle%s; limit is %d."):format(
                skipped, skipped == 1 and "" or "s", maxVehicles)
            or ""
        if #spawned > 1 and spawned[1] == spawned[#spawned] then
            local same = true
            for i = 2, #spawned do
                if spawned[i] ~= spawned[1] then same = false; break end
            end
            if same then
                return true, ("Spawned %s x%d."):format(spawned[1], #spawned) .. warning
            end
        end
        return true, "Spawned " .. table.concat(spawned, ", ") .. "." .. warning
    end)
