chatCommands.TP_CARRIER = Utils.Joaat("rcbandito")
chatCommands.tpActive = nil
chatCommands.tpBusyUntil = 0

function chatCommands.tpGroundZ(x, y)
    if not chatCommands.tpBuf then chatCommands.tpBuf = Memory.Alloc(8) end
    local buf = chatCommands.tpBuf
    local approx = Natives.InvokeFloat(0x29C24BFBED8AB8FB, x + 0.0, y + 0.0) or 0.0
    local deadline = Time.GetEpocheMs() + 2000
    repeat
        STREAMING.REQUEST_COLLISION_AT_COORD(x, y, approx)
        if Natives.InvokeBool(0xC906A7DAB05C8D2B, x + 0.0, y + 0.0, approx + 100.0, buf, false, false) then
            return Memory.ReadFloat(buf) + 1.0
        end
        Script.Yield(100)
    until scriptUnloading or Time.GetEpocheMs() > deadline
    return approx + 1.0
end

function chatCommands.tpVehicle(veh, x, y, z)
    local deadline = Time.GetEpocheMs() + 2000
    while not NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(veh) do
        if scriptUnloading or Time.GetEpocheMs() > deadline or not ENTITY.DOES_ENTITY_EXIST(veh) then
            return false, "couldn't take control of their vehicle"
        end
        NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(veh)
        Script.Yield(50)
    end
    Natives.InvokeVoid(0x239A3351AC1DA385, veh, x + 0.0, y + 0.0, z + 0.0, true, true, true)
    return true
end

function chatCommands.tpOnSyncNode(nodeType, node)
    local a = chatCommands.tpActive
    if not a or nodeType ~= eSyncDataNode.CVehicleProximityMigrationDataNode then return end
    local p = node.position
    if not p or (p.x - a.src.x) ^ 2 + (p.y - a.src.y) ^ 2 > 25.0 then return end
    if a.base == nil then a.base = node.hasOccupant[0] ~= nil and 0 or 1 end
    node.hasOccupant[a.base] = true
    node.occupantID[a.base] = a.netId
    node.isMoving = true
    node.position = V3.New(a.x, a.y, a.z)
    a.writes = a.writes + 1
end

function chatCommands.tpCarrier(pid, ped, x, y, z)
    local cped = Players.GetCPed(pid)
    local netObj = cped and cped.NetObject
    local netId = netObj and math.tointeger(netObj.ObjectID) or 0
    if netId == 0 then return false, "player has no network object" end
    local hash = chatCommands.TP_CARRIER
    Natives.InvokeVoid(N_REQUEST_MODEL, hash)
    local waited = 0
    while not Natives.InvokeBool(N_HAS_MODEL_LOADED, hash) and waited < 3000 and not scriptUnloading do
        Script.Yield(50); waited = waited + 50
    end
    if not Natives.InvokeBool(N_HAS_MODEL_LOADED, hash) then
        Natives.InvokeVoid(N_MODEL_NO_LONGER, hash)
        return false, "carrier model load timeout"
    end
    local netUsed = louderRadio.netVehicleCount()
    local netMax = NETWORK.GET_MAX_NUM_NETWORK_VEHICLES() or 0
    if netMax > 0 and netUsed + chatCommands.SPAWN_NET_HEADROOM >= netMax then
        Natives.InvokeVoid(N_MODEL_NO_LONGER, hash)
        return false, "network vehicle pool is busy"
    end

    local src = ENTITY.GET_ENTITY_COORDS(ped, true)
    local veh, registered = 0, false
    Script.ExecuteAsScript("freemode", function()
        veh = Natives.InvokeInt(N_CREATE_VEHICLE, hash, src.x + 0.0, src.y + 0.0, src.z + 0.0, 0.0,
            true, false, false) or 0
        if veh == 0 then return end
        Natives.InvokeVoid(0xEA1C610A04DB6BBB, veh, false, false)
        if Natives.InvokeBool(N_REGISTER_NETWORKED, veh) then
            local id = Natives.InvokeInt(N_NET_ID_FROM_ENTITY, veh)
            if id and id ~= 0 then
                Natives.InvokeVoid(N_ID_CAN_MIGRATE, id, true)
                Natives.InvokeVoid(0xA8A024587329F36A, id, GTA.GetLocalPlayerId(), true)
                registered = true
            end
        end
        if not registered then
            if not chatCommands.delBuf then chatCommands.delBuf = Memory.AllocInt() end
            Memory.WriteInt(chatCommands.delBuf, veh)
            ENTITY.DELETE_ENTITY(chatCommands.delBuf)
        end
    end)
    Natives.InvokeVoid(N_MODEL_NO_LONGER, hash)
    if veh == 0 then return false, "carrier create returned 0" end
    if not registered then return false, "carrier was not networked" end
    local entry = {
        handle = veh, addr = UnloadReap.addrOf(veh), pop = UnloadReap.popOf(veh),
        kind = "vehicle", released = false,
    }

    local a = { src = src, netId = netId, x = x, y = y, z = z, writes = 0, base = nil }
    chatCommands.tpActive = a
    local handler = EventMgr.RegisterHandler(eLuaEvent.ON_SYNC_DATA_NODE, chatCommands.tpOnSyncNode)
    for _ = 1, 15 do
        Script.Yield(50)
        if scriptUnloading or not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid)
            or not ENTITY.DOES_ENTITY_EXIST(veh) or not NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(veh) then
            break
        end
        GTA.GiveControl(pid, veh)
    end
    EventMgr.RemoveHandler(handler)
    chatCommands.tpActive = nil

    Script.QueueJob(function()
        local started = Time.GetEpocheMs()
        while Time.GetEpocheMs() - started < 60000 do
            Script.Yield(Time.GetEpocheMs() - started < 5000 and 100 or 500)
            if scriptUnloading then break end
            if not ENTITY.DOES_ENTITY_EXIST(veh) or UnloadReap.addrOf(veh) ~= entry.addr then break end
            if NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(veh) then
                chatCommands.deleteVehicle(entry)
                if ENTITY.DOES_ENTITY_EXIST(veh) then
                    VIBE_LOG_ERROR(("[ChatCommands] teleport carrier %d refused delete"):format(veh))
                end
                break
            end
            NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(veh)
        end
    end)
    if a.writes == 0 then return false, "carrier migration node was never sent" end
    return true
end

function chatCommands.tpMoved(pid, x, y, ms)
    local deadline = Time.GetEpocheMs() + ms
    repeat
        local ped = Natives.InvokeInt(N_GET_PLAYER_PED, pid)
        if ped and ped ~= 0 and ENTITY.DOES_ENTITY_EXIST(ped) then
            local p = ENTITY.GET_ENTITY_COORDS(ped, true)
            if (p.x - x) ^ 2 + (p.y - y) ^ 2 < 900.0 then return true end
        end
        Script.Yield(100)
    until scriptUnloading or not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) or Time.GetEpocheMs() > deadline
    return false
end

function chatCommands.teleportPlayer(pid, x, y)
    local ped = Natives.InvokeInt(N_GET_PLAYER_PED, pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then return false, "player is out of scope" end
    if PLAYER.IS_REMOTE_PLAYER_IN_NON_CLONED_VEHICLE(pid) then return false, "their vehicle is out of range" end
    local z = chatCommands.tpGroundZ(x, y)
    local veh = chatCommands.currentVehicle(pid)
    local ok, why
    if veh then
        ok, why = chatCommands.tpVehicle(veh, x, y, z)
    else
        ok, why = chatCommands.tpCarrier(pid, ped, x, y, z)
    end
    local moved = ok and chatCommands.tpMoved(pid, x, y, 3000)
    if not ok then return false, why end
    if not moved then return false, "player did not move" end
    return true
end

chatCommands.def("teleport", "Teleport to waypoint", SAFE, { "teleport", "tp" }, "player",
    function(pid, _, ownerCommand, issuer)
        local me = GTA.GetLocalPlayerId()
        if pid == me or (ownerCommand and pid == issuer) then
            if not Natives.InvokeBool(0x1DD1F58F493F1DA5) then
                return false, "you don't have a waypoint"
            end
            chatCommands.queueBuiltin(Utils.Joaat("TeleportToWaypoint"), me, false, "Teleport To Waypoint")
            return true, "Teleported to your waypoint."
        end
        local has, pos = Players.GetWaypoint(pid)
        if not has then
            return false, pid == issuer and "you don't have a waypoint"
                or (chatCommands.nameOf(pid) .. " doesn't have a waypoint")
        end
        local now = Time.GetEpocheMs()
        if now < chatCommands.tpBusyUntil then return false, "another teleport is running" end
        chatCommands.tpBusyUntil = now + 25000
        local ok, why = chatCommands.teleportPlayer(pid, pos.x, pos.y)
        if not ok then
            VIBE_LOG_ERROR(("[ChatCommands] teleport for pid=%d failed (%s); trying Cherax Send To Waypoint"):format(pid, tostring(why)))
            chatCommands.queueBuiltin("Send To Waypoint", pid, true, "Send To Waypoint")
            ok = chatCommands.tpMoved(pid, pos.x, pos.y, 8000)
        end
        chatCommands.tpBusyUntil = 0
        if not ok then return false, "it didn't take, try again" end
        return true, pid == issuer and "Teleported to your waypoint."
            or ("Teleported " .. chatCommands.nameOf(pid) .. " to their waypoint.")
    end)
