chatCommands.RAMP_CAP = 3
chatCommands.RAMP_GAP = 4.0
chatCommands.ramps = {}
chatCommands.nextRampLeaveCheckMs = 0

function chatCommands.deleteRamp(entry)
    local h = entry.handle
    if not ENTITY.DOES_ENTITY_EXIST(h) or UnloadReap.addrOf(h) ~= entry.addr then return end
    if not chatCommands.delBuf then chatCommands.delBuf = Memory.AllocInt() end
    Script.ExecuteAsScript("freemode", function()
        if not NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(h) then
            NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(h)
        end
        Memory.WriteInt(chatCommands.delBuf, h)
        ENTITY.DELETE_ENTITY(chatCommands.delBuf)
    end)
    if ENTITY.DOES_ENTITY_EXIST(h) then
        VIBE_LOG_ERROR(("[ChatCommands] ramp 0x%08X handle=%d did not delete (control=%s)"):format(entry.hash & 0xFFFFFFFF, h, tostring(NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(h))))
    end
end

chatCommands.rampDip = {}
function chatCommands.findRampDip(obj, s, fwd, minX, maxX, midY, minZ, maxZ)
    if not chatCommands.rayBuf then chatCommands.rayBuf = Memory.Alloc(64) end
    local rb = chatCommands.rayBuf
    local o = ENTITY.GET_ENTITY_COORDS(obj, false)
    local pts = {}
    local lx = minX
    while lx <= maxX do
        local wx = o.x + s * lx * fwd.x - s * midY * fwd.y
        local wy = o.y + s * lx * fwd.y + s * midY * fwd.x
        local h = SHAPETEST.START_EXPENSIVE_SYNCHRONOUS_SHAPE_TEST_LOS_PROBE(
            wx, wy, o.z + maxZ + 2.0, wx, wy, o.z + minZ - 2.0, 16, 0, 7)
        SHAPETEST.GET_SHAPE_TEST_RESULT(h, rb, rb + 8, rb + 32, rb + 56)
        if Memory.ReadByte(rb) ~= 0 and Memory.ReadInt(rb + 56) == obj then
            pts[#pts + 1] = { lx = lx, z = Memory.ReadFloat(rb + 24) }
        end
        lx = lx + 1.0
    end
    if #pts < 10 then return nil, #pts end

    local n = #pts
    local leftMax, rightMax = {}, {}
    for i = 1, n do leftMax[i] = math.max(leftMax[i - 1] or -math.huge, pts[i].z) end
    for i = n, 1, -1 do rightMax[i] = math.max(rightMax[i + 1] or -math.huge, pts[i].z) end
    local best, bestDepth = nil, 0.5
    for i = 1, n do
        local depth = math.min(leftMax[i], rightMax[i]) - pts[i].z
        if depth > bestDepth then best, bestDepth = i, depth end
    end
    if not best then return nil, n end
    local a, b = best, best
    while a > 1 and math.abs(pts[a - 1].z - pts[best].z) < 0.1 do a = a - 1 end
    while b < n and math.abs(pts[b + 1].z - pts[best].z) < 0.1 do b = b + 1 end
    local dip = {
        lx = (pts[a].lx + pts[b].lx) * 0.5,
        lz = pts[best].z - o.z,
    }
    return dip, n
end

function chatCommands.reapRampsIfLeft(key)
    local list = chatCommands.ramps[key]
    if not list or key == GTA.GetLocalPlayerId() then return end
    local gone = not NETWORK.NETWORK_IS_PLAYER_CONNECTED(key)
    if not gone and list.rid then
        local rid = chatCommands.ridOf(key)
        gone = rid ~= nil and rid ~= list.rid
    end
    if not gone then return end
    chatCommands.ramps[key] = nil
    for _, entry in ipairs(list) do chatCommands.deleteRamp(entry) end
end

function chatCommands.reapLeftRamps()
    local keys = {}
    for key in pairs(chatCommands.ramps) do keys[#keys + 1] = key end
    for _, key in ipairs(keys) do chatCommands.reapRampsIfLeft(key) end
end

function chatCommands.spawnRamp(pid, modelName, zDrop, flip, dip, issuer, ownerCommand, count)
    count = count or 1
    local ped = Natives.InvokeInt(N_GET_PLAYER_PED, pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then return false, "player is out of scope" end
    local ent = chatCommands.currentVehicle(pid) or ped
    local hash = Utils.Joaat(modelName)

    Natives.InvokeVoid(N_REQUEST_MODEL, hash)
    local waited = 0
    while not Natives.InvokeBool(N_HAS_MODEL_LOADED, hash) and waited < 5000 do
        Script.Yield(50); waited = waited + 50
        if scriptUnloading then
            Natives.InvokeVoid(N_MODEL_NO_LONGER, hash)
            return false, "unloading"
        end
    end
    if not Natives.InvokeBool(N_HAS_MODEL_LOADED, hash) then
        Natives.InvokeVoid(N_MODEL_NO_LONGER, hash)
        return false, "model load timeout"
    end

    if not chatCommands.dimBuf then chatCommands.dimBuf = Memory.Alloc(48) end
    local buf = chatCommands.dimBuf
    MISC.GET_MODEL_DIMENSIONS(ENTITY.GET_ENTITY_MODEL(ent), buf, buf + 24)
    local entFront = Memory.ReadFloat(buf + 32)
    local entBottom = Memory.ReadFloat(buf + 16)
    MISC.GET_MODEL_DIMENSIONS(hash, buf, buf + 24)
    local s = flip and -1.0 or 1.0
    local minX, maxX = Memory.ReadFloat(buf), Memory.ReadFloat(buf + 24)
    local minZ, maxZ = Memory.ReadFloat(buf + 16), Memory.ReadFloat(buf + 40)
    local nearX = flip and maxX or minX
    local minY, maxY = Memory.ReadFloat(buf + 8), Memory.ReadFloat(buf + 32)
    local midY = (minY + maxY) * 0.5
    local width = maxY - minY

    local pos = ENTITY.GET_ENTITY_COORDS(ent, true)
    local fwd = ENTITY.GET_ENTITY_FORWARD_VECTOR(ent)
    local heading = ((ENTITY.GET_ENTITY_HEADING(ent) or 0.0) + (flip and 270.0 or 90.0)) % 360.0
    local anchorX, ax, ay = nearX, pos.x, pos.y
    if dip then
        local known = chatCommands.rampDip[hash]
        anchorX = known and known.lx or (minX + maxX) * 0.5
    else
        ax = pos.x + fwd.x * (entFront + chatCommands.RAMP_GAP)
        ay = pos.y + fwd.y * (entFront + chatCommands.RAMP_GAP)
    end
    local x = ax - s * anchorX * fwd.x + s * midY * fwd.y
    local y = ay - s * anchorX * fwd.y - s * midY * fwd.x
    local z = pos.z + entBottom
    if Natives.InvokeBool(0xC906A7DAB05C8D2B, ax, ay, pos.z + 3.0, buf, false, false) then
        local gz = Memory.ReadFloat(buf)
        if math.abs(gz - z) < 5.0 then z = gz end
    end
    local groundZ = z
    z = z - (zDrop or 0.0)

    local key = ownerCommand and GTA.GetLocalPlayerId() or issuer or pid
    chatCommands.reapRampsIfLeft(key)
    local mine = chatCommands.ramps[key]
    if not mine then
        mine = { rid = chatCommands.ridOf(key) }
        chatCommands.ramps[key] = mine
    end
    while not ownerCommand and #mine + count > chatCommands.RAMP_CAP do
        chatCommands.deleteRamp(table.remove(mine, 1))
    end

    local baseX, baseY, created = x, y, 0
    for slot = 1, count do
        local lateral = (slot - (count + 1) * 0.5) * width * 0.97
        x = baseX - fwd.y * lateral
        y = baseY + fwd.x * lateral
        local obj, networked, netId = 0, false, 0
        Script.ExecuteAsScript("freemode", function()
            obj = Natives.InvokeInt(0x509D5878EB39E842, hash, x + 0.0, y + 0.0, z + 0.0,
                true, false, false) or 0
            if obj == 0 then return end
            Natives.InvokeVoid(N_SET_ENTITY_HEADING, obj, heading + 0.0)
            Natives.InvokeVoid(0x428CA6DBD1094446, obj, true)
            networked = Natives.InvokeBool(N_REGISTER_NETWORKED, obj)
            if networked then
                netId = Natives.InvokeInt(N_NET_ID_FROM_ENTITY, obj) or 0
                if netId ~= 0 then
                    Natives.InvokeVoid(N_ID_EXISTS_ALL, netId, true)
                    Natives.InvokeVoid(N_ID_CAN_MIGRATE, netId, false)
                end
            end
        end)
        if obj == 0 then
            VIBE_LOG_ERROR(("[ChatCommands] CREATE_OBJECT returned 0 for %s"):format(modelName))
            break
        end
        created = created + 1
        mine[#mine + 1] = {
            handle = obj, addr = UnloadReap.addrOf(obj), pop = UnloadReap.popOf(obj),
            kind = "object", hash = hash,
        }

        if dip then
            local d = chatCommands.rampDip[hash]
            if not d then
                local hits
                d, hits = chatCommands.findRampDip(obj, s, fwd, minX, maxX, midY, minZ, maxZ)
                if not d then
                    Script.Yield(0)
                    d, hits = chatCommands.findRampDip(obj, s, fwd, minX, maxX, midY, minZ, maxZ)
                end
                if d then
                    chatCommands.rampDip[hash] = d
                else
                    VIBE_LOG_ERROR(("[ChatCommands] ramp dip for %s not found (%d probe hits); left centred"):format(modelName, hits or 0))
                end
            end
            if d then
                x = pos.x - s * d.lx * fwd.x + s * midY * fwd.y
                y = pos.y - s * d.lx * fwd.y - s * midY * fwd.x
                z = groundZ - d.lz
                anchorX = d.lx
                Script.ExecuteAsScript("freemode", function()
                    Natives.InvokeVoid(0x239A3351AC1DA385, obj, x + 0.0, y + 0.0, z + 0.0,
                        false, false, false)
                end)
            end
        end
    end
    Natives.InvokeVoid(N_MODEL_NO_LONGER, hash)
    if created ~= count then
        return false, created == 0 and "create returned 0" or "only one ramp could be created"
    end
    return true
end

