function chatCommands.sortOrderByTier()
    table.sort(chatCommands.order, function(a, b)
        local da, db = chatCommands.commands[a], chatCommands.commands[b]
        if a == "help" or b == "help" then return a ~= "help" and b == "help" end
        local la, lb = LV[da.tier] or 1, LV[db.tier] or 1
        if la ~= lb then return la < lb end
        return (da.seq or 0) < (db.seq or 0)
    end)
end

local function hexEncode(s)
    return (tostring(s or ""):gsub(".", function(c) return ("%02X"):format(c:byte()) end))
end

local function hexDecode(s)
    if type(s) ~= "string" or #s % 2 ~= 0 or s:find("[^%x]") then return nil end
    return (s:gsub("%x%x", function(pair) return string.char(tonumber(pair, 16)) end))
end

local function resolveRegisteredButton(hash, pid, playerFeature, expectedName)
    local feature
    if playerFeature then
        feature = FeatureMgr.GetFeatureByName(expectedName, pid)
        if not feature then feature = FeatureMgr.GetFeature(hash, pid) end
    else
        feature = FeatureMgr.GetFeature(hash)
    end
    if not feature then return nil end
    local featureType = feature:GetType()
    if not isButtonFeatureType(featureType) then return nil end
    if getFeatureName(feature) ~= expectedName then return nil end
    return feature
end

chatCommands.customNext = 1

function chatCommands.toastUnavailable(name, featureHash)
    local now = Time.GetEpocheMs()
    local token = tostring(featureHash) .. ":" .. tostring(name)
    if now < (chatCommands.unavailableToastAt[token] or 0) then return end
    chatCommands.unavailableToastAt[token] = now + 3000
    GUI.AddToast("VibeScript",
        T("%s is disabled because its providing script is not loaded."):format(name), 4000)
end

function chatCommands.registerCustom(key, name, tier, aliases, featureHash, playerFeature, enabled)
    if not key then
        repeat
            key = "custom_" .. tostring(chatCommands.customNext)
            chatCommands.customNext = chatCommands.customNext + 1
        until not chatCommands.commands[key]
    else
        local n = tonumber(key:match("^custom_(%d+)$"))
        if n then chatCommands.customNext = math.max(chatCommands.customNext, n + 1) end
    end

    local d
    d = chatCommands.def(key, name, tier, aliases,
        playerFeature and "player" or nil,
        function(pid)
            local feature = resolveRegisteredButton(featureHash, pid, playerFeature, name)
            if not feature then
                d.available = false
                chatCommands.toastUnavailable(name, featureHash)
                chatCommands.requestFeatureRefresh()
                return false, "feature is disabled because its providing script is not loaded"
            end
            d.available = true
            feature:OnClick()
            return true, "Ran " .. name .. "."
        end)
    d.custom = true
    d.featureHash = featureHash
    d.playerFeature = playerFeature == true
    d.on = enabled ~= false
    d.available = nil
    chatCommands.sortOrderByTier()
    return d
end

function chatCommands.removeCustom(key)
    local d = chatCommands.commands[key]
    if not d or not d.custom then return end
    chatCommands.commands[key] = nil
    for i = #chatCommands.order, 1, -1 do
        if chatCommands.order[i] == key then table.remove(chatCommands.order, i) end
    end
    for _, person in pairs(chatCommands.people) do
        if person.grants then person.grants[key] = nil end
    end
    if chatCommands.selCmd == key then chatCommands.selCmd = nil end
    chatCommands.rebuildAliases()
    if chatCommands.savePersistent then chatCommands.savePersistent() end
end

function chatCommands.refreshFeatureChoices()
    local choices, seen, errors = {}, {}, {}
    local stats = { candidates = 0, resolved = 0, badType = 0, badName = 0 }
    local me = GTA.GetLocalPlayerId()

    local function add(feature, forcePlayer, knownHash)
        if not feature then return end
        stats.resolved = stats.resolved + 1
        local visible = feature:IsVisible()
        if not visible then return end
        local featureType = feature:GetType()
        if not isButtonFeatureType(featureType) then
            stats.badType = stats.badType + 1
            return
        end
        local name = getFeatureName(feature)
        local hash = knownHash
        if hash == nil then hash = feature:GetHash() end
        if type(name) ~= "string" or name == "" then
            stats.badName = stats.badName + 1
            return
        end
        local playerFeature = forcePlayer == true
        if not forcePlayer then
            playerFeature = feature:IsPlayerFeature() == true
        end
        local actualHash = feature:GetHash()
        local ownedByVibe = isVibeFeatureHash(hash)
            or isVibeFeatureHash(actualHash)
            or (playerFeature and VIBE_GATE.playerNames[name:lower()] == true)
        local isVibe = ownedByVibe
        if playerFeature then
            local index = feature:GetPlayerIndex()
            if type(index) == "number" and index >= 0 and index ~= me then return end
        else
            isVibe         = ownedByVibe and VIBE_SESSION_BUTTONS[name:lower()] == true
            local isCherax = CHERAX_SESSION_BUTTONS[name:lower()] == true
            if not (isVibe or isCherax) then
                stats.filtered = (stats.filtered or 0) + 1
                return
            end
        end
        local normalizedName = name:lower():gsub("%s+", " ")
        local provider = isVibe and "vibe:" or "external:"
        local id = playerFeature and ("p:" .. provider .. normalizedName)
            or ("g:" .. tostring(hash))
        local prior = seen[id]
        if prior then return end
        seen[id] = #choices + 1
        choices[#choices + 1] = {
            id = id,
            name = name,
            hash = hash,
            playerFeature = playerFeature,
            isVibe = isVibe,
            label = (feature:GetName(true) or name) .. (isVibe and "  [VibeScript]" or "")
                .. "  " .. T(playerFeature and "[Per-Player]" or "[Global]"),
        }
    end

    local function resolveAndAdd(hash, playerFeature)
        stats.candidates = stats.candidates + 1
        if type(hash) == "string" then hash = tonumber(hash) end
        if type(hash) ~= "number" then return end
        local feature
        if playerFeature then
            feature = FeatureMgr.GetFeature(hash)
            local index = feature and feature:GetPlayerIndex() or nil
            if not feature
                or (type(index) == "number" and index >= 0 and index ~= me) then
                feature = FeatureMgr.GetFeature(hash, me)
            end
        else
            feature = FeatureMgr.GetFeature(hash)
        end
        add(feature, playerFeature, hash)
    end

    local function eachHash(values, playerFeature)
        for key, value in pairs(values) do
            if type(value) == "number" or type(value) == "string" then
                resolveAndAdd(value, playerFeature)
            elseif type(key) == "number" and type(value) == "boolean" then
                resolveAndAdd(key, playerFeature)
            end
        end
    end

    local function walk(label, values, visitor)
        if values == nil then
            errors[#errors + 1] = label .. ": returned nil"
            return
        end
        visitor(values)
    end

    local globalHashes = FeatureMgr.GetAllFeatureHashes()
    walk("global hashes", globalHashes, function(values) eachHash(values, false) end)

    local globals = FeatureMgr.GetAllFeatures()
    walk("global features", globals, function(values)
        for _, value in pairs(values) do
            if type(value) == "number" or type(value) == "string" then
                resolveAndAdd(value, false)
            else add(value, false) end
        end
    end)

    local playerHashes = FeatureMgr.GetAllPlayerFeatureHashes(me)
    walk("player hashes", playerHashes, function(values) eachHash(values, true) end)

    local basePlayerHashes = FeatureMgr.GetAllPlayerFeatureHashes()
    walk("base player hashes", basePlayerHashes, function(values) eachHash(values, true) end)

    if #choices == 0 and #errors == 0 then
        errors[1] = ("Cherax returned no button features (candidates=%d, resolved=%d, " ..
            "rejected-type=%d, rejected-name=%d)"):format(
                stats.candidates, stats.resolved, stats.badType, stats.badName)
    end
    table.sort(choices, function(a, b)
        local an, bn = a.name:lower(), b.name:lower()
        if an ~= bn then return an < bn end
        return a.label < b.label
    end)
    local signatureParts = {}
    for i, entry in ipairs(choices) do signatureParts[i] = entry.id end
    local status = #errors > 0
        and T("Feature scan failed: %s"):format(table.concat(errors, " | ")) or nil
    local logSignature = table.concat(signatureParts, "\n") .. "\0" .. tostring(status)
    if chatCommands.featureScanLogSignature ~= logSignature then
        if status then
            VIBE_LOG_ERROR(("[ChatCommands] feature scan: %s"):format(table.concat(errors, " | ")))
        end
        chatCommands.featureScanLogSignature = logSignature
    end
    if #choices > 0 or not chatCommands.featureChoices then
        chatCommands.featureChoices = choices
    end
    chatCommands.featureScanStatus = status

    for _, key in ipairs(chatCommands.order) do
        local d = chatCommands.commands[key]
        if d and d.custom then
            d.available = resolveRegisteredButton(
                d.featureHash, me, d.playerFeature, d.name) ~= nil
        end
    end
end

function chatCommands.requestFeatureRefresh()
    if chatCommands.featureScanPending then return end
    chatCommands.featureScanPending = true
    if not chatCommands.featureChoices then
        chatCommands.featureScanStatus = T("Scanning button features...")
    end
    Script.QueueJob(function()
        chatCommands.refreshFeatureChoices()
        chatCommands.featureScanPending = false
    end)
end

function chatCommands.parseCustomAliases(text)
    local aliases, localSeen = {}, {}
    for raw in tostring(text or ""):gmatch("[^,%s]+") do
        local alias = raw:lower()
        if alias:sub(1, #chatCommands.prefix) == chatCommands.prefix then
            alias = alias:sub(#chatCommands.prefix + 1)
        end
        if alias ~= "" and #alias <= 32 and alias:match("^[%w_%-]+$")
            and not localSeen[alias] and not chatCommands.aliasMap[alias] then
            localSeen[alias] = true
            aliases[#aliases + 1] = alias
        end
    end
    return aliases
end

function chatCommands.rebuildAliases()
    local m = {}
    for _, key in ipairs(chatCommands.order) do
        local d = chatCommands.commands[key]
        for _, a in ipairs(d.aliases) do
            local la = a:lower()
            if la ~= "" then m[la] = key end
        end
    end
    chatCommands.aliasMap = m
end

for _, aud in ipairs(chatCommands.AUD_ORDER) do
    if aud == "everyone" then chatCommands.audiences[aud] = 1
    else                      chatCommands.audiences[aud] = 0
    end
end
chatCommands.rebuildAliases()

chatCommands.ridOf = VIBE_GATE.playerProtection.rid

function chatCommands.isOwner(pid, rid)
    local localPid = GTA.GetLocalPlayerId()
    if pid == localPid then return true end
    local senderRid = rid or chatCommands.ridOf(pid)
    local ownerRid = chatCommands.ridOf(localPid)
    return senderRid ~= nil and ownerRid ~= nil and senderRid == ownerRid
end

function chatCommands.nameOf(pid)
    local n = Natives.InvokeString(N_GET_PLAYER_NAME, pid)
    if type(n) == "string" and n ~= "" then return n end
    return "Player" .. tostring(pid)
end

function chatCommands.effectiveLevel(pid, rid, team)
    if chatCommands.isOwner(pid, rid) then
        return 3
    end
    local level = chatCommands.audiences.everyone or 0
    local function raise(aud)
        local a = chatCommands.audiences[aud] or 0
        if a > level then level = a end
    end
    if team then raise("team") end
    if isPlayerFriend(pid) then raise("friends") end
    if chatCommands.sameCrew(pid) then raise("crew") end
    local myBoss = getOrgBoss(GTA.GetLocalPlayerId())
    if myBoss >= 0 and myBoss <= 31 and getOrgBoss(pid) == myBoss then raise("org") end
    if rid and chatCommands.people[rid] and chatCommands.people[rid].mode == "trust" then
        if (chatCommands.trusted or 0) > level then level = chatCommands.trusted end
    end
    return level
end

function chatCommands.sameCrew(pid)
    local me = GTA.GetLocalPlayerId()
    if pid == me then return false end
    local a = chatCommands.clanId(me)
    local b = chatCommands.clanId(pid)
    return a ~= nil and a ~= 0 and a == b
end

function chatCommands.clanId(pid)
    if not chatCommands.handleBuf then chatCommands.handleBuf = Memory.Alloc(104) end
    if not chatCommands.clanBuf   then chatCommands.clanBuf   = Memory.Alloc(480) end
    Natives.InvokeVoid(N_HANDLE_FROM_PLAYER, pid, chatCommands.handleBuf, 13)
    if not Natives.InvokeBool(0xB124B57F571D8F18, chatCommands.handleBuf) then return nil end
    if not Natives.InvokeBool(0xEEE6EACBE8874FBA, chatCommands.clanBuf, 458, chatCommands.handleBuf) then return nil end
    return Memory.ReadLong(chatCommands.clanBuf)
end

chatCommands.engineChat = {
    AOB_CXN   = "39 3D ?? ?? ?? ?? 0F 85 ?? ?? ?? ?? 48 89", CXN_RIP = 2,
    AOB_WBQ   = "48 89 5C 24 08 48 89 6C 24 10 48 89 74 24 18 57 48 83 EC 20 41 8B F0 48 8B EA 48 8B D9 41 83 F8 20",
    AOB_WBI64 = "E8 ?? ?? ?? ?? 8A 53 39 48 8B CF", WBI64_RIP = 1,
    AOB_WBA   = "E8 ?? ?? ?? ?? 01 7E 08", WBA_RIP = 1,
    AOB_QP    = "E8 ?? ?? ?? ?? 84 C0 74 4D B3 01", QP_RIP = 1,
    AOB_CHAT_DATA = "48 8B 05 ?? ?? ?? ?? 0F 45 DF", CHAT_DATA_RIP = 3,
    AOB_BEGIN_SCALEFORM = "48 83 EC 38 4C 8B C2 8B 51 04",
    AOB_GAME_LIFETIME = "8B 05 ?? ?? ?? ?? 89 ?? 48 8D 4D C8", GAME_LIFETIME_RIP = 2,
    MSG_ID_OFF = 0x58,
    MSGTYPE    = 0x24,
    QP_FLAGS   = 1,
    BUF_BYTES  = 0x600,
    tried = false, ok = false,
    cxnGlobal = nil, wbq = nil, wbi64 = nil, wba = nil, qp = nil,
    chatDataGlobal = nil, beginScaleform = nil, gameLifetime = nil,
    bufData = nil, bitbuf = nil, strBuf = nil, guidBuf = nil,
    addMethod = nil, focusMethod = nil,
}

chatCommands.displayFilter = {
    state = 0, hook = 0, cave = 0, origHook = nil, origCave = nil, active = false,
    status = "not installed",
}

local function cdfWrite(addr, bytes)
    for i, b in ipairs(bytes) do Memory.WriteByte(addr + i - 1, b) end
end

local function cdfPatchSite(addr, bytes)
    for i = 2, #bytes do Memory.WriteByte(addr + i - 1, bytes[i]) end
    Memory.WriteByte(addr, bytes[1])
end

local function cdfWaitIdle(addr)
    local quietSince = nil
    local deadline = os.clock() + 0.100
    while os.clock() < deadline do
        if (Memory.ReadUInt(addr) or 0) == 0 then
            quietSince = quietSince or os.clock()
            if os.clock() - quietSince >= 0.010 then return true end
        else
            quietSince = nil
        end
    end
    return false
end

local function cdfRead(addr, n)
    local out = {}
    for i = 0, n - 1 do out[#out + 1] = Memory.ReadUByte(addr + i) or 0 end
    return out
end

local function cdfU32(v)
    v = v & 0xFFFFFFFF
    return { v & 0xFF, (v >> 8) & 0xFF, (v >> 16) & 0xFF, (v >> 24) & 0xFF }
end

local function cdfU64(v)
    local out = {}
    for i = 0, 7 do out[#out + 1] = (v >> (i * 8)) & 0xFF end
    return out
end

local function cdfAppend(dst, src)
    for _, b in ipairs(src) do dst[#dst + 1] = b end
end

local function cdfRel32(from, to) return (to - (from + 4)) & 0xFFFFFFFF end

function VIBE_GATE.findExecutablePadding(need, ranges)
    if type(need) ~= "number" or need < 1 or type(ranges) ~= "table" then return nil end
    local pat = "CC"
    for _ = 1, 64 do pat = pat .. " 00" end
    local hit = Memory.Scan(pat)
    if not hit or hit == 0 then return nil end
    local cave = hit + 1
    local inExecutableBody = false
    for _, r in ipairs(ranges) do
        if r.bodyFrom and r.bodyTo
                and cave >= r.bodyFrom and cave + need <= r.bodyTo then
            inExecutableBody = true
            break
        end
    end
    if not inExecutableBody then return nil end
    for o = 0, need - 1 do
        if (Memory.ReadUByte(cave + o) or 1) ~= 0 then return nil end
    end
    return cave
end

local function cdfFindCave(need)
    local base = Memory.GetBaseAddress("GTA5.exe")
    if not base or base == 0 then base = Memory.GetBaseAddress() end
    if not base or base == 0 then return nil, "game module base not found" end
    local pe = base + (Memory.ReadUInt(base + 0x3C) or 0)
    if Memory.ReadUInt(pe) ~= 0x4550 then return nil, "PE header not readable" end
    local nSec = Memory.ReadUShort(pe + 6)
    local secTab = pe + 24 + Memory.ReadUShort(pe + 20)
    local ranges = {}
    for i = 0, nSec - 1 do
        local s = secTab + i * 40
        if (Memory.ReadUInt(s + 36) & 0x20000000) ~= 0 then
            local vsize, vaddr = Memory.ReadUInt(s + 8), Memory.ReadUInt(s + 12)
            local r = {
                bodyFrom = base + vaddr,
                bodyTo = base + vaddr + vsize,
                from = base + vaddr + vsize,
                to = base + vaddr + math.floor((vsize + 0xFFF) / 0x1000) * 0x1000,
            }
            ranges[#ranges + 1] = r
            local run, start = 0, nil
            for a = r.from, r.to - 1 do
                if (Memory.ReadUByte(a) or 1) == 0 then
                    if run == 0 then start = a end
                    run = run + 1
                    if run >= need then return start end
                else
                    run, start = 0, nil
                end
            end
        end
    end
    local pad = VIBE_GATE.findExecutablePadding(need, ranges)
    if pad then return pad end
    return nil, ("no executable code cave (%d bytes needed)"):format(need)
end

function chatCommands.displayFilter.install()
    local df = chatCommands.displayFilter
    if df.active then return true end
    if IS_ENHANCED then return false, "Enhanced has no text chat" end

    local hit = Memory.Scan(chatCommands.engineChat.AOB_BEGIN_SCALEFORM)
    if not hit or hit == 0 then
        df.status = "current Scaleform entry signature not found"
        VIBE_LOG_ERROR(("[ChatCommands] hide messages unavailable: %s"):format(df.status))
        return false, df.status
    end

    local hook = hit
    local expected = { 0x48, 0x83, 0xEC, 0x38, 0x4C, 0x8B, 0xC2 }
    local original = cdfRead(hook, #expected)
    for i = 1, #expected do
        if original[i] ~= expected[i] then
            df.status = "current Scaleform entry bytes changed"
            VIBE_LOG_ERROR(("[ChatCommands] hide messages unavailable: %s"):format(df.status))
            return false, df.status
        end
    end

    local state = Memory.Alloc(16)
    if not state or state == 0 then return false, "state allocation failed" end
    Memory.MemSet(state, 0, 16)
    local cave, err = cdfFindCave(96)
    if not cave then Memory.Free(state); return false, err end

    local sc = {}
    local allowJumps = {}
    local function jumpAllow(opcode)
        cdfAppend(sc, { opcode, 0 })
        allowJumps[#allowJumps + 1] = #sc
    end
    cdfAppend(sc, { 0x48, 0xB8 }); cdfAppend(sc, cdfU64(state))
    cdfAppend(sc, { 0xF0, 0xFF, 0x40, 0x04 })
    cdfAppend(sc, { 0x80, 0x38, 0x00 }); jumpAllow(0x74)
    cdfAppend(sc, { 0x80, 0x78, 0x01, 0x00 }); jumpAllow(0x74)
    cdfAppend(sc, { 0x48, 0x85, 0xD2 }); jumpAllow(0x74)
    cdfAppend(sc, { 0x81, 0x3A, 0x41, 0x44, 0x44, 0x5F }); jumpAllow(0x75)
    cdfAppend(sc, { 0x81, 0x7A, 0x04, 0x4D, 0x45, 0x53, 0x53 }); jumpAllow(0x75)
    cdfAppend(sc, { 0x81, 0x7A, 0x08, 0x41, 0x47, 0x45, 0x00 }); jumpAllow(0x75)
    cdfAppend(sc, { 0xC6, 0x40, 0x01, 0x00 })
    cdfAppend(sc, { 0xF0, 0xFF, 0x48, 0x04 })
    cdfAppend(sc, { 0x33, 0xC0, 0xC3 })
    local allowOffset = #sc
    for _, index in ipairs(allowJumps) do
        sc[index] = (allowOffset - index) & 0xFF
    end
    cdfAppend(sc, { 0xF0, 0xFF, 0x48, 0x04 })
    cdfAppend(sc, original)
    local jumpFrom = cave + #sc
    cdfAppend(sc, { 0xE9 }); cdfAppend(sc, cdfU32(cdfRel32(jumpFrom + 1, hook + #original)))

    local origCave = cdfRead(cave, #sc)
    cdfWrite(cave, sc)
    local patch = { 0xE9 }
    cdfAppend(patch, cdfU32(cdfRel32(hook + 1, cave)))
    patch[#patch + 1], patch[#patch + 1] = 0x90, 0x90
    cdfPatchSite(hook, patch)

    df.state, df.hook, df.cave = state, hook, cave
    df.origHook, df.origCave = original, origCave
    df.active, df.status = true, "installed"
    return true
end

function chatCommands.displayFilter.sync()
    local df = chatCommands.displayFilter
    if chatCommands.hideMessages and not df.active then
        local ok, err = df.install()
        if not ok then return false, err end
    end
    local on = chatCommands.hideMessages or (chatTranslate and chatTranslate.incoming) or false
    if df.active and df.state ~= 0 then
        Memory.WriteByte(df.state, on and 1 or 0)
        if not on then Memory.WriteByte(df.state + 1, 0) end
    end
    return true
end

function chatCommands.displayFilter.markPending()
    local df = chatCommands.displayFilter
    if chatCommands.hideMessages and df.active and df.state ~= 0 then
        Memory.WriteByte(df.state + 1, 1)
    end
end

function chatCommands.displayFilter.uninstall()
    local df = chatCommands.displayFilter
    if not df.active then return end
    if df.hook ~= 0 and df.origHook then cdfPatchSite(df.hook, df.origHook) end
    local drained = df.state == 0 or cdfWaitIdle(df.state + 4)
    if drained then
        if df.cave ~= 0 and df.origCave then cdfWrite(df.cave, df.origCave) end
        if df.state ~= 0 then Memory.Free(df.state) end
    else
        if df.state ~= 0 then VIBE_GATE.retainAllocation(df.state) end
        VIBE_LOG_ERROR("[ChatCommands] hide messages cave drain timed out; retained for safety")
    end
    df.state, df.hook, df.cave, df.origHook, df.origCave = 0, 0, 0, nil, nil
    df.active, df.status = false, "uninstalled"
end

local function ecPlausible(p)
    return type(p) == "number" and p > 0x10000 and p < 0x7FFFFFFFFFFF
end

function chatCommands.engineChat.localRid()
    local gi = Players.GetById(GTA.GetLocalPlayerId())
    gi = gi and gi:GetGamerInfo()
    local rid = gi and math.tointeger(gi.RockstarId or 0) or nil
    if rid and rid > 0 then return rid end
    return nil
end

function chatCommands.engineChat.resolve()
    local ec = chatCommands.engineChat
    if ec.tried then return ec.ok end
    ec.tried = true
    if IS_ENHANCED then
        return false
    end
    local function scanRip(aob, ripOff)
        local m = Memory.Scan(aob)
        if not ecPlausible(m) then return nil end
        if ripOff == nil then return m end
        return Memory.Rip(m + ripOff)
    end
    local cxnM = Memory.Scan(ec.AOB_CXN)
    ec.cxnGlobal = ecPlausible(cxnM) and Memory.Rip(cxnM + ec.CXN_RIP) or nil
    ec.wbq   = scanRip(ec.AOB_WBQ, nil)
    ec.wbi64 = scanRip(ec.AOB_WBI64, ec.WBI64_RIP)
    ec.wba   = scanRip(ec.AOB_WBA, ec.WBA_RIP)
    ec.qp    = scanRip(ec.AOB_QP, ec.QP_RIP)
    local chatDataM = Memory.Scan(ec.AOB_CHAT_DATA)
    ec.chatDataGlobal = ecPlausible(chatDataM) and Memory.Rip(chatDataM + ec.CHAT_DATA_RIP) or nil
    local df = chatCommands.displayFilter
    ec.beginScaleform = scanRip(ec.AOB_BEGIN_SCALEFORM, nil)
        or (df.active and ecPlausible(df.hook) and df.hook or nil)
    local lifetimeM = Memory.Scan(ec.AOB_GAME_LIFETIME)
    ec.gameLifetime = ecPlausible(lifetimeM)
        and Memory.Rip(lifetimeM + ec.GAME_LIFETIME_RIP) or nil
    for _, v in ipairs({ { "connMgr", ec.cxnGlobal }, { "WBQ", ec.wbq },
        { "WBI64", ec.wbi64 }, { "WBA", ec.wba }, { "QP", ec.qp } }) do
        if not ecPlausible(v[2]) then
            VIBE_LOG_ERROR(("[ChatCommands] chat send: %s signature not found; disabled"):format(v[1]))
            return false
        end
    end
    ec.bufData = Memory.Alloc(ec.BUF_BYTES)
    ec.bitbuf  = Memory.Alloc(0x20)
    ec.strBuf  = Memory.Alloc(300)
    ec.guidBuf = Memory.Alloc(64)
    ec.addMethod = Memory.Alloc(32)
    ec.focusMethod = Memory.Alloc(32)
    if ecPlausible(ec.addMethod) then Memory.WriteString(ec.addMethod, "ADD_MESSAGE") end
    if ecPlausible(ec.focusMethod) then Memory.WriteString(ec.focusMethod, "SET_FOCUS") end
    for _, b in ipairs({ ec.bufData, ec.bitbuf, ec.strBuf, ec.guidBuf }) do
        if not ecPlausible(b) then
            VIBE_LOG_ERROR("[ChatCommands] chat send: buffer alloc failed; disabled")
            return false
        end
    end
    ec.ok = true
    return true
end

local function ecUtf8Prefix(text, maxBytes)
    text = tostring(text or "")
    if #text <= maxBytes then return text end
    local n = maxBytes
    while n > 0 do
        local candidate = text:sub(1, n)
        if utf8.len(candidate) then return candidate end
        n = n - 1
    end
    return ""
end

chatCommands.engineChat.utf8Prefix = ecUtf8Prefix

function chatCommands.engineChat.localEcho(text, team)
    local ec = chatCommands.engineChat
    if not ec.ok or not ecPlausible(ec.chatDataGlobal)
        or not ecPlausible(ec.beginScaleform) or not ecPlausible(ec.gameLifetime)
        or not ecPlausible(ec.addMethod) or not ecPlausible(ec.focusMethod) then
        VIBE_LOG_ERROR(("[ChatCommands] local echo unavailable: ok=%s chatData=%s begin=%s lifetime=%s"):format(tostring(ec.ok), tostring(ec.chatDataGlobal), tostring(ec.beginScaleform),
            tostring(ec.gameLifetime)))
        return false
    end
    local chat = Memory.ReadLong(ec.chatDataGlobal)
    if not ecPlausible(chat) then return false end

    local result = Memory.LuaCallCFunctionWithReturnValue(
        ec.beginScaleform, chat + 0x20, ec.addMethod)
    if not ecPlausible(result) then return false end
    local began = (Memory.ReadByte(result) or 0) ~= 0
    Memory.Free(result)
    if not began then return false end

    local name = Players.GetName(GTA.GetLocalPlayerId()) or "You"
    local scopeKey = team and "MP_CHAT_TEAM" or "MP_CHAT_ALL"
    local scope = Natives.InvokeString(0x7B5280EBA9840C72, scopeKey) or scopeKey
    Natives.InvokeVoid(0xE83A3E3557A56640, name)
    Natives.InvokeVoid(0x77FE3402004CD1B0, ecUtf8Prefix(text, 140))
    Natives.InvokeVoid(0xBA7148484BD90365, scope)
    Natives.InvokeVoid(0xC58424BA936EB458, team == true)
    Natives.InvokeVoid(0xC3D0841A0CC546A6, 0)
    Natives.InvokeVoid(0xC6796A8FFA375E53)

    if (Memory.ReadByte(chat + 0x14) or 0) == 0
        and (Memory.ReadInt(chat + 0x04) or 0) == 0 then
        result = Memory.LuaCallCFunctionWithReturnValue(
            ec.beginScaleform, chat + 0x20, ec.focusMethod)
        if ecPlausible(result) then
            began = (Memory.ReadByte(result) or 0) ~= 0
            Memory.Free(result)
            if began then
                Natives.InvokeVoid(0xC3D0841A0CC546A6, 1)
                Natives.InvokeVoid(0xC3D0841A0CC546A6, 0)
                Natives.InvokeVoid(0xC3D0841A0CC546A6, 0)
                Natives.InvokeVoid(0xE83A3E3557A56640, name)
                Natives.InvokeVoid(0xC3D0841A0CC546A6, 0)
                Natives.InvokeVoid(0xC6796A8FFA375E53)
            end
        end
    end
    Memory.WriteInt(chat, Memory.ReadInt(ec.gameLifetime) or 0)
    return true
end

function chatCommands.engineChat.wUint(val, bits)
    Memory.LuaCallCFunction(chatCommands.engineChat.wbq, chatCommands.engineChat.bitbuf, val, bits)
end
function chatCommands.engineChat.wInt64(val, bits)
    Memory.LuaCallCFunction(chatCommands.engineChat.wbi64, chatCommands.engineChat.bitbuf, val, bits)
end
function chatCommands.engineChat.wArray(ptr, bits)
    Memory.LuaCallCFunction(chatCommands.engineChat.wba, chatCommands.engineChat.bitbuf, ptr, bits, 0)
end

function chatCommands.engineChat.resetBuffer()
    local ec = chatCommands.engineChat
    Memory.WriteLong(ec.bitbuf + 0x00, ec.bufData)
    Memory.WriteInt(ec.bitbuf + 0x08, 0)
    Memory.WriteInt(ec.bitbuf + 0x0C, ec.BUF_BYTES * 8)
    Memory.WriteInt(ec.bitbuf + 0x10, 0)
    Memory.WriteInt(ec.bitbuf + 0x14, 0)
    Memory.WriteInt(ec.bitbuf + 0x18, 0)
    Memory.WriteByte(ec.bitbuf + 0x1C, 0)
end

function chatCommands.engineChat.wString(buf, str, maxChars)
    local ec = chatCommands.engineChat
    for i = 0, #str do Memory.WriteByte(buf + i, 0) end
    Memory.WriteString(buf, str)
    local numChars = math.min(maxChars, #str + 1)
    local big = numChars > 127
    ec.wUint(big and 1 or 0, 1)
    ec.wUint(numChars, big and 15 or 7)
    ec.wArray(buf, 8 * numChars)
end

local function ecUuid()
    local h = "0123456789abcdef"
    local function seg(n)
        local s = {}
        for _ = 1, n do local i = math.random(1, 16); s[#s+1] = h:sub(i, i) end
        return table.concat(s)
    end
    return ("%s-%s-4%s-%s%s-%s"):format(seg(8), seg(4), seg(3),
        ("89ab"):sub(math.random(1,4), math.random(1,4)), seg(3), seg(12))
end

function chatCommands.engineChat.buildPacket(text, team, rid)
    local ec = chatCommands.engineChat
    ec.resetBuffer()
    ec.wUint(0x3246, 14)
    ec.wUint(0, 1)
    ec.wUint(ec.MSGTYPE, 8)
    ec.wString(ec.strBuf, text, 256)
    ec.wString(ec.guidBuf, ecUuid(), 40)
    ec.wUint(3, 8)
    ec.wInt64(rid, 64)
    ec.wUint(0, 8)
    ec.wUint(team and 1 or 0, 1)
    local curBit = Memory.ReadInt(ec.bitbuf + 0x14) or 0
    return (curBit + 7) >> 3
end

function chatCommands.engineChat.send(text, team, targetPid, echoLocal)
    local ec = chatCommands.engineChat
    if not chatCommands.engineChat.resolve() then return false end
    local rid = chatCommands.engineChat.localRid()
    if not rid then return false end
    local mgr = Memory.ReadLong(ec.cxnGlobal)
    if not ecPlausible(mgr) then return false end

    text = ecUtf8Prefix(text, 255)
    local size = chatCommands.engineChat.buildPacket(text, team == true, rid)
    if not size or size <= 0 or size > ec.BUF_BYTES then return false end

    local me = GTA.GetLocalPlayerId()
    for pid = 0, 31 do
        if pid ~= me and (targetPid == nil or pid == targetPid)
            and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
            local np = Players.GetById(pid)
            local addr = np and np:GetAddress() or nil
            if ecPlausible(addr) then
                local msgId = Memory.ReadInt(addr + ec.MSG_ID_OFF)
                if type(msgId) == "number" and msgId ~= 0 then
                    Memory.LuaCallCFunctionWithReturnValue(ec.qp, mgr, msgId, ec.bufData, size, ec.QP_FLAGS, 0)
                end
            end
        end
    end
    if echoLocal then chatCommands.engineChat.localEcho(text) end
    return true
end

if not IS_ENHANCED then
    scanDoctor.register("CHAT-CONNMGR", { probe = function()
        return scanDoctor.scanOk(chatCommands.engineChat.AOB_CXN)
    end })
    scanDoctor.register("CHAT-QUEUEPKT", { probe = function()
        return scanDoctor.scanOk(chatCommands.engineChat.AOB_QP)
    end })
end

function chatCommands.reply(pid, mode, msg)
    if mode == "off" or not msg or msg == "" then return end
    if mode == "sms" then
        chatCommands.replySms(pid, msg)
        return
    end
    if mode == "private" then
        chatCommands.recentReply[msg] = Time.GetEpocheMs() + 4000
        chatCommands.engineChat.send(msg, false, pid, true)
        return
    end
    if mode == "public" then
        chatCommands.recentReply[msg] = Time.GetEpocheMs() + 4000
        if not chatCommands.engineChat.send(msg, false, nil, true) then
            GTA.SendChatMessageToEveryone(msg, false)
        end
    end
end

function chatCommands.replySms(pid, msg)
    if pid == GTA.GetLocalPlayerId() then return end
    if not chatCommands.handleBuf then chatCommands.handleBuf = Memory.Alloc(104) end
    Natives.InvokeVoid(N_HANDLE_FROM_PLAYER, pid, chatCommands.handleBuf, 13)
    Natives.InvokeBool(N_SEND_TEXT_MESSAGE, tostring(msg):sub(1, 60), chatCommands.handleBuf)
end

function chatCommands.logActivity(who, cmd, target, result)
    local a = chatCommands.activity
    a[#a + 1] = { t = os.date("%H:%M:%S"), who = who, cmd = cmd, target = target, result = result }
    while #a > chatCommands.ACT_MAX do table.remove(a, 1) end
end

function chatCommands.packCommandList(keys, maxChars)
    local header = "Chat Commands: "
    local lines, line = {}, header
    for _, key in ipairs(keys) do
        local d = chatCommands.commands[key]
        if d and d.on and d.aliases[1] then
            local token = chatCommands.prefix .. d.aliases[1]
            local candidate = line == header and (line .. token) or (line .. ", " .. token)
            if line ~= header and #candidate > maxChars then
                lines[#lines + 1] = line
                line = header .. token
            else
                line = candidate
            end
        end
    end
    if line == header then line = header .. "none" end
    lines[#lines + 1] = line
    return lines
end

function chatCommands.commandListLines()
    chatCommands.sortOrderByTier()
    local keys = {}
    local everyone = chatCommands.audiences.everyone or 0
    for _, key in ipairs(chatCommands.order) do
        local d = chatCommands.commands[key]
        if d.on and everyone >= LV[d.tier] then keys[#keys + 1] = key end
    end
    return chatCommands.packCommandList(keys, 140)
end

function chatCommands.postCommandList(silentCooldown)
    local now = Time.GetEpocheMs()
    local remaining = (chatCommands.nextCommandListMs or 0) - now
    if remaining > 0 then
        if not silentCooldown then
            GUI.AddToast("VibeScript",
                ("Command list is on cooldown for %.1f more seconds."):format(remaining / 1000), 2500)
        end
        return false
    end
    chatCommands.nextCommandListMs = now + chatCommands.COMMAND_LIST_COOLDOWN_MS
    Script.QueueJob(function()
        local lines = chatCommands.commandListLines()
        GUI.AddToast("VibeScript", T("Posting command list to the lobby..."), 3000)
        for _, line in ipairs(lines) do
            chatCommands.recentReply[line] = Time.GetEpocheMs() + 6000
            if not chatCommands.engineChat.send(line, false, nil, true) then
                GTA.SendChatMessageToEveryone(line, false)
            end
            Script.Yield(700)
        end
    end)
    return true
end

function chatCommands.sendHelp()
    chatCommands.postCommandList(true)
end

FeatureMgr.AddFeature(H.CHAT_COMMANDS, "Chat Commands", eFeatureType.Toggle,
    "Let other players run curated commands by typing them in text chat.")
    :SetSaveable(false)

function chatCommands.isEnabled()
    local f = FeatureMgr.GetFeature(H.CHAT_COMMANDS)
    return f ~= nil and f:IsToggled() == true and not IS_ENHANCED
end

function chatCommands.onChat(sender, message, isTeam)
    if not chatCommands.isEnabled() then return end
    if type(message) ~= "string" or message == "" then return end
    local exp = chatCommands.recentReply[message]
    if exp and Time.GetEpocheMs() < exp then return end
    if message:sub(1, #chatCommands.prefix) ~= chatCommands.prefix then return end
    chatCommands.displayFilter.markPending()
    if not sender then return end
    local pid = sender.PlayerId
    if type(pid) ~= "number" or pid < 0 or pid > 31 then return end

    local now = Time.GetEpocheMs()
    local team = isTeam == true
    local last = chatCommands.lastInbound[pid]
    if last and last.message == message and last.team == team and now - last.at < 500 then
        return
    end
    chatCommands.lastInbound[pid] = { message = message, team = team, at = now }

    chatCommands.jobs[#chatCommands.jobs + 1] = {
        pid = pid, text = message:sub(#chatCommands.prefix + 1), team = team,
    }
end

Script.RegisterLooped(function()
    if not scriptUnloading and Time.GetEpocheMs() >= chatCommands.nextRampLeaveCheckMs then
        chatCommands.nextRampLeaveCheckMs = Time.GetEpocheMs() + 2000
        local ok, err = pcall(chatCommands.reapLeftRamps)
        if not ok then VIBE_LOG_ERROR(("[ChatCommands] ramp leave check raised: %s"):format(tostring(err))) end
    end
    if scriptUnloading or #chatCommands.jobs == 0 then Script.Yield(80); return end
    local job = table.remove(chatCommands.jobs, 1)
    local ok, err = pcall(chatCommands.run, job)
    if not ok then VIBE_LOG_ERROR(("[ChatCommands] run raised: %s"):format(tostring(err))) end
    Script.Yield()
end)

function chatCommands.run(job)
    local pid = job.pid
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then return end
    local rid  = chatCommands.ridOf(pid)
    local who  = chatCommands.nameOf(pid)

    if rid and chatCommands.people[rid] and chatCommands.people[rid].mode == "block" then return end

    local text = job.text:gsub("^%s+", "")
    local word, rest = text:match("^(%S+)%s*(.*)$")
    if not word then return end
    local key = chatCommands.aliasMap[word:lower()]

    if not key then
        local hash = chatCommands.resolveVehicle(text)
        if not hash then hash = chatCommands.resolveVehicle(word) end
        if hash then key = "spawn"; rest = text end
    end
    if not key then return end

    local d = chatCommands.commands[key]
    if not d or not d.on then return end

    local isSelf = chatCommands.isOwner(pid, rid)
    local now = Time.GetEpocheMs()

    if not isSelf then
        if now < (chatCommands.cooldown[pid] or 0) then
            chatCommands.reply(pid, chatCommands.replyErr, "Slow down.")
            return
        end
        local level = chatCommands.effectiveLevel(pid, rid, job.team)
        local granted = rid and chatCommands.people[rid] and chatCommands.people[rid].mode == "grant"
            and chatCommands.people[rid].grants[key]
        if not (level >= LV[d.tier] or granted) then
            chatCommands.reply(pid, chatCommands.replyErr, "You can't use " .. chatCommands.prefix .. d.aliases[1] .. ".")
            return
        end
    end

    if key == "help" then
        d.run()
        return
    end

    local target, arg = pid, rest
    if d.arg == "player" then
        if chatCommands.needsName(d.name) and (not rest or rest:gsub("%s+", "") == "") then
            chatCommands.reply(pid, chatCommands.replyErr,
                "Usage: " .. chatCommands.prefix .. d.aliases[1] .. " PlayerName")
            return
        end
        if rest and rest:gsub("%s+", "") ~= "" then
            local t = chatCommands.findPlayer(rest)
            if not t then
                chatCommands.reply(pid, chatCommands.replyErr, "No player matching '" .. rest .. "'.")
                return
            end
            target = t
        end
        if not isSelf and chatCommands.protectSelf and target == GTA.GetLocalPlayerId() then
            chatCommands.reply(pid, chatCommands.replyErr, "Can't target the menu user.")
            return
        end
        if not isSelf and d.tier ~= SAFE then
            local issuerTrusted = rid and chatCommands.people[rid] and chatCommands.people[rid].mode == "trust"
            if chatCommands.protectFriends and not issuerTrusted and chatCommands.isProtectedTarget(target) then
                chatCommands.reply(pid, chatCommands.replyErr, "That player is protected.")
                return
            end
        end
    end

    if not isSelf then chatCommands.cooldown[pid] = now + chatCommands.COOLDOWN_MS end

    local ok, result = d.run(target, arg, isSelf, pid)
    local tname = (target == pid) and who or chatCommands.nameOf(target)
    chatCommands.logActivity(who, d.aliases[1], tname, ok and (result or "Done.") or ("failed: " .. tostring(result)))
    if ok then
        chatCommands.reply(pid, chatCommands.replyOk, tostring(result or "Done."))
    else
        chatCommands.reply(pid, chatCommands.replyErr, "Couldn't " .. d.aliases[1] .. ": " .. tostring(result))
    end
end

function chatCommands.needsName(name)
    name = name:lower()
    return name:find("kick", 1, true) ~= nil or name:find("crash", 1, true) ~= nil
end

function chatCommands.isProtectedTarget(pid)
    if isPlayerFriend(pid) then return true end
    local myBoss = getOrgBoss(GTA.GetLocalPlayerId())
    if myBoss >= 0 and myBoss <= 31 and getOrgBoss(pid) == myBoss then return true end
    return false
end

function chatCommands.findPlayer(text)
    local q = text:gsub("%s+$", ""):lower()
    if q == "me" or q == "self" then return nil end
    local list = Players.Get() or {}
    for _, pid in pairs(list) do
        if chatCommands.nameOf(pid):lower() == q then return pid end
    end
    local hit, count = nil, 0
    for _, pid in pairs(list) do
        if chatCommands.nameOf(pid):lower():sub(1, #q) == q then hit = pid; count = count + 1 end
    end
    if count == 1 then return hit end
    return nil
end

local TIER_LETTER = { [SAFE]="S", [RUDE]="R", [UNSAFE]="U" }
local LETTER_TIER = { S=SAFE, R=RUDE, U=UNSAFE }

function chatCommands.encode()
    local cc = chatCommands
    local flags = ("prefix=%s;protectself=%d;protect=%d;hide=%d;replyok=%s;replyerr=%s")
        :format(cc.prefix, cc.protectSelf and 1 or 0, cc.protectFriends and 1 or 0,
            cc.hideMessages and 1 or 0, cc.replyOk, cc.replyErr)

    local aud = {}
    for _, a in ipairs(cc.AUD_ORDER) do aud[#aud+1] = a .. ":" .. tostring(cc.audiences[a] or 0) end

    local cmds = {}
    local custom = {}
    for _, key in ipairs(cc.order) do
        local d = cc.commands[key]
        if d.custom then
            custom[#custom+1] = ("%s:%s:%d:%s:%d:%s:%s"):format(
                key, tostring(d.featureHash), d.playerFeature and 1 or 0,
                TIER_LETTER[d.tier] or "S", d.on and 1 or 0,
                hexEncode(d.name), table.concat(d.aliases, "+"))
        else
            cmds[#cmds+1] = ("%s:%s:%d:%s"):format(key, TIER_LETTER[d.tier] or "S",
                d.on and 1 or 0, table.concat(d.aliases, "+"))
        end
    end

    local ppl = {}
    for rid, p in pairs(cc.people) do
        local grants = {}
        if p.grants then for k in pairs(p.grants) do grants[#grants+1] = k end end
        ppl[#ppl+1] = ("%s:%s:%s"):format(rid, p.mode or "block", table.concat(grants, "+"))
    end

    return table.concat({
        flags,
        "aud=" .. table.concat(aud, ","),
        "trusted=" .. tostring(cc.trusted or 0),
        "cmd=" .. table.concat(cmds, ","),
        "custom=" .. table.concat(custom, ","),
        "people=" .. table.concat(ppl, ","),
    }, "|")
end

function chatCommands.decode(blob)
    local cc = chatCommands
    for i = #cc.order, 1, -1 do
        local key = cc.order[i]
        if cc.commands[key] and cc.commands[key].custom then
            cc.commands[key] = nil
            table.remove(cc.order, i)
        end
    end
    cc.customNext = 1
    local sect = {}
    for part in tostring(blob):gmatch("[^|]+") do
        local k, v = part:match("^(%a+)=(.*)$")
        if k then sect[k] = v end
    end
    local flags = tostring(blob):match("^([^|]+)")
    if flags then
        for k, v in flags:gmatch("(%a+)=([^;]*)") do
            if     k == "prefix"   then if v ~= "" then cc.prefix = v end
            elseif k == "protectself" then cc.protectSelf = v == "1"
            elseif k == "protect"  then cc.protectFriends = v == "1"
            elseif k == "hide"     then cc.hideMessages = v == "1"
            elseif k == "replyok"  then cc.replyOk = v
            elseif k == "replyerr" then cc.replyErr = v end
        end
    end
    if sect.aud then
        for entry in sect.aud:gmatch("[^,]+") do
            local a, lv = entry:match("^(%a+):(%d)$")
            if a and cc.audiences[a] ~= nil then cc.audiences[a] = tonumber(lv) or 0 end
        end
    end
    if sect.trusted then cc.trusted = tonumber(sect.trusted) or cc.trusted end
    if sect.custom then
        for entry in sect.custom:gmatch("[^,]+") do
            local key, hashText, player, letter, on, encodedName, aliases = entry:match(
                "^(custom_%d+):(-?%d+):([01]):(%a):([01]):(%x*):(.*)$")
            local hash = hashText and math.tointeger(tonumber(hashText))
            local name = encodedName and hexDecode(encodedName)
            if key and hash and name and name ~= "" and aliases and aliases ~= "" then
                local list = {}
                for alias in aliases:gmatch("[^+]+") do list[#list + 1] = alias end
                if #list > 0 then
                    cc.registerCustom(key, name, LETTER_TIER[letter] or SAFE, list,
                        hash, player == "1", on == "1")
                end
            end
        end
    end
    if sect.cmd then
        for entry in sect.cmd:gmatch("[^,]+") do
            local key, letter, on, aliases = entry:match("^([%w_]+):(%a):(%d):(.*)$")
            if key == "placeholder1" then key = "crash" end
            local d = key and cc.commands[key]
            if d then
                d.tier = LETTER_TIER[letter] or d.tier
                d.on = on == "1"
                if aliases and aliases ~= "" then
                    local list = {}
                    for a in aliases:gmatch("[^+]+") do list[#list+1] = a end
                    if #list > 0 then d.aliases = list end
                end
            end
        end
    end
    local wanted = cc.commands.wanted
    if wanted then
        local aliases = { "nocops" }
        for _, alias in ipairs(wanted.aliases) do
            local lower = alias:lower()
            if lower ~= "nocops" and lower ~= "wanted" then aliases[#aliases + 1] = alias end
        end
        wanted.aliases = aliases
    end
    cc.people = {}
    if sect.people then
        for entry in sect.people:gmatch("[^,]+") do
            local rid, mode, grants = entry:match("^(%d+):(%a+):(.*)$")
            if rid then
                local g = {}
                if grants then
                    for k in grants:gmatch("[^+]+") do
                        local grantKey = (k == "placeholder1") and "crash" or k
                        if cc.commands[grantKey] then g[grantKey] = true end
                    end
                end
                cc.people[math.tointeger(tonumber(rid))] = { name = "", mode = mode, grants = g }
            end
        end
    end
    cc.rebuildAliases()
    cc.sortOrderByTier()
    if cc.displayFilter then cc.displayFilter.sync() end
end

function chatCommands.savePersistent()
    local ok = FileMgr.WriteFileContent(chatCommands.configFile, chatCommands.encode(), false)
    if not ok then
        logErr("Save chat commands failed: could not write " .. chatCommands.configFile)
    end
    return ok == true
end

function chatCommands.loadPersistent(legacyBlob)
    local blob, migrate = nil, false
    if FileMgr.DoesFileExist(chatCommands.configFile) then
        blob = FileMgr.ReadFileContent(chatCommands.configFile)
    elseif legacyBlob and legacyBlob ~= "" then
        blob, migrate = legacyBlob, true
    end
    if not blob or blob == "" then return false end

    chatCommands.decode(blob)
    if migrate then chatCommands.savePersistent() end
    return true
end

chatCommands.loadPersistent()

local TIER_LABEL = { [SAFE]=T("Safe"), [RUDE]=T("Rude"), [UNSAFE]=T("Unsafe") }
local AUD_LABEL = {
    everyone=T("Everyone"), friends=T("Friends"), crew=T("Crew"),
    org=T("Org / MC"), team=T("Team chat"),
}

local function tierColor(tier)
    if tier == SAFE   then return 0.45, 0.85, 0.45 end
    if tier == RUDE   then return 0.95, 0.75, 0.30 end
    return 0.95, 0.40, 0.40
end

local function tierCombo(id, tier)
    local order = { SAFE, RUDE, UNSAFE }
    local cur = 0
    for i = 1, 3 do if order[i] == tier then cur = i - 1 end end
    ImGui.SetNextItemWidth(90)
    local sel, changed = Widget.combo("##" .. id, cur,
        { TIER_LABEL[SAFE], TIER_LABEL[RUDE], TIER_LABEL[UNSAFE] }, 3)
    if changed then return order[sel + 1] end
    return tier
end

function chatCommands.renderTab()
    chatCommands.buildDisplayNames()
    local cc = chatCommands

    ImGui.PushID("ChatCommandsHead")
    if ClickGUI.BeginCustomChildWindow(T("Settings")) then
        if ImGui.BeginTable("##cc_primary", 2, ImGuiTableFlags.SizingStretchSame) then
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0)
            ClickGUI.RenderFeature(H.CHAT_COMMANDS)
            ImGui.TableSetColumnIndex(1)
            local postLabel = T("Post command list")
            local postWidth = ImGui.CalcTextSize(postLabel) + 16
            local postX, postAvail = ImGui.GetCursorPosX(), ImGui.GetContentRegionAvail()
            ImGui.SetCursorPosX(postX + math.max(0, postAvail - postWidth))
            if ImGui.Button(postLabel .. "##Post command list", postWidth, 0) then
                cc.postCommandList()
            end
            if ImGui.IsItemHovered() then
                ImGui.SetTooltip(T("Posts in chat a list of commands available to the Everyone audience at its selected tier."))
            end
            ImGui.EndTable()
        end
        Theme.sep(1)

        local pi = 0
        for i = 1, #cc.PREFIXES do if cc.PREFIXES[i] == cc.prefix then pi = i - 1 end end
        local ri = 0
        for i = 1, #cc.REPLY_MODES do if cc.REPLY_MODES[i] == cc.replyOk then ri = i - 1 end end
        if ImGui.BeginTable("##cc_routing", 3, ImGuiTableFlags.SizingStretchSame) then
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0)
            ImGui.Text(T("Prefix"))
            ImGui.SetNextItemWidth(-1)
            local sel, ch = Widget.combo("##cc_prefix", pi, cc.PREFIXES, #cc.PREFIXES)
            if ch then
                cc.prefix = cc.PREFIXES[sel + 1]
                cc.displayFilter.sync()
            end

            ImGui.TableSetColumnIndex(1)
            ImGui.Text(T("Success reply"))
            ImGui.SetNextItemWidth(-1)
            sel, ch = Widget.combo("##cc_rok", ri,
                { T("off"), T("private chat"), T("lobby chat"), T("phone SMS") }, 4)
            if ch then cc.replyOk = cc.REPLY_MODES[sel + 1] end

            ImGui.TableSetColumnIndex(2)
            ImGui.Text(T("Error reply"))
            ImGui.SetNextItemWidth(-1)
            ri = 0
            for i = 1, #cc.REPLY_MODES do if cc.REPLY_MODES[i] == cc.replyErr then ri = i - 1 end end
            sel, ch = Widget.combo("##cc_rerr", ri,
                { T("off"), T("private chat"), T("lobby chat"), T("phone SMS") }, 4)
            if ch then cc.replyErr = cc.REPLY_MODES[sel + 1] end
            ImGui.EndTable()
        end

        local v, ch = ImGui.Checkbox(TL("Protect self"), cc.protectSelf)
        if ch then cc.protectSelf = v end
        ImGui.SameLine()
        v, ch = ImGui.Checkbox(TL("Protect friends / org"), cc.protectFriends)
        if ch then cc.protectFriends = v end
        ImGui.SameLine()
        v, ch = ImGui.Checkbox(TL("Hide command messages"), cc.hideMessages)
        if ch then
            cc.hideMessages = v
            local ok, err = cc.displayFilter.sync()
            if v and not ok then
                cc.hideMessages = false
                GUI.AddToast("VibeScript",
                    T("Hide command messages is unavailable: %s"):format(tostring(err)), 5000)
            end
        end
        ClickGUI.EndCustomChildWindow()
    end
    ImGui.PopID()

    if ImGui.BeginTable("##cc_top", 2, ImGuiTableFlags.SizingStretchSame) then
        ImGui.TableNextRow()

        ImGui.TableSetColumnIndex(0)
        ImGui.PushID("ChatCommandsAudiences")
        if ClickGUI.BeginCustomChildWindow(T("Permission Tiers")) then
            for _, a in ipairs(cc.AUD_ORDER) do
                ImGui.Text(AUD_LABEL[a]); ImGui.SameLine(110)
                ImGui.SetNextItemWidth(-1)
                local sel, ch = Widget.combo("##ccaud_" .. a, cc.audiences[a] or 0, LEVEL_LABELS, 4)
                if ch then cc.audiences[a] = sel end
            end
            Theme.sep(1)
            ImGui.Text(T("Trusted")); ImGui.SameLine(110)
            ImGui.SetNextItemWidth(-1)
            local ts, tch = Widget.combo("##cctrust", cc.trusted or 0, LEVEL_LABELS, 4)
            if tch then cc.trusted = ts end
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.PopID()

        ImGui.TableSetColumnIndex(1)
        ImGui.PushID("ChatCommandsPeople")
        if ClickGUI.BeginCustomChildWindow(T("Whitelist / Blocklist")) then
            if chatCommands.renderPeople then chatCommands.renderPeople() end
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.PopID()
        ImGui.PushID("ChatCommandsAliases")
        if ClickGUI.BeginCustomChildWindow(T("Aliases")) then
            if chatCommands.renderAliasEditor then chatCommands.renderAliasEditor() end
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.PopID()

        ImGui.EndTable()
    end

    ImGui.PushID("ChatCommandsList")
    if ClickGUI.BeginCustomChildWindow(T("Command List")) then
        cc.sortOrderByTier()
        local removeKey, resort = nil, false
        for _, key in ipairs(cc.order) do
            local d = cc.commands[key]
            local unavailable = d.custom and d.available == false
            if unavailable then
                ImGui.TextDisabled((cc.selCmd == key and "> " or "")
                    .. T("%s [Unavailable]"):format(T(d.name)))
                if ImGui.IsItemHovered() then
                    ImGui.SetTooltip(T("Disabled because the providing script is not loaded."))
                end
            else
                local vv, cch = ImGui.Checkbox("##on_" .. key, d.on)
                if cch then d.on = vv end
                ImGui.SameLine()
                local r, g, b = tierColor(d.tier)
                ImGui.TextColored(r, g, b, 1.0,
                    (cc.selCmd == key and "> " or "") .. T(d.name))
                ImGui.SameLine(200)
                local nt = tierCombo("tier_" .. key, d.tier)
                if nt ~= d.tier then d.tier = nt; resort = true end
                ImGui.SameLine()
                if ImGui.SmallButton(T("Aliases") .. "##ed_" .. key) then cc.selCmd = key end
                ImGui.SameLine()
                ImGui.TextDisabled(chatCommands.prefix
                    .. table.concat(d.aliases, ("  %s"):format(chatCommands.prefix)))
            end
            if d.custom then
                ImGui.SameLine()
                ImGui.PushStyleColor(ImGuiCol.Button,        0.55, 0.18, 0.18, 0.95)
                ImGui.PushStyleColor(ImGuiCol.ButtonHovered, 0.72, 0.24, 0.24, 1.00)
                ImGui.PushStyleColor(ImGuiCol.ButtonActive,  0.42, 0.13, 0.13, 1.00)
                if ImGui.SmallButton("X##del_" .. key) then removeKey = key end
                ImGui.PopStyleColor(3)
                if ImGui.IsItemHovered() then ImGui.SetTooltip(T("Delete custom command")) end
            end
        end
        if removeKey then cc.removeCustom(removeKey) end
        if resort then cc.sortOrderByTier() end

        Theme.sep(1)
        ImGui.Text(T("Add Custom Command"))
        ImGui.SameLine()
        if ImGui.SmallButton(T("Refresh") .. "##cc_refresh_features") then
            cc.requestFeatureRefresh()
        end
        cc.customFeatureFilter = cc.customFeatureFilter or ""
        local oldFilter = cc.customFeatureFilter
        cc.customFeatureFilter = ImGui.InputTextWithHint("##cc_feature_filter",
            T("Search for cherax and lua features"), cc.customFeatureFilter)
        if cc.customFeatureFilter ~= oldFilter then
            cc.customFeatureIndex = 0
            cc.customFeatureSelectionId = nil
        end
        if cc.featureScanStatus then
            ImGui.PushTextWrapPos(0)
            ImGui.TextDisabled(cc.featureScanStatus)
            ImGui.PopTextWrapPos()
        end

        local filtered, featureLabels = {}, {}
        local needle = cc.customFeatureFilter:lower()
        for _, entry in ipairs(cc.featureChoices or {}) do
            if needle == "" or entry.label:lower():find(needle, 1, true) then
                filtered[#filtered + 1] = entry
                featureLabels[#featureLabels + 1] = entry.label
            end
        end

        local selectedFeature = nil
        if #filtered > 0 then
            ImGui.Text(T("Feature"))
            if cc.customFeatureSelectionId then
                for i, entry in ipairs(filtered) do
                    if entry.id == cc.customFeatureSelectionId then
                        cc.customFeatureIndex = i - 1
                        break
                    end
                end
            end
            cc.customFeatureIndex = math.min(cc.customFeatureIndex or 0, #filtered - 1)
            ImGui.SetNextItemWidth(-1)
            local selected, changed = Widget.combo("##cc_custom_feature", cc.customFeatureIndex,
                featureLabels, #featureLabels)
            if changed then cc.customFeatureIndex = selected end
            selectedFeature = filtered[(cc.customFeatureIndex or 0) + 1]
            cc.customFeatureSelectionId = selectedFeature and selectedFeature.id or nil
        elseif not cc.featureScanPending and not cc.featureScanStatus then
            ImGui.TextDisabled(T("No matching button features."))
        end

        cc.customTierIndex = cc.customTierIndex or 0
        cc.customAliasInput = cc.customAliasInput or ""
        local addPressed = false
        if ImGui.BeginTable("##cc_custom_builder", 3, ImGuiTableFlags.SizingStretchSame) then
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0)
            ImGui.Text(T("Tier"))
            ImGui.SetNextItemWidth(-1)
            local tierIndex, tierChanged = Widget.combo("##cc_custom_tier", cc.customTierIndex,
                { TIER_LABEL[SAFE], TIER_LABEL[RUDE], TIER_LABEL[UNSAFE] }, 3)
            if tierChanged then cc.customTierIndex = tierIndex end

            ImGui.TableSetColumnIndex(1)
            ImGui.Text(T("Command / Aliases"))
            ImGui.SetNextItemWidth(-1)
            cc.customAliasInput = ImGui.InputTextWithHint("##cc_custom_aliases",
                T("aliases, separated by spaces"), cc.customAliasInput)

            ImGui.TableSetColumnIndex(2)
            ImGui.Text(" ")
            ImGui.PushStyleColor(ImGuiCol.Button,        0.20, 0.62, 0.30, 0.95)
            ImGui.PushStyleColor(ImGuiCol.ButtonHovered, 0.26, 0.78, 0.38, 1.00)
            ImGui.PushStyleColor(ImGuiCol.ButtonActive,  0.16, 0.52, 0.26, 1.00)
            addPressed = ImGui.Button("+##cc_add_custom", 45, 0)
            ImGui.PopStyleColor(3)
            if ImGui.IsItemHovered() then ImGui.SetTooltip(T("Add custom command")) end
            ImGui.EndTable()
        end

        if selectedFeature and selectedFeature.playerFeature then
            local exampleAlias = cc.customAliasInput:match("[^,%s]+") or "alias"
            if exampleAlias:sub(1, #cc.prefix) == cc.prefix then
                exampleAlias = exampleAlias:sub(#cc.prefix + 1)
            end
            ImGui.PushTextWrapPos(0)
            ImGui.TextDisabled(T("Player Feature Command Format: %s"):format(
                cc.prefix .. exampleAlias .. " PlayerName"))
            if not cc.needsName(selectedFeature.name) then
                ImGui.TextDisabled(T("Skip the name to target yourself."))
            end
            ImGui.PopTextWrapPos()
        end

        if addPressed and selectedFeature then
            local aliases = cc.parseCustomAliases(cc.customAliasInput)
            if #aliases > 0 then
                local tiers = { SAFE, RUDE, UNSAFE }
                cc.registerCustom(nil, selectedFeature.name, tiers[cc.customTierIndex + 1], aliases,
                    selectedFeature.hash, selectedFeature.playerFeature, true)
                cc.rebuildAliases()
                cc.savePersistent()
                cc.customAliasInput = ""
                cc.customAddStatus = nil
            else
                cc.customAddStatus = T("Enter at least one unused alias.")
            end
        end
        if cc.customAddStatus then ImGui.TextDisabled(cc.customAddStatus) end
        ClickGUI.EndCustomChildWindow()
    end
    ImGui.PopID()

    ImGui.PushID("ChatCommandsLog")
    if ClickGUI.BeginCustomChildWindow(T("Recent command activity")) then
        if #cc.activity == 0 then
            ImGui.TextDisabled(T("Nothing yet."))
        else
            for i = #cc.activity, math.max(1, #cc.activity - 12), -1 do
                local e = cc.activity[i]
                ImGui.Text(("[%s] %s: %s%s -> %s"):format(e.t, e.who, cc.prefix, e.cmd,
                    e.target)); ImGui.SameLine()
                ImGui.TextDisabled(e.result)
            end
        end
        ClickGUI.EndCustomChildWindow()
    end
    ImGui.PopID()
end

function chatCommands.renderPeople()
    local cc = chatCommands
    cc.peopleSearch = cc.peopleSearch or ""
    ImGui.SetNextItemWidth(-1)
    local q, _ = ImGui.InputTextWithHint("##cc_psearch", T("Search player names to add"), cc.peopleSearch)
    cc.peopleSearch = q
    if q ~= "" then
        local ql = q:lower()
        local shown = 0
        for _, pid in pairs(Players.Get() or {}) do
            if pid ~= GTA.GetLocalPlayerId() then
                local nm = cc.nameOf(pid)
                if nm:lower():find(ql, 1, true) and shown < 6 then
                    shown = shown + 1
                    if ImGui.SmallButton(T("Add") .. "##add_" .. pid) then
                        local rid = cc.ridOf(pid)
                        if rid then
                            cc.people[rid] = cc.people[rid] or { name = nm, mode = "trust", grants = {} }
                            cc.people[rid].name = nm

                        end
                    end
                    ImGui.SameLine(); ImGui.Text(nm)
                end
            end
        end
    end
    Theme.sep(1)
    local livePeople = {}
    for _, pid in pairs(Players.Get() or {}) do
        local rid = cc.ridOf(pid)
        if rid then
            livePeople[rid] = pid
            if cc.people[rid] then cc.people[rid].name = cc.nameOf(pid) end
        end
    end
    local any = false
    for rid, p in pairs(cc.people) do
        if livePeople[rid] then
            any = true
            local modes = { "trust", "grant", "block" }
            local labels = { T("Trust"), T("Grant one"), T("Block") }
            local cur = 0
            for i = 1, 3 do if modes[i] == p.mode then cur = i - 1 end end
            if ImGui.BeginTable("##person_" .. rid, 3, ImGuiTableFlags.SizingStretchSame) then
                ImGui.TableNextRow()
                ImGui.TableSetColumnIndex(0)
                ImGui.Text(p.name)
                ImGui.TableSetColumnIndex(1)
                ImGui.SetNextItemWidth(-1)
                local sel, ch = Widget.combo("##pm_" .. rid, cur, labels, 3)
                if ch then p.mode = modes[sel + 1] end
                ImGui.TableSetColumnIndex(2)
                if ImGui.Button(T("Remove") .. "##prm_" .. rid, ImGui.GetContentRegionAvail(), 0) then
                    cc.people[rid] = nil
                end
                ImGui.EndTable()
            end
            if p.mode == "grant" then
                p.grants = p.grants or {}
                if ImGui.BeginTable("##grants_" .. rid, 2, ImGuiTableFlags.SizingStretchSame) then
                    local col = 0
                    for _, key in ipairs(cc.order) do
                        if col == 0 then ImGui.TableNextRow() end
                        ImGui.TableSetColumnIndex(col)
                        local d = cc.commands[key]
                        local on = p.grants[key] == true
                        local vv, cch = ImGui.Checkbox(d.aliases[1] .. "##g_" .. rid .. key, on)
                        if cch then p.grants[key] = vv or nil end
                        col = (col + 1) % 2
                    end
                    ImGui.EndTable()
                end
            end
        end
    end
    if not any then
        ImGui.PushTextWrapPos(0)
        if next(cc.people) == nil then
            ImGui.TextDisabled(T("No people added yet. Search a name above to trust, grant, or block them."))
        else
            ImGui.TextDisabled(T("No saved people are in this lobby."))
        end
        ImGui.PopTextWrapPos()
    end
end

function chatCommands.renderAliasEditor()
    local cc = chatCommands
    local key = cc.selCmd
    local d = key and cc.commands[key]
    if not d then
        ImGui.PushTextWrapPos(0)
        ImGui.TextDisabled(T("Select a command below (Aliases) to change what people type for it."))
        ImGui.PopTextWrapPos()
        return
    end

    if ImGui.SmallButton(TL("Done")) then
        cc.savePersistent()
        cc.selCmd = nil
        cc.aliasInput = ""
        return
    end
    ImGui.SameLine()
    ImGui.Text(T("Editing: %s"):format(T(d.name)))
    ImGui.TextDisabled(T("Click a word to delete it. Add more below."))

    local avail = ImGui.GetContentRegionAvail()
    if type(avail) ~= "number" or avail <= 0 then avail = 300 end
    local removeAt, x = nil, 0
    for i, alias in ipairs(d.aliases) do
        local shown = alias .. "  x"
        local w = (ImGui.CalcTextSize(shown) or 40) + 18
        if i > 1 then
            if x + w <= avail then ImGui.SameLine() else x = 0 end
        end
        if ImGui.SmallButton(shown .. "##chip_" .. key .. "_" .. i) then removeAt = i end
        x = x + w + 8
    end
    if removeAt and #d.aliases > 1 then
        table.remove(d.aliases, removeAt)
        cc.rebuildAliases()
    end

    cc.aliasInput = cc.aliasInput or ""
    ImGui.SetNextItemWidth(-1)
    local nv, submitted = ImGui.InputTextWithHint("##cc_addalias",
        T("add an alias, press Enter"), cc.aliasInput, ImGuiInputTextFlags.EnterReturnsTrue)
    cc.aliasInput = nv
    if submitted then
        local a = (nv or ""):match("%S+")
        if a then
            a = a:lower()
            local dup = false
            for _, e in ipairs(d.aliases) do if e:lower() == a then dup = true end end
            if not dup and cc.aliasMap[a] and cc.aliasMap[a] ~= key then dup = true end
            if not dup then d.aliases[#d.aliases + 1] = a; cc.rebuildAliases() end
        end
        cc.aliasInput = ""
    end
end

EventMgr.RegisterHandler(eLuaEvent.ON_CHAT_MESSAGE, chatCommands.onChat)

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    chatCommands.savePersistent()
    chatCommands.displayFilter.uninstall()
    for _, list in pairs(chatCommands.spawned) do
        UnloadReap.markAll(list, "ChatCommands")
    end
    for _, list in pairs(chatCommands.ramps) do
        UnloadReap.markAll(list, "ChatCommands ramps")
    end
end)

end)()

