local FOLD = {}
for base, list in pairs(FOLD_SOURCE) do
    for hex in list:gmatch("%x+") do FOLD[tonumber(hex, 16)] = base end
end

local function plainLetters(text)
    if not utf8.len(text) then return text end
    local out = {}
    for _, cp in utf8.codes(text) do
        if cp < 0x300 or cp > 0x36F then
            out[#out + 1] = FOLD[cp] or utf8.char(cp)
        end
    end
    return table.concat(out)
end

