local function addHistory(entry)
    entry.at = os.date("%H:%M")
    ct.history[#ct.history + 1] = entry
    if #ct.history > 100 then table.remove(ct.history, 1) end
    ct.historyScroll = true
end

local function urlEncode(s)
    return (tostring(s):gsub("([^%w%-_%.~])", function(c)
        return ("%%%02X"):format(c:byte())
    end))
end

local function jsonStrings(s)
    local out, i, n = {}, 1, #s
    while i <= n do
        if s:byte(i) ~= 34 then i = i + 1 else
            i = i + 1
            local b = {}
            while i <= n do
                local c = s:byte(i); i = i + 1
                if c == 34 then break end
                if c ~= 92 then b[#b + 1] = string.char(c) else
                    local e = s:sub(i, i); i = i + 1
                    if e == "u" then
                        local h = s:sub(i, i + 3); i = i + 4
                        local cp = tonumber(h, 16)
                        if not cp then return nil end
                        b[#b + 1] = utf8.char(cp)
                    else
                        local esc = { ['"']='"', ['\\']='\\', ['/']='/',
                            b='\b', f='\f', n='\n', r='\r', t='\t' }
                        b[#b + 1] = esc[e] or e
                    end
                end
            end
            out[#out + 1] = table.concat(b)
        end
    end
    return out
end

local function reapTimedOutRequests()
    for i = #ct.timedOut, 1, -1 do
        local finished = false
        pcall(function() finished = ct.timedOut[i]:GetFinished() end)
        if finished then table.remove(ct.timedOut, i) end
    end
end

local function fetchStringsOnce(url)
    reapTimedOutRequests()
    if ct.recovery and Time.GetEpocheMs() >= ct.recovery.expires then
        return nil, "translation recovery deadline reached"
    end
    local h, started
    local ok, err = pcall(function()
        h = Curl.Easy()
        h:Setopt(eCurlOption.CURLOPT_URL, url)
        h:Perform()
        started = true
    end)
    if not ok or not started then return nil, "curl start: " .. tostring(err) end
    local deadline = Time.GetEpocheMs() + 6000
    if ct.recovery then deadline = math.min(deadline, ct.recovery.expires) end
    while Time.GetEpocheMs() < deadline do
        local pok, finished = pcall(function() return h:GetFinished() end)
        if not pok then
            ct.timedOut[#ct.timedOut + 1] = h
            return nil, "curl poll failed"
        end
        if finished then
            local rok, code, body = pcall(function()
                local c, b = h:GetResponse(); return c, b
            end)
            if not rok or type(body) ~= "string" then return nil, "no response" end
            local fields = body:match("^%s*%[") and jsonStrings(body)
            if not fields or not fields[1] then
                return nil, "bad response code=" .. tostring(code)
            end
            return fields, nil, body
        end
        Script.Yield()
    end
    ct.timedOut[#ct.timedOut + 1] = h
    return nil, "request timed out"
end

local function fetchStrings(url)
    local lastErr
    for attempt = 1, 2 do
        local fields, err, body = fetchStringsOnce(url)
        if fields then return fields, nil, body end
        lastErr = err
        if attempt < 2 then
            if VIBESCRIPT_VERBOSE == true then ctError("request attempt %d failed: %s; retrying", attempt, tostring(lastErr)) end
            if ct.recovery and Time.GetEpocheMs() + 250 >= ct.recovery.expires then break end
            Script.Yield(250)
        end
    end
    return nil, lastErr
end

local function translate(text, target, source)
    if ct.endpointOk.translate == false then return nil, nil, "translate endpoint failed its check" end
    local fields, err, body = fetchStrings("https://clients5.google.com/translate_a/t?client=dict-chrome-ex&sl="
        .. urlEncode(source or "auto") .. "&tl="
        .. urlEncode(target) .. "&q=" .. urlEncode(text))
    if not fields then
        if not ct.checking then ct.queueCheck(true) end
        return nil, nil, err
    end
    if fields[2] == "jw" then fields[2] = "jv" end
    return fields[1], fields[2] or source
end

local function romanizedTranslation(text, target, source)
    if ct.endpointOk.romanize == false then return nil, "romanize endpoint failed its check" end
    local fields, err, body = fetchStrings("https://clients5.google.com/translate_a/single?client=dict-chrome-ex&dt=t&dt=rm&sl="
        .. urlEncode(source or "auto") .. "&tl=" .. urlEncode(target) .. "&q=" .. urlEncode(text))
    if not fields then return nil, err end
    local at = body:find('[null,null,"', 1, true)
    return at and jsonStrings(body:sub(at))[1]
end

local function translateLatin(text, target, source)
    local romanized, err = romanizedTranslation(text, target, source)
    if err then return nil, nil, err end
    if romanized and romanized ~= "" then return plainLetters(romanized), source end
    local translated, detected, terr = translate(text, target, source)
    if not translated then return nil, nil, terr end
    return plainLetters(translated), detected
end

local ROMANIZED_INPUT = {
    ["zh-CN"] = "zh-t-i0-pinyin", ["zh-TW"] = "zh-hant-t-i0-pinyin", ja = "ja-t-i0-und",
    ru = "ru-t-i0-und",
    uk = "uk-t-i0-und",
    bg = "bg-t-i0-und",
}

local function inputToolsCandidate(run, iso)
    if ct.endpointOk.inputTools == false then return nil, "input tools endpoint failed its check" end
    local fields, err = fetchStrings("https://inputtools.google.com/request?itc=" .. ROMANIZED_INPUT[iso]
        .. "&num=1&cp=0&cs=1&ie=utf-8&oe=utf-8&text=" .. urlEncode(run))
    if fields and fields[1] == "SUCCESS" and fields[3] then return fields[3] end
    return nil, fields and tostring(fields[1]) or tostring(err)
end

local function fromRomanized(text, iso)
    local out, converted = {}, false
    local pos = 1
    for before, run, at in text:lower():gmatch("()([%a][%a' ]*)()") do
        out[#out + 1] = text:sub(pos, before - 1)
        local candidate, ferr = inputToolsCandidate(run, iso)
        if not candidate then
            if VIBESCRIPT_VERBOSE == true then ctError("input tools %s failed for '%s': %s", iso, run, tostring(ferr)) end
        end
        if candidate and candidate:find("[\128-\255]") then
            out[#out + 1] = candidate
            converted = true
        else
            out[#out + 1] = run
        end
        pos = at
    end
    out[#out + 1] = text:sub(pos)
    return converted and table.concat(out) or nil
end

local function localLanguage()
    local id = Natives.InvokeInt(GET_CURRENT_LANGUAGE)
    return LANG[id] and LANG[id][2] or "en"
end

local function playerSelectedLanguage(pid)
    local id = ScriptGlobal.GetInt(OFF.GPBD_FM_3_BASE + 1 + pid * OFF.GPBD_FM_3_SIZE + 132)
    return LANG[id] and LANG[id][2] or "en"
end

local function chosenLanguage(hash)
    local f = FeatureMgr.GetFeature(hash)
    local index = f and f:GetListIndex() or 0
    local language = index > 0 and LANGUAGES[index]
    return language and language[2] or nil
end

local function incomingTargetLanguage()
    return chosenLanguage(H.CHAT_TRANSLATE_IN_TARGET) or localLanguage()
end

local function outgoingSourceLanguage()
    local f = FeatureMgr.GetFeature(H.CHAT_TRANSLATE_OUT_SOURCE)
    local index = f and f:GetListIndex() or 0
    if index == 0 then return localLanguage() end
    if index == 1 then return nil end
    local language = LANGUAGES[index - 1]
    return language and language[2] or localLanguage()
end

local function outgoingTargetLanguage(pid)
    local f = FeatureMgr.GetFeature(H.CHAT_TRANSLATE_OUT_TARGET)
    local index = f and f:GetListIndex() or 0
    local gta = playerSelectedLanguage(pid)
    if index == 0 then
        local recent = ct.detected[pid]
        if recent and Time.GetEpocheMs() - recent.at < 30 * 60 * 1000 then
            return recent.iso, needsLatin(recent.iso, gta)
        end
        return gta, false
    end
    if index == 1 then return gta, false end
    local language = LANGUAGES[index - 1]
    if not language then return gta, false end
    return language[2], needsLatin(language[2], gta)
end

local function profileLanguage(pid)
    return playerSelectedLanguage(pid)
end

local function languageName(iso)
    return LANGUAGE_BY_ISO[iso] or tostring(iso):upper()
end

