local FONT_MOVIE_AOB = "E8 ?? ?? ?? ?? C6 44 24 48 00 C6 44 24 40 00 C7 44 24 38 02 00 00 00 C6 44 24 30 01 83 4C 24 28 FF 83 4C 24 20 FF 4C 8D 44 24 60 48 8D 54 24 68 48 8B C8 45 33 C9 E8 ?? ?? ?? ?? 8B D8 85 C0 0F 88"
local SF_MOVIE_STRIDE = 0x1E0
local SF_MOVIE_STORE_ID = 0xB0
local SF_MOVIE_FILENAME = 0xB8
local SF_MOVIE_STATE = 0x1B8
local GFX_STATE_FONTLIB = 0x13
local ff = {}

if not IS_ENHANCED then
    scanDoctor.register("CHAT-FONTMOVIE", { probe = function()
        return scanDoctor.scanOk(FONT_MOVIE_AOB)
    end })
end

local function ffOpcode(addr, bytes)
    for i, b in ipairs(bytes) do
        if Memory.ReadUByte(addr + i - 1) ~= b then return false end
    end
    return true
end

local function resolveFonts()
    if ff.tried then return ff.ok, ff.err end
    ff.tried = true
    if IS_ENHANCED then ff.err = "Enhanced has no text chat"; return false, ff.err end
    local a = Memory.Scan(FONT_MOVIE_AOB)
    if not a or a == 0 then ff.err = "CreateFontMovie signature not found"; return false, ff.err end
    local sites = {
        { 0x36, {0xE8} }, { 0x45, {0x0F,0xB7,0x0D} }, { 0x5D, {0x48,0x8B,0x0D} },
        { 0xA2, {0x48,0x8B,0x05} }, { 0xAC, {0xBA,GFX_STATE_FONTLIB,0x00,0x00,0x00} },
        { 0xC2, {0x48,0x8D,0x0D} }, { 0xCC, {0xE8} }, { 0x149, {0x48,0x8B,0x0D} },
        { 0x161, {0xE8} }, { 0x176, {0xE8} }, { 0x17E, {0xE8} }, { 0x186, {0xE8} },
        { 0x193, {0xE8} },
    }
    for _, s in ipairs(sites) do
        if not ffOpcode(a + s[1], s[2]) then
            ff.err = ("CreateFontMovie layout changed at +0x%X"):format(s[1])
            return false, ff.err
        end
    end
    ff.create    = Memory.Rip(a + 0x37)
    ff.count     = Memory.Rip(a + 0x48)
    ff.array     = Memory.Rip(a + 0x60)
    ff.movieMgr  = Memory.Rip(a + 0xA5)
    ff.store     = Memory.Rip(a + 0xC5)
    ff.addFonts  = Memory.Rip(a + 0xCD)
    ff.parser    = Memory.Rip(a + 0x14C)
    ff.loadTree  = Memory.Rip(a + 0x162)
    ff.handleXml = Memory.Rip(a + 0x177)
    ff.treeDtor  = Memory.Rip(a + 0x17F)
    ff.delete    = Memory.Rip(a + 0x187)
    ff.release   = Memory.Rip(a + 0x194)
    if not ffOpcode(ff.handleXml, {0x48,0x8B,0xC4,0x48,0x89,0x58,0x08})
        or not ffOpcode(ff.handleXml + 0xC4, {0xE8})
        or not ffOpcode(ff.handleXml + 0xEA, {0xE8}) then
        ff.err = "HandleXML layout changed"
        return false, ff.err
    end
    ff.findChild = Memory.Rip(ff.handleXml + 0xC5)
    ff.findAttr  = Memory.Rip(ff.handleXml + 0xEB)
    ff.ok = true
    return true
end

local function ffCall(fn, ...)
    local r = Memory.LuaCallCFunctionWithReturnValue(fn, ...)
    if not r or r == 0 then return 0 end
    local v = Memory.ReadLong(r) or 0
    local size = Memory.SizeOf(r)
    if size and size ~= 0 then Memory.Free(r) end
    return v
end

local function readFontFaces(libs)
    local faces = {}
    local tree = ffCall(ff.loadTree, Memory.ReadLong(ff.parser), "common:/data/ui/fontmap.xml", "", 0)
    if tree < 0x10000 then ctError("fonts: fontmap.xml did not load"); return faces end
    local root = Memory.ReadLong(tree) or 0
    if root >= 0x10000 then
        for _, lib in ipairs(libs or CJK_FONT_LIBS) do
            local node, n = 0, 0
            repeat
                node = ffCall(ff.findChild, root, lib.section, node, 1)
                if node >= 0x10000 then
                    n = n + 1
                    local nameAttr = ffCall(ff.findAttr, node, "name")
                    local mapAttr = ffCall(ff.findAttr, node, "mapping")
                    local name = nameAttr >= 0x10000 and Memory.ReadString(Memory.ReadLong(nameAttr + 8)) or nil
                    local mapping = mapAttr >= 0x10000 and Memory.ReadString(Memory.ReadLong(mapAttr + 8)) or nil
                    if name == "$Font2" and mapping and mapping ~= "" then faces[lib.iso] = mapping end
                end
            until node < 0x10000 or n > 64
        end
    end
    Memory.LuaCallCFunction(ff.treeDtor, tree)
    Memory.LuaCallCFunction(ff.delete, tree)
    return faces
end

local function fontMovieSlot(name)
    local arr = Memory.ReadLong(ff.array) or 0
    local count = math.min(Memory.ReadUShort(ff.count) or 0, 0x32)
    if arr < 0x10000 then return nil end
    for i = 0, count - 1 do
        local e = arr + i * SF_MOVIE_STRIDE
        local state = Memory.ReadInt(e + SF_MOVIE_STATE) or 0
        if (state == 3 or state == 5)
            and (Memory.ReadString(e + SF_MOVIE_FILENAME) or ""):lower() == name then
            return i, true
        end
    end
    local vec = Memory.Alloc(16)
    Memory.MemSet(vec, 0, 16)
    local idx = ffCall(ff.create, name, vec, vec + 8, 0, -1, -1, 1, 2, 0, 0) & 0xFFFFFFFF
    Memory.Free(vec)
    if idx >= 0x32 then return nil end
    return idx, false
end

local function loadLanguageFonts()
    local ok, err = resolveFonts()
    if not ok then ctError("all-language fonts unavailable: %s", tostring(err)); return end
    local faces = readFontFaces()
    local mgr = Memory.ReadLong(ff.movieMgr) or 0
    local loader = mgr >= 0x10000 and Memory.ReadLong(mgr + 0x20) or 0
    if loader < 0x10000 then ctError("all-language fonts: Scaleform loader missing"); return end
    local getState = Memory.ReadLong(Memory.ReadLong(loader) + 0x18)
    local fontLib = ffCall(getState, loader, GFX_STATE_FONTLIB)
    if fontLib < 0x10000 then ctError("all-language fonts: no font library"); return end
    local arr = Memory.ReadLong(ff.array)
    local loaded = 0
    for _, lib in ipairs(CJK_FONT_LIBS) do
        local name = "font_lib_" .. lib.section .. "_pc"
        local idx, reused = fontMovieSlot(name)
        if idx then
            local storeId = Memory.ReadInt(arr + idx * SF_MOVIE_STRIDE + SF_MOVIE_STORE_ID)
            if not reused then Memory.LuaCallCFunction(ff.addFonts, ff.store, fontLib, storeId) end
            loaded = loaded + 1
        else
            ctError("fonts: %s failed to load", name)
        end
    end
    Memory.LuaCallCFunction(ff.release, fontLib)
    ct.fontFaces = faces
    ct.fontsReady = loaded > 0 and next(faces) ~= nil
end

local function setDisplayFilter(on)
    local df = chatCommands.displayFilter
    if on and not df.active then
        local ok, err = df.install()
        if not ok then return false, err end
    end
    if df.active and df.state ~= 0 then
        Memory.WriteByte(df.state, (on or chatCommands.hideMessages) and 1 or 0)
        if not on and not chatCommands.hideMessages then Memory.WriteByte(df.state + 1, 0) end
    end
    return true
end

local function hideNextLine()
    local df = chatCommands.displayFilter
    if df.active and df.state ~= 0 then Memory.WriteByte(df.state + 1, 1) end
end

local function readBytes(addr, n)
    local t = {}; for i = 0, n - 1 do t[#t + 1] = Memory.ReadUByte(addr + i) or 0 end
    return t
end
local function writeBytes(addr, t)
    for i, b in ipairs(t) do Memory.WriteByte(addr + i - 1, b) end
end
local function u32(v)
    v = v & 0xFFFFFFFF
    return {v & 255, (v >> 8) & 255, (v >> 16) & 255, (v >> 24) & 255}
end
local function u64(v)
    local t = {}; for i = 0, 7 do t[#t + 1] = (v >> (8 * i)) & 255 end; return t
end
local function append(a, b) for _, v in ipairs(b) do a[#a + 1] = v end end
local function findCave(need)
    local ranges = VIBE_GATE.executableRanges()
    if not ranges then return nil end
    for _, r in ipairs(ranges) do
        local run, first = 0, 0
        for p = r.from, r.to - 1 do
            if (Memory.ReadUByte(p) or 1) == 0 then
                if run == 0 then first = p end
                run = run + 1
                if run >= need then return first end
            else run = 0 end
        end
    end
    return VIBE_GATE.findExecutablePadding(need, ranges)
end

local GLYPH_MAGIC = "VBGLYPH1"
local GLYPH_INDEX_SLOTS = { 0x20, 0x28, 0x30, 0x38, 0x40, 0x50, 0x58, 0x60, 0x68 }
local GLYPH_FALLBACK_ORDER = { "ko", "zh-CN", "zh-TW", "ja" }
local GLYPH_FIRST_BASE = 0x400
local GLYPH_CAVE_BYTES = 420
ct.glyph = { patched = {}, data = 0, vt = 0 }

local function glyphFonts()
    local mgr = Memory.ReadLong(ff.movieMgr) or 0
    local loader = mgr >= 0x10000 and Memory.ReadLong(mgr + 0x20) or 0
    if loader < 0x10000 then return nil end
    local fontLib = ffCall(Memory.ReadLong(Memory.ReadLong(loader) + 0x18), loader, GFX_STATE_FONTLIB)
    if fontLib < 0x10000 then return nil end
    local impl = Memory.ReadLong(fontLib + 0x18) or 0
    local movies = impl >= 0x10000 and Memory.ReadLong(impl) or 0
    local count = impl >= 0x10000 and (Memory.ReadLong(impl + 8) or 0) or 0
    local list = {}
    for m = 0, math.min(count, 16) - 1 do
        local def = Memory.ReadLong(movies + m * 8) or 0
        local data = def >= 0x10000 and Memory.ReadLong(def + 0x40) or 0
        local node = data >= 0x10000 and Memory.ReadLong(data + 0x110) or 0
        local n = 0
        while node >= 0x10000 and n < 64 do
            n = n + 1
            local font = Memory.ReadLong(node + 8) or 0
            if font >= 0x10000 then
                local vt = Memory.ReadLong(font)
                list[#list + 1] = {
                    movie = m, font = font, vt = vt,
                    name = Memory.ReadString(ffCall(Memory.ReadLong(vt + 0x78), font)) or "",
                    glyphs = ffCall(Memory.ReadLong(vt + 0x70), font) & 0xFFFFFFFF,
                }
            end
            node = Memory.ReadLong(node + 0x18) or 0
        end
    end
    Memory.LuaCallCFunction(ff.release, fontLib)
    return list
end

local function glyphCave(need)
    for _, r in ipairs(VIBE_GATE.executableRanges() or {}) do
        for a = r.from, r.to - #GLYPH_MAGIC do
            local match = true
            for i = 1, #GLYPH_MAGIC do
                if Memory.ReadUByte(a + i - 1) ~= GLYPH_MAGIC:byte(i) then match = false; break end
            end
            if match then return a, true end
        end
    end
    return findCave(need), false
end

local function glyphAsm()
    local b, labels, fix = {}, {}, {}
    local A = {}
    function A.bytes(...) for _, v in ipairs({...}) do b[#b + 1] = v end end
    function A.u32(v) for i = 0, 3 do b[#b + 1] = (v >> (8 * i)) & 0xFF end end
    function A.u64(v) for i = 0, 7 do b[#b + 1] = (v >> (8 * i)) & 0xFF end end
    function A.label(n) labels[n] = #b end
    function A.jcc8(op, n) b[#b + 1] = op; b[#b + 1] = 0; fix[#fix + 1] = { #b, n } end
    function A.pos() return #b end
    function A.finish()
        for _, f in ipairs(fix) do
            local rel = labels[f[2]] - f[1]
            assert(rel >= -128 and rel <= 127, "short jump out of range: " .. f[2])
            b[f[1]] = rel & 0xFF
        end
        return b
    end
    return A
end

local function installGlyphFallback()
    if #ct.glyph.patched > 0 then return true end
    local fonts = glyphFonts()
    if not fonts then return false, "font library not readable" end
    local byName = {}
    for _, f in ipairs(fonts) do
        if f.movie > 0 and not byName[f.name] then byName[f.name] = f end
    end
    local fallbacks, base = {}, GLYPH_FIRST_BASE
    for _, iso in ipairs(GLYPH_FALLBACK_ORDER) do
        local f = ct.fontFaces[iso] and byName[ct.fontFaces[iso]]
        if f and f.glyphs > 0 then
            fallbacks[#fallbacks + 1] = { iso = iso, font = f.font, base = base, name = f.name }
            base = base + ((f.glyphs + 0xFF) & ~0xFF)
        else
            ctError("glyphs: no %s fallback font (%s)", iso, tostring(ct.fontFaces[iso]))
        end
    end
    if #fallbacks == 0 then return false, "no Asian fonts loaded" end
    if base >= 0xFFFF then return false, ("glyph space overflow 0x%X"):format(base) end

    local primaries, classVt = {}, nil
    for _, f in ipairs(fonts) do
        if f.movie == 0 then
            classVt = classVt or f.vt
            if f.vt == classVt and f.glyphs < GLYPH_FIRST_BASE then primaries[#primaries + 1] = f end
        end
    end
    if not classVt or #primaries == 0 then return false, "no efigs fonts found" end
    for _, fb in ipairs(fallbacks) do
        if Memory.ReadLong(fb.font) ~= classVt then return false, fb.name .. " uses a different font class" end
    end

    local cave = glyphCave(GLYPH_CAVE_BYTES)
    if not cave then return false, "no executable cave" end
    local data = Memory.Alloc(0x60)
    Memory.MemSet(data, 0, 0x60)
    for i, fb in ipairs(fallbacks) do
        Memory.WriteInt(data + 4 * (i - 1), fb.base)
        Memory.WriteLong(data + 0x20 + 8 * (i - 1), fb.font)
    end
    Memory.WriteInt(data + 0x10, base)
    Memory.WriteLong(data + 0x40, classVt)

    local codeBase = cave + #GLYPH_MAGIC
    local a = glyphAsm()
    local glyphIndexAt = a.pos()
    a.bytes(0x53, 0x56, 0x57, 0x48, 0x83, 0xEC, 0x20)
    a.bytes(0x0F, 0xB7, 0xF2)
    a.bytes(0x48, 0xBF); a.u64(data)
    a.bytes(0x48, 0x8B, 0x47, 0x40, 0xFF, 0x50, 0x18)
    a.bytes(0x83, 0xF8, 0xFF); a.jcc8(0x75, "done")
    for i = 1, #fallbacks do
        a.bytes(0x48, 0x8B, 0x4F, 0x20 + 8 * (i - 1))
        a.bytes(0x89, 0xF2, 0x48, 0x8B, 0x01, 0xFF, 0x50, 0x18)
        a.bytes(0x83, 0xF8, 0xFF); a.jcc8(0x74, "miss" .. i)
        a.bytes(0x03, 0x47, 4 * (i - 1)); a.jcc8(0xEB, "done")
        a.label("miss" .. i)
    end
    a.label("done")
    a.bytes(0x48, 0x83, 0xC4, 0x20, 0x5F, 0x5E, 0x5B, 0xC3)
    local dispatchAt = a.pos()
    a.bytes(0x49, 0xBB); a.u64(data)
    a.bytes(0x41, 0x3B, 0x53, 0x10); a.jcc8(0x73, "orig")
    for i = #fallbacks, 1, -1 do
        if i == 1 then a.bytes(0x41, 0x3B, 0x13) else a.bytes(0x41, 0x3B, 0x53, 4 * (i - 1)) end
        a.jcc8(0x73, "fb" .. i)
    end
    a.label("orig")
    a.bytes(0x49, 0x8B, 0x43, 0x40, 0x42, 0xFF, 0x24, 0x10)
    for i = 1, #fallbacks do
        a.label("fb" .. i)
        if i == 1 then a.bytes(0x41, 0x2B, 0x13) else a.bytes(0x41, 0x2B, 0x53, 4 * (i - 1)) end
        a.bytes(0x49, 0x8B, 0x4B, 0x20 + 8 * (i - 1))
        a.bytes(0x48, 0x8B, 0x01, 0x42, 0xFF, 0x24, 0x10)
    end
    local stubAt = {}
    for _, slot in ipairs(GLYPH_INDEX_SLOTS) do
        stubAt[slot] = a.pos()
        a.bytes(0x41, 0xBA); a.u32(slot)
        a.bytes(0xE9); a.u32((dispatchAt - (a.pos() + 4)) & 0xFFFFFFFF)
    end
    local code = a.finish()
    if #code + #GLYPH_MAGIC > GLYPH_CAVE_BYTES then Memory.Free(data); return false, "fallback code too large" end

    for i, byte in ipairs(code) do Memory.WriteByte(codeBase + i - 1, byte) end
    for i = 1, #GLYPH_MAGIC do Memory.WriteByte(cave + i - 1, GLYPH_MAGIC:byte(i)) end

    local vt = Memory.Alloc(0x100)
    for off = 0, 0xF8, 8 do Memory.WriteLong(vt + off, Memory.ReadLong(classVt + off)) end
    Memory.WriteLong(vt + 0x18, codeBase + glyphIndexAt)
    for slot, at in pairs(stubAt) do Memory.WriteLong(vt + slot, codeBase + at) end

    for _, f in ipairs(primaries) do
        Memory.WriteLong(f.font, vt)
        ct.glyph.patched[#ct.glyph.patched + 1] = { font = f.font, vt = classVt }
    end
    ct.glyph.data, ct.glyph.vt = data, vt
    return true
end

local function removeGlyphFallback()
    if #ct.glyph.patched == 0 then return end
    for _, p in ipairs(ct.glyph.patched) do
        if Memory.ReadLong(p.font) == ct.glyph.vt then Memory.WriteLong(p.font, p.vt) end
    end
    VIBE_GATE.retainAllocation(ct.glyph.data)
    VIBE_GATE.retainAllocation(ct.glyph.vt)
    ct.glyph.patched = {}
end

local function installOutgoingHook()
    if ct.hook ~= 0 then return true end
    if IS_ENHANCED then return false, "Enhanced has no text chat" end
    local match = Memory.Scan(SUBMIT_CALL_AOB)
    if not match or match == 0 then return false, "SubmitText call-site signature not found" end
    local hook = match + SUBMIT_CALL_OFF
    local original = readBytes(hook, 5)
    if original[1] ~= 0xE8 then return false, "SubmitText call site already changed" end
    local state = Memory.Alloc(0x220)
    if not state or state == 0 then return false, "state allocation failed" end
    Memory.MemSet(state, 0, 0x220)
    local cave = findCave(128)
    if not cave then Memory.Free(state); return false, "no executable cave" end

    local sc = {}
    append(sc, {0x48,0xB8}); append(sc, u64(state))
    append(sc, {0xF0,0xFF,0x40,0x04})
    append(sc, {0x44,0x88,0x48,0x02})
    append(sc, {0x48,0x8D,0x50,0x10})
    append(sc, {0x4C,0x89,0xC1})
    append(sc, {0x41,0xB8,0xFF,0x00,0x00,0x00})
    local loop = #sc
    append(sc, {0x44,0x8A,0x09,0x44,0x88,0x0A})
    append(sc, {0x45,0x84,0xC9,0x74,0x0B})
    append(sc, {0x48,0xFF,0xC1,0x48,0xFF,0xC2,0x41,0xFF,0xC8})
    append(sc, {0x75, ((loop + 1) - (#sc + 3)) & 255})
    append(sc, {0xC6,0x02,0x00})
    append(sc, {0xC6,0x40,0x01,0x01})
    append(sc, {0xF0,0xFF,0x48,0x04,0xB0,0x01,0xC3})

    local oldCave = readBytes(cave, #sc)
    writeBytes(cave, sc)
    local rel = cave - (hook + 5)
    local patch = {0xE8}; append(patch, u32(rel))
    for i = 2, 5 do Memory.WriteByte(hook + i - 1, patch[i]) end
    Memory.WriteByte(hook, patch[1])
    ct.hook, ct.cave, ct.state = hook, cave, state
    ct.origHook, ct.origCave = original, oldCave
    return true
end

local function uninstallOutgoingHook()
    if ct.hook == 0 then return end
    for i = 2, #ct.origHook do Memory.WriteByte(ct.hook + i - 1, ct.origHook[i]) end
    Memory.WriteByte(ct.hook, ct.origHook[1])
    local deadline = os.clock() + 0.100
    while ct.state ~= 0 and (Memory.ReadUInt(ct.state + 4) or 0) ~= 0 and os.clock() < deadline do end
    if ct.state ~= 0 and (Memory.ReadUInt(ct.state + 4) or 0) == 0 then
        writeBytes(ct.cave, ct.origCave)
        Memory.Free(ct.state)
    elseif ct.state ~= 0 then
        VIBE_GATE.retainAllocation(ct.state)
        ctError("capture drain timed out; allocation retained")
    end
    ct.hook, ct.cave, ct.state, ct.origHook, ct.origCave = 0, 0, 0, nil, nil
end

local function poolEcho(pid, text, team)
    local shownText = chatCommands.engineChat.utf8Prefix(text, 255)
    local key = tostring(pid) .. "\0" .. shownText .. "\0" .. tostring(team == true)
    ct.injected[key] = Time.GetEpocheMs() + 1500
    GTA.AddChatMessageToPool(pid, shownText, team)
end

local function taggedText(tag, text)
    return ("[%s] %s"):format(tostring(tag):upper(), tostring(text or ""))
end

local function isSpellingOnlyChange(text, translated)
    local original = text:lower():gsub("%s+", " "):match("^%s*(.-)%s*$")
    local result = tostring(translated or ""):lower():gsub("%s+", " "):match("^%s*(.-)%s*$")
    if original == result then return true end
    local function chatSpelling(value)
        return (value:gsub("%a+", function(word)
            local compact, previous = "", ""
            for i = 1, #word do
                local ch = word:sub(i, i)
                if ch ~= previous then compact = compact .. ch; previous = ch end
            end
            return compact == "okay" and "ok" or compact
        end))
    end
    if chatSpelling(original) == chatSpelling(result) then return true end
    original = original:match("^(%a+)%p*$")
    result = result:match("^(%a+)%p*$")
    if not original or not result or #original < 8 or #result < 8
        or math.abs(#original - #result) > 2 then return false end
    local row = {}
    for j = 0, #result do row[j] = j end
    for i = 1, #original do
        local nextRow = { [0] = i }
        for j = 1, #result do
            local cost = original:sub(i, i) == result:sub(j, j) and 0 or 1
            nextRow[j] = math.min(row[j] + 1, nextRow[j - 1] + 1, row[j - 1] + cost)
        end
        row = nextRow
    end
    return row[#result] <= 2
end

local function isSingleWordTrim(text, translated)
    local original, result = text:lower(), tostring(translated or ""):lower()
    if not original:match("^%a+$") or not result:match("^%a+$") then return false end
    local shorter, longer = original, result
    if #shorter > #longer then shorter, longer = longer, shorter end
    return #shorter >= 4 and #shorter * 2 >= #longer
        and (longer:sub(1, #shorter) == shorter or longer:sub(-#shorter) == shorter)
end

local function isExpressiveOnly(text)
    local letters = text:lower():gsub("[%s%p]", "")
    if letters:match("^woooo+e?w$") then return true end
    local compact, previous = "", ""
    for i = 1, #letters do
        local ch = letters:sub(i, i)
        if ch ~= previous then compact = compact .. ch; previous = ch end
    end
    if compact == "ty" then return true end
    if #compact >= 8 and compact:match("^%a+$") then
        local alternating = true
        for i = 3, #compact do
            if compact:sub(i, i) ~= compact:sub((i - 1) % 2 + 1, (i - 1) % 2 + 1) then
                alternating = false
                break
            end
        end
        if alternating then return true end
    end
    if #compact >= 3 and compact:gsub("wo", "") == "w" then return true end
    if #compact >= 7 and compact:sub(-1) == "w" then
        compact = compact:sub(1, -2)
    end
    if compact:sub(1, 2) == "mu" then compact = compact:sub(3) end
    return #compact >= 4
        and (compact:gsub("ha", "") == "" or compact:gsub("he", "") == "")
end

local function obviousForeign(text, translated, source, target, declared, trusted, repeated)
    if isSingleWordTrim(text, translated) then return false, "single-word spelling trim" end
    if isExpressiveOnly(text) then return false, "expressive interjection only" end
    if not source or source == target then return false, "detected local language" end
    local letters = text:gsub("[%s%p%d]", "")
    local words = 0
    for _ in text:gmatch("%S+") do words = words + 1 end
    local lowerLetters = letters:lower()
    local firstLetter = lowerLetters:sub(1, 1)
    if #lowerLetters >= 4 and firstLetter ~= ""
        and lowerLetters == firstLetter:rep(#lowerLetters) then
        return false, "repeated-character noise"
    end
    local distinctScript = false
    for _, cp in utf8.codes(text) do
        if (cp >= 0x0370 and cp <= 0x052F) or (cp >= 0x0590 and cp <= 0x08FF)
            or (cp >= 0x3040 and cp <= 0x30FF) or (cp >= 0x3400 and cp <= 0x9FFF)
            or (cp >= 0xAC00 and cp <= 0xD7AF) then
            distinctScript = true
            break
        end
    end
    if distinctScript then return true, "distinct writing system" end
    local kept, total, seen = 0, 0, {}
    for w in tostring(translated or ""):lower():gmatch("[%w']+") do seen[w] = true end
    for w in text:lower():gmatch("[%w']+") do
        total = total + 1
        if seen[w] then kept = kept + 1 end
    end
    if total > 0 and kept * 2 >= total then
        return false, ("%d of %d words unchanged"):format(kept, total)
    end
    local function collapsedLetterRuns(value)
        local shape = ""
        for word in tostring(value or ""):lower():gmatch("%a+") do
            local compact, previous = "", ""
            for i = 1, #word do
                local ch = word:sub(i, i)
                if ch ~= previous then compact = compact .. ch; previous = ch end
            end
            shape = shape == "" and compact or (shape .. " " .. compact)
        end
        return shape
    end
    local originalShape = collapsedLetterRuns(text)
    if originalShape ~= "" and originalShape == collapsedLetterRuns(translated) then
        return false, "only repeated-letter spelling changed"
    end
    local chatWords = {
        aux=true, auxiliary=true, cannon=true, crash=true,
        afk=true, brb=true, bro=true, cap=true, gg=true, haha=true, hello=true,
        hey=true, idk=true, lmao=true, lol=true, no=true, omg=true, rofl=true,
        sup=true, wtf=true, yeah=true, yea=true, yup=true,
    }
    local chatWordCount = 0
    for w in text:lower():gmatch("[%a]+") do
        local compact = collapsedLetterRuns(w)
        if not chatWords[w] and not chatWords[compact] then break end
        chatWordCount = chatWordCount + 1
    end
    if chatWordCount == words and words > 0 then
        return false, "recognizable English chat"
    end
    if kept == 0 and total == 1 and #letters >= 8 then
        return true, "fully translated long word"
    end
    if kept == 0 and total >= 2 and #letters >= 8 then
        return true, "fully translated short phrase"
    end
    if trusted == source and #letters >= 4 then
        return true, "previously confirmed player language"
    end
    if repeated and #letters >= 8 and words >= 2 then
        return true, "repeated language detection"
    end
    if declared == source and declared ~= target and #letters >= 8 and words >= 2 then
        return true, "matches player language"
    end
    if #letters >= 14 and words >= 3 then return true, "long foreign phrase" end
    return false, "short/ambiguous Latin text"
end

local function queueIncoming(pid, name, text, team)
    ct.jobs[#ct.jobs + 1] = { kind="in", pid=pid, name=name, text=text, team=team }
end

local function isChatCommand(text)
    local prefix = chatCommands.prefix
    return chatCommands.isEnabled() and text:sub(1, #prefix) == prefix
end

local ENGLISH_CHAT_WORDS = {
    aux=true, auxiliary=true, cannon=true,
    about=true, again=true, airport=true, ammo=true, armor=true, are=true,
    at=true, back=true, bad=true, bro=true, buy=true, can=true, cap=true,
    car=true, casino=true, come=true, crash=true, crashed=true, did=true,
    dont=true, fast=true, fight=true, follow=true, ["for"]=true, funny=true,
    game=true, go=true, godmode=true, good=true, got=true, have=true,
    hear=true, heist=true, hello=true, here=true, hydra=true, im=true,
    join=true, kick=true, lagging=true, leave=true, lets=true, lobby=true,
    loud=true, marker=true, mechanic=true, meet=true, mic=true, mission=true,
    modder=true, money=true, more=true, my=true, need=true, nice=true,
    no=true, one=true, pick=true, played=true, ready=true, ride=true,
    see=true, shoot=true, some=true, sparrow=true, stop=true, team=true,
    thank=true, thanks=true, that=true, the=true, this=true, to=true,
    teleport=true, up=true, wait=true, was=true, well=true, what=true,
    when=true, where=true, why=true, wild=true, world=true, wrong=true,
    yeah=true, you=true, your=true,
    afk=true, brb=true, gg=true, idk=true, lmao=true, lol=true, npc=true,
    omg=true, rofl=true, wtf=true, yup=true,
}

local function romanizedCandidate(text, translated, romanIso, manualSource, source,
        target, declared, trusted)
    if not romanIso then return false, "no romanization language", 0, 0 end
    if romanIso == target then return false, "source equals target", 0, 0 end
    if text:find("[\128-\255]") then return false, "already native script", 0, 0 end
    if not manualSource and trusted == target and declared ~= romanIso then
        return false, "confirmed writing target language", 0, 0
    end

    local kept, total, letters, seen = 0, 0, 0, {}
    for word in translated:lower():gmatch("%a+") do
        if #word >= 2 then seen[word] = true end
    end
    for word in text:lower():gmatch("%a+") do
        if #word >= 2 then
            total = total + 1
            letters = letters + #word
            if seen[word] then kept = kept + 1 end
        end
    end
    if total == 0 or (total < 2 and letters < 6) then
        return false, "too little lexical evidence", kept, total
    end
    if kept * 2 < total then return false, "source was already translated", kept, total end
    if total < 2 and not manualSource
        and declared ~= romanIso and trusted ~= romanIso then
        return false, "single word lacks language evidence", kept, total
    end

    if target == "en" then
        local english = 0
        for word in text:lower():gmatch("%a+") do
            if #word >= 2 and ENGLISH_CHAT_WORDS[word] then english = english + 1 end
        end
        if english >= 2 and english * 2 >= total then
            return false, "looks like English chat", kept, total
        end
    end

    local detectedRoman = romanIso == (manualSource or source)
    if not detectedRoman and (total < 2 or source == "en") then
        return false, "profile-only language evidence", kept, total
    end
    return true, "romanized candidate", kept, total
end

local function historyOriginalLine(at, speaker, text)
    return ("[%s]   %s:   %s"):format(
        tostring(at or ""), tostring(speaker or ""), tostring(text or ""))
end

local function onChat(sender, message, team)
    local outAuto = ct.outgoing and (FeatureMgr.GetFeature(H.CHAT_TRANSLATE_OUT_TARGET):GetListIndex() or 0) == 0
    if not (ct.incoming or outAuto) or type(message) ~= "string" or message == "" or not sender then return end
    if isChatCommand(message) then return end
    local pid = sender.PlayerId
    if type(pid) ~= "number" or pid < 0 or pid > 31 or pid == ct.localPid then return end
    local key = tostring(pid) .. "\0" .. message .. "\0" .. tostring(team == true)
    local now = Time.GetEpocheMs()
    local injectedUntil = ct.injected[key]
    if injectedUntil and now < injectedUntil then
        ct.injected[key] = nil
        return
    end
    if ct.seen[key] and now - ct.seen[key] < 500 then return end
    ct.seen[key] = now
    if ct.incoming then hideNextLine() end
    queueIncoming(pid, nil, message, team == true)
end


local function processIncoming(j)
    j.name = j.name or Players.GetName(j.pid) or "Player"
    if isExpressiveOnly(j.text) then
        if ct.incoming then poolEcho(j.pid, j.text, j.team) end
        return
    end
    local manualSource = chosenLanguage(H.CHAT_TRANSLATE_IN_SOURCE)
    local target = incomingTargetLanguage()
    local translated, source, err = translate(j.text, target, manualSource)
    if manualSource then source = manualSource end
    if not translated then
        ctError("incoming failed: %s", tostring(err))
        if ct.incoming then
            addHistory({ kind="incoming", name=j.name, original=j.text, failed=true })
            poolEcho(j.pid, j.text, j.team)
        end
        return
    end
    local declared = profileLanguage(j.pid)
    if not manualSource and source == target and translated ~= j.text and utf8.len(j.text) then
        for _, cp in utf8.codes(j.text) do
            if cp >= 0xAC00 and cp <= 0xD7AF then source = "ko"; break end
            if cp >= 0x3040 and cp <= 0x30FF then source = "ja"; break end
            if cp >= 0x3400 and cp <= 0x9FFF then
                source = (declared == "zh-CN" or declared == "ja") and declared or "zh-TW"
            end
        end
    end
    local ev = ct.evidence[j.pid]
    if not manualSource then
        if source ~= target then
            if ev and ev.iso == source and Time.GetEpocheMs() - ev.at < 2 * 60 * 1000 then
                ev.count, ev.at = ev.count + 1, Time.GetEpocheMs()
            else
                ev = { iso=source, count=1, at=Time.GetEpocheMs() }
                ct.evidence[j.pid] = ev
            end
        else
            ct.evidence[j.pid] = nil
            ev = nil
        end
    end
    local trusted = ct.detected[j.pid]
    trusted = trusted and Time.GetEpocheMs() - trusted.at < 30 * 60 * 1000 and trusted.iso or nil
    local shouldTranslate
    local romanIso = (ROMANIZED_INPUT[manualSource or source or ""] and (manualSource or source))
        or (not manualSource and ROMANIZED_INPUT[declared] and declared) or nil
    local tryRomanized, _, _, romanWords = romanizedCandidate(
        j.text, translated, romanIso, manualSource, source, target, declared, trusted)
    if tryRomanized then
        local native = fromRomanized(j.text, romanIso)
        local converted = native and translate(native, target, romanIso)
        local same = 0
        if converted then
            local out = {}
            for w in converted:lower():gmatch("[%w']+") do out[w] = true end
            for w in j.text:lower():gmatch("[%w']+") do
                if out[w] then same = same + 1 end
            end
        end
        if converted and converted ~= native and same * 2 < romanWords then
            translated, source = converted, romanIso
            shouldTranslate = true
        end
    end
    if not shouldTranslate then
        if manualSource then
            shouldTranslate = manualSource ~= target
        else
            shouldTranslate = obviousForeign(
                j.text, translated, source, target, declared, trusted, ev and ev.count >= 2)
        end
    end
    if shouldTranslate and not manualSource and isSingleWordTrim(j.text, translated) then
        shouldTranslate = false
    end
    if shouldTranslate and (translated == j.text
        or (not manualSource and isSpellingOnlyChange(j.text, translated))) then
        shouldTranslate = false
    end
    local words = 0
    for _ in j.text:gmatch("[%w']+") do words = words + 1 end
    if not manualSource and LANGUAGE_BY_ISO[source]
        and (shouldTranslate or (source == target and words >= 3)) then
        ct.detected[j.pid] = { iso=source, at=Time.GetEpocheMs() }
    end
    if shouldTranslate and ct.incoming then
        Logger.Log(eLogColor.GREEN, "ChatTranslate", ("%s: %s"):format(
            j.name, (tostring(translated):gsub("[\r\n]+", " "))))
    end
    if ct.incoming then
        if shouldTranslate then
            addHistory({
                kind="incoming", name=j.name, original=j.text, translated=translated,
                source=source, target=target,
            })
            if ct.showIncomingOriginal then
                poolEcho(j.pid, j.text, j.team)
            end
            poolEcho(j.pid, taggedText(T("Translated"), translated), j.team)
        else
            poolEcho(j.pid, j.text, j.team)
        end
    end
end

local function processOutgoing(j)
    local me = GTA.GetLocalPlayerId()
    if isChatCommand(j.text) then
        if not chatCommands.engineChat.send(j.text, j.team) then
            ctError("outgoing chat command could not be sent")
        end
        poolEcho(me, j.text, j.team)
        return
    end
    local groups = {}
    for pid = 0, 31 do
        if pid ~= me and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
            local iso, latin = outgoingTargetLanguage(pid)
            local key = latin and (iso .. " latin") or iso
            groups[key] = groups[key] or { iso = iso, latin = latin }
            groups[key][#groups[key] + 1] = pid
        end
    end
    local manualSource = outgoingSourceLanguage()
    if not manualSource then
        local mine = localLanguage()
        local translated, detected = translate(j.text, mine)
        if translated and detected then
            local foreign = detected ~= mine and obviousForeign(j.text, translated, detected, mine)
            manualSource = foreign and detected or mine
        end
    end
    local localTranslations = {}
    local historyTranslations = {}
    local sentAny = false
    for key, pids in pairs(groups) do
        local iso = pids.iso
        local text, source, err
        if manualSource == iso and not pids.latin then
            text, source = j.text, manualSource
        else
            if pids.latin then
                text, source, err = translateLatin(j.text, iso, manualSource)
            else
                text, source, err = translate(j.text, iso, manualSource)
            end
            if not text then
                ctError("outgoing %s failed: %s", iso, tostring(err))
                text = j.text
            elseif source == iso or text == j.text then
            else
                localTranslations[key] = { iso = iso, text = text }
            end
        end
        historyTranslations[#historyTranslations + 1] = {
            iso=iso, text=text, recipients=#pids,
            failed=err ~= nil,
        }
        for _, pid in ipairs(pids) do
            chatCommands.engineChat.send(text, j.team, pid, false)
            sentAny = true
        end
    end
    poolEcho(me, j.text, j.team)
    if sentAny then
        table.sort(historyTranslations, function(a, b)
            return languageName(a.iso) < languageName(b.iso)
        end)
        addHistory({ kind="outgoing", original=j.text, translations=historyTranslations })
    end
    if sentAny and ct.showOutgoingTranslated then
        Script.Yield(50)
        local translationCount = 0
        for _ in pairs(localTranslations) do translationCount = translationCount + 1 end
        for key, t in pairs(localTranslations) do
            local tag = translationCount > 1
                and T("Translated - %s"):format(T(languageName(t.iso))) or T("Translated")
            if not chatCommands.engineChat.localEcho(taggedText(tag, t.text), j.team) then
                ctError("outgoing translation display failed")
            end
            Script.Yield(50)
        end
    end
end

EventMgr.RegisterHandler(eLuaEvent.ON_CHAT_MESSAGE, onChat)

local function takeOutgoing()
    if ct.state ~= 0 and (Memory.ReadByte(ct.state + 1) or 0) ~= 0 then
        local text = Memory.ReadString(ct.state + 0x10)
        local team = (Memory.ReadByte(ct.state + 2) or 0) ~= 0
        Memory.WriteByte(ct.state + 1, 0)
        if text and text ~= "" then ct.jobs[#ct.jobs + 1] = {kind="out", text=text, team=team} end
    end
end

local function runJob(j)
    local ok, err = pcall(function()
        if j.kind == "in" then processIncoming(j) else processOutgoing(j) end
    end)
    if not ok then ctError("worker error: %s", tostring(err)) end
end

local function serviceToggles(incoming, outgoing)
    ct.serviceToggle = true
    FeatureMgr.GetFeature(H.CHAT_TRANSLATE_IN):Toggle(incoming)
    FeatureMgr.GetFeature(H.CHAT_TRANSLATE_OUT):Toggle(outgoing)
    ct.serviceToggle = false
end

local function suspendTranslation()
    if not (ct.desiredIncoming or ct.desiredOutgoing) then return end
    if ct.recovery then serviceToggles(false, false); return end
    local now = Time.GetEpocheMs()
    ct.recovery = { expires = now + 300000, nextAt = now + 10000, attempts = 0 }
    serviceToggles(false, false)
    GUI.AddToast("VibeScript", T("Translation services are unavailable. Retrying for up to 5 minutes."), 10000)
end

local function recoveryTick()
    local r = ct.recovery
    if not r then return end
    local now = Time.GetEpocheMs()
    if now >= r.expires then
        ct.recovery = nil
        ctError("translation recovery failed after 5 minutes")
        GUI.AddToast("VibeScript", T("Translation services did not recover after 5 minutes. Turn chat translation on to try again."), 10000)
    elseif not ct.checking and now >= r.nextAt then
        r.attempts = r.attempts + 1
        ct.queueCheck(true)
    end
end

local function finishEndpointCheck()
    ct.checking = false
    if not ct.endpointOk.translate then
        suspendTranslation()
        if ct.recovery then
            local delay = math.max(1, ct.recovery.attempts - 1) * 10000
            ct.recovery.nextAt = Time.GetEpocheMs() + delay
        end
        return
    end
    if ct.recovery then
        if Time.GetEpocheMs() >= ct.recovery.expires then recoveryTick(); return end
        serviceToggles(ct.desiredIncoming, ct.desiredOutgoing)
        ct.recovery = nil
        GUI.AddToast("VibeScript", T("Translation services restored, features reenabled"), 10000)
    end
end

local function checkEndpoints()
    local ep = ct.endpointOk
    ep.translate, ep.romanize, ep.inputTools = nil, nil, nil
    local translated, detected, terr = translate("hello", "es")
    ep.translate = translated ~= nil and translated:lower():find("hola", 1, true) ~= nil
        and detected == "en"
    local romanized, rerr = romanizedTranslation("hello", "ru", "en")
    ep.romanize = romanized ~= nil and romanized:lower():find("privet", 1, true) ~= nil
    local candidate, ierr = inputToolsCandidate("nihao", "zh-CN")
    ep.inputTools = candidate == "\228\189\160\229\165\189"
    if not (ep.translate and ep.romanize and ep.inputTools) then
        if VIBESCRIPT_VERBOSE == true then ctError("endpoint check: translate %s, romanize %s, input tools %s",
            ep.translate and "OK" or ("FAILED (" .. tostring(terr or translated) .. ", " .. tostring(detected) .. ")"),
            ep.romanize and "OK" or ("FAILED (" .. tostring(rerr or romanized) .. ")"),
            ep.inputTools and "OK" or ("FAILED (" .. tostring(ierr or candidate) .. ")")) end
    end
    if not ep.translate then
        takeOutgoing()
        while #ct.jobs > 0 do runJob(table.remove(ct.jobs, 1)) end
        finishEndpointCheck()
        return
    end
    finishEndpointCheck()
    if not ep.romanize then
        GUI.AddToast("VibeScript", T("Latin-letter translation is unavailable right now. Those players get your original message."), 6000)
    end
    if not ep.inputTools then
        GUI.AddToast("VibeScript", T("Pinyin, romaji and Cyrillic transliteration are unavailable right now."), 6000)
    end
end

function ct.queueCheck(force)
    local ep = ct.endpointOk
    if ct.checking or (not force and ep.translate and ep.romanize and ep.inputTools) then return end
    ct.checking = true
    table.insert(ct.jobs, 1, { kind="check" })
end

Script.RegisterLooped(function()
    if scriptUnloading then Script.Yield(100); return end
    reapTimedOutRequests()
    recoveryTick()
    ct.localPid = GTA.GetLocalPlayerId()
    takeOutgoing()
    local j = table.remove(ct.jobs, 1)
    if j and j.kind == "check" then
        local ok, err = pcall(checkEndpoints)
        if not ok then
            ctError("endpoint check error: %s", tostring(err))
            ct.endpointOk.translate = false
            finishEndpointCheck()
        end
    elseif j then
        runJob(j)
    end
    Script.Yield(j and 0 or 50)
end)

function ct.syncFonts()
    ct.allFonts = ct.incoming or ct.outgoing
    if not ct.allFonts then removeGlyphFallback(); return end
    Script.QueueJob(function()
        if not ct.fontsReady then loadLanguageFonts() end
        if not ct.allFonts or not ct.fontsReady then return end
        local ok, err = installGlyphFallback()
        if not ok then ctError("glyph fallback unavailable: %s", tostring(err)) end
    end)
end

