        local ok, err = setDisplayFilter(ct.incoming)
        if ct.incoming and not ok then ctError("incoming unavailable: %s", tostring(err)) end
        ct.syncFonts()
    end):SetSaveable(false)

FeatureMgr.AddFeature(H.CHAT_TRANSLATE_OUT, "Translate Outgoing Chat", eFeatureType.Toggle,
    "Translates your chat messages into each player's language. Every player receives only their own version.", function(f)
        ct.outgoing = f:IsToggled() == true
        if not ct.serviceToggle then
            ct.desiredOutgoing = ct.outgoing
            if not (ct.desiredIncoming or ct.desiredOutgoing) then ct.recovery = nil end
