    P.compatibilityChecked = true
    if #failed > 0 then
        P.compatibilityStatus = "Compatibility failed: " .. table.concat(failed, ", ") .. ". Details for every failed site are in Cherax.log."
        return nil, P.compatibilityStatus
    end
