local function calibrate()
    assert(invoke(P.supported) == 1, "Invariant CPU timer unavailable")
    assert(Time and Time.GetEpocheNs, "High-resolution calibration clock unavailable")
    local low, high
    for _ = 1, 3 do
        local t0, n0 = invoke(P.ticks), Time.GetEpocheNs()
        Script.Yield(100)
        assert(not scriptUnloading and not ShouldUnload(), "Unloading during clock calibration")
        local t1, n1 = invoke(P.ticks), Time.GetEpocheNs()
        local ms = (n1 - n0) / 1000000
        assert(ms >= 50 and ms <= 2000 and t1 > t0, "CPU timer calibration failed")
        local rate = (t1 - t0) / ms
        assert(rate >= 100000 and rate <= 10000000, "CPU timer rate outside supported range")
        low, high = math.min(low or rate, rate), math.max(high or rate, rate)
    end
    assert(high / low < 1.03, "CPU timer calibration was unstable")
