function P.ensure()
    if not P.ready then
        local sites = P.preflight()
        if not sites then return false, P.compatibilityStatus end
        P.site, P.queue = sites.receive, sites.queue
        local function id(at)
            return u(at + 6 + signed32(u(at + 2)))
        end
        P.joinId, P.refusalId, P.reason = id(sites.join), id(sites.host), u(sites.reason + 1)
        assert(P.joinId > 0 and P.joinId <= 255 and P.refusalId > 0 and P.refusalId <= 255
            and P.joinId ~= P.refusalId and P.reason == 2, "Unrecognized current join protocol")
        P.stolen = hex(SPEC.stolen); P.original = P.stolen:sub(1, 8)
        assert(P.site % 64 <= 56 and read(P.site, #P.stolen) == P.stolen, "Unsafe or modified receive site")
        local d = findDescriptor(P.site)
        if d then
            assert(u(d.state + 8) == 0 and d.queue == P.queue, "Resident blocker is active or incompatible")
            P.cave, P.state, P.native, P.stubAt, P.callCode = d.cave, d.state, d.native, d.stub, d.callCode
            P.ticks, P.supported = d.ticks, d.supported
        else
            local _, _, _, endCode, endBytes = layout(0, 0, P.site)
            local extent = endCode + #endBytes
            local cave = reserveCave(extent)
            local state = Memory.Alloc(STATE_BYTES) or 0
            assert(state ~= 0 and state % 8 == 0, "Interior state allocation failed")
            Memory.MemSet(state, 0, STATE_BYTES)
            P.cave, P.state = cave, state
            local native, stub, sc, callCode, callBytes = layout(cave, state, P.site)
            P.native, P.stubAt, P.callCode = native, stub, callCode
            P.ticks, P.supported = native + A.bi_ticks, native + A.bi_clock_supported
            write(native, hex(A.code)); write(stub, sc); write(callCode, callBytes)
            Memory.WriteUInt(state, 0x42494E31); Memory.WriteUInt(state + 4, 2)
            Memory.WriteLong(cave + 16, state); Memory.WriteLong(cave + 24, P.site)
            Memory.WriteLong(state + 624, P.site); Memory.WriteLong(state + 632, P.queue)
            Memory.WriteLong(state + 640, #A.code // 2); write(state + 648, P.stolen)
            assert(read(native, #A.code // 2) == hex(A.code) and read(stub, #sc) == sc
                and read(callCode, #callBytes) == callBytes, "Cave code write failed")
            VIBE_GATE.retainAllocation(state)
            write(cave, MAGIC)
            assert(descriptor(cave, P.site), "Cave descriptor verification failed")
            P.extent = extent
        end
        Memory.WriteUInt(P.state + 8, 0); Memory.WriteUInt(P.state + 672, 0)
        Memory.WriteLong(P.state + 24, P.queue)
        Memory.WriteUInt(P.state + 48, P.joinId); Memory.WriteUInt(P.state + 52, P.refusalId)
        Memory.WriteUInt(P.state + 56, P.reason)
        calibrate()
        P.patch = hex("e9") .. string.pack("<i4", P.stubAt - (P.site + 5)) .. hex("909090")
        P.ready = true
    end
    assert(read(P.site, #P.stolen) == P.stolen, "Incoming dispatcher already modified")
    P.swap(P.original, P.patch)
    return true
end

local function stop(reason)
    if P.state then
        Memory.WriteUInt(P.state + 8, 0)
        Memory.WriteUInt(P.state + 60, (u(P.state + 60) + 1) & 0xFFFFFFFF)
    end
    if P.installed then
        if reason == "unload" then Memory.WriteUInt(P.state + 672, 1) end
        if read(P.site, 8) == P.patch then P.swap(P.patch, P.original)
        elseif read(P.site, 8) ~= P.original then fail("foreign receive patch preserved") end
        P.installed = false
    end
    P.key = nil
end
local function toggled(hash, pid)
    local f = pid ~= nil and FeatureMgr.GetFeature(hash, pid) or FeatureMgr.GetFeature(hash)
    return f and f:IsToggled() or false
end
local function eligibleSession()
    return isPlayerReady() and not Natives.InvokeBool(0x05095437424397FA)
        and not Natives.InvokeBool(0x68049AEFF83D8F0A)
        and not Natives.InvokeBool(0x520F3282A53D26B7)
end
local function tick()
    if scriptUnloading or ShouldUnload() then stop("unload"); return end
    local all = toggled(H.AUTO_INTERIOR_KICK_ALL)
    local wanted, rows, keys, ready = false, {}, {}, nil
    local me = GTA.GetLocalPlayerId()
    for pid = 0, 31 do
        if pid ~= me and (all or toggled(H.AUTO_INTERIOR_KICK, pid)) then
            wanted = true
            if ready == nil then ready = eligibleSession() end
            if ready and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                local player = Players.GetById(pid)
                local gamer = player and player:GetGamerInfo()
                local pointer = player and player:GetAddress() or 0
                local connection = player and player.CxnId
                local mapped = connection and Players.GetByConId(connection)
                if pointer ~= 0 and gamer and gamer.RockstarId and tostring(gamer.RockstarId) ~= "0"
                    and connection and connection >= 0 and mapped and mapped:GetAddress() == pointer
                    and u(pointer + 0x58) == connection then
                    rows[#rows+1] = connection
                    keys[#keys+1] = pid .. ":" .. pointer .. ":" .. tostring(gamer.RockstarId) .. ":" .. connection
                end
            end
        end
    end
    P.requested = wanted
    if not wanted then P.failed = false; P.lastError = nil end
    if #rows == 0 then stop("no eligible targets"); return end
    if DEV.activityRefusalIsActive and DEV.activityRefusalIsActive() then
        DEV.stopActivityJoinRefusal()
    end
    if DEV.activityRetryIsActive and DEV.activityRetryIsActive() then
        DEV.stopActivityJoinRetry()
        if DEV.activityRetryIsActive() then stop("waiting for test ACK recovery"); return end
    end
    if P.failed then return end
    if P.installed and read(P.site, 8) == P.original then P.installed = false; P.key = nil end
    local key = table.concat(keys, "|")
    if not P.installed then
        local recovered, failure = P.recoverDisabled()
        if not recovered then
            P.failed = true; P.lastError = "Entry blocker unavailable:"
            fail(P.lastError .. " " .. tostring(failure)); return
        end
        local ok, ready, failure = pcall(P.ensure)
        if not ok then failure, ready = ready, false end
        if not ready then
            P.failed = true; P.lastError = "Entry blocker unavailable:"
            fail(P.lastError .. " " .. tostring(failure)); return
        end
    end
    local now, ns = invoke(P.ticks), Time.GetEpocheNs()
    local ms = (ns - P.clockNs) / 1000000
    local delta = now - P.clockTicks
    if delta < 0 or ms < 0 or (ms >= 50 and (delta < P.rate * ms * 0.90 or delta > P.rate * ms * 1.10)) then
        stop("clock discontinuity"); P.failed = true; P.ready = false
        P.lastError = "Entry blocker disabled: CPU timer changed; toggle off before retrying."
        fail(P.lastError); return
    end
    P.clockTicks, P.clockNs = now, ns
    if P.key ~= key then
        Memory.WriteUInt(P.state + 8, 0)
        Memory.WriteUInt(P.state + 60, (u(P.state + 60)+1) & 0xFFFFFFFF)
        Memory.WriteUInt(P.state + 44, 2)
        Memory.WriteUInt(P.state + 64, Utils.Joaat("am_mp_property_ext") & 0xFFFFFFFF)
        Memory.WriteUInt(P.state + 68, Utils.Joaat("am_mp_smpl_interior_ext") & 0xFFFFFFFF)
        for i, connection in ipairs(rows) do Memory.WriteUInt(P.state + 680+(i-1)*4, connection) end
        Memory.WriteUInt(P.state + 676, #rows)
        P.key = key
    end
    Memory.WriteUInt(P.state + 12, 2)
    Memory.WriteLong(P.state + 32, now + P.rate * 5000)
    Memory.WriteLong(P.state + 16, now)
    Memory.WriteUInt(P.state + 8, 1)
    P.lastError = nil
end
VIBE_GATE.blockInterior = {
    isActive = function() return P.requested end,
}
scanDoctor.register("BI-RECV", { probe = function()
    return scanDoctor.scanOk(SPEC.receive.pattern) or scanDoctor.scanOk(SPEC.receive.tail.pattern)
end })
scanDoctor.register("BI-QUEUE", { sig = SPEC.queue.caller.pattern })
for _, name in ipairs({ "join", "host", "reason", "serializer" }) do
    scanDoctor.register("BI-" .. name:upper(), { sig = SPEC[name].pattern })
end
Script.RegisterLooped(function() tick(); Script.Yield(100) end)
EventMgr.RegisterHandler(eLuaEvent.ON_SESSION_CHANGE, function()
    if P.state then
        Memory.WriteUInt(P.state + 8, 0)
        Memory.WriteUInt(P.state + 60, (u(P.state + 60) + 1) & 0xFFFFFFFF)
    end
    P.key = nil
end)
local function unload()
    stop("unload")
end
local previousSweep = VIBE_GATE.allocSweep
VIBE_GATE.allocSweep = function() unload(); return previousSweep() end
EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, unload)

end)()
